#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/stat.h>

#define MAX_BUFFER_SIZE 1024 * 1024 // 1 MB buffer size

typedef struct {
    const char* input_file;
    const char* output_file;
    const char* transformation_rules;
    int batch_mode;
    long timeout; // in seconds
} FileTask;

typedef struct {
    pthread_t thread_id;
    FileTask task;
} WorkerThread;

void log_message(const char *message) {
    FILE *log_file = fopen("processing_log.txt", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

// Dummy transformation function to apply rules
void apply_transformation_rules(FILE *input, FILE *output, const char* rules) {
    char buffer[MAX_BUFFER_SIZE];
    size_t bytes_read;
    while ((bytes_read = fread(buffer, 1, MAX_BUFFER_SIZE, input)) > 0) {
        // Apply dummy transformation (e.g., convert all bytes to uppercase)
        for (size_t i = 0; i < bytes_read; ++i) {
            buffer[i] ^= 0x20; // Example transformation: toggle case
        }
        fwrite(buffer, 1, bytes_read, output);
    }
}

void* process_file(void *arg) {
    FileTask task = *(FileTask*) arg;

    int input_fd = open(task.input_file, O_RDONLY);
    if (input_fd == -1) {
        log_message((char[]) "Error opening input file: ");
        perror(task.input_file);
        return NULL;
    }

    FILE *input_file = fdopen(input_fd, "rb");
    if (!input_file) {
        close(input_fd);
        log_message((char[]) "Failed to open input file stream.");
        return NULL;
    }

    int output_fd = open(task.output_file, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (output_fd == -1) {
        fclose(input_file);
        log_message((char[]) "Error opening output file: ");
        perror(task.output_file);
        return NULL;
    }

    FILE *output_file = fdopen(output_fd, "wb");
    if (!output_file) {
        close(output_fd);
        fclose(input_file);
        log_message((char[]) "Failed to open output file stream.");
        return NULL;
    }

    log_message((char[]) "Processing started for:");
    log_message(task.input_file);

    // Apply transformation
    apply_transformation_rules(input_file, output_file, task.transformation_rules);

    fclose(output_file);
    fclose(input_file);

    log_message((char[]) "Processing completed for:");
    log_message(task.input_file);

    return NULL;
}

void process_files_concurrently(const char* files[][2], int num_files, const char *rules, long timeout) {
    pthread_t threads[num_files];
    WorkerThread worker_threads[num_files];

    for (int i = 0; i < num_files; ++i) {
        FileTask task;
        task.input_file = files[i][0];
        task.output_file = files[i][1];
        task.transformation_rules = rules;
        task.batch_mode = 1;
        task.timeout = timeout;

        worker_threads[i].task = task;
        if (pthread_create(&worker_threads[i].thread_id, NULL, process_file, &worker_threads[i].task) != 0) {
            log_message((char[]) "Error creating thread for file processing.");
        }
    }

    for (int i = 0; i < num_files; ++i) {
        pthread_join(worker_threads[i].thread_id, NULL);
    }
}

void process_file(const char* input_file, const char* output_file, const char* rules, int batch_mode, long timeout) {
    if (batch_mode) {
        // Example of handling multiple files in a real use case
        const char* files[][2] = { {input_file, output_file} }; // Add more file pairs as needed
        process_files_concurrently(files, 1, rules, timeout); // Adjust number based on actual files to process
    } else {
        FileTask task;
        task.input_file = input_file;
        task.output_file = output_file;
        task.transformation_rules = rules;
        task.batch_mode = batch_mode;
        task.timeout = timeout;

        pthread_t thread_id;
        if (pthread_create(&thread_id, NULL, process_file, &task) != 0) {
            log_message((char[]) "Error creating single processing thread.");
        }
        pthread_join(thread_id, NULL);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 6) {
        fprintf(stderr, "Usage: %s <input_file> <output_file> <rules> <batch_mode> <timeout>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char* input_file = argv[1];
    const char* output_file = argv[2];
    const char* rules = argv[3];
    int batch_mode = atoi(argv[4]);
    long timeout = atol(argv[5]);

    process_file(input_file, output_file, rules, batch_mode, timeout);

    return EXIT_SUCCESS;
}
```

### Key Features:

- **Concurrent Processing**: Uses pthreads to enable concurrent processing of files. The number of threads can be adjusted according to the system resources.

- **Memory Management**: Utilizes fixed-size buffers for reading and writing file data to handle large files efficiently.

- **Logging**: Logs progress and errors, providing insights into the process status.

- **Error Handling**: Handles various error scenarios gracefully, including I/O operations and thread creation failures.']

