    if (!file) {
        fprintf(stderr, "Error: Could not open file.\n");
        return EXIT_FAILURE;
    }

    int *numbers = malloc(MAX_ELEMENTS * sizeof(int));
    if (!numbers) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        fclose(file);
        return EXIT_FAILURE;
    }

    size_t count = 0;
    char line[1024];
    int largest = INT_MIN;
    int valid_input_found = 0;

    while (fgets(line, sizeof(line), file)) {
        if (count >= MAX_ELEMENTS) {
            fprintf(stderr, "Error: Exceeded maximum allowed elements.\n");
            break;
        }

        const char *token = strtok(line, " \t\n");
        while (token != NULL && count < MAX_ELEMENTS) {
            char *endptr;
            int number = strtol(token, &endptr, 10);

            if (*endptr == '\0' || isspace((unsigned char)*endptr)) { // Check for valid conversion
                numbers[count++] = number;
                if (number > largest) {
                    largest = number;
                }
                valid_input_found = 1;
            } else {
                fprintf(stderr, "Warning: Malformed integer '%s'. Skipping.\n", token);
            }

            token = strtok(NULL, " \t\n");
        }
    }

    fclose(file);

    if (valid_input_found) {
        printf("Largest integer: %d\n", largest);
    } else {
        fprintf(stderr, "Error: No valid integers found in the file.\n");
    }

    free_memory(numbers);
    return EXIT_SUCCESS;
}
