```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#ifdef USE_OPENSSL
#include <openssl/evp.h>
#include <openssl/chacha20.h>
#endif

#define AES_KEY_SIZE_128 16
#define AES_KEY_SIZE_256 32
#define CHACHA_NONCE_SIZE 12
#define GCM_TAG_LENGTH 16

typedef enum {
    ALG_AES,
    ALG_CHACHA20
} EncryptionAlgorithm;

typedef enum {
    MODE_GCM,
    MODE_CTR,
    MODE_OFB
} ModeOfOperation;

typedef struct {
    EncryptionAlgorithm algorithm;
    ModeOfOperation mode;
    size_t key_size;
    unsigned char *key;
    unsigned char *iv; // Initialization Vector or Nonce based on algorithm and mode.
} EncryptionConfig;

#ifdef USE_OPENSSL
static int aes_encrypt(EVP_CIPHER_CTX *ctx, const unsigned char *plaintext,
                       int plaintext_len, unsigned char *ciphertext);
static int aes_decrypt(EVP_CIPHER_CTX *ctx, const unsigned char *ciphertext,
                       int ciphertext_len, unsigned char *plaintext);
static int chacha20_encrypt(unsigned char *ciphertext, 
                            const unsigned char *plaintext, size_t length, 
                            const unsigned char key[32], 
                            const unsigned char nonce[12]);
#endif

EncryptionConfig* create_encryption_config(EncryptionAlgorithm algo,
                                           ModeOfOperation mode,
                                           const unsigned char *key) {
    EncryptionConfig *config = (EncryptionConfig *)malloc(sizeof(EncryptionConfig));
    if (!config) return NULL;

    config->algorithm = algo;
    config->mode = mode;

    switch (algo) {
        case ALG_AES:
            if (mode == MODE_GCM || mode == MODE_OFB) {
                config->key_size = AES_KEY_SIZE_256; // GCM or OFB typically use 256-bit keys
            } else {
                config->key_size = AES_KEY_SIZE_128; // CTR commonly uses 128-bit keys
            }
            break;
        case ALG_CHACHA20:
            config->key_size = 32;
            break;
    }

    config->key = (unsigned char *)malloc(config->key_size);
    memcpy(config->key, key, config->key_size);

    size_t iv_nonce_size = (algo == ALG_AES && mode != MODE_GCM) ? EVP_MAX_IV_LENGTH : CHACHA_NONCE_SIZE;
    config->iv = (unsigned char *)malloc(iv_nonce_size);

    if (config->algorithm == ALG_CHACHA20 || config->mode == MODE_CTR) {
        RAND_bytes(config->iv, iv_nonce_size); // Random IV/Nonce
    } else {
        memset(config->iv, 0, iv_nonce_size); // Zeroed out for other modes
    }

    return config;
}

void free_encryption_config(EncryptionConfig *config) {
    if (config) {
        free(config->key);
        free(config->iv);
        free(config);
    }
}

#ifdef USE_OPENSSL
static int aes_encrypt(EVP_CIPHER_CTX *ctx, const unsigned char *plaintext,
                       int plaintext_len, unsigned char *ciphertext) {
    int len;
    int ciphertext_len;

    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len))
        return -1;
    ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) 
        return -1;
    ciphertext_len += len;

    return ciphertext_len;
}

static int aes_decrypt(EVP_CIPHER_CTX *ctx, const unsigned char *ciphertext,
                       int ciphertext_len, unsigned char *plaintext) {
    int len;
    int plaintext_len;

    if (1 != EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len))
        return -1;
    plaintext_len = len;

    if (1 != EVP_DecryptFinal_ex(ctx, plaintext + len, &len)) 
        return -1;
    plaintext_len += len;

    return plaintext_len;
}

static int chacha20_encrypt(unsigned char *ciphertext,
                            const unsigned char *plaintext, size_t length,
                            const unsigned char key[32],
                            const unsigned char nonce[12]) {
    return crypto_chacha20(ciphertext, plaintext, length, key, nonce);
}
#endif

void process_file(const char *input_filename, const char *output_filename,
                  EncryptionConfig *config) {
#ifdef USE_OPENSSL
    FILE *fin = fopen(input_filename, "rb");
    FILE *fout = fopen(output_filename, "wb");

    if (!fin || !fout) {
        perror("File opening failed");
        return;
    }

    unsigned char buffer[4096];
    size_t bytes_read;

    EVP_CIPHER_CTX *ctx = NULL;
    int encrypt = 1; // Set to 0 for decryption

    if (config->algorithm == ALG_AES) {
        const EVP_CIPHER *cipher;
        switch(config->mode) {
            case MODE_GCM:
                cipher = EVP_aes_256_gcm();
                break;
            case MODE_CTR:
                cipher = EVP_aes_128_ctr();
                break;
            default: // MODE_OFB
                cipher = EVP_aes_128_ofb();
                break;
        }

        ctx = EVP_CIPHER_CTX_new();
        if (!ctx) {
            perror("EVP_CIPHER_CTX allocation failed");
            goto cleanup;
        }

        if (1 != EVP_EncryptInit_ex(ctx, cipher, NULL, config->key, config->iv)) {
            perror("Encryption initialization failed");
            goto cleanup;
        }
    } else { // ALG_CHACHA20
#ifdef USE_OPENSSL
        ctx = chacha20_alloc();
        crypto_chacha20_init(ctx, 1, config->key, config->nonce);
#endif
    }

    while ((bytes_read = fread(buffer, 1, sizeof(buffer), fin)) > 0) {
        unsigned char ciphertext[4096 + GCM_TAG_LENGTH];

        int len;
        if (config->algorithm == ALG_AES && config->mode == MODE_GCM) {
            // AES-GCM specific handling
            if (!EVP_EncryptUpdate(ctx, ciphertext, &len, buffer, bytes_read)) {
                perror("AES-GCM update failed");
                goto cleanup;
            }

            unsigned char tag[GCM_TAG_LENGTH];
            if (!EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, GCM_TAG_LENGTH, tag)) {
                perror("Tag generation failed");
                goto cleanup;
            }

            len += EVP_EncryptFinal_ex(ctx, ciphertext + len, &len);
            fwrite(ciphertext, 1, len, fout);

            // Write the tag
            fwrite(tag, 1, GCM_TAG_LENGTH, fout);
        } else {
            if (config->algorithm == ALG_AES) {
                int ciphertext_len = aes_encrypt(ctx, buffer, bytes_read, ciphertext);
                if (ciphertext_len < 0) {
                    perror("AES encryption failed");
                    goto cleanup;
                }
                fwrite(ciphertext, 1, ciphertext_len, fout);
            } else { // ALG_CHACHA20
#ifdef USE_OPENSSL
                chacha20_encrypt((unsigned char *)ciphertext, buffer, bytes_read, config->key, config->iv);
#endif
                fwrite(ciphertext, 1, bytes_read, fout);
            }
        }
    }

cleanup:
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx);
    }

    fclose(fin);
    fclose(fout);

#else
    fprintf(stderr, "OpenSSL is required for encryption.\n");
#endif
}

int main(int argc, char *argv[]) {
#ifdef USE_OPENSSL
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <input file> <output file> <key file> <mode>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *input_filename = argv[1];
    const char *output_filename = argv[2];
    const char *key_filename = argv[3];
    ModeOfOperation mode = (ModeOfOperation)atoi(argv[4]);

    FILE *kf = fopen(key_filename, "rb");
    if (!kf) {
        perror("Failed to open key file");
        return EXIT_FAILURE;
    }

    unsigned char key[32];
    fread(key, 1, sizeof(key), kf);
    fclose(kf);

    EncryptionConfig *config = create_encryption_config(ALG_AES, mode, key);
    if (!config) {
        fprintf(stderr, "Failed to create encryption configuration.\n");
        return EXIT_FAILURE;
    }

    process_file(input_filename, output_filename, config);
    free_encryption_config(config);
#endif

    return 0;
}
```

### Key Points:
- The code uses OpenSSL for AES and ChaCha20 encryption. Ensure OpenSSL is installed and linked.
- Modes of operation include GCM (for authenticated encryption), CTR, and OFB.
- AES can use either a 128-bit or 256-bit key depending on the mode.
- For file processing, the utility reads from an input file, encrypts the data, and writes it to an output file. 
- The `process_file` function handles both AES and ChaCha20 encryption.
- Error handling is incorporated for robustness during file operations and cryptographic processes.
- This example is a starting point; performance optimizations can include threading or more efficient memory management based on specific use cases.']

