import java.util.*;
import java.io.*;
import java.net.HttpURLConnection;
import java.net.URL;

public class PokemonReportGenerator {

    private static final String API_URL = "https://api.example.com/pokemon/type";
    private Map<String, TypeData> typeCache = new ConcurrentHashMap<>();
    private List<PokemonEntry> pokemonEntries;
    private static final Logger logger = Logger.getLogger(PokemonReportGenerator.class.getName());

    public PokemonReportGenerator(List<PokemonEntry> pokemonEntries) {
        this.pokemonEntries = pokemonEntries;
    }

    public void generateReports() {
        for (PokemonEntry entry : pokemonEntries) {
            try {
                String typeAnalysis = getTypeData(entry.getType());
                logger.info("Processed: " + entry.getName());

                // Generate and log the report for each Pokemon
                System.out.println(generateReport(entry, typeAnalysis));
            } catch (Exception e) {
                logger.warning("Error processing entry " + entry.getName() + ": " + e.getMessage());
            }
        }
    }

    private String getTypeData(String type) throws IOException {
        return typeCache.computeIfAbsent(type, this::fetchTypeDataFromApi);
    }

    private String fetchTypeDataFromApi(String type) {
        try {
            URL url = new URL(API_URL + "/" + type);
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();
            conn.setRequestMethod("GET");

            if (conn.getResponseCode() == 200) {
                BufferedReader reader = new BufferedReader(new InputStreamReader(conn.getInputStream()));
                String response = reader.lines().reduce("", String::concat);
                conn.disconnect();

                TypeData data = parseTypeData(response);
                return data.toString();
            } else {
                logger.warning("API returned error for type: " + type);
                // Fallback logic for unrecognized types
                return fallbackForUnrecognizedTypes(type);
            }
        } catch (IOException e) {
            logger.severe("Failed to fetch type data from API for type: " + type + ", using fallback. Error: " + e.getMessage());
            return fallbackForUnrecognizedTypes(type);
        }
    }

    private TypeData parseTypeData(String jsonResponse) {
        // Parse JSON response and return a TypeData object
        // Placeholder parsing logic; replace with actual JSON parsing code
        return new TypeData("parsedWeaknesses", "parsedAdvantages", "parsedThreats");
    }

    private String fallbackForUnrecognizedTypes(String type) {
        // Suggest similar types or provide default response
        logger.info("Using fallback data for unrecognized type: " + type);
        return "Default weaknesses, advantages, and threats";
    }

    private String generateReport(PokemonEntry entry, String typeAnalysis) {
        return "Pokemon Name: " + entry.getName() +
                "\nType Analysis: " + typeAnalysis;
    }

    public static void main(String[] args) {
        // Example usage
        List<PokemonEntry> entries = new ArrayList<>();
        entries.add(new PokemonEntry("Pikachu", "Electric", "Forest"));

        PokemonReportGenerator reportGenerator = new PokemonReportGenerator(entries);
        reportGenerator.generateReports();
    }

    private static class TypeData {
        String weaknesses;
        String advantages;
        String threats;

        public TypeData(String weaknesses, String advantages, String threats) {
            this.weaknesses = weaknesses;
            this.advantages = advantages;
            this.threats = threats;
        }

        @Override
        public String toString() {
            return "Weaknesses: " + weaknesses +
                    ", Advantages: " + advantages +
                    ", Threats: " + threats;
        }
    }

    private static class PokemonEntry {
        private final String name;
        private final String type;
        private final String habitat;

        public PokemonEntry(String name, String type, String habitat) {
            this.name = name;
            this.type = type;
            this.habitat = habitat;
        }

        public String getName() { return name; }
        public String getType() { return type; }
    }

    private static class Logger {
        private final String loggerName;

        private Logger(String loggerName) {
            this.loggerName = loggerName;
        }

        public static Logger getLogger(String name) {
            return new Logger(name);
        }

        public void info(String message) {
            System.out.println("INFO: " + loggerName + " - " + message);
        }

        public void warning(String message) {
            System.err.println("WARNING: " + loggerName + " - " + message);
        }

        public void severe(String message) {
            System.err.println("SEVERE: " + loggerName + " - " + message);
        }
    }
}
