#include <vector>
#include <algorithm>
#include <iostream>

// Function to update the vector according to the specified rules.
void updateVector(std::vector<int>& vec, int target, int newValue) {
    bool found = false;

    // Search and replace all occurrences of 'target' with 'newValue'.
    for (auto& element : vec) {
        if (element == target) {
            element = newValue;
            found = true;
        }
    }

    // If no occurrence of 'target' was found, append 'newValue'.
    if (!found) {
        vec.push_back(newValue);
    }
}

// Validation function to ensure all occurrences are replaced and the new value is appended correctly.
bool validateUpdate(const std::vector<int>& vec, int target, int newValue) {
    bool shouldAppend = true;

    // Check that each 'target' has been replaced with 'newValue'.
    for (int element : vec) {
        if (element == target) {
            return false;  // If any original 'target' value remains, validation fails.
        }
        if (shouldAppend && element != newValue) {
            shouldAppend = false;
        }
    }

    // Ensure the new integer is appended correctly at the end, if it was added.
    size_t countNewValue = std::count(vec.begin(), vec.end(), newValue);

    if (shouldAppend && countNewValue == 1) { 
        // If 'newValue' should have been appended and only appears once in vector,
        // check it's at the end.
        return *std::find(vec.rbegin(), vec.rend(), newValue) == vec.back();
    } else {
        return true; // No appending was required, or multiple occurrences are valid.
    }
}

// Example usage:
int main() {
    std::vector<int> data = {1, 2, 3, 4, 5};

    int target = 3;
    int newValue = 99;

    updateVector(data, target, newValue);

    // Validate the update operation.
    if (validateUpdate(data, target, newValue)) {
        std::cout << "Update and validation successful.\n";
    } else {
        std::cout << "Validation failed.\n";
    }

    return 0;
}
