using System;
using System.Collections.Generic;
using System.Data.Common;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.Logging;

public class SqlQueryExecutor
{
    private readonly IMemoryCache _cache;
    private readonly ILogger<SqlQueryExecutor> _logger;

    public SqlQueryExecutor(IMemoryCache cache, ILogger<SqlQueryExecutor> logger)
    {
        _cache = cache ?? throw new ArgumentNullException(nameof(cache));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task<List<T>> ExecuteAsync<T>(
        string connectionString,
        string sqlTemplate,
        Dictionary<string, object> parameters,
        TimeSpan? cacheDuration = null
    )
    {
        if (string.IsNullOrWhiteSpace(connectionString))
            throw new ArgumentException("Connection string cannot be null or whitespace.", nameof(connectionString));

        // Cache key based on connection string and serialized parameters
        var cacheKey = GenerateCacheKey(connectionString, sqlTemplate, parameters);

        // Check cache first
        if (_cache.TryGetValue(cacheKey, out List<T> cachedResult))
        {
            _logger.LogInformation("Cache hit for query: {Query}", sqlTemplate);
            return cachedResult;
        }

        using (var connection = CreateDbConnection(connectionString))
        {
            try
            {
                await connection.OpenAsync();

                var command = PrepareCommand(connection, sqlTemplate, parameters);

                _logger.LogDebug("Executing SQL: {Sql} with Parameters: {Params}", command.CommandText, parameters);

                // Execute the query and populate results asynchronously
                using (var reader = await command.ExecuteReaderAsync())
                {
                    var result = new List<T>();
                    while (await reader.ReadAsync())
                    {
                        var item = ConvertToEntity<T>(reader);
                        result.Add(item);
                    }

                    // Store in cache if specified
                    if (cacheDuration.HasValue)
                    {
                        _cache.Set(cacheKey, result, cacheDuration.Value);
                        _logger.LogInformation("Result cached for query: {Query}", sqlTemplate);
                    }

                    return result;
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error executing SQL: {Sql}", sqlTemplate);
                throw new InvalidOperationException("An error occurred while executing the SQL command.", ex);
            }
        }
    }

    private DbConnection CreateDbConnection(string connectionString)
    {
        if (connectionString.Contains("postgres"))
        {
            return new Npgsql.NpgsqlConnection(connectionString); // For PostgreSQL
        }
        else
        {
            return new System.Data.SqlClient.SqlConnection(connectionString); // Default to SQL Server
        }
    }

    private DbCommand PrepareCommand(DbConnection connection, string sqlTemplate, Dictionary<string, object> parameters)
    {
        var command = connection.CreateCommand();
        command.CommandText = sqlTemplate;

        foreach (var param in parameters)
        {
            var dbParam = command.CreateParameter();
            dbParam.ParameterName = param.Key;
            dbParam.Value = param.Value ?? DBNull.Value;
            command.Parameters.Add(dbParam);
        }

        return command;
    }

    private string GenerateCacheKey(string connectionString, string sqlTemplate, Dictionary<string, object> parameters)
    {
        var paramsString = string.Join(";", parameters.Keys);
        return $"{connectionString}:{sqlTemplate}:{paramsString}";
    }

    private T ConvertToEntity<T>(DbDataReader reader)
    {
        // Implement conversion logic based on entity mapping
        throw new NotImplementedException();
    }
}
```

This code provides a flexible and efficient solution for executing SQL queries, incorporating caching, logging, error handling, and system compatibility. Adjust the connection creation and query execution logic according to your specific database systems and entity mapping requirements.']

