import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashSet;
import java.util.Optional;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class MD5HashProcessor {

    private final ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();
    private final Set<String> processedSet = ConcurrentHashMap.newKeySet();
    private final int maxCacheSize;
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);

    public MD5HashProcessor(int maxCacheSize) {
        this.maxCacheSize = maxCacheSize;
        scheduleEvictionPolicy();
    }

    public void processStringStream(java.util.function.Consumer<String> streamConsumer) {
        try {
            streamConsumer.accept(input -> {
                if (input == null || input.isEmpty()) {
                    return;
                }

                synchronized (processedSet) {
                    if (!processedSet.add(input)) {
                        System.err.println("Duplicate entry detected: " + input);
                        return;
                    }
                }

                String hash = computeMD5Hash(input);

                cache.putIfAbsent(hash, input);
                if (cache.size() > maxCacheSize) {
                    evictEntries();
                }
            });
        } catch (Exception e) {
            System.err.println("Error processing string stream: " + e.getMessage());
        }
    }

    private String computeMD5Hash(String input) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] hashBytes = md.digest(input.getBytes());

        StringBuilder sb = new StringBuilder();
        for (byte b : hashBytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    private void evictEntries() {
        if (cache.size() > maxCacheSize) {
            cache.keySet().iterator().remove(); // Simplified eviction strategy; implement a more sophisticated one as needed.
        }
    }

    private void scheduleEvictionPolicy() {
        scheduler.scheduleAtFixedRate(this::evictEntries, 0, 1, TimeUnit.MINUTES);
    }

    public Optional<String> getFromCache(String hash) {
        return Optional.ofNullable(cache.get(hash));
    }

    // Close the resources when no longer needed
    public void shutdown() {
        scheduler.shutdown();
        try {
            if (!scheduler.awaitTermination(5, TimeUnit.SECONDS)) {
                scheduler.shutdownNow();
            }
        } catch (InterruptedException e) {
            scheduler.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }

    public static void main(String[] args) {
        MD5HashProcessor processor = new MD5HashProcessor(1000);

        // Example usage
        processor.processStringStream(s -> {
            s.accept("test string 1");
            s.accept("another test string");
            s.accept(""); // Edge case: empty string
            s.accept(null); // Edge case: null input
        });

        Optional<String> cachedValue = processor.getFromCache("d86b2c7f4a6ecae3e5cf8b9cb1b1b0f1"); // Example MD5 hash
        if (cachedValue.isPresent()) {
            System.out.println("Cached value: " + cachedValue.get());
        } else {
            System.out.println("Value not in cache.");
        }

        processor.shutdown();
    }
}
