using System;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Memory;
using Newtonsoft.Json;

public class ContentService
{
    private readonly IMemoryCache _cache;
    private readonly IHtmlValidationService _htmlValidationService;
    private readonly IUserContentService _userContentService;
    private static readonly HttpClient _httpClient = new HttpClient();

    public ContentService(IMemoryCache cache, IHtmlValidationService htmlValidationService, IUserContentService userContentService)
    {
        _cache = cache;
        _htmlValidationService = htmlValidationService;
        _userContentService = userContentService;
    }

    public async Task<HttpResponseMessage> HandlePostRequestAsync(int pageSectionId, int elementId, string htmlContent, string languagePreference = null)
    {
        try
        {
            // Attempt to get validated HTML from cache
            var cacheKey = $"ValidatedHtml_{elementId}_{languagePreference ?? "default"}";
            if (!_cache.TryGetValue(cacheKey, out string validatedHtml))
            {
                // Validate the HTML content using a third-party API with caching
                validatedHtml = await GetAndCacheValidatedHtmlAsync(htmlContent);

                // Ensure fallback to default language if validation fails for specified language
                if (string.IsNullOrEmpty(validatedHtml) && !string.IsNullOrWhiteSpace(languagePreference))
                {
                    validatedHtml = await GetAndCacheValidatedHtmlAsync(htmlContent, null);
                }
            }

            if (!string.IsNullOrEmpty(validatedHtml))
            {
                // Update the content in a thread-safe manner
                await _userContentService.UpdateElementContentAsync(pageSectionId, elementId, validatedHtml);

                return new HttpResponseMessage(System.Net.HttpStatusCode.OK)
                {
                    Content = new StringContent(JsonConvert.SerializeObject(new { message = "Page refresh required" }))
                };
            }
        }
        catch (Exception ex)
        {
            // Log the error and decide on retry mechanism or alerting
            Console.WriteLine($"Error updating content: {ex.Message}");
        }

        return new HttpResponseMessage(System.Net.HttpStatusCode.InternalServerError);
    }

    private async Task<string> GetAndCacheValidatedHtmlAsync(string htmlContent, string language = null)
    {
        var cacheEntryOptions = new MemoryCacheEntryOptions()
            .SetSlidingExpiration(TimeSpan.FromSeconds(60)); // Cache validated HTML for 1 minute

        try
        {
            var response = await _httpClient.PostAsJsonAsync("https://api.htmlvalidation.com/validate", new { HtmlContent = htmlContent, Language = language });

            if (response.IsSuccessStatusCode)
            {
                var validationResponse = JsonConvert.DeserializeObject<HtmlValidationResponse>(await response.Content.ReadAsStringAsync());

                if (validationResponse.IsValid)
                {
                    _cache.Set(cacheEntryOptions, $"{language ?? "default"}_validatedHtml", validationResponse.ValidatedHtml);
                    return validationResponse.ValidatedHtml;
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"HTML Validation API failed: {ex.Message}");
        }

        // If unable to validate or fetch valid HTML, return null
        return null;
    }
}

public interface IHtmlValidationService
{
    Task<string> ValidateHtmlAsync(string htmlContent);
}

public interface IUserContentService
{
    Task UpdateElementContentAsync(int pageSectionId, int elementId, string validatedHtml);
}

// Define a response structure to parse validation API response
public class HtmlValidationResponse
{
    public bool IsValid { get; set; }
    public string ValidatedHtml { get; set; }
}
