public final class StateLoader {

    private static final String DEFAULT_THEME_DIR = "themes/default";
    private static Path themeDirectory;
    private static ConcurrentHashMap<String, BufferedImage> themeCacheMap = new ConcurrentHashMap<>();

    // Private constructor to prevent instantiation
    private StateLoader() {}

    // Method to load application state from a serialized file
    public static Object loadState(String filePath) {
        if (filePath == null || filePath.isEmpty()) return null;

        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filePath))) {
            Object state = ois.readObject();
            if (state instanceof MoSTState) {
                return state;
            }
        } catch (IOException | ClassNotFoundException e) {
            System.err.println("Error loading state: " + e.getMessage());
        }

        return null;
    }

    // Method to check and release theme bitmap resources
    public static void releaseThemeResources() {
        synchronized (themeCacheMap) {
            themeCacheMap.clear();
        }
    }

    // Method to verify and initialize the theme directory if not configured
    public static void ensureDefaultThemeDirectory() {
        if (themeDirectory == null || !Files.exists(themeDirectory)) {
            Path defaultDir = Paths.get(DEFAULT_THEME_DIR);
            try {
                Files.createDirectories(defaultDir);
                themeDirectory = defaultDir;
            } catch (IOException e) {
                System.err.println("Error initializing theme directory: " + e.getMessage());
            }
        }
    }

    // Method to parse a PNG image and store it in the theme cache
    public static void parseAndCacheThemeImage(String identifier, String imagePath) {
        if (identifier == null || imagePath == null || identifier.isEmpty() || imagePath.isEmpty()) return;

        Path path = Paths.get(imagePath);
        if (!Files.exists(path)) return;

        try (BufferedImage image = ImageIO.read(path.toFile())) {
            themeCacheMap.put(identifier, image);
        } catch (IOException e) {
            System.err.println("Error parsing theme image: " + e.getMessage());
        }
    }

    // Example placeholder class for MoSTState to demonstrate type checking
    public static class MoSTState implements Serializable {
        private static final long serialVersionUID = 1L;
        // State attributes and methods here...
    }
}
