using System;
using System.Collections.Concurrent;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;
using Newtonsoft.Json;

public class IdentityProviderIntegrationModule
{
    private readonly IConfiguration _configuration;
    private readonly HttpClient _httpClient;
    private static readonly ConcurrentDictionary<string, DateTime> UserLockoutStore = new();
    private const int LockoutThreshold = 5; // Maximum allowed attempts before lockout
    private const int LockoutDurationMinutes = 15;

    public IdentityProviderIntegrationModule(IConfiguration configuration)
    {
        _configuration = configuration;
        _httpClient = new HttpClient();
    }

    public async Task<bool> CreateUserAsync(string username, string password, string phoneNumber)
    {
        if (IsUserLockedOut(username))
        {
            LogEvent($"Account lockout: User '{username}' is temporarily locked.");
            return false;
        }

        // Assume CreateUserOnExternalProvider is a method that communicates with the external identity provider
        bool creationSuccess = await CreateUserOnExternalProviderAsync(username, password);

        if (creationSuccess)
        {
            RegisterMFAService(phoneNumber);
        }
        else
        {
            RecordFailedAttempt(username);
        }

        return creationSuccess;
    }

    private async Task<bool> CreateUserOnExternalProviderAsync(string username, string password)
    {
        var user = new { Username = username, Password = password };
        var content = new StringContent(JsonConvert.SerializeObject(user), System.Text.Encoding.UTF8, "application/json");

        var response = await _httpClient.PostAsync(_configuration["IdentityProviderUrl"], content);
        return response.IsSuccessStatusCode;
    }

    private void RegisterMFAService(string phoneNumber)
    {
        // Assume RegisterForMFA is a method that communicates with the external MFA service
        _httpClient.GetAsync($"{_configuration["MFAServerUrl"]}/register?phoneNumber={phoneNumber}");
        LogEvent($"User registered for MFA: Phone number '{phoneNumber}'.");
    }

    private void RecordFailedAttempt(string username)
    {
        var lockoutEntry = UserLockoutStore.GetOrAdd(username, DateTime.UtcNow);
        if (lockoutEntry.AddMinutes(LockoutDurationMinutes) > DateTime.UtcNow)
        {
            if (!UserLockoutStore.TryUpdate(username, lockoutEntry + 1, lockoutEntry))
                return;
        }
        else
        {
            UserLockoutStore[username] = 1;
        }

        if (UserLockoutStore[username] >= LockoutThreshold)
        {
            LogEvent($"Account locked: User '{username}' exceeded maximum failed attempts.");
            // Consider sending an alert or notification to the user
        }
    }

    private bool IsUserLockedOut(string username)
    {
        if (!UserLockoutStore.TryGetValue(username, out var attemptCount))
            return false;

        if (attemptCount >= LockoutThreshold &&
            DateTime.UtcNow <= UserLockoutStore[username].AddMinutes(LockoutDurationMinutes))
        {
            LogEvent($"Account is locked: User '{username}'.");
            return true;
        }

        // Reset attempts after lockout duration has passed
        if (DateTime.UtcNow > UserLockoutStore[username].AddMinutes(LockoutDurationMinutes))
        {
            UserLockoutStore.TryRemove(username, out _);
        }

        return false;
    }

    private void LogEvent(string message)
    {
        // Assume SendToLoggingService is a method that sends logs to an external logging service
        _httpClient.PostAsync(_configuration["LoggingServiceUrl"], new StringContent(message));
    }
}
