const fs = require('fs');
const path = require('path');
const util = require('util');
const readdir = util.promisify(fs.readdir);
const readFile = util.promisify(fs.readFile);
const { promisify } = require('util');
const parseStringPromise = promisify(require('xml2js').parseString);
const csvParse = require('csv-parse/lib/sync');
const Ajv = require('ajv');

// Example of external configuration for schemas
async function loadSchema() {
    const schemaContent = await readFile(path.resolve(__dirname, 'schema.json'));
    return JSON.parse(schemaContent);
}

function parseFileByExtension(content, extension) {
    switch (extension) {
        case '.json':
            return JSON.parse(content);
        case '.csv':
            return csvParse(content, { columns: true });
        case '.xml':
            return parseStringPromise(content).then(result => result);
        default:
            throw new Error(`Unsupported file type: ${extension}`);
    }
}

async function validateData(schema, data) {
    const ajv = new Ajv();
    const validate = ajv.compile(schema);
    if (!validate(data)) {
        throw new Error(`Validation errors: ${ajv.errorsText(validate.errors)}`);
    }
}

const concurrencyLimit = 20;
let currentConcurrentProcesses = 0;

async function processFile(filePath, schema) {
    try {
        const content = await readFile(filePath, 'utf8');
        const extension = path.extname(filePath);
        const data = await parseFileByExtension(content, extension);

        await validateData(schema, data);
        console.log(`Successfully processed and validated file: ${filePath}`);
    } catch (error) {
        console.error(`Error processing file ${filePath}:`, error.message);
    } finally {
        currentConcurrentProcesses--;
        releaseQueue();
    }
}

function acquireSemaphore() {
    return new Promise(resolve => {
        while (currentConcurrentProcesses >= concurrencyLimit) {}
        currentConcurrentProcesses++;
        resolve();
    });
}

async function processFilesInDirectory(directoryPath) {
    const files = await readdir(directoryPath);
    const schema = await loadSchema();

    const promises = files.map(async file => {
        await acquireSemaphore();
        const filePath = path.join(directoryPath, file);
        return processFile(filePath, schema[file]);
    });

    await Promise.all(promises);
}

// Usage
processFilesInDirectory('/path/to/directory')
  .then(() => console.log('All files processed.'))
  .catch(error => console.error('Error in processing:', error.message));
