(function() {
    let cachedScripts = null;
    let previousScriptSet = new Set();

    const renderFooterScripts = (scripts, forceRender = false) => {
        if (!Array.isArray(scripts)) return '';

        // Normalize and deduplicate scripts based on their id
        const normalizedScripts = scripts.reduce((acc, script) => {
            if (typeof script === 'object' && script.id) {
                acc[script.id] = script;
            }
            return acc;
        }, {});

        const currentScriptSet = new Set(Object.keys(normalizedScripts));

        // Check for change in scripts
        const hasChanged = forceRender || !previousScriptSet.size 
                            || !currentScriptSet.size 
                            || ![...previousScriptSet].every(id => currentScriptSet.has(id))
                            || [...currentScriptSet].some(id => !previousScriptSet.has(id));

        if (!hasChanged) {
            return cachedScripts;
        }

        previousScriptSet = new Set(currentScriptSet);

        const scriptTags = Object.values(normalizedScripts).map(script => {
            return `<script id="${script.id}" type="text/javascript">${script.content || ''}</script>`;
        });

        cachedScripts = scriptTags.join('');
        return cachedScripts;
    };

    // Expose the function to be used elsewhere
    window.renderFooterScripts = renderFooterScripts;

})();
