async function refreshDialogFields(fieldNamesToCheck, fetchUrl) {
    if (!Array.isArray(fieldNamesToCheck) || typeof fetchUrl !== 'string') {
        throw new Error('Invalid input types');
    }

    const dialogFields = []; // Assume this is populated with your application's fields
    let updateResults = [];

    async function fetchData(fieldName, retries = 3) {
        try {
            const response = await fetch(`${fetchUrl}/${fieldName}`, { timeout: 5000 }); // Timeout example for Fetch
            if (!response.ok) throw new Error('Network response was not ok');
            return response.json();
        } catch (error) {
            if (retries > 0) {
                await new Promise(res => setTimeout(res, Math.pow(2, 3 - retries) * 1000)); // Exponential backoff
                return fetchData(fieldName, retries - 1);
            }
            console.error(`Failed to fetch data for ${fieldName}:`, error);
            throw error;
        }
    }

    const updatePromises = dialogFields.map(async field => {
        if (fieldNamesToCheck.includes(field.name)) {
            try {
                await fetchData(field.name);
                return { fieldName: field.name, success: true };
            } catch {
                return { fieldName: field.name, success: false };
            }
        }
    });

    updateResults = await Promise.all(updatePromises).then(results => results.filter(Boolean));

    return updateResults;
}

