#include <forward_list>
#include <string>

void insertAfterInForwardList(std::forward_list<std::string>& list, const std::string& target, const std::string& toInsert) {
    auto it = list.begin();
    for (; it != list.end(); ++it) {
        if (*it == target) {
            list.insert_after(it, toInsert);
            return;
        }
    }
    // If the target is not found, append to the end
    list.push_back(toInsert);
}

