import java.util.concurrent.*;
import java.util.logging.Level;
import java.util.logging.Logger;

public class DataProcessingService {

    private final BlockingQueue<DataItem> queue = new LinkedBlockingQueue<>();
    private final ExecutorService executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
    private volatile boolean running = false;
    private volatile boolean paused = false;
    private final Logger logger = Logger.getLogger(DataProcessingService.class.getName());

    public void start() {
        running = true;
        for (int i = 0; i < Runtime.getRuntime().availableProcessors(); i++) {
            executorService.submit(worker);
        }
    }

    public void stop() {
        running = false;
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
            logState("Service stopped");
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            logger.log(Level.SEVERE, "Interrupted during shutdown", e);
        }
    }

    public void pause() {
        paused = true;
    }

    public void resume() {
        paused = false;
    }

    private Runnable worker = () -> {
        while (running || !queue.isEmpty()) {
            if (!paused) {
                try {
                    DataItem dataItem = queue.poll(1, TimeUnit.SECONDS);
                    if (dataItem != null) {
                        process(dataItem);
                    }
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    logger.log(Level.SEVERE, "Worker interrupted", e);
                }
            }
        }
    };

    private void process(DataItem dataItem) {
        try {
            // Integrate with external data source and third-party messaging system
            if (!sendToMessagingSystem(dataItem)) {
                handleIntegrationFailure(dataItem);
            }
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Error processing data item", e);
        }
    }

    private boolean sendToMessagingSystem(DataItem dataItem) {
        // Simulate sending to a messaging system
        return true; // or false if integration fails
    }

    private void handleIntegrationFailure(DataItem dataItem) {
        logger.log(Level.WARNING, "Integration failure for data item: " + dataItem);
        // Retry logic or alternative handling
    }

    public void enqueueData(DataItem dataItem) {
        try {
            queue.put(dataItem);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            logger.log(Level.SEVERE, "Interrupted while enqueuing data", e);
        }
    }

    private void logState(String message) {
        // Log to centralized monitoring system with configurable delay
        ScheduledExecutorService scheduler = Executors.newSingleThreadScheduledExecutor();
        scheduler.schedule(() -> {
            // Simulate logging state
            logger.info(message);
        }, 5, TimeUnit.SECONDS);
        scheduler.shutdown();
    }

    public static class DataItem {
