    <script>
        const maxLoadTime = 10000; // 10 seconds

        function processFilename(filename) {
            let digitsCount = 0;
            let fileType = '';

            for (let char of filename) {
                if (!isNaN(char)) digitsCount++;
                if (char === '.') {
                    fileType = filename.substring(char + 1);
                    break;
                }
            }

            const newExtension = `${fileType}_${digitsCount}digits`;
            return `.${newExtension}`;
        }

        async function fetchFile(url) {
            try {
                const response = await fetch(url, { timeout: maxLoadTime });
                if (!response.ok) throw new Error(`Failed to load ${url}`);
                return await response.text();
            } catch (error) {
                console.error(error.message);
                return null;
            }
        }

        function executeScript(scriptText) {
            try {
                eval(scriptText);
            } catch (error) {
                console.error('Error executing script:', error);
            }
        }

        async function loadAndExecuteFiles(fileList, cache = {}) {
            const startTime = Date.now();

            for (let file of fileList) {
                if (cache[file]) {
                    executeScript(cache[file]);
                    continue;
                }

                const endTime = Date.now();
                if (endTime - startTime > maxLoadTime) {
                    console.error('Loading time exceeded the limit');
                    break;
                }

                const scriptText = await fetchFile(file);
                if (!scriptText) continue;

                cache[file] = scriptText;
                executeScript(scriptText);

                // Simulate processing filename to modify extension
                const newExtension = processFilename(file.split('/').pop());
                console.log(`Processed ${file} with new extension: ${newExtension}`);
            }
        }

        document.addEventListener('DOMContentLoaded', () => {
            const filesToLoad = [
                'script1.js',
                'library2.js',
                'module3.js'
            ];

            loadAndExecuteFiles(filesToLoad);
        });
    </script>
</head>
