import java.io.IOException;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.Logger;

public class DirectoryAnalyzer {
    private static final Logger logger = Logger.getLogger(DirectoryAnalyzer.class.getName());
    private final MetadataService metadataService;

    public DirectoryAnalyzer(MetadataService metadataService) {
        this.metadataService = metadataService;
    }

    public Map<String, Object> analyzeFilePaths(List<Path> filePaths) throws IOException, ExecutionException, InterruptedException {
        ConcurrentNavigableMap<String, Boolean> uniqueDirectories = new ConcurrentSkipListSet<>();
        ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        List<Future<FileMetadata>> futures = new ArrayList<>();

        long startTime = System.currentTimeMillis();

        for (Path filePath : filePaths) {
            final Path path = filePath;
            futures.add(executor.submit(() -> processFilePath(path)));
        }

        // Shutdown executor and wait for completion
        executor.shutdown();
        executor.awaitTermination(1, TimeUnit.HOURS);

        long endTime = System.currentTimeMillis();
        logger.info("Total processing time: " + (endTime - startTime) + " ms");

        Map<String, Object> report = new HashMap<>();
        uniqueDirectories.forEach((directory, _) -> {
            if (!isHidden(directory)) {
                uniqueDirectories.put(directory, true);
            }
        });

        // Gather directory count
        report.put("uniqueDirectoryCount", uniqueDirectories.size());

        // Collect file metadata information for reporting
        Map<String, FileMetadata> metadataMap = new HashMap<>();
        futures.forEach(future -> {
            try {
                FileMetadata metadata = future.get();
                if (metadata != null) {
                    metadataMap.put(metadata.getPath().toString(), metadata);
                }
            } catch (ExecutionException | InterruptedException e) {
                logger.warning("Failed to fetch file metadata: " + e.getMessage());
            }
        });

        report.put("fileMetadatas", metadataMap);

        // Optionally, collect memory usage metrics
        long usedMemory = Runtime.getRuntime().totalMemory() - Runtime.getRuntime().freeMemory();
        report.put("memoryUsageInMB", usedMetadata / (1024 * 1024));

        return report;
    }

    private FileMetadata processFilePath(Path path) {
        long startMillis = System.currentTimeMillis();

        try {
            Path absolutePath = path.toRealPath();
            Files.walkFileTree(absolutePath.getParent(), new SimpleFileVisitor<Path>() {
                @Override
                public FileVisitResult preVisitDirectory(Path dir, BasicFileAttributes attrs) {
                    if (!isHidden(dir)) {
                        uniqueDirectories.add(dir.toString());
                    }
                    return FileVisitResult.CONTINUE;
                }
            });

        } catch (IOException e) {
            logger.warning("Failed to process path: " + path + " due to " + e.getMessage());
            return null;
        }

        long endMillis = System.currentTimeMillis();
        logger.info("Time taken for path: " + path + ": " + (endMillis - startMillis) + " ms");

        // Fetch additional metadata from the external service
        FileMetadata metadata = metadataService.fetchFileMetadata(path);

        if (metadata == null) {
            logger.warning("Failed to fetch metadata for path: " + path);
        }

        return metadata;
    }

    private boolean isHidden(Path path) {
        String name = path.getFileName().toString();
        return name.startsWith(".");
    }
}

interface MetadataService {
    FileMetadata fetchFileMetadata(Path filePath) throws IOException;
}

class FileMetadata {
    private final Path path;
    private final long size;
    private final Date lastModified;

    public FileMetadata(Path path, long size, Date lastModified) {
        this.path = path;
        this.size = size;
        this.lastModified = lastModified;
    }

    public Path getPath() {
        return path;
    }

    public long getSize() {
        return size;
    }

    public Date getLastModified() {
        return lastModified;
    }
}
```

### Notes:
- The `MetadataService` interface is assumed to be implemented elsewhere, which provides file metadata.
- The solution uses a concurrent data structure and executor services for efficient parallel processing.
- Logging captures the time taken to process each path.
- Memory usage statistics are gathered as part of the report.']

['```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.Level;
import java.util.logging.Logger;

public class ConnectionManager {
    private static final Logger logger = Logger.getLogger(ConnectionManager.class.getName());
    private final ExecutorService executorService;
    private final ScheduledExecutorService scheduledExecutorService;
    private final Map<SocketAddress, SelectionKey> connectionMap;
    private final int timeoutMillis;

    public ConnectionManager(int threadPoolSize, int timeoutMillis) {
        this.executorService = Executors.newFixedThreadPool(threadPoolSize);
        this.scheduledExecutorService = Executors.newScheduledThreadPool(1);
        this.connectionMap = new ConcurrentHashMap<>();
        this.timeoutMillis = timeoutMillis;
    }

    public void start() {
        logger.info("Connection Manager started.");
        // Periodically check for timed-out connections
        scheduledExecutorService.scheduleAtFixedRate(this::checkTimeouts, 0, timeoutMillis, TimeUnit.MILLISECONDS);
    }

    public Future<Void> connect(InetSocketAddress address) {
        return executorService.submit(() -> {
            try (SocketChannel socketChannel = SocketChannel.open()) {
                socketChannel.configureBlocking(false);
                if (!socketChannel.connect(address)) {
                    SelectionKey key = socketChannel.register(selector, SelectionKey.OP_CONNECT);
                    connectionMap.put(address, key);
                    logger.info("Connection initiated to: " + address);
                }
            } catch (IOException e) {
                logger.log(Level.SEVERE, "Failed to connect to: " + address, e);
            }
        });
    }

    private void checkTimeouts() {
        long currentTime = System.currentTimeMillis();
        connectionMap.forEach((address, key) -> {
            if (!key.isValid()) {
                connectionMap.remove(address);
                logger.info("Connection removed for timed-out address: " + address);
            } else if (isTimedOut(key, currentTime)) {
                try {
                    key.cancel();
                    socketChannel(key).close();
                    connectionMap.remove(address);
                    logger.warning("Connection timed out for address: " + address);
                } catch (IOException e) {
                    logger.log(Level.SEVERE, "Failed to close timed-out connection for: " + address, e);
                }
            }
        });
    }

    private boolean isTimedOut(SelectionKey key, long currentTime) throws ClosedChannelException {
        if (!(key.attachment() instanceof Long)) return false;
        long startTime = (Long) key.attachment();
        return (currentTime - startTime) > timeoutMillis;
    }

    private SocketChannel socketChannel(SelectionKey key) throws IOException {
        return (SocketChannel) key.channel();
    }

    public void stop() {
        scheduledExecutorService.shutdownNow();
        executorService.shutdownNow();
        connectionMap.values().forEach(key -> {
            try {
                if (key.isValid()) key.cancel();
            } catch (ClosedChannelException e) {
                logger.log(Level.SEVERE, "Error during shutdown", e);
            }
        });
        logger.info("Connection Manager stopped.");
    }

    public static void main(String[] args) {
        ConnectionManager manager = new ConnectionManager(10, 5000);
        manager.start();

        // Example of connecting to a remote address
        Future<Void> connectionFuture = manager.connect(new InetSocketAddress("example.com", 80));

        try {
            connectionFuture.get();
        } catch (InterruptedException | ExecutionException e) {
            logger.log(Level.SEVERE, "Error during connection attempt", e);
        }

        // Shutdown manager after some time for demo purposes
        Runtime.getRuntime().addShutdownHook(new Thread(manager::stop));
    }
}
```

### Explanation:
- **Executor Services**: Used for managing threads to handle connections concurrently and periodic tasks.
- **NIO Channels & SelectionKeys**: Utilized for non-blocking I/O operations, allowing efficient connection management.
- **Scheduled Executor Service**: Periodically checks for timeout conditions on each connection.
- **Connection Map**: Maintains active connections with their corresponding `SelectionKey` objects.
- **Logging**: Integrated to track connection events and errors using Java's logging framework.']

