    let initial_rss = get_resident_set_size();

    let mut retry_count = 0;
    loop {
        match catch_with_exit_code(|args| args.run()) {
            Ok(exit_code) => return Ok(exit_code),
            Err(e) if retry_count < config.retries => {
                log_error(
                    "Compilation error: {}. Retrying {}/{}...",
                    (e.to_string(), retry_count + 1, config.retries)
                );
                std::thread::sleep(config.retry_delay);
                retry_count += 1;
            }
            Err(e) => return Err(Error::CompilationFailed {
                code: e.to_error().unwrap_or(1),
            })
            .context("Failed to compile"),
        }
