import requests
from typing import Optional

def get_user_details(user_id: int, page_size: int = 10, page_number: int = 1) -> dict:
    """
    Retrieves user details from a paginated API endpoint.

    Parameters:
    - user_id (int): The unique identifier for the user.
    - page_size (int): The number of records to retrieve per page.
    - page_number (int): The page number to retrieve.

    Returns:
    - dict: A dictionary containing the user's name, email, and profile picture URL.

    Raises:
    - ValueError: If user_id is invalid or if no data is found for the given user.
    - requests.exceptions.RequestException: For network-related errors.
    """

    API_URL = "https://api.example.com/users"
    headers = {
        'Authorization': 'Bearer YOUR_ACCESS_TOKEN',
        'Accept': 'application/json'
    }

    params = {
        'user_id': user_id,
        'page_size': page_size,
        'page_number': page_number
    }

    try:
        response = requests.get(API_URL, headers=headers, params=params)

        # Check for HTTP status codes and handle them accordingly
        if response.status_code == 404:
            raise ValueError(f"No user found with ID: {user_id}")
        elif response.status_code == 429:
            print("Rate limit exceeded. Please try again later.")
            return {}
        elif not response.ok:
            response.raise_for_status()

        data = response.json()

        # Check if the API response contains the expected data
        if 'name' in data and 'email' in data and 'profile_picture_url' in data:
            return {
                'name': data['name'],
                'email': data['email'],
                'profile_picture_url': data['profile_picture_url']
            }
        else:
            raise ValueError("Unexpected API response structure.")

    except requests.exceptions.RequestException as e:
        print(f"Network error occurred: {e}")
        return {}
