["```javascript
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

function generateConfiguredRandomString(directoryPath) {
    return readFileContents(path.join(directoryPath, 'config.json'))
        .then(configStr => {
            let config;
            try {
                config = JSON.parse(configStr);
            } catch (err) {
                logError(`Invalid JSON format: ${err.message}`);
                throw new Error('Configuration file is not valid JSON.');
            }

            const { charset = '', length = 10 } = config;

            if (!charset || !length) {
                logError('Character set or length missing in configuration.');
                throw new Error('Required fields are missing in the configuration file.');
            }

            const randomString = generateRandomString(charset, length);
            return hashString(randomString);
        })
        .catch(err => {
            logError(`Error: ${err.message}`);
            throw err;
        });
}

function readFileContents(filePath) {
    return new Promise((resolve, reject) => {
        fs.readFile(filePath, 'utf8', (err, data) => {
            if (err) {
                const errorMessage = err.code === 'ENOENT' ? 'File not found.' : `Unable to access file: ${err.message}`;
                logError(errorMessage);
                reject(new Error(errorMessage));
            } else {
                resolve(data);
            }
        });
    });
}

function generateRandomString(charset, length) {
    let result = '';
    for (let i = 0; i < length; i++) {
        const randomIndex = Math.floor(Math.random() * charset.length);
        result += charset[randomIndex];
    }
    return result;
}

function hashString(input) {
    return crypto.createHash('sha256').update(input).digest('hex');
}

function logError(message) {
    const logFilePath = path.join(__dirname, 'error.log');
    const timestamp = new Date().toISOString();
    const logMessage = `${timestamp} - ERROR: ${message}\n`;

    fs.appendFile(logFilePath, logMessage, err => {
        if (err) console.error('Failed to write to log file:', err);
    });
}

// Example usage
generateConfiguredRandomString('./config-directory')
    .then(hashedString => console.log(`Hashed String: ${hashedString}`))
    .catch(err => console.error(err.message));
