["```javascript
const axios = require('axios');
const { Readable } = require('stream');

async function fetchStream(url) {
    const response = await axios({
        url,
        method: 'GET',
        responseType: 'stream'
    });

    if (!response.status === 200) {
        throw new Error(`Failed to fetch data from ${url}`);
    }

    return response.data;
}

function pauseAndResume(stream, onPaused, onResumed) {
    stream.on('pause', () => onPaused());
    stream.on('resume', () => onResumed());
}

async function generateCertificateFromStream(oauthRequest) {
    const privateKeyUrl = oauthRequest.privateKeyLocation;
    const certificateUrl = oauthRequest.certificateLocation;

    try {
        const privateKeyStreamPromise = fetchStream(privateKeyUrl);
        const certificateStreamPromise = fetchStream(certificateUrl);

        const [privateKeyStream, certificateStream] = await Promise.all([privateKeyStreamPromise, certificateStreamPromise]);

        const combinedStream = new Readable({
            read() {}  // No-op. We're manually pushing data into this stream.
        });

        pauseAndResume(privateKeyStream, () => console.log('Private key stream paused'), () => console.log('Private key stream resumed'));
        pauseAndResume(certificateStream, () => console.log('Certificate stream paused'), () => console.log('Certificate stream resumed'));

        async function processStreams() {
            let ended = false;

            privateKeyStream.on('data', (chunk) => {
                if (!ended) combinedStream.push(chunk);
            });

            certificateStream.on('data', (chunk) => {
                if (!ended) combinedStream.push(chunk);
            });

            privateKeyStream.on('end', () => {
                if (!certificateStream.ended) return;
                ended = true;
                combinedStream.push(null);  // Signal that there is no more data to be read from the stream.
            });

            certificateStream.on('end', () => {
                if (!privateKeyStream.ended) return;
                ended = true;
                combinedStream.push(null);
            });
        }

        processStreams();

        const pemChunks = [];
        for await (const chunk of combinedStream) {
            pemChunks.push(chunk);
        }

        const pemData = Buffer.concat(pemChunks).toString('utf8');
        console.log('PEM Data:', pemData);

    } catch (error) {
        console.error(`Error generating certificate: ${error.message}`);
    }
}

// Example usage
const oauthRequest = {
    privateKeyLocation: 'https://example.com/private-key.pem',
    certificateLocation: 'https://example.com/certificate.pem'
};

generateCertificateFromStream(oauthRequest);
