<?php

class DnsCache {
    private $cache = [];
    private static $instance;

    private function __construct() {}

    public static function getInstance() {
        if (self::$instance === null) {
            self::$instance = new DnsCache();
        }
        return self::$instance;
    }

    public function get($key) {
        return isset($this->cache[$key]) ? $this->cache[$key] : false;
    }

    public function set($key, $value) {
        $this->cache[$key] = $value;
    }
}

class OAuthTokenCache {
    private $cache = [];
    private static $instance;

    private function __construct() {}

    public static function getInstance() {
        if (self::$instance === null) {
            self::$instance = new OAuthTokenCache();
        }
        return self::$instance;
    }

    public function get($client_id) {
        return isset($this->cache[$client_id]) ? $this->cache[$client_id] : false;
    }

    public function set($client_id, $token_data) {
        $this->cache[$client_id] = $token_data;
    }
}

function resolveAndAuthenticateHost($hostname, $oauthConfig) {
    session_start();

    // DNS Cache
    $dnsCache = DnsCache::getInstance();
    $cachedIp = $dnsCache->get($hostname);

    if ($cachedIp === false) {
        try {
            $ipAddress = gethostbyname($hostname);
            if (checkdnsrr($ipAddress, 'A')) {
                $resolvedHostname = gethostbyaddr($ipAddress);
                if ($resolvedHostname == $hostname) {
                    $dnsCache->set($hostname, $ipAddress);
                } else {
                    throw new Exception('Reverse DNS mismatch.');
                }
            } else {
                throw new Exception('DNS resolution failed.');
            }
        } catch (Exception $e) {
            return ['error' => 'DNS resolution error: ' . $e->getMessage()];
        }
    } else {
        $ipAddress = $cachedIp;
    }

    // OAuth Token Cache
    $tokenCache = OAuthTokenCache::getInstance();
    $clientId = $oauthConfig['client_id'];
    $accessToken = $tokenCache->get($clientId);

    if ($accessToken === false || (time() > $accessToken['expires_at'])) {
        try {
            $ch = curl_init();
            curl_setopt($ch, CURLOPT_URL, $oauthConfig['token_url']);
            curl_setopt($ch, CURLOPT_POST, true);
            curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query([
                'grant_type' => 'client_credentials',
                'client_id' => $oauthConfig['client_id'],
                'client_secret' => $oauthConfig['client_secret']
            ]));
            curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);

            $response = curl_exec($ch);
            if (curl_errno($ch)) {
                throw new Exception('OAuth authentication error: ' . curl_error($ch));
            }

            $tokenData = json_decode($response, true);
            if (!isset($tokenData['access_token'])) {
                throw new Exception('Invalid OAuth response.');
            }

            $accessToken = [
                'token' => $tokenData['access_token'],
                'expires_at' => time() + $tokenData['expires_in']
            ];

            $_SESSION['oauth_access_token'] = $accessToken;
            $tokenCache->set($clientId, $accessToken);

        } catch (Exception $e) {
            return ['error' => 'OAuth authentication error: ' . $e->getMessage()];
        }
    }

    return [
        'ip_address' => $ipAddress,
        'access_token' => $_SESSION['oauth_access_token']
    ];
}

?>
```

This PHP function `resolveAndAuthenticateHost` performs DNS resolution and OAuth 2.0 client credentials authentication for a given hostname, handling caching for both resolved IP addresses and access tokens to optimize performance under high concurrency. The code includes error handling for network failures, DNS resolution timeouts, and OAuth authentication issues."]

