// Function to generate state sequence from FSA and store in a linked list
Node* generate_state_sequence(int* initial_states, int num_initial_states,
                              FSA* fsa, int final_state) {
    if (!fsa || !initial_states || num_initial_states <= 0) return NULL;

    Node* head = NULL;
    pthread_mutex_lock(&fsa_lock);

    for (int i = 0; i < num_initial_states; ++i) {
        int state = initial_states[i];
        Node** current = &head;

        while (state != final_state) {
            // Allocate memory from the pool
            Node* new_node = (Node*)memory_pool_alloc(sizeof(Node));
            if (!new_node) {
                pthread_mutex_unlock(&fsa_lock);
                return NULL;
            }

            new_node->state = state;
            new_node->next = NULL;

            // Append to linked list
            *current = new_node;
            current = &(*current)->next;

            // Determine next state based on FSA transitions (simplified)
            // This should be replaced with actual transition logic from the FSA
            state = (state + 1) % fsa->num_states; // Example transition

            if (!*current && state != final_state) {
                memory_pool_free(new_node);
            }
        }
    }

    pthread_mutex_unlock(&fsa_lock);
    return head;
}

