#include <iostream>
#include <mutex>
#include <random>
#include <chrono>
#include <thread>
#include <atomic>

class AttackSelector {
public:
    AttackSelector() 
        : cooldown(9), attackCounts{0, 0, 0}, sessionActive(false) {}

    void startSession() {
        std::lock_guard<std::mutex> lock(mutex_);
        sessionActive = true;
        resetAttackCounts();
    }

    void endSession() {
        std::lock_guard<std::mutex> lock(mutex_);
        sessionActive = false;
    }

    void selectAttack() {
        if (!sessionActive) return;

        auto now = std::chrono::steady_clock::now();
        std::lock_guard<std::mutex> lock(mutex_);

        if (lastUsedTime + cooldown < now) {
            int attack = weightedRandomSelection();
            lastUsedTime = now;
            updateAttackCounts(attack);

            std::cout << "Selected Attack: " << attack + 1 << std::endl;

            // Simulate external configuration or data source impact
            adjustProbabilitiesBasedOnExternalData();
        }
    }

private:
    const int cooldown;
    std::chrono::steady_clock::time_point lastUsedTime;
    std::mutex mutex_;
    std::atomic<int> attackCounts[3];
    bool sessionActive;

    void resetAttackCounts() {
        for (int &count : attackCounts) {
            count = 0;
        }
    }

    int weightedRandomSelection() {
        static double probabilities[] = {0.4, 0.35, 0.25}; // Initial weights
        std::discrete_distribution<int> dist(probabilities, probabilities + 3);

        return dist(generator_);
    }

    void updateAttackCounts(int attack) {
        ++attackCounts[attack];
    }

    void adjustProbabilitiesBasedOnExternalData() {
        // Placeholder for external data influence logic
        // For example, modify weights based on real-time player statistics or global events.
    }

    static std::random_device rd;
    static std::mt19937 generator_;
};

std::random_device AttackSelector::rd;
std::mt19937 AttackSelector::generator_(AttackSelector::rd());

int main() {
    AttackSelector selector;

    selector.startSession();

    for (int i = 0; i < 100; ++i) {
        selector.selectAttack();
        std::this_thread::sleep_for(std::chrono::milliseconds(500)); // Simulating rapid calls
    }

    selector.endSession();

    return 0;
}
