// Callback function prototype
void callback(const char* str);

// C function to process a string
const char* processString(const char* input, int sizeLimit, void (*callbackFunc)(const char*)) {
    if (!input || sizeLimit <= 0) return NULL;

    int length = strlen(input);
    if (length > sizeLimit) return NULL;

    // Allocate memory for the new string with a slash at the end
    const size_t newSize = length + 2; // +1 for '/' and +1 for '\0'
    char* modifiedString = (char*)malloc(newSize);
    if (!modifiedString) return NULL;

    strcpy(modifiedString, input);
    strcat(modifiedString, "/");

    // Pass the modified string to the callback
    callbackFunc(modifiedString);

    // Return a pointer to allow caller to free memory if needed
    return modifiedString;
}

// Example callback function
void exampleCallback(const char* str) {
    printf("Processed String: %s\n", str);
}

int main() {
    const char* result = processString("example", 10, exampleCallback);
    if (result) {
        free((void*)result); // Free allocated memory
    }
    return 0;
}
