```javascript
function traverseDOM(node, filterFunc, config) {
    const results = [];
    const { depthLimit = Infinity, includeTextNodes = false, ignoreHiddenElements = true } = config;

    function isElementVisible(element) {
        if (!element.offsetParent && element.offsetWidth === 0 && element.offsetHeight === 0) {
            return false;
        }
        return true;
    }

    function traverse(currentNode, currentDepth) {
        if (currentDepth > depthLimit || !node || node.nodeType !== Node.ELEMENT_NODE) return;

        // Filter based on class or ID
        if ((filterFunc && filterFunc(currentNode)) ||
            (includeTextNodes && currentNode.nodeType === Node.TEXT_NODE)) {

            if (!ignoreHiddenElements || isElementVisible(currentNode)) {
                results.push(currentNode);
            }
        }

        for (let i = 0; i < currentNode.childNodes.length; i++) {
            traverse(currentNode.childNodes[i], currentDepth + 1);
        }
    }

    traverse(node, 0);
    return results;
}

// Example usage
document.addEventListener("DOMContentLoaded", function() {
    const filteredNodes = traverseDOM(document.body, (element) => element.classList.contains('myClass'), {
        depthLimit: 3,
        includeTextNodes: true,
        ignoreHiddenElements: false
    });

    console.log(filteredNodes);
});
```

These implementations handle edge cases such as empty strings or zero size limits in C and provide configurable options for DOM traversal in JavaScript, ensuring both efficiency and logical consistency.']

