char* process_line(const char *line) {
    char *result = malloc(MAX_LINE_LENGTH);
    if (!result) return NULL;

    char *token;
    char *last_fields[2] = {NULL, NULL};
    int field_count = 0;

    token = strtok((char *)line, ",");
    while (token != NULL && field_count < 2) {
        last_fields[field_count++] = strdup(token);
        token = strtok(NULL, ",");
    }

    if (field_count == 2) {
        double num1 = atof(last_fields[0]);
        double num2 = atof(last_fields[1]);
        double average = (num1 + num2) / 2.0;

        snprintf(result, MAX_LINE_LENGTH, "%s,%s,%.2f", line, last_fields[0], average);
    } else {
        strncpy(result, line, MAX_LINE_LENGTH - 1);
