['```c
#include <openssl/evp.h>
#include <openssl/kdf.h>
#include <openssl/sha.h>
#include <stdio.h>
#include <stdlib.h>
import os
from pathlib import Path
import threading

# Define constants
DEFAULT_THEME_DIR = "/default/theme/dir"
CACHE_ROOT = "/cache/root/"
IV_LENGTH = 16
KEY_LENGTH = 32
THREAD_LOCK = threading.Lock()

class ThemeCache:
    def __init__(self):
        self.cache = {}
        self.lock = THREAD_LOCK

    def get(self, key):
        with self.lock:
            return self.cache.get(key)

    def set(self, key, value):
        with self.lock:
            self.cache[key] = value

theme_cache = ThemeCache()

def derive_key(password: bytes) -> bytes:
    kdf_ctx = EVP_KDF_CTX_new(EVP_KDF_BLAKE2S128(), password, None, None)
    key_len = KEY_LENGTH
    key = bytearray(key_len)

    if not EVP_KDF_derive(kdf_ctx, key, key_len):
        raise Exception("Key derivation failed")

    EVP_KDF_free(kdf_ctx)
    return bytes(key)

def init_aes_cipher(password: str) -> EVP_CIPHER_CTX*:
    ctx = EVP_CIPHER_CTX_new()
    if not ctx:
        raise Exception("Cipher context allocation failed")

    password_bytes = password.encode('utf-8')
    key = derive_key(password_bytes)
    iv = os.urandom(IV_LENGTH)

    if not EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), None, key, iv):
        EVP_CIPHER_CTX_free(ctx)
        raise Exception("Cipher initialization failed")

    return ctx

def manage_theme_bitmap(bitmap=None):
    if bitmap is not None:
        # Recycle the bitmap
        del bitmap  # Simulate recycling by deleting reference
        return None
    else:
        # Initialize or recycle a default bitmap as needed
        return None

def check_and_set_default_theme_dir():
    theme_dir = Path(DEFAULT_THEME_DIR)
    if not theme_dir.exists():
        os.makedirs(theme_dir, exist_ok=True)

def parse_png_from_cache(user_path: str) -> bytes:
    safe_path = CACHE_ROOT + user_path.lstrip("/")
    path = Path(safe_path).resolve()

    # Ensure that the file is within CACHE_ROOT
    if not path.is_relative_to(CACHE_ROOT):
        raise Exception("Invalid path")

    with open(path, 'rb') as f:
        return f.read()

def cache_png_data(user_path: str, png_data: bytes):
    theme_cache.set(user_path, png_data)

def cleanup_cipher_context(ctx: EVP_CIPHER_CTX*):
    if ctx:
        EVP_CIPHER_CTX_free(ctx)

# Example usage
password = "your_secure_password"
cipher_ctx = init_aes_cipher(password)
try:
    manage_theme_bitmap()
    check_and_set_default_theme_dir()

    user_png_path = "path/to/user/png.png"
    png_data = parse_png_from_cache(user_png_path)
    cache_png_data(user_png_path, png_data)

finally:
    cleanup_cipher_context(cipher_ctx)
```

