#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <jansson.h>
#include <curl/curl.h>

#define SUCCESS 0
#define FAILURE 1

typedef struct {
    void (*log)(const char* message);
    void (*setup_database_connection)(const char* url);
} Dependencies;

// Utility function to check if a string is non-empty
int is_non_empty_string(const char *str) {
    return str && strlen(str) > 0;
}

// Validates the port number as a positive integer
int validate_positive_integer(const char *str, int *value) {
    char *endptr = NULL;
    long int val = strtol(str, &endptr, 10);
    if (endptr == str || *endptr != '\0' || val <= 0) {
        return FAILURE;
    }
    *value = (int)val;
    return SUCCESS;
}

// Validates the cache duration as a non-negative integer
int validate_non_negative_integer(const char *str, int *value) {
    char *endptr = NULL;
    long int val = strtol(str, &endptr, 10);
    if (endptr == str || (*endptr != '\0' && *endptr != '+') || val < 0) {
        return FAILURE;
    }
    *value = (int)val;
    return SUCCESS;
}

// Validates URL using libcurl
int is_valid_url(const char *url) {
    CURL *curl_handle;
    curl_global_init(CURL_GLOBAL_ALL);
    curl_handle = curl_easy_init();
    if(curl_handle) {
        curl_easy_setopt(curl_handle, CURLOPT_URL, url);
        CURLcode res = curl_easy_perform(curl_handle);
        curl_easy_cleanup(curl_handle);
        return (res == CURLE_OK);
    }
    return FAILURE;
}

// Function to resolve environment variables
char* resolve_env_var(const char *key) {
    if (!key) return NULL;
    const char *value = getenv(key);
    if (!value) return NULL;
    size_t len = strlen(value) + 1;
    char *resolved_value = (char *)malloc(len);
    if (!resolved_value) return NULL;
    strcpy(resolved_value, value);
    return resolved_value;
}

// Main function to process the JSON configuration
int process_json_config(const char *file_path, Dependencies dependencies) {
    json_error_t error;
    json_t *root = json_load_file(file_path, 0, &error);

    if (!root) {
        dependencies.log("Failed to load JSON config.");
        return FAILURE;
    }

    const char *app_name = json_string_value(json_object_get(root, "app_name"));
    if (!is_non_empty_string(app_name)) {
        dependencies.log("Invalid or missing app_name.");
        goto cleanup;
    }

    int port;
    if (json_is_number(json_object_get(root, "port"))) {
        const char *port_str = json_string_value(json_object_get(root, "port"));
        if (validate_positive_integer(port_str, &port) != SUCCESS) {
            dependencies.log("Invalid or missing port.");
            goto cleanup;
        }
    } else {
        dependencies.log("Port is not a number.");
        goto cleanup;
    }

    const char *database_url = json_string_value(json_object_get(root, "database_url"));
    if (!is_valid_url(database_url)) {
        dependencies.log("Invalid database URL.");
        goto cleanup;
    }
    dependencies.setup_database_connection(database_url);

    int cache_duration;
    const char *cache_str = json_string_value(json_object_get(root, "cache_duration"));
    if (validate_non_negative_integer(cache_str, &cache_duration) != SUCCESS) {
        dependencies.log("Invalid or missing cache_duration.");
        goto cleanup;
    }

    // Optional fields
    if (json_is_string(json_object_get(root, "logging_level"))) {
        const char *log_level = json_string_value(json_object_get(root, "logging_level"));
        // Handle logging level if needed.
    }

    json_t *api_keys = json_object_get(root, "api_keys");
    if (json_is_array(api_keys)) {
        size_t index;
        json_t *value;
        json_array_foreach(api_keys, index, value) {
            if (!json_is_string(value)) {
                dependencies.log("API keys array contains non-string values.");
                goto cleanup;
            }
        }
    }

    // Resolve environment variables in app_name, database_url
    char *resolved_app_name = resolve_env_var(app_name);
    char *resolved_database_url = resolve_env_var(database_url);

    if (resolved_app_name) {
        free(resolved_app_name);  // Free memory after use.
    }
    if (resolved_database_url) {
        free(resolved_database_url);  // Free memory after use.
    }

cleanup:
    json_decref(root);
    return SUCCESS;
}
```

### Notes:
- The function `process_json_config` loads a JSON file and validates its fields as specified. It also resolves environment variables dynamically.
