        return;
    }

    int newLength = strlen(input) + 2; // Original length + '/' + '\0'
    char* modifiedString = (char*)malloc(newLength);

    if (!modifiedString) {
        return;
    }

    strcpy(modifiedString, input);
    strcat(modifiedString, "/");

    callback(modifiedString);

    free(modifiedString);
}
