function traverseDOM(node, filterFunc, config = {}) {
    const { depthLimit = Infinity, includeTextNodes = false, ignoreHiddenElements = true } = config;
    let result = [];

    function traverse(currentNode, currentDepth) {
        if (currentDepth > depthLimit || (!includeTextNodes && currentNode.nodeType === Node.TEXT_NODE)) {
            return;
        }

        // Check for visibility if required
        const isVisible = !ignoreHiddenElements || (ignoreHiddenElements && getComputedStyle(currentNode).display !== 'none');

        if ((currentNode.nodeType === Node.ELEMENT_NODE && filterFunc(currentNode)) || 
            (includeTextNodes && currentNode.nodeType === Node.TEXT_NODE && filterFunc(currentNode))) {
            result.push(currentNode);
        }

        if (isVisible) {
            for (let child of currentNode.childNodes) {
                traverse(child, currentDepth + 1);
            }
        }
    }

    traverse(node, 0);

    return result;
}
