using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
import System.Security.Cryptography;
using System.Text;

public class MessageProcessor
{
    private readonly byte[] _tripledesKey;
    private readonly byte[] _tripledesIV;
    private readonly byte[] _hmacSecretKey;
    private const string Delimiter = "###DELIMITER###";

    public MessageProcessor(string tripleDESKey, string tripleDESVI, string hmacSecretKey)
    {
        if (tripleDESKey.Length != 24 || tripleDESVI.Length != 8)
            throw new ArgumentException("Invalid Triple DES Key or IV length.");

        _tripledesKey = Encoding.UTF8.GetBytes(tripleDESKey);
        _tripledesIV = Encoding.UTF8.GetBytes(tripleDESVI);
        _hmacSecretKey = Encoding.UTF8.GetBytes(hmacSecretKey);
    }

    public List<string> ProcessMessages(string input)
    {
        var messages = new List<string>();
        var parts = input.Split(new[] { Delimiter }, StringSplitOptions.RemoveEmptyEntries);

        foreach (var part in parts)
        {
            try
            {
                if (IsValidMessage(part))
                {
                    messages.Add(DecryptMessage(part));
                }
            }
            catch (Exception ex)
            {
                LogError(ex);
            }
        }

        return messages;
    }

    public string EncryptAndSignMessage(string message)
    {
        var encryptedData = EncryptMessage(message);
        var hmacSignature = GenerateHMAC(encryptedData);
        return Convert.ToBase64String(hmacSignature.Concat(encryptedData).ToArray());
    }

    private bool IsValidMessage(string base64EncodedMessageWithHmac)
    {
        var fullBytes = Convert.FromBase64String(base64EncodedMessageWithHmac);

        if (fullBytes.Length < 32) // HMAC-SHA256 length
            return false;

        var hmacProvided = fullBytes.Take(32).ToArray();
        var encryptedData = fullBytes.Skip(32).ToArray();

        using var hmac = new HMACSHA256(_hmacSecretKey);
        var expectedHmac = hmac.ComputeHash(encryptedData);

        return hmacProvided.SequenceEqual(expectedHmac);
    }

    private string DecryptMessage(string base64EncodedMessageWithHmac)
    {
        var fullBytes = Convert.FromBase64String(base64EncodedMessageWithHmac);
        var encryptedData = fullBytes.Skip(32).ToArray();

        using var tripleDes = new TripleDESCryptoServiceProvider
        {
            Key = _tripledesKey,
            IV = _tripledesIV,
            Mode = CipherMode.CBC,
            Padding = PaddingMode.PKCS7
        };

        return Encoding.UTF8.GetString(tripleDes.CreateDecryptor().TransformFinalBlock(encryptedData, 0, encryptedData.Length));
    }

    private byte[] EncryptMessage(string message)
    {
        var messageBytes = Encoding.UTF8.GetBytes(message);

        using var tripleDes = new TripleDESCryptoServiceProvider
        {
            Key = _tripledesKey,
            IV = _tripledesIV,
            Mode = CipherMode.CBC,
            Padding = PaddingMode.PKCS7
        };

        return tripleDes.CreateEncryptor().TransformFinalBlock(messageBytes, 0, messageBytes.Length);
    }

    private byte[] GenerateHMAC(byte[] data)
    {
        using var hmac = new HMACSHA256(_hmacSecretKey);
        return hmac.ComputeHash(data);
    }

    private void LogError(Exception ex)
    {
        // Implement logging logic here
        Console.Error.WriteLine(ex.Message);
    }
}
