using System;
using System.Collections.Concurrent;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Newtonsoft.Json;

public class AesDecryptor
{
    private static readonly HttpClient httpClient = new HttpClient();
    private const int MaxRetries = 3;
    private const string ApiEndpoint = "https://api.example.com/ciphertexts";

    public async Task<ConcurrentBag<byte[]>> DecryptCiphertextsAsync(
        byte[] encryptionKey,
        byte[] iv,
        Func<string, byte[]> fetchCiphertextsFromApi,
        Action<string> log,
        bool debugMode)
    {
        var ciphertextTasks = new ConcurrentBag<Task<CiphertextResult>>();
        var decryptedResults = new ConcurrentBag<byte[]>();

        int attempt = 0;
        while (attempt < MaxRetries)
        {
            try
            {
                string apiResponse = await fetchCiphertextsFromApi(ApiEndpoint);
                var ciphertextData = JsonConvert.DeserializeObject<CiphertextData[]>(apiResponse);

                foreach (var ciphertext in ciphertextData)
                {
                    ciphertextTasks.Add(Task.Run(() => DecryptAndValidateAsync(
                        encryptionKey, iv, ciphertext.Ciphertext, ciphertext.HmacHash,
                        decryptedResults, log, debugMode)));
                }

                await Task.WhenAll(ciphertextTasks);
                break;
            }
            catch (Exception ex) when (ex is HttpRequestException || ex is TimeoutException)
            {
                log($"Attempt {attempt + 1} failed: {ex.Message}");
                attempt++;
                if (attempt >= MaxRetries) throw new Exception("Failed to fetch ciphertexts after multiple attempts.");

                await Task.Delay(2000); // Backoff strategy
            }
        }

        return decryptedResults;
    }

    private async Task<CiphertextResult> DecryptAndValidateAsync(
        byte[] encryptionKey, 
        byte[] iv, 
        byte[] ciphertext, 
        string hmacHash,
        ConcurrentBag<byte[]> results, 
        Action<string> log, 
        bool debugMode)
    {
        var sw = Stopwatch.StartNew();

        try
        {
            using (var aes = Aes.Create())
            {
                aes.Key = encryptionKey;
                aes.IV = iv;
                aes.Mode = CipherMode.CBC;

                ICryptoTransform decryptor = aes.CreateDecryptor(aes.Key, aes.IV);

                using (MemoryStream msDecrypt = new MemoryStream(ciphertext))
                {
                    using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                    {
                        var decryptedData = new byte[ciphertext.Length];
                        int bytesRead = await csDecrypt.ReadAsync(decryptedData, 0, decryptedData.Length);

                        if (!ValidateHmacHash(decryptedData.Take(bytesRead).ToArray(), hmacHash))
                        {
                            throw new Exception("HMAC validation failed.");
                        }

                        results.Add(decryptedData.Take(bytesRead).ToArray());
                    }
                }
            }

            sw.Stop();
            log($"Decryption completed in {sw.ElapsedMilliseconds} ms");
        }
        catch (Exception ex)
        {
            log($"Error decrypting ciphertext: {ex.Message}");
            throw;
        }

        return new CiphertextResult
        {
            Success = true,
            DurationMs = sw.ElapsedMilliseconds
        };
    }

    private bool ValidateHmacHash(byte[] data, string hmacHash)
    {
        using (var hmac = new HMACSHA256())
        {
            var computedHash = Convert.ToBase64String(hmac.ComputeHash(data));
            return hmacHash == computedHash;
        }
    }

    public class CiphertextData
    {
        public byte[] Ciphertext { get; set; }
        public string HmacHash { get; set; }
    }

    public class CiphertextResult
    {
        public bool Success { get; set; }
        public long DurationMs { get; set; }
    }
}

// Usage example:
// var decryptor = new AesDecryptor();
