using System;
using System.Collections.Concurrent;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;
using System.Threading;

// Define a custom data structure that can evolve with schema changes.
[Serializable]
public class CustomDataStructure
{
    public int Id { get; set; }
    public string Name { get; set; }
    // Add additional fields as needed, ensuring backward compatibility.
}

public class DataLoader
{
    private static readonly ReaderWriterLockSlim _lock = new ReaderWriterLockSlim();

    public ConcurrentDictionary<int, CustomDataStructure> LoadAndDeserializeData(string filePath)
    {
        var dataMap = new ConcurrentDictionary<int, CustomDataStructure>();

        try
        {
            _lock.EnterReadLock();
            using (var fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.Read))
            using (var binaryReader = new BinaryReader(fileStream))
            {
                while (fileStream.Position < fileStream.Length)
                {
                    try
                    {
                        if (!IsDataValid(binaryReader))
                            throw new CorruptFileException("Data corruption detected.");

                        var dataObject = DeserializeData<CustomDataStructure>(binaryReader);
                        if (dataMap.ContainsKey(dataObject.Id))
                        {
                            // Handle potential duplicate keys or update logic as needed.
                            continue;
                        }

                        dataMap.TryAdd(dataObject.Id, dataObject);
                    }
                    catch (EndOfStreamException)
                    {
                        break; // Exit loop on unexpected EOF due to corruption or incomplete data.
                    }
                }
            }
        }
        catch (IOException ex)
        {
            Console.WriteLine($"IO Exception: {ex.Message}");
        }
        finally
        {
            _lock.ExitReadLock();
        }

        return dataMap;
    }

    private bool IsDataValid(BinaryReader binaryReader)
    {
        // Implement validation logic based on expected structure and size.
        const int expectedSize = sizeof(int) + 100; // Example: ID and fixed-size name buffer.

        if (binaryReader.BaseStream.Position + expectedSize > binaryReader.BaseStream.Length)
            return false;

        return true;
    }

    private T DeserializeData<T>(BinaryReader binaryReader) where T : class
    {
        using (var memoryStream = new MemoryStream())
        {
            var formatter = new BinaryFormatter();

            // Minimize memory footprint by deserializing directly into target structure.
            var tempData = formatter.Deserialize(binaryReader.BaseStream);

            if (tempData is T dataObject)
                return dataObject;

            throw new InvalidCastException("Deserialized data type mismatch.");
        }
    }

    class CorruptFileException : Exception
    {
        public CorruptFileException(string message) : base(message) { }
    }
}
