const ts = require('typescript');
const { exec } = require('child_process');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

// Cache object to store compiled outputs
const compileCache = new Map();

function hashFile(filePath) {
  const fileContent = fs.readFileSync(filePath, 'utf8');
  return crypto.createHash('md5').update(fileContent).digest('hex');
}

async function compileTypeScript(sourceFilePath, targetEnvironment) {
  const sourceHash = hashFile(sourceFilePath);

  // Check cache
  if (compileCache.has(sourceHash)) {
    console.log(`Using cached output for: ${sourceFilePath}`);
    return compileCache.get(sourceHash);
  }

  try {
    const program = ts.createProgram([sourceFilePath], { target: 'ESNext', module: 'CommonJS' });
    let emitResult = program.emit();

    let allDiagnostics = ts.getPreEmitDiagnostics(program).concat(emitResult.diagnostics);

    allDiagnostics.forEach(diagnostic => {
      if (diagnostic.file) {
        const { line, character } = diagnostic.file.getLineAndCharacterOfPosition(diagnostic.start);
        const message = ts.flattenDiagnosticMessageText(diagnostic.messageText, '\n');
        console.error(`${sourceFilePath} (${line + 1},${character + 1}): ${message}`);
      } else {
        console.error(ts.flattenDiagnosticMessageText(diagnostic.messageText, '\n'));
      }
    });

    if (emitResult.emitSkipped) {
      throw new Error('TypeScript compilation failed');
    }

    const jsFilePath = sourceFilePath.replace(/\.ts$/, '.js');
    fs.writeFileSync(jsFilePath, emitResult.outputFiles[0].text);

    // Cache the result
    compileCache.set(sourceHash, jsFilePath);
    return jsFilePath;
  } catch (error) {
    console.error(`Error compiling TypeScript file: ${sourceFilePath}`, error.message);
    throw new Error('TypeScript compilation error');
  }
}

function executeCompiledScript(jsFilePath, targetEnvironment) {
  const cmd = `node -v`; // Example command to check Node.js version compatibility
  exec(cmd, (error, stdout, stderr) => {
    if (error) {
      console.error(`Error executing script: ${jsFilePath}`, error.message);
      return;
    }
    console.log(`Executing compiled JavaScript: ${jsFilePath}`);
    const child = exec(`node ${jsFilePath}`, (err, out, errOut) => {
      if (err || errOut) {
        console.error(`Runtime execution failed for script: ${jsFilePath}`, err ? err.message : errOut);
      } else {
        console.log(out);
      }
    });
  });
}

async function runTypeScriptPipeline(sourceFilePaths, targetEnvironment) {
  const compilePromises = sourceFilePaths.map(filePath => 
    compileTypeScript(filePath, targetEnvironment)
  );

  try {
    const compiledScripts = await Promise.all(compilePromises);

    compiledScripts.forEach(jsFilePath => executeCompiledScript(jsFilePath, targetEnvironment));
  } catch (error) {
    console.error('Failed to run TypeScript pipeline:', error.message);
  }
}

// Example usage
const sourceFiles = ['./example1.ts', './example2.ts'];
runTypeScriptPipeline(sourceFiles, 'node12'); // Specify target environment if needed

module.exports = { runTypeScriptPipeline };
```

