from threading import Lock
from collections import defaultdict

class JSONFramework:
    _registry = {}
    _lock = Lock()

    @classmethod
    def register_factory(cls, type_id, factory_func):
        with cls._lock:
            if type_id in cls._registry:
                raise ValueError(f"Factory for type ID '{type_id}' is already registered.")
            cls._registry[type_id] = factory_func

    @classmethod
    def get_factory(cls, type_id):
        with cls._lock:
            return cls._registry.get(type_id)

    @staticmethod
    def parse_json(json_data):
        try:
            data_dict = json.loads(json_data)
            return JSONFramework._parse_nested(data_dict)
        except (json.JSONDecodeError, TypeError) as e:
            raise ValueError(f"Invalid JSON input: {e}")

    @staticmethod
    def _parse_nested(data):
        if isinstance(data, dict):
            type_id = data.get('type')
            factory_func = JSONFramework.get_factory(type_id)
            if factory_func:
                return factory_func(**data)
            else:
                return {k: JSONFramework._parse_nested(v) for k, v in data.items()}
        elif isinstance(data, list):
            return [JSONFramework._parse_nested(item) for item in data]
        else:
            return data

    @staticmethod
    def create_json(obj):
        if isinstance(obj, dict):
            type_id = obj.get('type')
            if type_id is None and isinstance(next(iter(obj.values())), (dict, list)):
                # Nested dictionary without a direct type ID
                return {k: JSONFramework.create_json(v) for k, v in obj.items()}
            elif type_id:
                factory_func = JSONFramework.get_factory(type_id)
                if factory_func:
                    return json.loads(json.dumps({**obj, **factory_func.to_dict()}))
            else:
                raise ValueError("Missing 'type' key for serialization")
        elif isinstance(obj, list):
            return [JSONFramework.create_json(item) for item in obj]
        else:
            return obj

    @staticmethod
    def versioned_serialize(obj, version="1.0"):
        data = JSONFramework.create_json(obj)
        data['version'] = version
        return json.dumps(data)

    @staticmethod
    def versioned_deserialize(json_data):
        try:
            data_dict = json.loads(json_data)
            version = data_dict.pop('version', "1.0")
            if version != "1.0":
                raise NotImplementedError(f"Version {version} is not supported.")
            return JSONFramework.parse_json(json.dumps(data_dict))
        except (json.JSONDecodeError, TypeError) as e:
            raise ValueError(f"Invalid JSON input: {e}")

class CustomTypeBase:
