    pthread_mutex_t lock;
} IntegerList;

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

IntegerList* initialize_integer_list(size_t max_length) {
    IntegerList *list = (IntegerList*)malloc(sizeof(IntegerList));
    if (!list) {
        log_error("Failed to allocate memory for IntegerList");
        return NULL;
    }

    list->data = (int*)calloc(max_length, sizeof(int));
    if (!list->data) {
        free(list);
        log_error("Failed to allocate memory for integer data");
        return NULL;
    }

    list->length = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void cleanup_integer_list(IntegerList *list) {
    if (list) {
        if (list->data) free(list->data);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

void add_to_list(IntegerList *list, int value) {
    if (!list || list->length >= MAX_INTEGER_COUNT)
        return;

    pthread_mutex_lock(&list->lock);

    if (list->length < MAX_INTEGER_COUNT) {
        list->data[list->length++] = value;
    }

    pthread_mutex_unlock(&list->lock);
}

int find_largest_integer(const IntegerList *list) {
    if (!list || list->length == 0)
        return INT_MIN;

    int max_value = INT_MIN;
    for (size_t i = 0; i < list->length; ++i) {
        if (list->data[i] > max_value) {
            max_value = list->data[i];
        }
    }

    printf("Largest integer: %d\n", max_value);
    return max_value;
}

