        int value = rand() % 100000; // Example integer generation, replace with actual network data

        add_to_list(list, value);
    }
}

void initialize_structures(IntegerList *list, NFAPI_CRC_INDICATION_PDU_T structures[], size_t count) {
    if (!structures || !list)
        return;

    for (size_t i = 0; i < count && i < list->length; ++i) {
        pthread_mutex_lock(&list->lock);

        structures[i].rx_ue_information_tag = rand() % UINT32_MAX;
        structures[i].rnti = rand() % UINT16_MAX;
        structures[i].crc_indication_rel8_tag = rand() % 256;
        structures[i].crcflag = rand() % 2;

        pthread_mutex_unlock(&list->lock);
    }
}

void network_interface_handler() {
    IntegerList *list = initialize_integer_list(MAX_INTEGER_COUNT);
    if (!list) return;

    process_network_data(list);

    NFAPI_CRC_INDICATION_PDU_T structures[MAX_INTEGER_COUNT];
    size_t count = list->length < MAX_INTEGER_COUNT ? list->length : MAX_INTEGER_COUNT;

    initialize_structures(list, structures, count);
    find_largest_integer(list);

    cleanup_integer_list(list);
}

int main() {
