```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_SIZE 16

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI; // Assuming RNTI is an unsigned long type
    int CRC_INDICATION_REL8_TAG;
    char CRCFLAG;       // Randomly set CRC flag
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct HashNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct HashNode* next;
} HashNode;

typedef struct {
    HashNode** buckets;
    size_t size;
    pthread_mutex_t lock;
} CRCIndicationHashTable;

unsigned long hash_function(unsigned long rnti, size_t table_size) {
    return rnti % table_size;
}

CRCIndicationHashTable* create_table(size_t initial_size) {
    CRCIndicationHashTable* table = (CRCIndicationHashTable*)malloc(sizeof(CRCIndicationHashTable));
    if (!table) return NULL;

    table->buckets = (HashNode**)calloc(initial_size, sizeof(HashNode*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    table->size = initial_size;
    pthread_mutex_init(&table->lock, NULL);

    return table;
}

void free_table(CRCIndicationHashTable* table) {
    for (size_t i = 0; i < table->size; ++i) {
        HashNode* current = table->buckets[i];
        while (current) {
            HashNode* to_free = current;
            current = current->next;
            free(to_free);
        }
    }

    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

int insert_entry(CRCIndicationHashTable* table, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&table->lock);

    unsigned long index = hash_function(entry.RNTI, table->size);
    HashNode* current = table->buckets[index];

    while (current) {
        if (current->data.RNTI == entry.RNTI) {
            pthread_mutex_unlock(&table->lock);
            return 0; // Duplicate RNTI
        }
        current = current->next;
    }

    HashNode* new_node = (HashNode*)malloc(sizeof(HashNode));
    if (!new_node) {
        pthread_mutex_unlock(&table->lock);
        return -1; // Memory allocation failure
    }

    new_node->data = entry;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;

    pthread_mutex_unlock(&table->lock);
    return 1; // Success
}

int find_entry(CRCIndicationHashTable* table, unsigned long rnti, NFAPI_CRC_INDICATION_PDU_T* result) {
    pthread_mutex_lock(&table->lock);

    unsigned long index = hash_function(rnti, table->size);
    HashNode* current = table->buckets[index];

    while (current) {
        if (current->data.RNTI == rnti) {
            *result = current->data;
            pthread_mutex_unlock(&table->lock);
            return 1; // Found
        }
        current = current->next;
    }

    pthread_mutex_unlock(&table->lock);
    return 0; // Not found
}

void remove_entry(CRCIndicationHashTable* table, unsigned long rnti) {
    pthread_mutex_lock(&table->lock);

    unsigned long index = hash_function(rnti, table->size);
    HashNode* current = table->buckets[index];
    HashNode* prev = NULL;

    while (current) {
        if (current->data.RNTI == rnti) {
            if (prev) {
                prev->next = current->next;
            } else {
                table->buckets[index] = current->next;
            }
            free(current);
            pthread_mutex_unlock(&table->lock);
            return; // Removed
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&table->lock);
}

// Example usage of the functions
int main() {
    CRCIndicationHashTable* table = create_table(INITIAL_SIZE);

    if (!table) {
        fprintf(stderr, "Failed to create hash table\n");
        return 1;
    }

    // Create and insert a new entry with random CRCFLAG
    NFAPI_CRC_INDICATION_PDU_T entry = { .RX_UE_INFORMATION_TAG = 123, 
                                         .RNTI = 456789, 
                                         .CRC_INDICATION_REL8_TAG = 7,
                                         .CRCFLAG = (rand() % 2) ? 'Y' : 'N'};
    if (!insert_entry(table, entry)) {
        fprintf(stderr, "Failed to insert entry or duplicate RNTI\n");
    }

    // Find the entry
    NFAPI_CRC_INDICATION_PDU_T found;
    if (find_entry(table, entry.RNTI, &found)) {
        printf("Entry found: RX_UE_INFORMATION_TAG=%d, RNTI=%lu, CRC_INDICATION_REL8_TAG=%d, CRCFLAG=%c\n",
               found.RX_UE_INFORMATION_TAG, found.RNTI, found.CRC_INDICATION_REL8_TAG, found.CRCFLAG);
    } else {
        printf("Entry not found\n");
    }

    // Remove the entry
    remove_entry(table, entry.RNTI);

    free_table(table);
    return 0;
}
```

This code uses a hash table with chaining for efficient insertion and lookup operations. It ensures thread safety using mutex locks to prevent concurrent access issues. The function handles memory allocation and deallocation carefully to avoid leaks.']

