['```cpp
#include <iostream>
#include <random>
#include <mutex>
#include <string>
#include <openssl/evp.h>

namespace CryptLib {

class CryptoManager {
private:
    static std::mt19937 rng;
    static std::once_flag seedInitFlag;

    // Ensure the random generator is initialized once
    void initializeRNG() {
        std::call_once(seedInitFlag, []() {
            auto seed = std::random_device{}();
            CryptLib::CryptoManager::rng.seed(seed);
        });
    }

public:
    CryptoManager() {
        initializeRNG();
    }

    EVP_CIPHER* getEncryptionCipher(const std::string& mode, const std::string& key) {
        if (mode == "ECB") return setupECB(key);
        else if (mode == "EDE" || mode == "EDE3") return setupEDE(mode, key);
        else if (mode == "CFB") return setupCFB(key);
        else if (mode == "NULL") return setupNull();
        throw std::runtime_error("Unsupported cipher mode");
    }

private:
    EVP_CIPHER* setupECB(const std::string& key) {
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(ctx, EVP_des_ecb(), nullptr, reinterpret_cast<const unsigned char*>(key.data()), nullptr);
        return ctx;
    }

    EVP_CIPHER* setupEDE(const std::string& mode, const std::string& key) {
        size_t nkeys = (mode == "EDE") ? 2 : 3;
        if (key.size() < nkeys * 8) throw std::invalid_argument("Key length too short for EDE/EDE3");

        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        unsigned char* keys[nkeys];
        for (size_t i = 0; i < nkeys; ++i)
            keys[i] = reinterpret_cast<unsigned char*>(key.data() + i * 8);

        EVP_EncryptInit_ex(ctx, EVP_des_ede3(), nullptr, keys[0], nullptr);
        return ctx;
    }

    EVP_CIPHER* setupCFB(const std::string& key) {
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        unsigned char iv[EVP_MAX_IV_LENGTH];
        rng().get(iv, sizeof(iv)); // Random IV generation
        EVP_EncryptInit_ex(ctx, EVP_des_cfb64(), nullptr, reinterpret_cast<const unsigned char*>(key.data()), iv);
        return ctx;
    }

    EVP_CIPHER* setupNull() {
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(ctx, EVP_null_aes_128_ecb(), nullptr, nullptr, nullptr);
        return ctx;
    }
};

std::mt19937 CryptLib::CryptoManager::rng(std::random_device{}());
std::once_flag CryptLib::CryptoManager::seedInitFlag;

} // namespace CryptLib

int main() {
    try {
        CryptLib::CryptoManager cryptoManager;
        EVP_CIPHER* cipher = cryptoManager.getEncryptionCipher("ECB", "01234567");

        // Use the cipher here...

        EVP_CIPHER_CTX_free(reinterpret_cast<EVP_CIPHER_CTX*>(cipher));
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << '\n';
    }

    return 0;
}
