    assert(process_strings(test_input, '|', MODE_ENCRYPT, NULL) == 0);
    assert(process_strings(test_input, '|', MODE_DECRYPT, NULL) == 0);

    const char *long_input = str_repeat("a", TOTAL_BUFFER_SIZE);
    assert(process_strings(long_input, ',', MODE_ENCRYPT, NULL) != 0);

    printf("All tests passed.\n");
}

char* str_repeat(char c, size_t n) {
    char *result = malloc(n + 1);
    if (result) {
        memset(result, c, n);
        result[n] = '\0';
    }
    return result;
}

int main() {
    test_process_strings();
    return 0;
}
