import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Arrays;

public class DistributedSystemProcessor {

    public static String[] processArrayAndString(int[] array, String input) {
        long startTime = System.currentTimeMillis();

        // Compute MD5 hash of the string parameter
        String md5Hash = null;
        try {
            MessageDigest digest = MessageDigest.getInstance("MD5");
            byte[] hashBytes = digest.digest(input.getBytes());
            StringBuilder hexString = new StringBuilder();
            for (byte b : hashBytes) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            md5Hash = hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            System.err.println("Error computing MD5: " + e.getMessage());
        }

        long endTime = System.currentTimeMillis();
        System.out.println("MD5 hash computation time: " + (endTime - startTime) + " ms");

        // Determine the number of disjoint pairs using Union-Find
        startTime = System.currentTimeMillis();

        int n = array.length;
        UnionFind unionFind = new UnionFind(n);

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (shouldUnion(array[i], array[j])) { // Fetch configuration from external source
                    unionFind.union(i, j);
                }
            }
        }

        int disjointPairCount = countDisjointPairs(unionFind);

        endTime = System.currentTimeMillis();
        System.out.println("Disjoint pairs computation time: " + (endTime - startTime) + " ms");

        return new String[]{md5Hash, Integer.toString(disjointPairCount)};
    }

    private static boolean shouldUnion(int a, int b) {
        // Placeholder for fetching configuration from external source
        return (a % 2 == 0 && b % 2 != 0) || (a % 2 != 0 && b % 2 == 0);
    }

    private static int countDisjointPairs(UnionFind uf) {
        int[] rootCounts = new int[uf.size];
        for (int i = 0; i < uf.size; i++) {
            rootCounts[uf.find(i)]++;
        }
        int disjointPairCount = 0;
        for (int count : rootCounts) {
            if (count > 1) {
                disjointPairCount += count * (count - 1) / 2;
            }
        }
        return disjointPairCount;
    }

    static class UnionFind {
        private final int[] parent;
        private final int[] rank;

        public UnionFind(int size) {
            parent = new int[size];
            rank = new int[size];
            for (int i = 0; i < size; i++) {
                parent[i] = i;
            }
        }

        public int find(int p) {
            if (parent[p] != p) {
                parent[p] = find(parent[p]);
            }
            return parent[p];
        }

        public void union(int p, int q) {
            int rootP = find(p);
            int rootQ = find(q);

            if (rootP != rootQ) {
                if (rank[rootP] > rank[rootQ]) {
                    parent[rootQ] = rootP;
                } else if (rank[rootP] < rank[rootQ]) {
                    parent[rootP] = rootQ;
                } else {
                    parent[rootQ] = rootP;
                    rank[rootP]++;
                }
            }
        }

        public int size() {
            return parent.length;
        }
    }
}
