using System;
using System.Threading.Tasks;
using UnityEngine;

public class RandomValueGenerator
{
    private float _minFloat;
    private float _maxFloat;
    private int _minInt;
    private int _maxInt;
    private int _floatCount = 0;
    private int _intCount = 0;

    public RandomValueGenerator(float min, float max)
    {
        _minFloat = min;
        _maxFloat = max;
    }

    public RandomValueGenerator(int min, int max)
    {
        _minInt = min;
        _maxInt = max;
    }

    public float GetRandomFloat(bool inclusiveMin = true, bool inclusiveMax = false)
    {
        float range = inclusiveMax ? _maxFloat - (_minFloat - (inclusiveMin ? 0.0001f : 0)) 
                                   : _maxFloat - _minFloat;
        _floatCount++;
        return UnityEngine.Random.Range(_minFloat + (inclusiveMin ? 0 : 0.0001f), range);
    }

    public int GetRandomInt(bool inclusiveMin = true, bool inclusiveMax = false)
    {
        int max = inclusiveMax ? _maxInt + 1 : _maxInt;
        _intCount++;
        return UnityEngine.Random.Range(_minInt, max);
    }

    public override string ToString()
    {
        return $"Float Range: [{_minFloat}, {_maxFloat}], Integer Range: [{_minInt}, {_maxInt}]";
    }

    public TaskCompletionSource<int> ExecuteBackgroundTask(Func<int> taskFunc)
    {
        var tcs = new TaskCompletionSource<int>();

        try
        {
            Task.Run(() =>
            {
                try
                {
                    int result = taskFunc();
                    tcs.SetResult(result);
                }
                catch (Exception ex)
                {
                    tcs.SetException(ex);
                }
            });
        }
        catch (Exception ex)
        {
            tcs.TrySetException(ex);
        }

        return tcs;
    }

    public void LogRandomValueUsage()
    {
        Debug.Log($"Float values generated: {_floatCount}");
        Debug.Log($"Integer values generated: {_intCount}");
    }
}
