typedef struct {
    int RNTI;
    // other fields...
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    int RNTI;
    struct Node* next;
} HashNode;

typedef struct {
    pthread_mutex_t lock;
    size_t current_size;
    size_t max_capacity;
    size_t reallocations;
    NFAPI_CRC_INDICATION_PDU_T** data_array;
