    HashNode* head = table[index];

    // Check for existing RNTI
    while (head != NULL) {
        if (head->RNTI == RNTI) return false;
        head = head->next;
    }

    // Insert new node
    HashNode* newNode = malloc(sizeof(HashNode));
    if (!newNode) return false;

    newNode->RNTI = RNTI;
    newNode->next = table[index];
    table[index] = newNode;
    return true;
}

void remove_hash(HashNode** table, int RNTI) {
    unsigned int index = hash(RNTI);
    HashNode* head = table[index];
    HashNode* prev = NULL;

    while (head != NULL) {
        if (head->RNTI == RNTI) {
            if (prev) {
                prev->next = head->next;
            } else {
                table[index] = head->next;
            }
            free(head);
            return;
        }
        prev = head;
        head = head->next;
    }
}

void log_statistics(DynamicList* list, size_t allocated_structures, size_t max_capacity) {
    time_t current_time = time(NULL);
    int index = list->log_index % MAX_LOG_ENTRIES;

    list->log_buffer[index][0] = (int)current_time;
    list->log_buffer[index][1] = allocated_structures;
    list->log_buffer[index][2] = max_capacity;

    list->log_index++;
}

void initialize_list(DynamicList* list, size_t initial_size, size_t max_capacity) {
    pthread_mutex_init(&list->lock, NULL);
    list->current_size = 0;
    list->max_capacity = max_capacity;
    list->reallocations = 0;
    list->data_array = malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    memset(list->hash_table, 0, sizeof(HashNode*) * HASH_TABLE_SIZE);
    list->log_index = 0;

    for (int i = 0; i < initial_size; ++i) {
        list->data_array[i] = NULL;
    }
}

void cleanup_list(DynamicList* list) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->current_size; ++i) {
        free(list->data_array[i]);
        remove_hash(list->hash_table, list->data_array[i]->RNTI);
    }

    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        HashNode* head = list->hash_table[i];
        while (head != NULL) {
            HashNode* temp = head;
            head = head->next;
            free(temp);
        }
    }

    free(list->data_array);

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

bool add_pdu(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&list->lock);

    if (list->current_size >= list->max_capacity) {
        size_t new_capacity = list->max_capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T** new_data_array = realloc(list->data_array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (!new_data_array) {
            pthread_mutex_unlock(&list->lock);
            return false;
        }
        list->data_array = new_data_array;
        memset(list->data_array + list->current_size, 0, (new_capacity - list->current_size) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        list->max_capacity = new_capacity;
        list->reallocations++;
    }

    if (!insert_hash(list->hash_table, pdu->RNTI)) {
        pthread_mutex_unlock(&list->lock);
        return false; // RNTI already exists
    }

    list->data_array[list->current_size] = pdu;
    log_statistics(list, list->current_size + 1, list->max_capacity);

    pthread_mutex_unlock(&list->lock);
    return true;
}

bool remove_pdu(DynamicList* list, int RNTI) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->current_size; ++i) {
        if (list->data_array[i] && list->data_array[i]->RNTI == RNTI) {
            remove_hash(list->hash_table, RNTI);
            free(list->data_array[i]);
            for (size_t j = i; j < list->current_size - 1; ++j) {
                list->data_array[j] = list->data_array[j + 1];
            }
            list->data_array[list->current_size - 1] = NULL;
            log_statistics(list, list->current_size - 1, list->max_capacity);
            pthread_mutex_unlock(&list->lock);
            return true;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return false; // RNTI not found
}

void export_list(DynamicList* list, const char* file_path, const char* format) {
    FILE* file = fopen(file_path, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    pthread_mutex_lock(&list->lock);
    if (strcmp(format, "json") == 0) {
        fprintf(file, "[\n");
        for (size_t i = 0; i < list->current_size; ++i) {
            // Serialize JSON format
            fprintf(file, "{ \"RNTI\": %d /* other fields */ }", list->data_array[i]->RNTI);
            if (i < list->current_size - 1) {
                fprintf(file, ",\n");
            }
        }
        fprintf(file, "\n]");
    } else if (strcmp(format, "binary") == 0) {
        for (size_t i = 0; i < list->current_size; ++i) {
            // Serialize binary format
            fwrite(&list->data_array[i]->RNTI, sizeof(int), 1, file);
            // write other fields...
        }
    }

    fclose(file);

    pthread_mutex_unlock(&list->lock);
}

int main() {
    DynamicList list;
    initialize_list(&list, 10, 100); // Initial and max capacity

    NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pdu->RNTI = rand(); // Random RNTI for demonstration
    add_pdu(&list, pdu);

    export_list(&list, "output.json", "json");

    cleanup_list(&list);
    return 0;
}
