import sys/socket
import select
import errno

#define VALID_MIN 0
#define VALID_MAX 1000

void process_stream(int sock_fd) {
    int running_max = -1;
    size_t buffer_size = 1024; // Initial buffer size
    int *buffer = malloc(buffer_size * sizeof(int));
    if (!buffer) {
        perror("Failed to allocate memory for buffer");
        close(sock_fd);
        return;
    }

    while (1) {
        fd_set read_fds;
        FD_ZERO(&read_fds);
        FD_SET(sock_fd, &read_fds);

        struct timeval timeout = {0, 500000}; // 0.5 seconds
        int select_result = select(sock_fd + 1, &read_fds, NULL, NULL, &timeout);

        if (select_result < 0) {
            perror("Select error");
            break;
        } else if (select_result == 0) {
            printf("Timeout waiting for data\n");
            continue;
        }

        char recv_buffer[1024];
        ssize_t bytes_received = recv(sock_fd, recv_buffer, sizeof(recv_buffer), 0);
        if (bytes_received < 0) {
            perror("Receive error");
            break;
        } else if (bytes_received == 0) {
            printf("Connection closed by peer\n");
            break;
        }

        char *data_ptr = recv_buffer;
        size_t current_size = buffer_size;

        while ((data_ptr - recv_buffer) < bytes_received) {
            int num;
            int chars_read = sscanf(data_ptr, "%d%n", &num, &chars_read);
            data_ptr += chars_read;

            if (chars_read == 0 || chars_read == EOF) {
                break; // No more integers
            }

            if (num >= VALID_MIN && num <= VALID_MAX) {
                if (current_size * sizeof(int) == buffer_size * sizeof(int)) {
                    buffer_size *= 2;
                    int *new_buffer = realloc(buffer, buffer_size * sizeof(int));
                    if (!new_buffer) {
                        perror("Failed to reallocate memory for buffer");
                        free(buffer);
                        close(sock_fd);
                        return;
                    }
                    buffer = new_buffer;
                }

                *(buffer + (current_size++ / sizeof(int))) = num;

                if (num > running_max) {
                    running_max = num;
                }
            }
        }
    }

    printf("Running maximum value: %d\n", running_max);
    free(buffer);
    close(sock_fd);
}

int main() {
    int sock_fd; // Assume sock_fd is initialized and connected elsewhere
    process_stream(sock_fd);
    return 0;
}
