['Here's a C implementation for managing a dynamic list of `NFAPI_CRC_INDICATION_PDU_T` structures with thread-safe operations and efficient memory management:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    unsigned int size;
} CRCList;

CRCList* create_crc_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->size = 0;
    return list;
}

int is_rnti_present(CRCList* list, unsigned int rnti) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) return 1;
        current = current->next;
    }
    return 0;
}

int add_crc_pdu(CRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    if (is_rnti_present(list, pdu.RNTI)) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Duplicate RNTI
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failure
    }

    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_crc_pdu(CRCList* list, unsigned int rnti) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current != NULL && current->data.RNTI != rnti) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return -1; // RNTI not found
    }

    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    list->size--;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int batch_process_crc(CRCList* list, unsigned int start_rnti, unsigned int end_rnti) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI >= start_rnti && current->data.RNTI <= end_rnti) {
            // Process CRC indication
            printf("Processing RNTI: %u\n", current->data.RNTI);
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void free_crc_list(CRCList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    CRCList* crc_list = create_crc_list();

    NFAPI_CRC_INDICATION_PDU_T pdu1 = {1, 1001, 0, rand() % 2};
    add_crc_pdu(crc_list, pdu1);

    NFAPI_CRC_INDICATION_PDU_T pdu2 = {2, 1002, 0, rand() % 2};
    add_crc_pdu(crc_list, pdu2);

    batch_process_crc(crc_list, 1000, 1010);

    free_crc_list(crc_list);
    return 0;
}
```

### Key Features:
- **Thread Safety**: Uses `pthread_mutex_t` for thread-safe operations.
- **Memory Management**: Ensures no memory leaks by freeing allocated nodes.
- **Duplicate RNTI Check**: Validates to avoid duplicate entries.
- **Batch Processing**: Supports batch processing of CRC indications within a specified RNTI range.

This implementation uses a linked list with mutex locks for simplicity and flexibility, which is suitable for dynamic datasets in high-performance environments. Adjustments can be made for different data structures or synchronization mechanisms as needed.']

