#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

// Define TIFF-related constants and structures
#define TIFF_BYTE_ORDER_MOTOROLA 0x4D4D
#define TIFF_BYTE_ORDER_INTEL    0x4949

typedef struct {
    uint16_t bits_per_sample;
    uint16_t samples_per_pixel;
    uint16_t compression;
    int extra_samples_count;
    char **extra_samples_info; // Dynamic array of strings for each extra sample info
} TiffMetadata;

// Define TIFF field tags
#define TAG_BITS_PER_SAMPLE 0x010E
#define TAG_SAMPLES_PER_PIXEL 0x0111
#define TAG_COMPRESSION 0x0103
#define TAG_EXTRASAMPLES 0x8769

// Compression type definitions
enum {
    COMPRESSION_NONE = 1,
    COMPRESSION_CCITTFAX3, // CCITT Group 3
    COMPRESSION_CCITTFAX4, // CCITT Group 4
    COMPRESSION_LZW = 5,
    COMPRESSION_PACKBITS = 32773
};

// Function prototypes
int parseTiff(const char *filePath, TiffMetadata *metadata);
void freeExtraSamples(char **extra_samples_info, int count);

int parseTiff(const char *filePath, TiffMetadata *metadata) {
    FILE *file = fopen(filePath, "rb");
    if (!file) return -1;

    uint16_t byteOrder;
    if (fread(&byteOrder, sizeof(uint16_t), 1, file) != 1) {
        fclose(file);
        return -2;
    }

    uint32_t magicNumber;
    if (byteOrder == TIFF_BYTE_ORDER_MOTOROLA) {
        // Motorola (big-endian)
        fpos_t pos = ftell(file);
        if (fseek(file, -2, SEEK_CUR)) goto error;
        fread(&magicNumber, sizeof(uint16_t), 1, file);
    } else if (byteOrder == TIFF_BYTE_ORDER_INTEL) {
        // Intel (little-endian)
        fread(&magicNumber, sizeof(uint32_t), 1, file);
    } else {
        fclose(file);
        return -3;
    }

    if (magicNumber != 0x002A && magicNumber != 42) goto error;

    metadata->bits_per_sample = 8; // Default value
    metadata->samples_per_pixel = 1; // Default value
    metadata->compression = COMPRESSION_NONE; // Default value
    metadata->extra_samples_count = 0;
    metadata->extra_samples_info = NULL;

    uint32_t numDirectories, directoryOffset;
    if (byteOrder == TIFF_BYTE_ORDER_MOTOROLA) {
        fpos_t pos = ftell(file);
        fseek(file, -4, SEEK_CUR); // Go back to read directory offset
        fread(&directoryOffset, sizeof(uint32_t), 1, file);
        fseek(file, pos, SEEK_SET);
    } else {
        fread(&numDirectories, sizeof(uint32_t), 1, file);
        fread(&directoryOffset, sizeof(uint32_t), 1, file);
    }

    for (uint16_t i = 0; i < numDirectories; ++i) {
        uint32_t tag, type, count;
        int64_t value;

        if (byteOrder == TIFF_BYTE_ORDER_MOTOROLA) {
            fpos_t pos = ftell(file);
            fseek(file, -4 * 3 + directoryOffset, SEEK_CUR); // Go back to read the tag
            fread(&tag, sizeof(uint16_t), 1, file);
            fread(&type, sizeof(uint16_t), 1, file);
            fread(&count, sizeof(uint32_t), 1, file);
            fseek(file, pos + directoryOffset - (4 * 3), SEEK_SET); // Go back to read value
        } else {
            fpos_t pos = ftell(file);
            fseek(file, -4 * 2 + directoryOffset, SEEK_CUR); // Go back to read the tag
            fread(&tag, sizeof(uint16_t), 1, file);
            fread(&type, sizeof(uint16_t), 1, file);
            fread(&count, sizeof(uint32_t), 1, file);
            fseek(file, pos + directoryOffset - (4 * 2), SEEK_SET); // Go back to read value
        }

        if (tag == TAG_BITS_PER_SAMPLE) {
            metadata->bits_per_sample = count > 0 ? *((uint16_t*)(&value)) : 8;
        } else if (tag == TAG_SAMPLES_PER_PIXEL) {
            metadata->samples_per_pixel = count > 0 ? *((uint16_t*)(&value)) : 1;
        } else if (tag == TAG_COMPRESSION) {
            metadata->compression = count > 0 ? *((uint16_t*)(&value)) : COMPRESSION_NONE;
        } else if (tag == TAG_EXTRASAMPLES && count > 0) {
            uint16_t *extra_samples = (uint16_t*)&value;
            metadata->extra_samples_count = count / sizeof(uint16_t);
            metadata->extra_samples_info = malloc(metadata->extra_samples_count * sizeof(char*));
            for (int j = 0; j < metadata->extra_samples_count; ++j) {
                switch(extra_samples[j]) {
                    case 0: // Undefined
                        metadata->extra_samples_info[j] = "Undefined";
                        break;
                    case 1: // Associated Alpha
                        metadata->extra_samples_info[j] = "Associated Alpha";
                        break;
                    case 2: // Unassociated Alpha
                        metadata->extra_samples_info[j] = "Unassociated Alpha";
                        break;
                    case 3: // Matrix Coefficients
                        metadata->extra_samples_info[j] = "Matrix Coefficients";
                        break;
                    default:
                        metadata->extra_samples_info[j] = "Unknown";
                }
            }
        }

        if (byteOrder == TIFF_BYTE_ORDER_MOTOROLA) {
            fseek(file, 4 * ((type == 3 || type == 9) ? count : 1), SEEK_CUR); // Move to the next tag
        } else {
            fseek(file, 4 * ((type == 3 || type == 9) ? count : 1), SEEK_CUR);
        }
    }

    fclose(file);
    return 0;

error:
    if (file) fclose(file);
    if (metadata->extra_samples_info) freeExtraSamples(metadata->extra_samples_info, metadata->extra_samples_count);
    return -4;
}

void freeExtraSamples(char **extra_samples_info, int count) {
    for (int i = 0; i < count; ++i) {
        free(extra_samples_info[i]);
    }
    free(extra_samples_info);
}

// Example usage
int main() {
    const char *filePath = "example.tiff";
    TiffMetadata metadata;

    if (parseTiff(filePath, &metadata) == 0) {
        printf("Bits per Sample: %d\n", metadata.bits_per_sample);
        printf("Samples per Pixel: %d\n", metadata.samples_per_pixel);
        printf("Compression Type: %d\n", metadata.compression);
        printf("Extra Samples Count: %d\n", metadata.extra_samples_count);

        for (int i = 0; i < metadata.extra_samples_count; ++i) {
            printf("Extra Sample %d: %s\n", i + 1, metadata.extra_samples_info[i]);
        }

        freeExtraSamples(metadata.extra_samples_info, metadata.extra_samples_count);
    } else {
        fprintf(stderr, "Failed to parse TIFF file.\n");
    }

    return 0;
}
