#define MAX_FILENAME_LENGTH 256

// Helper function to find and print the largest integer from a list of IDs.
void print_largest_id(int *ids, size_t count) {
    if (count == 0) return;

    int max_id = ids[0];
    for (size_t i = 1; i < count; ++i) {
        if (ids[i] > max_id) {
            max_id = ids[i];
        }
    }

    printf("Largest ID: %d\n", max_id);
}

// Function to analyze filename and determine new extension and number of digits.
void process_filename(const char *filename, char *new_filename) {
    int digit_count = 0;
    const char *dot_pos = strrchr(filename, '.');

    if (!dot_pos || dot_pos == filename) {
        strcpy(new_filename, "invalid.");
        return;
    }

    // Determine number of digits to append based on content
    for (const char *p = filename; *p && p < dot_pos; ++p) {
        if (isdigit(*p)) digit_count++;
    }

    // Determine new extension based on character analysis
    const char *ext = dot_pos + 1;
    char new_ext[10] = "txt";
    if (isalpha(ext[0])) {
        new_ext[0] = toupper(ext[0]);
        new_ext[1] = '\0';
    } else if (isdigit(ext[0])) {
        sprintf(new_ext, "%d", atoi(ext));
    }

    // Construct the new filename
    snprintf(new_filename, MAX_FILENAME_LENGTH, "%s%d.%s", filename, digit_count, new_ext);
}

// Main function to process filenames and timestamps.
void update_filenames_based_on_timestamp() {
    int *ids = NULL;
    time_t *timestamps = NULL;
    size_t count = 0, capacity = 0;
    char **filenames = NULL;

    // Allocate initial memory
    if (capacity == 0) {
        capacity = 10;
        ids = malloc(capacity * sizeof(int));
        timestamps = malloc(capacity * sizeof(time_t));
        filenames = malloc(capacity * sizeof(char *));

        if (!ids || !timestamps || !filenames) {
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }
    }

    // Read integers and timestamps from standard input
    while (scanf("%d %ld", &ids[count], &timestamps[count]) == 2) {
        char buffer[MAX_FILENAME_LENGTH];
        scanf(" %[^\n]", buffer);

        if (count >= capacity - 1) {
            capacity *= 2;
            ids = realloc(ids, capacity * sizeof(int));
            timestamps = realloc(timestamps, capacity * sizeof(time_t));
            filenames = realloc(filenames, capacity * sizeof(char *));

            if (!ids || !timestamps || !filenames) {
                fprintf(stderr, "Memory reallocation failed\n");
                free(ids);
                free(timestamps);
                free(filenames);
                return;
            }
        }

        // Allocate and store filename
        filenames[count] = malloc(MAX_FILENAME_LENGTH * sizeof(char));
        if (!filenames[count]) {
            fprintf(stderr, "Filename memory allocation failed\n");
            break;
        }
        strncpy(filenames[count], buffer, MAX_FILENAME_LENGTH - 1);

        count++;
    }

    // Find the most recently modified ID
    time_t latest_time = timestamps[0];
    size_t latest_index = 0;
    for (size_t i = 1; i < count; ++i) {
        if (timestamps[i] > latest_time) {
            latest_time = timestamps[i];
            latest_index = i;
        }
    }

    // Process the filename associated with the most recently modified ID
    char new_filename[MAX_FILENAME_LENGTH];
    process_filename(filenames[latest_index], new_filename);

    printf("Updated filename: %s\n", new_filename);

    // Free allocated memory
    for (size_t i = 0; i < count; ++i) {
        free(filenames[i]);
    }
    free(ids);
    free(timestamps);
    free(filenames);
}

int main() {
    update_filenames_based_on_timestamp();
    return 0;
}
