```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/kdf.h>

// Constants
#define SALT_SIZE 16
#define IV_SIZE_256_CBC 16
#define IV_SIZE_128_GCM 12
#define TAG_SIZE_128_GCM 16

typedef enum {
    AES_256_CBC,
    AES_128_GCM
} EncryptionMode;

typedef struct {
    EVP_CIPHER_CTX *ctx;
    int mode;
} CipherContext;

// Error handling function
void handleErrors(void) {
    ERR_print_errors_fp(stderr);
    abort();
}

// Key derivation using PBKDF2 with HMAC-SHA256
int derive_key(const char *passphrase, const unsigned char *salt,
               int iterations, size_t key_len, unsigned char **key) {
    if (PKCS5_PBKDF2_HMAC_SHA1(passphrase, strlen(passphrase),
                               salt, SALT_SIZE, iterations, key_len, *key) == 0) {
        fprintf(stderr, "Error deriving key\n");
        return 0;
    }
    return 1;
}

// Initialize cipher context
CipherContext* initialize_cipher(EncryptionMode mode, const char *passphrase,
                                 unsigned char *salt) {
    CipherContext *cipher_ctx = malloc(sizeof(CipherContext));
    if (!cipher_ctx) handleErrors();

    EVP_CIPHER_CTX_init(cipher_ctx->ctx);
    unsigned char key[EVP_MAX_KEY_LENGTH];
    if (!derive_key(passphrase, salt, 10000, (mode == AES_256_CBC ? 32 : 16), &key)) {
        free(cipher_ctx);
        return NULL;
    }

    cipher_ctx->mode = mode;

    // Initialize encryption
    int iv_len = (mode == AES_256_CBC) ? IV_SIZE_256_CBC : IV_SIZE_128_GCM;
    unsigned char iv[iv_len];
    if (!RAND_bytes(iv, iv_len)) handleErrors();

    if (EVP_EncryptInit_ex(cipher_ctx->ctx, 
                           (mode == AES_256_CBC) ? EVP_aes_256_cbc() : EVP_aes_128_gcm(),
                           NULL, key, iv) != 1) {
        free(cipher_ctx);
        return NULL;
    }

    if (mode == AES_128_GCM) {
        // Set additional authenticated data (AAD) for GCM mode
        const char *aad = "Some AAD";
        EVP_EncryptInit_ex(cipher_ctx->ctx, NULL, NULL, NULL, iv);
        EVP_EncryptUpdate(cipher_ctx->ctx, NULL, NULL, aad, strlen(aad));
    }

    return cipher_ctx;
}

// Encrypt data
int encrypt_data(CipherContext *cipher_ctx, const unsigned char *plaintext,
                 size_t plaintext_len, unsigned char **ciphertext,
                 size_t *ciphertext_len) {
    int len, ciphertext_size = 0;
    *ciphertext_len = plaintext_len + EVP_CIPHER_CTX_block_size(cipher_ctx->ctx);
    *ciphertext = malloc(*ciphertext_len);
    if (!*ciphertext) handleErrors();

    if (EVP_EncryptUpdate(cipher_ctx->ctx, *ciphertext, &len, plaintext, plaintext_len)
        != 1) {
        free(*ciphertext);
        return 0;
    }
    ciphertext_size += len;

    if (EVP_EncryptFinal_ex(cipher_ctx->ctx, *ciphertext + len, &len) != 1) {
        free(*ciphertext);
        return 0;
    }
    ciphertext_size += len;

    *ciphertext_len = ciphertext_size;
    return 1;
}

// Decrypt data
int decrypt_data(CipherContext *cipher_ctx, const unsigned char *ciphertext,
                 size_t ciphertext_len, unsigned char **plaintext,
                 size_t *plaintext_len) {
    int len, plaintext_size = 0;
    *plaintext_len = ciphertext_len;

    *plaintext = malloc(*plaintext_len);
    if (!*plaintext) handleErrors();

    if (EVP_DecryptUpdate(cipher_ctx->ctx, *plaintext, &len, ciphertext, ciphertext_len)
        != 1) {
        free(*plaintext);
        return 0;
    }
    plaintext_size += len;

    if (EVP_DecryptFinal_ex(cipher_ctx->ctx, *plaintext + len, &len) != 1) {
        free(*plaintext);
        return 0;
    }
    plaintext_size += len;

    *plaintext_len = plaintext_size;
    return 1;
}

// Clean up cipher context
void cleanup_cipher(CipherContext *cipher_ctx) {
    if (cipher_ctx) {
        EVP_CIPHER_CTX_free(cipher_ctx->ctx);
        free(cipher_ctx);
    }
}

int main() {
    unsigned char salt[SALT_SIZE];
    if (!RAND_bytes(salt, SALT_SIZE)) handleErrors();

    const char *passphrase = "securepass";
    CipherContext *cipher_ctx = initialize_cipher(AES_256_CBC, passphrase, salt);

    if (!cipher_ctx) {
        fprintf(stderr, "Cipher context initialization failed\n");
        return 1;
    }

    const unsigned char plaintext[] = "Hello, world!";
    size_t ciphertext_len, plaintext_len;

    if (encrypt_data(cipher_ctx, plaintext, sizeof(plaintext), &ciphertext, &ciphertext_len)) {
        printf("Encryption successful\n");

        unsigned char *decrypted;
        if (decrypt_data(cipher_ctx, ciphertext, ciphertext_len, &decrypted, &plaintext_len)) {
            decrypted[plaintext_len] = '\0';
            printf("Decryption successful: %s\n", decrypted);
            free(decrypted);
        } else {
            fprintf(stderr, "Decryption failed\n");
        }
    } else {
        fprintf(stderr, "Encryption failed\n");
    }

    free(ciphertext);
    cleanup_cipher(cipher_ctx);

    return 0;
}
```

**Notes:**
- This code uses OpenSSL for cryptographic operations.
- Ensure that the OpenSSL library is installed and linked during compilation (`gcc -o crypto_lib main.c -lcrypto`).
- The example demonstrates AES-256-CBC mode; modify `initialize_cipher` calls to switch modes.']

