#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_SIZE 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* create_list(size_t initial_capacity) {
    DynamicList *list = malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->entries = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->entries) {
        free(list);
        return NULL;
    }

    list->count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

int add_entry(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity && list->capacity < MAX_SIZE) {
        size_t new_capacity = list->capacity * 2;
        if (new_capacity > MAX_SIZE) new_capacity = MAX_SIZE;

        NFAPI_CRC_INDICATION_PDU_T *new_entries = realloc(list->entries, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_entries) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }

        list->entries = new_entries;
        list->capacity = new_capacity;

        if (list->count >= 0.8 * list->capacity) {
            printf("List is approaching maximum capacity.\n");
        }
    }

    if (list->count < list->capacity) {
        list->entries[list->count++] = entry;
    } else {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_entry(DynamicList *list, int RNTI) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->entries[i].RNTI == RNTI) {
            memmove(&list->entries[i], &list->entries[i + 1], (list->count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            --list->count;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return -1;
}

int update_crcflag(DynamicList *list, int RNTI, int new_flag) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->entries[i].RNTI == RNTI) {
            list->entries[i].CRC_INDICATION_REL8_TAG.CRCFLAG = new_flag;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return -1;
}

size_t get_entry_count(DynamicList *list) {
    pthread_mutex_lock(&list->lock);
    size_t count = list->count;
    pthread_mutex_unlock(&list->lock);
    return count;
}

void free_list(DynamicList *list) {
    pthread_mutex_destroy(&list->lock);
    free(list->entries);
    free(list);
}
