```csharp
using System;
using System.IO;
using System.IO.Compression;
using System.Net.Http;
using System.Threading.Tasks;

public class Metadata
{
    public string UploadUrl { get; set; }
    public long FileSize { get; set; }
}

public class CloudStorageUploader
{
    private readonly HttpClient _httpClient;

    public CloudStorageUploader(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    public async Task<Metadata> CompressAndUploadAsync(byte[] data, string cloudEndpointUrl)
    {
        try
        {
            using var memoryStream = new MemoryStream();

            // Compress the byte array
            await using (var compressionStream = new GZipStream(memoryStream, CompressionLevel.Optimal, leaveOpen: true))
            {
                await compressionStream.WriteAsync(data, 0, data.Length);
            }

            memoryStream.Position = 0;
            long compressedSize = memoryStream.Length;

            // Upload the compressed file
            var content = new StreamContent(memoryStream);
            content.Headers.Add("Content-Encoding", "gzip");

            HttpResponseMessage response = null;
            try
            {
                response = await _httpClient.PutAsync(cloudEndpointUrl, content);

                if (!response.IsSuccessStatusCode)
                {
                    throw new Exception($"Upload failed with status code: {response.StatusCode}");
                }

                string uploadUrl = response.RequestMessage.RequestUri.ToString();
                return new Metadata { UploadUrl = uploadUrl, FileSize = compressedSize };
            }
            catch (Exception ex)
            {
                // Handle network issues or service unavailability
                Console.WriteLine($"An error occurred during the upload: {ex.Message}");
                throw;
            }
            finally
            {
                response?.Dispose();
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred during compression: {ex.Message}");
            throw;
        }
    }

    public async Task UploadWithRetriesAsync(byte[] data, string cloudEndpointUrl, int maxRetries = 3)
    {
        int retryCount = 0;
        while (retryCount < maxRetries)
        {
            try
            {
                var metadata = await CompressAndUploadAsync(data, cloudEndpointUrl);
                Console.WriteLine($"File uploaded successfully: {metadata.UploadUrl}, Size: {metadata.FileSize} bytes");
                return;
            }
            catch
            {
                retryCount++;
                if (retryCount >= maxRetries)
                    throw;

                // Wait before retrying
                await Task.Delay(TimeSpan.FromSeconds(2));
            }
        }
    }
}
```

