typedef struct {
    time_t timestamp;
    size_t packet_size;
    void *packet_data;
} Packet;

typedef struct {
    Packet **packets;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} PacketArray;

void log_packet_added(Packet *packet) {
    // Integrate with an existing logging framework
    printf("Packet added: timestamp=%ld, packet_size=%zu\n", packet->timestamp, packet->packet_size);
}

int validate_packet(void *data, size_t size) {
    // Implement validation logic
    return (data != NULL && size > 0); // Example condition
}

void initialize_packet_array(PacketArray *array, size_t max_size) {
    array->packets = calloc(max_size, sizeof(Packet *));
    if (!array->packets) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    array->capacity = max_size;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
    pthread_cond_init(&array->cond, NULL);
}

void destroy_packet_array(PacketArray *array) {
    for (size_t i = 0; i < array->count; ++i) {
        free(array->packets[i]->packet_data);
        free(array->packets[i]);
    }
    free(array->packets);
    pthread_mutex_destroy(&array->lock);
    pthread_cond_destroy(&array->cond);
}

void *packet_processor(void *arg) {
    PacketArray *array = (PacketArray *)arg;

    while (1) {
        // Simulate non-blocking packet reception
        void *data = NULL; // Replace with actual data reception logic
        size_t size = 0;   // Replace with actual size retrieval

        if (!validate_packet(data, size)) {
            continue;
        }

        Packet *packet = malloc(sizeof(Packet));
        if (!packet) {
            perror("Failed to allocate memory for packet");
            continue;
        }

        pthread_mutex_lock(&array->lock);
        while (array->count >= array->capacity) {
            pthread_cond_wait(&array->cond, &array->lock);
        }

        packet->timestamp = time(NULL);
        packet->packet_size = size;
        packet->packet_data = malloc(size);
        if (!packet->packet_data) {
            perror("Failed to allocate memory for packet data");
            free(packet);
            pthread_mutex_unlock(&array->lock);
            continue;
        }

        memcpy(packet->packet_data, data, size); // Copy received data
        array->packets[array->count++] = packet;

        log_packet_added(packet);

        pthread_cond_signal(&array->cond);
        pthread_mutex_unlock(&array->lock);
    }

    return NULL;
}

void *garbage_collector(void *arg) {
    PacketArray *array = (PacketArray *)arg;

    while (1) {
        usleep(1000000); // Run every second

        pthread_mutex_lock(&array->lock);

        if (array->count > 0) {
            free(array->packets[0]->packet_data);
            free(array->packets[0]);
            memmove(array->packets, array->packets + 1, sizeof(Packet *) * (--array->count));
        }

        pthread_mutex_unlock(&array->lock);
    }

    return NULL;
}

void retrieve_summary_report(const PacketArray *array) {
    size_t total_size = 0;
    int malformed_count = 0;

    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (!validate_packet(array->packets[i]->packet_data, array->packets[i]->packet_size)) {
            malformed_count++;
        }
        total_size += array->packets[i]->packet_size;
    }

    pthread_mutex_unlock(&array->lock);

    printf("Total packets: %zu\n", array->count);
    printf("Average packet size: %.2f\n", array->count > 0 ? (double)total_size / array->count : 0.0);
    printf("Malformed packets discarded: %d\n", malformed_count);
}

int main() {
    const size_t max_packets = 100;
    PacketArray packet_array;

    initialize_packet_array(&packet_array, max_packets);

    pthread_t proc_thread, gc_thread;

    if (pthread_create(&proc_thread, NULL, packet_processor, &packet_array) != 0) {
        perror("Failed to create processing thread");
        return EXIT_FAILURE;
    }

    if (pthread_create(&gc_thread, NULL, garbage_collector, &packet_array) != 0) {
        perror("Failed to create garbage collection thread");
        return EXIT_FAILURE;
    }

    pthread_join(proc_thread, NULL);
    pthread_join(gc_thread, NULL);

    retrieve_summary_report(&packet_array);
    destroy_packet_array(&packet_array);

    return 0;
}
```

### Key Points:
- **Thread Safety**: Uses mutexes and condition variables to manage concurrent access.
- **Non-blocking I/O**: Simulates packet reception in a non-blocking manner.
- **Garbage Collection**: A separate thread periodically removes old packets when the array is full.
- **Logging**: Logs are printed whenever a packet is added (replace with an actual logging framework).
- **Summary Report**: Provides statistics on processed packets.

This code provides a basic structure to handle the described requirements. Adjustments may be needed based on specific network interfaces and logging frameworks used in your environment.']

