    CRC_INDICATION_REL8_TAG_T crc_indication_rel8_tag;
    unsigned char CRCFLAG;  // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

// Define the dynamic array structure with a mutex for thread safety
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t used;
    size_t size;
    pthread_mutex_t lock;
} NFAPIDynamicArray;

void initNFAPIDynamicArray(NFAPIDynamicArray *a, size_t initialSize) {
    a->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initialSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!a->array) exit(1); // Handle allocation failure
    a->used = 0;
    a->size = initialSize;
    pthread_mutex_init(&a->lock, NULL);
}

void insertNFAPIDynamicArray(NFAPIDynamicArray *a, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&a->lock);

    // Resize if necessary
    if (a->used == a->size) {
        size_t newSize = a->size * 2;
        NFAPI_CRC_INDICATION_PDU_T *newArray = realloc(a->array, newSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!newArray) exit(1); // Handle allocation failure
        a->array = newArray;
        a->size = newSize;
    }

    a->array[a->used++] = element;

    pthread_mutex_unlock(&a->lock);
}

void freeNFAPIDynamicArray(NFAPIDynamicArray *a) {
    pthread_mutex_lock(&a->lock);
    free(a->array);
    pthread_mutex_unlock(&a->lock);
    pthread_mutex_destroy(&a->lock);
}

