    pthread_mutex_t lock;
} DynamicCollection;

EVP_CIPHER* select_cipher(int key_size, const char* mode) {
    if (strcmp(mode, "GCM") == 0) {
        return EVP_aes_128_gcm();
    } else if (strcmp(mode, "CTR") == 0 && key_size == 256) {
        return EVP_aes_256_ctr();
    } else if (strcmp(mode, "OFB") == 0 && key_size == 128) {
        return EVP_chacha20_ofb();
    }
    // Add more cipher options as needed
    return NULL;
}

DynamicCollection* create_collection() {
    DynamicCollection *collection = malloc(sizeof(DynamicCollection));
    if (!collection) {
        perror("Failed to allocate collection");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&collection->lock, NULL);
    collection->data = NULL;
    collection->size = 0;
    collection->capacity = 0;

    return collection;
}

int add_pdu(DynamicCollection *collection, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&collection->lock);

    if (collection->size >= MAX_STRUCTS) {
        fprintf(stderr, "Max structures limit reached\n");
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    if (collection->capacity <= collection->size) {
        size_t new_capacity = collection->capacity == 0 ? 4 : collection->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(collection->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            perror("Failed to reallocate memory");
            pthread_mutex_unlock(&collection->lock);
            return -1;
        }
        collection->data = new_data;
        collection->capacity = new_capacity;
    }

    collection->data[collection->size] = pdu;
    collection->size++;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

void free_collection(DynamicCollection *collection) {
    if (collection) {
        pthread_mutex_destroy(&collection->lock);
        free(collection->data);
        free(collection);
    }
}

// Usage example
int main() {
    DynamicCollection* collection = create_collection();

    for (int i = 0; i < 10; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand();
        pdu.RNTI = rand();
        memset(pdu.CRC_INDICATION_REL8_TAG, rand() % 256, sizeof(pdu.CRC_INDICATION_REL8_TAG));

        if (add_pdu(collection, pdu) != 0) {
            fprintf(stderr, "Failed to add PDU\n");
        }
    }

    EVP_CIPHER* cipher = select_cipher(128, "GCM");
    if (!cipher) {
        fprintf(stderr, "Cipher selection failed\n");
    } else {
        printf("Selected Cipher: %s\n", EVP_CIPHER_name(cipher));
    }

    free_collection(collection);
    return 0;
}
```

### Key Points:

- **Thread Safety**: Uses `pthread_mutex_t` to ensure thread-safe operations when modifying the collection.

- **Dynamic Memory Management**: Efficiently manages memory by doubling capacity when needed and freeing resources properly.

- **Cipher Selection**: Dynamically selects an encryption cipher based on key size and mode.

- **Error Handling**: Handles allocation failures and invalid inputs gracefully.

- **Scalability**: Designed to handle up to `MAX_STRUCTS` efficiently, with room for further optimization.']

