        printf("Error: Array full. Cannot add more elements.\n");
        pthread_mutex_unlock(&dyn_array->lock);
        return -1;
    }

    size_t index = dyn_array->count++;
    dyn_array->array[index] = malloc(sizeof(LTE_ENB_RRC_API_T));
    if (!dyn_array->array[index]) {
        printf("Memory allocation failed for new element.\n");
        pthread_mutex_unlock(&dyn_array->lock);
        return -1;
