        printf("Memory allocation failed for MAC_PDU buffer.\n");
        free(dyn_array->array[index]);
        pthread_mutex_unlock(&dyn_array->lock);
        return -1;
    }

    // Log memory usage
    printf("Added element at index %zu. Current memory usage: %zu bytes\n", index, sizeof(LTE_ENB_RRC_API_T) + adaptive_buffer_size);

    pthread_mutex_unlock(&dyn_array->lock);
    return 0;
}

void free_dynamic_array(DynamicArray *dyn_array) {
    if (!dyn_array) return;

    pthread_mutex_lock(&dyn_array->lock);

    for (size_t i = 0; i < dyn_array->count; ++i) {
        if (dyn_array->array[i]) {
            free(dyn_array->array[i]->mac_pdu_buffer);
            free(dyn_array->array[i]);
        }
    }

    pthread_mutex_unlock(&dyn_array->lock);

    pthread_mutex_destroy(&dyn_array->lock);
    free(dyn_array);

    printf("Dynamic array freed. Final memory usage: 0 bytes\n");
}

void iterate_and_process(DynamicArray *dyn_array, void (*process)(LTE_ENB_RRC_API_T *)) {
