['```c
#include <stdio.h>
#include <stdlib.h>

// Define the structure for a record.
typedef struct {
    int value;
} Record;

/**
 * Allocate memory for a collection of records.
 *
 * @param count Number of records to allocate.
 * @return A pointer to an array of allocated records, or NULL if allocation fails.
 */
Record* allocate_records(size_t count) {
    // Attempt to allocate memory for the records
    Record* records = (Record*)malloc(count * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Initialize each record's value to zero.
    for (size_t i = 0; i < count; ++i) {
        records[i].value = 0;
    }

    return records;
}

/**
 * Serialize the data into a binary format and write it to a file.
 *
 * @param records Pointer to an array of records.
 * @param count Number of records in the array.
 * @param filename Name of the file to write the serialized data to.
 * @return 0 on success, -1 on failure.
 */
int serialize_to_file(const Record* records, size_t count, const char* filename) {
    if (!records || !filename) return -1;

    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("File opening failed");
        return -1;
    }

    // Write the number of records followed by each record's value.
    size_t written_bytes = fwrite(&count, sizeof(size_t), 1, file);
    if (written_bytes != 1) {
        perror("Failed to write record count");
        fclose(file);
        return -1;
    }

    written_bytes = fwrite(records, sizeof(Record), count, file);
    if (written_bytes != count) {
        perror("Failed to write records data");
        fclose(file);
        return -1;
    }

    if (fclose(file) != 0) {
        perror("File closing failed");
        return -1;
    }

    return 0;
}

/**
 * Free the allocated memory for records.
 *
 * @param records Pointer to an array of records.
 */
void free_records(Record* records) {
    if (records) {
        free(records);
    }
}
```

### Key Points:
- **Memory Management**: The `allocate_records` function allocates and initializes contiguous blocks of memory. It handles allocation failures by returning NULL, allowing the caller to manage error states.
- **Serialization**: The `serialize_to_file` function writes data in a binary format for efficiency, which balances performance with simplicity for deserialization.
- **Error Handling**: Both functions include robust error handling mechanisms, such as checking return values and using standard I/O functions that provide error reporting through `perror`.
- **Resource Management**: Functions are provided to both allocate (`allocate_records`) and free memory (`free_records`), ensuring resources are managed appropriately.']

