public enum DistributionType { Uniform, Normal }

public class DynamicRangeGenerator
{
    private int minValue;
    private int maxValue;
    private IExternalConfigService configService;
    private Random random = new Random();
    private ReaderWriterLockSlim rangeLock = new ReaderWriterLockSlim();
    private Dictionary<int, int> generationCounts = new Dictionary<int, int>();

    public DynamicRangeGenerator(IExternalConfigService configService)
    {
        this.configService = configService ?? throw new ArgumentNullException(nameof(configService));
        LoadConfig();
    }

    public int MinValue
    {
        get => minValue;
        set
        {
            rangeLock.EnterWriteLock();
            try
            {
                SetRange(value, maxValue, false);
            }
            finally
            {
                rangeLock.ExitWriteLock();
            }
        }
    }

    public int MaxValue
    {
        get => maxValue;
        set
        {
            rangeLock.EnterWriteLock();
            try
            {
                SetRange(minValue, value, false);
            }
            finally
            {
                rangeLock.ExitWriteLock();
            }
        }
    }

    public bool IsRangeSet() => minValue <= maxValue;

    public void LoadConfig()
    {
        rangeLock.EnterUpgradeableReadLock();
        try
        {
            if (!IsRangeSet())
            {
                var config = configService.GetDefaultRangeSettings();
                SetRange(config.MinValue, config.MaxValue);
            }
        }
        finally
        {
            rangeLock.ExitUpgradeableReadLock();
        }
    }

    public void ClearRange()
    {
        rangeLock.EnterWriteLock();
        try
        {
            minValue = int.MinValue;
            maxValue = int.MaxValue;
            generationCounts.Clear();
        }
        finally
        {
            rangeLock.ExitWriteLock();
        }
    }

    private void SetRange(int newMin, int newMax, bool allowOverlap)
    {
        if (newMin > newMax) throw new ArgumentException("Minimum value cannot be greater than maximum value.");

        if (!allowOverlap && IsRangeSet() && !(newMax < minValue || newMin > maxValue))
            throw new InvalidOperationException("Overlapping range not allowed without enabling overlap mode.");

        minValue = newMin;
        maxValue = newMax;
    }

    public int GenerateInt()
    {
        rangeLock.EnterReadLock();
        try
        {
            if (!IsRangeSet()) throw new InvalidOperationException("Range is not set.");

            int value = random.Next(minValue, maxValue + 1);
            UpdateGenerationStatistics(value);
            return value;
        }
        finally
        {
            rangeLock.ExitReadLock();
        }
    }

    public float GenerateFloat()
    {
        rangeLock.EnterReadLock();
        try
        {
            if (!IsRangeSet()) throw new InvalidOperationException("Range is not set.");

            float value = (float)(random.NextDouble() * (maxValue - minValue + 1) + minValue);
            UpdateGenerationStatistics((int)value);
            return value;
        }
        finally
        {
            rangeLock.ExitReadLock();
        }
    }

    public T GenerateRandom<T>(DistributionType type)
    {
        if (!IsRangeSet()) throw new InvalidOperationException("Range is not set.");

        switch (type)
        {
            case DistributionType.Uniform:
                return (T)(object)GenerateFloat(); // Simplified; extend for int or other types as needed.
            case DistributionType.Normal:
                double mean = (minValue + maxValue) / 2.0;
                double stddev = (maxValue - minValue) / 6.0;
                double normalVal = GenerateNormal(mean, stddev);
                return (T)(object)Math.Max(minValue, Math.Min(maxValue, (int)normalVal));
            default:
                throw new ArgumentException("Unsupported distribution type.");
        }
    }

    private void UpdateGenerationStatistics(int value)
    {
        if (!generationCounts.ContainsKey(value))
        {
            generationCounts[value] = 0;
        }
        generationCounts[value]++;
    }

    public IDictionary<int, int> GetGenerationStatistics()
    {
        rangeLock.EnterReadLock();
        try
        {
            return new Dictionary<int, int>(generationCounts);
        }
        finally
        {
            rangeLock.ExitReadLock();
        }
    }

    private double GenerateNormal(double mean, double stddev)
    {
        double u1 = 1.0 - random.NextDouble(); // uniform(0,1] random doubles
        double u2 = 1.0 - random.NextDouble();
        double randStdNormal = Math.Sqrt(-2.0 * Math.Log(u1)) *
                               Math.Sin(2.0 * Math.PI * u2); // random normal(0,1)
        return mean + stddev * randStdNormal; // random normal(mean,stdDev^2)
    }
}

public interface IExternalConfigService
{
    RangeSettings GetDefaultRangeSettings();
}

public class RangeSettings
{
    public int MinValue { get; set; }
    public int MaxValue { get; set; }
}
