```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    int value;
    int* key_ptr;
} Record;

typedef struct Node {
    long offset;
    int key;
    Record record;
} Node;

typedef struct Collection {
    Node* data;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    long total_value;
} Collection;

static void safe_add(long *total, long value) {
    if (value > 0 && (*total > LLONG_MAX - value)) {
        // Handle overflow
        *total = LLONG_MAX;
    } else if (value < 0 && (*total < LLONG_MIN - value)) {
        // Handle underflow
        *total = LLONG_MIN;
    } else {
        *total += value;
    }
}

Collection* init_collection(size_t initial_capacity) {
    Collection* coll = malloc(sizeof(Collection));
    coll->data = calloc(initial_capacity, sizeof(Node));
    coll->capacity = initial_capacity;
    coll->count = 0;
    coll->total_value = 0;
    pthread_mutex_init(&coll->mutex, NULL);
    return coll;
}

void resize_collection(Collection* coll) {
    pthread_mutex_lock(&coll->mutex);

    size_t new_capacity = coll->capacity * 2;
    Node* new_data = realloc(coll->data, new_capacity * sizeof(Node));

    if (new_data) {
        coll->data = new_data;
        coll->capacity = new_capacity;
    }

    pthread_mutex_unlock(&coll->mutex);
}

void initialize_records(Collection* coll) {
    srand(time(NULL));
    pthread_mutex_lock(&coll->mutex);

    for (size_t i = 0; i < coll->count; ++i) {
        double average = (double)coll->total_value / coll->count;
        int range_min = (int)(average - 10);
        int range_max = (int)(average + 10);

        if (range_min > range_max) {
            int temp = range_min;
            range_min = range_max;
            range_max = temp;
        }

        int value = rand() % (range_max - range_min + 1) + range_min;

        coll->data[i].record.value = value;
        coll->data[i].record.key_ptr = &coll->data[i].key;
        safe_add(&coll->total_value, value);
    }

    pthread_mutex_unlock(&coll->mutex);
}

void add_record(Collection* coll, long offset, int key) {
    pthread_mutex_lock(&coll->mutex);

    if (coll->count == coll->capacity) {
        resize_collection(coll);
    }

    Node* node = &coll->data[coll->count++];
    node->offset = offset;
    node->key = key;

    pthread_mutex_unlock(&coll->mutex);
}

void release_collection(Collection* coll) {
    pthread_mutex_lock(&coll->mutex);

    free(coll->data);
    pthread_mutex_unlock(&coll->mutex);

    pthread_mutex_destroy(&coll->mutex);
    free(coll);
}
```

### Key Points:

- **Thread Safety**: The function uses `pthread_mutex_t` to ensure thread-safe operations.
- **Efficient Resizing**: It doubles the capacity when needed, minimizing allocations.
- **Safe Arithmetic**: The `safe_add` function prevents overflow/underflow during total updates.
- **Random Initialization**: Records are initialized with values in a range based on the current average.
- **Memory Management**: Proper allocation and deallocation prevent memory leaks."]

