int validate_memory(void *start1, size_t size1, void *start2, size_t size2);

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to dynamically allocate and initialize data structures
void* allocate_and_initialize_data(size_t record_count) {
    if (record_count <= 0) return NULL;

    // Calculate total memory needed
    size_t offsets_size = record_count * sizeof(long);
    size_t keys_size = record_count * sizeof(int);
    size_t records_size = record_count * sizeof(Record);
    size_t metadata_size = record_count * sizeof(Metadata*);

    size_t total_size = offsets_size + keys_size + records_size + metadata_size;

    // Allocate memory in a single block
    void *memory_block = malloc(total_size);
    if (!memory_block) return NULL;

    long *offsets = (long *)memory_block;
    int *keys = (int *)(offsets + record_count);
    Record *records = (Record *)(keys + record_count);
    Metadata **metadata = (Metadata**)(records + record_count);

    // Initialize data
    for (size_t i = 0; i < record_count; ++i) {
        offsets[i] = rand() % 1000;
        keys[i] = rand() % 100;
        records[i].value = rand() % 500;
        metadata[i] = (Metadata)(intptr_t)i; // Unique identifier
    }

    return memory_block;
}

// Function to serialize and write data to a file with compression
void serialize_and_write_data(long *offsets, int *keys, Record *records, Metadata **metadata, size_t count, const char *filename) {
    pthread_mutex_lock(&mutex);

    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("File opening failed");
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Write data
    fwrite(offsets, sizeof(long), count, file);
    fwrite(keys, sizeof(int), count, file);
    fwrite(records, sizeof(Record), count, file);

    for (size_t i = 0; i < count; ++i) {
        fwrite(metadata[i], sizeof(Metadata), 1, file);
    }

    fclose(file);

    pthread_mutex_unlock(&mutex);
}

// Validate memory allocation
int validate_memory(void *start1, size_t size1, void *start2, size_t size2) {
    if (start1 == NULL || start2 == NULL)
        return 0;

    uintptr_t end1 = (uintptr_t)start1 + size1;
    uintptr_t begin2 = (uintptr_t)start2;
    uintptr_t end2 = begin2 + size2;

    return !(end1 > begin2 && begin2 < end1) && !(end2 > (uintptr_t)start1 && (uintptr_t)start1 < end2);
}

// Main function to demonstrate usage
int main() {
    srand(time(NULL));

    size_t record_count = 100;
    void *data_block = allocate_and_initialize_data(record_count);

    if (!data_block) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    long *offsets = (long *)data_block;
    int *keys = (int *)(offsets + record_count);
    Record *records = (Record *)(keys + record_count);
    Metadata **metadata = (Metadata**)(records + record_count);

    serialize_and_write_data(offsets, keys, records, metadata, record_count, "output.bin");

    free(data_block);
    return EXIT_SUCCESS;
}
