#include <ctype.h>

#define MAX_TIMESTAMPS 10000

void process_timestamps() {
    int *timestamps = NULL;
    int count = 0;
    char buffer[12]; // Buffer to store each line, assuming maximum length of a long integer in decimal form plus newline
    size_t bufsize = sizeof(buffer);

    while (fgets(buffer, bufsize, stdin) != NULL && count < MAX_TIMESTAMPS) {
        char *endptr;
        long timestamp = strtol(buffer, &endptr, 10);

        if (*buffer == '\0' || isspace(*buffer)) { // Skip empty lines or whitespace
            continue;
        }

        if (endptr != buffer && *endptr == '\n') { // Valid number found
            timestamps = realloc(timestamps, sizeof(int) * (count + 1));
            if (!timestamps) {
                fprintf(stderr, "Memory allocation failed\n");
                free(timestamps);
                return;
            }
            timestamps[count++] = timestamp;
        }
    }

    if (count == 0) {
        printf("No valid timestamps found.\n");
        free(timestamps);
        return;
    }

    int max_timestamp = timestamps[0];
    for (int i = 1; i < count; ++i) {
        if (timestamps[i] > max_timestamp) {
            max_timestamp = timestamps[i];
        }
    }

    printf("Largest timestamp: %d\n", max_timestamp);
    free(timestamps);
}
