typedef struct {
    int value;
} record;

// Function to handle memory allocation and random initialization for arrays
void init_arrays(long *offsets, int *keys, record *records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        offsets[i] = rand() % 10000;
        keys[i] = rand() % 100;
        records[i].value = rand() % 100;
    }
