// Function to fetch data from an external RESTful API asynchronously
size_t write_callback(void *ptr, size_t size, size_t nmemb, void *userdata) {
    // Append the fetched data to userdata (could be a buffer)
    return size * nmemb;
}

void fetch_data_async(const char* url) {
    CURL *curl = curl_easy_init();
    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        // Start the asynchronous transfer
        curl_multi_add_handle(curl_multi, curl);
        curl_easy_perform(curl);
        curl_multi_remove_handle(curl_multi, curl);
        curl_easy_cleanup(curl);
    }
}

// Function to encrypt data using AES or Camellia based on configuration
void encrypt_data(const unsigned char *plaintext, int plaintext_len,
                  const EVP_CIPHER *cipher_type, unsigned char *key, 
                  unsigned char *iv, unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, cipher_type, NULL, key, iv);
    EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len);
    EVP_EncryptFinal_ex(ctx, ciphertext + len, &len);
    EVP_CIPHER_CTX_free(ctx);
}

// Thread function for data processing
