#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a structure for each record
typedef struct {
    double number;
    char *str;
} Record;

// Function to dynamically allocate memory for records
Record* create_records(size_t num_records, size_t max_str_length) {
    // Allocate memory for the array of records
    Record* records = (Record*)malloc(num_records * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    // Initialize each record
    for (size_t i = 0; i < num_records; ++i) {
        records[i].number = 0.0;

        // Allocate memory for the string with an additional character for null-termination
        records[i].str = (char*)malloc(max_str_length + 1);
        if (!records[i].str) {
            perror("Failed to allocate memory for string");
            // Free already allocated strings in case of partial failure
            while (--i >= 0) free(records[i].str);
            free(records);
            return NULL;
        }

        // Initialize the string as empty
        records[i].str[0] = '\0';
    }

    return records;
}

// Function to safely handle external input and assign it to a record
int set_record(Record* record, double number, const char *input_str) {
    if (!record || !input_str) {
        return -1; // Invalid arguments
    }

    // Safely copy string into the record's allocated memory
    size_t len = strlen(input_str);
    if (len > (size_t)-1) {  // Check for potential overflow in length computation
        perror("Input string is too long");
        return -1;
    }

    strncpy(record->str, input_str, len); // Copy safely without exceeding buffer size

    // Set the number value
    record->number = number;

    return 0; // Success
}

// Function to free allocated memory for records
void destroy_records(Record* records, size_t num_records) {
    if (!records) {
        return;
    }

    for (size_t i = 0; i < num_records; ++i) {
        free(records[i].str);
    }

    free(records);
}

int main() {
    size_t num_records = 5; // Example record count
    size_t max_str_length = 100; // Maximum length of strings

    Record* records = create_records(num_records, max_str_length);
    if (!records) {
        return EXIT_FAILURE;
    }

    const char *example_strings[] = {"Hello", "World", "C programming", "Memory management", "Dynamic allocation"};

    for (size_t i = 0; i < num_records && i < sizeof(example_strings)/sizeof(*example_strings); ++i) {
        set_record(&records[i], (double)(i + 1), example_strings[i]);
    }

    // Print records
    for (size_t i = 0; i < num_records; ++i) {
        printf("Record %zu: Number = %.2f, String = '%s'\n", i, records[i].number, records[i].str);
    }

    destroy_records(records, num_records);

    return EXIT_SUCCESS;
}
