#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netdb.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_IP_LEN 16 // Max length for IPv4 address in string form, including null terminator
#define CACHE_SIZE 100
#define DNS_QUERY_LIMIT 10

typedef struct {
    char hostname[256];
    u_char ip[MAX_IP_LEN];
    time_t timestamp;
} DnsCacheEntry;

static DnsCacheEntry dns_cache[CACHE_SIZE];
static pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;
static unsigned int query_count = 0;
static pthread_mutex_t query_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the DNS cache
void init_dns_cache() {
    for (int i = 0; i < CACHE_SIZE; ++i) {
        dns_cache[i].hostname[0] = '\0';
    }
}

// Check if hostname is in cache and valid
static int check_cache(const char *hostname, u_char *ip_out) {
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (dns_cache[i].hostname[0] != '\0' &&
            strcmp(dns_cache[i].hostname, hostname) == 0 &&
            time(NULL) - dns_cache[i].timestamp < 300) { // Cache validity: 5 minutes
            memcpy(ip_out, dns_cache[i].ip, MAX_IP_LEN);
            pthread_mutex_unlock(&cache_lock);
            return 1;
        }
    }
    pthread_mutex_unlock(&cache_lock);
    return 0;
}

// Add entry to DNS cache
static void add_to_cache(const char *hostname, const u_char *ip) {
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (dns_cache[i].hostname[0] == '\0') {
            strncpy(dns_cache[i].hostname, hostname, sizeof(dns_cache[i].hostname));
            memcpy(dns_cache[i].ip, ip, MAX_IP_LEN);
            dns_cache[i].timestamp = time(NULL);
            pthread_mutex_unlock(&cache_lock);
            return;
        }
    }
    // Simple LRU eviction
    int oldest_index = 0;
    time_t oldest_time = dns_cache[0].timestamp;
    for (int i = 1; i < CACHE_SIZE; ++i) {
        if (dns_cache[i].timestamp < oldest_time) {
            oldest_time = dns_cache[i].timestamp;
            oldest_index = i;
        }
    }
    strncpy(dns_cache[oldest_index].hostname, hostname, sizeof(dns_cache[oldest_index].hostname));
    memcpy(dns_cache[oldest_index].ip, ip, MAX_IP_LEN);
    dns_cache[oldest_index].timestamp = time(NULL);
    pthread_mutex_unlock(&cache_lock);
}

// Asynchronous DNS resolution
static void *resolve_dns(void *arg) {
    struct hostent *host;
    char **addr_list;
    u_char resolved_ip[MAX_IP_LEN];
    const char *hostname = (const char *)arg;

    if ((host = gethostbyname(hostname)) == NULL) {
        pthread_exit((void *)(intptr_t)-1);
    }

    addr_list = (char **)host->h_addr_list;
    for (int i = 0; addr_list[i] != NULL; ++i) {
        inet_ntop(AF_INET, addr_list[i], resolved_ip, MAX_IP_LEN);
        add_to_cache(hostname, resolved_ip);
        pthread_exit((void *)(intptr_t)resolved_ip);
    }

    pthread_exit((void *)(intptr_t)-1);
}

u_char *resolve_hostname(const char *hostname, u_char *ip_array_out) {
    static pthread_mutex_t query_lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_t thread_id;
    void *thread_result;

    if (check_cache(hostname, ip_array_out)) {
        return ip_array_out;
    }

    pthread_mutex_lock(&query_lock);
    if (query_count >= DNS_QUERY_LIMIT) {
        pthread_mutex_unlock(&query_lock);
        return NULL; // Exceeded query limit
    }
    ++query_count;
    pthread_mutex_unlock(&query_lock);

    if (pthread_create(&thread_id, NULL, resolve_dns, (void *)hostname)) {
        return NULL;
    }

    if (pthread_join(thread_id, &thread_result)) {
        pthread_cancel(thread_id);
        pthread_mutex_lock(&query_lock);
        --query_count;
        pthread_mutex_unlock(&query_lock);
        return NULL;
    }

    int result = (intptr_t)thread_result;
    if (result == -1) {
        pthread_mutex_lock(&query_lock);
        --query_count;
        pthread_mutex_unlock(&query_lock);
        return NULL; // Resolution failed
    } else {
        memcpy(ip_array_out, thread_result, MAX_IP_LEN);
        return ip_array_out;
    }
}

// Wrapper function for testing
void test_resolve_hostname() {
    const char *hostname = "example.com";
    u_char resolved_ip[49] = {0}; // 48 bytes + null terminator

    if (resolve_hostname(hostname, resolved_ip)) {
        printf("Resolved IP: %s\n", resolved_ip);
    } else {
        printf("Failed to resolve hostname.\n");
    }
}

int main() {
    init_dns_cache();
    test_resolve_hostname();
    return 0;
}
