using System;
using System.IO;
using System.Xml;
using System.Collections.Generic;

public class DirectoryAndRecordManager
{
    private const string DefaultDirectoryPath = "C:\\DefaultDir";
    private const string XmlConfigFilePath = "config.xml";

    public static string CreateDirectoryWithEnvVar(string directoryName)
    {
        string parentPath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, directoryName);
        if (!Directory.Exists(parentPath))
            Directory.CreateDirectory(parentPath);

        string envVarValue;
        if (Environment.GetEnvironmentVariable(directoryName) != null)
        {
            envVarValue = Environment.GetEnvironmentVariable(directoryName);
        }
        else
        {
            envVarValue = parentPath;
            Environment.SetEnvironmentVariable(directoryName, parentPath);
        }

        return envVarValue;
    }

    public static string GetDirectoryFromXml(string elementName)
    {
        XmlDocument doc = new XmlDocument();
        try
        {
            doc.Load(XmlConfigFilePath);

            XmlNodeList nodes = doc.SelectNodes($"/Configuration/{elementName}");
            if (nodes.Count == 1)
                return nodes[0].InnerText;

            Console.WriteLine($"Info: {elementName} found {nodes.Count} times. Using default path.");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error parsing XML: {ex.Message}. Using default path.");
        }

        return DefaultDirectoryPath;
    }
}
