#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
    int keyIndex;
} Record;

#define MAX_THREADS 4
#define RANGE 100

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* ConcurrentRecordInitializer(void* args) {
    int numRecords = *(int*)args;
    long *offsets = malloc(numRecords * sizeof(long));
    int *keys = malloc(numRecords * sizeof(int));
    Record *records = malloc(numRecords * sizeof(Record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srand(time(NULL));

    long totalSum = 0;

    for (int i = 0; i < numRecords; ++i) {
        pthread_mutex_lock(&lock);

        offsets[i] = rand() % RANGE + totalSum;
        keys[i] = rand() % RANGE;

        records[i].value = rand() % (RANGE - totalSum);
        records[i].keyIndex = i;

        totalSum += records[i].value;

        pthread_mutex_unlock(&lock);
    }

    // Example usage
    for (int i = 0; i < numRecords; ++i) {
        printf("Record %d: Value=%d, Key=%d\n", i, records[i].value, keys[records[i].keyIndex]);
    }

    free(offsets);
    free(keys);
    free(records);

    return NULL;
}

int main() {
    int numThreads = MAX_THREADS;
    pthread_t threads[MAX_THREADS];
    int numRecords = 100;

    for (int i = 0; i < numThreads; ++i) {
        if (pthread_create(&threads[i], NULL, ConcurrentRecordInitializer, &numRecords)) {
            fprintf(stderr, "Error creating thread\n");
            return 1;
        }
    }

    for (int i = 0; i < numThreads; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
