        records[i].rnti = rand() % 100000;
        records[i].crc_indication_rel8_tag.CRCFLAG = rand() % 2;

#ifdef _WIN32
        Sleep(0); // Yield thread for Windows systems
#else
        sched_yield(); // Yield thread for POSIX systems
#endif
    }

    return records;
}

void free_records(NFAPI_CRC_INDICATION_PDU_T *records) {
