    WSADATA wsaData;
    WSAStartup(MAKEWORD(2, 2), &wsaData);
#endif

    NFAPI_CRC_INDICATION_PDU_T *records = allocate_and_initialize_records(record_count);

    if (records) {
        for (size_t i = 0; i < record_count; ++i) {
            printf("Record %zu: RNTI=%lu, CRCFLAG=%d\n",
                   i,
                   records[i].rnti,
                   records[i].crc_indication_rel8_tag.CRCFLAG);
        }
    }

    free_records(records);

#ifdef _WIN32
    WSACleanup();
#endif

    return 0;
}
