['Below is a C implementation of the described functionality. This example uses POSIX threads (pthreads) for thread safety and includes dynamic resizing of the collection, memory management strategies, and serialization.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

#define MAX_MESSAGES_INITIAL 10
#define MAX_MESSAGE_BODY_LENGTH 256

typedef struct {
    time_t timestamp;
    int id;
    char *body;
} Message;

typedef struct {
    Message **messages;
    size_t count;
    size_t capacity;
    size_t total_length;
    pthread_mutex_t lock;
} MessageCollection;

// Utility functions for safe arithmetic
int64_t safe_add(int64_t a, int64_t b) {
    if (a > INT64_MAX - b) return INT64_MAX;
    return a + b;
}

int64_t safe_mul(uint64_t a, uint64_t b) {
    if (a == 0 || b == 0) return 0;
    if (UINT64_MAX / b < a) return UINT64_MAX;
    return a * b;
}

// Function to initialize the message collection
void init_message_collection(MessageCollection *collection) {
    pthread_mutex_init(&collection->lock, NULL);
    collection->messages = malloc(MAX_MESSAGES_INITIAL * sizeof(Message *));
    if (!collection->messages) exit(EXIT_FAILURE);
    collection->count = 0;
    collection->capacity = MAX_MESSAGES_INITIAL;
    collection->total_length = 0;
}

// Function to resize the message collection
void resize_message_collection(MessageCollection *collection, size_t new_capacity) {
    Message **new_messages = realloc(collection->messages, new_capacity * sizeof(Message *));
    if (!new_messages) exit(EXIT_FAILURE);
    for (size_t i = collection->count; i < new_capacity; ++i) {
        new_messages[i] = NULL;
    }
    collection->messages = new_messages;
    collection->capacity = new_capacity;
}

// Function to add a message
void add_message(MessageCollection *collection, const char *templates[], size_t num_templates) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count >= collection->capacity) {
        resize_message_collection(collection, safe_mul(collection->capacity, 2));
    }

    Message *new_msg = malloc(sizeof(Message));
    if (!new_msg) exit(EXIT_FAILURE);

    new_msg->timestamp = time(NULL);
    new_msg->id = collection->count;
    size_t body_length = rand() % MAX_MESSAGE_BODY_LENGTH + 1;

    new_msg->body = malloc(body_length);
    if (!new_msg->body) {
        free(new_msg);
        exit(EXIT_FAILURE);
    }

    int template_index = rand() % num_templates;
    strncpy(new_msg->body, templates[template_index], body_length);

    collection->messages[collection->count] = new_msg;
    collection->total_length = safe_add(collection->total_length, (int64_t)body_length);
    ++collection->count;

    pthread_mutex_unlock(&collection->lock);
}

// Function to serialize the message collection
void serialize_message_collection(const MessageCollection *collection, FILE *file) {
    pthread_mutex_lock((pthread_mutex_t *)&collection->lock);

    fwrite(&collection->count, sizeof(collection->count), 1, file);
    for (size_t i = 0; i < collection->count; ++i) {
        const Message *msg = collection->messages[i];
        fwrite(&msg->timestamp, sizeof(msg->timestamp), 1, file);
        fwrite(&msg->id, sizeof(msg->id), 1, file);
        size_t body_length;
        fwrite(&body_length, sizeof(body_length), 1, file);
        fwrite(msg->body, sizeof(char), body_length, file);
    }

    pthread_mutex_unlock((pthread_mutex_t *)&collection->lock);
}

// Function to deserialize the message collection
void deserialize_message_collection(MessageCollection *collection, FILE *file) {
    pthread_mutex_lock(&collection->lock);

    fread(&collection->count, sizeof(collection->count), 1, file);
    for (size_t i = 0; i < collection->count; ++i) {
        Message *msg = malloc(sizeof(Message));
        if (!msg) exit(EXIT_FAILURE);

        fread(&msg->timestamp, sizeof(msg->timestamp), 1, file);
        fread(&msg->id, sizeof(msg->id), 1, file);

        size_t body_length;
        fread(&body_length, sizeof(body_length), 1, file);
        msg->body = malloc(body_length);
        if (!msg->body) {
            free(msg);
            exit(EXIT_FAILURE);
        }

        fread(msg->body, sizeof(char), body_length, file);

        collection->messages[i] = msg;
    }

    pthread_mutex_unlock(&collection->lock);
}

// Function to clean up the message collection
void cleanup_message_collection(MessageCollection *collection) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->messages[i]->body);
        free(collection->messages[i]);
    }

    free(collection->messages);
    pthread_mutex_unlock(&collection->lock);
}

// Example usage
int main() {
    MessageCollection collection;
    init_message_collection(&collection);

    const char *templates[] = {"Hello", "World", "Test message", "Another example"};
    size_t num_templates = sizeof(templates) / sizeof(templates[0]);

    srand(time(NULL)); // Seed for randomness

    add_message(&collection, templates, num_templates);

    FILE *file = fopen("messages.dat", "wb");
    serialize_message_collection(&collection, file);
    fclose(file);

    MessageCollection new_collection;
    init_message_collection(&new_collection);

    file = fopen("messages.dat", "rb");
    deserialize_message_collection(&new_collection, file);
    fclose(file);

    cleanup_message_collection(&collection);
    cleanup_message_collection(&new_collection);

    return 0;
}
```

### Key Points:
- **Thread Safety**: The use of `pthread_mutex_t` ensures that concurrent access to the message collection is thread-safe.
- **Dynamic Resizing**: The collection can grow dynamically by doubling its capacity when needed.
- **Memory Management**: Memory for message bodies is allocated as needed, and care is taken to handle allocation failures gracefully.
- **Serialization**: Functions are provided to serialize and deserialize the state of the message collection to/from a file.
- **Overflow Checks**: Custom safe arithmetic functions (`safe_add`, `safe_mul`) prevent integer overflow issues.

This implementation considers performance, thread safety, and maintainability while allowing for potential future extensions.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>
#include <stdint.h>

#define INITIAL_RECORDS 10
#define KEY_RANGE_MAX 1000

typedef struct {
    int value;
} record_t;

// Lock-free array using atomic operations for thread safety
typedef struct {
    _Atomic(int*) keys_array;
    _Atomic(long*) offsets_array;
    _Atomic(record_t**) records_array;
    size_t size;
} lock_free_array_t;

lock_free_array_t* create_lock_free_array(size_t initial_size) {
    lock_free_array_t* array = malloc(sizeof(lock_free_array_t));
    if (!array) return NULL;

    int* keys_array = calloc(initial_size, sizeof(int));
    long* offsets_array = calloc(initial_size, sizeof(long));
    record_t** records_array = calloc(initial_size, sizeof(record_t*));

    if (!keys_array || !offsets_array || !records_array) {
        free(keys_array);
        free(offsets_array);
        free(records_array);
        free(array);
        return NULL;
    }

    array->keys_array = atomic_init(&keys_array);
    array->offsets_array = atomic_init(&offsets_array);
    array->records_array = atomic_init(&records_array);
    array->size = initial_size;

    return array;
}

int add_record(lock_free_array_t* array, int key, long offset) {
    size_t index = __sync_fetch_and_add(&(array->size), 1);

    if (index >= 1000000) { // Arbitrary large number to prevent overflow
        fprintf(stderr, "Array is too large!\n");
        return -1;
    }

    record_t* new_record = malloc(sizeof(record_t));
    if (!new_record) {
        fprintf(stderr, "Failed to allocate memory for new record\n");
        return -1;
    }
    new_record->value = rand() % KEY_RANGE_MAX;

    int* keys_array = atomic_load(&array->keys_array);
    long* offsets_array = atomic_load(&array->offsets_array);
    record_t** records_array = atomic_load(&array->records_array);

    if (!keys_array || !offsets_array || !records_array) {
        free(new_record);
        return -1;
    }

    keys_array[index] = key;
    offsets_array[index] = offset;
    records_array[index] = new_record;

    return 0;
}

record_t* get_record_by_key(lock_free_array_t* array, int key) {
    size_t index = 0;
    while (index < atomic_load(&array->size)) {
        int* keys_array = atomic_load(&array->keys_array);
        if (!keys_array) return NULL;

        if (keys_array[index] == key)
            return atomic_load(&array->records_array)[index];

        index++;
    }
    return NULL;
}

void free_lock_free_array(lock_free_array_t* array) {
    size_t i = 0;
    while (i < atomic_load(&array->size)) {
        record_t** records_array = atomic_load(&array->records_array);
        if (!records_array) break;

        free(records_array[i]);
        i++;
    }

    int* keys_array = atomic_load(&array->keys_array);
    long* offsets_array = atomic_load(&array->offsets_array);
    record_t** records_array = atomic_load(&array->records_array);

    free(keys_array);
    free(offsets_array);
    free(records_array);

    free(array);
}

int main() {
    lock_free_array_t* array = create_lock_free_array(INITIAL_RECORDS);
    if (!array) {
        fprintf(stderr, "Failed to initialize lock-free array\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 20; ++i) {
        add_record(array, rand() % KEY_RANGE_MAX, rand());
    }

    record_t* rec = get_record_by_key(array, 42); // Example key
    if (rec)
        printf("Record found with value: %d\n", rec->value);

    free_lock_free_array(array);
    return EXIT_SUCCESS;
}
```

### Key Points:
- **Thread Safety**: The code uses atomic operations to ensure thread safety when accessing and modifying shared arrays.
- **Memory Management**: Handles memory allocation failures gracefully, freeing allocated resources in case of errors.
- **Dynamic Growth**: Supports dynamic growth by incrementing the size atomically.
- **Efficient Record Retrieval**: Provides a function to retrieve records by key efficiently.
- **Error Handling**: Includes error messages for memory allocation failures and other potential issues.']

