import "openssl/evp.h"
#include "openssl/aes.h"

#define MAX_KEY_LEN 32 // Maximum key length (256 bits)
#define BLOCK_SIZE 16   // AES block size

// Error codes
typedef enum {
    SUCCESS = 0,
    INVALID_MODE,
    INVALID_KEY_LENGTH,
    MEMORY_ERROR,
    ENCRYPTION_ERROR,
    DECRYPTION_ERROR
} ErrorCode;

typedef struct {
    EVP_CIPHER_CTX *ctx;
    int mode; // Cipher mode
    unsigned char key[MAX_KEY_LEN];
    size_t key_len;
    unsigned char iv[BLOCK_SIZE]; // Initialization vector for CFB
} EncryptionContext;

// Function declarations
ErrorCode init_context(EncryptionContext *context, const unsigned char *key, size_t key_len, int mode);
void destroy_context(EncryptionContext *context);
ErrorCode encrypt(EncryptionContext *context, const unsigned char *plaintext, int plaintext_len, unsigned char *ciphertext);
ErrorCode decrypt(EncryptionContext *context, const unsigned char *ciphertext, int ciphertext_len, unsigned char *plaintext);

// Cipher modes
#define ECB_MODE 1
#define EDE_MODE 2
#define EDE3_MODE 3
#define CFB_MODE 4
#define NULL_MODE 5

// Initialize the encryption context
ErrorCode init_context(EncryptionContext *context, const unsigned char *key, size_t key_len, int mode) {
    if (key_len > MAX_KEY_LEN) return INVALID_KEY_LENGTH;

    context->ctx = EVP_CIPHER_CTX_new();
    if (!context->ctx) return MEMORY_ERROR;

    switch (mode) {
        case ECB_MODE:
            if (!EVP_EncryptInit_ex(context->ctx, EVP_aes_256_ecb(), NULL, key, NULL)) return ENCRYPTION_ERROR;
            break;
        case EDE_MODE: // Simplified example
        case EDE3_MODE: 
            if (!EVP_CipherInit_ex(context->ctx, EVP_des_cbc(), NULL, key, context->iv, mode == EDE_MODE ? 1 : 2)) return ENCRYPTION_ERROR;
            break;
        case CFB_MODE:
            if (!EVP_EncryptInit_ex(context->ctx, EVP_aes_256_cfb128(), NULL, key, context->iv)) return ENCRYPTION_ERROR;
            break;
        case NULL_MODE: // Null encryption
            return SUCCESS;
        default:
            return INVALID_MODE;
    }

    context->key_len = key_len;
    context->mode = mode;

    return SUCCESS;
}

// Destroy the encryption context
void destroy_context(EncryptionContext *context) {
    if (context->ctx) EVP_CIPHER_CTX_free(context->ctx);
}

// Encrypt data
ErrorCode encrypt(EncryptionContext *context, const unsigned char *plaintext, int plaintext_len, unsigned char *ciphertext) {
    int len;
    int ciphertext_len;

    if (!EVP_EncryptUpdate(context->ctx, ciphertext, &len, plaintext, plaintext_len)) return ENCRYPTION_ERROR;
    ciphertext_len = len;

    if (!EVP_EncryptFinal_ex(context->ctx, ciphertext + len, &len)) return ENCRYPTION_ERROR;
    ciphertext_len += len;

    return SUCCESS;
}

// Decrypt data
ErrorCode decrypt(EncryptionContext *context, const unsigned char *ciphertext, int ciphertext_len, unsigned char *plaintext) {
    int len;
    int plaintext_len;

    if (!EVP_DecryptUpdate(context->ctx, plaintext, &len, ciphertext, ciphertext_len)) return DECRYPTION_ERROR;
    plaintext_len = len;

    if (!EVP_DecryptFinal_ex(context->ctx, plaintext + len, &len)) return DECRYPTION_ERROR;
    plaintext_len += len;

    return SUCCESS;
}

// Key rotation (simplified)
void rotate_key(EncryptionContext *context, const unsigned char *new_key, size_t new_key_len) {
    if (new_key_len > MAX_KEY_LEN) return; // Error handling omitted for brevity

    EVP_CIPHER_CTX_free(context->ctx);
    init_context(context, new_key, new_key_len, context->mode); // Reinitialize with new key
}

int main() {
    EncryptionContext ctx;
    unsigned char key[] = "mysecretkey123456"; // 16 bytes for AES-128
    unsigned char plaintext[] = "This is a secret message.";
    unsigned char ciphertext[128];
    unsigned char decryptedtext[128];

    ErrorCode result = init_context(&ctx, key, sizeof(key), CFB_MODE);
    if (result != SUCCESS) {
        fprintf(stderr, "Failed to initialize context\n");
        return 1;
    }

    // Encrypt
    result = encrypt(&ctx, plaintext, strlen((char *)plaintext), ciphertext);
    if (result != SUCCESS) {
        fprintf(stderr, "Encryption failed\n");
        destroy_context(&ctx);
        return 1;
    }

    // Decrypt
    result = decrypt(&ctx, ciphertext, sizeof(ciphertext), decryptedtext);
    if (result != SUCCESS) {
        fprintf(stderr, "Decryption failed\n");
        destroy_context(&ctx);
        return 1;
    }

    printf("Original: %s\n", plaintext);
    printf("Decrypted: %s\n", decryptedtext);

    // Clean up
    destroy_context(&ctx);

    return 0;
}
```

