#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <uuid/uuid.h>

#define MAX_SIZE 1000

typedef enum {
    CELSIUS,
    FAHRENHEIT
} Unit;

typedef struct {
    double temperature;
    Unit unit;
    char quality[7]; // "unknown", "valid", etc.
} TemperatureReading;

typedef struct HashTableEntry {
    uuid_t key;
    TemperatureReading *reading;
    struct HashTableEntry *next;
} HashTableEntry;

typedef struct {
    HashTableEntry **table;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

void log_message(const char *message) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    printf("[%s] %s\n", timestamp, message);
}

unsigned long hash_uuid(uuid_t uuid) {
    unsigned long hash = 0;
    for (int i = 0; i < sizeof(uuid_t); ++i)
        hash ^= ((hash << 5) + uuid[i] + (hash >> 2));
    return hash;
}

HashTable *create_hash_table(size_t size) {
    if (size == 0 || size > MAX_SIZE) {
        log_message("Invalid or zero-sized request for hash table.");
        return NULL;
    }

    HashTable *ht = malloc(sizeof(HashTable));
    if (!ht) {
        log_message("Failed to allocate memory for hash table.");
        return NULL;
    }

    ht->table = calloc(size, sizeof(HashTableEntry *));
    if (!ht->table) {
        free(ht);
        log_message("Failed to allocate memory for hash table entries.");
        return NULL;
    }

    ht->size = size;
    pthread_mutex_init(&ht->lock, NULL);

    log_message("Hash table created successfully.");

    return ht;
}

int add_temperature_reading(HashTable *ht, uuid_t key, TemperatureReading *reading) {
    if (!ht || !key || !reading) {
        log_message("Invalid input for adding temperature reading.");
        return 0;
    }

    unsigned long index = hash_uuid(key) % ht->size;

    pthread_mutex_lock(&ht->lock);

    HashTableEntry *entry = malloc(sizeof(HashTableEntry));
    if (!entry) {
        log_message("Failed to allocate memory for new hash table entry.");
        pthread_mutex_unlock(&ht->lock);
        return 0;
    }

    uuid_copy(entry->key, key);
    entry->reading = reading;
    entry->next = ht->table[index];
    ht->table[index] = entry;

    pthread_mutex_unlock(&ht->lock);

    log_message("Temperature reading added to hash table.");

    return 1;
}

void free_hash_table(HashTable *ht) {
    if (!ht) return;

    for (size_t i = 0; i < ht->size; ++i) {
        HashTableEntry *entry = ht->table[i];
        while (entry) {
            HashTableEntry *temp = entry;
            entry = entry->next;
            free(temp);
        }
    }

    free(ht->table);
    pthread_mutex_destroy(&ht->lock);
    free(ht);

    log_message("Hash table freed successfully.");
}

void initialize_temperature_reading(TemperatureReading *reading) {
    if (!reading) return;

    reading->temperature = 0.0;
    reading->unit = CELSIUS;
    strcpy(reading->quality, "unknown");
}

TemperatureCollection *initialize_temperature_collection(size_t size) {
    if (size == 0 || size > MAX_SIZE) {
        log_message("Invalid or zero-sized request for temperature collection.");
        return NULL;
    }

    TemperatureCollection *tc = malloc(sizeof(TemperatureCollection));
    if (!tc) {
        log_message("Failed to allocate memory for temperature collection.");
        return NULL;
    }

    tc->readings = malloc(size * sizeof(double));
    if (!tc->readings) {
        free(tc);
        log_message("Failed to allocate memory for temperature readings array.");
        return NULL;
    }

    tc->units = malloc(size * sizeof(char *));
    if (!tc->units) {
        free(tc->readings);
        free(tc);
        log_message("Failed to allocate memory for units strings.");
        return NULL;
    }

    tc->structures = malloc(size * sizeof(TemperatureReading));
    if (!tc->structures) {
        for (size_t i = 0; i < size; ++i)
            free(tc->units[i]);
        free(tc->units);
        free(tc->readings);
        free(tc);
        log_message("Failed to allocate memory for temperature reading structures.");
        return NULL;
    }

    tc->hash_table = create_hash_table(size);
    if (!tc->hash_table) {
        for (size_t i = 0; i < size; ++i)
            free(tc->structures[i].quality); // Assuming quality was dynamically allocated
        free(tc->structures);
        for (size_t i = 0; i < size; ++i)
            free(tc->units[i]);
        free(tc->units);
        free(tc->readings);
        free(tc);
        log_message("Failed to create hash table.");
        return NULL;
    }

    pthread_mutex_init(&tc->lock, NULL);

    for (size_t i = 0; i < size; ++i) {
        tc->readings[i] = 0.0;
        tc->units[i] = malloc(8); // Enough for "Celsius" or "Fahrenheit"
        if (!tc->units[i]) {
            log_message("Failed to allocate memory for unit string.");
            // Handle partial allocation cleanup
            free_temperature_collection(tc);
            return NULL;
        }
        strcpy(tc->units[i], i % 2 == 0 ? "Celsius" : "Fahrenheit");

        initialize_temperature_reading(&tc->structures[i]);
    }

    log_message("Temperature collection initialized successfully.");

    return tc;
}

void free_temperature_collection(TemperatureCollection *tc) {
    if (!tc) return;

    for (size_t i = 0; i < tc->readings_count; ++i)
        free(tc->units[i]);

    free(tc->units);
    free(tc->structures);
    free(tc->readings);

    free_hash_table(tc->hash_table);
    pthread_mutex_destroy(&tc->lock);

    free(tc);

    log_message("Temperature collection freed successfully.");
}

typedef struct {
    double *readings;
    char **units;
    TemperatureReading *structures;
    size_t readings_count;
    HashTable *hash_table;
    pthread_mutex_t lock;
} TemperatureCollection;

int main() {
    // Example usage
    uuid_t key;
    uuid_generate(key);

    size_t collection_size = 10;
    TemperatureCollection *tc = initialize_temperature_collection(collection_size);

    if (tc) {
        TemperatureReading reading;
        reading.temperature = 25.5;
        reading.unit = CELSIUS;
        strcpy(reading.quality, "valid");

        add_temperature_reading(tc->hash_table, key, &reading);

        free_temperature_collection(tc);
    }

    return 0;
}
