    dm->records = (record*)((char*)dm->keys + num_elements * sizeof(int));
    dm->metadatas = (metadata**)((char*)dm->records + num_elements * sizeof(record));
    dm->comp_metadatas = (compressed_metadata**)((char*)dm->metadatas
                                                  + num_elements * sizeof(void*));

    return dm;
}

void free_data_manager(data_manager *dm) {
    if (!dm) return;

    pthread_mutex_destroy(&dm->lock);
    free(dm);
}

int serialize_data(const data_manager *dm, const char *filename) {
    if (!dm || !filename) return -1;

    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    pthread_mutex_lock(&dm->lock);

    size_t num_elements = sizeof(dm->offsets) / sizeof(dm->offsets[0]);
    fwrite(dm->offsets, sizeof(long), num_elements, file);
    fwrite(dm->keys, sizeof(int), num_elements, file);
    fwrite(dm->records, sizeof(record), num_elements, file);

    for (size_t i = 0; i < num_elements; ++i) {
        if (dm->metadatas[i]) {
            fwrite(&dm->metadatas[i]->size, sizeof(size_t), 1, file);
            fwrite(dm->metadatas[i]->data, dm->metadatas[i]->size, 1, file);
