// Global variables for synchronization and logging
pthread_mutex_t record_lock = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file;

void log_message(const char *message) {
    pthread_mutex_lock(&record_lock);
    fprintf(log_file, "%s\n", message);
    fflush(log_file);  // Ensure the log is flushed immediately
    pthread_mutex_unlock(&record_lock);
}

// Function to initialize records and manage dynamic memory allocation
int initialize_records(int max_size, int min_value, int max_value) {
    long *offsets = NULL;
    int *keys = NULL;
    Record **records = NULL;

    // Open log file for remote server logging (for simplicity, we're using a local file)
    log_file = fopen("system_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        return -1;
    }

    log_message("Starting record initialization");

    // Allocate memory for offsets and keys
    offsets = (long *)malloc(max_size * sizeof(long));
    keys = (int *)malloc(max_size * sizeof(int));
    if (!offsets || !keys) {
        log_message("Memory allocation failed");
        return -1;
    }

    records = (Record **)malloc(max_size * sizeof(Record *));
    if (!records) {
        free(offsets);
        free(keys);
        log_message("Memory allocation for records failed");
        return -1;
    }

    // Initialize records with default values
    for (int i = 0; i < max_size; ++i) {
        Record *record = (Record *)malloc(sizeof(Record));
        if (!record) {
            free(offsets);
            free(keys);
            while (--i >= 0) free(records[i]);
            free(records);
            log_message("Memory allocation for a record failed");
            return -1;
        }

        pthread_mutex_lock(&record_lock);
        record->integer_value = rand() % (max_value - min_value + 1) + min_value;
        record->timestamp = time(NULL);
        record->status_flag = 0; // Default status
        record->metadata_tags = NULL; // Initialize metadata tags pointer to NULL
        records[i] = record;

        char log_entry[100];
        snprintf(log_entry, sizeof(log_entry), "Initialized record %d with value %d at time %ld", i, record->integer_value, (long)record->timestamp);
        log_message(log_entry);

        pthread_mutex_unlock(&record_lock);
    }

    // Clean up resources if needed
    pthread_mutex_destroy(&record_lock);
    fclose(log_file);

    return 0; // Success
}

// Example usage of the function
int main() {
    int result = initialize_records(100, 10, 50); // Initialize with max_size=100, range for integer values from 10 to 50
    if (result != 0) {
        fprintf(stderr, "Failed to initialize records.\n");
    }
    return 0;
}
