// Callback function type definition for string validation
typedef int (*ValidationCallback)(const char*);

int processString(const char* input, int sizeLimit, ValidationCallback validate) {
    if (input == NULL || validate == NULL) return NULL;
    if (sizeLimit < 0) return NULL;

    // Validate the string using the provided callback function
    if (!validate(input)) return NULL;

    // Check if appending a '/' would exceed the size limit
    int inputLength = strlen(input);
    if (inputLength + 1 > sizeLimit) return NULL;

    // Allocate memory for the modified string with an additional character for '/'
    char* result = malloc(sizeLimit + 1);
    if (result == NULL) return NULL; 

    strcpy(result, input);
    strcat(result, "/");

    return result;
}

// Example validation function
int exampleValidate(const char* str) {
    // Simple constraint: Allow only alphanumeric characters and underscores
    while (*str) {
        if (!((*str >= 'a' && *str <= 'z') || 
              (*str >= 'A' && *str <= 'Z') ||
              (*str >= '0' && *str <= '9') ||
              (*str == '_'))) return 0;
        str++;
    }
    return 1;
}
