function traverseDOM(node, filterFunc, includeNonElementNodes = false, threshold = 1000) {
    const results = [];
    let callCount = 0;

    function recurse(currentNode, remainingThreshold) {
        if (remainingThreshold <= 0) return;

        // Check if node matches the filtering criteria
        if ((currentNode.nodeType === Node.ELEMENT_NODE || includeNonElementNodes) &&
            filterFunc(currentNode)) {
            results.push(currentNode);
        }

        callCount++;
        let children = currentNode.childNodes;

        for (let child of children) {
            recurse(child, remainingThreshold - 1);
        }
    }

    if (node && node.nodeType === Node.ELEMENT_NODE) {
        recurse(node, threshold);
    }

    return results;
}
