<?php

// Function to set environment variables from a .env file
function loadEnv($filePath) {
    if (!file_exists($filePath)) {
        throw new Exception("Environment configuration file not found.");
    }

    $lines = file($filePath, FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES);
    foreach ($lines as $line) {
        if (strpos(trim($line), '#') === 0 || trim($line) === '') continue;

        list($key, $value) = explode('=', $line, 2);
        putenv(sprintf('%s=%s', trim($key), trim($value)));
    }
}

// Main script execution
try {
    // Set environment variables from .env file
    loadEnv(__DIR__ . '/.env');

    // Define and initialize the autoloader
    if (!class_exists('Composer\Autoload\ClassLoader')) {
        throw new Exception("Composer Autoloader not found.");
    }

    $vendorDir = getenv('VENDOR_DIR') ?: __DIR__ . '/vendor';
    require_once $vendorDir . '/autoload.php';

    // Load application configuration
    $configFile = getenv('CONFIG_FILE');
    if (!$configFile || !file_exists($configFile)) {
        throw new Exception("Configuration file path is invalid.");
    }

    $config = include $configFile;

