```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
    int *key_ptr;
} Record;

typedef struct {
    time_t last_accessed_time;
    size_t reference_count;
} Metadata;

typedef struct {
    int key;
    Record record;
    Metadata metadata;
} Entry;

typedef struct {
    Entry *entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    long long total_value;
    int max_value;
    int min_value;
} DynamicMemoryManager;

DynamicMemoryManager* create_manager(size_t initial_capacity) {
    DynamicMemoryManager *manager = (DynamicMemoryManager*)malloc(sizeof(DynamicMemoryManager));
    manager->entries = (Entry *)malloc(initial_capacity * sizeof(Entry));
    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    manager->total_value = 0;
    manager->max_value = INT_MIN;
    manager->min_value = INT_MAX;
    return manager;
}

void resize_manager(DynamicMemoryManager *manager) {
    size_t new_capacity = manager->capacity * 2;
    Entry *new_entries = (Entry *)realloc(manager->entries, new_capacity * sizeof(Entry));
    if (new_entries) {
        manager->entries = new_entries;
        manager->capacity = new_capacity;
    }
}

void initialize_random() {
    srand(time(NULL));
}

int random_value(DynamicMemoryManager *manager) {
    if (manager->count == 0)
        return rand() % 100; // Default range

    int avg_value = (int)(manager->total_value / manager->count);
    int range_min = avg_value - 50;
    int range_max = avg_value + 50;

    if (range_min < INT_MIN) range_min = INT_MIN;
    if (range_max > INT_MAX) range_max = INT_MAX;

    return rand() % (range_max - range_min + 1) + range_min;
}

void add_record(DynamicMemoryManager *manager, int key) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity)
        resize_manager(manager);

    Entry *entry = &manager->entries[manager->count++];
    entry->key = key;
    entry->record.value = random_value(manager);
    entry->record.key_ptr = &entry->key;

    time(&entry->metadata.last_accessed_time);
    entry->metadata.reference_count = 1;

    manager->total_value += entry->record.value;
    if (entry->record.value > manager->max_value)
        manager->max_value = entry->record.value;
    if (entry->record.value < manager->min_value)
        manager->min_value = entry->record.value;

    pthread_mutex_unlock(&manager->lock);
}

void release_manager(DynamicMemoryManager *manager) {
    free(manager->entries);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

// Example usage
int main() {
    initialize_random();
    DynamicMemoryManager *manager = create_manager(10);

    for (int i = 0; i < 20; ++i)
        add_record(manager, i);

    release_manager(manager);
    return 0;
}
```

