#include <stdio.h>
#include <stdlib.h>
import threading
from typing import Optional

# Structure for network connection metadata
typedef struct {
    char ip_address[16];  // IPv4 Address
    int port_number;
    int status;           // Connection status (e.g., open, closed)
    unsigned long packets_sent;
    unsigned long packets_received;
    double average_latency;
} Connection;

// Connection pool structure
typedef struct {
    Connection *connections;
    size_t capacity;
    size_t count;
    threading.Lock lock;
} ConnectionPool;

// Initialize the connection pool
void init_connection_pool(ConnectionPool *pool, size_t initial_capacity) {
    pool->capacity = initial_capacity;
    pool->count = 0;
    pool->connections = (Connection *)malloc(sizeof(Connection) * initial_capacity);
    threading.Lock_init(&pool->lock);
}

// Resize the connection pool if necessary
void ensure_capacity(ConnectionPool *pool, size_t min_capacity) {
    if (min_capacity > pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        while (new_capacity < min_capacity) {
            new_capacity *= 2;
        }
        Connection *new_connections = (Connection *)realloc(pool->connections, sizeof(Connection) * new_capacity);
        if (!new_connections) {
            // Handle memory allocation failure
            fprintf(stderr, "Memory allocation failed!\n");
            exit(EXIT_FAILURE);
        }
        pool->connections = new_connections;
        pool->capacity = new_capacity;
    }
}

// Add a new connection to the pool
void add_connection(ConnectionPool *pool, const char *ip_address, int port_number) {
    threading.Lock_lock(&pool->lock);

    ensure_capacity(pool, pool->count + 1);

    Connection *conn = &pool->connections[pool->count++];
    snprintf(conn->ip_address, sizeof(conn->ip_address), "%s", ip_address);
    conn->port_number = port_number;
    conn->status = 0; // Assume status 'open' is represented by 0
    conn->packets_sent = 0;
    conn->packets_received = 0;
    conn->average_latency = 0.0;

    threading.Lock_unlock(&pool->lock);
}

// Update connection data in a thread-safe manner
void update_connection(ConnectionPool *pool, size_t index, int status,
                       unsigned long packets_sent, unsigned long packets_received,
                       double average_latency) {
    if (index >= pool->count) return;

    threading.Lock_lock(&pool->lock);

    Connection *conn = &pool->connections[index];
    conn->status = status;

    // Prevent overflow
    if ((ULONG_MAX - conn->packets_sent) < packets_sent ||
        (ULONG_MAX - conn->packets_received) < packets_received) {
        fprintf(stderr, "Integer overflow detected!\n");
        exit(EXIT_FAILURE);
    }

    conn->packets_sent += packets_sent;
    conn->packets_received += packets_received;
    conn->average_latency = average_latency;

    threading.Lock_unlock(&pool->lock);
}

// Serialize connection pool to a file
void serialize_connection_pool(ConnectionPool *pool, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    threading.Lock_lock(&pool->lock);

    fwrite(&pool->capacity, sizeof(size_t), 1, file);
    fwrite(pool->connections, sizeof(Connection), pool->count, file);

    threading.Lock_unlock(&pool->lock);

    fclose(file);
}

// Deserialize connection pool from a file
void deserialize_connection_pool(ConnectionPool *pool, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    size_t new_capacity;
    fread(&new_capacity, sizeof(size_t), 1, file);

    ensure_capacity(pool, new_capacity);

    threading.Lock_lock(&pool->lock);

    pool->count = new_capacity;
    fread(pool->connections, sizeof(Connection), new_capacity, file);

    threading.Lock_unlock(&pool->lock);

    fclose(file);
}

// Clean up the connection pool
void free_connection_pool(ConnectionPool *pool) {
    if (pool->connections) {
        free(pool->connections);
    }
    threading.Lock_destroy(&pool->lock);
}
