```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>
#include <errno.h>
#include <inttypes.h>

#define MAX_RECORDS 1000
#define KEY_ARRAY_SIZE 500

typedef struct {
    int value;
    int *key_ref;
    long *offset_ref;
} Record;

typedef struct {
    Record *records;
    size_t count;
    int64_t total_sum;
    pthread_mutex_t lock;
} SharedMemoryRegion;

void log_error(const char *message) {
    perror(message);
}

int initialize_shared_memory(SharedMemoryRegion *shm, int keys[], long offsets[], size_t num_records) {
    if (num_records > MAX_RECORDS) {
        log_error("Exceeded maximum number of records");
        return -1;
    }

    pthread_mutex_init(&shm->lock, NULL);

    shm->records = malloc(num_records * sizeof(Record));
    if (!shm->records) {
        log_error("Failed to allocate memory for records");
        return -1;
    }

    shm->count = num_records;
    shm->total_sum = 0;

    srand(time(NULL));

    pthread_mutex_lock(&shm->lock);
    int64_t cumulative_sum = 0;

    for (size_t i = 0; i < num_records; ++i) {
        int range_min = 1, range_max = 100;
        if (cumulative_sum > INT_MAX / 2) {
            range_min = range_max / 2 + 1;
        }

        int value = rand() % (range_max - range_min + 1) + range_min;

        shm->records[i].value = value;
        shm->records[i].key_ref = &keys[i % KEY_ARRAY_SIZE];
        shm->records[i].offset_ref = &offsets[i];

        cumulative_sum += value;
        if (__builtin_add_overflow(cumulative_sum, 0, NULL)) {
            log_error("Integer overflow detected");
            pthread_mutex_unlock(&shm->lock);
            free(shm->records);
            pthread_mutex_destroy(&shm->lock);
            return -1;
        }

        shm->total_sum += value;
    }

    pthread_mutex_unlock(&shm->lock);

    return 0;
}

void cleanup_shared_memory(SharedMemoryRegion *shm) {
    if (shm->records) {
        free(shm->records);
        shm->records = NULL;
    }
    pthread_mutex_destroy(&shm->lock);
}
```

### Key Points:

- **Thread Safety**: Uses a mutex to ensure thread safety during updates.
- **Error Handling**: Logs errors using `perror`.
- **Integer Overflow**: Checks for overflow using `__builtin_add_overflow`.
- **Memory Management**: Allocates memory once and reuses it, minimizing fragmentation.
- **Range Adjustment**: Dynamically adjusts the range based on cumulative sum to prevent overflow.
- **Limitations**: Handles predefined limits on records and keys.']

