#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define MAX_RESOURCES 1000

typedef struct {
    char type[50];
    size_t size;
} ResourceType;

typedef struct Resource {
    time_t timestamp;
    int status_flag; // 1 for active, 0 for inactive
    ResourceType resource_info;
    struct Resource* next;
} Resource;

typedef struct {
    Resource** resources;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} ResourceManager;

ResourceManager* create_resource_manager() {
    ResourceManager* manager = (ResourceManager*)malloc(sizeof(ResourceManager));
    if (!manager) return NULL;

    manager->resources = (Resource**)calloc(INITIAL_CAPACITY, sizeof(Resource*));
    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void resize_resources(ResourceManager* manager) {
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        Resource** new_resources = (Resource**)realloc(manager->resources, new_capacity * sizeof(Resource*));
        if (!new_resources) return;

        for (size_t i = manager->count; i < new_capacity; ++i) {
            new_resources[i] = NULL;
        }

        manager->resources = new_resources;
        manager->capacity = new_capacity;
    }
}

void add_resource(ResourceManager* manager, const char* type, size_t size) {
    pthread_mutex_lock(&manager->lock);

    resize_resources(manager);

    Resource* resource = (Resource*)malloc(sizeof(Resource));
    if (!resource) {
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    resource->timestamp = time(NULL);
    resource->status_flag = 1;
    strncpy(resource->resource_info.type, type, sizeof(resource->resource_info.type) - 1);
    resource->resource_info.size = size;
    resource->next = NULL;

    manager->resources[manager->count++] = resource;

    pthread_mutex_unlock(&manager->lock);
}

void serialize_resources(const ResourceManager* manager, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&manager->count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < manager->count; ++i) {
        Resource* resource = manager->resources[i];
        fwrite(resource, sizeof(Resource), 1, file);
    }

    fclose(file);
}

void deserialize_resources(ResourceManager* manager, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    resize_resources(manager); // Ensure capacity is sufficient

    for (size_t i = 0; i < count && i < MAX_RESOURCES; ++i) {
        Resource* resource = (Resource*)malloc(sizeof(Resource));
        if (!resource) continue;

        fread(resource, sizeof(Resource), 1, file);
        manager->resources[i] = resource;
        manager->count++;
    }

    fclose(file);
}

void update_resource(ResourceManager* manager, size_t index, const char* type, size_t size) {
    pthread_mutex_lock(&manager->lock);

    if (index < manager->count) {
        Resource* resource = manager->resources[index];
        strncpy(resource->resource_info.type, type, sizeof(resource->resource_info.type) - 1);
        resource->resource_info.size = size;
        resource->timestamp = time(NULL);
    }

    pthread_mutex_unlock(&manager->lock);
}

void delete_resource(ResourceManager* manager, size_t index) {
    pthread_mutex_lock(&manager->lock);

    if (index < manager->count) {
        Resource* resource = manager->resources[index];
        free(resource);
        memmove(&manager->resources[index], &manager->resources[index + 1], 
                (manager->count - index - 1) * sizeof(Resource*));
        manager->count--;
    }

    pthread_mutex_unlock(&manager->lock);
}

void http_put_update(ResourceManager* manager, size_t id, const char* type, size_t size) {
    // Simulated HTTP PUT method
    update_resource(manager, id, type, size);
}

void http_delete_resource(ResourceManager* manager, size_t id) {
    // Simulated HTTP DELETE method
    delete_resource(manager, id);
}

int main() {
    ResourceManager* manager = create_resource_manager();

    add_resource(manager, "CPU", 1024);
    serialize_resources(manager, "resources.dat");
    deserialize_resources(manager, "resources.dat");

    http_put_update(manager, 0, "GPU", 2048);
    http_delete_resource(manager, 1);

    for (size_t i = 0; i < manager->count; ++i) {
        Resource* resource = manager->resources[i];
        printf("Resource %zu: Type=%s, Size=%zu, Timestamp=%ld\n",
               i, resource->resource_info.type, resource->resource_info.size,
               resource->timestamp);
    }

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->resources[i]);
    }
    free(manager->resources);
    pthread_mutex_destroy(&manager->lock);
    free(manager);

    return 0;
}
```

This code provides a basic implementation of the described system, handling resource management with dynamic resizing, serialization, and concurrent access. The HTTP functions simulate updates and deletions in a thread-safe manner.']

