// Function to process filenames and metadata
void process_filenames_and_metadata(int *ids, time_t *timestamps, int id_count) {
    char buffer[256];
    char new_filename[512];

    for (int i = 0; i < id_count; ++i) {
        // Read filename from standard input or remote source
        if (!fgets(buffer, sizeof(buffer), stdin)) {
            perror("Failed to read filename");
            continue;
        }

        size_t len = strlen(buffer);
        if (len == 0 || buffer[len - 1] == '\n') {
            buffer[--len] = '\0';
        }

        // Determine new file extension and number of digits based on filename characters
        int num_digits = 0, has_upper = 0, has_lower = 0, has_digit = 0, has_special = 0;

        for (size_t j = 0; j < len; ++j) {
            if (isupper(buffer[j])) has_upper = 1;
            else if (islower(buffer[j])) has_lower = 1;
            else if (isdigit(buffer[j])) has_digit = 1;
            else if (!ispunct(buffer[j]) && !isspace(buffer[j])) has_special = 1;
        }

        num_digits = has_digit ? strlen(strrchr(buffer, '0')) : 3;

        // Construct new filename
        sprintf(new_filename, "%s_%d%s", buffer, ids[i], has_upper ? ".UPPER" : ".lower");

        // Append digits to the filename
        char digit_str[12];
        snprintf(digit_str, sizeof(digit_str), "_%0*d", num_digits, timestamps[i]);
        strcat(new_filename, digit_str);

        printf("Updated Filename: %s\n", new_filename);
    }
}

int main() {
    size_t packet_count = 0;
    Packet *packets = init_packet_array(&packet_count, MAX_PACKETS);

    int id_count = 5; // Example ID count
    int ids[id_count] = {1, 2, 3, 4, 5};
    time_t timestamps[id_count];
    for (int i = 0; i < id_count; ++i) {
        timestamps[i] = time(NULL); // Simulate current timestamp
