// Main function to process the sensor data stream
int processSensorDataStream(const char* configSource) {
    // Load configuration settings
    char** sources = NULL;
    int sourceCount = 0;
    if (loadConfiguration(configSource, &sources, &sourceCount) != SUCCESS) {
        fprintf(stderr, "Failed to load configuration.\n");
        return CONFIG_LOAD_ERROR;
    }

    bool* isConnectedArray = malloc(sourceCount * sizeof(bool));
    for (int i = 0; i < sourceCount; ++i) {
        if (!establishConnection(sources[i], &isConnectedArray[i])) {
            fprintf(stderr, "Failed to connect to source: %s\n", sources[i]);
            closeConnections(sources, sourceCount);
            free(isConnectedArray);
            return CONNECTION_ERROR;
        }
    }

    // Data processing loop
    int cacheSize = 100;  // Adjust as needed based on expected data volume
    SensorData* dataCache = malloc(cacheSize * sizeof(SensorData));
    if (!dataCache) {
        fprintf(stderr, "Out of memory error.\n");
        closeConnections(sources, sourceCount);
        free(isConnectedArray);
        return DATA_PROCESSING_ERROR;
    }

    int currentCacheSize = 0;

    while (true) { // Replace with a condition to break based on application logic
        for (int i = 0; i < sourceCount; ++i) {
            if (!isConnectedArray[i]) continue;

            SensorData* newData = receiveData(isConnectedArray[i], &dataCache[currentCacheSize]);
            if (!newData) {
                fprintf(stderr, "Error receiving data from source: %s\n", sources[i]);
                isConnectedArray[i] = false;  // Attempt to reconnect later
                continue;
            }

            // Validate and process the received data
            int processDataResult = processData(newData, currentCacheSize + 1);
            if (processDataResult != SUCCESS) {
                fprintf(stderr, "Error processing data from source: %s\n", sources[i]);
                isConnectedArray[i] = false;  // Attempt to reconnect later
                continue;
            }

            // Cache the processed data
            dataCache[currentCacheSize++] = *newData;

            if (currentCacheSize >= cacheSize) {
                reportSummary(currentCacheSize);  // Report periodically or based on logic

                // Reset the cache after reporting
                currentCacheSize = 0;
            }
        }

        // Handle reconnection and cleanup logic as necessary
    }

    closeConnections(sources, sourceCount);
    free(isConnectedArray);
    free(dataCache);

    return SUCCESS;
}

