#define INITIAL_SIZE 1024
#define MAX_RECORDS 1000000
#define MEMORY_THRESHOLD_MB 2048

// Memory pool structure for records and keys
typedef struct {
    void *pool;
    size_t block_size;
    size_t total_blocks;
    size_t used_blocks;
} memory_pool_t;

void* allocate_from_pool(memory_pool_t *mp) {
    if (mp->used_blocks >= mp->total_blocks) {
        // Reallocate with increased size
        size_t new_total = mp->total_blocks + INITIAL_SIZE;
        void *new_pool = realloc(mp->pool, new_total * mp->block_size);
        if (!new_pool) return NULL;  // Handle allocation failure

        mp->pool = new_pool;
        mp->total_blocks = new_total;
    }
    mp->used_blocks++;
    return (char*)mp->pool + ((mp->used_blocks - 1) * mp->block_size);
}

void deallocate_from_pool(memory_pool_t *mp, void* ptr) {
    // Freeing is implicit; manage usage count instead
    if (ptr >= mp->pool && ptr < (char*)mp->pool + (mp->total_blocks * mp->block_size)) {
        mp->used_blocks--;
    }
}

memory_pool_t record_pool;
memory_pool_t key_pool;

void initialize_memory_pools() {
    record_pool.block_size = sizeof(record);
    key_pool.block_size = sizeof(int);

    record_pool.pool = malloc(INITIAL_SIZE * record_pool.block_size);
    key_pool.pool = malloc(INITIAL_SIZE * key_pool.block_size);

    if (!record_pool.pool || !key_pool.pool) {
        fprintf(stderr, "Failed to allocate memory pools.\n");
        exit(EXIT_FAILURE);
    }

    record_pool.total_blocks = INITIAL_SIZE;
    key_pool.total_blocks = INITIAL_SIZE;

    record_pool.used_blocks = 0;
    key_pool.used_blocks = 0;
}

void free_memory_pools() {
    free(record_pool.pool);
    free(key_pool.pool);
}

