#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <uuid/uuid.h>

#define MAX_STRING_LENGTH 256

typedef struct {
    double value;
    char unit; // 'C' for Celsius, 'F' for Fahrenheit
    char quality[10];
} TemperatureReading;

typedef struct {
    float value;
    time_t timestamp;
} HumidityReading;

// Simple hash table entry structure
typedef struct HashTableEntry {
    uuid_t key;
    void *value;
    struct HashTableEntry *next;
} HashTableEntry;

// Simplified hash table with chaining for collision resolution
typedef struct {
    int size;
    HashTableEntry **buckets;
    pthread_mutex_t lock;
} HashTable;

double* create_double_array(size_t max_size) {
    double *array = (double*)malloc(max_size * sizeof(double));
    if (!array) {
        fprintf(stderr, "Memory allocation failed for doubles\n");
        return NULL;
    }
    for (size_t i = 0; i < max_size; ++i) {
        array[i] = (double)(rand() % 100); // Random double between 0 and 99
    }
    return array;
}

char** create_char_array(size_t max_size) {
    char **array = (char**)malloc(max_size * sizeof(char*));
    if (!array) {
        fprintf(stderr, "Memory allocation failed for char pointers\n");
        free(array);
        return NULL;
    }

    for (size_t i = 0; i < max_size; ++i) {
        array[i] = (char*)malloc(MAX_STRING_LENGTH * sizeof(char));
        if (!array[i]) {
            fprintf(stderr, "Memory allocation failed for char array\n");
            while (--i >= 0) free(array[i]);
            free(array);
            return NULL;
        }
        snprintf(array[i], MAX_STRING_LENGTH, "String %zu", i); // Example string
    }

    return array;
}

TemperatureReading* create_temperature_array(size_t max_size) {
    TemperatureReading *array = (TemperatureReading*)malloc(max_size * sizeof(TemperatureReading));
    if (!array) {
        fprintf(stderr, "Memory allocation failed for temperature readings\n");
        return NULL;
    }

    for (size_t i = 0; i < max_size; ++i) {
        array[i].value = (double)(rand() % 100); // Random temp between 0 and 99
        array[i].unit = (char)((rand() % 2) ? 'C' : 'F'); // Randomly choose unit
        strcpy(array[i].quality, "unknown");
    }

    return array;
}

HumidityReading* create_humidity_array(size_t max_size) {
    HumidityReading *array = (HumidityReading*)malloc(max_size * sizeof(HumidityReading));
    if (!array) {
        fprintf(stderr, "Memory allocation failed for humidity readings\n");
        return NULL;
    }

    for (size_t i = 0; i < max_size; ++i) {
        array[i].value = (float)(rand() % 100); // Random humidity between 0 and 99
        array[i].timestamp = time(NULL); // Current time as example timestamp
    }

    return array;
}

HashTable* create_hash_table(size_t size) {
    HashTable *table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) {
        fprintf(stderr, "Memory allocation failed for hash table\n");
        return NULL;
    }

    table->size = size;
    table->buckets = (HashTableEntry**)calloc(table->size, sizeof(HashTableEntry*));
    if (!table->buckets) {
        fprintf(stderr, "Memory allocation failed for hash table buckets\n");
        free(table);
        return NULL;
    }

    pthread_mutex_init(&table->lock, NULL);

    return table;
}

void insert_into_hash_table(HashTable *table, void *value, uuid_t key) {
    size_t index = uuid_compare(key, UUID_ZERO) % table->size; // Simplistic hash function
    HashTableEntry *entry = (HashTableEntry*)malloc(sizeof(HashTableEntry));

    if (!entry) {
        fprintf(stderr, "Memory allocation failed for hash table entry\n");
        return;
    }

    memcpy(entry->key, key, sizeof(uuid_t));
    entry->value = value;
    entry->next = NULL;

    pthread_mutex_lock(&table->lock);
    if (table->buckets[index]) {
        HashTableEntry *current = table->buckets[index];
        while (current->next) current = current->next;
        current->next = entry;
    } else {
        table->buckets[index] = entry;
    }
    pthread_mutex_unlock(&table->lock);
}

int initialize_data_structures(size_t max_size, double **double_array, char ***char_array,
                               TemperatureReading **temperature_array, HumidityReading **humidity_array,
                               HashTable **hash_table) {

    if (max_size <= 0 || !double_array || !char_array || !temperature_array || !humidity_array || !hash_table) {
        fprintf(stderr, "Invalid parameters for initialization\n");
        return -1;
    }

    *double_array = create_double_array(max_size);
    if (!*double_array) return -1;

    *char_array = create_char_array(max_size);
    if (!*char_array) {
        free(*double_array);
        return -1;
    }

    *temperature_array = create_temperature_array(max_size);
    if (!*temperature_array) {
        for (size_t i = 0; i < max_size; ++i) free((*char_array)[i]);
        free(*char_array);
        free(*double_array);
        return -1;
    }

    *humidity_array = create_humidity_array(max_size);
    if (!*humidity_array) {
        free(*temperature_array);
        for (size_t i = 0; i < max_size; ++i) free((*char_array)[i]);
        free(*char_array);
        free(*double_array);
        return -1;
    }

    *hash_table = create_hash_table(max_size);
    if (!*hash_table) {
        free(*humidity_array);
        free(*temperature_array);
        for (size_t i = 0; i < max_size; ++i) free((*char_array)[i]);
        free(*char_array);
        free(*double_array);
        return -1;
    }

    // Populate hash table with temperature readings
    for (size_t i = 0; i < max_size; ++i) {
        uuid_t key;
        uuid_generate(key);
        insert_into_hash_table(*hash_table, &((*temperature_array)[i]), key);
    }

    // Populate hash table with humidity readings
    for (size_t i = 0; i < max_size; ++i) {
        uuid_t key;
        uuid_generate(key);
        insert_into_hash_table(*hash_table, &((*humidity_array)[i]), key);
    }

    return 0; // Success
}

void free_resources(double *double_array, char **char_array, TemperatureReading *temperature_array,
                    HumidityReading *humidity_array, HashTable *hash_table) {

    if (char_array) {
        for (size_t i = 0; i < MAX_STRING_LENGTH && char_array[i]; ++i) {
            free(char_array[i]);
        }
        free(char_array);
    }

    if (double_array) free(double_array);

    if (temperature_array) free(temperature_array);

    if (humidity_array) free(humidity_array);

    if (hash_table) {
        for (size_t i = 0; i < hash_table->size; ++i) {
            HashTableEntry *entry = hash_table->buckets[i];
            while (entry) {
                HashTableEntry *temp = entry;
                entry = entry->next;
                free(temp);
            }
        }
        free(hash_table->buckets);
        pthread_mutex_destroy(&hash_table->lock);
        free(hash_table);
    }
}

int main() {
    size_t max_size = 1000; // Example max size
    double *double_array = NULL;
    char **char_array = NULL;
    TemperatureReading *temperature_array = NULL;
    HumidityReading *humidity_array = NULL;
    HashTable *hash_table = NULL;

    if (initialize_data_structures(max_size, &double_array, &char_array, &temperature_array,
                                   &humidity_array, &hash_table) == 0) {
        printf("Data structures initialized successfully.\n");

        // Example operations would go here

        free_resources(double_array, char_array, temperature_array, humidity_array, hash_table);
    } else {
        fprintf(stderr, "Failed to initialize data structures\n");
    }

    return 0;
}
