int random_int_range(int min, int max) {
    return rand() % (max - min + 1) + min;
}

void* memory_manager(void *arg) {
    size_t used_memory = *(size_t*)arg;
    size_t threshold = getenv("MEMORY_THRESHOLD") ? atol(getenv("MEMORY_THRESHOLD")) : SIZE_MAX;

    while (1) {
        check_memory_threshold(used_memory, threshold);
        usleep(1000000); // Check every second
    }

    return NULL;
}

void initialize_arrays(long *offsets, int *keys, record *records, size_t num_records, const char* seed_str) {
    pthread_t monitor_thread;
    size_t used_memory = sizeof(*offsets) * num_records + sizeof(*keys) * num_records + sizeof(record) * num_records;

    if (seed_str) {
        srand(atoi(seed_str));
    } else {
        srand(time(NULL));
    }

    int policy_min_keys = getenv("MIN_KEYS") ? atoi(getenv("MIN_KEYS")) : 10;
    int policy_max_keys = getenv("MAX_KEYS") ? atoi(getenv("MAX_KEYS")) : 100;

    if (policy_min_keys > policy_max_keys || num_records < policy_min_keys) {
        fprintf(stderr, "Invalid configuration for keys.\n");
        exit(EXIT_FAILURE);
    }

    pthread_create(&monitor_thread, NULL, memory_manager, &used_memory);

    int total_sum = 0;
    int range_start = 1;

    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = i * sizeof(record);
        keys[i] = rand() % 1000; // Example key generation

        int new_value = random_int_range(range_start, range_start + total_sum / (num_records - i));

        if ((total_sum + new_value < 0) || ((long long)total_sum + (long long)new_value < (long long)total_sum)) {
            fprintf(stderr, "Integer overflow detected!\n");
            exit(EXIT_FAILURE);
        }

        records[i].value = new_value;
        total_sum += new_value;

        used_memory += sizeof(record); // Update memory usage
    }

    pthread_join(monitor_thread, NULL);

    for (size_t i = 0; i < num_records; ++i) {
        if ((long long)records[i].value != keys[(int)(offsets[i] / sizeof(record)) % num_records]) {
            fprintf(stderr, "Data integrity check failed!\n");
            exit(EXIT_FAILURE);
        }
    }

    printf("Total sum of records: %d\n", total_sum);
}

void manage_memory(size_t num_records) {
    long *offsets = (long*)malloc(sizeof(long) * num_records);
    int *keys = (int*)malloc(sizeof(int) * num_records);
    record *records = (record*)malloc(sizeof(record) * num_records);

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed!\n");
        exit(EXIT_FAILURE);
    }

    initialize_arrays(offsets, keys, records, num_records, getenv("RANDOM_SEED"));

    free(offsets);
    free(keys);
    free(records);
}

int main(int argc, char *argv[]) {
    size_t num_records = (argc > 1) ? atoi(argv[1]) : 50;

    manage_memory(num_records);

    return 0;
}
```

### Key Features:
- **Dynamic Memory Management**: Allocates and deallocates memory for offsets, keys, and records.
- **Random Initialization**: Initializes records with random values within a dynamic range.
- **Memory Usage Monitoring**: Checks memory usage against thresholds set via environment variables.
- **Data Integrity Verification**: Ensures that the data remains consistent across operations.
- **Thread Safety**: Uses threads to monitor memory without impacting performance significantly.
- **Reproducibility**: Allows setting a seed for random number generation via environment variables.']

