#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>

#define MAX_PACKETS 1000

typedef struct {
    uint64_t timestamp;
    size_t packet_size;
    void *data;
} Packet;

typedef struct {
    Packet **packets;
    size_t count;
    size_t max_size;
    pthread_mutex_t mutex;
    pthread_cond_t cond_var;
    FILE *log_file;
} PacketArray;

void log_packet(PacketArray *array, const char *message) {
    if (array->log_file) {
        fprintf(array->log_file, "%s\n", message);
        fflush(array->log_file);
    }
}

int is_valid_packet(const void *data, size_t packet_size) {
    // Implement your validation logic here
    return 1; // Assume valid for now
}

void *process_packets(void *arg) {
    PacketArray *array = (PacketArray *)arg;

    while (1) { // Replace with a condition to stop processing if needed
        pthread_mutex_lock(&array->mutex);

        while (array->count < array->max_size) {
            void *packet_data;  // Assume this is populated by receiving function
            size_t packet_size = sizeof(packet_data);  // Placeholder for actual size

            if (is_valid_packet(packet_data, packet_size)) {
                Packet *new_packet = malloc(sizeof(Packet));
                new_packet->timestamp = time(NULL);
                new_packet->packet_size = packet_size;
                new_packet->data = malloc(packet_size);

                memcpy(new_packet->data, packet_data, packet_size);

                array->packets[array->count++] = new_packet;

                char log_message[256];
                snprintf(log_message, sizeof(log_message), "Packet added: timestamp=%llu, size=%zu",
                         (unsigned long long)new_packet->timestamp, new_packet->packet_size);

                log_packet(array, log_message);

                pthread_cond_signal(&array->cond_var);
            }
        }

        pthread_mutex_unlock(&array->mutex);
    }

    return NULL;
}

void *limit_packets(void *arg) {
    PacketArray *array = (PacketArray *)arg;

    while (1) {  // Replace with a condition to stop limiting if needed
        sleep(5);  // Adjust time interval as necessary

        pthread_mutex_lock(&array->mutex);

        while (array->count > array->max_size) {
            free(array->packets[0]->data);
            free(array->packets[0]);

            memmove(array->packets, &array->packets[1], sizeof(Packet *) * (array->count - 1));
            --array->count;
        }

        pthread_mutex_unlock(&array->mutex);
    }

    return NULL;
}

void initialize_packet_array(PacketArray *array, size_t max_size) {
    array->packets = malloc(max_size * sizeof(Packet *));
    array->count = 0;
    array->max_size = max_size;

    pthread_mutex_init(&array->mutex, NULL);
    pthread_cond_init(&array->cond_var, NULL);

    // Open log file
    array->log_file = fopen("packet_log.txt", "a");

    if (!array->packets || !array->log_file) {
        fprintf(stderr, "Initialization failed: out of memory or unable to open log file\n");
        exit(EXIT_FAILURE);
    }

    pthread_t packet_thread, limit_thread;
    pthread_create(&packet_thread, NULL, process_packets, array);
    pthread_create(&limit_thread, NULL, limit_packets, array);

    // Join threads if needed; otherwise detach them
}

PacketArray *create_packet_array(size_t max_size) {
    PacketArray *array = malloc(sizeof(PacketArray));
    initialize_packet_array(array, max_size);
    return array;
}

void free_packet_array(PacketArray *array) {
    pthread_mutex_lock(&array->mutex);

    for (size_t i = 0; i < array->count; ++i) {
        free(array->packets[i]->data);
        free(array->packets[i]);
    }

    free(array->packets);

    pthread_mutex_unlock(&array->mutex);

    fclose(array->log_file);
    pthread_mutex_destroy(&array->mutex);
    pthread_cond_destroy(&array->cond_var);

    free(array);
}

int main() {
    size_t max_packets = MAX_PACKETS;
    PacketArray *packet_array = create_packet_array(max_packets);

    // Perform other operations...

    free_packet_array(packet_array);
    return 0;
}
