long* allocate_file_offsets(size_t count, size_t max_count) {
    if (count > max_count) {
        log_error("Requested file offsets exceed maximum allowed.");
        return NULL;
    }

    long *offsets = malloc(count * sizeof(long));
    if (!offsets) {
        log_error("Failed to allocate memory for file offsets.");
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        offsets[i] = i * 512; // assuming block size of 512 bytes
    }

    return offsets;
}

int* allocate_unique_identifiers(size_t count, pthread_mutex_t *mutex) {
    int *identifiers = malloc(count * sizeof(int));
    if (!identifiers) {
        log_error("Failed to allocate memory for unique identifiers.");
        return NULL;
    }

    pthread_mutex_lock(mutex);
    for (size_t i = 0; i < count; ++i) {
        identifiers[i] = rand() % 10000 + 1; // random IDs between 1 and 10000
    }
    pthread_mutex_unlock(mutex);

    return identifiers;
}

Record* allocate_records(size_t count, long min_key, long max_key, unsigned int seed, size_t *actual_count) {
    srand(seed);

    Record *records = malloc(count * sizeof(Record));
    if (!records) {
        log_error("Failed to allocate memory for records.");
        return NULL;
    }

    *actual_count = 0;
    for (size_t i = 0; i < count; ++i) {
        records[i].key = rand() % (max_key - min_key + 1) + min_key;

        if (strlen(records[i].data) < MAX_STRING_LENGTH) {
            snprintf(records[i].data, MAX_STRING_LENGTH, "Record_%zu", i);
            (*actual_count)++;
        }
    }

    return records;
}

void free_resources(long *file_offsets, int *identifiers, Record *records) {
    if (file_offsets != NULL) free(file_offsets);
    if (identifiers != NULL) free(identifiers);
    if (records != NULL) free(records);
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

int main() {
    size_t max_file_offsets = 1024;
    size_t count = 100; // example user input
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    long *file_offsets = allocate_file_offsets(count, max_file_offsets);
    int *identifiers = allocate_unique_identifiers(count, &mutex);

    if (!file_offsets || !identifiers) {
        free_resources(file_offsets, identifiers, NULL);
        return 1;
    }

    size_t actual_record_count;
    Record *records = allocate_records(count, 1000, 9999, time(NULL), &actual_record_count);

    if (!records) {
        free_resources(file_offsets, identifiers, records);
        return 1;
