#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct entry {
    char* data;
    int key;
    struct entry* next;
} entry;

typedef struct {
    entry** entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} EntryList;

#define INITIAL_CAPACITY 64
#define RESIZE_FACTOR 2

EntryList* init_entry_list() {
    EntryList* list = (EntryList*)malloc(sizeof(EntryList));
    if (!list) return NULL;

    list->entries = (entry**)calloc(INITIAL_CAPACITY, sizeof(entry*));
    if (!list->entries) {
        free(list);
        return NULL;
    }

    list->capacity = INITIAL_CAPACITY;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

int resize_if_needed(EntryList* list) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * RESIZE_FACTOR;
        entry** new_entries = (entry**)realloc(list->entries, new_capacity * sizeof(entry*));
        if (!new_entries) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Failed to resize
        }
        list->entries = new_entries;
        list->capacity = new_capacity;
    }
    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

int add_entry(EntryList* list, const char* data, int key) {
    if (resize_if_needed(list) != 0) {
        fprintf(stderr, "Failed to resize entry list.\n");
        return -1;
    }

    pthread_mutex_lock(&list->lock);
    entry* new_entry = (entry*)malloc(sizeof(entry));
    if (!new_entry) {
        pthread_mutex_unlock(&list->lock);
        fprintf(stderr, "Memory allocation failed for new entry.\n");
        return -2; // Allocation failure
    }

    new_entry->data = strdup(data);
    if (!new_entry->data) {
        free(new_entry);
        pthread_mutex_unlock(&list->lock);
        fprintf(stderr, "Failed to allocate memory for entry data string.\n");
        return -3;
    }

    new_entry->key = key;
    new_entry->next = NULL;

    list->entries[list->count++] = new_entry;
    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

void free_entry_list(EntryList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        entry* e = list->entries[i];
        if (e) {
            free(e->data);
            free(e);
        }
    }
    free(list->entries);
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}

void iterate_entries(const EntryList* list, void (*callback)(const entry*)) {
    if (!list || !callback) return;

    pthread_mutex_lock((pthread_mutex_t*)&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->entries[i]) {
            callback(list->entries[i]);
        }
    }
    pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
}

void print_entry(const entry* e) {
    if (!e) return;
    printf("Key: %d, Data: %s\n", e->key, e->data);
}
