#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define constants
#define MAX_RECORD_SIZE 8 * 1024 // 8KB per record
#define MAX_STRING_LENGTH 128

typedef struct {
    int key;
    char data[MAX_STRING_LENGTH + 1]; // +1 for null-termination
    time_t timestamp;
} Record;

typedef struct {
    long *file_indices;
    size_t num_indices;
    long last_accessed_index;

    int *record_identifiers;
    size_t num_identifiers;
    int recycle_threshold; // threshold to start recycling identifiers

    Record **records;
    size_t record_count;
    size_t max_records;

    // Hash map for quick lookup by key (simple version)
    Record **hash_map;
    size_t hash_size;
} StorageSystem;

// Forward declarations
void initialize_system(StorageSystem *system, size_t initial_indices, size_t initial_ids, size_t max_records);
void update_file_index(StorageSystem *system, long index);
int get_recycled_identifier(StorageSystem *system);
void insert_batch_records(StorageSystem *system, Record *records, size_t count);
Record* search_record_by_key(StorageSystem *system, int key);

// Hash map functions
#define HASH_KEY(key) ((key) % system->hash_size)
void add_to_hash_map(StorageSystem *system, Record *record);
Record* get_from_hash_map(StorageSystem *system, int key);

void initialize_system(StorageSystem *system, size_t initial_indices, size_t initial_ids, size_t max_records) {
    // Initialize file indices
    system->file_indices = (long *)malloc(initial_indices * sizeof(long));
    if (!system->file_indices) {
        fprintf(stderr, "Memory allocation failed for file indices\n");
        exit(EXIT_FAILURE);
    }
    system->num_indices = initial_indices;
    system->last_accessed_index = -1;

    // Initialize record identifiers
    system->record_identifiers = (int *)malloc(initial_ids * sizeof(int));
    if (!system->record_identifiers) {
        fprintf(stderr, "Memory allocation failed for record identifiers\n");
        free(system->file_indices);
        exit(EXIT_FAILURE);
    }
    system->num_identifiers = initial_ids;
    system->recycle_threshold = initial_ids / 2;

    // Initialize records and hash map
    system->records = (Record **)malloc(max_records * sizeof(Record *));
    if (!system->records) {
        fprintf(stderr, "Memory allocation failed for record storage\n");
        free(system->file_indices);
        free(system->record_identifiers);
        exit(EXIT_FAILURE);
    }
    system->max_records = max_records;
    system->record_count = 0;

    // Initialize hash map
    system->hash_size = max_records;
    system->hash_map = (Record **)calloc(max_records, sizeof(Record *));
    if (!system->hash_map) {
        fprintf(stderr, "Memory allocation failed for hash map\n");
        free(system->file_indices);
        free(system->record_identifiers);
        free(system->records);
        exit(EXIT_FAILURE);
    }
}

void update_file_index(StorageSystem *system, long index) {
    if (index >= system->num_indices) {
        size_t new_size = system->num_indices == 0 ? 1 : system->num_indices * 2;
        while (new_size <= index + 1) new_size *= 2;

        long *new_array = (long *)realloc(system->file_indices, new_size * sizeof(long));
        if (!new_array) {
            fprintf(stderr, "Memory allocation failed for resizing file indices\n");
            return;
        }

        system->file_indices = new_array;
        system->num_indices = new_size;

        memset(&system->file_indices[index + 1], 0, (new_size - index - 1) * sizeof(long));
    }
    system->last_accessed_index = index;
}

int get_recycled_identifier(StorageSystem *system) {
    for (size_t i = 0; i < system->num_identifiers; ++i) {
        if (i >= system->recycle_threshold) return system->record_identifiers[i % system->recycle_threshold];
    }
    int new_id = system->num_identifiers++;
    if (!new_id && !system->recycle_threshold) {
        system->recycle_threshold = 1;
    }
    return new_id;
}

void insert_batch_records(StorageSystem *system, Record *records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (system->record_count >= system->max_records) {
            fprintf(stderr, "Memory limit reached. Cannot insert more records.\n");
            break;
        }

        system->records[system->record_count++] = &records[i];
        add_to_hash_map(system, &records[i]);
    }
}

Record* search_record_by_key(StorageSystem *system, int key) {
    Record *record = get_from_hash_map(system, key);
    if (record) {
        record->timestamp = time(NULL); // update last accessed time
        return record;
    }
    return NULL;
}

void add_to_hash_map(StorageSystem *system, Record *record) {
    size_t hash_index = HASH_KEY(record->key);
    while (system->hash_map[hash_index] && system->hash_map[hash_index]->key != record->key) {
        hash_index = (hash_index + 1) % system->hash_size;
    }
    system->hash_map[hash_index] = record;
}

Record* get_from_hash_map(StorageSystem *system, int key) {
    size_t hash_index = HASH_KEY(key);
    while (system->hash_map[hash_index]) {
        if (system->hash_map[hash_index]->key == key) {
            return system->hash_map[hash_index];
        }
        hash_index = (hash_index + 1) % system->hash_size;
    }
    return NULL;
}

int main() {
    StorageSystem system;
    initialize_system(&system, 10, 100, 50);

    // Example usage
    update_file_index(&system, 5);

    Record records[2] = {{1, "Record 1", time(NULL)}, {2, "Record 2", time(NULL)}};
    insert_batch_records(&system, records, 2);

    Record *found_record = search_record_by_key(&system, 1);
    if (found_record) {
        printf("Found record: %s\n", found_record->data);
    } else {
        printf("Record not found.\n");
    }

    // Clean up
    free(system.file_indices);
    free(system.record_identifiers);
    free(system.records);
    free(system.hash_map);

    return 0;
}
