import subprocess
import logging
import os

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

def execute_command(command):
    try:
        result = subprocess.run(command, shell=True, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        logger.info(f"Command executed successfully: {command}")
        return result.stdout.decode().strip()
    except subprocess.CalledProcessError as e:
        logger.error(f"Failed to execute command: {e.cmd}\nError message: {e.stderr.decode().strip()}")
        raise

def apply_network_configuration(interface, config):
    try:
        # Update IP address and subnet mask
        ip_command = f"ip addr add {config['ip_address']}/{config['subnet_mask']} dev {interface}"
        execute_command(ip_command)

        # Set default gateway
        if 'gateway' in config:
            route_command = f"ip route replace default via {config['gateway']}"
            execute_command(route_command)

        # Update DNS servers (example for systemd-resolved)
        dns_config_path = "/etc/systemd/resolved.conf.d/custom.dns"
        os.makedirs(os.path.dirname(dns_config_path), exist_ok=True)
        with open(dns_config_path, 'w') as f:
            if 'dns_servers' in config:
                f.write(f"[Resolve]\nDNS={','.join(config['dns_servers'])}\n")

        # Apply tenant-specific routing rules
        for rule in config.get('routing_rules', []):
            route_command = f"ip route add {rule} dev {interface}"
            execute_command(route_command)

    except Exception as e:
        logger.error(f"Error applying network configuration: {e}")
        raise

def configure_traffic_control(interface, qos_config):
    try:
        for class_name, settings in qos_config.items():
            # Create traffic control classes
            create_class_command = f'tc qdisc add dev {interface} clsact'
            execute_command(create_class_command)

            # Add specific class and rate limit
            tc_command = (f"tc class add dev {interface} parent 1: classid 1:{class_name} "
                          f"htb rate {settings['rate']} ceil {settings['ceil']}")
            execute_command(tc_command)

            # Apply filters based on application type
            filter_command = (f"tc filter add dev {interface} protocol ip parent 1:0 prio 1 "
                              f"u32 match ip dport {settings['dport']} flowid 1:{class_name}")
            execute_command(filter_command)

    except Exception as e:
        logger.error(f"Error configuring traffic control: {e}")
        raise

def update_network_configuration(vm_id, configurations):
    try:
        for interface_config in configurations:
            interface = interface_config['interface']
            config = interface_config['config']

            # Apply the network configuration
            apply_network_configuration(interface, config)

            # Configure QoS if specified
            qos_config = interface_config.get('qos', {})
            if qos_config:
                configure_traffic_control(interface, qos_config)

    except Exception as e:
        logger.error(f"Failed to update network configuration for VM {vm_id}: {e}")
        # Attempt rollback or fallback actions here

def main():
    # Example configuration dictionary
    configurations = [
        {
            'interface': 'eth0',
            'config': {
                'ip_address': '192.168.1.10',
                'subnet_mask': 24,
                'gateway': '192.168.1.1',
                'dns_servers': ['8.8.8.8', '8.8.4.4'],
                'routing_rules': ['default via 192.168.2.1']
            },
            'qos': {
                '1': {'rate': '100mbit', 'ceil': '150mbit', 'dport': '80'}
            }
        }
    ]

    # Simulate VM ID
    vm_id = "vm-1234"

    update_network_configuration(vm_id, configurations)

if __name__ == "__main__":
    main()
