#include "UnityEngine.h"  // Assume this is where UnityEngine.Random.Range is defined

#define MAX_IDENTIFIER 1000000
#define MAX_RECORD_MEMORY 4096
#define BLOCK_SIZE 512

typedef struct {
    int key;
    char data[64];
} Record;

typedef struct {
    atomic_int min;
    atomic_int max;
    atomic_int float_count;
    atomic_int int_count;
    pthread_mutex_t lock;
} RandomValueGenerator;

void* allocate_and_initialize_file_offsets(size_t count) {
    if (count == 0 || count > MAX_IDENTIFIER / BLOCK_SIZE) {
        fprintf(stderr, "Invalid input size\n");
        return NULL;
    }

    long *fileOffsets = malloc(sizeof(long) * count);
    if (!fileOffsets) {
        perror("Failed to allocate memory for file offsets");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < count; ++i) {
        fileOffsets[i] = i * BLOCK_SIZE;
    }
    return fileOffsets;
}

void* initialize_file_identifiers(size_t count) {
    if (count == 0 || count > MAX_IDENTIFIER) {
        fprintf(stderr, "Invalid input size for identifiers\n");
        return NULL;
    }

    int *identifiers = malloc(sizeof(int) * count);
    if (!identifiers) {
        perror("Failed to allocate memory for file identifiers");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (size_t i = 0; i < count; ++i) {
        pthread_mutex_lock(&lock);
        identifiers[i] = rand() % MAX_IDENTIFIER + 1;
        pthread_mutex_unlock(&lock);
    }

    return identifiers;
}

void* allocate_and_initialize_records(size_t count) {
    if (count == 0 || sizeof(Record) * count > MAX_RECORD_MEMORY) {
        fprintf(stderr, "Invalid input size for records\n");
        return NULL;
    }

    Record *records = malloc(sizeof(Record) * count);
    if (!records) {
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (size_t i = 0; i < count; ++i) {
        pthread_mutex_lock(&lock);
        records[i].key = rand() % MAX_IDENTIFIER + 1;
        snprintf(records[i].data, sizeof(records[i].data), "Record_%zu", i);
        pthread_mutex_unlock(&lock);
    }

    return records;
}

RandomValueGenerator* RandomValueGenerator_Create(int min, int max) {
    RandomValueGenerator *generator = malloc(sizeof(RandomValueGenerator));
    if (!generator) {
        perror("Failed to allocate memory for random value generator");
        exit(EXIT_FAILURE);
    }

    atomic_init(&generator->min, min);
    atomic_init(&generator->max, max);
    atomic_store(&generator->float_count, 0);
    atomic_store(&generator->int_count, 0);

    pthread_mutex_init(&generator->lock, NULL);

    return generator;
}

int RandomValueGenerator_GetRandomInt(RandomValueGenerator *generator) {
    int value = UnityEngine.Random.Range(atomic_load(&generator->min), atomic_load(&generator->max));
    atomic_fetch_add(&generator->int_count, 1);
    return value;
}

float RandomValueGenerator_GetRandomFloat(RandomValueGenerator *generator) {
    float min = (float)atomic_load(&generator->min);
    float max = (float)atomic_load(&generator->max);
    float value = UnityEngine.Random.Range(min, max);
    atomic_fetch_add(&generator->float_count, 1);
    return value;
}

const char* RandomValueGenerator_ToString(RandomValueGenerator *generator) {
    pthread_mutex_lock(&generator->lock);
    static char buffer[128];
    snprintf(buffer, sizeof(buffer), "Range: [%d, %d], Floats: %d, Integers: %d",
             atomic_load(&generator->min), atomic_load(&generator->max),
             atomic_load(&generator->float_count), atomic_load(&generator->int_count));
    pthread_mutex_unlock(&generator->lock);

    return buffer;
}

#include <task.h>

TaskCompletionSource<int> RandomValueGenerator_ExecuteBackgroundTask(RandomValueGenerator *generator, Func<int> task) {
    TaskCompletionSource<int> tcs;
    int result = task();
    tcs.SetResult(result);
    return tcs;
}

