#include <iostream>
#include <vector>
#include <unordered_map>
#include <fstream>
#include <chrono>
#include <cstring>
#include <stdexcept>

// Define the Packet structure
struct Packet {
    std::chrono::time_point<std::chrono::steady_clock> timestamp;
    size_t packet_size;
    uint8_t* data;

    Packet() : packet_size(0), data(nullptr) {}
    ~Packet() { delete[] data; }
};

// Union-Find Data Structure
class UnionFind {
public:
    UnionFind(int size) : parent(size), rank(size, 0) {
        for (int i = 0; i < size; ++i)
            parent[i] = i;
    }

    int find(int u) {
        if (u != parent[u])
            parent[u] = find(parent[u]);
        return parent[u];
    }

    void unite(int u, int v) {
        int rootU = find(u);
        int rootV = find(v);

        if (rootU != rootV) {
            if (rank[rootU] > rank[rootV]) 
                parent[rootV] = rootU;
            else if (rank[rootU] < rank[rootV])
                parent[rootU] = rootV;
            else {
                parent[rootV] = rootU;
                ++rank[rootU];
            }
        }
    }

private:
    std::vector<int> parent, rank;
};

