    // Read and validate metadata (simplified)
    std::string line;
    while (std::getline(configFile, line)) {
        if (!line.empty()) {
            validPacketIDs[line] = 1; // Simplified: Assume all IDs are valid
        }
    }

    // Placeholder for receiving packets from network interface
    std::vector<Packet> packetBatch; // Replace with actual batch retrieval logic

    UnionFind uf(packetBatch.size());

    int disjointPairsCount = 0;
    double totalValidationTime = 0.0;

    auto startGlobal = std::chrono::steady_clock::now();

    for (size_t i = 0; i < packetBatch.size(); ++i) {
        auto& packet = packetBatch[i];

        // Validate packet using metadata
        if (validPacketIDs.find(packet.data) != validPacketIDs.end()) { // Simplified validation logic

            for (size_t j = i + 1; j < packetBatch.size(); ++j) {
                auto startPairValidation = std::chrono::steady_clock::now();

                uf.unite(i, j);

                auto endPairValidation = std::chrono::steady_clock::now();
                totalValidationTime += std::chrono::duration<double, std::milli>(endPairValidation - startPairValidation).count();
            }
        } else {
            delete[] packet.data;
            packet.data = nullptr;
            packet.packet_size = 0;
        }

        if (uf.find(i) != i) ++disjointPairsCount; // Check if the packet is a root of its own component
    }

    auto endGlobal = std::chrono::steady_clock::now();
    totalValidationTime += std::chrono::duration<double, std::milli>(endGlobal - startGlobal).count();

    return {disjointPairsCount, totalValidationTime};
}

int main() {
    try {
