#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include "tiffio.h"
#include "murmurhash3.h"

typedef struct {
    int value;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record* records;
    size_t count;
    pthread_mutex_t lock;
} data_struct;

// Function prototypes
void initialize_data(data_struct *data, size_t num_records);
unsigned int murmurhash3_int(int input);
void process_tiff_file(const char *filename, data_struct *data);
void log_message(const char *message);
void* thread_function(void *arg);

void initialize_data(data_struct *data, size_t num_records) {
    pthread_mutex_init(&data->lock, NULL);
    data->count = num_records;
    data->offsets = (long*)calloc(num_records, sizeof(long));
    data->keys = (int*)calloc(num_records, sizeof(int));
    data->records = (record*)malloc(num_records * sizeof(record));

    for (size_t i = 0; i < num_records; ++i) {
        data->records[i].value = rand() % 100; // Example initialization
    }
}

unsigned int murmurhash3_int(int input) {
    return MurmurHash3_x86_32(&input, sizeof(input), 0);
}

void process_tiff_file(const char *filename, data_struct *data) {
    TIFF* tif = TIFFOpen(filename, "r");
    if (!tif) {
        log_message("Failed to open TIFF file.");
        return;
    }

    uint32 samplesPerPixel, bitsPerSample, extraSamples;
    if (TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &samplesPerPixel) &&
        TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &bitsPerSample) &&
        TIFFGetField(tif, TIFFTAG_EXTRASAMPLES, &extraSamples)) {

        // Process each strip
        uint32 strips_per_image;
        if (TIFFNumberOfStrips(tif, &strips_per_image)) {
            for (uint32 i = 0; i < strips_per_image; ++i) {
                char buffer[1024 * 64]; // Example buffer size
                uint32 strip_size;
                if (TIFFReadEncodedStrip(tif, i, buffer, sizeof(buffer))) {
                    pthread_t thread;
                    pthread_create(&thread, NULL, thread_function, data);
                    pthread_join(thread, NULL);
                }
            }
        }
    } else {
        log_message("Failed to read TIFF metadata.");
    }

    TIFFClose(tif);
}

void log_message(const char *message) {
    // Simple logging mechanism
    printf("%s\n", message);
}

void* thread_function(void *arg) {
    data_struct *data = (data_struct *)arg;
    pthread_mutex_lock(&data->lock);

    for (size_t i = 0; i < data->count; ++i) {
        unsigned int checksum = murmurhash3_int(data->records[i].value);
        printf("Record %zu: Value = %d, Checksum = %u\n", i, data->records[i].value, checksum);
    }

    pthread_mutex_unlock(&data->lock);
    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s <tiff_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    data_struct data;
    initialize_data(&data, 10000); // Example number of records

    process_tiff_file(argv[1], &data);

    free(data.offsets);
    free(data.keys);
    free(data.records);
    pthread_mutex_destroy(&data.lock);

    return EXIT_SUCCESS;
}
```

### Key Points:
- **Memory Allocation**: Uses `calloc` and `malloc` for dynamic memory allocation.
- **MurmurHash3**: Implements a simple hashing function for data integrity checks.
- **TIFF Parsing**: Utilizes libtiff for TIFF file handling, extracting metadata, and processing image strips.
- **Logging**: Basic logging to console for errors and processing information.
- **Multi-threading**: Uses pthreads for concurrent execution, ensuring thread safety with mutex locks.
- **Error Handling**: Checks for potential errors in file operations and metadata extraction.

### Considerations:
- Ensure `libtiff` is linked correctly during compilation.
- Adjust buffer size and number of records as needed based on actual data requirements.
- Extend logging and error handling as necessary for production use.']

