public class ConfigLoader
{
    public int TileSize { get; private set; }
    public int WorldWidth { get; private set; }
    public int WorldHeight { get; private set; }
    public float CameraSpeed { get; private set; }

    public ConfigLoader(string configPath)
    {
        XmlDocument doc = new XmlDocument();
        try
        {
            doc.Load(configPath);
            XmlNode root = doc.DocumentElement;

            TileSize = GetIntValue(root, "TileSize", 64); // Default value if missing or invalid
            WorldWidth = GetIntValue(root, "WorldWidth", 1024);
            WorldHeight = GetIntValue(root, "WorldHeight", 768);
            CameraSpeed = GetFloatValue(root, "CameraSpeed", 1.0f);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error loading configuration: {ex.Message}");
        }
    }

    private int GetIntValue(XmlNode node, string elementName, int defaultValue)
    {
        XmlNode child = node[elementName];
        if (child != null && int.TryParse(child.InnerText, out int value))
        {
            return value;
        }
        Console.WriteLine($"Invalid or missing {elementName}, using default: {defaultValue}");
        return defaultValue;
    }

    private float GetFloatValue(XmlNode node, string elementName, float defaultValue)
    {
        XmlNode child = node[elementName];
        if (child != null && float.TryParse(child.InnerText, out float value))
        {
            return value;
        }
        Console.WriteLine($"Invalid or missing {elementName}, using default: {defaultValue}");
        return defaultValue;
    }

    public static void Main(string[] args)
    {
        ConfigLoader config = new ConfigLoader("config.xml");
        Console.WriteLine($"Tile Size: {config.TileSize}");
        Console.WriteLine($"World Width: {config.WorldWidth}");
        Console.WriteLine($"World Height: {config.WorldHeight}");
        Console.WriteLine($"Camera Speed: {config.CameraSpeed}");
    }
}
