['Below is a C implementation for managing a dynamic data structure with thread-safe operations, efficient aggregation, and periodic flushing:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

#define INITIAL_CAPACITY 10

typedef struct {
    int key;
    int value;
} Record;

typedef struct {
    atomic_int64_t total; // Use atomic for thread safety
} Summary;

typedef struct {
    Record *records;
    Summary *summaries;
    size_t capacity;
    pthread_mutex_t lock;
    atomic_size_t count;
} DataStructure;

void initialize_data_structure(DataStructure *ds) {
    ds->capacity = INITIAL_CAPACITY;
    ds->records = malloc(sizeof(Record) * ds->capacity);
    ds->summaries = calloc(ds->capacity, sizeof(Summary));
    pthread_mutex_init(&ds->lock, NULL);
    atomic_store(&ds->count, 0);
}

void resize_data_structure(DataStructure *ds, size_t new_capacity) {
    pthread_mutex_lock(&ds->lock);
    ds->records = realloc(ds->records, sizeof(Record) * new_capacity);
    ds->summaries = realloc(ds->summaries, sizeof(Summary) * new_capacity);
    ds->capacity = new_capacity;
    pthread_mutex_unlock(&ds->lock);
}

void add_record(DataStructure *ds, int key) {
    size_t index = atomic_fetch_add_explicit(&ds->count, 1, memory_order_relaxed);

    if (index >= ds->capacity) {
        resize_data_structure(ds, ds->capacity * 2);
        index = atomic_fetch_sub_explicit(&ds->count, 1, memory_order_relaxed);
    }

    pthread_mutex_lock(&ds->lock);

    Record *record = &ds->records[index];
    record->key = key;

    int64_t cumulative_sum = 0;
    for (size_t i = 0; i < index; ++i) {
        cumulative_sum += ds->records[i].value;
    }

    record->value = rand() % 100 + cumulative_sum;
    atomic_fetch_add_explicit(&ds->summaries[key].total, record->value, memory_order_relaxed);

    pthread_mutex_unlock(&ds->lock);
}

void flush_summaries(DataStructure *ds) {
    // Simulate flushing to persistent storage
    printf("Flushing summaries...\n");
    for (size_t i = 0; i < ds->count; ++i) {
        printf("Key: %d, Total: %" PRId64 "\n", ds->records[i].key, atomic_load(&ds->summaries[ds->records[i].key].total));
    }
}

void *periodic_flush(void *arg) {
    DataStructure *ds = (DataStructure *)arg;
    while (1) {
        sleep(10); // Adjust flush frequency as needed
        flush_summaries(ds);
    }
    return NULL;
}

int main() {
    srand(time(NULL));
    DataStructure ds;
    initialize_data_structure(&ds);

    pthread_t flush_thread;
    pthread_create(&flush_thread, NULL, periodic_flush, &ds);

    for (int i = 0; i < 100; ++i) {
        add_record(&ds, rand() % INITIAL_CAPACITY);
    }

    // Simulate running
    sleep(60);

    free(ds.records);
    free(ds.summaries);
    pthread_mutex_destroy(&ds.lock);
    return 0;
}
```

### Key Features:
- **Thread Safety**: Uses `pthread_mutex` and atomic operations to ensure safe concurrent access.
- **Dynamic Resizing**: Doubles capacity when needed, minimizing allocations.
- **Periodic Flushing**: Flushes summaries every 10 seconds (adjustable) for data durability.
- **Overflow Handling**: Uses `int64_t` for totals to prevent overflow.
- **Memory Optimization**: Reuses memory efficiently with resizing strategy.']

