        ds->records[i].value = range_start + rand() % (range_end - range_start + 1);

        if ((ds->total_sum += ds->records[i].value) < ds->total_sum) {
            log_error("Integer overflow detected");
            break;
        }
    }

    pthread_mutex_unlock(&ds->lock);
}

