        if (pthread_create(&threads[i], NULL, record_insertion_thread, NULL)) {
            fprintf(stderr, "Error creating thread\n");
            return 1;
        }
    }

    // Periodic statistics reporting
    while (1) {
        sleep(10); // Every 10 seconds
        pthread_mutex_lock(&storage.lock);
        Statistics stats = {0};
        calculate_statistics(&stats);
        report_statistics();
        pthread_mutex_unlock(&storage.lock);
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Cleanup
    free(storage.records);
    pthread_mutex_destroy(&storage.lock);
    pthread_cond_destroy(&cond_var);

    return 0;
}

void init_memory_pool(StorageSystem *storage) {
    storage->records = (Record *)malloc(INITIAL_CAPACITY * sizeof(Record));
    if (!storage->records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    storage->capacity = INITIAL_CAPACITY;
}

Record* allocate_record_from_pool() {
    pthread_mutex_lock(&storage.lock);

    if (storage.count >= storage.capacity) {
        // Double capacity
        size_t new_capacity = storage.capacity * 2;
        Record *new_records = realloc(storage.records, new_capacity * sizeof(Record));
        if (!new_records) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        storage->records = new_records;
        storage->capacity = new_capacity;
    }

    Record *record = &storage.records[storage.count++];
    pthread_mutex_unlock(&storage.lock);

    return record;
}

void deallocate_record_to_pool(Record *record) {
    // Placeholder for pool deallocation logic
}

int random_value_adjusted_by_sum(long current_total_sum) {
    int value = rand() % 100; // Adjust this as needed
    long new_sum = calculate_new_sum_with_limit(value, current_total_sum);
    return (int)(new_sum - current_total_sum);
}

long calculate_new_sum_with_limit(int value, long current_sum) {
    long new_sum = current_sum + value;
    while (new_sum > MAX_SUM_RANGE) {
        // Adjust the sum to stay within range
        new_sum -= value;  // Simplistic adjustment logic
    }
    return new_sum;
}

void calculate_statistics(Statistics *stats) {
    pthread_mutex_lock(&storage.lock);

    int total = 0, max_value = INT_MIN, min_value = INT_MAX;
    for (size_t i = 0; i < storage.count; ++i) {
        Record record = storage.records[i];
        total += record.value;
        if (record.value > max_value) max_value = record.value;
        if (record.value < min_value) min_value = record.value;
    }

    stats->average = storage.count ? (double)total / storage.count : 0.0;
    stats->max_value = max_value;
    stats->min_value = min_value;

    pthread_mutex_unlock(&storage.lock);
}

void report_statistics() {
    Statistics stats;
    calculate_statistics(&stats);
    printf("Average: %.2f, Max: %d, Min: %d\n", stats.average, stats.max_value, stats.min_value);
}

void *record_insertion_thread(void *arg) {
