// Assume these are provided by external dependencies
extern void log_message(const char* message);
extern int parse_config_file(const char* filename, int* initial_range, size_t* num_records, size_t* max_memory_usage);

typedef struct {
    int value;
} record;

typedef struct {
    const char* tag;
} metadata;

// Global variables for configuration
int global_initial_range = 100;
size_t global_num_records = 0;
size_t global_max_memory_usage = 0;

// Thread-safe global variables
pthread_mutex_t lock;
long long running_total = 0;

// Function prototypes
void initialize_arrays(size_t num_records, int* initial_range);
void free_resources(long offset[], int key1[], int key2[], record records[], metadata tags[]);
size_t calculate_size(size_t size_of_record, size_t num_records);

void memory_management_function(const char* config_file) {
    // Parse configuration file
    parse_config_file(config_file, &global_initial_range, &global_num_records, &global_max_memory_usage);

    // Initialize mutex for thread safety
    pthread_mutex_init(&lock, NULL);

    long offset[global_num_records];
    int key1[global_num_records / 2]; // Assuming two keys share the records equally
    int key2[global_num_records / 2];
    record records[global_num_records];
    metadata tags[global_num_records];

    initialize_arrays(global_num_records, &global_initial_range);

    // Simulate cache eviction and adjustment logic here (omitted for brevity)

    // Free resources when done
    free_resources(offset, key1, key2, records, tags);

    pthread_mutex_destroy(&lock);
}

void initialize_arrays(size_t num_records, int* initial_range) {
    size_t size_of_record = sizeof(record);
    size_t max_size_in_memory = calculate_size(size_of_record, global_num_records);

    if (max_size_in_memory > global_max_memory_usage) {
        log_message("Memory usage exceeds maximum allowable limit.");
        return;
    }

    for (size_t i = 0; i < num_records; ++i) {
        offset[i] = rand() % INT_MAX;

        int key_index = i % 2 == 0 ? i / 2 : i / 2 + global_num_records / 2;
        if (i < global_num_records / 2) {
            key1[key_index] = rand() % *initial_range;
        } else {
            key2[key_index - global_num_records / 2] = rand() % *initial_range;
        }

        pthread_mutex_lock(&lock);
        records[i].value = rand() % *initial_range;
        running_total += records[i].value;
        if (running_total > LLONG_MAX) {
            log_message("Integer overflow detected.");
            // Handle overflow scenario
        }
        pthread_mutex_unlock(&lock);

        tags[i].tag = "example_metadata";  // Simplified for example

        // Adjust the range based on running total (efficiently, by a factor)
        *initial_range = (*initial_range + running_total / num_records) % INT_MAX;
    }

    log_message("Arrays initialized successfully.");
}

void free_resources(long offset[], int key1[], int key2[], record records[], metadata tags[]) {
    free(offset);
    free(key1);
    free(key2);
    free(records);
    free(tags);
    log_message("Resources freed successfully.");
}

size_t calculate_size(size_t size_of_record, size_t num_records) {
    return sizeof(long) * num_records + sizeof(int) * (num_records + num_records / 2)
           + size_of_record * num_records + sizeof(metadata) * num_records;
}
