}

// Function to dynamically allocate and initialize data structures
data_structures_t* init_data_structures(size_t num_records, int range_min, int range_max) {
    data_structures_t *ds = malloc(sizeof(data_structures_t));
    if (!ds) return NULL;

    pthread_mutex_init(&ds->lock, NULL);

    ds->offsets = malloc(num_records * sizeof(long));
    ds->keys = malloc(num_records * sizeof(int));
    ds->records = malloc(num_records * sizeof(record_t));
    ds->num_records = num_records;
    ds->sum = 0;

    if (!ds->offsets || !ds->keys || !ds->records) {
        free(ds->offsets);
        free(ds->keys);
        free(ds->records);
        pthread_mutex_destroy(&ds->lock);
        free(ds);
        return NULL;
    }

    for (size_t i = 0; i < num_records; ++i) {
        pthread_mutex_lock(&ds->lock);

        // Randomly assign key and calculate offset
        ds->keys[i] = rand() % 10000; // Example range
        ds->offsets[i] = i * sizeof(record_t);

        // Calculate a random value within the specified range, adjusting based on sum
        int base_value = rand() % (range_max - range_min + 1) + range_min;
        ds->records[i].value = base_value;

        // Update total sum and handle potential overflow
        if (__builtin_add_overflow(ds->sum, ds->records[i].value, &ds->sum)) {
            fprintf(stderr, "Integer overflow detected\n");
            pthread_mutex_unlock(&ds->lock);
            free(ds->offsets);
            free(ds->keys);
            free(ds->records);
            pthread_mutex_destroy(&ds->lock);
            free(ds);
            return NULL;
        }

        pthread_mutex_unlock(&ds->lock);
    }

    return ds;
}

// Function to free allocated resources
void cleanup_data_structures(data_structures_t *ds) {
    if (ds) {
        free(ds->offsets);
        free(ds->keys);
        free(ds->records);
        pthread_mutex_destroy(&ds->lock);
        free(ds);
    }
}

int main() {
