```c
#include <stdio.h>
#include <stdlib.h>
import java.nio.channels.SocketChannel;
import com.google.gson.Gson;  // Assuming use of Gson library for JSON

typedef struct {
    double timestamp;
    size_t packet_size;
    char *data;
} Packet;

// Function prototypes for utility functions
SocketChannel connectToRemoteAddress(const char *remote_address);
void handleError(const char *message);

// Mutex for thread-safe operations on the dynamic array
#include <pthread.h>
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Dynamic array structure to manage packets
typedef struct {
    Packet **packets;
    size_t capacity;
    size_t count;
} PacketArray;

PacketArray* createPacketArray(size_t initial_capacity) {
    PacketArray *array = (PacketArray *)malloc(sizeof(PacketArray));
    if (!array) {
        handleError("Memory allocation failed for PacketArray");
        return NULL;
    }

    array->packets = (Packet **)calloc(initial_capacity, sizeof(Packet *));
    if (!array->packets) {
        free(array);
        handleError("Memory allocation failed for packets array");
        return NULL;
    }

    array->capacity = initial_capacity;
    array->count = 0;

    return array;
}

void resizePacketArray(PacketArray *array, size_t new_capacity) {
    pthread_mutex_lock(&mutex);

    Packet **new_packets = (Packet **)realloc(array->packets, new_capacity * sizeof(Packet *));
    if (!new_packets) {
        handleError("Memory reallocation failed for packets array");
        pthread_mutex_unlock(&mutex);
        return;
    }

    array->packets = new_packets;
    array->capacity = new_capacity;

    pthread_mutex_unlock(&mutex);
}

void freePacketArray(PacketArray *array) {
    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->packets[i]) {
            free(array->packets[i]->data);
            free(array->packets[i]);
        }
    }

    free(array->packets);
    pthread_mutex_unlock(&mutex);

    free(array);
}

void initializeNetworkPackets(const char *remote_address) {
    try {
        SocketChannel channel = connectToRemoteAddress(remote_address);

        Gson gson;  // Initialize JSON parser
        PacketArray *packetArray = createPacketArray(10);  // Initial capacity

        if (!packetArray) return;

        while (true) {  // Loop to simulate continuous packet reception
            char buffer[1024];  // Assuming fixed-size buffer for demonstration
            int bytesRead = channel.read(ByteBuffer.wrap(buffer));

            if (bytesRead < 0) {
                handleError("Failed to read from the network");
                break;
            }

            Packet *packet = (Packet *)malloc(sizeof(Packet));
            if (!packet) {
                handleError("Memory allocation failed for new packet");
                continue; // Skip this iteration
            }

            // Simulate JSON deserialization into packet fields
            String jsonStr(buffer);
            packet->data = gson.fromJson(jsonStr, String.class).toCharArray();  // Convert to char array

            packet->timestamp = /* simulate floating-point arithmetic */;
            packet->packet_size = bytesRead;

            pthread_mutex_lock(&mutex);

            if (packetArray->count == packetArray->capacity) {
                resizePacketArray(packetArray, packetArray->capacity * 2);
            }

            packetArray->packets[packetArray->count++] = packet;

            pthread_mutex_unlock(&mutex);
        }
    } catch (Exception e) {
        handleError(e.getMessage());
    }
}

SocketChannel connectToRemoteAddress(const char *remote_address) {
