['Below is a C function implementation that dynamically manages memory for three arrays: one for `long` offset values, another for `int` keys, and a third for `record` structures. The function ensures thread safety, efficient memory management, and scalability.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
    int key_index;
} record;

typedef struct {
    long *offsets;
    size_t offset_capacity;
    size_t offset_size;

    int *keys;
    size_t key_capacity;
    size_t key_size;

    record *records;
    size_t record_capacity;
    size_t record_size;

    pthread_mutex_t mutex;
    int total_value_sum;
} MemoryManager;

void initialize_memory_manager(MemoryManager *manager, size_t init_offset_size, size_t offset_increment,
                               size_t init_key_size, size_t key_increment, size_t init_record_size, size_t record_increment) {
    pthread_mutex_init(&manager->mutex, NULL);
    manager->offsets = malloc(init_offset_size * sizeof(long));
    manager->offset_capacity = init_offset_size;
    manager->offset_size = 0;

    manager->keys = malloc(init_key_size * sizeof(int));
    manager->key_capacity = init_key_size;
    manager->key_size = 0;

    manager->records = malloc(init_record_size * sizeof(record));
    manager->record_capacity = init_record_size;
    manager->record_size = 0;

    manager->total_value_sum = 0;
}

void resize_array(void **array, size_t current_size, size_t capacity, size_t increment) {
    size_t new_capacity = capacity + increment;
    void *new_array = realloc(*array, new_capacity * sizeof(**array));
    if (new_array == NULL) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }
    *array = new_array;
}

void add_record(MemoryManager *manager, long offset, int key_index, int value_range_start, int value_range_end) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->record_size >= manager->record_capacity) {
        resize_array((void **)&manager->records, manager->record_size, manager->record_capacity, 10);
        manager->record_capacity += 10;
    }

    record new_record;
    new_record.key_index = key_index;

    int sum_of_values = manager->total_value_sum;
    srand(time(NULL) + offset); // Seed with time and offset for randomness
    new_record.value = (rand() % (value_range_end - value_range_start + 1)) + value_range_start + (sum_of_values % 10);

    if (manager->offset_size >= manager->offset_capacity) {
        resize_array((void **)&manager->offsets, manager->offset_size, manager->offset_capacity, 10);
        manager->offset_capacity += 10;
    }

    if (manager->key_size >= manager->key_capacity) {
        resize_array((void **)&manager->keys, manager->key_size, manager->key_capacity, 10);
        manager->key_capacity += 10;
    }

    manager->records[manager->record_size++] = new_record;
    manager->offsets[manager->offset_size++] = offset;
    manager->keys[manager->key_size++] = key_index;

    // Update total value sum with overflow handling
    long long int temp_sum = (long long int)manager->total_value_sum + new_record.value;
    if (temp_sum < 0 || temp_sum > INT_MAX) {
        fprintf(stderr, "Integer overflow detected\n");
        exit(EXIT_FAILURE);
    }
    manager->total_value_sum += new_record.value;

    pthread_mutex_unlock(&manager->mutex);
}

void free_memory_manager(MemoryManager *manager) {
    pthread_mutex_destroy(&manager->mutex);
    free(manager->offsets);
    free(manager->keys);
    free(manager->records);
}

int main() {
    MemoryManager manager;
    initialize_memory_manager(&manager, 10, 5, 10, 5, 10, 5);

    // Example usage
    add_record(&manager, 100L, 1, 0, 50);
    add_record(&manager, 200L, 2, 0, 50);

    free_memory_manager(&manager);
    return 0;
}
```

### Key Features:
- **Thread Safety**: Uses `pthread_mutex_t` to ensure thread-safe operations.
- **Dynamic Resizing**: Arrays are resized dynamically when needed, minimizing allocations and deallocations.
- **Efficient Memory Management**: Reuses existing memory blocks with `realloc`.
- **Integer Overflow Handling**: Checks for overflow during sum updates.
- **Modular Design**: Functions for initialization, resizing, adding records, and cleanup ensure modularity and extensibility.']

['Below is a C implementation that meets the requirements described in your task:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int value;
    char *str_ptr;
} CustomData;

typedef struct HashNode {
    char *key;
    CustomData data;
    struct HashNode *next;
} HashNode;

typedef struct {
    HashNode **buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t *locks;
    unsigned long (*hash_func)(const char *);
    int (*eq_func)(const char *, const char *);
    size_t load_factor;
} HashTable;

#define INITIAL_CAPACITY 16
#define LOAD_FACTOR_THRESHOLD 0.75

unsigned long default_hash(const char *str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    return hash;
}

int default_eq(const char *a, const char *b) {
    return strcmp(a, b) == 0;
}

void initialize_hash_table(HashTable *table, size_t initial_capacity,
                           unsigned long (*hash_func)(const char *),
                           int (*eq_func)(const char *, const char *)) {
    table->buckets = calloc(initial_capacity, sizeof(HashNode *));
    if (!table->buckets) {
        perror("Failed to allocate memory for hash table");
        exit(EXIT_FAILURE);
    }

    table->capacity = initial_capacity;
    table->size = 0;
    table->load_factor = 0.0;

    table->locks = calloc(initial_capacity, sizeof(pthread_mutex_t));
    if (!table->locks) {
        perror("Failed to allocate memory for hash table locks");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < initial_capacity; ++i)
        pthread_mutex_init(&table->locks[i], NULL);

    table->hash_func = hash_func ? hash_func : default_hash;
    table->eq_func = eq_func ? eq_func : default_eq;
}

void destroy_hash_table(HashTable *table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        HashNode *node = table->buckets[i];
        while (node) {
            HashNode *tmp = node;
            node = node->next;
            free(tmp->key);
            free(tmp->data.str_ptr);
            free(tmp);
        }
    }

    free(table->buckets);
    for (size_t i = 0; i < table->capacity; ++i)
        pthread_mutex_destroy(&table->locks[i]);

    free(table->locks);
}

static void resize_hash_table(HashTable *table) {
    size_t new_capacity = table->capacity * 2;
    HashNode **new_buckets = calloc(new_capacity, sizeof(HashNode *));
    if (!new_buckets) {
        perror("Failed to allocate memory for hash table resizing");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_t *new_locks = realloc(table->locks, new_capacity * sizeof(pthread_mutex_t));
    if (!new_locks) {
        perror("Failed to reallocate memory for hash table locks during resize");
        free(new_buckets);
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < new_capacity; ++i)
        pthread_mutex_init(&new_locks[i], NULL);

    for (size_t i = 0; i < table->capacity; ++i) {
        HashNode *node = table->buckets[i];
        while (node) {
            size_t index = table->hash_func(node->key) % new_capacity;
            pthread_mutex_lock(&new_locks[index]);

            node->next = new_buckets[index];
            new_buckets[index] = node;

            pthread_mutex_unlock(&new_locks[index]);
            node = node->next;
        }
    }

    free(table->buckets);
    table->buckets = new_buckets;
    table->capacity = new_capacity;
    table->locks = new_locks;
}

int hash_table_insert(HashTable *table, const char *key, CustomData data) {
    if (!key || !data.str_ptr) return -1;

    size_t index = table->hash_func(key) % table->capacity;

    pthread_mutex_lock(&table->locks[index]);

    HashNode **bucket = &table->buckets[index];
    while (*bucket && table->eq_func((*bucket)->key, key)) {
        pthread_mutex_unlock(&table->locks[index]);
        return -1; // Key already exists
    }

    if ((*bucket == NULL) || !(*bucket)->next) {
        HashNode *new_node = malloc(sizeof(HashNode));
        new_node->key = strdup(key);
        new_node->data = data;
        new_node->next = *bucket;
        *bucket = new_node;

        ++table->size;
    }

    table->load_factor = (double)table->size / table->capacity;
    if (table->load_factor > LOAD_FACTOR_THRESHOLD) {
        pthread_mutex_unlock(&table->locks[index]);
        resize_hash_table(table);
        return hash_table_insert(table, key, data); // Retry insertion
    }

    pthread_mutex_unlock(&table->locks[index]);
    return 0;
}

CustomData *hash_table_lookup(HashTable *table, const char *key) {
    if (!key) return NULL;

    size_t index = table->hash_func(key) % table->capacity;
    pthread_mutex_lock(&table->locks[index]);

    HashNode *node = table->buckets[index];
    while (node && !table->eq_func(node->key, key)) {
        node = node->next;
    }

    CustomData *result = NULL;
    if (node) {
        result = &node->data;
    }

    pthread_mutex_unlock(&table->locks[index]);
    return result;
}

void print_hash_table(HashTable *table) {
    printf("Hash Table:\n");
    for (size_t i = 0; i < table->capacity; ++i) {
        pthread_mutex_lock(&table->locks[i]);

        HashNode *node = table->buckets[i];
        while (node) {
            printf("Bucket %zu: Key=%s, Value=%d\n", i, node->key, node->data.value);
            node = node->next;
        }

        pthread_mutex_unlock(&table->locks[i]);
    }
}

int main() {
    HashTable table1, table2;
    initialize_hash_table(&table1, INITIAL_CAPACITY, NULL, NULL);
    initialize_hash_table(&table2, INITIAL_CAPACITY, default_hash, default_eq);

    CustomData data = {42, "example"};

    hash_table_insert(&table1, "key1", data);
    hash_table_insert(&table2, "key2", (CustomData){24, "another example"});

    print_hash_table(&table1);
    print_hash_table(&table2);

    destroy_hash_table(&table1);
    destroy_hash_table(&table2);

    return 0;
}
```

### Key Features:

- **Dynamic Memory Management**: The code dynamically manages memory for two hash tables, allowing custom initial sizes and resizing as needed.
- **Thread Safety**: Each bucket has its own mutex to minimize contention. This approach uses mutexes over spinlocks because they provide a better balance between performance and resource usage under high concurrency scenarios.
- **Custom Hash Functions and Equality Comparators**: The implementation allows users to specify custom hash functions and equality comparators, defaulting to standard implementations if none are provided.
- **Resizing Mechanism**: The tables automatically resize when the load factor exceeds a threshold (set at 0.75).
- **Error Handling**: Graceful handling of memory allocation failures with appropriate error messages and program termination.
- **Logging and Monitoring**: A simple print function (`print_hash_table`) is included for basic monitoring, which could be expanded into more comprehensive logging as needed.

This code provides a robust foundation for managing hash tables concurrently in C. Adjustments can be made to further optimize performance based on specific use cases or deployment environments.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
    int *key_ref;
} Record;

typedef struct MemoryPool {
    void *blocks;
    size_t block_size;
    size_t num_blocks;
    size_t used_blocks;
    pthread_mutex_t lock; // Mutex for thread safety
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool *pool = (MemoryPool *)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->blocks = malloc(block_size * num_blocks);
    if (!pool->blocks) {
        free(pool);
        return NULL;
    }

    pool->block_size = block_size;
    pool->num_blocks = num_blocks;
    pool->used_blocks = 0;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void* allocate_from_pool(MemoryPool *pool) {
    if (pool->used_blocks >= pool->num_blocks) {
        return NULL; // Pool is full
    }

    pthread_mutex_lock(&pool->lock);
    void *block = ((char *)pool->blocks + pool->used_blocks * pool->block_size);
    pool->used_blocks++;
    pthread_mutex_unlock(&pool->lock);

    return block;
}

void* reallocate_memory_pool(MemoryPool *pool, size_t new_num_blocks) {
    if (new_num_blocks <= pool->num_blocks) return NULL;

    void *new_blocks = realloc(pool->blocks, pool->block_size * new_num_blocks);
    if (!new_blocks) return NULL;

    pthread_mutex_lock(&pool->lock);
    pool->blocks = new_blocks;
    pool->num_blocks = new_num_blocks;
    pthread_mutex_unlock(&pool->lock);

    return new_blocks;
}

void initialize_memory(long num_offsets, int min_val, int max_val) {
    MemoryPool *offset_pool = create_memory_pool(sizeof(long), num_offsets);
    if (!offset_pool) { printf("Failed to allocate memory pool for offsets\n"); return; }

    long *offsets = (long *)malloc(num_offsets * sizeof(long));
    if (!offsets) { 
        free(offset_pool->blocks); 
        free(offset_pool); 
        return; 
    }

    MemoryPool *key_pool = create_memory_pool(sizeof(int), num_offsets);
    if (!key_pool) { 
        free(offsets); 
        free(offset_pool->blocks); 
        free(offset_pool); 
        return; 
    }

    int *keys = (int *)malloc(num_offsets * sizeof(int));
    if (!keys) { 
        free(offsets); 
        free(key_pool->blocks); 
        free(key_pool); 
        free(offset_pool->blocks); 
        free(offset_pool);
        return; 
    }

    MemoryPool *record_pool = create_memory_pool(sizeof(Record), num_offsets);
    if (!record_pool) { 
        free(offsets); 
        free(keys); 
        free(key_pool->blocks); 
        free(key_pool); 
        free(offset_pool->blocks); 
        free(offset_pool);
        return; 
    }

    Record *records = (Record *)malloc(num_offsets * sizeof(Record));
    if (!records) { 
        free(offsets); 
        free(keys); 
        free(record_pool->blocks); 
        free(record_pool); 
        free(key_pool->blocks); 
        free(key_pool);
        free(offset_pool->blocks); 
        free(offset_pool);
        return; 
    }

    int global_sum = 0;
    srand(time(NULL));

    for (long i = 0; i < num_offsets; ++i) {
        offsets[i] = allocate_from_pool(offset_pool) ? i : -1;
        keys[i] = allocate_from_pool(key_pool) ? i : -1;

        Record *record = allocate_from_pool(record_pool);
        if (!record) {
            printf("Memory pool exhausted, reallocating...\n");
            reallocate_memory_pool(record_pool, record_pool->num_blocks * 2);

            if (!reallocate_memory_pool(record_pool, record_pool->num_blocks * 2)) {
                printf("Failed to reallocate memory pool for records\n");
                break;
            }

            continue; // Retry allocation
        }

        int range = max_val - min_val + 1;
        int rand_value = (rand() % range) + min_val;

        if ((global_sum > INT_MAX - rand_value)) {
            printf("Integer overflow detected, capping to INT_MAX\n");
            rand_value = INT_MAX - global_sum;
        }

        record->value = global_sum += rand_value;
        record->key_ref = &keys[allocate_from_pool(key_pool) ? i : 0];
    }

    // Clean up
    free(offsets);
    free(keys);
    free(record_pool->blocks);
    free(record_pool);
    free(key_pool->blocks);
    free(key_pool);
    free(offset_pool->blocks);
    free(offset_pool);
}

int main() {
    initialize_memory(100, 1, 10); // Example usage
    return 0;
}
