['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <math.h>

typedef struct Record {
    int key;
    int value;
} Record;

typedef struct Summary {
    double average;
    double stddev;
    size_t count;
} Summary;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    Summary* summaries;
    size_t capacity;
} RecordCollection;

void initRecordCollection(RecordCollection* collection, size_t initial_capacity) {
    collection->head = NULL;
    pthread_mutex_init(&collection->lock, NULL);
    collection->summaries = (Summary*)malloc(initial_capacity * sizeof(Summary));
    collection->capacity = initial_capacity;
}

int addRecord(RecordCollection* collection, int key, int value) {
    pthread_mutex_lock(&collection->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&collection->lock);
        return -1; // Memory allocation failure
    }

    new_node->record.key = key;
    new_node->record.value = value;

    size_t count = 0, sum = 0;
    Node* current = collection->head;
    while (current) {
        sum += current->record.value;
        if (current->record.key == key) {
            break;
        }
        current = current->next;
        ++count;
    }

    double avg = count > 0 ? ((double)sum / count) : 0.0;

    new_node->next = collection->head;
    collection->head = new_node;

    if (key < collection->capacity) {
        Summary* summary = &collection->summaries[key];
        size_t n = ++summary->count;
        double delta = value - summary->average;
        summary->average += delta / n;

        // Welford's method for online variance calculation
        double mean_diff = value - summary->average;
        summary->stddev = sqrt(((n - 1) * pow(summary->stddev, 2) + delta * mean_diff) / n);
    }

    pthread_mutex_unlock(&collection->lock);
    return 0; // Success
}

void reportSummary(RecordCollection* collection, void (*report_func)(int key, double average, double stddev)) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->capacity; ++i) {
        if (collection->summaries[i].count > 0) {
            report_func(i, collection->summaries[i].average, collection->summaries[i].stddev);
        }
    }

    pthread_mutex_unlock(&collection->lock);
}

void freeRecordCollection(RecordCollection* collection) {
    Node* current = collection->head;
    while (current) {
        Node* next_node = current->next;
        free(current);
        current = next_node;
    }

    pthread_mutex_destroy(&collection->lock);
    free(collection->summaries);
}

int main() {
    RecordCollection collection;
    initRecordCollection(&collection, 10);

    addRecord(&collection, 1, 100);
    addRecord(&collection, 2, 200);
    addRecord(&collection, 1, 150); // Updating existing key

    reportSummary(&collection, [](int key, double average, double stddev) {
        printf("Key: %d, Average: %.2f, Stddev: %.2f\n", key, average, stddev);
    });

    freeRecordCollection(&collection);

    return 0;
}
```

