import java.util.Arrays;

#define MAX_PACKET_SIZE 4096
#define BUFFER_SIZE (64 * 1024) // 64KB buffer size

typedef struct {
    uint32_t timestamp;
    size_t packet_size;
    uint8_t* data;
    uint16_t checksum;
