int initializeNetworkPackets(const char* remote_address, int port, size_t max_packet_rate, double timeout_seconds) {
    ConcurrentHashMap<Long, Packet> packetStore = new ConcurrentHashMap<>();
    SocketChannel socketChannel;

    try {
        socketChannel = SocketChannel.open();
        InetSocketAddress address = new InetSocketAddress(remote_address, port);
        socketChannel.configureBlocking(false);
        socketChannel.socket().setSoTimeout((int)(timeout_seconds * 1000));
        if (!socketChannel.connect(address)) {
            throw new IOException("Connection to remote server failed.");
        }

        while (true) {
            ByteBuffer buffer = ByteBuffer.allocate(BUFFER_SIZE);
            int bytesRead;

            try {
                bytesRead = socketChannel.read(buffer);
                if (bytesRead > 0) {
                    handleIncomingData(buffer.array(), bytesRead, packetStore, max_packet_rate);
                }
            } catch (IOException e) {
                fprintf(stderr, "Error reading from channel: %s\n", e.getMessage());
                return -1;
            }

            if (System.currentTimeMillis() - startTime > timeout_seconds * 1000) {
                break; // Handle the timeout scenario
            }
        }
    } catch (IOException e) {
        fprintf(stderr, "Failed to establish connection: %s\n", e.getMessage());
        return -2;
    } finally {
        if (socketChannel != null) {
            try {
                socketChannel.close();
            } catch (IOException e) { /* Ignore */ }
        }
    }

    // Convert ConcurrentHashMap to dynamic array of packets
    Packet* packetArray = malloc(packetStore.size() * sizeof(Packet));
    int index = 0;
    for (Packet packet : packetStore.values()) {
        if (index < MAX_PACKET_SIZE && packet.packet_size <= MAX_PACKET_SIZE) {
            packetArray[index++] = packet;
        } else {
            free(packet.data);
            fprintf(stderr, "Invalid packet size detected.\n");
        }
    }

    return index; // Return number of valid packets received
}

void handleIncomingData(byte[] data, int bytesRead, ConcurrentHashMap<Long, Packet> packetStore, size_t max_packet_rate) {
    for (int i = 0; i < bytesRead;) {
        if (i + sizeof(PacketHeader) > bytesRead) break;

        PacketHeader header;
        memcpy(&header, &data[i], sizeof(PacketHeader));

        if (!isValidChecksum(data, header.checksum)) continue;

        int packetSize = header.packet_size;
        if (packetSize > MAX_PACKET_SIZE || i + packetSize > bytesRead) {
            fprintf(stderr, "Packet size out of bounds or incomplete.\n");
            continue;
        }

        Packet packet = new Packet();
        packet.timestamp = header.timestamp;
        packet.packet_size = packetSize;
        packet.data = Arrays.copyOfRange(data, i + sizeof(PacketHeader), i + packetSize);
        packet.checksum = header.checksum;

        packetStore.put(packet.timestamp, packet);

        // Handle out-of-order packets and logging
        if (!isSequential(packet.timestamp)) {
            reorderPacket(packet);
            logOutOfOrderPacket(packet.timestamp);
        }

        i += sizeof(PacketHeader) + packet.packet_size;
    }
}

