    long *offsets;
    int *keys;
    Record *records;
    size_t size; // Keep track of the allocated size for cleanup
} DataArrays;

// Function to dynamically allocate memory and initialize arrays
DataArrays* create_data_arrays(size_t num_elements) {
    if (num_elements == 0) return NULL;

    // Allocate memory for offsets, keys, and records
    long *offsets = (long *)malloc(num_elements * sizeof(long));
    int *keys = (int *)malloc(num_elements * sizeof(int));
    Record *records = (Record *)malloc(num_elements * sizeof(Record));

    if (!offsets || !keys || !records) {
        // Handle allocation failure
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Initialize arrays with sample data or zeros
    for (size_t i = 0; i < num_elements; ++i) {
        offsets[i] = (long)i;  // Example initialization

        keys[i] = (int)i;      // Example initialization

        records[i].value = (int)i;  // Example initialization

        // Allocate memory for each record's string and initialize it
        char *str = (char *)malloc(20); // Example size
        if (!str) {
            // Handle allocation failure, free previously allocated memory
            for (size_t j = 0; j < i; ++j) {
                free(records[j].string_ptr);
            }
            free(offsets);
            free(keys);
            free(records);
            return NULL;
        }

        snprintf(str, 20, "String %zu", i); // Example string
        records[i].string_ptr = str;
    }

    // Package into a single structure and return
    DataArrays *data_arrays = (DataArrays *)malloc(sizeof(DataArrays));
    if (!data_arrays) {
        free(offsets);
        free(keys);
        for (size_t i = 0; i < num_elements; ++i) {
            free(records[i].string_ptr);
        }
        free(records);
        return NULL;
    }

    data_arrays->offsets = offsets;
    data_arrays->keys = keys;
    data_arrays->records = records;
    data_arrays->size = num_elements;

    return data_arrays;
}

// Function to free the allocated memory
void free_data_arrays(DataArrays *data_arrays) {
    if (!data_arrays) return;

    for (size_t i = 0; i < data_arrays->size; ++i) {
        free(data_arrays->records[i].string_ptr);
    }
    free(data_arrays->offsets);
    free(data_arrays->keys);
    free(data_arrays->records);
    free(data_arrays);
}
