int add_packet(PacketArray *array, const Packet *packet);
int validate_packet(const Packet *packet);
void resize_packet_array(PacketArray *array);

void initialize_packet_array(PacketArray *array, size_t initial_capacity, size_t max_memory_usage) {
    array->packets = malloc(initial_capacity * sizeof(Packet*));
    if (!array->packets) {
        log_info("Failed to allocate memory for packets.");
        return;
    }

    array->capacity = initial_capacity;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
    array->max_memory_usage = max_memory_usage;

    log_info("PacketArray initialized with capacity: " + std::to_string(initial_capacity));
}

int add_packet(PacketArray *array, const Packet *packet) {
    if (!validate_packet(packet)) {
        log_info("Invalid packet encountered.");
        return 0;
    }

    pthread_mutex_lock(&array->lock);

    // Resize if necessary
    if (array->count == array->capacity || 
        (array->packets[array->count] && sizeof(Packet) + packet->packet_size > array->max_memory_usage)) {
        resize_packet_array(array);
    }

    Packet *new_packet = malloc(sizeof(Packet));
    if (!new_packet) {
        pthread_mutex_unlock(&array->lock);
        log_info("Failed to allocate memory for new packet.");
        return 0;
    }

    memcpy(new_packet, packet, sizeof(Packet));
    new_packet->data = malloc(packet->packet_size);
    if (new_packet->data) {
        memcpy(new_packet->data, packet->data, packet->packet_size);
    } else {
        free(new_packet);
        pthread_mutex_unlock(&array->lock);
        log_info("Failed to allocate memory for packet data.");
        return 0;
    }

    array->packets[array->count++] = new_packet;

    pthread_mutex_unlock(&array->lock);

    log_info("Packet added successfully.");
    return 1;
}

int validate_packet(const Packet *packet) {
    // Example validation: non-zero timestamp and packet size
    if (packet->timestamp == 0 || packet->packet_size == 0) {
        return 0; // Invalid packet
    }
    return 1; // Valid packet
}

void resize_packet_array(PacketArray *array) {
    size_t new_capacity = array->capacity * 2;
    Packet **new_packets = realloc(array->packets, new_capacity * sizeof(Packet*));

    if (!new_packets) {
        log_info("Failed to reallocate memory for packets.");
        return;
    }

    memset(new_packets + array->capacity, 0, (new_capacity - array->capacity) * sizeof(Packet*));

    array->packets = new_packets;
    array->capacity = new_capacity;

    log_info("PacketArray resized to capacity: " + std::to_string(new_capacity));
}
