#define MAX_COUNT 10000
#define RNTI_MIN 0x0001
#define RNTI_MAX 0xFFFF

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        uint8_t CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int is_valid_rnti(uint16_t rnti) {
    return (rnti >= RNTI_MIN && rnti <= RNTI_MAX);
}

void print_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
}

uint16_t find_largest_integer(int *array, int size) {
    if (size == 0) return UINT16_MAX; // Or another indicative value for empty array

    uint16_t largest = 0;
    for (int i = 0; i < size; ++i) {
        if ((uint16_t)array[i] > largest) {
            largest = (uint16_t)array[i];
        }
    }
    return largest;
}

void validate_data_structures(NFAPI_CRC_INDICATION_PDU_T *pdus, int count) {
    for (int i = 0; i < count; ++i) {
        if (!is_valid_rnti(pdus[i].RNTI)) {
            print_error("Invalid RNTI value detected");
            exit(EXIT_FAILURE);
        }
        // Add more validation rules as necessary
    }
}

void read_and_process_input(NFAPI_CRC_INDICATION_PDU_T **pdus) {
    int *integers = malloc(MAX_COUNT * sizeof(int));
    if (!integers) {
        print_error("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    int count = 0;
    while (scanf("%d", &integers[count]) == 1 && count < MAX_COUNT) {
        // Check for non-integer input
        if (ferror(stdin)) {
            clearerr(stdin);
            print_error("Non-integer value encountered");
            break;
        }
        ++count;
    }

    *pdus = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!(*pdus)) {
        free(integers);
        print_error("Memory allocation failed for PDUs");
        exit(EXIT_FAILURE);
    }

    uint16_t rnti_set[MAX_COUNT] = {0};
    int unique_count = 0;

    for (int i = 0; i < count; ++i) {
        if (!rnti_set[integers[i]]) {
            (*pdus)[unique_count].RX_UE_INFORMATION_TAG = (uint16_t)integers[i];
            do {
                (*pdus)[unique_count].RNTI = rand() % ((RNTI_MAX + 1) - RNTI_MIN) + RNTI_MIN;
            } while (!is_valid_rnti((*pdus)[unique_count].RNTI) || rnti_set[(*pdus)[unique_count].RNTI]);

            (*pdus)[unique_count].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
            rnti_set[integers[i]] = (*pdus)[unique_count].RNTI;
            ++unique_count;
        }
    }

    if (unique_count == 0) {
        print_error("No valid structures created");
        free(integers);
        free(*pdus);
        *pdus = NULL;
        return;
    }

    validate_data_structures(*pdus, unique_count);

    uint16_t largest_integer = find_largest_integer(integers, count);
    printf("Largest integer: %u\n", largest_integer);

    free(integers);
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T *pdus = NULL;
    read_and_process_input(&pdus);

    if (pdus) {
        // Use the populated PDUs as needed
        free(pdus);
    }

    return 0;
}
