#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Entry {
    char* name;
    int priority;
} Entry;

typedef struct Node {
    Entry entry;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t node_size;
} DynamicList;

DynamicList* create_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;
    list->head = NULL;
    list->node_size = sizeof(Node);
    return list;
}

void free_entry(Entry* entry) {
    free(entry->name);
}

void delete_list(DynamicList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free_entry(&current->entry);
        free(current);
        current = next;
    }
    free(list);
}

Node* create_node(const char* name, int priority) {
    Node* node = (Node*)malloc(list->node_size);
    if (!node) return NULL;

    node->entry.name = strdup(name);
    if (!node->entry.name) {
        free(node);
        return NULL;
    }

    node->entry.priority = priority;
    node->next = NULL;
    return node;
}

int insert_entry(DynamicList* list, const char* name, int priority) {
    Node** current = &list->head;
    while (*current && ((*current)->entry.priority < priority ||
                       ((*current)->entry.priority == priority &&
                        strcmp((*current)->entry.name, name) <= 0))) {
        current = &(*current)->next;
    }

    Node* new_node = create_node(name, priority);
    if (!new_node) return -1;

    new_node->next = *current;
    *current = new_node;
    return 0;
}

int delete_entry(DynamicList* list, const char* name) {
    Node** current = &list->head;
    while (*current && strcmp((*current)->entry.name, name) != 0) {
        current = &(*current)->next;
    }

    if (!*current) return -1;

    Node* to_delete = *current;
    *current = to_delete->next;
    free_entry(&to_delete->entry);
    free(to_delete);
    return 0;
}

int modify_entry(DynamicList* list, const char* old_name, const char* new_name, int new_priority) {
    Node** current = &list->head;
    while (*current && strcmp((*current)->entry.name, old_name) != 0) {
        current = &(*current)->next;
    }

    if (!*current) return -1;

    free_entry(&(*current)->entry);
    (*current)->entry.name = strdup(new_name);
    if (!(*current)->entry.name) return -1;
    (*current)->entry.priority = new_priority;

    // Re-sort the list
    Node* node_to_move = *current;
    *current = node_to_move->next;
    free(node_to_move);

    insert_entry(list, new_name, new_priority);
    return 0;
}

Node* search_entry(DynamicList* list, const char* name) {
    Node* current = list->head;
    while (current) {
        if (strcmp(current->entry.name, name) == 0) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void update_list_from_source(DynamicList* list, const char** names, int* priorities, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        insert_entry(list, names[i], priorities[i]);
    }
}

int main() {
    DynamicList* list = create_list();
    if (!list) return -1;

    update_list_from_source(list, (const char*[]){"Alice", "Bob"}, (int[]){2, 3}, 2);

    Node* found = search_entry(list, "Alice");
    if (found) printf("Found: %s with priority %d\n", found->entry.name, found->entry.priority);

    modify_entry(list, "Alice", "Alicia", 1);
    delete_entry(list, "Bob");

    delete_list(list);
    return 0;
}
