// Function to check metadata validity and compute average pixel values
int validateAndComputeMetadata(ImageMetadata *metadata, float *average_pixel_value) {
    if (!metadata || !metadata->image_data || metadata->width <= 0 || metadata->height <= 0) {
        return -1; // Invalid metadata
    }

    unsigned long total_pixels = (unsigned long)metadata->width * metadata->height;
    unsigned char *data = metadata->image_data;

    if (!total_pixels || !data) {
        return -2; // Failed to compute due to invalid image data or dimensions
    }

    float sum = 0.0f;
    for (unsigned long i = 0; i < total_pixels; ++i) {
        sum += data[i];
    }

    *average_pixel_value = sum / total_pixels;
    return 0; // Success
}

// Function to recursively scan directory and process image files
void* processImageFile(void *arg) {
    ProcessParams *params = (ProcessParams *)arg;
    const char *directory = params->directory;

    // Use third-party library to list files in the directory
    FileList *file_list = third_party_library_get_file_list(directory);

    if (!file_list) {
        fprintf(stderr, "Failed to retrieve file list for directory: %s\n", directory);
        return NULL;
    }

    int num_files = third_party_library_get_file_count(file_list);

    ImageMetadata *image_metadata_array = (ImageMetadata *)malloc(sizeof(ImageMetadata) * num_files);
    if (!image_metadata_array) {
        fprintf(stderr, "Memory allocation failed for image metadata array\n");
        free(file_list);
        return NULL;
    }

    float average_pixel_value;
    int valid_count = 0;

    pthread_mutex_lock(&lock);
    for (int i = 0; i < num_files; ++i) {
        char *file_path = third_party_library_get_file_path(file_list, i);

        ImageMetadata metadata;
        if (!third_party_library_extract_metadata(file_path, &metadata)) {
            fprintf(stderr, "Error extracting metadata for file: %s\n", file_path);
            free(file_path); // Assuming third-party library allocates the path
            continue;
        }

        if (validateAndComputeMetadata(&metadata, &average_pixel_value) == 0) {
            image_metadata_array[valid_count++] = metadata; // Copy valid metadata
        } else {
            fprintf(stderr, "Invalid metadata for file: %s\n", file_path);
        }

        free(file_path); // Free path allocated by third-party library
    }
    pthread_mutex_unlock(&lock);

    // Handle system load and resource utilization adjustments here if needed

    // Output results or further process them as necessary

    free(image_metadata_array);
    third_party_library_free_file_list(file_list);
    return NULL;
}

void processImageMetadata(const char *directory_path) {
    ProcessParams params = { .directory = directory_path, .thread_count = MAX_THREADS };

    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; ++i) {
        if (pthread_create(&threads[i], NULL, processImageFile, &params)) {
            fprintf(stderr, "Error creating thread %d\n", i);
        }
    }

    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    pthread_mutex_destroy(&lock);
}
