#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <stdint.h>

#define INITIAL_CAPACITY 10

typedef struct {
    int value;
} record_t;

typedef struct {
    long offset;
    int key;
    record_t data;
} entry_t;

typedef struct {
    entry_t *entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    uint64_t total_sum; // Use uint64_t to prevent overflow
    pthread_key_t local_storage_key;
} record_set_t;

void init_record_set(record_set_t *set) {
    set->entries = (entry_t *)malloc(INITIAL_CAPACITY * sizeof(entry_t));
    set->capacity = INITIAL_CAPACITY;
    set->count = 0;
    set->total_sum = 0;
    pthread_mutex_init(&set->lock, NULL);
    pthread_key_create(&set->local_storage_key, free);
}

void cleanup_record_set(record_set_t *set) {
    free(set->entries);
    pthread_mutex_destroy(&set->lock);
    pthread_key_delete(set->local_storage_key);
}

entry_t* get_entry_from_local_storage(record_set_t *set) {
    entry_t *local_entry = (entry_t *)pthread_getspecific(set->local_storage_key);
    if (!local_entry) {
        local_entry = &set->entries[set->count % set->capacity];
        pthread_setspecific(set->local_storage_key, local_entry);
    }
    return local_entry;
}

void add_record(record_set_t *set, long offset, int key, int min_range, int max_range) {
    entry_t *entry = get_entry_from_local_storage(set);

    if (set->count >= set->capacity) {
        size_t new_capacity = set->capacity * 2;
        entry_t *new_entries = (entry_t *)realloc(set->entries, new_capacity * sizeof(entry_t));
        if (!new_entries) return; // handle allocation failure
        set->entries = new_entries;
        set->capacity = new_capacity;
    }

    pthread_mutex_lock(&set->lock);

    entry->offset = offset;
    entry->key = key;

    int range = max_range - min_range + 1;
    entry->data.value = (int)((double)rand() / RAND_MAX * range) + min_range;

    uint64_t new_sum = set->total_sum + entry->data.value;
    if (new_sum < set->total_sum) { // handle overflow
        printf("Warning: Integer overflow detected.\n");
        return; 
    }
    set->total_sum = new_sum;

    set->count++;

    pthread_mutex_unlock(&set->lock);
}

uint64_t get_total_sum(record_set_t *set) {
    pthread_mutex_lock(&set->lock);
    uint64_t sum = set->total_sum;
    pthread_mutex_unlock(&set->lock);
    return sum;
}
