#define MAX_RECORDS 1000
#define MAX_KEYS 200

typedef struct {
    int value;
    time_t timestamp;
} Record;

typedef struct {
    long *offsets;
    size_t num_offsets;
    int *keys1;
    size_t num_keys1;
    int *keys2;
    size_t num_keys2;
    Record *records;
    size_t num_records;
    int64_t rolling_sum;
    pthread_mutex_t lock;
} DataStructure;

static inline int safe_add(int a, int b) {
    if (a > INT_MAX - b) return 0; // Overflow case
    return a + b;
}

DataStructure* initialize_data_structure(size_t num_offsets, size_t num_keys1, size_t num_keys2) {
    DataStructure *ds = malloc(sizeof(DataStructure));
    if (!ds) {
        fprintf(stderr, "Memory allocation failed for DataStructure\n");
        return NULL;
    }

    ds->offsets = calloc(num_offsets, sizeof(long));
    ds->keys1 = calloc(num_keys1, sizeof(int));
    ds->keys2 = calloc(num_keys2, sizeof(int));
    ds->records = calloc(MAX_RECORDS, sizeof(Record)); // Pre-allocate max records
    if (!ds->offsets || !ds->keys1 || !ds->keys2 || !ds->records) {
        fprintf(stderr, "Memory allocation failed for internal structures\n");
        free(ds->offsets);
        free(ds->keys1);
        free(ds->keys2);
        free(ds->records);
        free(ds);
        return NULL;
    }

    ds->num_offsets = num_offsets;
    ds->num_keys1 = num_keys1;
    ds->num_keys2 = num_keys2;
    ds->num_records = 0;
    ds->rolling_sum = 0;

    pthread_mutex_init(&ds->lock, NULL);

    // Initialize records with random values
    srand((unsigned)time(NULL));
    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        int range = safe_add(ds->rolling_sum % 100 + 1, -safe_add(1, ds->num_records * 2));
        if (range <= 0) range = 1;

        pthread_mutex_lock(&ds->lock);
        Record *record = &ds->records[i];
        record->value = rand() % range + 1; // Random value within the range
        record->timestamp = time(NULL);

        ds->rolling_sum = safe_add(ds->rolling_sum, record->value);
        if (i == MAX_RECORDS - 1 && ds->num_records < i) {
            // Resize records array as needed
            size_t new_size = ds->num_records + MAX_RECORDS;
            Record *new_records = realloc(ds->records, new_size * sizeof(Record));
            if (!new_records) {
                fprintf(stderr, "Memory reallocation failed for records\n");
                pthread_mutex_unlock(&ds->lock);
                break; // Exit loop on failure
            }
            ds->records = new_records;
        }
        ++ds->num_records;
        pthread_mutex_unlock(&ds->lock);

        if (i >= MAX_RECORDS - 1) break; // Prevent overflow in the for-loop
    }

    return ds;
}

void free_data_structure(DataStructure *ds) {
    if (!ds) return;
    free(ds->offsets);
    free(ds->keys1);
    free(ds->keys2);
    free(ds->records);
    pthread_mutex_destroy(&ds->lock);
    free(ds);
}

// Serialization and logging functions would be implemented similarly
