['Below is a C implementation for managing a shared data structure accessed by multiple threads. It includes thread-safe operations, dynamic array management, and performance optimizations as per the given constraints:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 100
#define MAX_RECORDS 1000

typedef struct {
    int value;
    size_t key_index;
    size_t offset_index;
} Record;

typedef struct {
    long *offsets;
    int *keys;
    Record *records;
    size_t record_count;
    size_t capacity;
    int total_sum;
    pthread_mutex_t mutex;
} SharedDataStructure;

// Function prototypes
SharedDataStructure* create_shared_data_structure(size_t initial_capacity);
void free_shared_data_structure(SharedDataStructure *sds);
int init_records(SharedDataStructure *sds, int min_value, int max_value);
int add_record(SharedDataStructure *sds, int key, long offset, int value);
void remove_oldest_record(SharedDataStructure *sds);

// Helper function to get a random number within a range
int get_random(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Create and initialize the shared data structure
SharedDataStructure* create_shared_data_structure(size_t initial_capacity) {
    SharedDataStructure *sds = malloc(sizeof(SharedDataStructure));
    if (!sds) return NULL;

    sds->offsets = calloc(initial_capacity, sizeof(long));
    sds->keys = calloc(initial_capacity, sizeof(int));
    sds->records = calloc(initial_capacity, sizeof(Record));
    sds->record_count = 0;
    sds->capacity = initial_capacity;
    sds->total_sum = 0;

    pthread_mutex_init(&sds->mutex, NULL);

    return sds;
}

// Free the shared data structure
void free_shared_data_structure(SharedDataStructure *sds) {
    if (sds) {
        free(sds->offsets);
        free(sds->keys);
        free(sds->records);
        pthread_mutex_destroy(&sds->mutex);
        free(sds);
    }
}

// Initialize records with random values
int init_records(SharedDataStructure *sds, int min_value, int max_value) {
    pthread_mutex_lock(&sds->mutex);

    for (size_t i = 0; i < sds->record_count; ++i) {
        int value = get_random(min_value, max_value);
        if (value + sds->total_sum > INT_MAX || value + sds->total_sum < INT_MIN) {
            fprintf(stderr, "Integer overflow detected\n");
            pthread_mutex_unlock(&sds->mutex);
            return -1;
        }
        sds->records[i].value = value;
        sds->total_sum += value;

        // Log the operation
        printf("Initialized record %zu with value %d. Total sum: %d\n", i, value, sds->total_sum);
    }

    pthread_mutex_unlock(&sds->mutex);
    return 0;
}

// Add a new record to the shared data structure
int add_record(SharedDataStructure *sds, int key, long offset, int value) {
    pthread_mutex_lock(&sds->mutex);

    if (sds->record_count >= sds->capacity) {
        // Resize arrays
        size_t new_capacity = sds->capacity * 2;
        sds->offsets = realloc(sds->offsets, new_capacity * sizeof(long));
        sds->keys = realloc(sds->keys, new_capacity * sizeof(int));
        sds->records = realloc(sds->records, new_capacity * sizeof(Record));

        if (!sds->offsets || !sds->keys || !sds->records) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&sds->mutex);
            return -1;
        }

        sds->capacity = new_capacity;
    }

    size_t index = sds->record_count++;
    sds->offsets[index] = offset;
    sds->keys[index] = key;

    int adjusted_value = get_random(0, value); // Adjust based on external logic
    if (adjusted_value + sds->total_sum > INT_MAX || adjusted_value + sds->total_sum < INT_MIN) {
        fprintf(stderr, "Integer overflow detected\n");
        pthread_mutex_unlock(&sds->mutex);
        return -1;
    }

    sds->records[index].value = adjusted_value;
    sds->records[index].key_index = index;
    sds->records[index].offset_index = index;
    sds->total_sum += adjusted_value;

    // Log the operation
    printf("Added record %zu with value %d. Total sum: %d\n", index, adjusted_value, sds->total_sum);

    if (sds->record_count > MAX_RECORDS) {
        remove_oldest_record(sds);
    }

    pthread_mutex_unlock(&sds->mutex);
    return 0;
}

// Remove the oldest record from the shared data structure
void remove_oldest_record(SharedDataStructure *sds) {
    if (sds->record_count == 0) return;

    size_t oldest_index = sds->record_count - MAX_RECORDS;
    int value_to_remove = sds->records[oldest_index].value;

    // Adjust total sum
    sds->total_sum -= value_to_remove;

    // Log the operation
    printf("Removed record %zu with value %d. Total sum: %d\n", oldest_index, value_to_remove, sds->total_sum);

    for (size_t i = oldest_index; i < sds->record_count - 1; ++i) {
        sds->records[i] = sds->records[i + 1];
        sds->offsets[i] = sds->offsets[i + 1];
        sds->keys[i] = sds->keys[i + 1];
    }

    --sds->record_count;
}

int main() {
    srand(time(NULL));

    SharedDataStructure *sds = create_shared_data_structure(INITIAL_CAPACITY);
    if (!sds) {
        fprintf(stderr, "Failed to create shared data structure\n");
        return EXIT_FAILURE;
    }

    // Simulate adding records
    for (int i = 0; i < 1500; ++i) {
        add_record(sds, rand() % 100, rand(), 10);
    }

    // Initialize record values
    init_records(sds, 1, 10);

    free_shared_data_structure(sds);
    return EXIT_SUCCESS;
}
```

### Key Features:

- **Thread Safety**: Uses `pthread_mutex_t` to ensure thread-safe operations.
- **Dynamic Memory Management**: Resizes arrays as needed while minimizing allocations and deallocations.
- **Overflow Handling**: Checks for integer overflow when updating the total sum.
- **Logging**: Logs each operation with details about record initialization and addition.
- **Scalability**: Efficiently manages memory usage and scales gracefully with increasing records.']

