// Render email template safely with input sanitization to prevent XSS attacks.
char* render_email_template_safe(const char *template, const char *user_input) {
    // Simple example: Replace {user} in the template with sanitized user input
    size_t tmpl_len = strlen(template);
    size_t input_len = strlen(user_input);

    // Allocate memory for resulting string
    char *result = malloc(tmpl_len + input_len + 1);  // +1 for null-terminator
    if (!result) return NULL;

    const char *src = template;
    char *dst = result;

    while (*src) {
        if (strncmp(src, "{user}", 6) == 0) {  // Found placeholder
            src += 6; // Skip the placeholder

            // Copy and sanitize user input
            while (*src && *src != '}') {
                if ((*src >= 'a' && *src <= 'z') || (*src >= 'A' && *src <= 'Z') ||
                    (*src >= '0' && *src <= '9')) {  // Allow alphanumeric characters
                    *dst++ = *src++;
                }
            }

            src++; // Skip the closing '}'
        } else {
            *dst++ = *src++;
        }
    }

    *dst = '\0';  // Null-terminate result string
    return result;
}

