// Define Packet structure with timestamp, size, and data pointer.
struct Packet {
    int64_t timestamp;
    size_t packet_size;
    char* data;

    Packet(int64_t ts, size_t sz) : timestamp(ts), packet_size(sz), data(new char[sz]) {}
    ~Packet() { delete[] data; }
};

// Union-Find Structure
class UnionFind {
private:
    std::unordered_map<int, int> parent;
public:
    int find(int x) {
        if (parent[x] != x)
            parent[x] = find(parent[x]);
        return parent[x];
    }

    void unite(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX != rootY) parent[rootY] = rootX;
    }
};

// Memory Pool
class MemoryPool {
private:
    std::mutex pool_mutex;
    std::queue<std::unique_ptr<char[]>> free_list;

public:
    char* allocate(size_t size) {
        std::lock_guard<std::mutex> lock(pool_mutex);
        if (free_list.empty()) return new char[size];
        auto ptr = std::move(free_list.front());
        free_list.pop();
        return ptr.release();
    }

    void deallocate(char* ptr, size_t /*size*/) {
        std::lock_guard<std::mutex> lock(pool_mutex);
        free_list.emplace(ptr);
    }
};

// Global memory pool
MemoryPool g_memory_pool;

// External logging service (stub)
void log(const std::string& message) {
    // Implementation to send logs to an external service.
}

// Packet Processing Function
std::pair<int, double> processPackets(int* identifiers, size_t count) {
    UnionFind uf;
    std::unordered_map<int, std::vector<Packet*>> packets_by_id;

    for (size_t i = 0; i < count; ++i)
        uf.parent[identifiers[i]] = identifiers[i];

    auto start_time = std::chrono::high_resolution_clock::now();

    // Simulate packet receiving with validation
    std::vector<Packet*> valid_packets;
    try {
        for (size_t i = 0; i < count; ++i) {
            int id = identifiers[i];

            if (!uf.parent.count(id)) continue;

            auto packet_data = g_memory_pool.allocate(1024); // Example size
            Packet* packet = new Packet(std::chrono::duration_cast<std::chrono::milliseconds>(
                std::chrono::system_clock::now().time_since_epoch()).count(),
                1024);

            packet->data[0] = 'A'; // Simulating data assignment

            valid_packets.push_back(packet);
            packets_by_id[id].push_back(packet);
        }
    } catch (const std::bad_alloc&) {
        log("Out of memory error occurred");
    }

    int disjoint_pairs_count = 0;
    std::mutex counter_mutex;

    auto validate_pair = [&](int id1, int id2) {
        if (uf.find(id1) != uf.find(id2)) {
            std::lock_guard<std::mutex> lock(counter_mutex);
            ++disjoint_pairs_count;
            auto validation_time = std::chrono::duration_cast<std::chrono::milliseconds>(
                std::chrono::high_resolution_clock::now() - start_time).count();
            std::cout << "Disjoint pair (" << id1 << ", " << id2 
                      << ") validated in " << validation_time << " ms\n";
        }
    };

    // Multithreaded disjoint pair checking
    std::vector<std::thread> threads;
    for (auto& [id, packets] : packets_by_id) {
        for (size_t i = 0; i < packets.size(); ++i) {
            for (size_t j = i + 1; j < packets.size(); ++j) {
                int id1 = id, id2 = id; // Simplified assumption
                threads.emplace_back(validate_pair, id1, id2);
            }
        }
    }

    for (auto& th : threads) th.join();

    auto end_time = std::chrono::high_resolution_clock::now();
    double total_time = std::chrono::duration_cast<std::chrono::milliseconds>(
        end_time - start_time).count() / 1000.0;

    // Cleanup
    for (Packet* p : valid_packets) {
        g_memory_pool.deallocate(p->data, p->packet_size);
        delete p;
    }

    return {disjoint_pairs_count, total_time};
}

