#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <limits.h>

typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    size_t num_records;
    long total_sum;
    pthread_mutex_t lock;
} shared_data;

void initialize_shared_data(shared_data *data, size_t num_records) {
    data->num_records = num_records;
    data->offsets = malloc(num_records * sizeof(long));
    data->keys = malloc(num_records * sizeof(int));
    data->records = malloc(num_records * sizeof(record));
    data->total_sum = 0;

    if (!data->offsets || !data->keys || !data->records) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&data->lock, NULL);

    for (size_t i = 0; i < num_records; ++i) {
        data->offsets[i] = rand(); // Example offset value
        data->keys[i] = rand() % 100; // Example key value
        data->records[i].value = 0;
    }
}

void *initialize_record(void *arg) {
    shared_data *data = (shared_data *)arg;

    for (size_t i = 0; i < data->num_records; ++i) {
        pthread_mutex_lock(&data->lock);

        long current_sum = data->total_sum;
        int range_min = 1;
        int range_max = 100 + (int)(current_sum % 50); // Dynamic range adjustment

        if (range_max > INT_MAX - range_min) {
            fprintf(stderr, "Potential integer overflow detected\n");
            pthread_mutex_unlock(&data->lock);
            continue;
        }

        data->records[i].value = rand() % (range_max - range_min + 1) + range_min;
        data->total_sum += data->records[i].value;

        if (data->total_sum > LONG_MAX) {
            fprintf(stderr, "Total sum overflow detected\n");
            data->total_sum -= data->records[i].value; // Rollback
        }

        pthread_mutex_unlock(&data->lock);
    }
    return NULL;
}

void run_initialization(shared_data *data, size_t num_threads) {
    pthread_t threads[num_threads];

    for (size_t i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, initialize_record, data)) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }

    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }
}

void cleanup_shared_data(shared_data *data) {
    free(data->offsets);
    free(data->keys);
    free(data->records);
    pthread_mutex_destroy(&data->lock);
}

int main() {
    srand(time(NULL));

    size_t num_records = 1000;
    size_t num_threads = 4;

    shared_data data;
    initialize_shared_data(&data, num_records);

    run_initialization(&data, num_threads);

    printf("Total sum: %ld\n", data.total_sum);

    cleanup_shared_data(&data);

    return 0;
}
```

### Key Features:
- **Memory Management**: Uses dynamic memory allocation and ensures proper deallocation.
- **Concurrency**: Utilizes pthreads with mutexes to manage concurrent access to shared resources.
- **Dynamic Range Adjustment**: Adjusts the random value range based on cumulative sums.
- **Error Handling**: Checks for potential integer overflow scenarios.
- **Logging**: Basic error logging using `fprintf` and `perror`.
- **Scalability**: Designed to handle multiple threads, allowing parallel processing.

### Considerations:
- This implementation does not include database integration or advanced logging mechanisms. These would require additional libraries and more complex setup.
- The mutex lock is used to ensure thread safety when updating shared resources like `total_sum` and individual records.']

