typedef struct {
    DataObject **data_objects;
    int count;
    int capacity;
    pthread_mutex_t lock;
    size_t total_resource_size;
} DataCollection;

DataCollection* init_data_collection(int initial_capacity) {
    DataCollection* collection = (DataCollection*)malloc(sizeof(DataCollection));
    if (!collection) return NULL;

    collection->data_objects = (DataObject**)calloc(initial_capacity, sizeof(DataObject*));
    collection->count = 0;
    collection->capacity = initial_capacity;
    pthread_mutex_init(&collection->lock, NULL);
    collection->total_resource_size = 0;

    return collection;
}

int resize_data_collection(DataCollection *collection) {
    int new_capacity = collection->capacity * 2;
    DataObject **new_objects = (DataObject**)realloc(collection->data_objects, new_capacity * sizeof(DataObject*));
    if (!new_objects) return -1;

    collection->data_objects = new_objects;
    collection->capacity = new_capacity;
    return 0;
}

void add_data_object(DataCollection *collection, Resource *resource, int value) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count == collection->capacity) {
        if (resize_data_collection(collection) != 0) {
            pthread_mutex_unlock(&collection->lock);
            return;
        }
    }

    DataObject *new_obj = (DataObject*)malloc(sizeof(DataObject));
    if (!new_obj) {
        pthread_mutex_unlock(&collection->lock);
        return;
    }

    new_obj->timestamp = time(NULL);
    new_obj->status_flag = 0; // Set based on predefined conditions
    new_obj->resource = resource;
    collection->total_resource_size += resource->size;

    if (collection->count > 0) {
        int total_value = 0;
        for (int i = 0; i < collection->count; ++i) {
            total_value += collection->data_objects[i]->value;
        }
        new_obj->value = (total_value + value) / (collection->count + 1);
    } else {
        new_obj->value = value;
    }

    collection->data_objects[collection->count++] = new_obj;

    pthread_mutex_unlock(&collection->lock);
}

void remove_data_object(DataCollection *collection, int index) {
    pthread_mutex_lock(&collection->lock);

    if (index < 0 || index >= collection->count) {
        pthread_mutex_unlock(&collection->lock);
        return;
    }

    DataObject *obj_to_remove = collection->data_objects[index];
    collection->total_resource_size -= obj_to_remove->resource->size;

    free(obj_to_remove->resource); // Assuming resource needs to be freed
    free(obj_to_remove);

    for (int i = index; i < collection->count - 1; ++i) {
        collection->data_objects[i] = collection->data_objects[i + 1];
    }
    collection->data_objects[--collection->count] = NULL;

    pthread_mutex_unlock(&collection->lock);
}

void aggregate_summary_statistics(DataCollection *collection) {
    // Implement aggregation and reporting logic
}

void free_data_collection(DataCollection *collection) {
    for (int i = 0; i < collection->count; ++i) {
        free(collection->data_objects[i]->resource);
        free(collection->data_objects[i]);
    }
    free(collection->data_objects);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int main() {
    DataCollection *collection = init_data_collection(10);

    Resource resource1 = {.type = "TypeA", .size = 100};
    add_data_object(collection, &resource1, 42);

    // Further operations...

