typedef struct {
    float value;
    Timestamp timestamp;
    DeviceMetadata metadata;
} SensorReading;

typedef struct {
    SensorReading *readings;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    float running_total;
    float min_value;
    float max_value;
} SensorCollection;

void init_sensor_collection(SensorCollection *collection, size_t initial_capacity) {
    collection->readings = (SensorReading *)malloc(initial_capacity * sizeof(SensorReading));
    if (!collection->readings) {
        fprintf(stderr, "Failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }
    collection->capacity = initial_capacity;
    collection->count = 0;
    collection->running_total = 0.0f;
    collection->min_value = FLT_MAX;
    collection->max_value = -FLT_MAX;
    pthread_mutex_init(&collection->lock, NULL);
}

void resize_sensor_collection(SensorCollection *collection, size_t new_capacity) {
    pthread_mutex_lock(&collection->lock);

    SensorReading *new_readings = (SensorReading *)realloc(collection->readings, new_capacity * sizeof(SensorReading));
    if (!new_readings && new_capacity > 0) {
        fprintf(stderr, "Failed to reallocate memory\n");
        exit(EXIT_FAILURE);
    }

    collection->capacity = new_capacity;
    collection->readings = new_readings;

    pthread_mutex_unlock(&collection->lock);
}

void add_sensor_reading(SensorCollection *collection, float value, Timestamp timestamp, DeviceMetadata metadata) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count >= collection->capacity) {
        resize_sensor_collection(collection, collection->capacity * 2);
    }

    SensorReading new_reading = { .value = value, .timestamp = timestamp, .metadata = metadata };

    collection->readings[collection->count++] = new_reading;

    // Update running total
    collection->running_total += value;

    // Update min and max values
    if (value < collection->min_value) {
        collection->min_value = value;
    }
    if (value > collection->max_value) {
        collection->max_value = value;
    }

    pthread_mutex_unlock(&collection->lock);
}

void free_sensor_collection(SensorCollection *collection) {
    pthread_mutex_lock(&collection->lock);

    free(collection->readings);
    collection->readings = NULL;
    collection->capacity = 0;
    collection->count = 0;

    pthread_mutex_destroy(&collection->lock);
}

int main() {
    SensorCollection collection;
    init_sensor_collection(&collection, 10);

    Timestamp ts = { .timestamp = time(NULL), .sequence_number = 1 };
    DeviceMetadata metadata = { .signal_strength = 5.0f, .temperature_compensation = 2.0f };

    add_sensor_reading(&collection, 12.3f, ts, metadata);
    add_sensor_reading(&collection, 4.5f, ts, metadata);

    printf("Running total: %.2f\n", collection.running_total);
    printf("Min value: %.2f\n", collection.min_value);
    printf("Max value: %.2f\n", collection.max_value);

    free_sensor_collection(&collection);

    return 0;
}
