#include <pthread.h>
#include <time.h>

typedef struct {
    char status;
    float value;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;  // Mutex for thread safety
} RecordArray;

// Function to initialize the random number generator with a seed
void init_random(unsigned int seed) {
    srand(seed);
}

// Function to generate a random float within a range [min, max]
float rand_float(float min, float max) {
    return min + (max - min) * ((float)rand() / RAND_MAX);
}

// Initialize the record array with a specified capacity
int init_record_array(RecordArray *array, size_t initial_capacity) {
    if (!array) return -1;

    pthread_mutex_init(&array->lock, NULL);

    array->records = (Record *)malloc(initial_capacity * sizeof(Record));
    if (!array->records) return -2;  // Memory allocation failed

    array->capacity = initial_capacity;
    array->count = 0;

    return 0;  // Success
}

// Resize the record array when capacity is reached
int resize_record_array(RecordArray *array, size_t new_capacity) {
    if (!array || new_capacity <= array->capacity) return -1;

    Record *new_records = (Record *)realloc(array->records, new_capacity * sizeof(Record));
    if (!new_records) return -2;  // Memory allocation failed

    array->records = new_records;
    array->capacity = new_capacity;

    return 0;  // Success
}

// Add a record to the array with thread-safe operation
int add_record(RecordArray *array, char status, float value_min, float value_max) {
    if (!array) return -1;

    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 4;
        int resize_result = resize_record_array(array, new_capacity);
        if (resize_result != 0) {
            pthread_mutex_unlock(&array->lock);
            return -3;  // Resize failed
        }
    }

    float value = rand_float(value_min, value_max);

    array->records[array->count].status = status;
    array->records[array->count].value = value;

    array->count++;

    pthread_mutex_unlock(&array->lock);

    return 0;  // Success
}

// Free the resources of the record array
void free_record_array(RecordArray *array) {
    if (array) {
        pthread_mutex_destroy(&array->lock);
        free(array->records);
        array->records = NULL;
        array->capacity = 0;
        array->count = 0;
    }
}

int main() {
    RecordArray array;

    int init_result = init_record_array(&array, 4);
    if (init_result != 0) {
        fprintf(stderr, "Failed to initialize record array\n");
        return -1;
    }

    // Example usage
    init_random(42);  // Seed for reproducibility

    add_record(&array, 'A', 0.0f, 100.0f);
    add_record(&array, 'B', 50.0f, 150.0f);

    free_record_array(&array);

    return 0;
}
