    size_t structure_count = 0;

    for (size_t i = 0; i < num_ints; i += 3) {
        if (structure_count >= NUM_NFAPI_STRUCTS) break;

        NFAPI_CRC_INDICATION_PDU_T *pdu = &nfaapi_structures[structure_count];
        pdu->RX_UE_INFORMATION_TAG = ints[i];

        unsigned int rnti_candidate = ints[i + 1];
        if (!validate_rnti(rnti_candidate)) {
            log_message("RNTI out of range. Skipping structure.");
            free(nfaapi_structures);
            return;
        }

        // Ensure RNTI uniqueness
        for (size_t j = 0; j < i + 1; j += 3) {
            if (ints[j + 1] == rnti_candidate && used_rntis[ints[j + 1]]) break;
        } else {
            pdu->RNTI = rnti_candidate;
            used_rntis[rnti_candidate] = 1;
        }

        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = generate_crcflag();

        structure_count++;
    }

    if (structure_count == 0) {
        log_message("No valid structures created.");
        free(nfaapi_structures);
        return;
    }

    // Validation and processing of NFAPI structures
    for (size_t i = 0; i < structure_count; ++i) {
        if (!validate_rnti(nfaapi_structures[i].RNTI)) {
            log_message("Validation failed: RNTI out of range.");
            break;
        }
        // Additional CRCFLAG validation logic can be added here
    }

    // Log the number of successfully created structures
    log_message("Successfully processed and validated structures.");

    free(nfaapi_structures);
}

int main() {
