```java
import java.nio.ByteBuffer;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.SocketChannel;
import java.util.concurrent.*;
import java.util.logging.Level;
import java.util.logging.Logger;

public class ServiceManager {
    private static final Logger logger = Logger.getLogger(ServiceManager.class.getName());
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
    private final Semaphore stopSemaphore = new Semaphore(1, true);
    private volatile boolean running = false;
    private int maxStopFrequencyPerMinute = 10; // Configurable
    private long lastStopTime = -1;

    public static void main(String[] args) {
        ServiceManager manager = new ServiceManager();
        manager.startManagingService();
    }

    public void startManagingService() {
        scheduler.scheduleAtFixedRate(this::manageService, 0, 10, TimeUnit.SECONDS);
    }

    private void manageService() {
        try {
            if (canStopService()) {
                stopSemaphore.acquire();
                stopService("Scheduled Stop");
            }
        } catch (InterruptedException e) {
            logger.log(Level.SEVERE, "Thread interrupted", e);
        }
    }

    private boolean canStopService() {
        long currentTime = System.currentTimeMillis();
        if (lastStopTime == -1 || currentTime - lastStopTime >= 60000 / maxStopFrequencyPerMinute) {
            lastStopTime = currentTime;
            return true;
        }
        return false;
    }

    private void stopService(String reason) throws InterruptedException {
        running = false;
        long startTime = System.currentTimeMillis();

        try (SocketChannel channel = openSocketChannel()) {
            ByteBuffer buffer = ByteBuffer.allocate(4096);
            // Simulate sending a message with the reason and metrics
            buffer.put(("Stopping Service: " + reason).getBytes());
            buffer.flip();
            while (buffer.hasRemaining()) {
                channel.write(buffer);
            }
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Failed to stop service or send message", e);
        }

        long duration = System.currentTimeMillis() - startTime;
        logger.info("Service stopped: Duration=" + duration + "ms");
    }

    private SocketChannel openSocketChannel() throws IOException {
        Selector selector = Selector.open();
        SocketChannel channel = SocketChannel.open();
        channel.configureBlocking(false);
        SelectionKey key = channel.register(selector, SelectionKey.OP_CONNECT);

        // Assume connection setup here
        return channel;
    }

    public void startService() {
        running = true;
        logger.info("Service started");
        // Simulate service operation
    }

    public static class ServiceFailureException extends Exception {
        public ServiceFailureException(String message) {
            super(message);
        }
    }

    private void handleError(ServiceFailureException e) {
        logger.log(Level.SEVERE, "Error in service management", e);
    }

    // Additional methods for dynamic adjustments and packet handling
}
```

### Key Points:
