        pthread_join(obj->management_thread, NULL); 
        while (--obj->algorithm_count >= 0) free(obj->algorithms[obj->algorithm_count]);
        free(obj->algorithms);
        pthread_mutex_destroy(&obj->cache->lock);
        free(obj->cache);
        free(obj);
        return EXIT_FAILURE;
    }

    struct pcap_pkthdr header;
    const u_char *packet_data;

    while ((packet_data = pcap_next(handle, &header)) != NULL) {
        process_packet(obj, packet_data, &header);
    }

    // Cleanup
