    pthread_join(obj->management_thread, NULL); 
    while (--obj->algorithm_count >= 0) free(obj->algorithms[obj->algorithm_count]);
    free(obj->algorithms);
    pthread_mutex_destroy(&obj->cache->lock);
    free(obj->cache);
    free(obj);

    pcap_close(handle);

    return EXIT_SUCCESS;
}
