['Here's a C function that manages a dynamic collection of `record` structures with the considerations you've outlined:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    int value;
} Record;

typedef struct {
    Record *records;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} RecordCollection;

void init_record_collection(RecordCollection *collection) {
    collection->records = NULL;
    collection->count = 0;
    collection->capacity = 0;
    pthread_mutex_init(&collection->lock, NULL);
}

int rand_range(int min, int max) {
    return rand() % (max - min + 1) + min;
}

void expand_capacity(RecordCollection *collection) {
    size_t new_capacity = collection->capacity == 0 ? 10 : collection->capacity * 2;
    Record *new_records = realloc(collection->records, new_capacity * sizeof(Record));
    if (new_records) {
        collection->records = new_records;
        collection->capacity = new_capacity;
    } else {
        perror("Failed to expand capacity");
        exit(EXIT_FAILURE);
    }
}

int add_record(RecordCollection *collection, long offset, int key, int min_value, int max_value) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count == collection->capacity) {
        expand_capacity(collection);
    }

    Record new_record;
    new_record.offset = offset;
    new_record.key = key;
    new_record.value = rand_range(min_value, max_value);

    collection->records[collection->count++] = new_record;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

void free_record_collection(RecordCollection *collection) {
    pthread_mutex_lock(&collection->lock);
    free(collection->records);
    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
}

int main() {
    RecordCollection collection;
    init_record_collection(&collection);

    // Example usage
    for (int i = 0; i < 20; ++i) {
        add_record(&collection, i * 100, i, 1, 10);
    }

    for (size_t i = 0; i < collection.count; ++i) {
        printf("Record %zu: offset=%ld, key=%d, value=%d\n", i, collection.records[i].offset,
               collection.records[i].key, collection.records[i].value);
    }

    free_record_collection(&collection);
    return 0;
}
```

### Key Features:

- **Thread Safety**: Uses `pthread_mutex_t` to ensure thread-safe operations.
- **Dynamic Memory Management**: Efficiently manages memory with dynamic resizing using `realloc`.
- **Random Value Initialization**: Initializes the value field with a random number within a specified range.
- **Modular Design**: Functions are modular, making maintenance and updates easier.
- **Error Handling**: Handles errors in memory allocation gracefully.

This implementation considers scalability, performance, and ease of use while ensuring thread safety and efficient memory management.']

