#include <pthread.h>

// Define the Record structure
typedef struct {
    long value;
    int key;
    long *offsetPtr;
} Record;

// Function prototypes
long generateRandomLong(long min, long max);
void manageMemory(Record **records, size_t initialCapacity, const int *keysArray, size_t nKeys, 
                  const long *offsetsArray, size_t nOffsets, long minValue, long maxValue);

// Mutex for thread safety
pthread_mutex_t recordMutex = PTHREAD_MUTEX_INITIALIZER;

// Function to generate a random long value within the specified range
long generateRandomLong(long min, long max) {
    return (rand() % (max - min + 1)) + min;
}

// Function to manage memory and operations on Record array
void manageMemory(Record **records, size_t initialCapacity, const int *keysArray, size_t nKeys, 
                  const long *offsetsArray, size_t nOffsets, long minValue, long maxValue) {
    // Error handling for invalid inputs
    if (!records || !keysArray || !offsetsArray || initialCapacity == 0 || nKeys == 0 || nOffsets == 0)
        return;

    pthread_mutex_lock(&recordMutex);

    *records = (Record *)malloc(initialCapacity * sizeof(Record));
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed for Record array\n");
        exit(EXIT_FAILURE);
    }

    long *offsetsCopy = (long *)malloc(nOffsets * sizeof(long));
    if (!offsetsCopy) {
        free(*records);
        fprintf(stderr, "Memory allocation failed for offsets copy\n");
        exit(EXIT_FAILURE);
    }
    memcpy(offsetsCopy, offsetsArray, nOffsets * sizeof(long));

    size_t currentCapacity = initialCapacity;
    size_t recordCount = 0;

    // Main loop to populate records
    while (1) {
        if (recordCount >= currentCapacity) {
            size_t newCapacity = currentCapacity * 2;
            Record *tempRecords = (Record *)realloc(*records, newCapacity * sizeof(Record));
            if (!tempRecords) {
                free(*records);
                free(offsetsCopy);
                fprintf(stderr, "Memory reallocation failed for Record array\n");
                exit(EXIT_FAILURE);
            }
            *records = tempRecords;
            currentCapacity = newCapacity;
        }

        (*records)[recordCount].value = generateRandomLong(minValue, maxValue);
        (*records)[recordCount].key = keysArray[recordCount % nKeys];
        (*records)[recordCount].offsetPtr = &offsetsCopy[recordCount % nOffsets];

        recordCount++;

        // Termination condition for demonstration purposes (replace with actual condition)
        if (recordCount >= 1000) break; 
    }

    printf("Memory usage: Current capacity = %zu, Used records = %zu\n", currentCapacity, recordCount);

    pthread_mutex_unlock(&recordMutex);
}

// Function to free all allocated memory
void freeRecords(Record **records, long *offsetsCopy) {
    if (records && *records) {
        free(*records);
        *records = NULL;
    }
    if (offsetsCopy) {
        free(offsetsCopy);
    }
}
```

This code defines a `manageMemory` function that handles dynamic allocation and resizing of a `Record` array. It ensures thread safety using mutexes, manages memory allocations, and provides error handling for invalid inputs or failed memory operations. The function also tracks and reports memory usage statistics.']

