public class StateLoader {

    private static final String DEFAULT_THEME_DIR = "/default/theme/directory";
    private static Map<String, byte[]> themeCache = new ConcurrentHashMap<>();
    private static long lastDnsQueryTime = 0;
    private static final long DNS_RATE_LIMIT_MS = 1000; // Rate limit in milliseconds

    public MoSTState loadStateFromFile(String filePath) {
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filePath))) {
            Object obj = ois.readObject();
            if (obj instanceof MoSTState) {
                return (MoSTState) obj;
            }
        } catch (IOException | ClassNotFoundException e) {
            logError("Failed to load or deserialize state object", e);
        }
        return null;
    }

    public void ensureDefaultThemeDir() {
        String themeDir = System.getProperty("theme.dir", DEFAULT_THEME_DIR);
        // Set the default theme directory if not defined
        if (Files.notExists(Paths.get(themeDir))) {
            System.setProperty("theme.dir", DEFAULT_THEME_DIR);
        }
    }

    public byte[] loadImageFromCache(String imageName) throws IOException {
        String cachePath = Paths.get(System.getProperty("theme.dir"), imageName).toString();
        if (!themeCache.containsKey(cachePath)) {
            try (InputStream is = new FileInputStream(cachePath)) {
                themeCache.put(cachePath, is.readAllBytes());
            }
        }
        return themeCache.get(cachePath);
    }

    public u_char[] resolveHostnameToIP(String hostname) {
        long currentTime = System.currentTimeMillis();
        if (currentTime - lastDnsQueryTime < DNS_RATE_LIMIT_MS) {
            logError("Rate limit exceeded for DNS queries");
            return null;
        }
        try {
            InetAddress inetAddress = InetAddress.getByName(hostname);
            lastDnsQueryTime = currentTime;
            return inetAddress.getAddress();
        } catch (IOException e) {
            logError("Failed to resolve hostname", e);
            return null;
        }
    }

    private void logError(String message, Exception e) {
