void addMessage(MessageArray *messageArray, Message *message) {
    pthread_mutex_lock(&messageArray->lock);

    // Resize array if needed
    size_t new_count = messageArray->count + 1;
    Message **new_messages = realloc(messageArray->messages, new_count * sizeof(Message*));
    if (!new_messages) {
