['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_PACKET_SIZE 1500
#define INITIAL_CAPACITY 10

typedef struct {
    time_t timestamp;
    size_t packet_size;
    char *data;
} Packet;

typedef struct {
    Packet **packets;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    int received_count;
    int dropped_count;
    size_t max_packet_size;
    pthread_cond_t flush_condition;
    time_t retention_duration;
    pthread_t flush_thread;
    int active_flushing;
} PacketCache;

PacketCache *create_packet_cache(size_t max_packet_size, time_t retention_duration) {
    PacketCache *cache = malloc(sizeof(PacketCache));
    if (!cache) return NULL;

    cache->packets = calloc(INITIAL_CAPACITY, sizeof(Packet *));
    if (!cache->packets) {
        free(cache);
        return NULL;
    }

    cache->capacity = INITIAL_CAPACITY;
    cache->count = 0;
    pthread_mutex_init(&cache->lock, NULL);
    pthread_cond_init(&cache->flush_condition, NULL);

    cache->received_count = 0;
    cache->dropped_count = 0;
    cache->max_packet_size = max_packet_size;
    cache->retention_duration = retention_duration;
    cache->active_flushing = 0;

    // Start flush thread
    if (pthread_create(&cache->flush_thread, NULL, packet_cache_flusher, cache) != 0) {
        free(cache->packets);
        free(cache);
        return NULL;
    }

    return cache;
}

void *packet_cache_flusher(void *arg) {
    PacketCache *cache = (PacketCache *)arg;
    while (1) {
        pthread_mutex_lock(&cache->lock);
        while (!cache->active_flushing && cache->count > 0) {
            time_t current_time = time(NULL);
            for (size_t i = 0; i < cache->count;) {
                if ((current_time - cache->packets[i]->timestamp) > cache->retention_duration) {
                    free(cache->packets[i]->data);
                    free(cache->packets[i]);
                    memmove(&cache->packets[i], &cache->packets[i + 1], 
                            (cache->count - i - 1) * sizeof(Packet *));
                    cache->count--;
                } else {
                    i++;
                }
            }
        }

        if (cache->active_flushing && cache->count == 0) {
            cache->active_flushing = 0;
            pthread_cond_signal(&cache->flush_condition);
        }
        pthread_mutex_unlock(&cache->lock);

        sleep(5); // Flush every 5 seconds
    }
}

int add_packet(PacketCache *cache, const char *source_ip, const char *dest_ip, const void *data, size_t data_size) {
    if (data_size > cache->max_packet_size) return -1;

    pthread_mutex_lock(&cache->lock);

    // Resize if necessary
    if (cache->count == cache->capacity) {
        size_t new_capacity = cache->capacity * 2;
        Packet **new_packets = realloc(cache->packets, new_capacity * sizeof(Packet *));
        if (!new_packets) {
            pthread_mutex_unlock(&cache->lock);
            return -1;
        }
        memset(new_packets + cache->capacity, 0, (new_capacity - cache->capacity) * sizeof(Packet *));
        cache->packets = new_packets;
        cache->capacity = new_capacity;
    }

    Packet *packet = malloc(sizeof(Packet));
    if (!packet) {
        pthread_mutex_unlock(&cache->lock);
        return -1;
    }

    packet->timestamp = time(NULL);
    packet->packet_size = data_size;
    packet->data = malloc(data_size);
    if (!packet->data) {
        free(packet);
        pthread_mutex_unlock(&cache->lock);
        return -1;
    }

    memcpy(packet->data, data, data_size);

    // Log the packet details
    printf("Packet from %s to %s: size %zu bytes\n", source_ip, dest_ip, data_size);

    cache->packets[cache->count++] = packet;
    cache->received_count++;

    pthread_mutex_unlock(&cache->lock);
    return 0;
}

void drop_packet(PacketCache *cache) {
    pthread_mutex_lock(&cache->lock);
    if (cache->count > 0) {
        Packet *packet = cache->packets[--cache->count];
        free(packet->data);
        free(packet);
        cache->dropped_count++;
    }
    pthread_mutex_unlock(&cache->lock);
}

void activate_flushing(PacketCache *cache) {
    pthread_mutex_lock(&cache->lock);
    if (!cache->active_flushing) {
        cache->active_flushing = 1;
        pthread_cond_signal(&cache->flush_condition);
    }
    pthread_mutex_unlock(&cache->lock);
}

int main() {
    PacketCache *cache = create_packet_cache(MAX_PACKET_SIZE, 60); // Example retention duration of 60 seconds

    if (!cache) {
        fprintf(stderr, "Failed to initialize packet cache\n");
        return EXIT_FAILURE;
    }

    char data[MAX_PACKET_SIZE] = {0};
    strcpy(data, "Example Packet Data");

    add_packet(cache, "192.168.1.1", "192.168.1.2", data, strlen(data));

    // Example of activating flushing
    activate_flushing(cache);

    // Clean up
    pthread_mutex_destroy(&cache->lock);
    pthread_cond_destroy(&cache->flush_condition);
    free(cache->packets);
    free(cache);

    return EXIT_SUCCESS;
}
