void cache_insert(const Resource *resource, const char *type) {
    pthread_rwlock_wrlock(&cache_manager.rwlock);

    for (int i = 0; i < CACHE_SIZE; i++) {
        if (!cache_manager.cache[i].type || strcmp(cache_manager.cache[i].type, type) != 0) {
            free(cache_manager.cache[i].type);
            cache_manager.cache[i].type = strdup(type);
            cache_manager.cache[i].size = resource->size;
            cache_manager.cache[i].last_accessed = time(NULL);

            pthread_rwlock_unlock(&cache_manager.rwlock);
            return;
        }
    }

    // Evict the least recently used entry if necessary
    int lru_index = 0;
    time_t oldest_time = cache_manager.cache[0].last_accessed;

    for (int i = 1; i < CACHE_SIZE; i++) {
        if (cache_manager.cache[i].last_accessed < oldest_time) {
            oldest_time = cache_manager.cache[i].last_accessed;
            lru_index = i;
        }
    }

    free(cache_manager.cache[lru_index].type);
    cache_manager.cache[lru_index].type = strdup(type);
    cache_manager.cache[lru_index].size = resource->size;
    cache_manager.cache[lru_index].last_accessed = time(NULL);

    pthread_rwlock_unlock(&cache_manager.rwlock);
}

