// Resource structure definition
struct Resource {
    std::string type;
    size_t size;

    Resource(const std::string& t, size_t s) : type(t), size(s) {}
};

// Data object containing timestamp, status flag, and resource reference
struct Data {
    using Clock = std::chrono::system_clock;
    struct TimePoint { 
        std::chrono::time_point<Clock> point;
        explicit TimePoint(const Clock::time_point& tp) : point(tp) {}
    };

    TimePoint timestamp;
    bool statusFlag;
    Resource* resource;

    Data(Resource* res, bool status = false)
        : timestamp(Clock::now()), statusFlag(status), resource(res) {}

    ~Data() { delete resource; }
};

// Forward list manager class for handling data objects
class DataManager {
public:
    using dataList_t = std::forward_list<Data>;

private:
    dataList_t dataList;
    size_t totalResourceSize = 0;
    std::mutex mtx;

public:
    // Function to add a new Data object
    void addObject(const Resource& res, bool status) {
        std::lock_guard<std::mutex> lock(mtx);
        auto newData = std::make_unique<Data>(new Resource(res), status);
        dataList.push_front(std::move(*newData));
        totalResourceSize += res.size;

        // Check resource limits and alert if needed
        checkResourceLimits();
    }

    // Function to update status flags based on predefined conditions
    void updateStatusFlags() {
        std::lock_guard<std::mutex> lock(mtx);
        for (auto& data : dataList) {
            // Example condition: toggle the status flag
            data.statusFlag = !data.statusFlag;
        }
    }

    // Function to handle dynamic resizing and efficient resource management
    void resizeAndReallocate() {
        std::lock_guard<std::mutex> lock(mtx);
        // Implement strategies for resizing and reallocation if necessary
    }

    // Serialize current state of the data objects
    void serializeState(std::ostream& os) const {
        std::lock_guard<std::mutex> lock(mtx);
        for (const auto& data : dataList) {
            os << "Timestamp: "
               << std::chrono::duration_cast<std::chrono::milliseconds>(
                      data.timestamp.point.time_since_epoch())
                   .count()
               << ", Status: " << data.statusFlag
               << ", Resource Type: " << data.resource->type
               << ", Resource Size: " << data.resource->size << '\n';
        }
    }

    // Deserialize state from an input stream
    void deserializeState(std::istream& is) {
        std::lock_guard<std::mutex> lock(mtx);
        dataList.clear();
        totalResourceSize = 0;
        std::string line;

        while (std::getline(is, line)) {
            auto parts = split(line, ',');
            if (parts.size() < 4) continue;

            long long timestampMs = std::stoll(parts[0].substr(12));
            bool statusFlag = parts[1] == "true";
            std::string type = parts[2].substr(17);
            size_t size = std::stoull(parts[3].substr(14));

            auto resource = new Resource(type, size);
            dataList.emplace_front(resource, statusFlag);

            totalResourceSize += size;
        }
    }

private:
    void checkResourceLimits() {
        const size_t limit = 1000; // Example limit
        if (totalResourceSize > limit) {
            std::cerr << "Warning: Resource limits approached!\n";
        }
    }

    static std::vector<std::string> split(const std::string& str, char delimiter) {
        std::vector<std::string> tokens;
        size_t start = 0, end = 0;
        while ((end = str.find(delimiter, start)) != std::string::npos) {
            tokens.push_back(str.substr(start, end - start));
            start = end + 1;
        }
        tokens.push_back(str.substr(start));
        return tokens;
    }

public:
    // Function to insert a string after the first occurrence of another string
    void insertAfterFirstOccurrence(
        std::forward_list<std::string>& list,
        const std::string& target,
        const std::string& insertion) {

        bool inserted = false;

        for (auto it = list.before_begin(); 
             auto currIt = ++it; // Move to next element
             ) {

            if (*currIt == target && !inserted) {
                list.insert_after(currIt, insertion);
                inserted = true;
            }
        }

        if (!inserted) {
            list.push_back(insertion);
        }
    }
};

// Usage example (for illustration purposes)
int main() {
    DataManager manager;

    // Adding some resources
    manager.addObject({"TypeA", 100}, false);
    manager.addObject({"TypeB", 200}, true);

    // Update status flags
    manager.updateStatusFlags();

    // Serialize state to an output stream
    std::ostringstream os;
    manager.serializeState(os);

    // Deserialize from input stream
    std::istringstream is(os.str());
    manager.deserializeState(is);

    // Example usage of inserting strings in a forward list
    std::forward_list<std::string> strList{"apple", "banana", "cherry"};
    DataManager().insertAfterFirstOccurrence(strList, "banana", "blueberry");

    for (const auto& s : strList) {
        std::cout << s << '\n';
    }

    return 0;
}
