#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

typedef struct {
    int key;
    long offset;
    int value;
} record;

typedef struct {
    record *records;
    size_t capacity;
    size_t count;
    int64_t total_value_sum;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} record_collection;

void init_random() {
    srand(time(NULL));
}

int generate_random_value(int avg_value, int min_val, int max_val) {
    // Dynamically adjust range based on average value
    int adjusted_min = avg_value / 2 > min_val ? avg_value / 2 : min_val;
    int adjusted_max = avg_value * 2 < max_val ? avg_value * 2 : max_val;
    return rand() % (adjusted_max - adjusted_min + 1) + adjusted_min;
}

record_collection* create_record_collection(size_t initial_capacity) {
    record_collection *col = malloc(sizeof(record_collection));
    col->records = malloc(initial_capacity * sizeof(record));
    col->capacity = initial_capacity;
    col->count = 0;
    col->total_value_sum = 0;
    pthread_mutex_init(&col->lock, NULL);
    pthread_cond_init(&col->cond, NULL);
    return col;
}

int can_add_record(int64_t current_sum, int value, int64_t limit) {
    int64_t new_sum = current_sum + value;
    // Check for overflow
    if (new_sum < current_sum || new_sum > limit) {
        return 0; // Cannot add without exceeding the limit or causing overflow
    }
    return 1;
}

int add_record(record_collection *col, int key, long offset, int64_t limit, int min_val, int max_val) {
    pthread_mutex_lock(&col->lock);

    while (col->count == col->capacity || 
           (!can_add_record(col->total_value_sum, generate_random_value(0, min_val, max_val), limit))) {
        // Wait for space or permissible value
        pthread_cond_wait(&col->cond, &col->lock);
    }

    int avg_value = col->count > 0 ? (int)(col->total_value_sum / col->count) : 0;
    int value = generate_random_value(avg_value, min_val, max_val);

    if (!can_add_record(col->total_value_sum, value, limit)) {
        pthread_mutex_unlock(&col->lock);
        return -1; // Failed to add due to overflow or limit
    }

    record *new_rec = &col->records[col->count++];
    new_rec->key = key;
    new_rec->offset = offset;
    new_rec->value = value;

    col->total_value_sum += value;

    pthread_cond_signal(&col->cond);
    pthread_mutex_unlock(&col->lock);

    return 0; // Success
}

void handle_data_burst(record_collection *col, int key, long offset, int64_t limit, int min_val, int max_val) {
    while (add_record(col, key, offset, limit, min_val, max_val)) {
        // If adding failed due to overflow or limits, attempt to reallocate
        pthread_mutex_lock(&col->lock);

        size_t new_capacity = col->capacity * 2;
        record *new_records = realloc(col->records, new_capacity * sizeof(record));

        if (new_records) {
            col->records = new_records;
            col->capacity = new_capacity;
            pthread_cond_signal(&col->cond);
        }

        // If reallocation failed, wait and try again
        pthread_mutex_unlock(&col->lock);
        sleep(1); // Backoff to prevent busy waiting
    }
}

void free_record_collection(record_collection *col) {
    free(col->records);
    pthread_mutex_destroy(&col->lock);
    pthread_cond_destroy(&col->cond);
    free(col);
}
