#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <limits.h>

#define MAX_RECORDS 1000
#define MAX_KEYS 500

typedef struct {
    int value;
} Record;

// Thread-safe data structure for rolling average calculation.
typedef struct {
    double sum;
    int count;
    pthread_mutex_t lock;
} RollingAverage;

RollingAverage avg = { .sum = 0, .count = 0 };
pthread_mutex_t avg_lock = PTHREAD_MUTEX_INITIALIZER;

void init_rolling_average(RollingAverage *avg) {
    pthread_mutex_init(&avg->lock, NULL);
}

void update_rolling_average(RollingAverage *avg, int new_value) {
    pthread_mutex_lock(&avg->lock);
    if (avg->count < 100) {
        avg->sum += new_value;
        avg->count++;
    } else {
        avg->sum = avg->sum - (new_value / 100) + new_value;
    }
    pthread_mutex_unlock(&avg->lock);
}

double get_rolling_average(RollingAverage *avg) {
    double result;
    pthread_mutex_lock(&avg->lock);
    result = avg->count ? avg->sum / avg->count : 0;
    pthread_mutex_unlock(&avg->lock);
    return result;
}

// Memory management for arrays
typedef struct {
    long *offsets;
    int *keys;
    Record *records;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

void init_dynamic_array(DynamicArray *array, size_t initial_size) {
    array->offsets = malloc(initial_size * sizeof(long));
    array->keys = malloc(initial_size * sizeof(int));
    array->records = malloc(initial_size * sizeof(Record));
    array->size = initial_size;
    pthread_mutex_init(&array->lock, NULL);
}

void resize_dynamic_array(DynamicArray *array, size_t new_size) {
    pthread_mutex_lock(&array->lock);
    if (new_size > array->size) {
        array->offsets = realloc(array->offsets, new_size * sizeof(long));
        array->keys = realloc(array->keys, new_size * sizeof(int));
        array->records = realloc(array->records, new_size * sizeof(Record));
        array->size = new_size;
    }
    pthread_mutex_unlock(&array->lock);
}

void free_dynamic_array(DynamicArray *array) {
    free(array->offsets);
    free(array->keys);
    free(array->records);
    pthread_mutex_destroy(&array->lock);
}

// Function to initialize and manage memory for arrays
void initialize_and_manage_arrays(DynamicArray *arrays, size_t num_records, size_t num_keys) {
    if (num_records > arrays->size || num_keys > arrays->size) {
        resize_dynamic_array(arrays, MAX(num_records, num_keys));
    }

    srand(time(NULL));

    int sum = 0;
    for (size_t i = 0; i < num_records; ++i) {
        int range_min = 1;
        int range_max = get_rolling_average(&avg) + 10;

        if (range_min >= INT_MAX - 10) {
            fprintf(stderr, "Integer overflow risk detected.\n");
            continue;
        }

        arrays->records[i].value = range_min + rand() % ((range_max < range_min) ? INT_MIN : (range_max - range_min));

        int key_index = i % num_keys; 
        arrays->keys[key_index] = i;

        sum += arrays->records[i].value;
    }

    update_rolling_average(&avg, sum);
}

// Serialization function to save current state
void serialize_state(const DynamicArray *arrays, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file) {
        fwrite(&arrays->size, sizeof(size_t), 1, file);
        fwrite(arrays->offsets, sizeof(long), arrays->size, file);
        fwrite(arrays->keys, sizeof(int), arrays->size, file);
        fwrite(arrays->records, sizeof(Record), arrays->size, file);
        fclose(file);
    }
}

// Deserialization function to load state
void deserialize_state(DynamicArray *arrays, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file) {
        fread(&arrays->size, sizeof(size_t), 1, file);
        resize_dynamic_array(arrays, arrays->size);
        fread(arrays->offsets, sizeof(long), arrays->size, file);
        fread(arrays->keys, sizeof(int), arrays->size, file);
        fread(arrays->records, sizeof(Record), arrays->size, file);
        fclose(file);
    }
}

int main() {
    DynamicArray arrays;
    init_dynamic_array(&arrays, MAX_RECORDS);

    initialize_and_manage_arrays(&arrays, 500, 250);

    serialize_state(&arrays, "state.dat");

    DynamicArray loadedArrays;
    init_dynamic_array(&loadedArrays, MAX_RECORDS);
    deserialize_state(&loadedArrays, "state.dat");

    free_dynamic_array(&arrays);
    free_dynamic_array(&loadedArrays);

    return 0;
}
```

**Explanation of Approach:**
- **Thread Safety:** Used mutexes to ensure thread-safe updates and access to shared data structures like the rolling average.
- **Memory Management:** Dynamic resizing with `realloc` is used to minimize frequent allocations and deallocations. Memory usage efficiency is prioritized by only expanding when necessary.
- **Rolling Average:** Implemented a thread-safe mechanism to maintain a rolling average of sums, dynamically adjusting based on new record values.
- **Serialization/Deserialization:** Functions for saving and loading the state using file I/O to ensure persistence across calls or restarts.
- **Overflow Checks:** Safeguards against potential integer overflows with safe arithmetic operations.']

