struct Packet {
    int timestamp;
    size_t packetSize;
    char* data;

    Packet(int ts, size_t sz) : timestamp(ts), packetSize(sz) {
        data = new char[packetSize];
    }

    ~Packet() {
        delete[] data;
    }
};

class UnionFind {
public:
    std::unordered_map<int, int> parent;

    int find(int x) {
        if (parent[x] != x)
            parent[x] = find(parent[x]);
        return parent[x];
    }

    void unite(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX != rootY) {
            parent[rootY] = rootX;
        }
    }
};

bool isValidPacket(const Packet& packet, const std::unordered_map<int, size_t>& metadata) {
    auto it = metadata.find(packet.timestamp);
    return it != metadata.end() && it->second == packet.packetSize;
}

std::pair<size_t, double> processPackets(
    int networkInterface,
    const std::string& configFilePath,
    int optimizationLevel)
{
    std::unordered_map<int, size_t> metadata;
    std::ifstream configFile(configFilePath);

    if (!configFile.is_open()) {
        std::cerr << "Failed to open configuration file." << std::endl;
        return {0, 0.0};
    }

    int timestamp;
    size_t packetSize;
    while (configFile >> timestamp >> packetSize) {
        metadata[timestamp] = packetSize;
    }

    UnionFind uf;
    std::vector<Packet*> dynamicArray;
    std::mutex vecMutex;
    std::shared_mutex logMutex;

    auto startTime = std::chrono::high_resolution_clock::now();
    size_t disjointCount = 0;
    double totalValidationTime = 0.0;

    // Simulate receiving packets in batches
    for (int i = 0; i < 1000000; ++i) { // Example loop, replace with actual packet reception logic
        int ts = rand() % 10000;
        size_t sz = rand() % 1024 + 1;

        Packet* packet = new Packet(ts, sz);

        {
            std::shared_lock lock(logMutex);
            if (isValidPacket(*packet, metadata)) {
                uf.parent[ts] = ts; // Initialize Union-Find structure
                std::lock_guard<std::mutex> guard(vecMutex);
                dynamicArray.push_back(packet);

                int startID = uf.find(ts); // Simulate another packet with same root ID for testing disjoint pairs
                int endID = (rand() % 2 == 0) ? startID : ts + rand() % 10;

                auto pairStartTime = std::chrono::high_resolution_clock::now();
                uf.unite(startID, endID);
                auto pairEndTime = std::chrono::high_resolution_clock::now();

                if (uf.find(startID) != uf.find(endID)) {
                    ++disjointCount;
                }

                double validationTimeMs = std::chrono::duration<double, std::milli>(pairEndTime - pairStartTime).count();
                totalValidationTime += validationTimeMs;

                // Dynamic adjustment of optimization level
                if (totalValidationTime > 1000) { // Example condition for demonstration purposes
                    --optimizationLevel;
                }
            } else {
                delete packet;
            }
        }
    }

    auto endTime = std::chrono::high_resolution_clock::now();
    double totalTimeMs = std::chrono::duration<double, std::milli>(endTime - startTime).count();

    // Cleanup
    for (auto* pkt : dynamicArray) {
        delete pkt;
    }

    return {disjointCount, totalValidationTime};
}

int main() {
    int networkInterface = 1; // Example identifier
    std::string configFilePath = "config.txt"; // Example file path
    int optimizationLevel = 5; // Example level

