#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a structure for records.
typedef struct {
    long offset;
    int key;
} Record;

// Function to handle errors gracefully.
void handleError(const char *message) {
    fprintf(stderr, "%s\n", message);
    exit(EXIT_FAILURE);
}

// Function to parse the CSV file and initialize records.
Record** parseCSV(const char *filename, size_t *num_records) {
    FILE *file = fopen(filename, "r");
    if (!file) handleError("Error opening file");

    // Buffer for reading lines from the file
    const size_t buffer_size = 1024;
    char buffer[buffer_size];

    // Determine number of records.
    fseek(file, 0, SEEK_END);
    long filesize = ftell(file);
    fseek(file, 0, SEEK_SET);

    *num_records = 0;
    while (fgets(buffer, buffer_size, file)) {
        if (strchr(buffer, '\n')) (*num_records)++;
    }

    // Allocate memory for records.
    Record **records = malloc(*num_records * sizeof(Record *));
    if (!records) handleError("Memory allocation failed");

    fseek(file, 0, SEEK_SET);
    size_t record_index = 0;

    // Set of keys to detect duplicates
    int *key_set = calloc(*num_records, sizeof(int));
    if (!key_set) handleError("Memory allocation for key set failed");

    while (fgets(buffer, buffer_size, file)) {
        char *line = strdup(buffer);
        if (!line) handleError("Strdup failed");

        // Remove newline character
        size_t len = strlen(line);
        if (len > 0 && line[len - 1] == '\n') line[--len] = '\0';

        // Parse offset and key from the CSV line.
        long offset;
        int key;

        if (2 != sscanf(line, "%ld,%d", &offset, &key)) {
            handleError("Malformed CSV entry");
        }

        // Check for duplicate keys within the same record structure
        size_t i = 0;
        while (i < *num_records) {
            if (!records[i]) { // Find an empty slot or a matching offset to replace
                records[i] = malloc(sizeof(Record));
                if (!records[i]) handleError("Memory allocation failed");
                records[i]->offset = offset;
                records[i]->key = key;

                // Check for duplicates
                if (key_set[key]) {
                    free(records[i]);
                    records[i] = NULL; // Invalidate this record
                    free(line);
                    handleError("Duplicate key found");
                } else {
                    key_set[key] = 1;
                    break;
                }
            }
            i++;
        }

        free(line);
    }

    // Cleanup if needed.
    fclose(file);

    return records;
}

// Example usage of the function.
int main() {
    size_t num_records = 0;
    Record **records = parseCSV("data.csv", &num_records);

    for (size_t i = 0; i < num_records; ++i) {
        if (records[i]) { // Print valid records
            printf("Offset: %ld, Key: %d\n", records[i]->offset, records[i]->key);
            free(records[i]);
        }
    }

    free(records);
    return 0;
}
