#define MAX_MEASUREMENTS 500000

typedef enum {
    CELSIUS,
    FAHRENHEIT
} TemperatureUnit;

typedef struct {
    time_t timestamp;
    int locationID;
    float temperatureValue;
    TemperatureUnit unit;
} TemperatureMeasurement;

TemperatureMeasurement* measurements = NULL;
int measurementCount = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void logAnomaly(const char* message) {
    printf("Anomaly detected: %s\n", message);
}

float getRandomFloat(float min, float max) {
    return (float)(rand() / (double)RAND_MAX * (max - min)) + min;
}

TemperatureUnit getRandomUnit() {
    return rand() % 2 == 0 ? CELSIUS : FAHRENHEIT;
}

int isValidTemperature(float temperature) {
    return temperature >= -273.15; // Absolute zero in Celsius
}

void* processStream(void* arg) {
    int sockfd = *(int*)arg;

    while (1) {
        float tempValue;
        if (recv(sockfd, &tempValue, sizeof(tempValue), 0) <= 0) {
            logAnomaly("Network error or packet loss");
            continue;
        }

        pthread_mutex_lock(&lock);

        if (measurementCount >= MAX_MEASUREMENTS) {
            logAnomaly("Buffer overflow");
            pthread_mutex_unlock(&lock);
            break;
        }

        int locationID = rand() % 1000; // Simulate receiving a location ID
        TemperatureMeasurement newMeasure;

        newMeasure.timestamp = time(NULL);
        newMeasure.locationID = locationID;
        newMeasure.temperatureValue = tempValue;
        newMeasure.unit = getRandomUnit();

        if (!isValidTemperature(newMeasure.temperatureValue)) {
            logAnomaly("Out-of-range temperature reading");
            pthread_mutex_unlock(&lock);
            continue;
        }

        for (int i = 0; i < measurementCount; ++i) {
            if (measurements[i].locationID == locationID) {
                logAnomaly("Duplicate location ID detected");
                pthread_mutex_unlock(&lock);
                break;
            }
        }

        measurements[measurementCount++] = newMeasure;

        pthread_mutex_unlock(&lock);
    }

    return NULL;
}

float computeAverageTemperature(TemperatureMeasurement* measurements, int count) {
    float sum = 0.0;
    for (int i = 0; i < count; ++i) {
        if (measurements[i].unit == FAHRENHEIT) {
            // Convert to Celsius
            sum += (measurements[i].temperatureValue - 32) * 5 / 9;
        } else {
            sum += measurements[i].temperatureValue;
        }
    }
    return count > 0 ? sum / count : 0.0f;
}

void handleStream(int sockfd) {
    srand(time(NULL));
    measurements = (TemperatureMeasurement*)malloc(MAX_MEASUREMENTS * sizeof(TemperatureMeasurement));

    pthread_t thread;
    if (pthread_create(&thread, NULL, processStream, &sockfd)) {
        logAnomaly("Failed to create processing thread");
        free(measurements);
        return;
    }

    pthread_join(thread, NULL);

    float averageTemp = computeAverageTemperature(measurements, measurementCount);
    printf("Average Temperature: %.2f\n", averageTemp);

    free(measurements);
}
