    struct sockaddr_in sa;
    return inet_pton(AF_INET, ipAddr, &(sa.sin_addr)) == 1;
}

int isValidMACAddress(const char *macAddr) {
    // Check if MAC address is in the correct format
    int i = 0, len = strlen(macAddr);
    while (i < len) {
        if ((i % 3 == 2 && macAddr[i] != ':') ||
            !isxdigit(macAddr[i]) || 
            ((macAddr[i + 1] == '\0' || macAddr[i + 1] == ':' || macAddr[i + 1] == '-') && i != len - 1)) {
            return 0;
        }
        ++i;
    }
    return (len == 17);
}

