        configs[i].isActive = (rand() / (RAND_MAX + 1.0)) < PROBABILITY_ACTIVE;

        if (!isValidIPAddress(configs[i].ipAddr) || !isValidMACAddress(configs[i].macAddress)) {
            logEvent("Invalid network configuration detected.");
            free(configs);
            pthread_mutex_unlock(&configMutex);
            return NULL;
        }
    }

    FILE *file = fopen(CONFIG_FILE, "w");
    if (!file) {
        logEvent("Failed to open config file for writing.");
        free(configs);
        pthread_mutex_unlock(&configMutex);
        return NULL;
    }

    fprintf(file, "{\n\"networkInterfaces\": [\n");
    for (int i = 0; i < MAX_INTERFACES; ++i) {
        fprintf(file, "  {\"ipAddress\": \"%s\", \"macAddress\": \"%s\", \"isActive\": %d}",
                configs[i].ipAddr, configs[i].macAddress, configs[i].isActive);
        if (i < MAX_INTERFACES - 1) {
            fprintf(file, ",\n");
        }
    }
    fprintf(file, "\n]\n}");

    fclose(file);

    // Implement rollback mechanism and other error handling as needed.

    pthread_mutex_unlock(&configMutex);
    return configs;
}

void cleanupConfigurations(networkConfig *configs) {
    if (configs) {
        free(configs);
    }
}
