// Global mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

unsigned long generateUniqueRNTI(unsigned long *rntiSet, size_t setSize) {
    unsigned long rnti;
    do {
        rnti = rand() % (1UL << 16); // Assuming RNTI is a 16-bit value
    } while (set_bit(rntiSet, rnti));
    return rnti;
}

void set_bit(unsigned long *bitArray, unsigned long bit) {
    size_t index = bit / (sizeof(long) * 8);
    size_t shift = bit % (sizeof(long) * 8);
    bitArray[index] |= (1UL << shift);
}

int is_set(const unsigned long *bitArray, unsigned long bit) {
    size_t index = bit / (sizeof(long) * 8);
    size_t shift = bit % (sizeof(long) * 8);
    return (bitArray[index] & (1UL << shift)) != 0;
}

void initializeDataStructures(size_t numRecords, long **offsets, int **keys, record ***records,
                              NFAPI_CRC_INDICATION_PDU_T ***nfapiCrcIndicationPdus) {
    size_t memoryUsage = sizeof(long) * numRecords + sizeof(int) * numRecords +
                         sizeof(record) * numRecords + sizeof(NFAPI_CRC_INDICATION_PDU_T) * numRecords;

    // Check if the memory usage is within limits
    if (memoryUsage > MEMORY_LIMIT_MB * 1024 * 1024) {
        fprintf(stderr, "Memory limit exceeded.\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&mutex);

    *offsets = malloc(sizeof(long) * numRecords);
    *keys = malloc(sizeof(int) * numRecords);
    *records = malloc(sizeof(record *) * numRecords);
    *nfapiCrcIndicationPdus = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T *) * numRecords);

    if (!*offsets || !*keys || !*records || !*nfapiCrcIndicationPdus) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    unsigned long rntiSet[(1UL << 16) / (sizeof(long) * 8)] = {0};

    for (size_t i = 0; i < numRecords; ++i) {
        (*offsets)[i] = rand() % 1000;
        (*keys)[i] = rand() % 100;

        *records[i] = malloc(sizeof(record));
        if (!*records[i]) {
            fprintf(stderr, "Memory allocation failed for records.\n");
            exit(EXIT_FAILURE);
        }
        (*records[i])->value = rand() % 1000;

        *nfapiCrcIndicationPdus[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!*nfapiCrcIndicationPdus[i]) {
            fprintf(stderr, "Memory allocation failed for nfapiCrcIndicationPdus.\n");
            exit(EXIT_FAILURE);
        }
        (*nfapiCrcIndicationPdus[i])->RX_UE_INFORMATION_TAG = rand() % 1000;
        (*nfapiCrcIndicationPdus[i])->RNTI = generateUniqueRNTI(rntiSet, (1UL << 16) / (sizeof(long) * 8));
        (*nfapiCrcIndiationPdus[i])->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }

    pthread_mutex_unlock(&mutex);
}

void freeDataStructures(size_t numRecords, long *offsets, int *keys,
                        record **records, NFAPI_CRC_INDICATION_PDU_T **nfapiCrcIndicationPdus) {
    for (size_t i = 0; i < numRecords; ++i) {
