```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

#define MAX_RECORDS 512 // Assuming a total limit of 8KB per record, with each record being up to 128 bytes + metadata overhead

typedef struct {
    int key;
    char data[128];
    time_t last_accessed;
} Record;

typedef struct {
    long *file_indices;
    size_t count;
    size_t capacity;
    uint64_t recycled_ids;
    Record **records;
    size_t record_count;
    size_t record_capacity;
    // Hash map for quick access (simplified representation)
    int hash_map[MAX_RECORDS];
} StorageSystem;

// Initialize the storage system
StorageSystem* initialize_storage_system(size_t initial_capacity) {
    StorageSystem *system = malloc(sizeof(StorageSystem));
    if (!system) return NULL;

    system->file_indices = calloc(initial_capacity, sizeof(long));
    if (!system->file_indices) {
        free(system);
        return NULL;
    }
    system->capacity = initial_capacity;
    system->count = 0;

    system->recycled_ids = 0; // Bitmask for recycled IDs

    system->records = malloc(MAX_RECORDS * sizeof(Record*));
    if (!system->records) {
        free(system->file_indices);
        free(system);
        return NULL;
    }
    system->record_count = 0;
    system->record_capacity = MAX_RECORDS;

    memset(system->hash_map, -1, sizeof(system->hash_map));

    return system;
}

// Allocate and recycle record identifiers using a bitmask
uint64_t allocate_record_id(StorageSystem *system) {
    uint64_t id = __builtin_ctzll(~system->recycled_ids); // Find first zero bit
    if (id < 64) { // If found within bounds
        system->recycled_ids |= (1ULL << id);
        return id;
    }
    // No recycled ID available, allocate a new one
    uint64_t new_id = system->record_count++;
    if (new_id >= MAX_RECORDS) {
        fprintf(stderr, "Max record limit reached\n");
        exit(EXIT_FAILURE);
    }
    return new_id;
}

// Release a record identifier for recycling
void recycle_record_id(StorageSystem *system, uint64_t id) {
    if (id < 64) {
        system->recycled_ids &= ~(1ULL << id);
    } else {
        fprintf(stderr, "Invalid ID to recycle\n");
    }
}

// Dynamic allocation and initialization of a record
Record* allocate_record(StorageSystem *system, int key, const char *data) {
    if (system->record_count >= MAX_RECORDS) return NULL;

    Record *new_record = malloc(sizeof(Record));
    if (!new_record) return NULL;

    new_record->key = key;
    strncpy(new_record->data, data, sizeof(new_record->data) - 1);
    new_record->data[sizeof(new_record->data) - 1] = '\0';
    new_record->last_accessed = time(NULL);

    // Simple hash map insertion
    int index = key % MAX_RECORDS;
    while (system->hash_map[index] != -1 && system->hash_map[index] != key) {
        index = (index + 1) % MAX_RECORDS; // Linear probing for simplicity
    }
    system->hash_map[index] = key;

    system->records[system->record_count++] = new_record;
    return new_record;
}

// Batch insertion function
size_t batch_insert_records(StorageSystem *system, Record **new_records, size_t count) {
    size_t inserted = 0;
    for (size_t i = 0; i < count && system->record_count < MAX_RECORDS; ++i) {
        if (!allocate_record(system, new_records[i]->key, new_records[i]->data)) {
            break;
        }
        inserted++;
    }
    return inserted;
}

// Search feature
Record* search_record_by_key(StorageSystem *system, int key) {
    int index = key % MAX_RECORDS;
    while (system->hash_map[index] != -1 && system->hash_map[index] != key) {
        index = (index + 1) % MAX_RECORDS; // Linear probing
    }
    if (system->hash_map[index] == -1) return NULL;

    Record *record = NULL;
    for (size_t i = 0; i < system->record_count; ++i) {
        if (system->records[i]->key == key) {
            record = system->records[i];
            break;
        }
    }

    if (record) {
        record->last_accessed = time(NULL);
    }
    return record;
}

// Graceful memory allocation failure handling
void handle_allocation_failure() {
    fprintf(stderr, "Memory allocation failed. Consider increasing limits or optimizing data structures.\n");
}

int main() {
    StorageSystem *system = initialize_storage_system(1024);
    if (!system) {
        handle_allocation_failure();
        return EXIT_FAILURE;
    }

    // Example usage
    Record record1 = { .key = 1, .data = "Example Data" };
    allocate_record(system, record1.key, record1.data);

    Record *found = search_record_by_key(system, 1);
    if (found) {
        printf("Found: %s\n", found->data);
    }

    // Clean up
    for (size_t i = 0; i < system->record_count; ++i) {
        free(system->records[i]);
    }
    free(system->file_indices);
    free(system->records);
    free(system);

    return EXIT_SUCCESS;
}
```

### Key Points:

- **Memory Management**: Uses dynamic memory allocation for records and file indices.
- **Record Structure**: Contains a key, data string (max 128 chars), and timestamp.
- **Hash Map**: Simple linear probing hash map for fast record access by key.
- **Batch Insertion**: Minimizes allocations by inserting multiple records at once.
- **Identifier Management**: Uses a bitmask to recycle identifiers efficiently.
- **Search Feature**: Updates last accessed time on retrieval, using the hash map.
- **Error Handling**: Provides feedback on memory allocation failures.

This code is designed for scalability and efficiency in a distributed storage system context. Adjustments may be needed based on specific system requirements and constraints.']

