Collection* create_record_collection(size_t initial_capacity, int min_value, int max_value, size_t name_length) {
    Collection *collection = (Collection *)malloc(sizeof(Collection));
    if (!collection) return NULL;

    int result = initialize_collection(collection, initial_capacity, min_value, max_value, name_length);
    if (result != SUCCESS) {
        free(collection);
        return NULL;
    }

    return collection;
}

int initialize_collection(Collection *collection, size_t initial_capacity, int min_value, int max_value, size_t name_length) {
    collection->records = (Record *)malloc(initial_capacity * sizeof(Record));
    if (!collection->records) return ALLOC_ERROR;

    collection->count = 0;
    collection->capacity = initial_capacity;

    for (size_t i = 0; i < initial_capacity; ++i) {
        collection->records[i].name = (char *)malloc(name_length + 1);
        if (!collection->records[i].name) {
            // Free previously allocated memory on failure
            while (i > 0) {
                free(collection->records[--i].name);
            }
            free(collection->records);
            return ALLOC_ERROR;
        }

        collection->records[i].value = generate_random(min_value, max_value);
    }

    return SUCCESS;
