#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int value;
    char *str;
} record;

#define POOL_SIZE 1024

typedef struct {
    void *pool[POOL_SIZE];
    size_t size[POOL_SIZE];
    int free_count;
} MemoryPool;

MemoryPool memory_pool = {{0}, {0}, POOL_SIZE};

void init_memory_pool() {
    for (int i = 0; i < POOL_SIZE; ++i) {
        memory_pool.pool[i] = malloc(1024); // Allocate 1KB blocks
        if (!memory_pool.pool[i]) {
            fprintf(stderr, "Failed to initialize memory pool\n");
            exit(EXIT_FAILURE);
        }
        memory_pool.size[i] = 1024;
    }
}

void* allocate_from_pool(size_t size) {
    for (int i = 0; i < POOL_SIZE; ++i) {
        if (memory_pool.free_count > 0 && memory_pool.size[i] >= size) {
            void *ptr = memory_pool.pool[i];
            memory_pool.pool[i] = NULL;
            memory_pool.size[i] = 0;
            memory_pool.free_count--;
            printf("Allocated %zu bytes from pool\n", size);
            return ptr;
        }
    }
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed for %zu bytes\n", size);
        exit(EXIT_FAILURE);
    }
    printf("Dynamically allocated %zu bytes\n", size);
    return ptr;
}

void deallocate_to_pool(void *ptr, size_t size) {
    if (memory_pool.free_count < POOL_SIZE) {
        memory_pool.pool[memory_pool.free_count] = ptr;
        memory_pool.size[memory_pool.free_count] = size;
        memory_pool.free_count++;
        printf("Deallocated %zu bytes back to pool\n", size);
    } else {
        free(ptr);
        printf("Freed %zu bytes dynamically\n", size);
    }
}

void* safe_reallocate(void *ptr, size_t old_size, size_t new_size) {
    void *new_ptr = realloc(ptr, new_size);
    if (!new_ptr && ptr != NULL) {
        fprintf(stderr, "Memory reallocation failed: cannot resize %zu bytes to %zu\n", old_size, new_size);
        exit(EXIT_FAILURE);
    }
    printf("Reallocated memory from %zu to %zu bytes\n", old_size, new_size);
    return new_ptr;
}

int manage_data_structures(long *offsets, int *keys, record **records, int *string_lengths, size_t num_records) {
    if (num_records > POOL_SIZE) {
        fprintf(stderr, "Exceeded maximum records limit\n");
        return -1;
    }

    offsets = allocate_from_pool(num_records * sizeof(long));
    keys = allocate_from_pool(num_records * sizeof(int));
    string_lengths = allocate_from_pool(num_records * sizeof(int));

    *records = malloc(num_records * sizeof(record));
    if (!*records) {
        fprintf(stderr, "Memory allocation failed for records\n");
        free(offsets);
        free(keys);
        free(string_lengths);
        return -1;
    }

    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i].value = 0;
        (*records)[i].str = allocate_from_pool(256); // Assuming a fixed buffer size of 256 bytes
        if (!(*records)[i].str) {
            fprintf(stderr, "Memory allocation failed for record string\n");
            deallocate_resources(offsets, keys, records, string_lengths);
            return -1;
        }
    }

    printf("Data structures initialized successfully for %zu records\n", num_records);
    return 0;
}

void deallocate_resources(long *offsets, int *keys, record **records, int *string_lengths) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (string_lengths) free(string_lengths);

    for (size_t i = 0; i < POOL_SIZE && records && *records; ++i) {
        if ((*records)[i].str) {
            deallocate_to_pool((*records)[i].str, 256); // Return the allocated buffer to pool
        }
    }

    if (*records) free(*records);
    printf("Resources deallocated successfully\n");
}

int main() {
    init_memory_pool();

    long *offsets = NULL;
    int *keys = NULL;
    record *records = NULL;
    int *string_lengths = NULL;

    size_t num_records = 100; // Example number of records
    if (manage_data_structures(offsets, keys, &records, string_lengths, num_records) == 0) {
        // Use the data structures...

        // Cleanup
        deallocate_resources(offsets, keys, &records, string_lengths);
    }

    return 0;
}
```']

['```csharp
using System;
using System.Threading.Tasks;

public class DynamicValueGenerator
{
    private float _minFloat;
    private float _maxFloat;
    private int _minInt;
    private int _maxInt;

    private int _floatCount;
    private int _intCount;

    public DynamicValueGenerator(float minFloat, float maxFloat, int minInt, int maxInt)
    {
        _minFloat = minFloat;
        _maxFloat = maxFloat;
        _minInt = minInt;
        _maxInt = maxInt;
    }

    public float GenerateRandomFloat()
    {
        var randomValue = (float)(_random.NextDouble() * (_maxFloat - _minFloat)) + _minFloat;
        Interlocked.Increment(ref _floatCount);
        return randomValue;
    }

    public int GenerateRandomInteger()
    {
        var randomValue = _random.Next(_minInt, _maxInt);
        Interlocked.Increment(ref _intCount);
        return randomValue;
    }

    public TaskCompletionSource<int> ExecuteBackgroundTask(Func<int> task)
    {
        var tcs = new TaskCompletionSource<int>();
        try
        {
            Task.Run(() =>
            {
                try
                {
                    int result = task();
                    tcs.SetResult(result);
                }
                catch (Exception ex)
                {
                    tcs.SetException(ex);
                }
            });
        }
        catch
        {
            tcs.SetCanceled();
        }

        return tcs;
    }

    public void UpdateRange(float newMinFloat, float newMaxFloat, int newMinInt, int newMaxInt)
    {
        _minFloat = newMinFloat;
        _maxFloat = newMaxFloat;
        _minInt = newMinInt;
        _maxInt = newMaxInt;
    }

    public void LogGeneratedCounts()
    {
        Console.WriteLine($"Float Values Generated: {_floatCount}");
        Console.WriteLine($"Integer Values Generated: {_intCount}");
    }

    private static readonly Random _random = new Random();
}
```

**Note**: This implementation assumes a basic logging mechanism via console output. For more robust applications, consider integrating with a logging framework like `NLog` or `log4net`. The class methods are designed to be thread-safe using `Interlocked.Increment`, and the `ExecuteBackgroundTask` method handles tasks asynchronously without blocking the main execution flow.']

