#include <string.h>

#define MAX_BUFFER_SIZE 1024

typedef struct {
    double timestamp;
    float sensorValue;
    int qualityFlag; // Assume 1 for good quality, 0 for bad quality
} DataPoint;

int initializeSensorBundle(const char* filePath, DataPoint*** bundle) {
    FILE *file = fopen(filePath, "r");
    if (!file) return -1; // Error opening file

    size_t capacity = 10;
    size_t count = 0;
    *bundle = malloc(capacity * sizeof(DataPoint*));
    if (!*bundle) {
        fclose(file);
        return -2; // Memory allocation error
    }

    char buffer[MAX_BUFFER_SIZE];
    while (fgets(buffer, MAX_BUFFER_SIZE, file)) {
        DataPoint *point = malloc(sizeof(DataPoint));
        if (!point) {
            for (size_t i = 0; i < count; ++i) free((*bundle)[i]);
            free(*bundle);
            fclose(file);
            return -3; // Memory allocation error
        }

        // Parse and validate data point
        if (sscanf(buffer, "%lf %f %d", &point->timestamp, &point->sensorValue, &point->qualityFlag) == 3 && point->qualityFlag) {
            if (count >= capacity) {
                size_t newCapacity = capacity * 2;
                DataPoint **newBundle = realloc(*bundle, newCapacity * sizeof(DataPoint*));
                if (!newBundle) {
                    free(point);
                    for (size_t i = 0; i < count; ++i) free((*bundle)[i]);
                    free(*bundle);
                    fclose(file);
                    return -4; // Reallocation error
                }
                *bundle = newBundle;
                capacity = newCapacity;
            }
            (*bundle)[count++] = point;
        } else {
            free(point);
        }
    }

    fclose(file);
    return (int)count;
}
