#include <netdb.h>
#include <errno.h>

#define MAX_HOSTNAME_LENGTH 256
#define BUFFER_SIZE 4096
#define DNS_LIMIT 5

typedef struct {
    u_char ip[16];
    int result;
} dns_result_t;

int resolve_dns(const char *hostname, dns_result_t *result) {
    struct addrinfo hints, *res, *p;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET6; // Support for both IPv4 and IPv6

    if (getaddrinfo(hostname, NULL, &hints, &res)) {
        result->result = -1;
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        if (p->ai_family == AF_INET || p->ai_family == AF_INET6) {
            void *addr;
            if (p->ai_family == AF_INET) {
                struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
                addr = &(ipv4->sin_addr);
            } else { // AF_INET6
                struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
                addr = &(ipv6->sin6_addr);
            }
            inet_ntop(p->ai_family, addr, (char *)result->ip, sizeof(result->ip));
            result->result = 0;
        }
    }

    freeaddrinfo(res);
    return result->result == 0 ? 0 : -1;
}

void process_file(const char *input_filename, const char *output_filename) {
    FILE *input_file = fopen(input_filename, "r");
    if (!input_file) {
        perror("Error opening input file");
        return;
    }

    FILE *output_file = fopen(output_filename, "w");
    if (!output_file) {
        perror("Error opening output file");
        fclose(input_file);
        return;
    }

    char line[BUFFER_SIZE];
    while (fgets(line, BUFFER_SIZE, input_file)) {
        int values[3], count = 0;
        char *token = strtok(line, " \t\n");
        while (token && count < 3) {
            if (sscanf(token, "%d", &values[count]) == 1) {
                count++;
            }
            token = strtok(NULL, " \t\n");
        }

        if (count >= 2) {
            double average = (values[1] + values[2]) / 2.0;
            fprintf(output_file, "%d,%d,%f\n", values[0], values[1], average);
        }
    }

    fclose(input_file);
    fclose(output_file);
}

void unit_tests() {
    dns_result_t result;

    // Test DNS resolution
    if (resolve_dns("example.com", &result) == 0) {
        printf("DNS Resolution successful: %s\n", result.ip);
    } else {
        printf("DNS Resolution failed.\n");
    }

    // Test file processing with a sample input
    char sample_input[] = "1 2 3\n4 5 6\n";
    FILE *temp_file = fopen("test_input.txt", "w");
    fwrite(sample_input, sizeof(char), strlen(sample_input), temp_file);
    fclose(temp_file);

    process_file("test_input.txt", "output_log.csv");

    // Validate output
    FILE *output_log = fopen("output_log.csv", "r");
    char buffer[BUFFER_SIZE];
    while (fgets(buffer, BUFFER_SIZE, output_log)) {
        printf("Output: %s", buffer);
    }
    fclose(output_log);

    remove("test_input.txt");
    remove("output_log.csv");

    // Additional tests can be added as needed
}

int main() {
    unit_tests();
    return 0;
}
