#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef enum { PENDING, IN_PROGRESS, COMPLETED } Status;

typedef struct {
    char* name;
    int priority;
    double deadline;
    Status status;
} Project;

typedef struct {
    Project** projects;
    size_t count;
    pthread_mutex_t lock; // For concurrency control
} ProjectList;

// Function prototypes
ProjectList* create_project_list(size_t num_projects);
void free_project_list(ProjectList* list);
void sort_projects_by_priority(ProjectList* list);
void update_status_on_deadline(ProjectList* list, double current_time);

static void init_random(void) {
    time_t t;
    srand((unsigned) time(&t));
}

// Allocate and initialize a dynamic list of projects
ProjectList* create_project_list(size_t num_projects) {
    ProjectList* list = malloc(sizeof(ProjectList));
    if (!list) return NULL;

    pthread_mutex_init(&list->lock, NULL);
    list->count = num_projects;
    list->projects = malloc(num_projects * sizeof(Project*));

    for (size_t i = 0; i < num_projects; ++i) {
        Project* project = malloc(sizeof(Project));

        // Simulating random project name
        char buffer[50];
        snprintf(buffer, sizeof(buffer), "Project_%zu", i + 1);
        project->name = strdup(buffer);

        // Random priority between 1 and 10
        project->priority = rand() % 10 + 1;

        // Deadline within the next month (in days)
        project->deadline = time(NULL) / (24 * 60 * 60) + (rand() % 30) + 1;

        project->status = PENDING;
        list->projects[i] = project;
    }

    return list;
}

// Free allocated memory for the dynamic list of projects
void free_project_list(ProjectList* list) {
    if (!list) return;

    for (size_t i = 0; i < list->count; ++i) {
        free(list->projects[i]->name);
        free(list->projects[i]);
    }

    free(list->projects);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Sorting function using bubble sort (for simplicity)
void sort_projects_by_priority(ProjectList* list) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count - 1; ++i) {
        for (size_t j = 0; j < list->count - i - 1; ++j) {
            if (list->projects[j]->priority > list->projects[j + 1]->priority) {
                Project* temp = list->projects[j];
                list->projects[j] = list->projects[j + 1];
                list->projects[j + 1] = temp;
            }
        }
    }

    pthread_mutex_unlock(&list->lock);
}

// Update status of projects if their deadline has passed
void update_status_on_deadline(ProjectList* list, double current_time) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (current_time >= list->projects[i]->deadline && list->projects[i]->status == PENDING) {
            list->projects[i]->status = IN_PROGRESS;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

// Example usage
int main() {
    init_random();

    ProjectList* project_list = create_project_list(10);

    sort_projects_by_priority(project_list);

    // Simulate current time for demonstration purposes
    double simulated_current_time = time(NULL) / (24 * 60 * 60) + 15; // Example: halfway into the next month

    update_status_on_deadline(project_list, simulated_current_time);

    // Clean up resources
    free_project_list(project_list);

    return 0;
}
```

### Key Points:
- **Memory Management**: Dynamic allocation and deallocation of memory is handled properly to minimize fragmentation.
- **Concurrency**: The `pthread_mutex_t` lock ensures that concurrent access by multiple threads does not lead to race conditions.
- **Scalability & Performance**: While bubble sort is used for simplicity, you might consider more efficient sorting algorithms (like quicksort) for larger datasets. Updates and sorts are quick due to the small size of each project structure.
- **Integration**: The modular design makes it easy to integrate with external systems for updates or status changes.
- **Usability & Maintainability**: Functions are self-contained and named clearly, making them intuitive to use and maintain.']

