        fprintf(stderr, "Failed to allocate memory for records array\n");
        free(col);
        return NULL;
    }

    pthread_mutex_init(&col->lock, NULL);
    col->count = 0;

    srand(time(NULL));
    int last_value = -1;

    for (size_t i = 0; i < col->capacity && col->count < col->capacity; ++i) {
        Record *record = malloc(sizeof(Record));
        if (!record) {
            fprintf(stderr, "Failed to allocate memory for record\n");
            continue;
        }

        size_t string_len = rand() % (MAX_STRING_LENGTH + 1);
        record->data = calloc(string_len + 1, sizeof(char));
        if (!record->data) {
            fprintf(stderr, "Failed to allocate memory for data string\n");
            free(record);
            continue;
        }

        snprintf(record->data, string_len + 1, "String of length %zu", string_len);
        log_allocation("Allocated string");

        int value;
        do {
            value = rand() % (MAX_INT_VALUE - MIN_INT_VALUE + 1) + MIN_INT_VALUE;
        } while (value == last_value);

        record->number = value;
        last_value = value;

        // Initialize metadata
        record->meta.key = strdup("ExampleKey");
        if (!record->meta.key) {
            fprintf(stderr, "Failed to allocate memory for metadata key\n");
            free(record->data);
            free(record);
            continue;
        }

        pthread_mutex_lock(&col->lock);
        col->records[col->count++] = record;
        pthread_mutex_unlock(&col->lock);
    }

    return col;
}

void resize_collection(Collection *collection, size_t new_size) {
    if (new_size > UPPER_LIMIT) {
        fprintf(stderr, "Requested size exceeds upper limit\n");
        return;
    }

    pthread_mutex_lock(&collection->lock);

    Record **new_records = realloc(collection->records, new_size * sizeof(Record *));
    if (!new_records) {
        fprintf(stderr, "Failed to resize records array\n");
        pthread_mutex_unlock(&collection->lock);
        return;
    }

    collection->capacity = new_size;
    collection->records = new_records;

    pthread_mutex_unlock(&collection->lock);
}

void free_collection(Collection *collection) {
    if (!collection) return;

    free_resources(collection);

    pthread_mutex_destroy(&collection->lock);
    free(collection);
}
```

This C function manages a dynamic collection of records. It initializes the integer fields with random values ensuring no two consecutive records have identical values, allocates null-terminated strings, and includes error handling for memory allocation failures. The function provides mechanisms to resize the collection dynamically and ensures thread safety through mutexes. The cleanup process is efficient, freeing all allocated resources, including nested allocations within metadata. Monitoring logs are integrated for string allocation patterns.']

