#include "external_logging.h"
#include "random_number_generator.h"
#include "error_handling.h"

#define MAX_RECORDS 100000

typedef struct {
    char *name;
    int value;
    int key_index;
    long offset_index;
} Record;

typedef struct {
    Record *records;
    size_t total_records;
    int *keys;
    long *offsets;
    size_t keys_count;
    pthread_mutex_t lock;
    long cumulative_sum;
} RecordCollection;

// Initialize the record collection
int initialize_record_collection(RecordCollection *collection, const char **names, int min_value, int max_value, int *keys, long *offsets, size_t keys_count) {
    if (!collection || !names || !keys || !offsets || keys_count == 0) {
        log_error("Invalid parameters for initializing record collection");
        return ERROR_INVALID_ARGUMENT;
    }

    collection->records = NULL;
    collection->total_records = 0;
    collection->keys = keys;
    collection->keys_count = keys_count;
    collection->cumulative_sum = 0;

    if (pthread_mutex_init(&collection->lock, NULL) != 0) {
        log_error("Mutex initialization failed");
        return ERROR_MUTEX_INIT;
    }

    size_t record_count = strlen(names); // Assuming names is null-terminated array of strings
    if (record_count > MAX_RECORDS) {
        log_warning("Number of records exceeds maximum allowed limit. Truncating to %d", MAX_RECORDS);
        record_count = MAX_RECORDS;
    }

    collection->records = malloc(record_count * sizeof(Record));
    if (!collection->records) {
        log_error("Memory allocation for records failed");
        return ERROR_MEMORY_ALLOCATION;
    }

    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < record_count; ++i) {
        collection->records[i].name = strdup(names[i]);
        if (!collection->records[i].name) {
            log_error("Memory allocation for string failed at index %zu", i);
            // Attempt cleanup
            while (--i >= 0) free(collection->records[i].name);
            free(collection->records);
            pthread_mutex_unlock(&collection->lock);
            pthread_mutex_destroy(&collection->lock);
            return ERROR_MEMORY_ALLOCATION;
        }

        int range_min = min_value;
        int range_max = max_value;

        // Adjust the range based on cumulative sum
        if (collection->cumulative_sum > 0) {
            range_min += collection->cumulative_sum / record_count;
            range_max += collection->cumulative_sum / record_count;
        }

        long random_value = generate_random_number(range_min, range_max);

        // Handle potential overflow
        if ((random_value > INT_MAX - collection->cumulative_sum) || (collection->cumulative_sum + random_value < 0)) {
            log_warning("Integer overflow prevented at index %zu", i);
            continue;
        }

        collection->records[i].value = (int)random_value;
        collection->cumulative_sum += collection->records[i].value;

        if (i < keys_count) {
            collection->records[i].key_index = i;
            collection->records[i].offset_index = i; // Assuming one-to-one mapping for simplicity
        } else {
            log_warning("Key or offset index out of bounds at index %zu", i);
            free(collection->records[i].name);
            collection->records[i].name = NULL;
            continue;
        }
    }

    collection->total_records = record_count;

    pthread_mutex_unlock(&collection->lock);
    return SUCCESS;
}

// Free the allocated resources for the record collection
void cleanup_record_collection(RecordCollection *collection) {
    if (!collection) return;

    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->total_records; ++i) {
        free(collection->records[i].name);
    }

    free(collection->records);
    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
}

// Example usage
int main() {
    const char *names[] = {"Record1", "Record2", NULL}; // null-terminated array of names
    int keys[] = {101, 102};
    long offsets[] = {1001L, 1002L};

    RecordCollection collection;
    if (initialize_record_collection(&collection, names, 0, 100, keys, offsets, sizeof(keys) / sizeof(int)) != SUCCESS) {
        handle_error("Failed to initialize record collection");
        return EXIT_FAILURE;
    }

    // Use the record collection...

    cleanup_record_collection(&collection);

    return EXIT_SUCCESS;
}
```

