#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int key;
    long offset;
} Record;

typedef struct Node {
    Record data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} RecordCollection;

RecordCollection* create_collection() {
    RecordCollection* collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!collection) return NULL;
    collection->head = NULL;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

int insert_record(RecordCollection* collection, int key, long offset) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1;

    new_node->data.key = key;
    new_node->data.offset = offset;
    new_node->next = NULL;

    pthread_mutex_lock(&collection->lock);

    // Insert at the beginning for efficiency
    new_node->next = collection->head;
    collection->head = new_node;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

Record* retrieve_record(RecordCollection* collection, int key) {
    pthread_mutex_lock(&collection->lock);

    Node* current = collection->head;
    while (current) {
        if (current->data.key == key) {
            pthread_mutex_unlock(&collection->lock);
            return &current->data;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&collection->lock);
    return NULL;
}

int update_record(RecordCollection* collection, int key, long new_offset) {
    pthread_mutex_lock(&collection->lock);

    Node* current = collection->head;
    while (current) {
        if (current->data.key == key) {
            current->data.offset = new_offset;
            pthread_mutex_unlock(&collection->lock);
            return 0;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&collection->lock);
    return -1;
}

int delete_record(RecordCollection* collection, int key) {
    pthread_mutex_lock(&collection->lock);

    Node *current = collection->head, *prev = NULL;

    while (current) {
        if (current->data.key == key) {
            if (prev) {
                prev->next = current->next;
            } else {
                collection->head = current->next;
            }
            free(current);
            pthread_mutex_unlock(&collection->lock);
            return 0;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&collection->lock);
    return -1;
}

void destroy_collection(RecordCollection* collection) {
    pthread_mutex_lock(&collection->lock);

    Node* current = collection->head;
    while (current) {
        Node* next_node = current->next;
        free(current);
        current = next_node;
    }

    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int main() {
    RecordCollection* collection = create_collection();
    if (!collection) return -1;

    insert_record(collection, 1, 100L);
    Record* record = retrieve_record(collection, 1);
    if (record) printf("Record found: key=%d, offset=%ld\n", record->key, record->offset);

    update_record(collection, 1, 200L);
    record = retrieve_record(collection, 1);
    if (record) printf("Updated Record: key=%d, offset=%ld\n", record->key, record->offset);

    delete_record(collection, 1);
    record = retrieve_record(collection, 1);
    if (!record) printf("Record deleted successfully.\n");

    destroy_collection(collection);
    return 0;
}
```']

