typedef struct {
    time_t timestamp;
    size_t packet_size;
    void *data;
} Packet;

typedef struct {
    Packet **packets;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} PacketArray;

PacketArray* initialize_packet_array(size_t max_capacity) {
    PacketArray *array = (PacketArray *)malloc(sizeof(PacketArray));
    if (!array) {
        log_error("Failed to allocate memory for PacketArray");
        return NULL;
    }

    array->packets = (Packet **)calloc(max_capacity, sizeof(Packet *));
    if (!array->packets) {
        free(array);
        log_error("Failed to allocate memory for packets");
        return NULL;
    }

    array->capacity = max_capacity;
    array->count = 0;

    pthread_mutex_init(&array->lock, NULL);
    pthread_cond_init(&array->cond, NULL);

    return array;
}

int validate_packet(const void *data, size_t size) {
    // Implement packet validation logic
    return (data != NULL && size > 0); // Example condition
}

void add_packet(PacketArray *array, const void *packet_data, size_t packet_size) {
    if (!validate_packet(packet_data, packet_size)) {
        log_error("Received malformed packet");
        return;
    }

    pthread_mutex_lock(&array->lock);

    while (array->count >= array->capacity) {
        pthread_cond_wait(&array->cond, &array->lock);
    }

    Packet *new_packet = (Packet *)malloc(sizeof(Packet));
    if (!new_packet) {
        log_error("Failed to allocate memory for new packet");
        pthread_mutex_unlock(&array->lock);
        return;
    }

    new_packet->timestamp = time(NULL);
    new_packet->packet_size = packet_size;
    new_packet->data = malloc(packet_size);
    if (new_packet->data) {
        memcpy(new_packet->data, packet_data, packet_size);
    } else {
        free(new_packet);
        log_error("Failed to allocate memory for packet data");
        pthread_mutex_unlock(&array->lock);
        return;
    }

    array->packets[array->count++] = new_packet;

    char log_message[256];
    snprintf(log_message, sizeof(log_message), "Packet added: size=%zu, timestamp=%ld", packet_size, new_packet->timestamp);
    log_info(log_message);

    pthread_mutex_unlock(&array->lock);
}

void dispose_older_packets(PacketArray *array) {
    pthread_mutex_lock(&array->lock);

    // Implement logic to remove older packets if needed
    // For example, keep only the latest N packets

    pthread_mutex_unlock(&array->lock);
}

void* packet_cleanup_thread(void *arg) {
    PacketArray *array = (PacketArray *)arg;

    while (1) {
        sleep(5); // Adjust cleanup interval as needed
        dispose_older_packets(array);
    }

    return NULL;
}

void start_packet_processing(PacketArray *array) {
    pthread_t cleanup_thread;
    if (pthread_create(&cleanup_thread, NULL, packet_cleanup_thread, array)) {
        log_error("Failed to create cleanup thread");
    }
}

size_t load_resource_bundle(const char *path, void ***bundle) {
    FILE *file = fopen(path, "r");
    if (!file) {
        log_error("Failed to open resource file");
        return 0;
    }

    // Example: Count lines or items in the file
    size_t count = 0;
    char line[256];
    while (fgets(line, sizeof(line), file)) {
        count++;
    }
    rewind(file);

    *bundle = malloc(count * sizeof(void *));
    if (!*bundle) {
        fclose(file);
        log_error("Failed to allocate memory for resource bundle");
        return 0;
    }

    size_t i = 0;
    while (fgets(line, sizeof(line), file)) {
        (*bundle)[i++] = strdup(line); // Example: Store line as item
    }
    fclose(file);

    return count;
}

void free_resource_bundle(void **bundle, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free(bundle[i]);
    }
    free(bundle);
}
