#define MAX_PACKETS 10000

typedef struct {
    time_t timestamp;
    size_t packet_size;
    unsigned char *data;
    unsigned char *encrypted_data;
} Packet;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

Packet* initializeNetworkPacketsWithCrypto(const char* remote_address, int num_packets);
void freePackets(Packet *packets, size_t count);
int findLargestInteger(int *array, size_t count);

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Helper function to log errors
void logError(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

Packet* initializeNetworkPacketsWithCrypto(const char* remote_address, int num_packets) {
    if (num_packets <= 0 || num_packets > MAX_PACKETS) {
        logError("Invalid number of packets");
        return NULL;
    }

    Packet *packets = malloc(num_packets * sizeof(Packet));
    if (!packets) {
        logError("Memory allocation failed for packets");
        return NULL;
    }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        logError("Failed to create cipher context");
        freePackets(packets, num_packets);
        return NULL;
    }

    // Example: Initialize DES in ECB mode
    if (1 != EVP_EncryptInit_ex(ctx, EVP_des_ecb(), NULL, NULL, NULL)) {
        logError("DES initialization failed");
        EVP_CIPHER_CTX_free(ctx);
        freePackets(packets, num_packets);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *cric_pdu = malloc(num_packets * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!cric_pdu) {
        logError("Memory allocation failed for CRIC PDU");
        EVP_CIPHER_CTX_free(ctx);
        freePackets(packets, num_packets);
        return NULL;
    }

    pthread_t threads[2];
    int largest_integer;

    // Thread to handle network communication and packet processing
    pthread_create(&threads[0], NULL, [](void* arg) -> void* {
        Packet **packets = (Packet**)arg;
        for (int i = 0; i < MAX_PACKETS; ++i) {
            pthread_mutex_lock(&lock);
            // Simulate network packet reception and encryption
            (*packets)[i].timestamp = time(NULL);
            (*packets)[i].packet_size = rand() % 1024;
            (*packets)[i].data = malloc((*packets)[i].packet_size);
            if (!(*packets)[i].data) {
                logError("Memory allocation failed for packet data");
                continue;
            }
            memcpy((*packets)[i].data, "Sample Data", 11); // Simulate data
            size_t encrypted_size = (*packets)[i].packet_size + DES_BLOCK_SIZE;
            (*packets)[i].encrypted_data = malloc(encrypted_size);
            if (!(*packets)[i].encrypted_data) {
                logError("Memory allocation failed for encrypted data");
                free((*packets)[i].data);
                continue;
            }
            EVP_EncryptUpdate(EVP_CIPHER_CTX_new(), // Use a new context per packet
                              (*packets)[i].encrypted_data,
                              NULL,
                              (*packets)[i].data,
                              (*packets)[i].packet_size);
            pthread_mutex_unlock(&lock);
        }
        return NULL;
    }, (void*)&packets);

    // Thread to initialize CRIC PDU structures
    pthread_create(&threads[1], NULL, [](void* arg) -> void* {
        NFAPI_CRC_INDICATION_PDU_T *cric_pdu = (NFAPI_CRC_INDICATION_PDU_T*)arg;
        for (int i = 0; i < MAX_PACKETS; ++i) {
            pthread_mutex_lock(&lock);
            cric_pdu[i].RX_UE_INFORMATION_TAG = rand();
            cric_pdu[i].RNTI = rand();
            cric_pdu[i].CRC_INDICATION_REL8_TAG = rand();
            cric_pdu[i].CRCFLAG = rand() % 2;
            pthread_mutex_unlock(&lock);
        }
        return NULL;
    }, (void*)cric_pdu);

    // Wait for threads to complete
    pthread_join(threads[0], NULL);
    pthread_join(threads[1], NULL);

    int *integers = malloc(MAX_PACKETS * sizeof(int));
    if (!integers) {
        logError("Memory allocation failed for integers");
        EVP_CIPHER_CTX_free(ctx);
        freePackets(packets, num_packets);
        free(cric_pdu);
        return NULL;
    }

    // Simulate filling the integer array
    for (int i = 0; i < MAX_PACKETS; ++i) {
        integers[i] = rand();
    }

    largest_integer = findLargestInteger(integers, MAX_PACKETS);
    printf("Largest Integer: %d\n", largest_integer);

    free(integers);
    EVP_CIPHER_CTX_free(ctx);
    return packets;
}

void freePackets(Packet *packets, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (packets[i].data) free(packets[i].data);
        if (packets[i].encrypted_data) free(packets[i].encrypted_data);
    }
    free(packets);
}

int findLargestInteger(int *array, size_t count) {
    int largest = array[0];
    for (size_t i = 1; i < count; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}
