#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int key;
    long offset;
    int value;
} record;

#define INITIAL_CAPACITY 10
#define MAX_SUM 10000

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

record* records = NULL;
long* offsets = NULL;
int* keys = NULL;
size_t size = 0;
size_t capacity = 0;
long total_sum = 0;
int range_min = 1, range_max = 10;

void init_random() {
    srand(time(NULL));
}

int random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

void adjust_range() {
    if (size == 0) return;
    long average = total_sum / size;
    range_min = (average > range_min) ? average / 2 : range_min;
    range_max = (average < range_max) ? average * 2 : range_max;
}

int add_record(long offset, int key, int value) {
    pthread_mutex_lock(&mutex);

    if ((total_sum + value) > MAX_SUM) {
        pthread_mutex_unlock(&mutex);
        return -1; // Exceeds the sum limit
    }

    if (size == capacity) {
        size_t new_capacity = capacity ? capacity * 2 : INITIAL_CAPACITY;
        record* new_records = realloc(records, new_capacity * sizeof(record));
        long* new_offsets = realloc(offsets, new_capacity * sizeof(long));
        int* new_keys = realloc(keys, new_capacity * sizeof(int));

        if (!new_records || !new_offsets || !new_keys) {
            pthread_mutex_unlock(&mutex);
            return -1; // Memory allocation failed
        }

        records = new_records;
        offsets = new_offsets;
        keys = new_keys;
        capacity = new_capacity;
    }

    int index = size++;
    records[index].key = key;
    records[index].offset = offset;
    records[index].value = value;
    offsets[index] = offset;
    keys[index] = key;

    total_sum += value;
    adjust_range();

    pthread_mutex_unlock(&mutex);
    return 0;
}

void process_streaming_data() {
    while (1) {
        long offset = rand();
        int key = rand() % 1000; // Simulating unique keys
        int value = random_int(range_min, range_max);

        if (add_record(offset, key, value) == -1) {
            printf("Failed to add record or sum limit exceeded\n");
        }

        // Simulate data bursts with sleep
        usleep(100000); // 100ms
    }
}

void* thread_function(void* arg) {
    process_streaming_data();
    return NULL;
}

int main() {
    init_random();

    records = malloc(INITIAL_CAPACITY * sizeof(record));
    offsets = malloc(INITIAL_CAPACITY * sizeof(long));
    keys = malloc(INITIAL_CAPACITY * sizeof(int));

    if (!records || !offsets || !keys) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    pthread_t thread;
    pthread_create(&thread, NULL, thread_function, NULL);

    // Main thread could perform other tasks or manage threads
    pthread_join(thread, NULL);

    free(records);
    free(offsets);
    free(keys);

    pthread_mutex_destroy(&mutex);

    return 0;
}
```

### Key Points:
- **Thread Safety**: Uses `pthread_mutex_t` to ensure that the shared data (`records`, `offsets`, `keys`, and `total_sum`) is accessed in a thread-safe manner.
- **Dynamic Range Adjustment**: Adjusts the range for random values based on the average of existing records' integer values.
- **Memory Management**: Initially allocates memory and doubles capacity when needed, ensuring efficient use of memory.
- **Streaming Data Handling**: Simulates continuous data processing with sleep to handle bursts.
- **Resource Management**: Frees allocated memory at the end of execution and destroys mutex resources.']

['```java
import java.net.MalformedURLException;
import java.net.URL;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.logging.Level;
import java.util.logging.Logger;

public class URLProcessor {

    private static final Logger LOGGER = Logger.getLogger(URLProcessor.class.getName());

    public Map<String, Integer> countUniqueTLDs(List<String> urls) {
        ExecutorService executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        ConcurrentHashMap<String, AtomicInteger> tldCountMap = new ConcurrentHashMap<>();

        for (String urlStr : urls) {
            executorService.submit(() -> processUrl(urlStr, tldCountMap));
        }

        executorService.shutdown();

        try {
            while (!executorService.isTerminated()) {
                // Wait for all tasks to finish
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        Map<String, Integer> finalTLDCounts = new HashMap<>();
        tldCountMap.forEach((tld, count) -> finalTLDCounts.put(tld, count.get()));

        return finalTLDCounts;
    }

    private void processUrl(String urlStr, ConcurrentHashMap<String, AtomicInteger> tldCountMap) {
        long startTime = System.nanoTime();
        try {
            URL url = new URL(urlStr);
            String host = url.getHost();
            if (host != null && !host.isEmpty()) {
                int dotIndex = host.lastIndexOf('.');
                if (dotIndex > 0) { // Ensure there's at least one dot for TLD extraction
                    String tld = host.substring(dotIndex + 1);
                    tldCountMap.computeIfAbsent(tld, k -> new AtomicInteger(0)).incrementAndGet();
                }
            }
        } catch (MalformedURLException e) {
            LOGGER.log(Level.SEVERE, "Malformed URL encountered: " + urlStr, e);
        }
        long endTime = System.nanoTime();
        LOGGER.info("Processed URL: " + urlStr + " in " + (endTime - startTime) / 1_000_000.0 + " ms");
    }

    public static void main(String[] args) {
        List<String> urls = Arrays.asList(
            "https://www.example.com",
            "http://test.org",
            "ftp://invalid.url",
            "http://another-example.co.uk"
        );

        URLProcessor processor = new URLProcessor();
        Map<String, Integer> result = processor.countUniqueTLDs(urls);
        System.out.println(result);
    }
}
