// Function to initialize the list with a specified number of projects
void init_projects(int count) {
    if (project_count > 0) free(projects);
    project_count = count < MAX_PROJECTS ? count : MAX_PROJECTS;
    projects = malloc(sizeof(Project) * project_count);

    for (int i = 0; i < project_count; ++i) {
        projects[i].name = malloc(50); // Assuming max name length
        snprintf(projects[i].name, 50, "Project %d", i + 1);
        projects[i].priority = rand() % 10 + 1;
        time_t now = time(NULL);
        double deadline = difftime(mktime((struct tm*)localtime(&now) + (2 * 7 * 24 * 60 * 60)), now);
        projects[i].deadline = deadline + ((double)rand() / RAND_MAX * 14 * 24 * 60 * 60); // Random within next two weeks
        projects[i].status = "planned";
    }
}

// Function to sort projects by priority in ascending order
void sort_projects_by_priority(void (*swap)(Project *, Project *)) {
    for (int i = 0; i < project_count - 1; ++i) {
        for (int j = 0; j < project_count - i - 1; ++j) {
            if (projects[j].priority > projects[j + 1].priority) {
                swap(&projects[j], &projects[j + 1]);
            }
        }
    }
}

// Swap function helper
void swap_projects(Project *a, Project *b) {
    Project temp = *a;
    *a = *b;
    *b = temp;
}

// Function to archive completed projects
void archive_completed_projects(void (*archive)(Project *)) {
    int j = 0;
    for (int i = 0; i < project_count; ++i) {
        if (strcmp(projects[i].status, "completed") != 0) {
            projects[j++] = projects[i];
        } else {
            archive(&projects[i]);
        }
    }
    project_count = j;
}

// External API mock function
