    // Mock implementation to simulate network call
    project->status = new_status;
}

// Mutex for handling concurrency issues
#include <pthread.h>
pthread_mutex_t lock;

// Function to safely update project status using external API
void update_project_status(int index, char *new_status) {
    pthread_mutex_lock(&lock);
    update_project_status_api(&projects[index], new_status);
    pthread_mutex_unlock(&lock);
}

int main() {
    srand(time(NULL));

    init_projects(10); // Initialize with 10 projects

    sort_projects_by_priority(swap_projects);

    update_project_status(2, "in progress");

    archive_completed_projects([](Project *project) { printf("Archived: %s\n", project->name); });

    for (int i = 0; i < project_count; ++i) {
        printf("Project Name: %s, Priority: %d, Deadline: %.2f, Status: %s\n",
            projects[i].name, projects[i].priority, projects[i].deadline, projects[i].status);
