        strcat(json, project_json);
        free(name_escaped);
    }

    strcat(json, "]}");

    return json;
}

void deallocate_projects(Project *projects, int num_projects) {
    for (int i = 0; i < num_projects; ++i) {
        free(projects[i].name);
    }
    free(projects);
}

// Example usage
int main() {
    int num_projects = 5;
    Project *projects = allocate_projects(num_projects);

    sort_projects_by_priority(projects, num_projects);

    for (int i = 0; i < num_projects; ++i) {
        update_project_status(&projects[i]);
    }

    char *json = serialize_projects_to_json(projects, num_projects);
    printf("%s\n", json);
    free(json);

    deallocate_projects(projects, num_projects);
    return 0;
}
