#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>
#include <jansson.h>  // JSON library
#include <libcurl/curl.h>
#include "url_validator.h" // Assumed robust URL validation library

// Error codes
#define SUCCESS 0
#define ERR_INVALID_CONFIG -1
#define ERR_MISSING_FIELD -2
#define ERR_URL_VALIDATION_FAILED -3
#define ERR_ENV_VARIABLE_RESOLVE -4

typedef struct {
    char *app_name;
    int port;
    char *database_url;
    int cache_duration;
    size_t num_records;
    int *records;
    char **api_keys; // Optional field: array of strings for api keys
} Config;

typedef void (*Logger)(const char *message);
typedef void *(*DbConnector)(const char *url);

// Function prototypes
int process_config(const char *json_data, Logger logger, DbConnector db_connector);
void log_message(Logger logger, const char *message);
char **resolve_env_variables(jansson::json_t *json_obj, size_t *num_keys);
size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp);

int process_config(const char *json_data, Logger logger, DbConnector db_connector) {
    jansson::json_error_t error;
    jansson::json_t *root = jansson::json_loads(json_data, 0, &error);

    if (!root) {
        log_message(logger, "Invalid JSON format.");
        return ERR_INVALID_CONFIG;
    }

    // Validate and resolve app_name
    const char *app_name = jansson::json_string_value(jansson::json_object_get(root, "app_name"));
    if (jansson::json_is_null(app_name)) {
        log_message(logger, "Missing required field: app_name");
        return ERR_MISSING_FIELD;
    }

    // Resolve environment variables in app_name
    char *resolved_app_name = resolve_env_variable(app_name);
    if (!resolved_app_name) {
        log_message(logger, "Failed to resolve environment variable in app_name.");
        return ERR_ENV_VARIABLE_RESOLVE;
    }

    // Validate port
    jansson::json_t *port_json = jansson::json_object_get(root, "port");
    if (jansson::json_is_null(port_json)) {
        log_message(logger, "Missing required field: port");
        return ERR_MISSING_FIELD;
    }

    int port = jansson::json_integer_value(port_json);
    if (port <= 0) {
        log_message(logger, "Invalid value for port; must be positive.");
        return ERR_INVALID_CONFIG;
    }

    // Validate cache_duration
    jansson::json_t *cache_duration_json = jansson::json_object_get(root, "cache_duration");
    int cache_duration = jansson::json_integer_value(cache_duration_json);
    if (cache_duration < 0) {
        log_message(logger, "Invalid value for cache_duration; must be non-negative.");
        return ERR_INVALID_CONFIG;
    }

    // Validate database_url
    const char *database_url_str = jansson::json_string_value(jansson::json_object_get(root, "database_url"));
    if (jansson::json_is_null(database_url_str) || !validate_url(database_url_str)) {
        log_message(logger, "Invalid or missing field: database_url");
        return ERR_URL_VALIDATION_FAILED;
    }

    // Resolve environment variables in database_url
    char *resolved_db_url = resolve_env_variable(database_url_str);
    if (!resolved_db_url) {
        log_message(logger, "Failed to resolve environment variable in database_url.");
        return ERR_ENV_VARIABLE_RESOLVE;
    }

    // Initialize Config struct
    Config config;
    config.app_name = resolved_app_name;
    config.port = port;
    config.database_url = resolved_db_url;
    config.cache_duration = cache_duration;

    // Process records
    jansson::json_t *records_json = jansson::json_object_get(root, "record");
    size_t record_count = jansson::json_array_size(records_json);

    if (record_count > 0) {
        config.num_records = record_count;
        config.records = malloc(record_count * sizeof(int));
        for (size_t i = 0; i < record_count; ++i) {
            int min_value, max_value;
            jansson::json_t *min_val_json = jansson::json_object_get(records_json[i], "min");
            jansson::json_t *max_val_json = jansson::json_object_get(records_json[i], "max");

            if (!jansson::json_is_integer(min_val_json) || !jansson::json_is_integer(max_val_json)) {
                log_message(logger, "Invalid range for records.");
                free(config.records);
                return ERR_INVALID_CONFIG;
            }

            min_value = jansson::json_integer_value(min_val_json);
            max_value = jansson::json_integer_value(max_val_json);

            if (min_value > max_value) {
                log_message(logger, "Invalid record range: min greater than max.");
                free(config.records);
                return ERR_INVALID_CONFIG;
            }

            config.records[i] = rand() % (max_value - min_value + 1) + min_value;
        }
    } else {
        config.num_records = 0;
        config.records = NULL;
    }

    // Process optional api_keys
    jansson::json_t *api_keys_json = jansson::json_object_get(root, "api_keys");
    if (!jansson::json_is_null(api_keys_json)) {
        size_t key_count = jansson::json_array_size(api_keys_json);
        config.api_keys = malloc(key_count * sizeof(char *));
        for (size_t i = 0; i < key_count; ++i) {
            const char *key_str = jansson::json_string_value(jansson::json_array_get(api_keys_json, i));
            if (!key_str) {
                log_message(logger, "Invalid API key format.");
                // Free allocated memory on error
                for (size_t j = 0; j <= i; ++j) {
                    free(config.api_keys[j]);
                }
                free(config.api_keys);
                return ERR_INVALID_CONFIG;
            }

            config.api_keys[i] = strdup(key_str); // Store a copy of the API key string
        }
    } else {
        config.api_keys = NULL;
    }

    // Establish database connection using the provided DbConnector function
    void *db_connection = db_connector(resolved_db_url);
    if (!db_connection) {
        log_message(logger, "Failed to establish database connection.");
        return ERR_INVALID_CONFIG;
    }

    // Clean up and return success
    jansson::json_decref(root);
    free(config.app_name);
    free(config.database_url);

    return SUCCESS;
}

void log_message(Logger logger, const char *message) {
    if (logger) {
        logger(message);
    } else {
        fprintf(stderr, "%s\n", message); // Default logging to stderr
    }
}

char *resolve_env_variable(const char *variable_str) {
    if (!variable_str) return NULL;

    size_t buffer_size = 512;
    char *resolved_string = malloc(buffer_size);

    if (resolved_string) {
        // Example implementation using getenv and sprintf for simplicity,
        // you should replace this with a robust resolver.

        const char *env_value = getenv(variable_str + 2); // Skip $ symbol

        if (env_value) {
            snprintf(resolved_string, buffer_size, "%s", env_value);
        } else {
            snprintf(resolved_string, buffer_size, "%s", variable_str);
        }
    }

    return resolved_string;
}

char **resolve_env_variables(jansson::json_t *json_obj, size_t *num_keys) {
    // Example implementation for resolving environment variables in JSON
    // Extend this logic to handle more keys and structures as needed.

    jansson::json_error_t error;
    char **env_resolved = NULL;
    size_t env_count = 0;

    jansson::json_object_foreach(json_obj, key, val) {
        if (jansson::json_is_string(val)) {
            const char *value_str = jansson::json_string_value(val);

            // Detect and resolve environment variable placeholders
            if (strncmp(value_str, "$", 1) == 0) {
                char *resolved_value = resolve_env_variable(value_str);

                env_resolved = realloc(env_resolved, sizeof(char *) * (env_count + 1));
                env_resolved[env_count] = resolved_value;
                ++env_count;
            }
        }
    }

    if (num_keys) *num_keys = env_count;

    return env_resolved;
}

size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    ((std::string *)userp)->append((char *)contents, size * nmemb);
    return size * nmemb;
}
```

