        $envVars = [
            'APP_ENV' => getenv('APP_ENV') ?: 'production',
            'DB_HOST' => getenv('DB_HOST') ?: 'localhost',
            // Add more variables as needed
        ];

        foreach ($envVars as $key => $value) {
            if (empty($value)) {
                $this->logger->warning("Environment variable {$key} is missing. Using default: {$value}");
            }
        }

        $_ENV = array_merge($_ENV, $envVars);
    }

    private function selectProfile()
    {
        $profile = $_ENV['APP_ENV'];
        $this->logger->info("Selected profile: {$profile}");
    }

    private function loadConfiguration()
    {
        $cacheItem = $this->cache->getItem('config_' . $_ENV['APP_ENV']);

        if (!$cacheItem->isHit()) {
            // Load configuration from files or external API
            $configData = $this->fetchConfigFromSources();
            $cacheItem->set($configData);
            $this->logger->info("Configuration loaded and cached for profile: {$_ENV['APP_ENV']}");
        } else {
            $this->config = $cacheItem->get();
            $this->logger->info("Loaded configuration from cache");
        }

        $this->config = $cacheItem->get();
    }

    private function fetchConfigFromSources()
    {
        // Implement logic to load config files or make API calls
        return [
            'db' => [
                'host' => $_ENV['DB_HOST'],
                // More configuration parameters
            ],
        ];
    }
}

class CLIController
{
    private $configManager;

    public function __construct(ConfigManager $configManager)
    {
        $this->configManager = $configManager;
    }

    public function handleCommand($argv)
    {
        if (isset($argv[1])) {
            switch ($argv[1]) {
                case 'show':
                    echo "Current configuration:\n";
                    print_r($this->configManager->getConfig());
                    break;
                // Add more CLI commands as needed
            }
        }
    }

    public function getConfig()
    {
        return $this->configManager->loadConfiguration();
    }
}

function main()
{
    use Monolog\Logger;
    use Monolog\Handler\StreamHandler;

    $logger = new Logger('app');
    $logger->pushHandler(new StreamHandler(__DIR__ . '/logs/app.log', Logger::DEBUG));

    $configManager = new ConfigManager($logger);
