['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_rwlock_t lock;  // Read-write lock for thread-safe operations
} Table;

Table* create_table() {
    Table* table = (Table*)malloc(sizeof(Table));
    if (!table) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    table->head = NULL;
    pthread_rwlock_init(&table->lock, NULL);
    return table;
}

void free_table(Table* table) {
    Node* current = table->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_rwlock_destroy(&table->lock);
    free(table);
}

int add_record(Table* table, Record record) {
    if (!table) return -1;

    pthread_rwlock_wrlock(&table->lock);

    // Check for duplicate keys
    Node* current = table->head;
    while (current) {
        if (current->record.key == record.key) {
            pthread_rwlock_unlock(&table->lock);
            return 0;  // Duplicate key, no addition
        }
        current = current->next;
    }

    // Allocate new node and add to the front for faster access
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_rwlock_unlock(&table->lock);
        return -1;
    }
    newNode->record = record;
    newNode->next = table->head;
    table->head = newNode;

    pthread_rwlock_unlock(&table->lock);
    return 1; // Successfully added
}

Record* get_record(Table* table, int key) {
    if (!table) return NULL;

    pthread_rwlock_rdlock(&table->lock);

    Node* current = table->head;
    while (current) {
        if (current->record.key == key) {
            Record* record = malloc(sizeof(Record));
            if (!record) {
                fprintf(stderr, "Memory allocation failed\n");
                pthread_rwlock_unlock(&table->lock);
                return NULL;
            }
            *record = current->record;
            pthread_rwlock_unlock(&table->lock);
            return record;  // Found and returned a copy of the record
        }
        current = current->next;
    }

    pthread_rwlock_unlock(&table->lock);
    return NULL;  // Not found
}

void update_record(Table* table, int key, Record newRecord) {
    if (!table) return;

    pthread_rwlock_wrlock(&table->lock);

    Node* current = table->head;
    while (current) {
        if (current->record.key == key) {
            current->record.offset = newRecord.offset;  // Update the record
            break;
        }
        current = current->next;
    }

    pthread_rwlock_unlock(&table->lock);
}

void parse_csv_and_initialize(Table* table, const char* csv_filename) {
    if (!table || !csv_filename) return;

    FILE* file = fopen(csv_filename, "r");
    if (!file) {
        fprintf(stderr, "Failed to open CSV file\n");
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        long offset;
        int key;
        if (sscanf(line, "%ld,%d", &offset, &key) == 2) {
            Record record = { .offset = offset, .key = key };
            add_record(table, record);
        }
    }

    fclose(file);
}

int main() {
    Table* table = create_table();
    if (!table) return EXIT_FAILURE;

    parse_csv_and_initialize(table, "data.csv");

    int searchKey = 42;
    Record* record = get_record(table, searchKey);
    if (record) {
        printf("Record found: offset=%ld, key=%d\n", record->offset, record->key);
        free(record); // Free the allocated memory for the record
    } else {
        printf("Record not found\n");
    }

    free_table(table);
    return EXIT_SUCCESS;
}
```']

