typedef struct record {
    int key;
    long offset;
    struct { int value; } data;
} record_t;

typedef struct node {
    record_t *record;
    struct node *next;
} node_t;

typedef struct {
    node_t *head;
    pthread_mutex_t lock;
    uint64_t total_value;
    int min_records;
    int max_records;
    bool initialized;
} record_set_t;

uint32_t generate_random(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

void init_record(record_t *rec, int key, long offset, uint64_t sum_of_values) {
    rec->key = key;
    rec->offset = offset;
    rec->data.value = generate_random(0, (int)(sum_of_values % UINT32_MAX));
}

record_set_t* create_record_set(int min_records, int max_records) {
    record_set_t *set = malloc(sizeof(record_set_t));
    if (!set) return NULL;

    set->head = NULL;
    pthread_mutex_init(&set->lock, NULL);
    set->total_value = 0;
    set->min_records = min_records;
    set->max_records = max_records;
    set->initialized = false;

    return set;
}

bool insert_record(record_set_t *set, int key, long offset) {
    pthread_mutex_lock(&set->lock);

    node_t *current = set->head;
    while (current) {
        if (current->record->key == key) {
            pthread_mutex_unlock(&set->lock);
            return false; // Key already exists
        }
        current = current->next;
    }

    record_t *new_record = malloc(sizeof(record_t));
    if (!new_record) {
        pthread_mutex_unlock(&set->lock);
        return false;
    }

    init_record(new_record, key, offset, set->total_value);

    node_t *new_node = malloc(sizeof(node_t));
    if (!new_node) {
        free(new_record);
        pthread_mutex_unlock(&set->lock);
        return false;
    }
    new_node->record = new_record;
    new_node->next = set->head;
    set->head = new_node;

    set->total_value += (uint64_t)new_record->data.value;
    set->initialized = true;

    pthread_mutex_unlock(&set->lock);
    return true;
}

bool retrieve_record(record_set_t *set, int key, record_t **record) {
    pthread_mutex_lock(&set->lock);

    node_t *current = set->head;
    while (current) {
        if (current->record->key == key) {
            *record = current->record;
            pthread_mutex_unlock(&set->lock);
            return true;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&set->lock);
    return false;
}

bool update_record(record_set_t *set, int key, long new_offset) {
    pthread_mutex_lock(&set->lock);

    node_t *current = set->head;
    while (current) {
        if (current->record->key == key) {
            record_t *rec = current->record;
            uint64_t old_value = rec->data.value;
            rec->offset = new_offset;

            // Simulate reinitialization with updated total value
            init_record(rec, key, new_offset, set->total_value - old_value + rec->data.value);

            pthread_mutex_unlock(&set->lock);
            return true;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&set->lock);
    return false;
}

void destroy_record_set(record_set_t *set) {
    pthread_mutex_lock(&set->lock);

    node_t *current = set->head;
    while (current) {
        node_t *temp = current;
        current = current->next;
        free(temp->record);
        free(temp);
    }

    pthread_mutex_unlock(&set->lock);
    pthread_mutex_destroy(&set->lock);
    free(set);
}

// Synchronization and error handling functions would be implemented here
// For example, handling external data source synchronization with retries,
// managing network latency, ensuring data consistency, etc.

void synchronize_with_external_source(record_set_t *set) {
    // Placeholder for synchronization logic
    // This function should handle network latency, data loss, and ensure consistency.
}

int main() {
    record_set_t *record_set = create_record_set(10, 100);
    if (!record_set) return EXIT_FAILURE;

    insert_record(record_set, 1, 0);
    insert_record(record_set, 2, 10);

    record_t *rec;
    if (retrieve_record(record_set, 1, &rec)) {
        printf("Record found with key 1: Value = %d\n", rec->data.value);
    } else {
        printf("Record not found.\n");
    }

    update_record(record_set, 1, 20);

    synchronize_with_external_source(record_set);

    destroy_record_set(record_set);
    return EXIT_SUCCESS;
}
