#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int weight;
} record;

typedef enum { RED, GREEN, BLUE, YELLOW, CYAN, MAGENTA, ORANGE, PURPLE } Color;
typedef enum { TYPE_A, TYPE_B, TYPE_C, TYPE_D, TYPE_E } EdgeType;

#define INITIAL_CAPACITY 10000
#define MAX_LABEL_LENGTH 10

// Custom LCG parameters for reproducibility
#define A 1664525L
#define C 1013904223L
#define M (1LL << 32)

typedef struct {
    long *vertexOffsets;
    int *keys;
    record **edges;
    char **labels;
    Color *colors;
    EdgeType *edgeTypes;
    time_t *timestamps;
    size_t numVertices;
    size_t capacity;
} Graph;

unsigned long lcg_seed = 42; // Fixed seed for reproducibility

// Linear congruential generator
unsigned int lcg() {
    lcg_seed = (lcg_seed * A + C) % M;
    return lcg_seed;
}

int initializeGraph(Graph *graph, size_t initialCapacity) {
    if (!graph) return -1;

    graph->vertexOffsets = malloc(initialCapacity * sizeof(long));
    graph->keys = malloc(initialCapacity * sizeof(int));
    graph->edges = malloc(initialCapacity * sizeof(record *));
    graph->labels = malloc(initialCapacity * sizeof(char *));
    graph->colors = malloc(initialCapacity * sizeof(Color));
    graph->edgeTypes = malloc(initialCapacity * sizeof(EdgeType));
    graph->timestamps = malloc(initialCapacity * sizeof(time_t));

    if (!graph->vertexOffsets || !graph->keys || !graph->edges || 
        !graph->labels || !graph->colors || !graph->edgeTypes || 
        !graph->timestamps) {
        free(graph->vertexOffsets);
        free(graph->keys);
        free(graph->edges);
        free(graph->labels);
        free(graph->colors);
        free(graph->edgeTypes);
        free(graph->timestamps);
        return -1;
    }

    graph->numVertices = 0;
    graph->capacity = initialCapacity;

    for (size_t i = 0; i < initialCapacity; ++i) {
        graph->vertexOffsets[i] = 0;
        graph->keys[i] = -1;
        graph->edges[i] = NULL;
        graph->labels[i] = NULL;
        graph->colors[i] = RED;
        graph->edgeTypes[i] = TYPE_A;
    }

    return 0;
}

void resizeGraph(Graph *graph) {
    if (!graph || graph->capacity == 0) return;

    size_t newCapacity = graph->capacity * 2;

    long *newOffsets = realloc(graph->vertexOffsets, newCapacity * sizeof(long));
    int *newKeys = realloc(graph->keys, newCapacity * sizeof(int));
    record **newEdges = realloc(graph->edges, newCapacity * sizeof(record *));
    char **newLabels = realloc(graph->labels, newCapacity * sizeof(char *));
    Color *newColors = realloc(graph->colors, newCapacity * sizeof(Color));
    EdgeType *newEdgeTypes = realloc(graph->edgeTypes, newCapacity * sizeof(EdgeType));
    time_t *newTimestamps = realloc(graph->timestamps, newCapacity * sizeof(time_t));

    if (!newOffsets || !newKeys || !newEdges || !newLabels || 
        !newColors || !newEdgeTypes || !newTimestamps) {
        // Handle allocation failure
        return;
    }

    graph->vertexOffsets = newOffsets;
    graph->keys = newKeys;
    graph->edges = newEdges;
    graph->labels = newLabels;
    graph->colors = newColors;
    graph->edgeTypes = newEdgeTypes;
    graph->timestamps = newTimestamps;

    for (size_t i = graph->capacity; i < newCapacity; ++i) {
        graph->vertexOffsets[i] = 0;
        graph->keys[i] = -1;
        graph->edges[i] = NULL;
        graph->labels[i] = NULL;
        graph->colors[i] = RED;
        graph->edgeTypes[i] = TYPE_A;
    }

    graph->capacity = newCapacity;
}

int addVertex(Graph *graph, int key, const char *label, Color color) {
    if (!graph || !key || !label || strlen(label) >= MAX_LABEL_LENGTH)
        return -1;

    if (graph->numVertices == graph->capacity) {
        resizeGraph(graph);
    }

    size_t index = graph->numVertices++;
    graph->keys[index] = key;
    graph->labels[index] = strdup(label);
    graph->colors[index] = color;

    return 0;
}

int addEdge(Graph *graph, int fromKey, int toKey, int minWeight, int maxWeight) {
    if (!graph || fromKey == toKey)
        return -1;

    size_t fromIndex = -1, toIndex = -1;
    for (size_t i = 0; i < graph->numVertices; ++i) {
        if (graph->keys[i] == fromKey) fromIndex = i;
        if (graph->keys[i] == toKey) toIndex = i;
    }

    if (fromIndex == -1 || toIndex == -1)
        return -1;

    size_t edgeCount = graph->vertexOffsets[fromIndex + 1] - graph->vertexOffsets[fromIndex];
    record *newEdges = realloc(graph->edges[fromIndex], (edgeCount + 1) * sizeof(record));
    if (!newEdges) return -1;

    graph->edges[fromIndex] = newEdges;
    graph->vertexOffsets[fromIndex + 1]++;

    record *edge = &graph->edges[fromIndex][edgeCount];
    edge->weight = minWeight + lcg() % (maxWeight - minWeight + 1);

    // Add more properties if needed
    // Example: strcpy(edge->label, label);
    // Example: edge->color = color;
    // Example: edge->type = type;

    return 0;
}

void serializeGraph(const Graph *graph, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&graph->numVertices, sizeof(size_t), 1, file);
    fwrite(graph->keys, sizeof(int), graph->numVertices, file);
    fwrite(graph->vertexOffsets, sizeof(long), graph->capacity + 1, file);

    for (size_t i = 0; i < graph->numVertices; ++i) {
        size_t edgeCount = graph->vertexOffsets[i + 1] - graph->vertexOffsets[i];
        if (edgeCount > 0) {
            fwrite(&edgeCount, sizeof(size_t), 1, file);
            fwrite(graph->edges[i], sizeof(record), edgeCount, file);
        }
    }

    fclose(file);
}

int deserializeGraph(Graph *graph, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    size_t numVertices;
    fread(&numVertices, sizeof(size_t), 1, file);

    resizeGraph(graph);
    graph->numVertices = numVertices;

    fread(graph->keys, sizeof(int), numVertices, file);
    fread(graph->vertexOffsets, sizeof(long), graph->capacity + 1, file);

    for (size_t i = 0; i < numVertices; ++i) {
        size_t edgeCount;
        fread(&edgeCount, sizeof(size_t), 1, file);

        if (edgeCount > 0) {
            record *newEdges = realloc(graph->edges[i], edgeCount * sizeof(record));
            if (!newEdges) return -1;

            graph->edges[i] = newEdges;
            fread(graph->edges[i], sizeof(record), edgeCount, file);
        }
    }

    fclose(file);
    return 0;
}

void freeGraph(Graph *graph) {
    if (!graph) return;

    for (size_t i = 0; i < graph->numVertices; ++i) {
        free(graph->labels[i]);
        free(graph->edges[i]);
    }

    free(graph->vertexOffsets);
    free(graph->keys);
    free(graph->edges);
    free(graph->labels);
    free(graph->colors);
    free(graph->edgeTypes);
    free(graph->timestamps);
}
