['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <string.h>

// Record structure definition
typedef struct {
    int value;
    int key_index;
    long offset;
} record_t;

// Configuration for logging and error handling
typedef enum {
    LOG_LEVEL_NONE = 0,
    LOG_LEVEL_ERROR,
    LOG_LEVEL_WARNING,
    LOG_LEVEL_INFO,
    LOG_LEVEL_DEBUG
} log_level_t;

typedef struct {
    log_level_t level;
    void (*log_callback)(const char* message);
} logger_t;

// Global mutex for thread safety
pthread_mutex_t memory_management_mutex = PTHREAD_MUTEX_INITIALIZER;

void log_message(const char* message, log_level_t level, const logger_t* logger) {
    if (level <= logger->level && logger->log_callback) {
        logger->log_callback(message);
    }
}

// Function to initialize and manage memory for the arrays
int init_memory_management(long n_offsets, int n_keys, int n_records,
                           long offset_range, int key_range, int record_value_range,
                           logger_t* logger) {

    pthread_mutex_lock(&memory_management_mutex);

    // Allocate memory for arrays
    long *offsets = (long*) malloc(n_offsets * sizeof(long));
    if (!offsets) {
        log_message("Failed to allocate memory for offsets", LOG_LEVEL_ERROR, logger);
        pthread_mutex_unlock(&memory_management_mutex);
        return -1;
    }

    int *keys = (int*) malloc(n_keys * sizeof(int));
    if (!keys) {
        free(offsets);
        log_message("Failed to allocate memory for keys", LOG_LEVEL_ERROR, logger);
        pthread_mutex_unlock(&memory_management_mutex);
        return -1;
    }

    record_t *records = (record_t*) malloc(n_records * sizeof(record_t));
    if (!records) {
        free(offsets);
        free(keys);
        log_message("Failed to allocate memory for records", LOG_LEVEL_ERROR, logger);
        pthread_mutex_unlock(&memory_management_mutex);
        return -1;
    }

    // Initialize offsets and keys with random values
    srand(time(NULL));  // Seed the random number generator
    long cumulative_sum = 0;

    for (int i = 0; i < n_offsets; ++i) {
        offsets[i] = rand() % offset_range + 1;
    }

    for (int j = 0; j < n_keys; ++j) {
        keys[j] = rand() % key_range + 1;
    }

    // Initialize records with random values and track cumulative sum
    for (int k = 0; k < n_records; ++k) {
        int value = rand() % record_value_range + 1;

        // Check for potential overflow before adding to cumulative_sum
        if (__builtin_add_overflow(cumulative_sum, value, &cumulative_sum)) {
            log_message("Integer overflow detected during cumulative sum update", LOG_LEVEL_WARNING, logger);
            break;
        }

        records[k].value = value;
        records[k].key_index = k % n_keys;  // Reference a key from keys array
        records[k].offset = offsets[(k + cumulative_sum) % n_offsets];  // Associate an offset

        log_message("Record initialized", LOG_LEVEL_DEBUG, logger);
    }

    pthread_mutex_unlock(&memory_management_mutex);

    return 0;
}

// Example logging callback function
void example_log_callback(const char* message) {
    printf("%s\n", message);
}

int main() {
    // Logger configuration
    logger_t logger = {LOG_LEVEL_INFO, example_log_callback};

