    while (scanf("%d", &number) == 1 && count < MAX_INPUT_SIZE) {
        if (count >= capacity) {
            capacity = (capacity == 0) ? 4 : capacity * 2;
            numbers = realloc(numbers, capacity * sizeof(int));
            if (!numbers) {
                fprintf(stderr, "Memory allocation failed\n");
                return -1;
            }
