#define MAX_DNS_QUERIES 10

typedef struct {
    char hostname[256];
    int query_count;
} UserSession;

UserSession user_sessions[MAX_USERS] = {0}; // Assume max users pre-defined
int dns_query_count = 0;

int resolve_hostname(const char *hostname, u_char ip_address[4]) {
    if (dns_query_count >= MAX_DNS_QUERIES) {
        fprintf(stderr, "DNS query limit reached.\n");
        return -1;
    }

    struct hostent *host_info = gethostbyname(hostname);
    dns_query_count++;

    if (!host_info || host_info->h_addrtype != AF_INET) {
        fprintf(stderr, "Error resolving hostname: %s\n", hostname);
        return -2;
    }

    struct in_addr addr;
    memcpy(&addr, host_info->h_addr_list[0], sizeof(struct in_addr));
    memcpy(ip_address, &addr, 4);

    printf("Hostname resolved to IP: %s\n", inet_ntoa(addr));
    return 0;
}

