// Define a Packet structure with necessary fields
typedef struct {
    time_t timestamp;
    size_t packet_size;
    void *data;
} Packet;

// Define the dynamic array and its associated metadata
typedef struct {
    Packet **packets; // Dynamic array of pointers to Packet structures
    size_t count;     // Current number of packets
    size_t capacity;  // Maximum capacity
    pthread_mutex_t mutex; // Mutex for thread safety
} PacketArray;

// Configuration structure for network interfaces
typedef struct {
    int id;
    size_t max_packet_size;
    int logging_level;
    double health_threshold;
} NetworkInterfaceConfig;

// Function prototypes
PacketArray* initialize_packet_array(size_t initial_capacity);
void add_packet(PacketArray *array, const void *data, size_t packet_size, int network_interface_id);
void cleanup_packet_array(PacketArray *array);
void *packet_disposal_thread(void *arg);
void log_packet(const Packet *packet, int network_interface_id);

// Initialize a dynamic array of Packet structures
PacketArray* initialize_packet_array(size_t initial_capacity) {
    PacketArray *array = (PacketArray *)malloc(sizeof(PacketArray));
    if (!array) {
        perror("Failed to allocate memory for packet array");
        return NULL;
    }

    array->packets = (Packet **)malloc(initial_capacity * sizeof(Packet *));
    if (!array->packets) {
        free(array);
        perror("Failed to allocate memory for packets");
        return NULL;
    }

    array->count = 0;
    array->capacity = initial_capacity;

    pthread_mutex_init(&array->mutex, NULL);

    // Start the packet disposal thread
    pthread_t tid;
    if (pthread_create(&tid, NULL, packet_disposal_thread, array) != 0) {
        perror("Failed to create packet disposal thread");
        cleanup_packet_array(array);
        return NULL;
    }

    return array;
}

// Add a validated packet to the dynamic array
void add_packet(PacketArray *array, const void *data, size_t packet_size, int network_interface_id) {
    if (pthread_mutex_lock(&array->mutex)) {
        perror("Failed to lock mutex");
        return;
    }

    // Validate packet data and size here (omitted for brevity)
    if (packet_size == 0 || !data) {
        pthread_mutex_unlock(&array->mutex);
        fprintf(stderr, "Malformed packet detected\n");
        return;
    }

    // Resize array if necessary
    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        Packet **new_packets = (Packet **)realloc(array->packets, new_capacity * sizeof(Packet *));
        if (!new_packets) {
            perror("Failed to reallocate memory for packets");
            pthread_mutex_unlock(&array->mutex);
            return;
        }
        array->packets = new_packets;
        array->capacity = new_capacity;
    }

    // Create and add the packet
    Packet *packet = (Packet *)malloc(sizeof(Packet));
    if (!packet) {
        perror("Failed to allocate memory for packet");
        pthread_mutex_unlock(&array->mutex);
        return;
    }

    packet->timestamp = time(NULL);
    packet->packet_size = packet_size;
    packet->data = malloc(packet_size);
    if (!packet->data) {
        free(packet);
        perror("Failed to allocate memory for packet data");
        pthread_mutex_unlock(&array->mutex);
        return;
    }

    memcpy(packet->data, data, packet_size);

    array->packets[array->count++] = packet;

    log_packet(packet, network_interface_id);

    pthread_mutex_unlock(&array->mutex);
}

// Cleanup the dynamic array
void cleanup_packet_array(PacketArray *array) {
    if (pthread_mutex_lock(&array->mutex)) {
        perror("Failed to lock mutex");
        return;
    }

    for (size_t i = 0; i < array->count; ++i) {
        free(array->packets[i]->data);
        free(array->packets[i]);
    }

    free(array->packets);
    pthread_mutex_unlock(&array->mutex);

    pthread_mutex_destroy(&array->mutex);
    free(array);
}

// Thread function for periodically checking and disposing of older packets
void *packet_disposal_thread(void *arg) {
    PacketArray *array = (PacketArray *)arg;
    while (1) {
        sleep(5); // Adjust the interval as necessary

        if (pthread_mutex_lock(&array->mutex)) {
            perror("Failed to lock mutex in disposal thread");
            continue;
        }

        if (array->count > array->capacity / 2) { // Example condition
            for (size_t i = 0; i < array->count / 2 && array->count > array->capacity / 4; ++i) {
                free(array->packets[i]->data);
                free(array->packets[i]);
                memmove(&array->packets[i], &array->packets[i + 1],
                        (array->count - i - 1) * sizeof(Packet *));
            }
            array->count -= array->count / 2;
        }

        pthread_mutex_unlock(&array->mutex);
    }

    return NULL;
}

// Log packet information
