#include <iostream>
#include <vector>
#include <mutex>
#include <shared_mutex>
#include <thread>
#include <atomic>
#include <chrono>
#include <condition_variable>
#include <map>
#include <fstream>
#include <nlohmann/json.hpp> // For JSON serialization, use a library like nlohmann/json

// Define resource structure
struct Resource {
    int cpu_cores;
    double current_load; // 0.0 to 1.0
};

// Task entity definition
class Task {
public:
    int id;
    int priority;
    double estimated_execution_time;
    std::atomic<double> progress;
    Resource resource_config;

    Task(int task_id, int pri, double exec_time, const Resource& res)
        : id(task_id), priority(pri), estimated_execution_time(exec_time), 
          progress(0.0), resource_config(res) {}

    void updateProgress(double value) {
        progress += value;
        adjustPriority();
    }

private:
    void adjustPriority() {
        // Adjust the priority based on the completion percentage
        double completed = progress.load() / estimated_execution_time;
        if (completed > 0.5) {
            priority += 1; // Increase priority if more than 50% complete
        }
    }
};

// TaskManager class to manage tasks
class TaskManager {
public:
    TaskManager(size_t initial_capacity = 100)
        : tasks(initial_capacity), threshold(100.0) {}

    void addTask(const Task& task) {
        std::unique_lock lock(task_mutex);
        if (tasks.size() >= max_tasks) throw std::runtime_error("Max tasks limit reached.");
        tasks.push_back(task);
        cond_var.notify_all();
    }

    void updateTaskPriority(int id, int new_priority) {
        std::shared_lock lock(task_mutex);
        auto it = std::find_if(tasks.begin(), tasks.end(), [&](const Task& task) { return task.id == id; });
        if (it != tasks.end()) {
            it->priority = new_priority;
        }
    }

    void updateTaskExecutionTime(int id, double new_time) {
        std::shared_lock lock(task_mutex);
        auto it = std::find_if(tasks.begin(), tasks.end(), [&](const Task& task) { return task.id == id; });
        if (it != tasks.end()) {
            it->estimated_execution_time = new_time;
        }
    }

    void cancelTask(int id) {
        std::unique_lock lock(task_mutex);
        auto it = std::remove_if(tasks.begin(), tasks.end(), [&](const Task& task) { return task.id == id; });
        if (it != tasks.end()) tasks.erase(it, tasks.end());

        // Create a new default task
        Task new_task(id + 1, 0, 10.0, Resource{4, 0.0});
        tasks.push_back(new_task);
    }

    void serializeState(const std::string& filename) {
        nlohmann::json json_tasks;
        {
            std::shared_lock lock(task_mutex);
            for (const auto& task : tasks) {
                json_tasks.push_back({
                    {"id", task.id},
                    {"priority", task.priority},
                    {"estimated_execution_time", task.estimated_execution_time},
                    {"progress", task.progress.load()},
                    {"resource_config.cpu_cores", task.resource_config.cpu_cores},
                    {"resource_config.current_load", task.resource_config.current_load}
                });
            }
        }

        std::ofstream file(filename);
        if (file.is_open()) {
            file << json_tasks.dump(4);
            file.close();
        } else {
            throw std::runtime_error("Unable to open file for serialization.");
        }
    }

    void monitorTasks() {
        while (true) {
            double avg_turnaround_time = 0.0;
            size_t count = 0;

            {
                std::shared_lock lock(task_mutex);
                for (const auto& task : tasks) {
                    avg_turnaround_time += task.estimated_execution_time - task.progress.load();
                    ++count;
                }
            }

            if (count > 0) {
                avg_turnaround_time /= count;
                if (avg_turnaround_time > threshold) {
                    std::cout << "Alert: Average turnaround time exceeded the threshold!" << std::endl;
                }
            }

            // Sleep for a while before next check
            std::this_thread::sleep_for(std::chrono::seconds(5));
        }
    }

private:
    static constexpr size_t max_tasks = 1000;
    double threshold;
    std::vector<Task> tasks;
    mutable std::shared_mutex task_mutex;
    std::condition_variable cond_var;
};

// RESTful API function implementations (pseudo-code for illustration)
void patchTask(int id, int new_priority, double new_exec_time) {
