                pduList[pduCount].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2 == 0; // Random CRC flag
                ++pduCount;
                break;
            }
        }
    }

    free(*array);
    *count = pduCount;

    freeValidTags(validTags, validSize);

    if (pduCount > 0) {
        printf("Largest integer: %d\n", findLargestInteger(tempArray, n));
