        if (tag == validTags[i]) {
            return true;
        }
    }
    return false;
}

int findLargestInteger(const int *arr, size_t n) {
    if (n == 0) return -1;

    int largest = arr[0];
    for (size_t i = 1; i < n; ++i) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }

    return largest;
