['Below is a C code implementation that meets the requirements of dynamically managing memory for a scalable data structure capable of storing thousands of records efficiently. The implementation includes synchronization for thread safety, logging for monitoring, and mechanisms to handle integer overflow and system resource limitations.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int value;
} Record;

typedef struct {
    size_t offset;
    int key;
    Record record;
} DataRecord;

typedef struct {
    pthread_mutex_t lock;
    DataRecord **records;
    size_t count;
    size_t capacity;
    long running_sum;
    pthread_cond_t cond_var;
} DataManager;

DataManager* create_data_manager(size_t initial_capacity) {
    DataManager *dm = malloc(sizeof(DataManager));
    if (!dm) return NULL;

    dm->records = calloc(initial_capacity, sizeof(DataRecord *));
    if (!dm->records) {
        free(dm);
        return NULL;
    }

    pthread_mutex_init(&dm->lock, NULL);
    pthread_cond_init(&dm->cond_var, NULL);

    dm->count = 0;
    dm->capacity = initial_capacity;
    dm->running_sum = 0;

    return dm;
}

void adjust_range(long running_sum) {
    // Adjust the random range based on running sum
    if (running_sum > INT_MAX / 2 || running_sum < -INT_MAX / 2)
        printf("Warning: Running sum is approaching integer overflow limits.\n");
}

int add_record(DataManager *dm, size_t offset, int key, int value) {
    pthread_mutex_lock(&dm->lock);

    if (dm->count >= dm->capacity) {
        // Expand capacity
        size_t new_capacity = dm->capacity * 2;
        DataRecord **new_records = realloc(dm->records, new_capacity * sizeof(DataRecord *));
        if (!new_records) {
            pthread_mutex_unlock(&dm->lock);
            return -1; // Memory allocation failed
        }
        dm->records = new_records;
        dm->capacity = new_capacity;
    }

    // Check for integer overflow risk in running sum
    long new_sum = dm->running_sum + value;
    if ((value > 0 && dm->running_sum > INT_MAX - value) ||
        (value < 0 && dm->running_sum < INT_MIN - value)) {
        pthread_mutex_unlock(&dm->lock);
        return -1; // Integer overflow detected
    }

    DataRecord *new_record = malloc(sizeof(DataRecord));
    if (!new_record) {
        pthread_mutex_unlock(&dm->lock);
        return -1; // Memory allocation failed
    }

    new_record->offset = offset;
    new_record->key = key;
    new_record->record.value = value;

    dm->records[dm->count++] = new_record;
    dm->running_sum = new_sum;

    adjust_range(dm->running_sum);

    printf("Record added. Current count: %zu, Running sum: %ld\n", dm->count, dm->running_sum);

    pthread_mutex_unlock(&dm->lock);
    return 0; // Success
}

void free_data_manager(DataManager *dm) {
    if (!dm) return;

    pthread_mutex_lock(&dm->lock);

    for (size_t i = 0; i < dm->count; ++i) {
        free(dm->records[i]);
    }

    free(dm->records);
    pthread_mutex_unlock(&dm->lock);

    pthread_mutex_destroy(&dm->lock);
    pthread_cond_destroy(&dm->cond_var);
    free(dm);
}

// Function to be called periodically for memory compaction and logging
void maintain_data_manager(DataManager *dm) {
    pthread_mutex_lock(&dm->lock);

    // Log current state
    printf("Maintaining data manager. Current capacity: %zu, Record count: %zu\n", dm->capacity, dm->count);

    // Implement memory compaction logic if necessary (not implemented here)

    pthread_mutex_unlock(&dm->lock);
}

// Main function for demonstration purposes
int main() {
    DataManager *dm = create_data_manager(1000);

    if (!dm) {
        fprintf(stderr, "Failed to initialize data manager.\n");
        return 1;
    }

    int keys[] = {1, 2, 3, 4, 5}; // Example key array

    for (int i = 0; i < 10000; ++i) {
        if (add_record(dm, i % 100, keys[i % 5], rand() % 100 - 50)) {
            fprintf(stderr, "Failed to add record at iteration %d.\n", i);
            break;
        }
    }

    maintain_data_manager(dm);

    free_data_manager(dm);
    return 0;
}
