### Key Points:
- **Thread Safety**: The random number generator is initialized once and accessed in a thread-safe manner using `std::mutex`.
- **Cipher Management**: Uses OpenSSL to manage DES-based ciphers.
- **Graph Structure**: Randomly generates vertices and edges with weights, ensuring memory management through RAII with vectors.
- **Cooldown Mechanism**: Implements a 9-second cooldown between attack selections.
- **Logging**: Basic logging is demonstrated via console output.
- **Error Handling**: Includes basic error handling for unsupported cipher modes.']

['Below is a C implementation of the task described:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>

#define MAX_LIMIT 1000000

typedef struct {
    int value;
    int* key_reference;
} Record;

typedef struct {
    pthread_mutex_t lock;
    double current_average;
    uint64_t total_sum;
    size_t initialized_count;
} ThreadSafeStats;

ThreadSafeStats stats = {PTHREAD_MUTEX_INITIALIZER, 0.0, 0, 0};

void log_warning(const char* message) {
    fprintf(stderr, "WARNING: %s\n", message);
}

int random_range(int min, int max) {
    return rand() % (max - min + 1) + min;
}

Record* initialize_records(Record** records_out, size_t num_records, int* keys, size_t key_count) {
    if (!records_out || !keys || key_count == 0) return NULL;

    *records_out = malloc(num_records * sizeof(Record));
    if (*records_out == NULL) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    pthread_mutex_lock(&stats.lock);

    for (size_t i = 0; i < num_records; ++i) {
        // Validate key reference
        if (i >= key_count || keys[i] < 0) {
            free(*records_out);
            *records_out = NULL;
            log_warning("Invalid key reference or out of bounds access detected.");
            pthread_mutex_unlock(&stats.lock);
            return NULL;
        }

        int dynamic_range_min = (int)(stats.current_average - 10);
        int dynamic_range_max = (int)(stats.current_average + 10);
        if (dynamic_range_min < 1) dynamic_range_min = 1; // Ensure positive range
        if (dynamic_range_max < dynamic_range_min) dynamic_range_max = dynamic_range_min;

        int random_value = random_range(dynamic_range_min, dynamic_range_max);

        (*records_out)[i].value = random_value;
        (*records_out)[i].key_reference = &keys[i];

        // Update stats
        uint64_t new_sum = stats.total_sum + random_value;
        if (new_sum > MAX_LIMIT) {
            log_warning("Sum of record values exceeds maximum limit.");
            free(*records_out);
            *records_out = NULL;
            pthread_mutex_unlock(&stats.lock);
            return NULL;
        }

        stats.total_sum = new_sum;
        stats.initialized_count++;
    }

    // Calculate new average
    stats.current_average = (double)stats.total_sum / stats.initialized_count;

    pthread_mutex_unlock(&stats.lock);

    return *records_out;
}

void free_records(Record* records, size_t num_records) {
    if (!records) return;
    free(records);
}

// Test function to validate behavior under stress conditions
void test_initialize_records() {
    int keys[] = {1, 2, 3, 4, 5};
    size_t key_count = sizeof(keys) / sizeof(keys[0]);
    Record* records = NULL;

    // Initialize with varying number of records and validate thread safety
    for (size_t i = 0; i < 1000; ++i) {
        initialize_records(&records, rand() % 10 + 1, keys, key_count);
        free_records(records, sizeof(Record) * ((rand() % 10) + 1));
    }

    printf("Test completed successfully.\n");
}

int main() {
