DataManager* create_data_manager(size_t initial_capacity, double frag_threshold) {
    DataManager *dm = (DataManager *)malloc(sizeof(DataManager));
    if (!dm) return NULL;

    dm->offsets = (long *)calloc(initial_capacity, sizeof(long));
    dm->keys = (int *)calloc(initial_capacity, sizeof(int));
    dm->records = (record **)calloc(initial_capacity, sizeof(record *));
    if (!dm->offsets || !dm->keys || !dm->records) {
        free(dm->offsets);
        free(dm->keys);
        free(dm->records);
        free(dm);
        return NULL;
    }

    pthread_mutex_init(&dm->lock, NULL);

    dm->count = 0;
    dm->capacity = initial_capacity;
    dm->sum_values = 0;

    const char *log_filename = "memory_usage.log";
    dm->log_file = fopen(log_filename, "a");
