        free(dm->offsets);
        free(dm->keys);
        free(dm->records);
        free(dm);
        return NULL;
    }

    fprintf(dm->log_file, "Initialized DataManager with capacity %zu\n", initial_capacity);

    dm->fragmentation_threshold = frag_threshold;
    dm->max_capacity = initial_capacity;

    return dm;
}

void log_memory_usage(DataManager *dm) {
    pthread_mutex_lock(&dm->lock);
    fprintf(dm->log_file, "Count: %zu, Capacity: %zu, Sum: %ld\n", dm->count, dm->capacity, dm->sum_values);
