    }
}

int add_record(DataManager *dm, int key, record *rec) {
    pthread_mutex_lock(&dm->lock);

    if (dm->count >= dm->capacity) {
        size_t new_capacity = dm->capacity * 2;
        long *new_offsets = realloc(dm->offsets, new_capacity * sizeof(long));
        int *new_keys = realloc(dm->keys, new_capacity * sizeof(int));
        record **new_records = realloc(dm->records, new_capacity * sizeof(record *));

        if (!new_offsets || !new_keys || !new_records) {
            pthread_mutex_unlock(&dm->lock);
            return -1;
        }

        dm->offsets = new_offsets;
        dm->keys = new_keys;
        dm->records = new_records;
        dm->capacity = new_capacity;

        fprintf(dm->log_file, "Resized memory to capacity %zu\n", dm->capacity);
    }

    size_t offset_index = dm->count;
    dm->offsets[offset_index] = rand() % (dm->sum_values + 1);
    dm->keys[offset_index] = key;
    dm->records[offset_index] = rec;

    pthread_mutex_unlock(&dm->lock);

    log_memory_usage(dm);
    check_and_compact_memory(dm);

    return 0;
}

void evict_records(DataManager *dm) {
    // Implement LRU eviction policy
    size_t lru_index = 0; // Simplified: Evict the first element as LRU
    if (dm->records[lru_index]) {
        free(dm->records[lru_index]);
        dm->sum_values -= dm->records[lru_index]->value;
    }
    memmove(&dm->offsets[1], &dm->offsets[0], lru_index * sizeof(long));
    memmove(&dm->keys[1], &dm->keys[0], lru_index * sizeof(int));
    memmove(&dm->records[1], &dm->records[0], (lru_index + 1) * sizeof(record *));
    dm->count--;
}

void update_data_manager(DataManager *dm, int key, record *rec) {
    if (add_record(dm, key, rec) == -1 || dm->count > dm->max_capacity) {
        evict_records(dm);
        add_record(dm, key, rec);
    }

    dm->sum_values += rec->value;
}

void free_data_manager(DataManager *dm) {
    pthread_mutex_lock(&dm->lock);

    for (size_t i = 0; i < dm->count; ++i) {
        if (dm->records[i]) free(dm->records[i]);
    }

    free(dm->offsets);
    free(dm->keys);
    free(dm->records);

    pthread_mutex_unlock(&dm->lock);

    fclose(dm->log_file);
    pthread_mutex_destroy(&dm->lock);
    free(dm);
}

int main() {
