```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>

typedef struct {
    int value;
} Record;

typedef struct {
    size_t offset;
    int key;
    Record record;
} Entry;

#define INITIAL_CAPACITY 1024

typedef struct {
    Entry *entries;
    size_t capacity;
    size_t count;
    int64_t sum;
    pthread_mutex_t lock;
    // Add more fields as needed for distributed environment, logging, etc.
} DataStructure;

void init_data_structure(DataStructure *ds) {
    ds->capacity = INITIAL_CAPACITY;
    ds->count = 0;
    ds->sum = 0;
    ds->entries = malloc(ds->capacity * sizeof(Entry));
    pthread_mutex_init(&ds->lock, NULL);
}

int add_entry(DataStructure *ds, int offset, int key, int value) {
    pthread_mutex_lock(&ds->lock);

    if (ds->count == ds->capacity) {
        size_t new_capacity = ds->capacity * 2;
        Entry *new_entries = realloc(ds->entries, new_capacity * sizeof(Entry));
        if (!new_entries) {
            pthread_mutex_unlock(&ds->lock);
            return -1; // Memory allocation failed
        }
        ds->entries = new_entries;
        ds->capacity = new_capacity;
    }

    Entry *entry = &ds->entries[ds->count++];
    entry->offset = offset;
    entry->key = key;
    entry->record.value = value;

    ds->sum += value;

    pthread_mutex_unlock(&ds->lock);
    return 0; // Success
}

void remove_entry(DataStructure *ds, size_t index) {
    pthread_mutex_lock(&ds->lock);

    if (index < ds->count) {
        ds->sum -= ds->entries[index].record.value;
        memmove(&ds->entries[index], &ds->entries[index + 1],
                (--ds->count - index) * sizeof(Entry));
    }

    pthread_mutex_unlock(&ds->lock);
}

void compact_memory(DataStructure *ds) {
    pthread_mutex_lock(&ds->lock);

    // Compact logic: remove gaps, defragment memory
    size_t new_capacity = ds->capacity;
    Entry *new_entries = malloc(new_capacity * sizeof(Entry));
    if (!new_entries) {
        pthread_mutex_unlock(&ds->lock);
        return; // Memory allocation failed
    }

    memcpy(new_entries, ds->entries, ds->count * sizeof(Entry));
    free(ds->entries);

    ds->entries = new_entries;
    ds->capacity = new_capacity;

    pthread_mutex_unlock(&ds->lock);
}

void cleanup_data_structure(DataStructure *ds) {
    pthread_mutex_lock(&ds->lock);

    free(ds->entries);
    pthread_mutex_unlock(&ds->lock);
    pthread_mutex_destroy(&ds->lock);
}

// Implement additional functions for garbage collection, logging, etc.

int main() {
    DataStructure ds;
    init_data_structure(&ds);

    // Example usage
    add_entry(&ds, 0, 1, 42);
    remove_entry(&ds, 0);

    compact_memory(&ds);
    cleanup_data_structure(&ds);

    return 0;
}
```

