#include <string.h>

#define MAX_BUFFER_SIZE 32768 // 32KB buffer size for throughput optimization

typedef struct {
    double timestamp;
    int sensorID;
    float measurementValue;
    bool qualityFlag;
} Data;

typedef struct {
    Data* dataArray;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int version;
} DynamicArray;

DynamicArray* createDynamicArray(int initialCapacity) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->dataArray = (Data*)malloc(initialCapacity * sizeof(Data));
    if (!array->dataArray) {
        free(array);
        return NULL;
    }

    array->size = 0;
    array->capacity = initialCapacity;
    pthread_mutex_init(&array->lock, NULL);
    pthread_cond_init(&array->cond, NULL);
    array->version = 1; // Assuming version 1 for compatibility

    return array;
}

void freeDynamicArray(DynamicArray* array) {
    if (!array) return;

    free(array->dataArray);
    pthread_mutex_destroy(&array->lock);
    pthread_cond_destroy(&array->cond);
    free(array);
}

bool addDataToDynamicArray(DynamicArray* array, Data data) {
    if (!array) return false;

    pthread_mutex_lock(&array->lock);

    if (array->size >= array->capacity) {
        size_t newCapacity = array->capacity * 2;
        Data* newDataArray = (Data*)realloc(array->dataArray, newCapacity * sizeof(Data));
        if (!newDataArray) {
            pthread_mutex_unlock(&array->lock);
            return false;
        }
        array->dataArray = newDataArray;
        array->capacity = newCapacity;
    }

    array->dataArray[array->size++] = data;

    pthread_mutex_unlock(&array->lock);
    pthread_cond_signal(&array->cond);

    return true;
}

bool validateData(Data* data) {
    if (!data) return false;

    // Define thresholds and validation logic
    const float lowerThreshold = 0.0;
    const float upperThreshold = 100.0;

    return (data->measurementValue >= lowerThreshold &&
            data->measurementValue <= upperThreshold &&
            data->qualityFlag);
}

void* processSensorDataStream(void* arg) {
    // Setup WebSocket connection
    char* sensorType = (char*)arg;
    int retryCount = 0;
    const int maxRetries = 5;

    while (retryCount < maxRetries) {
        // Connect to WebSocket server with given sensor type and version compatibility checks
        printf("Connecting to WebSocket server for sensor: %s\n", sensorType);

        // Simulate connection setup and check version
        bool isConnected = true; // Assume successful connection for demo

        if (isConnected && validateWebSocketVersion()) {
            char buffer[MAX_BUFFER_SIZE];
            size_t bytesRead;

            while ((bytesRead = receiveData(buffer, sizeof(buffer))) > 0) {
                pthread_mutex_lock(&globalArray.lock);

                Data* dataPoint = parseData(buffer, bytesRead);
                if (!dataPoint || !validateData(dataPoint)) {
                    free(dataPoint);
                    pthread_mutex_unlock(&globalArray.lock);
                    continue;
                }

                addDataToDynamicArray(&globalArray, *dataPoint);
                free(dataPoint);

                // Handle out-of-sequence data by sorting or buffering
                sortOrBufferOutOfSequenceData();

                pthread_mutex_unlock(&globalArray.lock);
            }
        } else {
            printf("Connection failed. Retrying...\n");
            retryCount++;
            sleep((1 << retryCount) * 1000); // Exponential backoff
        }

        if (isConnected) break;
    }

    if (!isConnected) {
        fprintf(stderr, "Failed to establish connection after %d attempts.\n", maxRetries);
        return (void*)-1;
    }

    return NULL;
}

bool validateWebSocketVersion() {
    // Simulate version compatibility check
    return true; 
}

size_t receiveData(char* buffer, size_t bufferSize) {
    // Simulate data reception from WebSocket
    memset(buffer, 0, bufferSize);
    return sizeof(Data); // Example: Assume we always read a full Data structure
}

Data* parseData(const char* buffer, size_t bytesRead) {
    if (bytesRead < sizeof(Data)) return NULL;

    Data* data = (Data*)malloc(sizeof(Data));
    if (!data) return NULL;

    memcpy(data, buffer, sizeof(Data));

    return data;
}

void sortOrBufferOutOfSequenceData() {
    // Implement sorting or buffering logic for out-of-sequence data
}

int main(int argc, char** argv) {
    DynamicArray* dataArray = createDynamicArray(10);
    if (!dataArray) {
        fprintf(stderr, "Failed to initialize dynamic array.\n");
        return -1;
    }

    globalArray = *dataArray;

    pthread_t threadId;
    const char* sensorType = "temperature";

    int result = pthread_create(&threadId, NULL, processSensorDataStream, (void*)sensorType);
    if (result != 0) {
        fprintf(stderr, "Failed to create processing thread.\n");
        freeDynamicArray(dataArray);
        return -1;
    }

    void* threadResult;
    pthread_join(threadId, &threadResult);

    if ((intptr_t)threadResult == -1) {
        fprintf(stderr, "Error occurred in data stream processing.\n");
    }

    freeDynamicArray(dataArray);
    return 0;
}
