    size_t count;
    size_t capacity;
    pthread_spinlock_t lock;  // Using spinlocks for high concurrency
    size_t total_resource_size;
} DataManager;

DataManager* create_data_manager() {
    DataManager *manager = malloc(sizeof(DataManager));
    manager->objects = malloc(INITIAL_CAPACITY * sizeof(DataObject *));
    manager->count = 0;
    manager->capacity = INITIAL_CAPACITY;
    pthread_spin_init(&manager->lock, PTHREAD_PROCESS_PRIVATE);
    manager->total_resource_size = 0;

    return manager;
}

void resize_data_manager(DataManager *manager) {
    size_t new_capacity = manager->capacity * 2;
    DataObject **new_objects = realloc(manager->objects, new_capacity * sizeof(DataObject *));

    if (new_objects != NULL) {
        manager->objects = new_objects;
        manager->capacity = new_capacity;
    } else {
        // Handle allocation failure
        fprintf(stderr, "Failed to resize data manager\n");
    }
}

DataObject* create_data_object(const char *resource_type, size_t resource_size) {
    DataObject *obj = malloc(sizeof(DataObject));
    obj->timestamp = time(NULL);
    obj->status = STATUS_NEW;
    obj->resource = malloc(sizeof(Resource));
    strncpy(obj->resource->type, resource_type, sizeof(obj->resource->type) - 1);
    obj->resource->size = resource_size;

    return obj;
}

void add_data_object(DataManager *manager, DataObject *obj) {
    pthread_spin_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        resize_data_manager(manager);
    }

    if (manager->count < MAX_OBJECTS) {
        manager->objects[manager->count++] = obj;
        manager->total_resource_size += obj->resource->size;

        // Update status based on conditions
        obj->status = STATUS_ACTIVE;  // Example condition
    } else {
        fprintf(stderr, "Maximum object count reached\n");
    }

    pthread_spin_unlock(&manager->lock);
}

void serialize_data_manager(DataManager *manager) {
    pthread_spin_lock(&manager->lock);

    FILE *file = fopen("data_state.json", "w");
    if (file == NULL) {
        perror("Failed to open file for serialization");
        return;
    }

    fprintf(file, "[\n");
    for (size_t i = 0; i < manager->count; ++i) {
        DataObject *obj = manager->objects[i];
        fprintf(file, "  {\"timestamp\": %ld, \"status\": \"%d\", \"resource_type\": \"%s\", \"resource_size\": %zu}",
                obj->timestamp, obj->status, obj->resource->type, obj->resource->size);
        if (i < manager->count - 1) {
            fprintf(file, ",");
        }
        fprintf(file, "\n");
    }
    fprintf(file, "]\n");

    fclose(file);

    pthread_spin_unlock(&manager->lock);
}

void free_data_manager(DataManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->objects[i]->resource);
        free(manager->objects[i]);
    }
    free(manager->objects);
    pthread_spin_destroy(&manager->lock);
    free(manager);
}

int main() {
    DataManager *manager = create_data_manager();

    for (size_t i = 0; i < 20; ++i) {
        DataObject *obj = create_data_object("ResourceType", rand() % 1024 + 1);
        add_data_object(manager, obj);
    }

    serialize_data_manager(manager);

    free_data_manager(manager);
    return 0;
}
```

### Key Points:
- **Thread Safety**: Spinlocks are used for high-concurrency scenarios.
- **Dynamic Resizing**: The collection resizes dynamically using exponential growth strategy.
- **Serialization**: Data is serialized in JSON format to a file named `data_state.json`.
- **Memory Management**: Objects are managed dynamically with custom memory allocation and deallocation functions.
- **Concurrency Handling**: Spinlocks ensure safe concurrent access.
- **Resource Tracking**: Total resource size is tracked and updated with each new object addition.']

