#include <time.h>

#define INITIAL_CAPACITY 10

typedef struct {
    int value;
    int *ptr;
} Record;

typedef struct {
    long *offsets;
    int *keys;
    Record **records;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} StructType;

// Function to resize the records array
void resizeRecords(StructType *structData) {
    pthread_mutex_lock(&structData->lock);

    if (structData->count >= structData->capacity) {
        size_t newCapacity = structData->capacity == 0 ? INITIAL_CAPACITY : structData->capacity * 2;
        Record **newRecords = realloc(structData->records, newCapacity * sizeof(Record *));

        if (newRecords) {
            memset(newRecords + structData->capacity, 0, (newCapacity - structData->capacity) * sizeof(Record *));
            structData->records = newRecords;
            structData->capacity = newCapacity;
        } else {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&structData->lock);
            exit(EXIT_FAILURE);
        }
    }

    pthread_mutex_unlock(&structData->lock);
}

// Function to initialize records with random values
void initRecords(StructType *structData) {
    long sum = 0;
    for (size_t i = 0; i < structData->count; ++i) {
        sum += structData->records[i]->value;
    }

    double average = structData->count > 0 ? (double)sum / structData->count : 1.0;

    pthread_mutex_lock(&structData->lock);

    for (size_t i = structData->count; i < structData->capacity; ++i) {
        resizeRecords(structData);

        double range = average * 2;
        int minValue = (int)(average - range / 2);
        int maxValue = (int)(average + range / 2);

        structData->records[i] = malloc(sizeof(Record));
        if (!structData->records[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&structData->lock);
            exit(EXIT_FAILURE);
        }

        structData->records[i]->value = minValue + rand() % (maxValue - minValue + 1);
        sum += structData->records[i]->value;
        average = (double)sum / (i + 1);
    }

    pthread_mutex_unlock(&structData->lock);
}

// Callback function for further processing
void processString(const char *str) {
    printf("Processing string: %s\n", str);
}

// Main function to process the string and records
const char* processStringAndProcessRecords(const char *input, int sizeLimit, void *dataPtr) {
    StructType *structData = (StructType *)dataPtr;

    pthread_mutex_init(&structData->lock, NULL);

    if (strlen(input) > sizeLimit) {
        printf("String exceeds the size limit\n");
        return NULL;
    }

    char *modifiedStr = malloc(strlen(input) + 2);
    snprintf(modifiedStr, strlen(input) + 2, "%s/", input);

    processString(modifiedStr);

    for (size_t i = 0; i < INITIAL_CAPACITY; ++i) {
        resizeRecords(structData);
    }

    initRecords(structData);

    free(modifiedStr);
    pthread_mutex_destroy(&structData->lock);

    return modifiedStr;
}

// Function to safely release all allocated memory
void cleanupStruct(StructType *structData) {
    pthread_mutex_lock(&structData->lock);

    for (size_t i = 0; i < structData->count; ++i) {
        free(structData->records[i]);
    }

    free(structData->records);
    free(structData->offsets);
    free(structData->keys);

    pthread_mutex_unlock(&structData->lock);
}
