from contextlib import contextmanager
import sys

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class TimeoutException(Exception):
    pass

@contextmanager
def timeout(time_duration):
    def raise_timeout(signum, frame):
        raise TimeoutException("Timed out!")

    signal.signal(signal.SIGALRM, raise_timeout)
    signal.alarm(time_duration)
    try:
        yield
    finally:
        signal.alarm(0)

def run_test(label, f, sync_quality_threshold, test_duration):
    module_name = 'c_module'  # Assuming the C code is compiled into this Python extension
    c_module = importlib.import_module(module_name)

    logging.info(f"Running tests for module: {module_name}")
    logging.info(f"Test label: {label}")

    try:
        with timeout(test_duration):
            result = f(c_module)
            if result < sync_quality_threshold:
                logging.error(f"Sync quality check failed. Result: {result}, Threshold: {sync_quality_threshold}")
            else:
                logging.info(f"Test passed. Sync quality: {result}")
    except TimeoutException:
        logging.error("Test exceeded the duration limit.")
    except Exception as e:
        logging.error(f"An error occurred during testing: {e}")

# Example test function
def example_test_function(c_module):
    # Assume 'c_module' has a method to get sync quality for demonstration
    sync_quality = c_module.get_sync_quality()
    return sync_quality

if __name__ == "__main__":
