#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include "json-c/json.h" // Ensure you have the json-c library installed

#define MAX_RECORDS 10000
#define INIT_ARRAY_SIZE 1000

typedef struct {
    int value;
} record;

typedef struct {
    float f_value;
    int i_value;
    bool b_value;
    double latitude;
    double longitude;
} data;

typedef struct {
    pthread_mutex_t mutex;
    long* offsets;
    int* keys;
    record* records;
    double* doubles;
    char** strings;
    data* datas;
    size_t current_size;
    size_t max_size;
} memory_manager;

void init_memory(memory_manager* mm, size_t initial_size) {
    pthread_mutex_init(&mm->mutex, NULL);
    mm->current_size = 0;
    mm->max_size = initial_size;

    mm->offsets = (long*)malloc(initial_size * sizeof(long));
    mm->keys = (int*)malloc(initial_size * sizeof(int));
    mm->records = (record*)malloc(initial_size * sizeof(record));
    mm->doubles = (double*)malloc(initial_size * sizeof(double));
    mm->strings = (char**)malloc(initial_size * sizeof(char*));
    mm->datas = (data*)malloc(initial_size * sizeof(data));

    for (size_t i = 0; i < initial_size; ++i) {
        mm->offsets[i] = rand() % 10000;
        mm->keys[i] = rand() % 10000;
        mm->records[i].value = rand() % 10000;
        mm->doubles[i] = (double)(rand() % 1000) / 10.0;
        mm->strings[i] = strdup("default");
        mm->datas[i].f_value = (float)(rand() % 1000) / 10.0;
        mm->datas[i].i_value = rand() % 10000;
        mm->datas[i].b_value = rand() % 2 == 0;
        mm->datas[i].latitude = ((double)rand() / RAND_MAX * 180.0) - 90.0;
        mm->datas[i].longitude = ((double)rand() / RAND_MAX * 360.0) - 180.0;
    }
}

void resize_memory(memory_manager* mm, size_t new_size) {
    pthread_mutex_lock(&mm->mutex);

    if (new_size > mm->max_size) {
        mm->offsets = (long*)realloc(mm->offsets, new_size * sizeof(long));
        mm->keys = (int*)realloc(mm->keys, new_size * sizeof(int));
        mm->records = (record*)realloc(mm->records, new_size * sizeof(record));
        mm->doubles = (double*)realloc(mm->doubles, new_size * sizeof(double));
        char** temp_strings = (char**)malloc(new_size * sizeof(char*));

        for (size_t i = 0; i < new_size; ++i) {
            if (i < mm->current_size) {
                temp_strings[i] = strdup(mm->strings[i]);
                free(mm->strings[i]);
            } else {
                temp_strings[i] = strdup("default");
            }
        }

        free(mm->strings);
        mm->strings = temp_strings;

        mm->datas = (data*)realloc(mm->datas, new_size * sizeof(data));
    }

    pthread_mutex_unlock(&mm->mutex);
}

void serialize_state(memory_manager* mm, const char* filename) {
    pthread_mutex_lock(&mm->mutex);

    json_object *jobj = json_object_new_object();
    for (size_t i = 0; i < mm->current_size; ++i) {
        json_object *record_obj = json_object_new_object();
        json_object_object_add(record_obj, "offset", json_object_new_int(mm->offsets[i]));
        json_object_object_add(record_obj, "key", json_object_new_int(mm->keys[i]));
        json_object_object_add(record_obj, "value", json_object_new_int(mm->records[i].value));
        json_object_object_add(record_obj, "double", json_object_new_double(mm->doubles[i]));
        char* str_dup = strdup(mm->strings[i]);
        json_object_object_add(record_obj, "string", json_object_new_string(str_dup));
        free(str_dup);

        json_object *data_obj = json_object_new_object();
        json_object_object_add(data_obj, "f_value", json_object_new_double(mm->datas[i].f_value));
        json_object_object_add(data_obj, "i_value", json_object_new_int(mm->datas[i].i_value));
        json_object_object_add(data_obj, "b_value", json_object_new_boolean(mm->datas[i].b_value));
        json_object_object_add(data_obj, "latitude", json_object_new_double(mm->datas[i].latitude));
        json_object_object_add(record_obj, "longitude", json_object_new_double(mm->datas[i].longitude));

        json_object_object_add(jobj, json_stringify(i), record_obj);
    }

    FILE* fp = fopen(filename, "w");
    if (fp) {
        fprintf(fp, "%s\n", json_object_to_json_string_ext(jobj, JSON_C_TO_STRING_PLAIN));
        fclose(fp);
    }

    pthread_mutex_unlock(&mm->mutex);
    json_object_put(jobj);
}

void free_memory(memory_manager* mm) {
    pthread_mutex_lock(&mm->mutex);

    for (size_t i = 0; i < mm->current_size; ++i) {
        free(mm->strings[i]);
    }

    free(mm->offsets);
    free(mm->keys);
    free(mm->records);
    free(mm->doubles);
    free(mm->strings);
    free(mm->datas);

    pthread_mutex_unlock(&mm->mutex);
}

// Example usage:
int main() {
    memory_manager mm;
    init_memory(&mm, INIT_ARRAY_SIZE);

    // Simulate operations
    resize_memory(&mm, 2000);
    serialize_state(&mm, "state.json");
    free_memory(&mm);

    return 0;
}
