#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        bool CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->data) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

bool add_element(DynamicArray* array, int RX_UE_INFORMATION_TAG, int RNTI, bool CRCFLAG) {
    if (!array) return false;

    pthread_mutex_lock(&array->mutex);

    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&array->mutex);
            return false;
        }
        array->data = new_data;
        array->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T* element = &array->data[array->size];
    element->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    element->RNTI = RNTI;
    element->CRC_INDICATION_REL8_TAG.CRCFLAG = CRCFLAG;

    array->size++;
    pthread_mutex_unlock(&array->mutex);
    return true;
}

bool get_element(const DynamicArray* array, size_t index, NFAPI_CRC_INDICATION_PDU_T* out_element) {
    if (!array || !out_element || index >= array->size) return false;

    *out_element = array->data[index];
    return true;
}

void iterate_elements(const DynamicArray* array, void (*callback)(const NFAPI_CRC_INDICATION_PDU_T*)) {
    if (!array || !callback) return;

    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size; ++i) {
        callback(&array->data[i]);
    }
    pthread_mutex_unlock(&array->mutex);
}

void free_dynamic_array(DynamicArray* array) {
    if (!array) return;

    pthread_mutex_lock(&array->mutex);
    free(array->data);
    pthread_mutex_unlock(&array->mutex);

    pthread_mutex_destroy(&array->mutex);
    free(array);
}
