using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading.Tasks;
using System.Linq;
using System.Diagnostics;
using System.IO;
using Microsoft.Extensions.Caching.Memory;

public class HttpClientLibrary : IDisposable
{
    private readonly HttpClient _httpClient;
    private readonly IMemoryCache _cache;
    private const int CacheSizeLimit = 1024 * 1024 * 50; // 50 MB

    public HttpClientLibrary()
    {
        _httpClient = new HttpClient();
        _httpClient.DefaultRequestHeaders.Add("User-Agent", "HttpClientLibrary");
        _cache = new MemoryCache(new MemoryCacheOptions { SizeLimit = CacheSizeLimit });
    }

    public async Task<HttpResponseMessage> SendAsync(
        string method,
        Uri url,
        IDictionary<string, string> headers = null,
        IDictionary<string, string> queryParams = null,
        HttpContent content = null)
    {
        var stopwatch = new Stopwatch();
        stopwatch.Start();

        try
        {
            // Construct the request URI with query parameters
            var queryString = string.Join("&", queryParams?.Select(kvp => $"{Uri.EscapeDataString(kvp.Key)}={Uri.EscapeDataString(kvp.Value)}"));
            var fullUrl = url + (queryString != null ? "?" + queryString : "");

            // Create cache key
            var cacheKey = GetCacheKey(method, fullUrl, headers, content);

            if (_cache.TryGetValue(cacheKey, out HttpResponseMessage cachedResponse))
            {
                stopwatch.Stop();
                LogPerformance(method, fullUrl, stopwatch.ElapsedMilliseconds, cachedResponse.StatusCode);
                return cachedResponse;
            }

            // Prepare the HTTP request message
            var requestMessage = new HttpRequestMessage(new HttpMethod(method), fullUrl) { Content = content };

            // Add headers to the request
            if (headers != null)
            {
                foreach (var header in headers)
                {
                    requestMessage.Headers.TryAddWithoutValidation(header.Key, header.Value);
                }
            }

            // Send HTTP request asynchronously
            var response = await _httpClient.SendAsync(requestMessage);

            // Cache the response
            _cache.Set(cacheKey, response, TimeSpan.FromMinutes(5));

            stopwatch.Stop();
            LogPerformance(method, fullUrl, stopwatch.ElapsedMilliseconds, response.StatusCode);
            return response;
        }
        catch (Exception ex)
        {
            stopwatch.Stop();
            Console.WriteLine($"Error: {ex.Message}");
            throw; // Graceful handling could involve logging and/or returning a default/fallback response
        }
    }

    private string GetCacheKey(string method, Uri url, IDictionary<string, string> headers, HttpContent content)
    {
        var headerString = headers != null ? string.Join(",", headers.Select(h => $"{h.Key}:{string.Join(";", h.Value)}")) : "";
        var bodyString = content != null ? ReadHttpContent(content) : "";

        return $"{method}_{url.AbsoluteUri}_{headerString}_{bodyString}";
    }

    private async Task<string> ReadHttpString(HttpContent content)
    {
        using (var reader = new StreamReader(await content.ReadAsStreamAsync()))
        {
            return await reader.ReadToEndAsync();
        }
    }

    private string ReadHttpContent(HttpContent content)
    {
        if (content == null) return "";

        var readTask = ReadHttpString(content);
        return Task.Run(readTask).GetAwaiter().GetResult(); // Synchronously wait for async operation
    }

    private void LogPerformance(string method, Uri url, long latencyMs, System.Net.HttpStatusCode statusCode)
    {
        Console.WriteLine($"Method: {method}, URL: {url}, Latency: {latencyMs}ms, Status Code: {statusCode}");
    }

    public void Dispose()
    {
        _httpClient?.Dispose();
    }
}
```

### Additional Notes:

- The library supports asynchronous operations and exception handling.
- It uses `MemoryCache` for caching responses based on request parameters.
- Provides a mechanism to track request latency and log response status codes.
- Developers can extend the library by adding support for different authentication schemes or modifying caching policies.

This code is designed with extensibility, performance monitoring, and efficient resource management in mind.']

