#define MAX_STRUCTS_PER_SESSION 1000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG; // Randomly set
    time_t timestamp; // Unique timestamp for tracking creation
    int sequence_number; // Sequence number for tracking within a session
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *structures;
    size_t count;
    size_t capacity;
} DynamicList;

int isValidRNTI(uint16_t rnti) {
    return rnti <= 65535;
}

DynamicList* create_dynamic_list() {
    DynamicList *list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) {
        perror("Failed to allocate memory for list");
        return NULL;
    }
    list->structures = NULL;
    list->count = 0;
    list->capacity = 0;
    return list;
}

int add_structure(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T new_struct) {
    if (list->count >= MAX_STRUCTS_PER_SESSION) {
        fprintf(stderr, "Session limit reached. Cannot add more structures.\n");
        return -1; // Indicate failure due to session limit
    }

    if (!isValidRNTI(new_struct.RNTI)) {
        fprintf(stderr, "Invalid RNTI value: %u\n", new_struct.RNTI);
        return 0; // Continue processing valid entries
    }

    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity == 0 ? 10 : list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_structures = realloc(list->structures, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_structures) {
            perror("Failed to allocate memory for structures");
            return -1; // Indicate failure due to allocation error
        }
        list->structures = new_structures;
        list->capacity = new_capacity;
    }

    // Set timestamp and sequence number
    time(&new_struct.timestamp);
    new_struct.sequence_number = list->count;

    list->structures[list->count++] = new_struct;
    return 1; // Indicate success
}

size_t get_total_count(DynamicList *list) {
    return list->count;
}

void free_dynamic_list(DynamicList *list) {
    if (list) {
        free(list->structures);
        free(list);
    }
}

int main() {
    DynamicList *list = create_dynamic_list();
    if (!list) return 1;

    // Example usage
    for (int i = 0; i < 2000; ++i) { // Simulate more than MAX_STRUCTS_PER_SESSION entries
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand();
        pdu.RNTI = rand() % 70000; // Random RNTI, some will be invalid
        pdu.CRC_INDICATION_REL8_TAG = rand() % 256;
        pdu.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

        add_structure(list, pdu);
    }

    printf("Total valid structures added: %zu\n", get_total_count(list));

    free_dynamic_list(list);
    return 0;
}
