void log_error(const char *message, const char *file_location) {
    fprintf(stderr, "Error: %s at %s\n", message, file_location);
}

NFAPI_CRC_INDICATION_PDU_T* read_nfa_crc_indication_pdu_from_file(
    const char *filename,
    size_t *count
) {
    FILE *fp = fopen(filename, "rb");
    if (!fp) {
        perror("Failed to open file");
        return NULL;
    }

    // Attempt to determine the number of structures by reading the file size
    fseek(fp, 0, SEEK_END);
    long filesize = ftell(fp);
    if (filesize <= 0) {
        log_error("Invalid file size", filename);
        fclose(fp);
        return NULL;
    }
    rewind(fp);

    // Calculate expected count based on structure size (assumed to be known)
    const size_t structure_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    *count = filesize / structure_size;

    if (filesize % structure_size != 0) {
        log_error("File does not contain complete structures", filename);
        fclose(fp);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(*count * structure_size);
    if (!pdus) {
        perror("Failed to allocate memory");
        fclose(fp);
        return NULL;
    }

    size_t read_count = fread(pdus, structure_size, *count, fp);
    if (read_count != *count) {
        free(pdus);
        log_error("File read incomplete or corrupted", filename);
        fclose(fp);
        return NULL;
    }

    // Populate timestamp for each structure
    time_t current_time = time(NULL);
    for (size_t i = 0; i < *count; ++i) {
        struct tm *tm_info = localtime(&current_time);
        pdus[i].rx_ue_information_tag = (uint32_t)(mktime(tm_info) & 0xFFFFFFFF); // Example timestamp
    }

    fclose(fp);
    return pdus;
}

void free_nfa_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *pdus, size_t count) {
    if (pdus) {
        free(pdus);
    }
}
