    private $db;
    private $redisClient;
    private $emailService;

    public function __construct($dbConnection, $redisClient, $emailService) {
        $this->db = $dbConnection;
        $this->redisClient = $redisClient;
        $this->emailService = $emailService;
    }

    public function manageAccount() {
        try {
            // Start transaction
            $this->db->beginTransaction();

            $id = $_REQUEST['id'] ?? null;
            $name = $_REQUEST['name'] ?? '';
            $email = $_REQUEST['email'] ?? '';
            $password = $_REQUEST['password'] ?? '';
            $subAction = $_REQUEST['sub_action'] ?? '';
            $confirmationToken = $_REQUEST['confirmation_token'] ?? '';

            if (!$this->validate($id, $name, $email, $password, $subAction, $confirmationToken)) {
                throw new Exception('Validation failed.');
            }

            switch ($subAction) {
                case 'create':
                    $this->createUser($name, $email, $password);
                    break;

                case 'update':
                    $this->updateUser($id, $name, $email, $password);
                    break;

                case 'delete':
                    if (!$this->validateDeletion($confirmationToken)) {
                        throw new Exception('Invalid confirmation token.');
                    }
                    $this->deleteUser($id, $confirmationToken);
                    break;

                default:
                    throw new Exception('Invalid sub_action.');
            }

            // Commit transaction
            $this->db->commit();
        } catch (Exception $e) {
            // Rollback on error
            $this->db->rollBack();
            $this->logError($e->getMessage());
            echo json_encode(['error' => $e->getMessage()]);
        }
    }

    private function validate($id, $name, $email, $password, $subAction, $confirmationToken) {
        if (empty($name) || empty($email)) return false;

        if (!preg_match('/^(?=.*\d)(?=.*[!@#$%^&*])(?=.*[a-z]).{8,}$/', $password)) return false;

        if ($subAction === 'create' && !$this->isEmailUnique($email)) {
            return false;
        }

        if ($subAction === 'delete' && !$this->isValidConfirmationToken($id, $confirmationToken)) {
            return false;
        }

        return true;
    }

    private function isEmailUnique($email) {
        // Check if email exists in the database
        $stmt = $this->db->prepare('SELECT COUNT(*) FROM users WHERE email = :email');
        $stmt->execute([':email' => $email]);
        return $stmt->fetchColumn() == 0;
    }

    private function isValidConfirmationToken($id, $confirmationToken) {
        // Validate confirmation token logic
        $stmt = $this->db->prepare('SELECT COUNT(*) FROM users WHERE id = :id AND confirmation_token = :token');
        $stmt->execute([':id' => $id, ':token' => $confirmationToken]);
        return $stmt->fetchColumn() > 0;
    }

    private function createUser($name, $email, $password) {
        // Acquire distributed lock
        if (!$this->redisClient->setnx("lock:user:create", 1)) {
            throw new Exception('Unable to acquire lock for user creation.');
        }

        try {
            $stmt = $this->db->prepare('INSERT INTO users (name, email, password) VALUES (:name, :email, :password)');
            $stmt->execute([':name' => $name, ':email' => $email, ':password' => password_hash($password, PASSWORD_DEFAULT)]);
        } finally {
            // Release lock
            $this->redisClient->del("lock:user:create");
        }
    }

    private function updateUser($id, $name, $email, $password) {
        if (!$this->validateUserId($id)) return;

        // Acquire distributed lock
        if (!$this->redisClient->setnx("lock:user:update:$id", 1)) {
            throw new Exception('Unable to acquire lock for user update.');
        }

        try {
            $stmt = $this->db->prepare('UPDATE users SET name = :name, email = :email, password = :password WHERE id = :id');
            $stmt->execute([':name' => $name, ':email' => $email, ':password' => password_hash($password, PASSWORD_DEFAULT), ':id' => $id]);
        } finally {
            // Release lock
            $this->redisClient->del("lock:user:update:$id");
        }
    }

    private function deleteUser($id, $confirmationToken) {
        if (!$this->validateUserId($id)) return;

        // Acquire distributed lock
        if (!$this->redisClient->setnx("lock:user:delete:$id", 1)) {
            throw new Exception('Unable to acquire lock for user deletion.');
        }

        try {
            $stmt = $this->db->prepare('DELETE FROM users WHERE id = :id AND confirmation_token = :token');
            $stmt->execute([':id' => $id, ':token' => $confirmationToken]);

            if ($stmt->rowCount() > 0) {
                // Send email notification
                $this->emailService->sendConfirmationEmail($id);
            } else {
                throw new Exception('Deletion failed.');
            }
        } finally {
            // Release lock
            $this->redisClient->del("lock:user:delete:$id");
        }
    }

    private function validateUserId($id) {
        $stmt = $this->db->prepare('SELECT COUNT(*) FROM users WHERE id = :id');
        $stmt->execute([':id' => $id]);
        return $stmt->fetchColumn() > 0;
    }

    private function logError($message) {
        // Implement logging logic
        error_log($message);
    }
}

// Usage example:
$dbConnection = new PDO('mysql:host=localhost;dbname=testdb', 'username', 'password');
$redisClient = new Redis();
$redisClient->connect('127.0.0.1', 6379);
$emailService = new EmailService(); // Assume this is a class that handles email operations

$userManager = new UserManager($dbConnection, $redisClient, $emailService);
$userManager->manageAccount();

?>
