void* initialize_arrays(long num_records, int min_value, int max_value, size_t max_buf_size, size_t total_memory_limit) {
    if (num_records <= 0 || max_buf_size == 0 || total_memory_limit == 0) {
        return ERROR_PTR;
    }

    long offset_array_size = num_records * sizeof(long);
    int key_array_size = num_records * sizeof(int);
    record *records = NULL;

    size_t record_struct_size = sizeof(record) + max_buf_size - 1; // -1 because we don't count the null terminator
    size_t total_memory_needed = offset_array_size + key_array_size + (num_records * record_struct_size);

    if (total_memory_needed > total_memory_limit) {
        return ERROR_PTR;
    }

    pthread_mutex_lock(&lock);

    long* offsets = malloc(offset_array_size);
    int* keys = malloc(key_array_size);
    records = malloc(num_records * sizeof(record));

    if (!offsets || !keys || !records) {
        free(offsets); // Avoid memory leak
        free(keys);    // Avoid memory leak
        free(records); // Avoid memory leak
        pthread_mutex_unlock(&lock);
        return ERROR_PTR;
