}

// Function to create and populate the linked list
NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu_list(size_t count) {
    pthread_rwlock_wrlock(&rwlock);

    NFAPI_CRC_INDICATION_PDU_T *new_node = NULL;
    NFAPI_CRC_INDICATION_PDU_T *last_node = head;

    for (size_t i = 0; i < count; ++i) {
        new_node = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_node) {
