        new_node->rnti = new_node->rx_ue_information_tag.RNTI;
        new_node->crc_indication_rel8_tag.CRCFLAG = generate_random_crcflag();

        if (head == NULL) {
            head = new_node;
        } else {
            last_node->next = new_node;
        }

        last_node = new_node;
    }

    pthread_rwlock_unlock(&rwlock);
    return head;
}

// Function to free the linked list
void free_crc_indication_pdu_list() {
    pthread_rwlock_wrlock(&rwlock);

    NFAPI_CRC_INDICATION_PDU_T *current = head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }

    head = NULL;

    pthread_rwlock_unlock(&rwlock);
}

// Example usage
int main() {
    // Initialize random seed
    srand(time(NULL));

    // Create a list with 10 entries
    create_crc_indication_pdu_list(10);

    // Free the list after use
    free_crc_indication_pdu_list();

    return 0;
}
