#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MEMORY_POOL_SIZE 1024 * 1024 // Example pool size: 1 MB

typedef struct {
    double value;
    char identifier;
} custom_record;

typedef struct MemoryBlock {
    void* start;
    size_t size;
    struct MemoryBlock* next;
} MemoryBlock;

static pthread_mutex_t memory_pool_lock = PTHREAD_MUTEX_INITIALIZER;
static MemoryBlock* free_blocks = NULL;

void initialize_memory_pool(size_t pool_size) {
    void* pool_start = malloc(pool_size);
    if (!pool_start) {
        perror("Failed to allocate memory pool");
        exit(EXIT_FAILURE);
    }

    MemoryBlock* block = (MemoryBlock*)malloc(sizeof(MemoryBlock));
    if (!block) {
        free(pool_start);
        perror("Failed to allocate memory for block header");
        exit(EXIT_FAILURE);
    }

    block->start = pool_start;
    block->size = pool_size;
    block->next = NULL;

    pthread_mutex_lock(&memory_pool_lock);
    free_blocks = block;
    pthread_mutex_unlock(&memory_pool_lock);
}

void* allocate_memory(size_t size) {
    pthread_mutex_lock(&memory_pool_lock);

    MemoryBlock** current = &free_blocks;
    while (*current) {
        if ((*current)->size >= size) {
            void* allocated_memory = (*current)->start;
            (*current)->start = (char*)allocated_memory + size;
            (*current)->size -= size;

            if ((*current)->size == 0) {
                MemoryBlock* temp = *current;
                *current = (*current)->next;
                free(temp);
            }

            pthread_mutex_unlock(&memory_pool_lock);
            return allocated_memory;
        }
        current = &(*current)->next;
    }

    // If no block is large enough, allocate a new one
    void* new_block_start = malloc(size + sizeof(MemoryBlock));
    if (!new_block_start) {
        pthread_mutex_unlock(&memory_pool_lock);
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    MemoryBlock* new_block = (MemoryBlock*)((char*)new_block_start + size);
    new_block->start = new_block_start;
    new_block->size = sizeof(MemoryBlock);
    new_block->next = NULL;

    *current = new_block;
    pthread_mutex_unlock(&memory_pool_lock);

    return new_block_start;
}

void deallocate_memory(void* ptr) {
    // Simplified example: assume each allocation is independent for now
    // Implement a free list or similar strategy for real use cases

    pthread_mutex_lock(&memory_pool_lock);
    // Add to some form of free list (not implemented)
    pthread_mutex_unlock(&memory_pool_lock);
}

void* allocate_aligned_memory(size_t size, size_t alignment) {
    void* raw_ptr = malloc(size + alignment + sizeof(void*));
    if (!raw_ptr) return NULL;

    uintptr_t aligned_address = (uintptr_t)(((uintptr_t)raw_ptr + alignment + sizeof(void*)) & ~(alignment - 1));

    *((void**)((char*)aligned_address - sizeof(void*))) = raw_ptr;

    void* result = (void*)aligned_address;
    ((char*)result)[size] = '\0'; // Ensure zeroed out memory

    return result;
}

typedef struct {
    long* long_array;
    short* short_array;
    custom_record* record_array;
} DataStructures;

DataStructures manage_data_structures(size_t num_elements, int use_memory_pool) {
    pthread_mutex_lock(&memory_pool_lock);

    size_t long_array_size = num_elements * sizeof(long);
    size_t short_array_size = num_elements * sizeof(short);
    size_t record_array_size = num_elements * sizeof(custom_record);

    void* long_ptr;
    void* short_ptr;
    void* record_ptr;

    if (use_memory_pool) {
        long_ptr = allocate_memory(long_array_size);
        short_ptr = allocate_memory(short_array_size);
        record_ptr = allocate_memory(record_array_size);
    } else {
        long_ptr = aligned_alloc(alignof(long), long_array_size);
        short_ptr = aligned_alloc(alignof(short), short_array_size);
        record_ptr = aligned_alloc(alignof(custom_record), record_array_size);
    }

    memset(long_ptr, 0, long_array_size);
    memset(short_ptr, 0, short_array_size);
    memset(record_ptr, 0, record_array_size);

    pthread_mutex_unlock(&memory_pool_lock);

    DataStructures data_structures = {
        .long_array = (long*)long_ptr,
        .short_array = (short*)short_ptr,
        .record_array = (custom_record*)record_ptr
    };

    return data_structures;
}

void free_data_structures(DataStructures* data_structures, int use_memory_pool) {
    if (use_memory_pool) {
        deallocate_memory(data_structures->long_array);
        deallocate_memory(data_structures->short_array);
        deallocate_memory(data_structures->record_array);
    } else {
        free(data_structures->long_array);
        free(data_structures->short_array);
        free(data_structures->record_array);
    }
}

