}

void startStream(int index, int priority) {
    if (index < 0 || index >= MAX_STREAMS) return;

    StreamConfig *config = &streams[index];
    config->priority = priority;
    config->active = 1;
    pthread_create(&config->thread_id, NULL, streamHandler, config);
    running_streams++;
}

void stopStream(int index) {
    if (index < 0 || index >= MAX_STREAMS) return;

    StreamConfig *config = &streams[index];
    pthread_mutex_lock(&mutex);
    config->active = 0;
    pthread_join(config->thread_id, NULL);  // Ensure thread completion
    running_streams--;
    pthread_mutex_unlock(&mutex);
}

void generateReport() {
    printf("Metrics Report:\n");
    for (int i = 0; i < MAX_STREAMS; i++) {
        if (streams[i].active) {
            printf("Stream %d: Throughput=%f, Latency=%f ms, Error Rate=%f%%\n",
                   i,
                   metrics[i].throughput,
                   metrics[i].latency,
                   metrics[i].error_rate);
        }
    }
}

void resetMetrics() {
    for (int i = 0; i < MAX_STREAMS; i++) {
        pthread_mutex_lock(&mutex);
        metrics[i].throughput = 0.0;
        metrics[i].latency = 0.0;
        metrics[i].error_rate = 0.0;
        pthread_mutex_unlock(&mutex);
    }
}

int main() {
