    for (int i = 0; i < MAX_STREAMS / 2; i++) {
        startStream(i, rand() % 10);  // Random priority between 0 and 9
    }

    while (running_streams > 0) {
        sleep(CONFIGURATION_INTERVAL);
        generateReport();
        resetMetrics();
    }

    return 0;
}
