NFAPI_CRC_INDICATION_PDU_T* manage_nfa_list(size_t n) {
    if (n == 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        perror("Failed to allocate memory for the list");
        exit(EXIT_FAILURE);
    }

    pthread_t threads[n];
    size_t chunk_size = n / 4; // Example: split work across 4 threads
    for (size_t i = 0; i < n; i += chunk_size) {
        size_t start = i;
        size_t end = (i + chunk_size > n) ? n : i + chunk_size;

        pthread_create(&threads[i / chunk_size], NULL, [](void* arg) -> void* {
            auto range = *(std::pair<size_t*, size_t*>*)arg;
            for (size_t j = range.first; j < range.second; ++j) {
                // Populate with randomly set CRCFLAG and other relevant fields
                list[j].ue_info = {/* populate fields */};
                list[j].rnti = rand();
                list[j].crc_tag.CRCFLAG = rand() % 2;
            }
            return NULL;
        }, new std::pair<size_t*, size_t*>(&start, &end));
    }

    for (size_t i = 0; i < n / chunk_size; ++i) {
        pthread_join(threads[i], NULL);
    }

    return list;
}

// Cleanup function
void free_nfa_list(NFAPI_CRC_INDICATION_PDU_T* list, size_t n) {
    if (list) {
        free(list);
    }
}
