#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_VERTICES 1000
#define MAX_EDGES 5000
#define MAX_ID_SIZE 1024
#define EDGE_WEIGHT_MIN 1
#define EDGE_WEIGHT_MAX 100

typedef struct {
    int weight;
} record;

typedef struct {
    long *vertex_offsets;
    int *vertex_keys;
    record **edge_weights;
    size_t num_vertices;
    size_t num_edges;
} DynamicGraph;

// Function prototypes
DynamicGraph* create_graph(size_t max_vertices, size_t max_edges);
void free_graph(DynamicGraph *graph);
int add_vertex(DynamicGraph *graph);
int add_edge(DynamicGraph *graph, int vertex1, int vertex2);

DynamicGraph* create_graph(size_t max_vertices, size_t max_edges) {
    DynamicGraph *graph = (DynamicGraph *)malloc(sizeof(DynamicGraph));
    if (!graph) return NULL;

    graph->vertex_offsets = (long *)calloc(max_vertices, sizeof(long));
    graph->vertex_keys = (int *)calloc(max_vertices, sizeof(int));
    graph->edge_weights = (record **)calloc(max_edges, sizeof(record *));
    if (!graph->vertex_offsets || !graph->vertex_keys || !graph->edge_weights) {
        free(graph->vertex_offsets);
        free(graph->vertex_keys);
        free(graph->edge_weights);
        free(graph);
        return NULL;
    }

    graph->num_vertices = 0;
    graph->num_edges = 0;

    // Seed random number generator
    srand(time(NULL));

    return graph;
}

void free_graph(DynamicGraph *graph) {
    if (!graph) return;

    for (size_t i = 0; i < graph->num_edges; ++i) {
        free(graph->edge_weights[i]);
    }
    free(graph->vertex_offsets);
    free(graph->vertex_keys);
    free(graph->edge_weights);
    free(graph);
}

int add_vertex(DynamicGraph *graph) {
    if (graph->num_vertices >= MAX_VERTICES) return -1;

    long offset = rand() % MAX_ID_SIZE;
    int key = rand() % MAX_ID_SIZE;

    graph->vertex_offsets[graph->num_vertices] = offset;
    graph->vertex_keys[graph->num_vertices] = key;
    ++graph->num_vertices;

    return 0;
}

int add_edge(DynamicGraph *graph, int vertex1, int vertex2) {
    if (graph->num_edges >= MAX_EDGES || vertex1 < 0 || vertex1 >= graph->num_vertices || vertex2 < 0 || vertex2 >= graph->num_vertices)
        return -1;

    record *edge = (record *)malloc(sizeof(record));
    if (!edge) return -1;

    edge->weight = EDGE_WEIGHT_MIN + rand() % (EDGE_WEIGHT_MAX - EDGE_WEIGHT_MIN + 1);
    graph->edge_weights[graph->num_edges] = edge;
    ++graph->num_edges;

    return 0;
}

int main() {
    DynamicGraph *graph = create_graph(MAX_VERTICES, MAX_EDGES);
    if (!graph) {
        fprintf(stderr, "Failed to create graph\n");
        return EXIT_FAILURE;
    }

    // Add random vertices and edges
    for (size_t i = 0; i < MAX_VERTICES / 2; ++i) {
        add_vertex(graph);
    }

    for (size_t i = 0; i < MAX_EDGES / 2; ++i) {
        int v1 = rand() % graph->num_vertices;
        int v2 = rand() % graph->num_vertices;
        add_edge(graph, v1, v2);
    }

    // Free resources
    free_graph(graph);

    return EXIT_SUCCESS;
