// Define the NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a stream node for linked list management of streams
typedef struct StreamNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct StreamNode* next;
} StreamNode;

// Define a structure for managing stream processing metrics
typedef struct {
    int totalProcessed;
    int errors;
    double averageLatency; // in milliseconds
} StreamMetrics;

// Function prototypes
void processStream(StreamNode* head);
void* threadFunction(void* arg);
void logEvent(const char* message);

// Global variables for simplicity (in a real-world scenario, consider encapsulation)
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
StreamMetrics metrics[10]; // Assuming a max of 10 concurrent streams

// Main stream processing module
void streamProcessingModule(int numStreams) {
    pthread_t threads[numStreams];
    StreamNode* streams[numStreams];

    for (int i = 0; i < numStreams; ++i) {
        streams[i] = malloc(sizeof(StreamNode));
        if (!streams[i]) {
            logEvent("Failed to allocate memory for stream node");
            continue;
        }

        // Simulate data population
        streams[i]->data.RX_UE_INFORMATION_TAG = rand() % 1000;
        streams[i]->data.RNTI = rand() % 1000;
        streams[i]->data.CRC_INDICATION_REL8_TAG = rand() % 1000;
        streams[i]->data.CRCFLAG = rand() % 2;
        streams[i]->next = NULL;

        pthread_create(&threads[i], NULL, threadFunction, (void*)streams[i]);
    }

    for (int i = 0; i < numStreams; ++i) {
        pthread_join(threads[i], NULL);
    }
}

// Function to process each stream
void* threadFunction(void* arg) {
    StreamNode* head = (StreamNode*)arg;
    processStream(head);

    return NULL;
}

// Process a single data stream
void processStream(StreamNode* head) {
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    // Simulate processing logic
    pthread_mutex_lock(&lock);
    int index = rand() % 10; // Randomly select a metric index for demonstration
    metrics[index].totalProcessed++;
    if (rand() % 10 < 2) { // Simulate an error condition
        metrics[index].errors++;
        logEvent("Error processing stream data");
    }
    clock_gettime(CLOCK_MONOTONIC, &end);
    double latency = (end.tv_sec - start.tv_sec) * 1000.0;
    latency += (end.tv_nsec - start.tv_nsec) / 1000000.0;
    metrics[index].averageLatency = ((metrics[index].averageLatency * (metrics[index].totalProcessed - 1)) + latency) / metrics[index].totalProcessed;

    pthread_mutex_unlock(&lock);
}

// Log events for debugging and analysis
void logEvent(const char* message) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), message);
}

int main() {
    // Example usage with 5 concurrent streams
    streamProcessingModule(5);

    // Output metrics for demonstration
    for (int i = 0; i < 10; ++i) {
        if (metrics[i].totalProcessed > 0) {
            printf("Stream %d - Processed: %d, Errors: %d, Avg Latency: %.2f ms\n",
                   i, metrics[i].totalProcessed, metrics[i].errors, metrics[i].averageLatency);
        }
    }

    return 0;
}
```

