        : max_recent_attacks(max_recent_attacks), cooldown_period(10s) {}

    void select_attack(const std::string& player_id, const GameState& game_state);

private:
    size_t max_recent_attacks;
    std::chrono::seconds cooldown_period;
    std::vector<std::pair<std::chrono::steady_clock::time_point, std::string>> recent_attacks;
    std::mutex attacks_mutex;
    std::unordered_map<std::string, std::chrono::steady_clock::time_point> player_last_attack;

    bool validate_attack(const std::string& attack) {
