    void cleanup_old_attacks() {
        while (true) {
            std::this_thread::sleep_for(std::chrono::seconds(5)); // Cleanup interval
            std::lock_guard<std::mutex> lock(attacks_mutex);
            auto now = std::chrono::steady_clock::now();
            recent_attacks.erase(
                std::remove_if(recent_attacks.begin(), recent_attacks.end(),
                    [now](const auto& attack) {
                        return now - attack.first > cooldown_period;
                    }),
                recent_attacks.end());
        }
    }

    void start_cleanup_thread() {
        std::thread([this]() { cleanup_old_attacks(); }).detach();
    }

    bool is_cooldown_complete(const std::string& player_id) {
        auto last_attack_time = player_last_attack[player_id];
        return (std::chrono::steady_clock::now() - last_attack_time) > cooldown_period;
    }
};

void AttackManager::select_attack(const std::string& player_id, const GameState& game_state) {
    if (!is_cooldown_complete(player_id)) {
        log_attack(player_id, "cooldown");
        return;
    }

    std::string attack_type = determine_strategy(game_state);

    if (!validate_attack(attack_type)) {
        log_attack(player_id, "invalid");
        return;
    }

    // Update recent attacks and player's last attack time
    {
        std::lock_guard<std::mutex> lock(attacks_mutex);
        recent_attacks.emplace_back(std::chrono::steady_clock::now(), attack_type);
        if (recent_attacks.size() > max_recent_attacks) {
            recent_attacks.erase(recent_attacks.begin());
        }
    }

    player_last_attack[player_id] = std::chrono::steady_clock::now();
    log_attack(player_id, attack_type);
}

