# test_nfaapi.py

import ctypes
import logging
from datetime import datetime
from concurrent.futures import ThreadPoolExecutor
import threading

logging.basicConfig(level=logging.DEBUG)
lock = threading.Lock()

def execute_test(label, f, start_time):
    with lock:
        logging.info(f"Starting Test: {label} at {datetime.now()} - {start_time}")

    try:
        f()

        with lock:
            logging.info(f"Completed Test: {label} successfully at {datetime.now()}")

    except Exception as e:
        with lock:
            logging.error(f"Error in Test: {label} at {datetime.now()}: {e}")

def load_and_run_tests():
    nfaapi = ctypes.CDLL('./nfaapi_message_pdu.so')

    populate_nfaapi_message_pdus = nfaapi.populate_nfaapi_message_pdus
    populate_nfaapi_message_pdus.restype = ctypes.POINTER(ctypes.c_void_p)

    def test_populate_nfaapi():
        pdus = populate_nfaapi_message_pdus(10000)
        if not pdus:
            raise RuntimeError("Memory allocation failed")
        # Add additional checks as needed

    tests = [
        ("Test 1: Populate 10,000 PDUs", test_populate_nfaapi, datetime.now())
    ]

    with ThreadPoolExecutor(max_workers=4) as executor:
        futures = [executor.submit(execute_test, label, f, start_time) for label, f, start_time in tests]

        for future in futures:
            future.result()  # Wait for all threads to complete

if __name__ == "__main__":
    load_and_run_tests()
