    CRC_INDICATION_REL8_TAG crc;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct Node* next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int is_valid_RX_UE_INFORMATION_TAG(uint32_t tag) {
    return tag <= MAX_RX_UE_INFORMATION_TAG && tag > 0;
}

uint16_t generate_random_CRCFLAG() {
    return rand() % 2; // Randomly set to 0 or 1
}

Node* create_node(uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;

    new_node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->RNTI = RNTI;
    new_node->pdu.crc.CRCFLAG = generate_random_CRCFLAG();
    new_node->next = NULL;

    return new_node;
}

int add_to_list(Node** head, uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    if (!is_valid_RX_UE_INFORMATION_TAG(RX_UE_INFORMATION_TAG)) {
        return -1; // Invalid tag
    }

    pthread_mutex_lock(&lock);

    Node* current = *head;
    while (current) {
        if (current->RNTI == RNTI && time(NULL) - current->RX_UE_INFORMATION_TAG < TIME_WINDOW) {
            pthread_mutex_unlock(&lock);
            return 0; // Duplicate within time window
        }
        current = current->next;
    }

    Node* new_node = create_node(RX_UE_INFORMATION_TAG, RNTI);
    if (!new_node) {
        pthread_mutex_unlock(&lock);
        return -1; // Memory allocation failed
    }

    new_node->next = *head;
    *head = new_node;

    pthread_mutex_unlock(&lock);
    return 1;
}

void free_list(Node** head) {
    Node* current = *head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

// Test harness
