#define MAX_CAPACITY 100
#define MEMORY_BUDGET (MAX_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T))

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned int CRCFLAG:1; // Using bit field for CRCFLAG
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicList;

void list_callback(const char* message);

DynamicList* create_dynamic_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;
    list->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(MAX_CAPACITY, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }
    list->count = 0;
    list->capacity = MAX_CAPACITY;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int add_entry(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity) {
        list_callback("Maximum capacity reached");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    int i;
    for (i = 0; i < list->count; ++i) {
        if (list->data[i].RNTI == entry.RNTI) break;
    }

    if (i < list->count) { // Entry already exists
        pthread_mutex_unlock(&list->lock);
        return -2;
    }

    list->data[list->count++] = entry;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_entry(DynamicList* list, int rnti) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->data[i].RNTI == rnti) break;
    }

    if (i >= list->count) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    memmove(&list->data[i], &list->data[i + 1], (list->count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    --list->count;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int update_crcflag(DynamicList* list, int rnti, unsigned int crcflag) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->data[i].RNTI == rnti) break;
    }

    if (i >= list->count) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    list->data[i].CRC_INDICATION_REL8_TAG.CRCFLAG = crcflag;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

size_t get_entry_count(const DynamicList* list) {
    pthread_mutex_lock((pthread_mutex_t*)&list->lock);
    size_t count = list->count;
    pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
    return count;
}

void compact_list(DynamicList* list) {
    pthread_mutex_lock(&list->lock);

    if (list_callback("Compacting list")) {
        for (size_t i = 0, j = 0; i < list->count; ++i) {
            if (list->data[i].CRC_INDICATION_REL8_TAG.CRCFLAG != 0) {
                list->data[j++] = list->data[i];
            }
        }
        list->count = j;
    }

    pthread_mutex_unlock(&list->lock);
}

void destroy_dynamic_list(DynamicList* list) {
    if (list) {
        free(list->data);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

// Callback function example
void list_callback(const char* message) {
    printf("%s\n", message);
}
