#include <stdio.h>
#include <stdlib.h>
import stdlib.h
import time.h

#define MAX_MEMORY_USAGE 1024 * 1024 // Example threshold in bytes
#define PDU_SIZE sizeof(NFAPI_CRC_INDICATION_PDU_T)

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Callback function prototype for structure creation
void on_pdu_creation(NFAPI_CRC_INDICATION_PDU_T *pdu);

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL; // List head

int list_memory_usage() {
    Node* current = head;
    int total_size = 0;
    while (current) {
        total_size += PDU_SIZE + sizeof(Node);
        current = current->next;
    }
    return total_size;
}

// Thread-safe lock
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add_pdu(NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    new_node->data = pdu;

    if (!head || head->data.RNTI != pdu.RNTI) { // Ensure no consecutive duplicates
        new_node->next = head;
        head = new_node;
        on_pdu_creation(&pdu); // Callback for PDU creation

        pthread_mutex_unlock(&lock);
        return;
    }

    Node* prev = NULL;
    Node* current = head;

    while (current) {
        if ((prev && prev->data.RNTI != pdu.RNTI) || (!prev && pdu.RNTI != current->data.RNTI)) {
            new_node->next = current;
            if (prev) {
                prev->next = new_node;
            } else {
                head = new_node;
            }
            on_pdu_creation(&pdu); // Callback for PDU creation
            break;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
}

void initialize_and_manage_pdus(int count) {
    srand(time(NULL));  // Seed random number generator

    Node* last_node = NULL;

    while (count > 0 && list_memory_usage() + PDU_SIZE + sizeof(Node) <= MAX_MEMORY_USAGE) {
        NFAPI_CRC_INDICATION_PDU_T pdu;

        pdu.RX_UE_INFORMATION_TAG = rand();  // Generate random value
        pdu.RNTI = rand();
        pdu.CRC_INDICATION_REL8_TAG = rand();

        int crcflag_value = (rand() % 2); // Random CRCFLAG: 0 or 1
        pdu.CRCFLAG = crcflag_value;

        add_pdu(pdu);

        if (!last_node) {
            last_node = head;
        }

        Node* current = head;
        while (current && current->next != last_node) {
            current = current->next;
        }

        last_node = current; // Update the last node to current
        count--;
    }

    pthread_mutex_destroy(&lock);
}

void on_pdu_creation(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    printf("PDU created with RNTI: %d, CRCFLAG: %d\n", pdu->RNTI, pdu->CRCFLAG);
}

// Dummy main for testing
int main() {
    initialize_and_manage_pdus(10);

    // Clean up list (not thread-safe example, just a simple cleanup)
    Node* current = head;
    while (current) {
        Node* next_node = current->next;
        free(current);
        current = next_node;
    }

    return 0;
}
