    list->size = 0;
    list->max_size = max_size;
    list->filename = filename;
}

// Add a new PDU to the list
int add_pdu(CRC_Indication_List *list, unsigned int rx_ue_information_tag, unsigned int rnti) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= list->max_size) {
        fprintf(stderr, "Warning: List is at maximum capacity.\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pdu) {
        perror("Failed to allocate memory for new PDU");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_pdu->rx_ue_information_tag = rx_ue_information_tag;
    new_pdu->rnti = rnti;
    new_pdu->crc_indication_rel8_tag.crc_flag = rand() % 2; // Randomly set CRCFLAG
    time(&new_pdu->timestamp);
    new_pdu->next = list->head;
    list->head = new_pdu;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Clear expired PDUs from the list
void clear_expired_pdus(CRC_Indication_List *list, time_t expiration_threshold_ms) {
    pthread_mutex_lock(&list->lock);

    time_t current_time = time(NULL);
    NFAPI_CRC_INDICATION_PDU_T **tracer = &list->head;

    while (*tracer) {
        if (difftime(current_time, (*tracer)->timestamp) > (expiration_threshold_ms / 1000.0)) {
            NFAPI_CRC_INDICATION_PDU_T *expired_pdu = *tracer;
            *tracer = expired_pdu->next;
            free(expired_pdu);
            list->size--;
        } else {
            tracer = &(*tracer)->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

// Serialize the list to a file
void serialize_list(CRC_Indication_List *list) {
    pthread_mutex_lock(&list->lock);

    FILE *file = fopen(list->filename, "wb");
    if (!file) {
        perror("Failed to open file for serialization");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        fwrite(current, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    fclose(file);
    pthread_mutex_unlock(&list->lock);
}

// Deserialize the list from a file
void deserialize_list(CRC_Indication_List *list) {
    FILE *file = fopen(list->filename, "rb");
    if (!file) {
        perror("Failed to open file for deserialization");
        return;
    }

    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T temp_pdu;
    while (fread(&temp_pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        if (list->size >= list->max_size) break;

        NFAPI_CRC_INDICATION_PDU_T *new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pdu) {
            perror("Failed to allocate memory for new PDU during deserialization");
            continue;
        }

        *new_pdu = temp_pdu;
        new_pdu->next = list->head;
        list->head = new_pdu;
        list->size++;
    }

    fclose(file);
    pthread_mutex_unlock(&list->lock);
}

// Example usage
int main() {
    CRC_Indication_List list;
    init_list(&list, 100, "nfa_list.dat");

    // Add PDUs
    for (int i = 0; i < 120; ++i) {
        add_pdu(&list, i, rand());
    }

    // Periodically clear expired PDUs
    while (1) {
        sleep(5); // Simulate periodic operation
        clear_expired_pdus(&list, 10000);
        serialize_list(&list);
    }

    return 0;
}
