['```javascript
function renderFooterScripts(scripts, forceRender = false, callback) {
    const footerElement = document.getElementById('footer');
    let renderedHTMLCache = footerElement.getAttribute('data-rendered-scripts') || '';

    // Sort scripts by priority (descending), and then by id for consistent ordering
    scripts.sort((a, b) => b.priority - a.priority || a.id.localeCompare(b.id));

    // Create the HTML string to render
    let newRenderedHTML = '<script>';
    scripts.forEach(script => {
        newRenderedHTML += `</script><script type="text/javascript" id="${script.id}"`;

        if (script.async) newRenderedHTML += ' async';
        if (script.defer) newRenderedHTML += ' defer';

        newRenderedHTML += `>\n/* Script Content: ${script.content} */\n</script>`;
    });

    // Check if the rendered HTML has changed or force render is requested
    if (renderedHTMLCache !== newRenderedHTML || forceRender) {
        footerElement.innerHTML = newRenderedHTML;

        // Cache the new rendered string
        footerElement.setAttribute('data-rendered-scripts', newRenderedHTML);
    }

    // Execute callback after rendering
    if (typeof callback === 'function') {
        callback();
    }
}
