        config->metric_collection_interval = json_object_get_int(host_ip_obj);
    }
    if (json_object_object_get_ex(parsed_json, "alert_thresholds", &config->alert_thresholds)) {}

    // Clean up
    json_object_put(parsed_json);

    // Additional setup with injected dependencies
    network_manager.setup_network(config->host_ip, config->port);
}

