// Define constants
#define MAX_LIMIT 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Randomly set value (0 or 1)
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t count;
} PDU_Array;

// Function to initialize the PDU array
PDU_Array* init_pdu_array(size_t initial_capacity) {
    if (initial_capacity > MAX_LIMIT) {
        fprintf(stderr, "Initial capacity exceeds maximum limit.\n");
        return NULL;
    }

    PDU_Array *pdu_array = (PDU_Array*)malloc(sizeof(PDU_Array));
    if (!pdu_array) {
        perror("Failed to allocate memory for PDU array.");
        return NULL;
    }

    pdu_array->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_array->array) {
        perror("Failed to allocate memory for PDU elements.");
        free(pdu_array);
        return NULL;
    }

    pdu_array->capacity = initial_capacity;
    pdu_array->count = 0;

    return pdu_array;
}

// Function to resize the PDU array
int resize_pdu_array(PDU_Array *pdu_array, size_t new_capacity) {
    if (new_capacity > MAX_LIMIT) {
        fprintf(stderr, "New capacity exceeds maximum limit.\n");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(pdu_array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        perror("Failed to resize PDU array.");
        return -1;
    }

    pdu_array->array = new_array;
    pdu_array->capacity = new_capacity;

    // Initialize newly allocated space
    memset(pdu_array->array + pdu_array->count, 0, (pdu_array->capacity - pdu_array->count) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    return 0;
}

// Function to add a PDU to the array
int add_pdu(PDU_Array *pdu_array) {
    if (!pdu_array || pdu_array->count >= pdu_array->capacity) {
        size_t new_capacity = pdu_array->capacity ? pdu_array->capacity * 2 : 1;
        if (new_capacity > MAX_LIMIT) {
            fprintf(stderr, "Cannot add more PDUs: maximum limit reached.\n");
            return -1;
        }

        if (resize_pdu_array(pdu_array, new_capacity) != 0) {
            return -1;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = &pdu_array->array[pdu_array->count];

    // Randomly set CRCFLAG
    srand(time(NULL));
    pdu->CRCFLAG = rand() % 2;

    // Assign other fields with example values
    pdu->RX_UE_INFORMATION_TAG = rand();   // Example value, should be validated/assigned properly in real scenario
    pdu->RNTI = rand();                     // Example value
    pdu->CRC_INDICATION_REL8_TAG = rand();  // Example value

    if (pdu->RX_UE_INFORMATION_TAG == 0 || pdu->RNTI == 0 || pdu->CRC_INDICATION_REL8_TAG == 0) {
        fprintf(stderr, "Invalid PDU fields detected.\n");
        return -1;
    }

    pdu_array->count++;

    return 0;
}

// Function to free the PDU array
void free_pdu_array(PDU_Array *pdu_array) {
    if (pdu_array) {
        if (pdu_array->array) {
            free(pdu_array->array);
        }
        free(pdu_array);
    }
}

// Example usage of the functions
int main() {
    PDU_Array *pdu_array = init_pdu_array(10);
    if (!pdu_array) {
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < 15; ++i) { // Add more PDUs than initial capacity to test resizing
        if (add_pdu(pdu_array) != 0) {
            fprintf(stderr, "Failed to add PDU %zu.\n", i);
            free_pdu_array(pdu_array);
            return EXIT_FAILURE;
        }
    }

    printf("Successfully added %zu PDUs with capacity %zu.\n", pdu_array->count, pdu_array->capacity);

    // Free allocated resources
    free_pdu_array(pdu_array);

    return EXIT_SUCCESS;
}
