#include <string.h>
#include <jansson.h> // JSON parsing library

// Define constants
#define MAX_MEMORY_USAGE 1024 * 1024 // 1 MB
#define CONFIG_FILE_PATH "config.json"

// Define the NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    int rnti;
    char app_name[256];
    int port;
    char database_url[512];
    int cache_duration;
} NFAPI_CRC_INDICATION_PDU_T;

// Logging function type
typedef void (*LogFunction)(const char *message);

// Database setup function type
typedef int (*DatabaseSetupFunction)();

// Configuration processing and API indications generation
int processConfigAndGenerateNfaApiIndications(LogFunction log, DatabaseSetupFunction dbSetup) {
    json_error_t error;
    json_t *root = json_load_file(CONFIG_FILE_PATH, 0, &error);

    if (!root) {
        log("Failed to load configuration file");
        return -1;
