// JavaScript Function: `refreshDialogFields`

async function refreshDialogFields(fieldNames, url) {
    const fetchWithTimeout = (resource, options = {}, timeout = 5000) => 
        new Promise((resolve, reject) => {
            const timer = setTimeout(() => reject(new Error('Request timed out')), timeout);
            fetch(resource, options)
                .then(resolve)
                .catch(reject)
                .finally(() => clearTimeout(timer));
        });

    const batchFetch = async (requests) => {
        try {
            return await Promise.allSettled(requests.map(req => fetchWithTimeout(...req)));
        } catch (error) {
            console.error('Batch fetch error:', error);
        }
    };

    const dialogFields = fieldNames.reduce((acc, fieldName) => {
        const fieldElement = document.querySelector(`[data-field="${fieldName}"]`);
        if (fieldElement) acc.push({ name: fieldName, element: fieldElement });
        return acc;
    }, []);

    if (!dialogFields.length) return;

    const requests = dialogFields.map(({ name }) =>
        [`${url}?field=${encodeURIComponent(name)}`, { method: 'GET' }]
    );

    try {
        const results = await batchFetch(requests);

        results.forEach((result, index) => {
            const { name, element } = dialogFields[index];
            if (result.status === 'fulfilled') {
                result.value.json().then(data => {
                    if (data && data.value !== undefined) {
                        element.value = data.value;
                    }
                }).catch(error => console.error(`Error processing response for ${name}:`, error));
            } else {
                console.warn(`Failed to fetch or timeout for field: ${name}`);
            }
        });
    } catch (error) {
        console.error('Error in refreshDialogFields:', error);
    }
}

// C++ Function: `insertAfterInForwardList`

#include <forward_list>
#include <string>

void insertAfterInForwardList(std::forward_list<std::string>& flist, const std::string& target, const std::string& insertion) {
    auto it = flist.before_begin();
    for (auto curr = flist.begin(); curr != flist.end(); ++curr) {
        if (*curr == target) {
            flist.insert_after(curr, insertion);
            return;
        }
        it = curr;
    }
    // If target not found, append at the end
    flist.insert_after(it, insertion);
}
