    // Simulate fetching a value and returning 0 for success, -1 for failure
    *value = 42.0; // Placeholder value
    return 0;
}

// Function to validate fetched data
int is_valid_data(double value) {
    // Implement specific validation logic here
    return value != 0.0;
}

void handle_error(const char* message) {
    fprintf(stderr, "%s\n", message);
    exit(EXIT_FAILURE);
}

matrix_3d* create_matrix(unsigned int rows, unsigned int cols, unsigned int depths) {
    matrix_3d *mat = (matrix_3d*)malloc(sizeof(matrix_3d));
    if (!mat) handle_error("Failed to allocate memory for matrix structure.");

    mat->rows = rows;
    mat->cols = cols;
    mat->depths = depths;

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    mat->matrix_data = (matrix_element ***)malloc(rows * sizeof(matrix_element**));
    if (!mat->matrix_data) handle_error("Failed to allocate memory for rows.");

    for (unsigned int i = 0; i < rows; ++i) {
        mat->matrix_data[i] = (matrix_element **)malloc(cols * sizeof(matrix_element*));
        if (!mat->matrix_data[i]) handle_error("Failed to allocate memory for columns.");

        for (unsigned int j = 0; j < cols; ++j) {
            mat->matrix_data[i][j] = (matrix_element *)malloc(depths * sizeof(matrix_element));
            if (!mat->matrix_data[i][j]) handle_error("Failed to allocate memory for depths.");

            pthread_mutex_lock(&lock);
            for (unsigned int k = 0; k < depths; ++k) {
                double value;
                if (fetch_initial_value(&value) == -1 || !is_valid_data(value)) {
                    mat->matrix_data[i][j][k].value = 0.0; // Default fallback value
                } else {
                    mat->matrix_data[i][j][k].value = value;
                }
            }
            pthread_mutex_unlock(&lock);
        }
    }

    return mat;
}

void free_matrix(matrix_3d *mat) {
    if (!mat) return;

    for (unsigned int i = 0; i < mat->rows; ++i) {
        for (unsigned int j = 0; j < mat->cols; ++j) {
            free(mat->matrix_data[i][j]);
        }
        free(mat->matrix_data[i]);
    }
    free(mat->matrix_data);
    free(mat);
}

int main() {
    unsigned int rows = 3, cols = 4, depths = 5;

    matrix_3d *mat = create_matrix(rows, cols, depths);

    // Example of accessing a value
    printf("Value at (0, 0, 0): %f\n", mat->matrix_data[0][0][0].value);

    free_matrix(mat);
    return 0;
}
```

