    pthread_mutex_t lock;
} DeviceManager;

// Custom memory allocator functions
static void *custom_alloc(size_t size) {
    return malloc(size);
}

static void custom_free(void *ptr) {
    free(ptr);
}

// Initialize the device manager with a specified capacity
void initialize_device_manager(DeviceManager *manager, size_t initial_capacity) {
    pthread_mutex_init(&manager->lock, NULL);

    manager->devices = (DeviceState *)custom_alloc(initial_capacity * sizeof(DeviceState));
    manager->count = 0;
    manager->capacity = initial_capacity;
    manager->total_power_consumption = 0.0;
    manager->min_power_consumption = DBL_MAX;
    manager->max_power_consumption = -DBL_MAX;

    if (initial_capacity > 0) {
        srand(time(NULL)); // Seed the random number generator
    }
}

// Function to resize the device array while preserving existing data
void resize_device_manager(DeviceManager *manager, size_t new_capacity) {
    pthread_mutex_lock(&manager->lock);

    DeviceState *new_devices = (DeviceState *)custom_alloc(new_capacity * sizeof(DeviceState));
    for (size_t i = 0; i < manager->count; ++i) {
        new_devices[i] = manager->devices[i];
    }

    custom_free(manager->devices);
    manager->devices = new_devices;
    manager->capacity = new_capacity;

    pthread_mutex_unlock(&manager->lock);
}

// Add a device to the manager
void add_device(DeviceManager *manager, double temperature, unsigned long last_uptime, int error_count) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        resize_device_manager(manager, manager->capacity * 2);
    }

    // Calculate random power consumption based on average
    double avg_power_consumption = manager->total_power_consumption / (manager->count + 1);
    double range = rand() % 10 + 1; // Randomly define a small range for variability
    double new_power_consumption = avg_power_consumption + ((rand() % 2000) / 100.0 - range);

    DeviceState new_device = {
        .current_power_consumption = new_power_consumption,
        .temperature = temperature,
        .last_uptime = last_uptime,
        .error_count = error_count
    };

    // Update running totals and track min/max power consumption
    if (manager->count == 0) {
        manager->total_power_consumption = new_power_consumption;
        manager->min_power_consumption = new_power_consumption;
        manager->max_power_consumption = new_power_consumption;
    } else {
        manager->total_power_consumption += new_power_consumption;
        if (new_power_consumption < manager->min_power_consumption) {
            manager->min_power_consumption = new_power_consumption;
        }
        if (new_power_consumption > manager->max_power_consumption) {
            manager->max_power_consumption = new_power_consumption;
        }
    }

    manager->devices[manager->count++] = new_device;

    pthread_mutex_unlock(&manager->lock);
}

// Release all allocated resources
void destroy_device_manager(DeviceManager *manager) {
    custom_free(manager->devices);
    pthread_mutex_destroy(&manager->lock);
}
```

### Notes:
- **Memory Management:** Uses a custom memory allocator for flexibility. Future changes can include more sophisticated allocators.
- **Concurrency:** Utilizes `pthread_mutex_t` to ensure thread safety during concurrent access and modifications.
- **Scalability:** Resizing is implemented using doubling strategy to balance between reallocations and excess capacity.
- **Precision:** Handles power consumption calculations with double precision, minimizing floating-point errors by careful aggregation.
- **Extensibility:** Design allows easy addition of fields or integration with external systems.
- **Robustness:** Ensures all allocated memory is freed properly.']

