#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_KEY_LENGTH 256

typedef struct {
    float value;
    char *key;
} Entry;

typedef struct Node {
    Entry entry;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} Collection;

void trim_string(char **str) {
    if (strlen(*str) > MAX_KEY_LENGTH - 1) {
        (*str)[MAX_KEY_LENGTH - 1] = '\0';
    }
}

Entry* find_entry(Collection *collection, const char *key) {
    pthread_mutex_lock(&collection->lock);

    Node *current = collection->head;
    while (current != NULL) {
        if (strcmp(current->entry.key, key) == 0) {
            Entry *found = &current->entry;
            pthread_mutex_unlock(&collection->lock);
            return found;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&collection->lock);
    return NULL;
}

void insert_entry(Collection *collection, float value, const char *key) {
    char *trimmed_key = strdup(key);
    trim_string(&trimmed_key);

    Entry new_entry;
    new_entry.value = value;
    new_entry.key = trimmed_key;

    Node *new_node = (Node *)malloc(sizeof(Node));
    if (!new_node) return; // Handle memory allocation failure

    new_node->entry = new_entry;
    new_node->next = NULL;

    pthread_mutex_lock(&collection->lock);

    if (collection->head == NULL) {
        collection->head = new_node;
    } else {
        Node *current = collection->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    pthread_mutex_unlock(&collection->lock);
}

void iterate_reverse(Collection *collection, void (*callback)(float value, const char *key)) {
    pthread_mutex_lock(&collection->lock);

    Node **current = &collection->head;
    while (*current != NULL) {
        Node *entry_node = *current;
        current = &entry_node->next;

        callback(entry_node->entry.value, entry_node->entry.key);
    }

    pthread_mutex_unlock(&collection->lock);
}

void free_collection(Collection *collection) {
    pthread_mutex_lock(&collection->lock);

    Node *current = collection->head;
    while (current != NULL) {
        Node *next = current->next;
        free(current->entry.key);
        free(current);
        current = next;
    }
    collection->head = NULL;

    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
}

void initialize_collection(Collection **collection) {
    *collection = (Collection *)malloc(sizeof(Collection));
    if (!*collection) return; // Handle memory allocation failure

    (*collection)->head = NULL;
    pthread_mutex_init(&(*collection)->lock, NULL);
}
