#include <openssl/pkcs5.h>

// Error handling omitted for brevity

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char iv[16];
} CryptoContext;

// Memory allocation and initialization
void* allocate_memory(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    memset(ptr, 0, size);
    return ptr;
}

void free_memory(void *ptr) {
    free(ptr);
}

// Key derivation using PBKDF2
int derive_key(const char *password, const unsigned char *salt, int salt_len,
               unsigned char *key, int key_length, int iterations) {
    return PKCS5_PBKDF2_HMAC_SHA1(password, strlen(password), 
                                  salt, salt_len, iterations, 
                                  key_length, key);
}

// Encrypt data
int encrypt_data(CryptoContext *crypto_ctx, const unsigned char *plaintext,
                 int plaintext_len, unsigned char **ciphertext,
                 size_t *ciphertext_len, int use_aes_256_cbc) {
    EVP_CIPHER *cipher = use_aes_256_cbc ? EVP_aes_256_cbc() : EVP_aes_128_gcm();
    int block_size = EVP_CIPHER_block_size(cipher);

    *ciphertext_len = plaintext_len + block_size;
    *ciphertext = (unsigned char *)allocate_memory(*ciphertext_len);

    if (!EVP_EncryptInit_ex(crypto_ctx->ctx, cipher, NULL, crypto_ctx->iv, NULL)) {
        return -1;
    }

    int len;
    int ciphertext_len_temp = 0;

    if (!EVP_EncryptUpdate(crypto_ctx->ctx, *ciphertext, &len, plaintext, plaintext_len)) {
        return -1;
    }
    ciphertext_len_temp += len;

    if (!EVP_EncryptFinal_ex(crypto_ctx->ctx, (*ciphertext) + len, &len)) {
        return -1;
    }
    ciphertext_len_temp += len;

    *ciphertext_len = ciphertext_len_temp;
    return 0;
}

// Decrypt data
int decrypt_data(CryptoContext *crypto_ctx, const unsigned char *ciphertext,
                 int ciphertext_len, unsigned char **plaintext,
                 size_t *plaintext_len, int use_aes_256_cbc) {
    EVP_CIPHER *cipher = use_aes_256_cbc ? EVP_aes_256_cbc() : EVP_aes_128_gcm();

    *plaintext = (unsigned char *)allocate_memory(ciphertext_len);

    if (!EVP_DecryptInit_ex(crypto_ctx->ctx, cipher, NULL, crypto_ctx->iv, NULL)) {
        return -1;
    }

    int len;
    int plaintext_len_temp = 0;

    if (!EVP_DecryptUpdate(crypto_ctx->ctx, *plaintext, &len, ciphertext, ciphertext_len)) {
        return -1;
    }
    plaintext_len_temp += len;

    if (!EVP_DecryptFinal_ex(crypto_ctx->ctx, (*plaintext) + len, &len)) {
        return -1;
    }
    plaintext_len_temp += len;

    *plaintext_len = plaintext_len_temp;
    return 0;
}

// Initialize cryptographic context
int init_crypto_context(CryptoContext **crypto_ctx, int use_aes_256_cbc) {
    EVP_CIPHER_CTX *ctx = (EVP_CIPHER_CTX *)allocate_memory(sizeof(EVP_CIPHER_CTX));
    if (!EVP_CIPHER_CTX_init(ctx)) {
        free(ctx);
        return -1;
    }

    unsigned char iv[16];
    RAND_bytes(iv, sizeof(iv));

    CryptoContext *context = (CryptoContext *)allocate_memory(sizeof(CryptoContext));
    context->ctx = ctx;
    memcpy(context->iv, iv, sizeof(iv));

    EVP_CIPHER *cipher = use_aes_256_cbc ? EVP_aes_256_cbc() : EVP_aes_128_gcm();

    if (!EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, iv)) {
        free_memory(ctx);
        return -1;
    }

    *crypto_ctx = context;
    return 0;
}

// Cleanup cryptographic context
void cleanup_crypto_context(CryptoContext **crypto_ctx) {
    EVP_CIPHER_CTX_cleanup((*crypto_ctx)->ctx);
    free_memory((*crypto_ctx)->ctx);
    free_memory(*crypto_ctx);
}
