static size_t max_elements = MAX_ELEMENTS;
static size_t system_memory_limit = SYSTEM_MEMORY_LIMIT;
static FILE *log_file = NULL;
static int log_level = 1; // 0: none, 1: errors, 2: warnings, 3: info

void configure_logging(const char* filename, int level) {
    log_file = fopen(filename, "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    log_level = level;
}

void log_message(int level, const char *message) {
    if (level <= log_level && log_file) {
        fprintf(log_file, "%s\n", message);
        fflush(log_file);
    }
}

int parse_config(const char* config_filename) {
    FILE *config_file = fopen(config_filename, "r");
    if (!config_file) {
        perror("Failed to open config file");
        return -1;
    }

    pthread_mutex_lock(&config_lock);

    int max_elems, memory_limit;
    while (fscanf(config_file, "%d %lu", &max_elems, &memory_limit) == 2) {
        if (max_elems > 0 && memory_limit > 0) {
            max_elements = max_elems;
            system_memory_limit = memory_limit;
        }
    }

    pthread_mutex_unlock(&config_lock);
    fclose(config_file);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_nfa_pi_array(size_t num_elements, int *error_code) {
    if (num_elements == 0 || num_elements > max_elements) {
        *error_code = EINVAL;
        log_message(1, "Invalid number of elements requested.");
        return NULL;
    }

    size_t element_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    size_t total_memory_required = num_elements * element_size;

    if (total_memory_required > system_memory_limit) {
        log_message(2, "Memory limit exceeded. Reducing allocation size.");
        size_t adjusted_num_elements = system_memory_limit / element_size;
        total_memory_required = adjusted_num_elements * element_size;
        num_elements = adjusted_num_elements;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(total_memory_required);
    if (!array) {
        *error_code = ENOMEM;
        log_message(1, "Memory allocation failed.");
        return NULL;
    }

    for (size_t i = 0; i < num_elements; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        array[i].RNTI = rand() % 1000;
        array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }

    *error_code = 0;
    log_message(3, "Successfully allocated and populated NFAPI_CRC_INDICATION_PDU_T array.");
    return array;
}

void free_nfa_pi_array(NFAPI_CRC_INDICATION_PDU_T* array) {
    if (array) {
        free(array);
        log_message(3, "Freed NFAPI_CRC_INDICATION_PDU_T array memory.");
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <config_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    if (parse_config(argv[1]) != 0) {
        return EXIT_FAILURE;
    }

    configure_logging("app.log", 3);

    int error_code = 0;
    size_t num_elements = 500; // Example value, could be set dynamically
    NFAPI_CRC_INDICATION_PDU_T* array = allocate_nfa_pi_array(num_elements, &error_code);
    if (array && error_code == 0) {
        // Use the allocated array for processing...

        free_nfa_pi_array(array);
    } else {
        log_message(1, "Failed to allocate NFAPI_CRC_INDICATION_PDU_T array.");
    }

    fclose(log_file);
    return EXIT_SUCCESS;
}
