// C function to process file names
void processFilename(const char *filename) {
    const char *dot = strrchr(filename, '.');
    if (!dot || dot == filename) return;

    printf("Processing: %s\n", filename);

    int numDigits = 0;
    int fileTypeLength = strlen(dot + 1);

    for (const char *p = dot - 1; p >= filename && *p != '.'; --p) {
        if (*p >= '0' && *p <= '9') numDigits++;
    }

    printf("Number of digits: %d, File type length: %d\n", numDigits, fileTypeLength);

    char newFilename[256];
    snprintf(newFilename, sizeof(newFilename), "%s%d%d.%s",
             filename, numDigits, fileTypeLength, dot + 1);

    printf("New file name: %s\n", newFilename);
}

// C function to initialize records
void initRecords(const char *configFile) {
    FILE *file = fopen(configFile, "r");
    if (!file) {
        fprintf(stderr, "Error opening config file.\n");
        return;
    }

    int numRecords;
    fscanf(file, "%d", &numRecords);
    fclose(file);

    const size_t maxMemory = 2 * 1024 * 1024; // 2 MB
    size_t recordSize = sizeof(Record);
    size_t totalSize = numRecords * recordSize;

    if (totalSize > maxMemory) {
        fprintf(stderr, "Configured memory exceeds limit.\n");
        return;
    }

    Record *records = malloc(totalSize);
    if (!records) {
        fprintf(stderr, "Memory allocation failed.\n");
        return;
    }

    // Initialize records with dummy data
    for (int i = 0; i < numRecords; ++i) {
        records[i].offset = rand() % 1000000;
        int key = rand() % 1000;

        // Handle key collisions
        for (int j = 0; j < i; ++j) {
            if (records[j].key == key) {
                key++;
            }
        }

        records[i].key = key;
        records[i].value = static_cast<double>(rand()) / RAND_MAX * 100.0;

        // Simulate fetching from an external source
        printf("Record %d: Offset=%ld, Key=%d, Value=%.2f\n", i + 1,
               records[i].offset, records[i].key, records[i].value);
    }

    free(records);
}

int main() {
    processFilename("example123.js");

    const char *configFile = "config.txt";
    initRecords(configFile);

    return 0;
}
