['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Node {
    char* data;
    int value;
} Node;

typedef struct {
    Node** array;
    size_t size;
    pthread_mutex_t lock;
} NodeArray;

NodeArray* create_node_array() {
    NodeArray* nodeArray = (NodeArray*)malloc(sizeof(NodeArray));
    nodeArray->array = NULL;
    nodeArray->size = 0;
    pthread_mutex_init(&nodeArray->lock, NULL);
    return nodeArray;
}

void destroy_node_array(NodeArray* nodeArray) {
    for (size_t i = 0; i < nodeArray->size; i++) {
        free(nodeArray->array[i]->data);
        free(nodeArray->array[i]);
    }
    free(nodeArray->array);
    pthread_mutex_destroy(&nodeArray->lock);
    free(nodeArray);
}

int insert_node(NodeArray* nodeArray, char* data, int value) {
    pthread_mutex_lock(&nodeArray->lock);

    size_t pos = 0;
    while (pos < nodeArray->size && nodeArray->array[pos]->value < value) {
        pos++;
    }

    Node** new_array = realloc(nodeArray->array, sizeof(Node*) * (nodeArray->size + 1));
    if (!new_array) {
        pthread_mutex_unlock(&nodeArray->lock);
        return -1; // Memory allocation failure
    }
    nodeArray->array = new_array;

    for (size_t i = nodeArray->size; i > pos; i--) {
        nodeArray->array[i] = nodeArray->array[i - 1];
    }

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&nodeArray->lock);
        return -1; // Memory allocation failure
    }
    newNode->data = strdup(data); // Duplicate data for safety
    newNode->value = value;
    nodeArray->array[pos] = newNode;

    nodeArray->size++;
    pthread_mutex_unlock(&nodeArray->lock);

    return 0; // Success
}

void print_node_array(NodeArray* nodeArray) {
    pthread_mutex_lock(&nodeArray->lock);
    for (size_t i = 0; i < nodeArray->size; i++) {
        printf("Value: %d, Data: %s\n", nodeArray->array[i]->value, nodeArray->array[i]->data);
    }
    pthread_mutex_unlock(&nodeArray->lock);
}

int main() {
    NodeArray* nodeArray = create_node_array();
    insert_node(nodeArray, "Data1", 10);
    insert_node(nodeArray, "Data2", 5);
    insert_node(nodeArray, "Data3", 20);

    print_node_array(nodeArray);

    destroy_node_array(nodeArray);

    return 0;
}
```

This code provides a thread-safe implementation of an array of `Node` structures with functions to create, manage, and destroy the array. It uses mutexes for synchronizing access across threads. The insert function maintains order based on the `value` field, handles memory allocation failures gracefully, and ensures no memory leaks by releasing resources properly.']

['Below is an example implementation of a C function that initializes and configures a dynamic array of `LTE_PDCP_PDU_T` structures with the considerations mentioned:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define structure for LTE PDCP PDU
typedef struct {
    uint16_t SN;                   // Sequence Number
    uint8_t SRB_ID;                // Signalling Radio Bearer Identifier
    size_t payload_size;
    unsigned char *payload;        // Optional DL-PDU Payload
} LTE_PDCP_PDU_T;

// Define structure for dynamic array of PDUs
typedef struct {
    LTE_PDCP_PDU_T *pdus;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} PDU_Array;

// Function prototypes
int init_pdu_array(PDU_Array *array, size_t initial_capacity);
int resize_pdu_array(PDU_Array *array, size_t new_capacity);
int add_pdu_to_array(PDU_Array *array, LTE_PDCP_PDU_T pdu);
void free_pdu_array(PDU_Array *array);

// Initialize the PDU array
int init_pdu_array(PDU_Array *array, size_t initial_capacity) {
    if (array == NULL || initial_capacity == 0)
        return -1; // Error: Invalid parameters

    pthread_mutex_init(&array->lock, NULL);
    array->capacity = initial_capacity;
    array->count = 0;
    array->pdus = malloc(sizeof(LTE_PDCP_PDU_T) * array->capacity);

    if (array->pdus == NULL)
        return -1; // Error: Memory allocation failed

    return 0;
}

// Resize the PDU array
int resize_pdu_array(PDU_Array *array, size_t new_capacity) {
    if (new_capacity <= array->capacity)
        return 0;

    LTE_PDCP_PDU_T *temp = realloc(array->pdus, sizeof(LTE_PDCP_PDU_T) * new_capacity);
    if (temp == NULL)
        return -1; // Error: Memory allocation failed

    array->pdus = temp;
    array->capacity = new_capacity;

    return 0;
}

// Add a PDU to the array
int add_pdu_to_array(PDU_Array *array, LTE_PDCP_PDU_T pdu) {
    if (array == NULL)
        return -1; // Error: Invalid parameter

    pthread_mutex_lock(&array->lock);

    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        int resize_result = resize_pdu_array(array, new_capacity);
        if (resize_result != 0) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Error: Resizing failed
        }
    }

    memcpy(&array->pdus[array->count], &pdu, sizeof(LTE_PDCP_PDU_T));
    array->count++;

    if (pdu.payload != NULL && pdu.payload_size > 0) {
        array->pdus[array->count - 1].payload = malloc(pdu.payload_size);
        if (array->pdus[array->count - 1].payload == NULL) {
            array->count--;
            pthread_mutex_unlock(&array->lock);
            return -1; // Error: Memory allocation for payload failed
        }
        memcpy(array->pdus[array->count - 1].payload, pdu.payload, pdu.payload_size);
    }

    pthread_mutex_unlock(&array->lock);

    return 0;
}

// Free the PDU array resources
void free_pdu_array(PDU_Array *array) {
    if (array == NULL)
        return;

    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->pdus[i].payload != NULL)
            free(array->pdus[i].payload);
    }

    free(array->pdus);
    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
}

int main() {
    PDU_Array pdu_array;
    LTE_PDCP_PDU_T pdu = { .SN = 1, .SRB_ID = 2, .payload_size = 10 };
    unsigned char payload[10] = "HelloWorld";

    if (init_pdu_array(&pdu_array, 5) != 0)
        return -1;

    pdu.payload = payload;
    if (add_pdu_to_array(&pdu_array, pdu) != 0)
        return -1;

    free_pdu_array(&pdu_array);

    return 0;
}
```

