typedef struct {
    Packet **packets;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} PacketArray;

// Function declarations
PacketArray* initialize_packet_array(size_t initial_capacity);
bool add_packet(PacketArray *array, Packet *packet, ValidationPluginSystem *plugin_system);
void dispose_old_packets(PacketArray *array);
MemoryPool* create_memory_pool(size_t pool_size);
void* allocate_from_pool(MemoryPool *pool, size_t size);
void free_to_pool(MemoryPool *pool, void *ptr);

// Worker function for background processing
void* packet_processing_worker(void *arg) {
    PacketArray *packet_array = (PacketArray*)arg;
    while (true) {
        pthread_mutex_lock(&packet_array->lock);
        // Simulate packet processing
        dispose_old_packets(packet_array);
        pthread_mutex_unlock(&packet_array->lock);

        // Sleep to simulate non-blocking behavior
        usleep(100000); // 100 ms
    }
    return NULL;
}

// Initialize the dynamic array of packets
PacketArray* initialize_packet_array(size_t initial_capacity) {
    PacketArray *array = malloc(sizeof(PacketArray));
    if (!array) return NULL;

    pthread_mutex_init(&array->lock, NULL);
    array->packets = malloc(initial_capacity * sizeof(Packet *));
    if (!array->packets) {
        free(array);
        return NULL;
    }
    array->capacity = initial_capacity;
    array->count = 0;

    // Start a background thread for processing packets
    pthread_t worker_thread;
    if (pthread_create(&worker_thread, NULL, packet_processing_worker, array)) {
        fprintf(stderr, "Error creating worker thread\n");
        free(array->packets);
        free(array);
        return NULL;
    }
    pthread_detach(worker_thread);

    return array;
}

// Add a packet to the array after validation
bool add_packet(PacketArray *array, Packet *packet, ValidationPluginSystem *plugin_system) {
    if (!packet || !array || !plugin_system) return false;

    // Validate packet using plugin system
    for (size_t i = 0; i < plugin_system->num_rules; ++i) {
        pthread_mutex_lock(&plugin_system->lock);
        if (!plugin_system->rules[i](packet)) {
            pthread_mutex_unlock(&plugin_system->lock);
            return false;
        }
        pthread_mutex_unlock(&plugin_system->lock);
    }

    pthread_mutex_lock(&array->lock);

    // Resize array if necessary
    if (array->count == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        Packet **new_packets = realloc(array->packets, new_capacity * sizeof(Packet *));
        if (!new_packets) {
            pthread_mutex_unlock(&array->lock);
            return false;
        }
        array->packets = new_packets;
        array->capacity = new_capacity;
    }

    // Add packet to the array
    array->packets[array->count++] = packet;

    pthread_mutex_unlock(&array->lock);

    return true;
}

// Dispose of older packets when capacity is exceeded
void dispose_old_packets(PacketArray *array) {
    if (array->count > 0 && array->capacity >= array->max_capacity) {
        // Free the oldest packet and shift remaining packets
        free(array->packets[0]->data);
        memmove(&array->packets[0], &array->packets[1], (array->count - 1) * sizeof(Packet *));
        --array->count;
    }
}

// Create a memory pool for efficient buffer management
MemoryPool* create_memory_pool(size_t pool_size) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pthread_mutex_init(&pool->lock, NULL);
    pool->memory_pool = malloc(pool_size);
    if (!pool->memory_pool) {
        free(pool);
        return NULL;
    }
    pool->pool_size = pool_size;

    return pool;
}

// Allocate memory from the pool
void* allocate_from_pool(MemoryPool *pool, size_t size) {
    if (!pool || size > pool->pool_size) return NULL;

    pthread_mutex_lock(&pool->lock);
    void *ptr = malloc(size); // Simplified allocation logic for demonstration
    pthread_mutex_unlock(&pool->lock);

    return ptr;
}

// Free memory back to the pool
void free_to_pool(MemoryPool *pool, void *ptr) {
    if (!pool || !ptr) return;

    pthread_mutex_lock(&pool->lock);
    free(ptr); // Simplified deallocation logic for demonstration
    pthread_mutex_unlock(&pool->lock);
}

// Example validation rule function
bool sample_validation_rule(Packet *packet) {
    // Implement specific validation logic here
    return true;
}

// Example of plugin system initialization
ValidationPluginSystem* initialize_plugin_system() {
    ValidationPluginSystem *plugin_system = malloc(sizeof(ValidationPluginSystem));
    if (!plugin_system) return NULL;

    pthread_mutex_init(&plugin_system->lock, NULL);
    plugin_system->rules = malloc(1 * sizeof(ValidationRule));
    if (!plugin_system->rules) {
        free(plugin_system);
        return NULL;
    }
    plugin_system->rules[0] = sample_validation_rule;
    plugin_system->num_rules = 1;

    return plugin_system;
}

// Example main function
int main() {
    // Initialize packet array and plugin system
    PacketArray *packet_array = initialize_packet_array(10);
    ValidationPluginSystem *plugin_system = initialize_plugin_system();

    // Create a memory pool for packet data
    MemoryPool *pool = create_memory_pool(1024 * 1024); // 1 MB pool

    // Simulate receiving packets and adding them to the array
    for (int i = 0; i < 20; ++i) {
        Packet *packet = malloc(sizeof(Packet));
        if (!packet) continue;

        packet->data = allocate_from_pool(pool, 128); // Allocate 128 bytes for data
        packet->timestamp = time(NULL);
        packet->packet_size = 128;

        add_packet(packet_array, packet, plugin_system);

        free(packet); // Packet structure is added to the array
    }

    // Cleanup
    free(plugin_system->rules);
    free(plugin_system);
    free(pool->memory_pool);
    free(pool);
    pthread_mutex_destroy(&packet_array->lock);
    free(packet_array->packets);
    free(packet_array);

    return 0;
}
