# app.py
from flask import Flask, request, jsonify
import threading

app = Flask(__name__)
resources = {}
lock = threading.Lock()

@app.route('/update/<int:resource_id>', methods=['POST'])
def update_resource(resource_id):
    data = request.get_json()
    with lock:
        if resource_id in resources:
            resources[resource_id].update(data)
            return jsonify(resources[resource_id])
        else:
            return "Resource not found", 404

@app.route('/delete/<int:resource_id>', methods=['DELETE'])
def delete_resource(resource_id):
    with lock:
        if resource_id in resources:
            del resources[resource_id]
            new_resource = {"id": resource_id, "data": "default"}
            return jsonify(new_resource)
        else:
            return "Resource not found", 404

if __name__ == '__main__':
    app.run(threaded=True)
```

