} LogManager;

LogManager* create_log_manager(size_t initial_capacity) {
    LogManager *manager = (LogManager *)malloc(sizeof(LogManager));
    manager->entries = (LogEntry **)calloc(initial_capacity, sizeof(LogEntry *));
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void add_log_entry(LogManager *manager, const char *message, int timestamp,
                   const char *message_id, float log_level) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->entries[0]) {  // Simplified check; replace with dynamic capacity management
        size_t new_capacity = manager->count * 2;
        LogEntry **new_entries = (LogEntry **)realloc(manager->entries, new_capacity * sizeof(LogEntry *));
        memset(new_entries + manager->count, 0, (new_capacity - manager->count) * sizeof(LogEntry *));
        manager->entries = new_entries;
    }

    LogEntry *entry = (LogEntry *)malloc(sizeof(LogEntry));
    entry->message = strdup(message);
    entry->timestamp = timestamp;
    strncpy(entry->message_id, message_id, sizeof(entry->message_id) - 1);
    entry->log_level = log_level;

