typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define SUCCESS 0
#define MEMORY_ERROR -1

// Mutex for thread safety
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int manage_crc_indication_pdu_array(NFAPI_CRC_INDICATION_PDU_T *buffer, size_t buffer_size, int N) {
    if (N > buffer_size || N <= 0) {
        // If buffer is too small or invalid N, allocate dynamically
        NFAPI_CRC_INDICATION_PDU_T *dynamic_buffer = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!dynamic_buffer) return MEMORY_ERROR;
        buffer = dynamic_buffer;
    }

    pthread_mutex_lock(&mutex);

    // Data structure to track used CRC tags for efficiency
    unsigned int crc_tags[1 << 16] = {0}; // Assuming CRC is a 16-bit number

    // Populate the structures
    for (int i = 0; i < N; ++i) {
        buffer[i].RX_UE_INFORMATION_TAG = i + 1;
        buffer[i].RNTI = i + 1;

        unsigned int crc_tag;
        do {
            crc_tag = rand() & 0xFFFF; // Generate a random CRC
        } while (crc_tags[crc_tag]);   // Ensure uniqueness

        crc_tags[crc_tag] = 1;         // Mark this tag as used
        buffer[i].CRC_INDICATION_REL8_TAG = crc_tag;
    }

    pthread_mutex_unlock(&mutex);

    return SUCCESS;
}

int main() {
    const int N = 1000;
    size_t initial_buffer_size = 500;  // Example smaller than N to trigger dynamic allocation

    NFAPI_CRC_INDICATION_PDU_T *buffer = malloc(initial_buffer_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!buffer) {
        fprintf(stderr, "Memory allocation failed.\n");
        return MEMORY_ERROR;
    }

    int result = manage_crc_indication_pdu_array(buffer, initial_buffer_size, N);
    if (result != SUCCESS) {
        fprintf(stderr, "Error managing CRC indication PDU array.\n");
        free(buffer);
        return result;
    }

    // Use the buffer for some purpose...

    free(buffer);  // Free dynamically allocated memory
    pthread_mutex_destroy(&mutex);

    return 0;
}
```

### Key Points:

1. **Buffer Management**: The function checks if the pre-allocated buffer size is sufficient. If not, it dynamically allocates a new buffer and assigns it to `buffer`.

2. **Concurrency Control**: A mutex is used to ensure thread-safe operations when accessing or modifying shared data.

3. **Data Population**: Unique `RX_UE_INFORMATION_TAG`, `RNTI`, and non-duplicating `CRC_INDICATION_REL8_TAG` values are generated for each element using a simple hashing mechanism (`crc_tags` array).

4. **Error Handling**: The function checks for memory allocation failures and returns appropriate error codes.

5. **Performance Considerations**: Efficient data structures (like the `crc_tags` array) minimize duplicate CRC generation overhead, ensuring good performance even as `N` increases.

6. **Scalability**: The modular design allows easy future expansions or modifications, such as adding more fields to the structure or changing synchronization mechanisms if needed.']

