['```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.SocketChannel;
import java.util.*;
import java.util.concurrent.*;

public class ConnectionPool {
    private final int maxConnectionsPerAddress;
    private final long idleTimeoutMillis;
    private final ScheduledExecutorService scheduler;
    private final ConcurrentMap<String, Deque<SocketChannel>> connectionPools = new ConcurrentHashMap<>();
    private final ExecutorService connectionAcquisitionExecutor = Executors.newCachedThreadPool();
    private final ExternalServiceManager serviceManager;

    public ConnectionPool(int maxConnectionsPerAddress, long idleTimeoutMillis, ExternalServiceManager serviceManager) {
        this.maxConnectionsPerAddress = maxConnectionsPerAddress;
        this.idleTimeoutMillis = idleTimeoutMillis;
        this.serviceManager = serviceManager;
        this.scheduler = Executors.newScheduledThreadPool(1);
    }

    public SocketChannel acquireConnection(String remoteAddress) throws IOException {
        String key = getPoolKey(remoteAddress);

        connectionPools.computeIfAbsent(key, k -> new ConcurrentLinkedDeque<>());
        Deque<SocketChannel> pool = connectionPools.get(key);

        SocketChannel channel = pool.pollFirst();
        if (channel == null || !isConnectionAlive(channel)) {
            channel = createNewConnection(remoteAddress);
        } else {
            updateLastUsedTime(pool, channel);
        }

        return channel;
    }

    private String getPoolKey(String remoteAddress) {
        return remoteAddress; // Customize key generation as needed
    }

    private boolean isConnectionAlive(SocketChannel channel) {
        try {
            return channel.isConnected() && channel.isOpen();
        } catch (IOException e) {
            return false;
        }
    }

    private SocketChannel createNewConnection(String remoteAddress) throws IOException {
        InetSocketAddress address = new InetSocketAddress(remoteAddress, 80); // Customize port
        SocketChannel channel = SocketChannel.open();
        channel.configureBlocking(false);
        if (!channel.connect(address)) {
            channel.finishConnect(); // Non-blocking connect
        }
        return channel;
    }

    private void updateLastUsedTime(Deque<SocketChannel> pool, SocketChannel channel) {
        pool.remove(channel);  // Remove and re-add to update order
        pool.offerFirst(channel);
    }

    public void releaseConnection(String remoteAddress, SocketChannel channel) {
        String key = getPoolKey(remoteAddress);
        Deque<SocketChannel> pool = connectionPools.get(key);

        if (pool != null && !isConnectionAlive(channel)) {
            tryCloseConnection(channel);
        } else if (!pool.isFull() || pool.size() < maxConnectionsPerAddress) {
            pool.offerLast(channel);
        }
    }

    private void tryCloseConnection(SocketChannel channel) {
        try {
            if (channel.isOpen()) {
                channel.close();
            }
        } catch (IOException e) {
            // Log error
        }
    }

    public void startIdleTimeoutTask() {
        scheduler.scheduleAtFixedRate(this::closeIdleConnections, idleTimeoutMillis, idleTimeoutMillis, TimeUnit.MILLISECONDS);
    }

    private void closeIdleConnections() {
        long now = System.currentTimeMillis();
        connectionPools.forEach((key, pool) -> {
            Iterator<SocketChannel> iterator = pool.iterator();
            while (iterator.hasNext()) {
                SocketChannel channel = iterator.next();
                if (!isConnectionAlive(channel) || (now - getLastUsedTime(pool, channel)) > idleTimeoutMillis) {
                    tryCloseConnection(channel);
                    iterator.remove();
                }
            }
        });
    }

    private long getLastUsedTime(Deque<SocketChannel> pool, SocketChannel channel) {
        // Maintain last used time map or store as metadata if possible
        return 0L; 
    }

    public void handleScalingEvent() {
        try {
            List<String> addresses = serviceManager.getCurrentAddresses();
            for (String address : addresses) {
                int currentSize = connectionPools.getOrDefault(getPoolKey(address), new ConcurrentLinkedDeque<>()).size();
                if (currentSize < maxConnectionsPerAddress) {
                    createAdditionalConnectionsIfNeeded(address, maxConnectionsPerAddress - currentSize);
                }
            }
        } catch (Exception e) {
            // Log error and handle integration issues
        }
    }

    private void createAdditionalConnectionsIfNeeded(String address, int count) throws IOException {
        for (int i = 0; i < count; i++) {
            SocketChannel channel = acquireConnection(address);
            if (channel != null && isConnectionAlive(channel)) {
                releaseConnection(address, channel); // Add to pool
            }
        }
    }

    public void shutdown() {
        scheduler.shutdown();
        connectionAcquisitionExecutor.shutdown();

        connectionPools.values().forEach(pool -> {
            while (!pool.isEmpty()) {
                SocketChannel channel = pool.pollFirst();
                if (channel != null) {
                    tryCloseConnection(channel);
                }
            }
        });
    }

    // Placeholder for the external service manager
    interface ExternalServiceManager {
        List<String> getCurrentAddresses() throws IOException;
    }

    public static void main(String[] args) {
        ConnectionPool pool = new ConnectionPool(10, 60000, addresses -> Arrays.asList("192.168.1.1", "192.168.1.2"));
        pool.startIdleTimeoutTask();

        try {
            SocketChannel channel = pool.acquireConnection("192.168.1.1");
            // Use the connection
            pool.releaseConnection("192.168.1.1", channel);
        } catch (IOException e) {
            // Handle exceptions
        }

        pool.handleScalingEvent();  // Call periodically or based on external triggers

        Runtime.getRuntime().addShutdownHook(new Thread(pool::shutdown));
    }
}
