    // Simulate reading and updating the theme cache
    printf("Updating theme cache from path: %s\n", theme_path);
    pthread_mutex_unlock(&cache_data->lock);
}

// Function to handle memory cleanup
void free_cache(struct CacheData *cache_data) {
    if (cache_data) {
        pthread_mutex_lock(&cache_data->lock);
        free(cache_data->offsets);
        free(cache_data->keys);
        free(cache_data->records);
        free(cache_data->checksums);
        pthread_mutex_unlock(&cache_data->lock);
        pthread_mutex_destroy(&cache_data->lock);

        free(cache_data);
    }
}

// Example usage
int main() {
    struct CacheData *cache_data = init_arrays(10, 5);
    if (cache_data) {
        update_theme_cache(cache_data, "/path/to/theme");
        free_cache(cache_data);
    } else {
        printf("Failed to initialize cache data.\n");
    }
    return 0;
}

// MurmurHash3 implementation
uint32_t murmurhash3_32(const void *key, int len, uint32_t seed) {
    const uint8_t *data = (const uint8_t *)key;
    uint32_t h1 = seed;
    const uint32_t c1 = 0xcc9e2d51;
    const uint32_t c2 = 0x1b873593;

    int i = 0;
    while (len >= 4) {
        uint32_t k1 = *(uint32_t *)(data + i);
        k1 *= c1;
        k1 = (k1 << 15) | (k1 >> 17);
        k1 *= c2;

        h1 ^= k1;
        h1 = (h1 << 13) | (h1 >> 19);
        h1 = h1 * 5 + 0xe6546b64;

        i += 4;
        len -= 4;
    }

    switch (len) {
        case 3:
            h1 ^= data[i + 2] << 16;
        case 2:
            h1 ^= data[i + 1] << 8;
        case 1:
            h1 ^= data[i];
            h1 *= c1;
            h1 = (h1 << 15) | (h1 >> 17);
            h1 *= c2;
            break;
    }

    h1 ^= len;
    h1 ^= h1 >> 16;
    h1 *= 0x85ebca6b;
    h1 ^= h1 >> 13;
    h1 *= 0xc2b2ae35;
    h1 ^= h1 >> 16;

    return h1;
}
```

