['Below is a C code block implementing the specified requirements. The code includes dynamic memory management for arrays of offsets and keys, as well as initialization and management of a linked list of records with thread safety using mutexes.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    int value;
    int keyIndex;
    struct Record* next;
} Record;

typedef struct {
    long* offsets;
    size_t offsetCount;
    pthread_mutex_t offsetsMutex;

    int* keys;
    size_t keyCount;
    pthread_mutex_t keysMutex;

    Record* recordsHead;
    pthread_mutex_t recordsMutex;

    long totalSum;
    double maxAverage;
    int maxValue;
    pthread_mutex_t summaryMutex;
} DataManager;

#define INITIAL_OFFSET_COUNT 10
#define INITIAL_KEY_COUNT 10

void initializeDataManager(DataManager* manager) {
    pthread_mutex_init(&manager->offsetsMutex, NULL);
    pthread_mutex_init(&manager->keysMutex, NULL);
    pthread_mutex_init(&manager->recordsMutex, NULL);
    pthread_mutex_init(&manager->summaryMutex, NULL);

    manager->offsets = malloc(INITIAL_OFFSET_COUNT * sizeof(long));
    manager->offsetCount = INITIAL_OFFSET_COUNT;

    manager->keys = malloc(INITIAL_KEY_COUNT * sizeof(int));
    manager->keyCount = INITIAL_KEY_COUNT;

    manager->recordsHead = NULL;
    pthread_mutex_lock(&manager->summaryMutex);
    manager->totalSum = 0;
    manager->maxAverage = 0.0;
    manager->maxValue = INT_MIN;
    pthread_mutex_unlock(&manager->summaryMutex);
}

void randomizeRangeAndUpdate(int* currentValue, int rangeStart, int rangeEnd, long totalSum) {
    int rangeSize = (rangeEnd - rangeStart + 1);
    *currentValue = rangeStart + rand() % rangeSize;
    if (*currentValue > rangeEnd / 2)
        *currentValue -= rangeEnd - rangeStart; // Adjust to lower half
}

void addOrUpdateRecord(DataManager* manager, long offset, int keyIndex) {
    pthread_mutex_lock(&manager->recordsMutex);
    Record* newRecord = malloc(sizeof(Record));
    newRecord->keyIndex = keyIndex;

    pthread_mutex_lock(&manager->summaryMutex);
    randomizeRangeAndUpdate(&(newRecord->value), 0, 100, manager->totalSum);
    manager->totalSum += newRecord->value;

    if (manager->recordsHead == NULL) {
        manager->recordsHead = newRecord;
        newRecord->next = NULL;
    } else {
        Record* current = manager->recordsHead;
        while (current->next != NULL)
            current = current->next;
        current->next = newRecord;
        newRecord->next = NULL;
    }

    pthread_mutex_unlock(&manager->summaryMutex);

    // Update summary stats
    int maxV = INT_MIN;
    long sum = 0;
    Record* cur = manager->recordsHead;
    size_t count = 0;

    while (cur != NULL) {
        sum += cur->value;
        if (cur->value > maxV)
            maxV = cur->value;
        cur = cur->next;
        ++count;
    }

    double avg = count ? (double)sum / count : 0.0;

    pthread_mutex_lock(&manager->summaryMutex);
    manager->maxValue = max(manager->maxValue, maxV);
    if (avg > manager->maxAverage)
        manager->maxAverage = avg;
    pthread_mutex_unlock(&manager->summaryMutex);

    pthread_mutex_unlock(&manager->recordsMutex);
}

double queryCurrentAverage(DataManager* manager) {
    double average = 0.0;
    pthread_mutex_lock(&manager->summaryMutex);
    long sum = manager->totalSum;
    size_t count = 0;

    Record* cur = manager->recordsHead;
    while (cur != NULL) {
        ++count;
        cur = cur->next;
    }

    if (count > 0)
        average = (double)sum / count;

    pthread_mutex_unlock(&manager->summaryMutex);
    return average;
}

int queryMaxValueSeenSoFar(DataManager* manager) {
    int maxValue = INT_MIN;
    pthread_mutex_lock(&manager->summaryMutex);
    maxValue = manager->maxValue;
    pthread_mutex_unlock(&manager->summaryMutex);
    return maxValue;
}

void cleanupDataManager(DataManager* manager) {
    pthread_mutex_destroy(&manager->offsetsMutex);
    pthread_mutex_destroy(&manager->keysMutex);
    pthread_mutex_destroy(&manager->recordsMutex);
    pthread_mutex_destroy(&manager->summaryMutex);

    free(manager->offsets);
    free(manager->keys);

    Record *current, *next;
    for (current = manager->recordsHead; current != NULL;) {
        next = current->next;
        free(current);
        current = next;
    }
}

int main() {
    srand(time(NULL));

    DataManager manager;
    initializeDataManager(&manager);

    // Example of adding records
    addOrUpdateRecord(&manager, 0, 1); // offset is ignored in this example
    addOrUpdateRecord(&manager, 1, 2);

    printf("Current Average: %f\n", queryCurrentAverage(&manager));
    printf("Max Value Seen: %d\n", queryMaxValueSeenSoFar(&manager));

    cleanupDataManager(&manager);

    return 0;
}
```

This implementation focuses on the core requirements of managing memory dynamically and ensuring thread safety with mutexes, while providing basic functionality for querying average values and maximum values. It uses dynamic arrays for offsets and keys, linked lists for records, and employs random value generation adjusted by previous sums to meet specific constraints. The code is structured to allow easy integration into a larger application that may update keys from an external source and handle concurrent operations efficiently.']

