    long timestamp;
    double temperature;
    Status status;
} sensorData;

void log(const char *message) {
    printf("%s\n", message);
}

double sample_gaussian(double mean, double stddev) {
    static unsigned int seed = 0; // Static variable to keep state between calls
    if (seed == 0)
        srand((unsigned int)time(NULL));

    double u1 = rand() / (RAND_MAX + 1.0);
    double u2 = rand() / (RAND_MAX + 1.0);

    double z0 = sqrt(-2.0 * log(u1)) * cos(2 * M_PI * u2);
    return mean + z0 * stddev;
}

sensorData* initializeSensorData(int numSensors, double meanTemp, double tempStdDev) {
    if (numSensors <= 0) return NULL;

    long *timestamps = malloc(numSensors * sizeof(long));
    double *temperatures = malloc(numSensors * sizeof(double));
    Status *statuses = malloc(numSensors * sizeof(Status));

    sensorData *dataArray = malloc(numSensors * sizeof(sensorData));
    if (!timestamps || !temperatures || !statuses || !dataArray) {
        log("Memory allocation failed");
        free(timestamps);
        free(temperatures);
        free(statuses);
        free(dataArray);
        return NULL;
    }

    for (int i = 0; i < numSensors; ++i) {
        timestamps[i] = time(NULL); // Example: current timestamp
        temperatures[i] = sample_gaussian(meanTemp, tempStdDev);
        statuses[i] = (rand() % 2 == 0) ? OK : ERROR;

        dataArray[i].timestamp = timestamps[i];
        dataArray[i].temperature = temperatures[i];
        dataArray[i].status = statuses[i];

        log("Initialized sensor data entry");
    }

    free(timestamps); // No longer needed after initialization
    free(temperatures);
    free(statuses);

    return dataArray;
}

void cleanupSensorData(sensorData *dataArray, int numSensors) {
    if (dataArray) {
        free(dataArray);
        log("Freed sensor data array");
