typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int transaction_id;
    unsigned long timestamp; // for age calculation
    int weight_sum;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to simulate setting CRCFLAG with predefined distribution
void set_crc_flag(CRC_INDICATION_REL8_TAG* tag) {
    const int probability = 75; // Example: 75% chance for flag true (1)
    int random_value = rand() % 100;
    if (random_value < probability) {
        tag->CRCFLAG = 1;
    } else {
        tag->CRCFLAG = 0;
    }
}

// Function to initialize the dynamic list
NFAPI_CRC_INDICATION_PDU_T* initialize_list(int num_elements, int current_time) {
    NFAPI_CRC_INDICATION_PDU_T* list = malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        return NULL;
    }

    for (int i = 0; i < num_elements; ++i) {
        list[i].transaction_id = i;
        list[i].timestamp = current_time + rand() % 10; // Random age between 0 to 9 seconds
        list[i].weight_sum = rand() % 100; // Example weight sum

        CRC_INDICATION_REL8_TAG* crc_tag = &(list[i].crc_tag);
        crc_tag->RX_UE_INFORMATION_TAG = rand();
        crc_tag->RNTI = rand();

        set_crc_flag(crc_tag); // Randomly set the CRCFLAG
    }

    return list;
}

// Function to filter transactions based on criteria and update metrics
void process_transactions(NFAPI_CRC_INDICATION_PDU_T* list, int num_elements, 
                          unsigned long current_time, int max_recent_trans, 
                          double* avg_processing_time, double* transaction_throughput) {
    unsigned long start_time = clock();

    int valid_count = 0;
    int recent_transactions = 0;
    NFAPI_CRC_INDICATION_PDU_T max_weight_transaction = {0};

    for (int i = 0; i < num_elements; ++i) {
        // Filter based on age of transaction
        if ((current_time - list[i].timestamp) > 5) continue;

        // Count number of transactions within last 3 seconds
        if ((current_time - list[i].timestamp) <= 3000) {
            recent_transactions++;
        }

        // Process weight sum and check for maximum
        if (list[i].weight_sum > max_weight_transaction.weight_sum) {
            max_weight_transaction = list[i];
        }

        valid_count++;
    }

    *avg_processing_time = ((double)(clock() - start_time)) / CLOCKS_PER_SEC / num_elements;
    *transaction_throughput = ((double)valid_count) / (((double)(current_time % 10000)) / 1000.0); // Example throughput calculation

    printf("Max Weighted Sum: %d, Transaction ID: %d\n", max_weight_transaction.weight_sum, max_weight_transaction.transaction_id);
}

// Function to free the dynamically allocated list
void cleanup_list(NFAPI_CRC_INDICATION_PDU_T* list) {
    free(list);
}

int main() {
    srand(time(NULL));

    int num_elements = 1000; // Example number of elements
    unsigned long current_time = time(NULL);

    NFAPI_CRC_INDICATION_PDU_T* transaction_list = initialize_list(num_elements, current_time);
    if (!transaction_list) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    double avg_processing_time = 0.0;
    double transaction_throughput = 0.0;

