#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define INITIAL_SIZE 10
#define MAX_RESOURCES 1000

typedef struct {
    int type;
    size_t size;
} Resource;

typedef struct {
    time_t timestamp;
    int status_flag;
    Resource* resource;
    double value;
} DataObject;

typedef struct {
    DataObject* objects;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    double total_value;
    size_t total_resource_size;
} DataManager;

void init_data_manager(DataManager* manager) {
    manager->objects = (DataObject*)malloc(INITIAL_SIZE * sizeof(DataObject));
    manager->count = 0;
    manager->capacity = INITIAL_SIZE;
    pthread_mutex_init(&manager->lock, NULL);
    manager->total_value = 0.0;
    manager->total_resource_size = 0;
}

void resize_data_manager(DataManager* manager) {
    size_t new_capacity = manager->capacity * 2;
    DataObject* new_objects = (DataObject*)realloc(manager->objects, new_capacity * sizeof(DataObject));
    if (new_objects) {
        manager->objects = new_objects;
        manager->capacity = new_capacity;
    }
}

void add_data_object(DataManager* manager, Resource resource, double value) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        resize_data_manager(manager);
    }

    DataObject* obj = &manager->objects[manager->count++];
    obj->timestamp = time(NULL);
    obj->status_flag = 1; // Default status
    obj->resource = malloc(sizeof(Resource));
    *obj->resource = resource;
    manager->total_resource_size += resource.size;

    if (manager->count == 1) {
        obj->value = value;
    } else {
        double previous_avg = manager->total_value / (manager->count - 1);
        obj->value = (previous_avg * (manager->count - 1) + value) / manager->count;
    }
    manager->total_value += obj->value;

    pthread_mutex_unlock(&manager->lock);
}

void remove_data_object(DataManager* manager, size_t index) {
    if (index >= manager->count) return;

    pthread_mutex_lock(&manager->lock);

    Resource* resource = manager->objects[index].resource;
    manager->total_resource_size -= resource->size;
    free(resource);

    double old_value = manager->objects[index].value;
    size_t remaining_count = manager->count - 1;

    if (remaining_count > 0) {
        manager->total_value -= old_value;
        double new_avg = manager->total_value / remaining_count;
        for (size_t i = index; i < remaining_count; ++i) {
            manager->objects[i] = manager->objects[i + 1];
            if (i != index) { // Update average for non-removed objects
                manager->objects[i].value = new_avg;
            }
        }
    }

    manager->count--;
    pthread_mutex_unlock(&manager->lock);
}

void report_summary(DataManager* manager) {
    pthread_mutex_lock(&manager->lock);

    printf("Total Records: %zu\n", manager->count);
    printf("Average Value: %.2f\n", manager->count ? (manager->total_value / manager->count) : 0.0);
    printf("Total Resource Size: %zu bytes\n", manager->total_resource_size);

    pthread_mutex_unlock(&manager->lock);
}

void cleanup_data_manager(DataManager* manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->objects[i].resource);
    }
    free(manager->objects);
    pthread_mutex_destroy(&manager->lock);
}

int main() {
    DataManager manager;
    init_data_manager(&manager);

    Resource resource1 = { .type = 1, .size = 100 };
    add_data_object(&manager, resource1, 10.0);

    Resource resource2 = { .type = 2, .size = 200 };
    add_data_object(&manager, resource2, 20.0);

    report_summary(&manager);

    remove_data_object(&manager, 0);
    report_summary(&manager);

    cleanup_data_manager(&manager);
    return 0;
}
```

This code defines a `DataManager` that manages a collection of `DataObject`s, each containing a timestamp, status flag, resource reference, and value. It supports dynamic resizing, concurrent access with thread safety, and efficient memory management. The manager tracks total resource size and provides summary reporting.']

