#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <arpa/inet.h>
#include <resolv.h>
#include <time.h>
#include <errno.h>

typedef struct {
    int value;
} record_t;

#define MAX_LOG_LEVEL 3 // 0: Error, 1: Info, 2: Debug
#define LOG_FILE "service.log"
#define DEFAULT_IP "127.0.0.1"

pthread_mutex_t rand_lock = PTHREAD_MUTEX_INITIALIZER;

// Thread-safe random number generator
int thread_safe_rand(int min, int max) {
    pthread_mutex_lock(&rand_lock);
    srand(time(NULL) ^ (pthread_self() << 16));
    int result = min + rand() % ((max - min) + 1);
    pthread_mutex_unlock(&rand_lock);
    return result;
}

// Logging function
void log_message(int level, const char *message) {
    if (level > MAX_LOG_LEVEL) return;

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline

    fprintf(log_file, "[%s] [%d] %s\n", time_str, level, message);

    fclose(log_file);
}

// DNS resolution function
int resolve_dns(const char *hostname, struct in_addr *ip) {
    struct hostent *host;
    pthread_t dns_thread;

    int (*dns_resolv)(const char *, int, struct in_addr *) = (int (*)(const char *, int, struct in_addr *))res_ninit(hostname, AF_INET);
    if (!dns_resolv) return -1;

    void *arg = malloc(sizeof(struct in_addr));
    if (!arg) {
        log_message(0, "Memory allocation failed for DNS resolution");
        return -1;
    }

    memcpy(arg, ip, sizeof(struct in_addr));

    int dns_thread_func(void *arg) {
        struct hostent *host = gethostbyname(hostname);
        if (host == NULL) {
            free(arg);
            log_message(0, "DNS resolution failed");
            return -1;
        }
        struct in_addr resolved_ip = *(struct in_addr *)host->h_addr_list[0];
        memcpy(ip, &resolved_ip, sizeof(struct in_addr));
        free(arg);
        return 0;
    }

    pthread_create(&dns_thread, NULL, (void *(*)(void *))dns_thread_func, arg);
    pthread_detach(dns_thread);

    sleep(1); // Wait for async resolution
    host = gethostbyname(hostname);
    if (host == NULL) {
        struct in_addr default_ip;
        inet_pton(AF_INET, DEFAULT_IP, &default_ip);
        memcpy(ip, &default_ip, sizeof(struct in_addr));
        log_message(1, "Using default IP due to DNS resolution failure");
    }

    return 0;
}

// Main function
int manage_network_service(int offset_count, int key_count, int record_count) {
    if (offset_count <= 0 || key_count <= 0 || record_count <= 0) {
        log_message(0, "Invalid input parameters");
        return -1;
    }

    long *offsets = malloc(offset_count * sizeof(long));
    int *keys = malloc(key_count * sizeof(int));
    if (!offsets || !keys) {
        log_message(0, "Memory allocation failed for offsets or keys");
        free(offsets);
        free(keys);
        return -1;
    }

    record_t *records = malloc(record_count * sizeof(record_t));
    if (!records) {
        log_message(0, "Memory allocation failed for records");
        free(offsets);
        free(keys);
        return -1;
    }

    struct in_addr ip;
    memset(&ip, 0, sizeof(struct in_addr));

    resolve_dns("example.com", &ip);

    for (int i = 0; i < record_count; ++i) {
        records[i].value = thread_safe_rand(1, 100);
    }

    log_message(2, "Network service managed successfully");

    free(offsets);
    free(keys);
    free(records);

    return 0;
}

