        int featureSize;
        size_t maxLeafNodes;
        size_t capacityPerNode;
    };

    DynamicOctree(Config config)
        : featureSize(config.featureSize),
          maxLeafNodes(config.maxLeafNodes),
          capacityPerNode(config.capacityPerNode) {}

    void addNode(const std::vector<float>& position, const LeafData& data);
    bool removeNode(const std::vector<float>& position);
