    int featureSize;
    size_t maxLeafNodes;
    size_t capacityPerNode;

    std::shared_mutex treeMutex; // For read-write lock management
    std::unique_ptr<OctreeNode> root;

    void splitNode(OctreeNode* node);
    bool mergeNode(OctreeNode* node);

    OctreeNode* findNode(const std::vector<float>& position, OctreeNode* currentNode) const;
};

void DynamicOctree::addNode(const std::vector<float>& position, const LeafData& data) {
    std::unique_lock lock(treeMutex); // Write lock
    root = std::make_unique<OctreeNode>(); // Initialize if null

    auto* node = findNode(position, root.get());
    if (node->isLeaf && node->data.size() < capacityPerNode) {
        node->data.push_back(data);
    } else {
        splitNode(node);
        addNode(position, data); // Retry after splitting
    }
}

bool DynamicOctree::removeNode(const std::vector<float>& position) {
    std::unique_lock lock(treeMutex);
    auto* node = findNode(position, root.get());
    if (node && !node->isLeaf) return false;

    if (node && node->data.size() > 0) {
        for (auto it = node->data.begin(); it != node->data.end(); ++it) {
            // Assume LeafData or a comparable type to identify correct element
            if (*it == /* condition to match data */) {
                node->data.erase(it);
                break;
            }
        }
        if (node->data.empty()) mergeNode(node);
        return true;
    }

    return false;
}

void DynamicOctree::updateNode(const std::vector<float>& oldPosition,
                               const std::vector<float>& newPosition, 
                               const LeafData& newData) {
    removeNode(oldPosition);
    addNode(newPosition, newData);
}

void DynamicOctree::iterateNodes(void (*callback)(const OctreeNode* node)) {
    std::shared_lock lock(treeMutex); // Read lock
    std::function<void(const OctreeNode*)> recurse = [&](const OctreeNode* node) {
        if (node->isLeaf) callback(node);
        else for (const auto& child : node->children)
            recurse(child.get());
    };

    recurse(root.get());
}

