// Create a new item with error handling for memory allocation
Item* create_item(const char* name, int value, double weight) {
    if (name == NULL || strlen(name) >= MAX_NAME_LENGTH) {
        fprintf(stderr, "Error: Invalid name provided.\n");
        return NULL;
    }

    Item* item = (Item*)malloc(sizeof(Item));
    if (!item) {
        perror("Failed to allocate memory for Item struct.");
        return NULL;
    }

    item->name = (char*)malloc(MAX_NAME_LENGTH);
    if (!item->name) {
        perror("Failed to allocate memory for item name.");
        free(item);
        return NULL;
    }

    strncpy(item->name, name, MAX_NAME_LENGTH - 1);
    item->value = value;
    item->weight = weight;

    // Calculate a checksum (simple example: sum of ASCII values)
    unsigned int checksum = 0;
    for (size_t i = 0; i < strlen(name); ++i) {
        checksum += name[i];
    }
    checksum += value + (unsigned int)(weight * 1000);

    printf("Item created with checksum: %u\n", checksum);

    return item;
}

// Free all items and their associated memory
void free_items(Item** items, size_t count) {
    if (!items || !*items) return;

    for (size_t i = 0; i < count; ++i) {
        if ((*items)[i] != NULL) {
            free((*items)[i]->name);
            free((*items)[i]);
        }
    }

    free(*items);
    *items = NULL;
}

// Parse a TIFF image and populate items
int parse_tiff_image(const char* filename, Item*** items) {
    if (!filename || !items) return -1;

    FILE* tif_file = fopen(filename, "rb");
    if (!tif_file) {
        perror("Error opening TIFF file.");
        return -1;
    }

    TIFF* tif = TIFFOpen(tif_file, "r");
    if (!tif) {
        fprintf(stderr, "Error: Failed to open TIFF file.\n");
        fclose(tif_file);
        return -1;
    }

    int width, height;
    uint16 sampmodel;

    // Read image dimensions and sample model
    if (TIFFGetField(tif, TIFFTAG_IMAGEWIDTH, &width) &&
        TIFFGetField(tif, TIFFTAG_IMAGELENGTH, &height) &&
        TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &sampmodel)) {

        size_t num_samples = width * height;
        uint16 samples_per_pixel;

        // Allocate space for items
        *items = (Item**)malloc(num_samples * sizeof(Item*));
        if (!(*items)) {
            fprintf(stderr, "Memory allocation error: Unable to allocate memory for items.\n");
            TIFFClose(tif);
            fclose(tif_file);
            return -1;
        }

        // Parse each sample in the image
        for (int row = 0; row < height; ++row) {
            for (int col = 0; col < width; ++col) {
                if (TIFFReadRGBASample(tif, &samples_per_pixel, col, row, NULL)) {
                    // Create and assign items with dummy data (to be replaced by actual values)
                    (*items)[row * width + col] = create_item("Sample", samples_per_pixel, 0.5);
                }
            }
        }

    } else {
        fprintf(stderr, "Error: Unable to read TIFF metadata.\n");
        TIFFClose(tif);
        fclose(tif_file);
        return -1;
    }

    TIFFClose(tif);
    fclose(tif_file);

    // Verify integrity of parsed items (simple checksum verification)
    for (size_t i = 0; i < num_samples; ++i) {
        if ((*items)[i] != NULL) {
            unsigned int expected_checksum = 0;
            for (size_t j = 0; j < strlen((*items)[i]->name); ++j) {
                expected_checksum += (*items)[i]->name[j];
            }
            expected_checksum += (*items)[i]->value + (unsigned int)((*items)[i]->weight * 1000);

            if (expected_checksum != checksum) {  // 'checksum' should be defined locally or globally
                fprintf(stderr, "Error: Checksum mismatch for item %zu.\n", i);
                free_items(*items, num_samples);
                return -1;
            }
        }
    }

    return 0; // Success
}
