    new_node->crc_tag = crc_tag ? malloc(sizeof(CRC_INDICATION_REL8_TAG)) : NULL;
    memcpy(new_node->crc_tag, crc_tag, sizeof(CRC_INDICATION_REL8_TAG));
    new_node->next = NULL;

    *current = new_node;

    pthread_mutex_unlock(&list->lock);
