['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>

#define INITIAL_POOL_SIZE 10
#define MAX_CONNECTIONS 100

typedef struct {
    char ip_address[16];
    uint16_t port;
    bool active;
    size_t packets_sent;
    size_t packets_received;
    double average_latency; // in milliseconds
    time_t last_active_time;
} Connection;

typedef struct {
    Connection *pool;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} ConnectionPool;

ConnectionPool* create_connection_pool(size_t initial_size) {
    ConnectionPool *cp = (ConnectionPool *)malloc(sizeof(ConnectionPool));
    cp->size = 0;
    cp->capacity = initial_size > MAX_CONNECTIONS ? MAX_CONNECTIONS : initial_size;
    cp->pool = (Connection *)calloc(cp->capacity, sizeof(Connection));

    pthread_mutex_init(&cp->lock, NULL);
    pthread_cond_init(&cp->cond, NULL);

    return cp;
}

void destroy_connection_pool(ConnectionPool *cp) {
    if (!cp) return;

    free(cp->pool);
    pthread_mutex_destroy(&cp->lock);
    pthread_cond_destroy(&cp->cond);
    free(cp);
}

bool safe_add(size_t a, size_t b, size_t *result) {
    if (a > SIZE_MAX - b) return false;
    *result = a + b;
    return true;
}

void update_connection(Connection *conn) {
    conn->average_latency = ((conn->average_latency * (double)(conn->packets_sent + conn->packets_received)) 
                             + /* new latency value here */ 10.0) / 
                            ((conn->packets_sent + conn->packets_received) + 1);
}

void resize_connection_pool(ConnectionPool *cp, size_t new_capacity) {
    if (new_capacity > MAX_CONNECTIONS || !safe_add(cp->size, 1, &new_capacity)) return;

    Connection *new_pool = realloc(cp->pool, new_capacity * sizeof(Connection));
    if (!new_pool) return; // Handle allocation failure

    cp->capacity = new_capacity;
    cp->pool = new_pool;
}

void add_connection(ConnectionPool *cp, const char *ip_address, uint16_t port) {
    pthread_mutex_lock(&cp->lock);

    while (cp->size >= cp->capacity) {
        resize_connection_pool(cp, cp->capacity * 2);
        if (cp->size >= cp->capacity) {
            pthread_cond_wait(&cp->cond, &cp->lock);
        }
    }

    Connection *conn = &cp->pool[cp->size++];
    strncpy(conn->ip_address, ip_address, sizeof(conn->ip_address));
    conn->port = port;
    conn->active = true;
    conn->packets_sent = 0;
    conn->packets_received = 0;
    conn->average_latency = 0.0;
    conn->last_active_time = time(NULL);

    pthread_mutex_unlock(&cp->lock);
}

void remove_connection(ConnectionPool *cp, size_t index) {
    if (index >= cp->size) return;

    pthread_mutex_lock(&cp->lock);

    cp->pool[index] = cp->pool[--cp->size];
    pthread_mutex_unlock(&cp->lock);
}

void update_all_connections(ConnectionPool *cp) {
    pthread_mutex_lock(&cp->lock);

    for (size_t i = 0; i < cp->size; ++i) {
        if (cp->pool[i].active) {
            // Update connection with new statistics
            update_connection(&cp->pool[i]);
            cp->pool[i].last_active_time = time(NULL);
        }
    }

    pthread_mutex_unlock(&cp->lock);
}

void check_for_timeouts(ConnectionPool *cp, time_t timeout_duration) {
    time_t current_time = time(NULL);

    pthread_mutex_lock(&cp->lock);

    for (size_t i = 0; i < cp->size; ++i) {
        if (cp->pool[i].active && (current_time - cp->pool[i].last_active_time > timeout_duration)) {
            remove_connection(cp, i);
            --i;
        }
    }

    pthread_mutex_unlock(&cp->lock);
}

void serialize_connection_pool(const ConnectionPool *cp, FILE *file) {
    pthread_mutex_lock((pthread_mutex_t*)&cp->lock);

    fwrite(&cp->size, sizeof(size_t), 1, file);
    fwrite(cp->pool, sizeof(Connection), cp->size, file);

    pthread_mutex_unlock((pthread_mutex_t*)&cp->lock);
}

void deserialize_connection_pool(ConnectionPool *cp, FILE *file) {
    size_t new_size;

    fread(&new_size, sizeof(size_t), 1, file);
    if (new_size > cp->capacity || !safe_add(cp->size, new_size, &cp->capacity)) return;

    resize_connection_pool(cp, new_size);

    fread(cp->pool, sizeof(Connection), new_size, file);
    cp->size = new_size;
}

// Example usage
int main() {
    ConnectionPool *cp = create_connection_pool(INITIAL_POOL_SIZE);

    add_connection(cp, "192.168.1.1", 8080);
    update_all_connections(cp);
    check_for_timeouts(cp, 60); // 60 seconds timeout

    FILE *file = fopen("connections.dat", "wb");
    serialize_connection_pool(cp, file);
    fclose(file);

    ConnectionPool *cp2 = create_connection_pool(INITIAL_POOL_SIZE);
    file = fopen("connections.dat", "rb");
    deserialize_connection_pool(cp2, file);
    fclose(file);

    destroy_connection_pool(cp);
    destroy_connection_pool(cp2);

    return 0;
}
```

