// Define the record structure
typedef struct {
    int value;  // References a key from the keys array
} record;

// Function declarations
void* manage_memory_and_initialize(void *args);
int generate_random_value(int current_sum, int range_min, int range_max);

// Thread-safe globals
pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;
long total_sum = 0;

typedef struct {
    long num_records;           // Number of records to allocate
    int range_min;              // Min value for the random number generator
    int range_max;              // Max value for the random number generator
} config_t;

void* manage_memory_and_initialize(void *args) {
    config_t *config = (config_t *)args;

    long num_records = config->num_records;
    int range_min = config->range_min;
    int range_max = config->range_max;

    // Allocate memory for the arrays
    long *offsets = malloc(num_records * sizeof(long));
    int *keys = malloc(num_records * sizeof(int));

    if (!offsets || !keys) {
        perror("Memory allocation failed");
        return NULL;
    }

    record *records = malloc(num_records * sizeof(record));
    if (!records) {
        perror("Memory allocation failed");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize random number generator
    srand(time(NULL));

    for (long i = 0; i < num_records; ++i) {
        offsets[i] = i;

        // Assign a key from the keys array based on offset
        keys[i] = rand() % num_records;

        // Calculate record value and update total sum
        int current_value = generate_random_value(total_sum, range_min, range_max);

        pthread_mutex_lock(&memory_lock);
        records[i].value = keys[current_value % num_records];
        total_sum += records[i].value;
        pthread_mutex_unlock(&memory_lock);
    }

    // Periodic memory integrity verification
    for (long i = 0; i < num_records; ++i) {
        if (records[i].value >= num_records || records[i].value < 0) {
            fprintf(stderr, "Data corruption detected at index %ld\n", i);
            break;
        }
    }

    // Cleanup
    free(offsets);
    free(keys);
    free(records);

    return NULL;
}

int generate_random_value(int current_sum, int range_min, int range_max) {
    return (rand() % (range_max - range_min + 1)) + range_min + current_sum;
}
