typedef struct {
    int value;
} record;

#define MIN_SIZE 1000

void* custom_random_generator(void) {
    // Simple custom random number generator implementation
    static unsigned long long seed = 1;
    seed ^= seed << 21;
    seed ^= seed >> 35;
    seed ^= seed << 4;
    return (void*)(seed & ((unsigned long long)(RAND_MAX + 1)));
}

int is_unique_int(int *keys, int size, int key) {
    for (int i = 0; i < size; ++i) {
        if (keys[i] == key) {
            return 0;
        }
    }
    return 1;
}

void* memory_manager(void* arg) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    long *offsets = NULL;
    int *keys = NULL;
    record *records = NULL;

    offsets = (long*)malloc(MIN_SIZE * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Failed to allocate memory for offsets.\n");
        goto cleanup;
    }

    keys = (int*)malloc(MIN_SIZE * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Failed to allocate memory for keys.\n");
        free(offsets);
        goto cleanup;
    }

    records = (record*)malloc(MIN_SIZE * sizeof(record));
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records.\n");
        free(offsets);
        free(keys);
        goto cleanup;
    }

    srand(time(NULL));

    pthread_mutex_lock(&mutex);

    // Initialize offsets with values greater than zero
    for (int i = 0; i < MIN_SIZE; ++i) {
        offsets[i] = rand() % (MAX_LONG - 1) + 1;
    }

    // Generate unique keys
    int count_unique_keys = 0;
    while (count_unique_keys < MIN_SIZE) {
        int key = rand();
        if (is_unique_int(keys, count_unique_keys, key)) {
            keys[count_unique_keys++] = key;
        }
    }

    // Initialize records with random values using custom generator
    for (int i = 0; i < MIN_SIZE; ++i) {
        void* random_value = custom_random_generator();
        records[i].value = ((unsigned long)random_value) % 1001;
    }

    pthread_mutex_unlock(&mutex);

cleanup:
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) free(records);
    return NULL;
}

void update_record(int index, int new_value, record *records, int size) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    pthread_mutex_lock(&mutex);

    if (index >= 0 && index < size) {
        records[index].value = new_value;
    } else {
        fprintf(stderr, "Invalid index: %d\n", index);
    }

    pthread_mutex_unlock(&mutex);
}

int main() {
    pthread_t thread_id;

    // Create a separate thread to manage memory
    if (pthread_create(&thread_id, NULL, &memory_manager, NULL) != 0) {
        fprintf(stderr, "Failed to create thread.\n");
        return EXIT_FAILURE;
    }

    // Wait for the thread to complete
    pthread_join(thread_id, NULL);

    return EXIT_SUCCESS;
}
