void manage_nfa_crc_indication_pdu_array(
    NFAPI_CRC_INDICATION_PDU_T** pdu_array,
    size_t* array_size,
    const int* active_rntis,
    size_t num_active_rntis,
    size_t max_entries) {

    if (!pdu_array || !array_size || !active_rntis) {
        log_error("Invalid input parameters");
        return;
    }

    *array_size = 0;
    srand(time(NULL));

    while (*array_size < max_entries) {
        int rnti = rand() % 10000; // Example range for RNTI
        if (!is_active_rnti(rnti, active_rntis, num_active_rntis)) {
            log_error("RNTI out of bounds");
            continue;
        }

        NFAPI_CRC_INDICATION_PDU_T* temp_array = realloc(*pdu_array, (*array_size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!temp_array) {
            log_error("Memory allocation failed");
            free(*pdu_array);
            *pdu_array = NULL;
            break;
        }

        (*pdu_array) = temp_array;
        (*pdu_array)[*array_size].RX_UE_INFORMATION_TAG = rand() % 1000; // Example range
        (*pdu_array)[*array_size].RNTI = rnti;
        int crcflag = generate_random_crcflag();

        printf("Generated CRC_INDICATION_REL8_TAG with CRCFLAG: %d\n", crcflag);

        (*array_size)++;
    }

    if (*array_size == 0) {
        free(*pdu_array);
        *pdu_array = NULL;
    }
}

void cleanup_nfa_crc_indication_pdu_array(NFAPI_CRC_INDICATION_PDU_T** pdu_array) {
