    }

    public function hashPassword($password, $salt = null) {
        if ($salt === null) {
            $salt = $this->generateSalt();
        }

        switch ($this->hashingAlgorithm) {
            case 'bcrypt':
                $options = ['cost' => $this->workFactor];
                return password_hash($password . $salt, PASSWORD_BCRYPT, $options) . ':' . bin2hex($salt);
            case 'argon2id':
                return password_hash($password . $salt, PASSWORD_ARGON2ID, array_merge(['memory_cost' => $this->argon2Params['memory_cost'], 
                                                                                          'time_cost' => $this->argon2Params['time_cost'],
                                                                                          'threads' => $this->argon2Params['threads']], ['hash_len' => 32])) . ':' . bin2hex($salt);
            case 'sha256':
                return hash('sha256', $password . $salt) . ':' . bin2hex($salt);
            default:
                throw new InvalidArgumentException('Unsupported hashing algorithm.');
        }
    }

    public function verifyPassword($password, $hashedPasswordWithSalt) {
        list($hash, $saltHex) = explode(':', $hashedPasswordWithSalt);

        switch ($this->hashingAlgorithm) {
            case 'bcrypt':
            case 'argon2id':
                return password_verify($password . hex2bin($saltHex), $hash);
            case 'sha256':
                return hash('sha256', $password . hex2bin($saltHex)) === $hash;
            default:
                throw new InvalidArgumentException('Unsupported hashing algorithm.');
        }
    }

    public function serializeUserDataForStorage($userId, $hashedPasswordWithSalt) {
        return json_encode([
            'user_id' => $userId,
            'hashed_password_with_salt' => $hashedPasswordWithSalt,
        ]);
    }

    public function deserializeUserDataFromStorage($data) {
        return json_decode($data, true);
    }

    private function logOperation($operationType, $result) {
        // This is a placeholder for logging mechanism. Implement according to the system requirements.
        error_log("[$operationType] - Result: $result at " . date('Y-m-d H:i:s'));
    }
}

?>
