['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Node {
    struct Node *parent;
    struct Node *first_child;
    int value;
    int active; // 0 for inactive, 1 for active
} Node;

// Mutex for thread safety during insertion and validation
pthread_mutex_t tree_mutex = PTHREAD_MUTEX_INITIALIZER;

Node* create_node(int value) {
    Node *node = (Node*) malloc(sizeof(Node));
    if (!node) return NULL;

    node->parent = NULL;
    node->first_child = NULL;
    node->value = value;
    node->active = 1; // New nodes are active by default
    return node;
}

void free_tree(Node *root) {
    if (!root) return;

    Node *current, *next;
    for (current = root; current != NULL;) {
        next = current->first_child;
        free(current);
        current = next;
    }
}

int validate_tree(Node *node, int expected_value, int depth) {
    // A simple validation: ensure all nodes are active and have correct values
    if (!node || !node->active) return 0;

    Node *current = node;
    while (current) {
        if (current->value != expected_value + depth) return 0;
        current = current->first_child;
    }
    return 1;
}

void insert_node(Node *parent, int value_offset) {
    pthread_mutex_lock(&tree_mutex);

    Node *new_node = create_node(parent->value + value_offset);
    if (!new_node) {
        pthread_mutex_unlock(&tree_mutex);
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    new_node->parent = parent;

    // Insert node as the first child of the parent
    new_node->first_child = parent->first_child;
    parent->first_child = new_node;

    if (!validate_tree(parent, parent->value, 1)) {
        fprintf(stderr, "Tree validation failed after insertion\n");
        free(new_node);
    }

    pthread_mutex_unlock(&tree_mutex);
}

int main() {
    Node *root = create_node(0); // Initialize root with value 0
    if (!root) {
        fprintf(stderr, "Failed to initialize the root node\n");
        return EXIT_FAILURE;
    }

    // Example of inserting nodes concurrently using threads
    pthread_t thread1, thread2;

    pthread_create(&thread1, NULL, (void *(*)(void *))insert_node, (void *)(root));
    pthread_create(&thread2, NULL, (void *(*)(void *))insert_node, (void *)(root));

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    free_tree(root);

    return 0;
}
```']

