    PacketArray *array = malloc(sizeof(PacketArray));
    array->packets = malloc(10 * sizeof(Packet *));
    array->count = 0;
    array->capacity = 10;
    pthread_mutex_init(&array->mutex, NULL);
    pthread_cond_init(&array->cond_var, NULL);
    return array;
}

