    pthread_mutex_lock(&array->mutex);

    if (!validate_packet(packet)) {
        log_message("Invalid packet");
        pthread_mutex_unlock(&array->mutex);
        free(packet->data);
        free(packet);
        return;
    }

    if (array->count == array->capacity) {
        array->capacity *= 2;
        array->packets = realloc(array->packets, array->capacity * sizeof(Packet *));
    }
    array->packets[array->count++] = packet;

    pthread_mutex_unlock(&array->mutex);
}

