#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define INITIAL_RECORD_COUNT 10

typedef struct {
    long value;
    int key;
    long *offsetPtr;
} Record;

typedef struct {
    long *offsets;
    int *keys;
    size_t capacity;
    size_t count;
} DynamicArray;

// Memory pool for Record structures
#define POOL_SIZE 100
Record recordPool[POOL_SIZE];
size_t poolIndex = 0;

void initializeMemoryPool() {
    memset(recordPool, 0, sizeof(recordPool));
}

Record* allocateFromPool() {
    if (poolIndex < POOL_SIZE) {
        return &recordPool[poolIndex++];
    }
    return NULL; // Pool exhausted
}

void freeToPool(Record *record) {
    if (record && poolIndex > 0) {
        poolIndex--;
        memset(record, 0, sizeof(*record)); // Reset memory for reuse
    }
}

// Initialize dynamic arrays with validation and unique keys
bool initializeDynamicArrays(DynamicArray *offsets, DynamicArray *keys) {
    offsets->capacity = INITIAL_RECORD_COUNT;
    offsets->count = 0;

    keys->capacity = INITIAL_RECORD_COUNT;
    keys->count = 0;

    // Allocate memory for dynamic arrays
    offsets->offsets = (long *)malloc(offsets->capacity * sizeof(long));
    if (!offsets->offsets) return false;

    keys->keys = (int *)malloc(keys->capacity * sizeof(int));
    if (!keys->keys) {
        free(offsets->offsets);
        return false;
    }

    // Initialize with unique keys and offsets > 0
    bool keyExists[256] = {false}; // Assuming int range is manageable in this array

    for (size_t i = 0; i < INITIAL_RECORD_COUNT; ++i) {
        if (!keyExists[keys->keys[i]]) {
            keyExists[keys->keys[i]] = true;
            keys->count++;
        } else {
            // Handle duplicate keys by finding a new unique key
            int newKey = rand() % 256;
            while (keyExists[newKey]) {
                newKey = (newKey + 1) % 256;
            }
            keys->keys[i] = newKey;
            keyExists[newKey] = true;
        }

        offsets->offsets[i] = rand() % 1000000 + 1; // Offset > 0
    }

    return true;
}

void resizeDynamicArray(DynamicArray *array, size_t newCapacity) {
    void *newMemory = realloc(array->offsets, newCapacity * sizeof(*(array->offsets)));
    if (newMemory) {
        array->capacity = newCapacity;
        array->offsets = (long *)newMemory;
    } else {
        fprintf(stderr, "Failed to resize dynamic array\n");
    }
}

Record* createRecords(DynamicArray *keys, DynamicArray *offsets, size_t recordCount) {
    Record *records = (Record *)malloc(recordCount * sizeof(Record));
    if (!records) return NULL;

    for (size_t i = 0; i < recordCount; ++i) {
        records[i].value = generateRandomLong(1, 100);
        records[i].key = keys->keys[i % keys->count];
        size_t offsetIndex = rand() % offsets->count;
        records[i].offsetPtr = &offsets->offsets[offsetIndex];

        // If pool allocation is preferred
        Record *poolRecord = allocateFromPool();
        if (poolRecord) {
            memcpy(poolRecord, &records[i], sizeof(Record));
            records[i] = *poolRecord;
        }
    }

    return records;
}

void updateRecordValue(Record *records, size_t index, long newValue) {
    if (index < 0 || index >= poolIndex) {
        fprintf(stderr, "Index out of bounds\n");
        return;
    }

    // Update in a cache-friendly manner
    records[index].value = newValue;
}

void freeMemory(Record *records, DynamicArray *offsets, DynamicArray *keys) {
    if (records) free(records);

    if (offsets->offsets) free(offsets->offsets);
    if (keys->keys) free(keys->keys);

    // Reset pool index
    poolIndex = 0;
}

long generateRandomLong(long min, long max) {
    return rand() % (max - min + 1) + min;
}
```

