#include <bzlib.h>

#define MAX_CONCURRENT_READS 4

typedef struct {
    FILE *file;
    size_t chunk_size;
} FileChunkReader;

typedef struct {
    char *data;
    size_t data_len;
    int is_compressed;
    const char *format; // "gzip", "bz2"
} ChunkData;

void streamFileData(const char *filename, size_t chunk_size, const char *file_format) {
    if (chunk_size < 4096 || chunk_size > 65536) {
        fprintf(stderr, "Invalid chunk size. Must be between 4KB and 64KB.\n");
        return;
    }

    FILE *fp = fopen(filename, "rb");
    if (!fp) {
        perror("Failed to open file");
        return;
    }

    pthread_t threads[MAX_CONCURRENT_READS];
    FileChunkReader readers[MAX_CONCURRENT_READS] = {0};
    for (int i = 0; i < MAX_CONCURRENT_READS; ++i) {
        readers[i].file = fp;
        readers[i].chunk_size = chunk_size;

        if (pthread_create(&threads[i], NULL, readChunk, &readers[i])) {
            fprintf(stderr, "Error creating thread\n");
            break;
        }
    }

    for (int i = 0; i < MAX_CONCURRENT_READS; ++i) {
        pthread_join(threads[i], NULL);
    }

    fclose(fp);
}

void* readChunk(void *arg) {
    FileChunkReader *reader = (FileChunkReader *)arg;
    ChunkData chunk_data;

    while (1) {
        chunk_data.data = malloc(reader->chunk_size);
        if (!chunk_data.data) {
            fprintf(stderr, "Memory allocation failed\n");
            break;
        }

        size_t bytes_read = fread(chunk_data.data, 1, reader->chunk_size, reader->file);
        if (bytes_read == 0 && feof(reader->file)) {
            free(chunk_data.data);
            break;
        }

        chunk_data.data_len = bytes_read;
        chunk_data.is_compressed = strcmp(reader->format, "gzip") == 0 || strcmp(reader->format, "bz2") == 0;

        if (chunk_data.is_compressed) {
            processCompressedData(&chunk_data);
        } else {
            // Process uncompressed data
            processData(chunk_data.data, chunk_data.data_len);
        }

        free(chunk_data.data);
    }
    return NULL;
}

void processCompressedData(ChunkData *data) {
    if (strcmp(data->format, "gzip") == 0) {
        z_stream strm;
        strm.zalloc = Z_NULL;
        strm.zfree = Z_NULL;
        strm.opaque = Z_NULL;
        strm.avail_in = data->data_len;
        strm.next_in = (unsigned char *)data->data;

        if (inflateInit(&strm) != Z_OK) {
            fprintf(stderr, "Failed to initialize gzip decompression\n");
            return;
        }

        // Decompress the chunk
        unsigned char out[2 * reader.chunk_size];
        strm.avail_out = sizeof(out);
        strm.next_out = out;

        int ret = inflate(&strm, Z_NO_FLUSH);
        if (ret != Z_STREAM_END) {
            fprintf(stderr, "Gzip decompression failed\n");
        }

        // Use decompressed data
        processData(out, reader.chunk_size - strm.avail_out);

        inflateEnd(&strm);
    } else if (strcmp(data->format, "bz2") == 0) {
        BZFILE *bzfp = BZ2_bzReadOpen(NULL, &data->file, NULL, 0, NULL, 0);
        unsigned char out[2 * reader.chunk_size];
        int bzret;

        bzret = BZ2_bzBuffToBuffDecompress(out, sizeof(out), data->data, data->data_len, 0, NULL, NULL);
        if (bzret != BZ_OK) {
            fprintf(stderr, "Bzip2 decompression failed\n");
        } else {
            processData(out, reader.chunk_size - bzret);
        }

        BZ2_bzReadClose(&bzfp);
    }
}

void processData(const void *data, size_t len) {
    // Implement processing logic here
}
