void deserialize_list(LinkedList* list, const char* filename);
void update_node_value(LinkedList* list, double old_value, double new_value);

// Custom memory allocator
void* custom_alloc(size_t size) {
    return malloc(size); // Simple wrapper for demonstration purposes
}

void* custom_free(void* ptr) {
    free(ptr);
    return NULL;
}

// Create a new linked list with mutex initialization
LinkedList* create_list() {
    LinkedList* list = (LinkedList*)custom_alloc(sizeof(LinkedList));
    if (!list) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Insert a node at the head of the list
void insert_head(LinkedList* list, double value) {
    Node* new_node = (Node*)custom_alloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    new_node->value = value;
    new_node->next = list->head;

    pthread_mutex_lock(&list->lock);
    list->head = new_node;
    if (list->tail == NULL) {
        list->tail = new_node;
    }
    pthread_mutex_unlock(&list->lock);
}

// Insert a node at the tail of the list
void insert_tail(LinkedList* list, double value) {
    Node* new_node = (Node*)custom_alloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    new_node->value = value;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;
    pthread_mutex_unlock(&list->lock);
}

// Delete the first node with a specific value
Node* delete_node(LinkedList* list, double criterion) {
    Node *current = list->head, *prev = NULL;

    pthread_mutex_lock(&list->lock);

    while (current != NULL) {
        if (current->value == criterion) {
            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }
            if (current == list->tail) {
                list->tail = prev;
            }

            pthread_mutex_unlock(&list->lock);
            return current; // Return the deleted node
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}

// Print all values in the list
void print_list(LinkedList* list) {
    Node* current = list->head;

    pthread_mutex_lock(&list->lock);

    while (current != NULL) {
        printf("%f ", current->value);
        current = current->next;
    }
    printf("\n");

    pthread_mutex_unlock(&list->lock);
}

// Search for a node with a specific value
Node* search_node(LinkedList* list, double value) {
    Node* current = list->head;

    pthread_mutex_lock(&list->lock);

    while (current != NULL) {
        if (current->value == value) {
            pthread_mutex_unlock(&list->lock);
            return current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}

// Merge sort helper function
Node* sorted_merge(Node *a, Node *b) {
    if (!a) return b;
    if (!b) return a;

    Node* result = NULL;

    if (a->value <= b->value) {
        result = a;
        result->next = sorted_merge(a->next, b);
    } else {
        result = b;
        result->next = sorted_merge(a, b->next);
    }
    return result;
}

// Split the linked list into two halves
void front_back_split(Node* source, Node** frontRef, Node** backRef) {
    Node *fast, *slow;
    slow = source;
    fast = source->next;

    while (fast != NULL) {
        fast = fast->next;
        if (fast != NULL) {
            slow = slow->next;
            fast = fast->next;
        }
    }

    *frontRef = source;
    *backRef = slow->next;
    slow->next = NULL;
}

// Merge sort implementation
void merge_sort(Node** head_ref) {
    Node* head = *head_ref;
    Node* a;
    Node* b;

    if ((head == NULL) || (head->next == NULL)) {
        return;
    }

    front_back_split(head, &a, &b);

    merge_sort(&a);
    merge_sort(&b);

    *head_ref = sorted_merge(a, b);
}

// Sort the list
void sort_list(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    merge_sort(&(list->head));
    pthread_mutex_unlock(&list->lock);
}

// Serialize the list to a file
void serialize_list(LinkedList* list, const char* filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }

    pthread_mutex_lock(&list->lock);
    Node* current = list->head;

    while (current != NULL) {
        fwrite(&(current->value), sizeof(double), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);

    fclose(file);
}

// Deserialize the list from a file
void deserialize_list(LinkedList* list, const char* filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for reading\n");
        return;
    }

    pthread_mutex_lock(&list->lock);
    while (1) {
        double value;
        size_t read_size = fread(&(value), sizeof(double), 1, file);
        if (read_size == 0) break; // End of file
        insert_tail(list, value);
    }
    pthread_mutex_unlock(&list->lock);

    fclose(file);
}

// Update a node's value
void update_node_value(LinkedList* list, double old_value, double new_value) {
    Node* current = search_node(list, old_value);
    if (current) {
        pthread_mutex_lock(&list->lock);
        current->value = new_value;
        pthread_mutex_unlock(&list->lock);
    }
}

// Free the entire linked list
void free_list(LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        custom_free(current);
        current = next;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    custom_free(list);
}

// Main function for testing
int main() {
    LinkedList* list = create_list();

    insert_head(list, 3.5);
    insert_tail(list, 2.1);
    insert_tail(list, 4.8);

    printf("List before sorting: ");
    print_list(list);

    sort_list(list);
    printf("List after sorting: ");
    print_list(list);

    Node* deleted_node = delete_node(list, 2.1);
    if (deleted_node) {
        custom_free(deleted_node);
    }

    printf("List after deletion: ");
    print_list(list);

    serialize_list(list, "list.dat");
    LinkedList* new_list = create_list();
    deserialize_list(new_list, "list.dat");

    printf("Deserialized list: ");
    print_list(new_list);

    update_node_value(new_list, 3.5, 9.0);
    printf("List after updating value: ");
    print_list(new_list);

    free_list(list);
    free_list(new_list);

    return 0;
}
```']

['Below is a C implementation of the `manage_packet_queue` function based on your requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_QUEUE_SIZE 1000

typedef struct {
    int timestamp;
    size_t packet_size;
    void *packet_data;
} Packet;

typedef struct Node {
    Packet packet;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    int count;
    pthread_mutex_t mutex;
} PacketQueue;

// Function to parse packet data using an external library
int parse_packet_data(void *raw_data, void **parsed_data) {
    // Simulate parsing logic
    if (raw_data == NULL) return -1; // Error in parsing
    *parsed_data = malloc(100); // Assume parsed data size is 100 bytes
    if (*parsed_data == NULL) return -2; // Memory allocation failure
    strcpy((char *)*parsed_data, "Parsed Data");
    return 0;
}

// Function to check for duplicate packets
int is_duplicate(PacketQueue *queue, Packet packet) {
    Node* current = queue->head;
    while (current != NULL) {
        if (current->packet.timestamp == packet.timestamp &&
            current->packet.packet_size == packet.packet_size) {
            return 1; // Duplicate found
        }
        current = current->next;
    }
    return 0; // No duplicate
}

// Function to add a packet to the queue
void enqueue(PacketQueue *queue, Packet packet) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    new_node->packet = packet;
    new_node->next = NULL;

    pthread_mutex_lock(&queue->mutex);
    if (queue->tail == NULL) {
        queue->head = queue->tail = new_node;
    } else {
        queue->tail->next = new_node;
        queue->tail = new_node;
    }
    queue->count++;
    pthread_mutex_unlock(&queue->mutex);

    // Remove oldest packet if the queue exceeds max size
    while (queue->count > MAX_QUEUE_SIZE) {
        Node* temp = queue->head;
        queue->head = queue->head->next;
        free(temp);
        queue->count--;
    }
}

// Function to manage the packet queue
void manage_packet_queue(PacketQueue *queue, void *raw_data) {
    Packet new_packet;
    int parse_status = parse_packet_data(raw_data, (void**)&new_packet.packet_data);

    if (parse_status != 0) {
        fprintf(stderr, "Failed to parse packet data\n");
        return;
    }

    pthread_mutex_lock(&queue->mutex);

    // Validate packet
    if (!raw_data || new_packet.packet_size == 0 || !new_packet.packet_data) {
        fprintf(stderr, "Invalid packet received\n");
        free(new_packet.packet_data);
        pthread_mutex_unlock(&queue->mutex);
        return;
    }

    // Assign timestamp and size for the example (these should come from somewhere)
    new_packet.timestamp = rand(); // Example: using random as a placeholder
    new_packet.packet_size = 100; // Example packet size

    if (!is_duplicate(queue, new_packet)) {
        enqueue(queue, new_packet);
    } else {
        fprintf(stderr, "Duplicate packet detected\n");
    }

    pthread_mutex_unlock(&queue->mutex);

    // Free the parsed data after processing
    free(new_packet.packet_data);
}

// Function to initialize the queue
PacketQueue* create_packet_queue() {
    PacketQueue* queue = (PacketQueue*)malloc(sizeof(PacketQueue));
    if (!queue) {
        fprintf(stderr, "Memory allocation failed for packet queue\n");
        return NULL;
    }
    queue->head = queue->tail = NULL;
    queue->count = 0;
    pthread_mutex_init(&queue->mutex, NULL);
    return queue;
}

// Function to destroy the queue
void destroy_packet_queue(PacketQueue *queue) {
    Node* current = queue->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&queue->mutex);
    free(queue);
}
```

### Key Points:
- **Concurrency**: Uses a mutex to ensure thread-safe operations.
- **Duplication Check**: Compares timestamps and sizes to identify duplicates.
- **Queue Management**: Discards the oldest packets when exceeding capacity.
- **Error Handling**: Handles parsing errors, memory allocation failures, and invalid packets gracefully.']

