    ProcessingUnit *processing_unit;
} Workload;

typedef struct {
    Workload **workloads;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} WorkloadCollection;

WorkloadCollection workload_collection = {NULL, 0, 10, PTHREAD_MUTEX_INITIALIZER};

void initialize_workload(Workload *w, ProcessingUnit *pu) {
    w->timestamp = time(NULL);
    w->priority = rand() % 10; // Random priority for demonstration
    w->processing_unit = pu;
}

void resize_workload_collection(size_t new_capacity) {
    pthread_mutex_lock(&workload_collection.lock);

    Workload **new_array = realloc(workload_collection.workloads, new_capacity * sizeof(Workload *));
    if (new_array == NULL) {
        perror("Failed to resize workload array");
        exit(EXIT_FAILURE);
    }

    if (!new_array) {
        memset(new_array + workload_collection.capacity, 0,
               (new_capacity - workload_collection.capacity) * sizeof(Workload *));
    }

    workload_collection.workloads = new_array;
    workload_collection.capacity = new_capacity;

    pthread_mutex_unlock(&workload_collection.lock);
}

void add_workload(ProcessingUnit *pu) {
    if (workload_collection.size >= workload_collection.capacity) {
        resize_workload_collection(workload_collection.capacity * 2);
    }

    Workload *w = malloc(sizeof(Workload));
    if (!w) {
        perror("Failed to allocate memory for workload");
        exit(EXIT_FAILURE);
    }

    initialize_workload(w, pu);

    pthread_mutex_lock(&workload_collection.lock);
    workload_collection.workloads[workload_collection.size++] = w;
    pthread_mutex_unlock(&workload_collection.lock);
}

void update_workload_priority(int index) {
    // Example priority update rule
    pthread_mutex_lock(&workload_collection.lock);
    if (index < 0 || index >= workload_collection.size) {
        fprintf(stderr, "Index out of bounds\n");
        pthread_mutex_unlock(&workload_collection.lock);
        return;
    }

    Workload *w = workload_collection.workloads[index];
    w->priority += 1; // Increment priority
    pthread_mutex_unlock(&workload_collection.lock);
}

void serialize_workloads(const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for serialization");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&workload_collection.lock);

    fwrite(&workload_collection.size, sizeof(size_t), 1, file);
    for (size_t i = 0; i < workload_collection.size; ++i) {
        Workload *w = workload_collection.workloads[i];
        fwrite(w, sizeof(Workload), 1, file);
    }

    pthread_mutex_unlock(&workload_collection.lock);

    fclose(file);
}

void deserialize_workloads(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for deserialization");
        exit(EXIT_FAILURE);
    }

    size_t new_size;
    fread(&new_size, sizeof(size_t), 1, file);

    resize_workload_collection(new_size);

    pthread_mutex_lock(&workload_collection.lock);
    for (size_t i = 0; i < workload_collection.size; ++i) {
        Workload *w = malloc(sizeof(Workload));
        fread(w, sizeof(Workload), 1, file);
        workload_collection.workloads[i] = w;
    }
    workload_collection.size = new_size;

    pthread_mutex_unlock(&workload_collection.lock);

    fclose(file);
}

void* monitoring_function(void *arg) {
