    okr->offsets = (int *)calloc(initial_capacity, sizeof(int));
    okr->keys = (int *)calloc(initial_capacity, sizeof(int));
    okr->records = (int *)calloc(initial_capacity, sizeof(int));
    okr->count = 0;
    pthread_mutex_unlock(&lock);
}

void generate_random_int_range_adjusted(int *value) {
    int range_start = -MAX_RANGE / 2;
    int range_end = MAX_RANGE / 2;

    // Adjust range based on cumulative sum
    long long cumulative_sum = 0;
    for (size_t i = 0; i < count; ++i) {
        cumulative_sum += records[i];
    }

    range_start += cumulative_sum % MAX_RANGE;
    range_end += cumulative_sum % MAX_RANGE;

    *value = rand() % (range_end - range_start + 1) + range_start;
}

int is_overflow_detected(long long a, long long b) {
    return a > LLONG_MAX - b;
}

void serialize_data_structure(const OffsetKeyRecord *okr, const char *filename) {
