    fwrite(okr->offsets, sizeof(int), okr->count, file);
    fwrite(okr->keys, sizeof(int), okr->count, file);
    fwrite(okr->records, sizeof(int), okr->count, file);
    fclose(file);
    pthread_mutex_unlock(&lock);
