Now, here's a C# program to load configuration settings from an XML file:

```csharp
using System;
using System.Xml.Linq;

class ConfigurationSettings {
    public int TileSize { get; set; }
    public int WorldWidth { get; set; }
    public int WorldHeight { get; set; }
    public float CameraSpeed { get; set; }

    static void LoadConfiguration(string filePath) {
        try {
            var doc = XDocument.Load(filePath);
            ConfigurationSettings settings = new ConfigurationSettings();

            settings.TileSize = (int)doc.Element("Settings").Element("TileSize").Value;
            settings.WorldWidth = (int)doc.Element("Settings").Element("WorldWidth").Value;
            settings.WorldHeight = (int)doc.Element("Settings").Element("WorldHeight").Value;
            settings.CameraSpeed = float.Parse(doc.Element("Settings").Element("CameraSpeed").Value);

            Console.WriteLine($"Tile Size: {settings.TileSize}, World Width: {settings.WorldWidth}, " +
                              $"World Height: {settings.WorldHeight}, Camera Speed: {settings.CameraSpeed}");
        }
        catch (Exception ex) {
            Console.Error.WriteLine($"Error loading configuration: {ex.Message}");
        }
    }

    static void Main() {
        string configFilePath = "config.xml";
        LoadConfiguration(configFilePath);
    }
}
