} LogLevel;

typedef struct {
    char *level_str;
} LogLevelMap;

LogLevelMap log_level_map[] = {
    {"DEBUG"}, {"INFO"}, {"WARNING"}, {"ERROR"}, {"CRITICAL"}
};

#define MAX_LOG_FILES 5
#define LOG_FILE_SIZE_THRESHOLD (1024 * 1024) // 1MB

typedef struct {
    FILE **log_files;
    int current_file_index;
    size_t current_log_size;
    pthread_mutex_t file_lock;
} LogFileManager;

LogFileManager log_manager = {NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER};

void init_logger(const char *base_filename) {
    char filename[256];
    for (int i = 0; i < MAX_LOG_FILES; ++i) {
        snprintf(filename, sizeof(filename), "%s_%d.log", base_filename, i);
        log_manager.log_files[i] = fopen(filename, "a");
        if (!log_manager.log_files[i]) {
            perror("Failed to open log file");
            exit(EXIT_FAILURE);
        }
    }
}

void rotate_log_file() {
    pthread_mutex_lock(&log_manager.file_lock);

    if (log_manager.current_log_size > LOG_FILE_SIZE_THRESHOLD) {
        fclose(log_manager.log_files[log_manager.current_file_index]);
        log_manager.current_file_index = (log_manager.current_file_index + 1) % MAX_LOG_FILES;
        char filename[256];
        snprintf(filename, sizeof(filename), "%s_%d.log", "base_log", log_manager.current_file_index);
        log_manager.log_files[log_manager.current_file_index] = fopen(filename, "a");
        if (!log_manager.log_files[log_manager.current_file_index]) {
            perror("Failed to open rotated log file");
            exit(EXIT_FAILURE);
        }
    }

    pthread_mutex_unlock(&log_manager.file_lock);
}

void log_message(LogLevel level, const char *message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    char formatted_message[1024];
    snprintf(formatted_message, sizeof(formatted_message),
             "[%s] [%s]: %s\n",
             timestamp,
             log_level_map[level].level_str,
             message);

    printf("%s", formatted_message); // Output to console

    pthread_mutex_lock(&log_manager.file_lock);
    fprintf(log_manager.log_files[log_manager.current_file_index], "%s", formatted_message);
    log_manager.current_log_size += strlen(formatted_message);
    rotate_log_file();
    pthread_mutex_unlock(&log_manager.file_lock);
}

void cleanup_logger() {
    for (int i = 0; i < MAX_LOG_FILES; ++i) {
        if (log_manager.log_files[i]) {
            fclose(log_manager.log_files[i]);
        }
    }
}

int main() {
    init_logger("app_log");

    log_message(DEBUG, "This is a debug message.");
    log_message(INFO, "Informational message.");
    log_message(WARNING, "Warning: something might be wrong.");
    log_message(ERROR, "Error encountered!");
    log_message(CRITICAL, "Critical issue!");

    cleanup_logger();
    return 0;
}
```

### Key Points:
- **Log Levels**: Enum for different logging levels.
- **Log Rotation**: Rotates log files based on size threshold and maintains a maximum number of log files.
- **Synchronization**: Uses mutexes to manage concurrent access to log files.
- **Memory Management**: Ensures proper opening and closing of file streams.']

