### C Code: MAC Entity Context Library

```c
// mac_ec.h
#ifndef MAC_EC_H
#define MAC_EC_H

#include <pthread.h>

typedef struct {
    int identifier;
    void *logical_channels; // Placeholder for logical channel list
    struct {
        unsigned int timers[5];  // Example timer parameters
        char state;              // Example state parameter
    } config;
} MacEcInstance;

typedef struct {
    MacEcInstance **instances;
    size_t count;
    pthread_mutex_t lock;
} MacEcManager;

// Function prototypes
MacEcManager* initialize_mac_ec_manager(size_t initial_size);
int add_mac_ec_instance(MacEcManager *manager, int identifier, void *logical_channels, unsigned int timers[5], char state);
void delete_mac_ec_instance(MacEcManager *manager, int identifier);
MacEcInstance* get_mac_ec_instance(const MacEcManager *manager, int identifier);
void free_mac_ec_manager(MacEcManager *manager);

#endif // MAC_EC_H

// mac_ec.c
#include "mac_ec.h"
#include <stdlib.h>
#include <string.h>

MacEcManager* initialize_mac_ec_manager(size_t initial_size) {
    MacEcManager *manager = malloc(sizeof(MacEcManager));
    manager->instances = calloc(initial_size, sizeof(MacEcInstance *));
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

int add_mac_ec_instance(MacEcManager *manager, int identifier, void *logical_channels, unsigned int timers[5], char state) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->instances[i]->identifier == identifier) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Identifier already exists
        }
    }

    MacEcInstance *instance = malloc(sizeof(MacEcInstance));
    instance->identifier = identifier;
    instance->logical_channels = logical_channels;
    memcpy(instance->config.timers, timers, sizeof(instance->config.timers));
    instance->config.state = state;

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2 ? manager->capacity * 2 : 16;
        MacEcInstance **new_instances = realloc(manager->instances, new_capacity * sizeof(MacEcInstance *));
        if (!new_instances) {
            free(instance);
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->instances = new_instances;
        manager->capacity = new_capacity;
    }

    manager->instances[manager->count++] = instance;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void delete_mac_ec_instance(MacEcManager *manager, int identifier) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->instances[i]->identifier == identifier) {
            free(manager->instances[i]);
            memmove(&manager->instances[i], &manager->instances[i + 1], (manager->count - i - 1) * sizeof(MacEcInstance *));
            --manager->count;
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

MacEcInstance* get_mac_ec_instance(const MacEcManager *manager, int identifier) {
    pthread_mutex_lock((pthread_mutex_t *)&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->instances[i]->identifier == identifier) {
            MacEcInstance *instance = manager->instances[i];
            pthread_mutex_unlock((pthread_mutex_t *)&manager->lock);
            return instance;
        }
    }

    pthread_mutex_unlock((pthread_mutex_t *)&manager->lock);
    return NULL;
}

void free_mac_ec_manager(MacEcManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->instances[i]);
    }
    free(manager->instances);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
```

### JavaScript Code: Interface Module

```javascript
// macEntityManager.js
const { promisify } = require('util');
const ffi = require('ffi-napi');

// Define the C library interface
const libmacec = ffi.Library('./libmacec', {
  'initialize_mac_ec_manager': ['pointer', ['size_t']],
  'add_mac_ec_instance': ['int', ['pointer', 'int', 'pointer', 'array', 'char']],
  'delete_mac_ec_instance': ['void', ['pointer', 'int']],
  'get_mac_ec_instance': ['pointer', ['pointer', 'int']],
  'free_mac_ec_manager': ['void', ['pointer']]
});

// Wrapper functions for JS
function initializeMacEcManager(initialSize) {
    return libmacec.initialize_mac_ec_manager(initialSize);
}

function addMacEcInstance(manager, identifier, logicalChannels, timers, state) {
    // Convert JavaScript structures to appropriate C types using ffi
    const addResult = libmacec.add_mac_ec_instance(manager, identifier, logicalChannels, timers, Buffer.from(state));
    return addResult === 0;
}

function deleteMacEcInstance(manager, identifier) {
    libmacec.delete_mac_ec_instance(manager, identifier);
}

function getMacEcInstance(manager, identifier) {
    const instancePtr = libmacec.get_mac_ec_instance(manager, identifier);
    if (!instancePtr.isNull()) {
        // Convert pointer to JavaScript object
        return { /* Extracted properties */ };
    }
    return null;
}

function freeMacEcManager(manager) {
    libmacec.free_mac_ec_manager(manager);
}

// Export the interface functions
module.exports = {
    initializeMacEcManager,
    addMacEcInstance,
    deleteMacEcInstance,
    getMacEcInstance,
    freeMacEcManager,
};

// Logging and batch processing utility
function logOperation(operation, status, identifier) {
    console.log(`Operation: ${operation}, Status: ${status}, Identifier: ${identifier}`);
}

async function batchProcessOperations(operations) {
    const results = [];
    for (const op of operations) {
        let result;
        switch (op.type) {
            case 'add':
                result = addMacEcInstance(op.manager, op.identifier, op.logicalChannels, op.timers, op.state);
                logOperation('Add', result ? 'Success' : 'Failure', op.identifier);
                break;
            case 'delete':
                deleteMacEcInstance(op.manager, op.identifier);
                logOperation('Delete', 'Success', op.identifier);
                break;
            case 'get':
                const instance = getMacEcInstance(op.manager, op.identifier);
                result = { ...instance };
                logOperation('Get', instance ? 'Success' : 'Failure', op.identifier);
                results.push(result);
                break;
        }
    }
    return results;
}

module.exports.batchProcessOperations = batchProcessOperations;

// Example usage of the module
(async () => {
    const manager = initializeMacEcManager(10);
    await batchProcessOperations([
        { type: 'add', manager, identifier: 1, logicalChannels: {}, timers: [1000], state: 'active' },
        { type: 'get', manager, identifier: 1 }
    ]);
    freeMacEcManager(manager);
})();
```

