typedef struct {
    time_t timestamp;
    double temperature;
    int status; // 0 for inactive, 1 for active, etc.
} sensorData;

#define MAX_SENSORS 100

// Define a structure to hold the sensor data array and synchronization primitives
typedef struct {
    sensorData* dataArray;
    size_t count;
    pthread_mutex_t lock;
    size_t capacity;
} SensorManager;

// Function prototypes
void initializeSensorManager(SensorManager* manager, size_t initialCapacity);
void destroySensorManager(SensorManager* manager);
int addSensorData(SensorManager* manager, double temperature, int status);
sensorData getSensorData(const SensorManager* manager, size_t index);

// Initialize the sensor data management system
void initializeSensorManager(SensorManager* manager, size_t initialCapacity) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->capacity = initialCapacity;
    manager->count = 0;
    manager->dataArray = (sensorData*)malloc(manager->capacity * sizeof(sensorData));
    if (!manager->dataArray) {
        perror("Failed to allocate memory for sensor data");
        exit(EXIT_FAILURE);
    }
}

// Free allocated resources
void destroySensorManager(SensorManager* manager) {
    free(manager->dataArray);
    pthread_mutex_destroy(&manager->lock);
}

// Add new sensor data entry in a thread-safe manner
int addSensorData(SensorManager* manager, double temperature, int status) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        size_t newCapacity = manager->capacity * 2;
        sensorData* newDataArray = (sensorData*)realloc(manager->dataArray, newCapacity * sizeof(sensorData));
        if (!newDataArray) {
            perror("Failed to reallocate memory for sensor data");
            pthread_mutex_unlock(&manager->lock);
            return -1; // Indicate failure
        }
        manager->capacity = newCapacity;
        manager->dataArray = newDataArray;
    }

    time_t currentTime = time(NULL);
    sensorData newEntry = {currentTime, temperature, status};
    manager->dataArray[manager->count++] = newEntry;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Indicate success
}

// Retrieve an existing sensor data entry in a thread-safe manner
sensorData getSensorData(const SensorManager* manager, size_t index) {
    if (index >= manager->count) {
        fprintf(stderr, "Index out of bounds\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock((pthread_mutex_t*)&manager->lock);
    sensorData data = manager->dataArray[index];
    pthread_mutex_unlock((pthread_mutex_t*)&manager->lock);

    return data;
}

// Example of unsafe code with potential issues
void unsafeAddSensorData(sensorData* dataArray, size_t* count, double temperature, int status) {
    time_t currentTime = time(NULL);
    sensorData newEntry = {currentTime, temperature, status};

    // No synchronization mechanism in place; leads to race conditions
    if (*count == MAX_SENSORS) {
        fprintf(stderr, "Sensor data array is full\n");
        return;
    }

    dataArray[*count] = newEntry;
    (*count)++;
}

int main() {
    SensorManager manager;
    initializeSensorManager(&manager, 10);

    // Example usage
    addSensorData(&manager, 23.5, 1);
    sensorData data = getSensorData(&manager, 0);
    printf("Temperature: %.2f, Status: %d\n", data.temperature, data.status);

    destroySensorManager(&manager);
    return 0;
}
