                fprintf(stderr, "TLS handshake failed\n");
                error_code = TLS_HANDSHAKE_FAILED;
                connection_attempt++;
                sleep((1 << connection_attempt)); // Exponential backoff
                continue;
            }
            break; // Successful connection
        }

        if (error_code != SUCCESS) {
