#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

#define MAX_PACKET_SIZE 4096
#define MAX_PACKET_RATE 100 // packets per second
#define BUFFER_SIZE 65536   // 64KB buffer

typedef struct {
    int value;
    int *key_ref;
} Record;

typedef struct {
    time_t timestamp;
    size_t packet_size;
    uint8_t *data;
    uint32_t checksum;
} Packet;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
long *offsets = NULL;
int *keys = NULL;
Record **records = NULL;
Packet *packets = NULL;
size_t packet_count = 0;

uint32_t calculate_checksum(uint8_t *data, size_t length) {
    uint32_t checksum = 0;
    for (size_t i = 0; i < length; ++i) {
        checksum += data[i];
    }
    return checksum;
}

void initializeDataStructures(int num_offsets, int max_random_value, int max_packet_rate) {
    pthread_mutex_lock(&lock);

    // Initialize dynamic arrays
    offsets = (long *)malloc(num_offsets * sizeof(long));
    keys = (int *)malloc(num_offsets * sizeof(int));
    records = (Record **)calloc(num_offsets, sizeof(Record *));
    packets = (Packet *)malloc(BUFFER_SIZE * sizeof(Packet));

    if (!offsets || !keys || !records || !packets) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    int total_sum = 0;
    for (int i = 0; i < num_offsets; ++i) {
        offsets[i] = rand() % num_offsets;

        keys[i] = rand() % 1000; // Example key generation

        Record *record = (Record *)malloc(sizeof(Record));
        if (!record) {
            perror("Memory allocation failed for record");
            exit(EXIT_FAILURE);
        }
        record->value = rand() % max_random_value;
        total_sum += record->value;

        if ((long long)total_sum + record->value < total_sum) {
            fprintf(stderr, "Integer overflow detected\n");
            exit(EXIT_FAILURE);
        }

        record->key_ref = &keys[offsets[i]];
        records[offsets[i]] = record;
    }

    // Packet management simulation
    for (size_t i = 0; i < BUFFER_SIZE / sizeof(Packet); ++i) {
        packets[i].timestamp = time(NULL);
        packets[i].packet_size = rand() % (MAX_PACKET_SIZE + 1);
        packets[i].data = (uint8_t *)malloc(packets[i].packet_size);
        if (!packets[i].data) {
            perror("Memory allocation failed for packet data");
            exit(EXIT_FAILURE);
        }

        for (size_t j = 0; j < packets[i].packet_size; ++j) {
            packets[i].data[j] = rand() % 256;
        }
        packets[i].checksum = calculate_checksum(packets[i].data, packets[i].packet_size);

        if ((i + 1) % max_packet_rate == 0) {
            printf("Processed packet rate: %zu\n", i + 1);
        }

        // Simulate out-of-order handling by swapping two random packets
        if (i > 0 && rand() % 2) {
            size_t idx = rand() % i;
            Packet temp = packets[i];
            packets[i] = packets[idx];
            packets[idx] = temp;
        }
    }

    pthread_mutex_unlock(&lock);
}

int main() {
    srand(time(NULL));
    initializeDataStructures(1000, 10000, MAX_PACKET_RATE);
    return 0;
}
