void resize_if_needed(ConfigManager* manager) {
    if (manager->size >= manager->capacity) {
        sem_wait(&manager->available_slots); // Wait for available slot
        manager->capacity *= 2;
        Config** new_configs = (Config**)realloc(manager->configs, manager->capacity * sizeof(Config*));
        memset(new_configs + manager->size, 0, (manager->capacity - manager->size) * sizeof(Config*));
