        new_config->param.strValue = (char*)malloc(len);
        strcpy(new_config->param.strValue, (char*)value);
    }

    manager->configs[manager->size++] = new_config;

    pthread_mutex_unlock(&manager->mutex);
    return new_config->version;
}

void delete_config(ConfigManager* manager, const char* name) {
    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->size; ++i) {
        if (strcmp(manager->configs[i]->name, name) == 0) {
            free(manager->configs[i]->name);
            free_config(manager->configs[i]->param);
            free(manager->configs[i]);
            memmove(&manager->configs[i], &manager->configs[i + 1], (manager->size - i - 1) * sizeof(Config*));
            manager->size--;
            sem_post(&manager->available_slots); // Release slot
            pthread_mutex_unlock(&manager->mutex);
            return;
        }
