    size_t int_array_size;
    size_t record_array_size;
    int rand_min;
    int rand_max;
    size_t max_memory_limit;
    unsigned int seed;
} Config;

// Global variables for thread safety and memory tracking
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static size_t total_allocated_memory = 0;

// Function to dynamically adjust array sizes based on available memory
void adjust_array_sizes(Config *config, size_t max_memory_limit) {
    // Example: Simple adjustment logic
    if (total_allocated_memory > max_memory_limit) {
        config->long_array_size /= 2;
        config->int_array_size /= 2;
        config->record_array_size /= 2;
    }
}

// Function to allocate memory for arrays and records
void* allocate_and_initialize(Config *config) {
    pthread_mutex_lock(&mutex);

    adjust_array_sizes(config, config->max_memory_limit);

    // Calculate required memory size with alignment considerations
    size_t long_array_mem = config->long_array_size * sizeof(long);
    size_t int_array_mem = config->int_array_size * sizeof(int);
    size_t record_array_mem = config->record_array_size * sizeof(Record);
    size_t total_required_memory = long_array_mem + int_array_mem + record_array_mem;

    // Check if memory allocation is feasible
    if (total_required_memory > config->max_memory_limit) {
        pthread_mutex_unlock(&mutex);
        fprintf(stderr, "Error: Memory requirement exceeds the limit.\n");
        return NULL;
    }

    total_allocated_memory = total_required_memory;

    long *offsets = (long *)aligned_alloc(alignof(long), long_array_mem);
    int *keys = (int *)aligned_alloc(alignof(int), int_array_mem);
    Record *records = (Record *)aligned_alloc(alignof(Record), record_array_mem);

    if (!offsets || !keys || !records) {
        pthread_mutex_unlock(&mutex);
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    // Initialize arrays
    for (size_t i = 0; i < config->long_array_size; ++i) offsets[i] = 0;
    for (size_t i = 0; i < config->int_array_size; ++i) keys[i] = 0;

    srand(config->seed);
    for (size_t i = 0; i < config->record_array_size; ++i)
        records[i].value = rand() % (config->rand_max - config->rand_min + 1) + config->rand_min;

    pthread_mutex_unlock(&mutex);

    // Return a pointer to the allocated memory block
    return malloc(3 * sizeof(void*));
}

// Validation routine to check initialization and no leaks
int validate_memory(void **memory, Config *config) {
    if (!memory) return 0;

    long *offsets = (long *)memory[0];
    int *keys = (int *)memory[1];
    Record *records = (Record *)memory[2];

    for (size_t i = 0; i < config->long_array_size; ++i)
        if (offsets[i] != 0) return 0;

    for (size_t i = 0; i < config->int_array_size; ++i)
        if (keys[i] != 0) return 0;

    for (size_t i = 0; i < config->record_array_size; ++i)
        if (records[i].value < config->rand_min || records[i].value > config->rand_max) return 0;

    return 1;
}

// Function to free allocated memory
void free_memory(void **memory, Config *config) {
    pthread_mutex_lock(&mutex);

    if (!memory) {
        pthread_mutex_unlock(&mutex);
        return;
    }

    long *offsets = (long *)memory[0];
    int *keys = (int *)memory[1];
    Record *records = (Record *)memory[2];

    free(offsets);
    free(keys);
    free(records);

    total_allocated_memory = 0;

    pthread_mutex_unlock(&mutex);
}

// Example usage
int main() {
    Config config = {100, 100, 100, 1, 10, 1024 * 1024, 42};

    void **memory = (void **)allocate_and_initialize(&config);

    if (!validate_memory(memory, &config)) {
        fprintf(stderr, "Validation failed.\n");
        free_memory(memory, &config);
        return EXIT_FAILURE;
    }

    printf("Memory validated successfully.\n");

    free_memory(memory, &config);

    return EXIT_SUCCESS;
}
