['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include "tiffio.h"
#include "logging.h"

typedef struct {
    int bits_per_sample;
    int samples_per_pixel;
    TIFFcompression compression;
    int extra_samples_count;
    int *extra_samples_info;
} TiffImageInfo;

#define ERROR_UNSUPPORTED_BITS_PER_SAMPLE -1
#define ERROR_FILE_CORRUPTED -2
#define ERROR_UNSUPPORTED_COMPRESSION -3

TiffImageInfo parse_tiff_file(const char* filename) {
    TIFF* tif = TIFFOpen(filename, "r");
    TiffImageInfo info = {0};

    if (!tif) {
        log_error("Unable to open TIFF file: %s", filename);
        return (TiffImageInfo){ .bits_per_sample = ERROR_FILE_CORRUPTED };
    }

    if (!TIFFIsTiled(tif)) {
        log_error("Unsupported TIFF format: not tiled.");
        TIFFClose(tif);
        return (TiffImageInfo){ .bits_per_sample = ERROR_FILE_CORRUPTED };
    }

    uint32 samplesPerPixel;
    TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &samplesPerPixel);

    info.samples_per_pixel = samplesPerPixel;

    if (!TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &(info.bits_per_sample))) {
        log_error("Bits per sample not found in TIFF file.");
        TIFFClose(tif);
        return (TiffImageInfo){ .bits_per_sample = ERROR_FILE_CORRUPTED };
    }

    if (!TIFFGetField(tif, TIFFTAG_COMPRESSION, &info.compression)) {
        log_error("Compression method not found in TIFF file.");
        TIFFClose(tif);
        return (TiffImageInfo){ .bits_per_sample = ERROR_UNSUPPORTED_COMPRESSION };
    }

    uint32 photometric;
    if (!TIFFGetField(tif, TIFFTAG_PHOTOMETRIC, &photometric)) {
        log_error("Photometric interpretation not found in TIFF file.");
        TIFFClose(tif);
        return (TiffImageInfo){ .bits_per_sample = ERROR_FILE_CORRUPTED };
    }

    uint32 planarConfig;
    if (!TIFFGetField(tif, TIFFTAG_PLANARCONFIG, &planarConfig) || planarConfig != PLANARCONFIG_CONTIG) {
        log_error("Unsupported planar configuration: not contiguous.");
        TIFFClose(tif);
        return (TiffImageInfo){ .bits_per_sample = ERROR_FILE_CORRUPTED };
    }

    uint16 samplesPerRow;
    if (!TIFFGetField(tif, TIFFTAG_SAMPLESPERROW, &samplesPerRow)) {
        log_error("Samples per row not found in TIFF file.");
        TIFFClose(tif);
        return (TiffImageInfo){ .bits_per_sample = ERROR_FILE_CORRUPTED };
    }

    uint16 rowsPerStrip;
    if (!TIFFGetField(tif, TIFFTAG_ROWSPERSTRIP, &rowsPerStrip)) {
        log_error("Rows per strip not found in TIFF file.");
        TIFFClose(tif);
        return (TiffImageInfo){ .bits_per_sample = ERROR_FILE_CORRUPTED };
    }

    // Check if bits per sample are supported
    if ((info.bits_per_sample != 1 && info.bits_per_sample != 2 &&
         info.bits_per_sample != 4 && info.bits_per_sample != 8 &&
         info.bits_per_sample != 16)) {
        log_error("Unsupported bits per sample: %d", info.bits_per_sample);
        TIFFClose(tif);
        return (TiffImageInfo){ .bits_per_sample = ERROR_UNSUPPORTED_BITS_PER_SAMPLE };
    }

    // Process extra samples
    uint32 extraSamples;
    if (TIFFGetField(tif, TIFFTAG_EXTRASAMPLES, &extraSamples)) {
        info.extra_samples_count = 0;

        for (uint16 i = 0; i < extraSamples / sizeof(uint32); ++i) {
            uint32 sample_info;
            if (TIFFFetchNormalTagData(tif, TIFFTAG_EXTRASAMPLES, i * sizeof(uint32), &sample_info, sizeof(sample_info)) == 1) {
                // Process and store each extra sample information
                info.extra_samples_count++;
            }
        }

        if (info.extra_samples_count > 0) {
            info.extra_samples_info = malloc(info.extra_samples_count * sizeof(int));
            if (!info.extra_samples_info) {
                log_error("Memory allocation failed for extra samples information.");
                TIFFClose(tif);
                return (TiffImageInfo){ .bits_per_sample = ERROR_FILE_CORRUPTED };
            }
        } else {
            info.extra_samples_info = NULL;
        }
    }

    // Close the file and release resources
    if (info.extra_samples_info) free(info.extra_samples_info);

    TIFFClose(tif);

    return info;
}
