['Below is a C program that addresses the described requirements. This example assumes you have basic knowledge of C programming, file I/O operations, dynamic memory management, and multi-threading.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <dirent.h>
#include <sys/types.h>
#include <errno.h>
#include <unistd.h>

#define DEFAULT_THEME_DIR "/default/theme/path"
#define LOG_FILE "processing.log"

typedef struct {
    char *themeBitmap;
} ThemeCacheEntry;

typedef struct {
    pthread_mutex_t lock;
    ThemeCacheEntry **entries;
    size_t capacity;
    size_t size;
} ThemeCache;

void initLog(const char *filePath) {
    FILE *logFile = fopen(filePath, "a");
    if (logFile == NULL) {
        perror("Error opening log file");
        exit(EXIT_FAILURE);
    }
    fclose(logFile);  // Just to ensure the file is created
}

void logMessage(const char *message) {
    FILE *logFile = fopen(LOG_FILE, "a");
    if (logFile != NULL) {
        fprintf(logFile, "%s\n", message);
        fclose(logFile);
    }
}

ThemeCache* createThemeCache(size_t initialCapacity) {
    ThemeCache *cache = (ThemeCache *)malloc(sizeof(ThemeCache));
    cache->lock = PTHREAD_MUTEX_INITIALIZER;
    cache->capacity = initialCapacity;
    cache->size = 0;
    cache->entries = (ThemeCacheEntry **)malloc(initialCapacity * sizeof(ThemeCacheEntry *));
    for (size_t i = 0; i < initialCapacity; ++i) {
        cache->entries[i] = NULL;
    }
    return cache;
}

void addBitmapToCache(ThemeCache *cache, const char *path) {
    pthread_mutex_lock(&cache->lock);

    if (cache->size >= cache->capacity) {
        size_t newCapacity = cache->capacity * 2;
        ThemeCacheEntry **newEntries = realloc(cache->entries, newCapacity * sizeof(ThemeCacheEntry *));

        for (size_t i = cache->capacity; i < newCapacity; ++i) {
            newEntries[i] = NULL;
        }

        if (!newEntries) {
            logMessage("Error reallocating memory for theme cache.");
            pthread_mutex_unlock(&cache->lock);
            return;
        }

        cache->entries = newEntries;
        cache->capacity = newCapacity;
    }

    ThemeCacheEntry *entry = (ThemeCacheEntry *)malloc(sizeof(ThemeCacheEntry));
    entry->themeBitmap = strdup(path); // Simulating loading a bitmap
    if (!entry->themeBitmap) {
        logMessage("Error allocating memory for theme bitmap.");
        free(entry);
        pthread_mutex_unlock(&cache->lock);
        return;
    }

    cache->entries[cache->size++] = entry;

    pthread_mutex_unlock(&cache->lock);
}

void cleanupThemeCache(ThemeCache *cache) {
    pthread_mutex_lock(&cache->lock);

    for (size_t i = 0; i < cache->size; ++i) {
        free(cache->entries[i]->themeBitmap);
        free(cache->entries[i]);
    }

    free(cache->entries);
    pthread_mutex_unlock(&cache->lock);
    pthread_mutex_destroy(&cache->lock);
    free(cache);
}

double calculateAverage(const char *line, size_t startOffset, size_t fieldSize) {
    int values[3];
    for (size_t i = 0; i < 3; ++i) {
        char numStr[fieldSize + 1] = {0};
        strncpy(numStr, line + startOffset + i * fieldSize, fieldSize);
        values[i] = atoi(numStr);
    }
    return (values[0] + values[1] + values[2]) / 3.0;
}

void processLine(const char *line, FILE *outputFile) {
    const size_t lineLength = strlen(line);
    const size_t delimiterOffset = lineLength - 4; // assuming last three numeric fields are the end
    double average = calculateAverage(line, delimiterOffset + 1, 2); // assuming each number is 2 digits

    char *processedLine = (char *)malloc(lineLength + 20);
    if (!processedLine) {
        logMessage("Error allocating memory for processed line.");
        return;
    }

    snprintf(processedLine, lineLength + 20, "%s%.1f\n", line, average);

    fprintf(outputFile, "%s", processedLine);
    free(processedLine);
}

void processFile(const char *inputPath, const char *outputPath) {
    FILE *inputFile = fopen(inputPath, "r");
    if (!inputFile) {
        logMessage("Error opening input file.");
        return;
    }

    FILE *outputFile = fopen(outputPath, "w");
    if (!outputFile) {
        fclose(inputFile);
        logMessage("Error opening output file.");
        return;
    }

    char line[1024];
    while (fgets(line, sizeof(line), inputFile)) {
        processLine(line, outputFile);
    }

    fclose(inputFile);
    fclose(outputFile);
}

void* loadThemesFromDirectory(void *arg) {
    ThemeCache *cache = (ThemeCache *)arg;
    const char *cacheRoot = "/path/to/cache/root";  // Example path
    DIR *dir;
    struct dirent *entry;

    if ((dir = opendir(cacheRoot)) == NULL) {
        logMessage("Error opening cache directory.");
        return NULL;
    }

    while ((entry = readdir(dir)) != NULL) {
        if (strstr(entry->d_name, ".png")) {
            char fullPath[PATH_MAX];
            snprintf(fullPath, sizeof(fullPath), "%s/%s", cacheRoot, entry->d_name);
            addBitmapToCache(cache, fullPath);
        }
    }

    closedir(dir);
    return NULL;
}

int main(int argc, char *argv[]) {
    initLog(LOG_FILE);

    if (argc < 3) {
        logMessage("Usage: program <input-file> <output-file>");
        return EXIT_FAILURE;
    }

    const char *inputPath = argv[1];
    const char *outputPath = argv[2];

    ThemeCache *cache = createThemeCache(10);
    pthread_t themeLoaderThread;

    if (pthread_create(&themeLoaderThread, NULL, loadThemesFromDirectory, cache) != 0) {
        logMessage("Error creating thread for loading themes.");
        cleanupThemeCache(cache);
        return EXIT_FAILURE;
    }

    processFile(inputPath, outputPath);

    pthread_join(themeLoaderThread, NULL);
    cleanupThemeCache(cache);

    return EXIT_SUCCESS;
}
```

### Key Points:
- **Dynamic Memory Management:** The program dynamically allocates memory for processing each line and theme cache entries.
- **Thread Safety:** Uses `pthread_mutex_t` to ensure thread-safe operations on the theme cache.
- **Logging:** Implements a simple logging mechanism to record errors and warnings.
- **Command-line Arguments:** Supports specifying input and output file paths via command-line arguments.
- **Cross-platform Compatibility:** Uses POSIX-compliant functions for directory handling and threading.

This program should be compiled with `-pthread` if using GCC, due to the use of pthreads. Adjust paths and constants as necessary for your specific environment or requirements.']

