} UeSessionInfo;

typedef struct {
    UeSessionInfo** sessions;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock; // For thread safety
} DynamicUeSessionArray;

DynamicUeSessionArray* initDynamicUeSessionArray(size_t initialCapacity) {
    DynamicUeSessionArray* array = malloc(sizeof(DynamicUeSessionArray));
    array->sessions = malloc(initialCapacity * sizeof(UeSessionInfo*));
    array->count = 0;
    array->capacity = initialCapacity;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void resizeDynamicUeSessionArray(DynamicUeSessionArray* array) {
    size_t newCapacity = array->capacity * 2;
    UeSessionInfo** newSessions = realloc(array->sessions, newCapacity * sizeof(UeSessionInfo*));
    if (newSessions) {
        array->sessions = newSessions;
        array->capacity = newCapacity;
    }
}

void addOrUpdateUeSession(DynamicUeSessionArray* array, int ueId, RrcConnectionInfo* rrcTags, size_t rrcCount) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->sessions[i]->ueId == ueId) {
            free(array->sessions[i]->rrcTags);
            array->sessions[i]->rrcTags = malloc(rrcCount * sizeof(RrcConnectionInfo));
            memcpy(array->sessions[i]->rrcTags, rrcTags, rrcCount * sizeof(RrcConnectionInfo));
            array->sessions[i]->rrcCount = rrcCount;
            array->sessions[i]->lastUpdateTimestamp = time(NULL);
            pthread_mutex_unlock(&array->lock);
            return;
        }
    }

    if (array->count == array->capacity) {
        resizeDynamicUeSessionArray(array);
    }

    UeSessionInfo* newSession = malloc(sizeof(UeSessionInfo));
    newSession->ueId = ueId;
    newSession->rrcTags = malloc(rrcCount * sizeof(RrcConnectionInfo));
    memcpy(newSession->rrcTags, rrcTags, rrcCount * sizeof(RrcConnectionInfo));
    newSession->rrcCount = rrcCount;
    newSession->lastUpdateTimestamp = time(NULL);

    array->sessions[array->count++] = newSession;
    pthread_mutex_unlock(&array->lock);
}

UeSessionInfo* getUeSessionByUeId(DynamicUeSessionArray* array, int ueId) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->count; ++i) {
        if (array->sessions[i]->ueId == ueId) {
            pthread_mutex_unlock(&array->lock);
            return array->sessions[i];
        }
    }
    pthread_mutex_unlock(&array->lock);
    return NULL;
}

void cleanupDynamicUeSessionArray(DynamicUeSessionArray* array) {
    for (size_t i = 0; i < array->count; ++i) {
        free(array->sessions[i]->rrcTags);
        free(array->sessions[i]);
    }
    free(array->sessions);
    pthread_mutex_destroy(&array->lock);
    free(array);
}
