        total_size += array->packets[i]->packet_size;
    }

    size_t average_size = (array->count - malformed_count) > 0 ? total_size / (array->count - malformed_count) : 0;
    snprintf(report, 256,
             "Total packets: %zu\n"
             "Average packet size: %zu\n"
             "Malformed packets discarded: %zu",
             array->count, average_size, malformed_count);
}

