        fprintf(stderr, "Failed to initialize packet array.\n");
        return EXIT_FAILURE;
    }

    pthread_t receive_thread, limit_thread;

    pthread_create(&receive_thread, NULL, receive_packets, packet_array);
    pthread_create(&limit_thread, NULL, limit_packets, packet_array);

    sleep(10); // Run for a certain duration

    packet_array->stop_flag = 1;
    pthread_join(receive_thread, NULL);
    pthread_join(limit_thread, NULL);

    char report[256];
    get_summary_report(packet_array, report);
    printf("%s", report);

    cleanup_packet_array(packet_array);

    return EXIT_SUCCESS;
}
