#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define VALUE_RANGE_MIN 0
#define VALUE_RANGE_MAX 1000000

typedef struct Record {
    int key;
    long value;
} Record;

typedef struct CacheNode {
    int key;
    long value;
    unsigned int freq; // Frequency of access
    time_t last_access_time; // Time of the last access
    struct CacheNode* prev;
    struct CacheNode* next;
} CacheNode;

typedef struct LRUCache {
    int capacity;
    CacheNode* head;
    CacheNode* tail;
    pthread_mutex_t lock;
} LRUCache;

// Function prototypes
void initializeCache(LRUCache** cache, int initial_capacity);
long getValue(LRUCache* cache, int key);
void setValue(LRUCache* cache, int key, long value);
void resizeCache(LRUCache** cache, int new_capacity);
void freeCache(LRUCache* cache);

// Logging mechanism
typedef struct Log {
    char message[256];
    struct Log* next;
} Log;

Log* log_head = NULL;
pthread_mutex_t log_lock;

void asyncLog(const char* msg) {
    pthread_mutex_lock(&log_lock);
    Log* new_log = (Log*)malloc(sizeof(Log));
    if (!new_log) return; // Handle allocation failure gracefully
    strncpy(new_log->message, msg, sizeof(new_log->message) - 1);
    new_log->next = log_head;
    log_head = new_log;
    pthread_mutex_unlock(&log_lock);
}

// Separate logging thread function
void* logWriter(void* arg) {
    while (1) { // Loop indefinitely or until signaled to stop
        pthread_mutex_lock(&log_lock);
        Log* current = log_head;
        if (current != NULL) {
            printf("%s\n", current->message); // Replace with actual logging mechanism
            log_head = current->next;
            free(current);
        }
        pthread_mutex_unlock(&log_lock);
        usleep(100000); // Sleep for 100ms or a suitable interval
    }
    return NULL;
}

// Cache operations

void initializeCache(LRUCache** cache, int initial_capacity) {
    *cache = (LRUCache*)malloc(sizeof(LRUCache));
    if (!*cache) {
        fprintf(stderr, "Failed to allocate memory for LRUCache\n");
        exit(EXIT_FAILURE);
    }
    (*cache)->capacity = initial_capacity;
    (*cache)->head = NULL;
    (*cache)->tail = NULL;
    pthread_mutex_init(&(*cache)->lock, NULL);

    // Start logging thread
    pthread_t log_thread;
    pthread_create(&log_thread, NULL, logWriter, NULL);
}

long getValue(LRUCache* cache, int key) {
    pthread_mutex_lock(&cache->lock);
    CacheNode* current = cache->head;
    while (current != NULL) {
        if (current->key == key) {
            current->freq++;
            current->last_access_time = time(NULL);
            pthread_mutex_unlock(&cache->lock);
            return current->value;
        }
        current = current->next;
    }

    // If not found, simulate a cache miss
    asyncLog("Cache miss for key: %d", key);

    pthread_mutex_unlock(&cache->lock);
    return -1; // Indicate that the value was not found in the cache
}

void setValue(LRUCache* cache, int key, long value) {
    if (value < VALUE_RANGE_MIN || value > VALUE_RANGE_MAX) {
        fprintf(stderr, "Value out of range\n");
        return;
    }

    pthread_mutex_lock(&cache->lock);

    CacheNode* current = cache->head;
    while (current != NULL) {
        if (current->key == key) {
            current->value = value;
            current->freq++;
            current->last_access_time = time(NULL);
            pthread_mutex_unlock(&cache->lock);
            return;
        }
        current = current->next;
    }

    // If not found, add to cache
    if (cache->head == NULL || cache->tail == NULL) {
        CacheNode* new_node = (CacheNode*)malloc(sizeof(CacheNode));
        if (!new_node) {
            fprintf(stderr, "Failed to allocate memory for CacheNode\n");
            pthread_mutex_unlock(&cache->lock);
            return;
        }
        new_node->key = key;
        new_node->value = value;
        new_node->freq = 1;
        new_node->last_access_time = time(NULL);
        new_node->prev = NULL;
        new_node->next = NULL;

        cache->head = new_node;
        cache->tail = new_node;
    } else {
        if (cache->capacity > 0) {
            CacheNode* new_node = (CacheNode*)malloc(sizeof(CacheNode));
            if (!new_node) {
                fprintf(stderr, "Failed to allocate memory for CacheNode\n");
                pthread_mutex_unlock(&cache->lock);
                return;
            }
            new_node->key = key;
            new_node->value = value;
            new_node->freq = 1;
            new_node->last_access_time = time(NULL);

            cache->tail->next = new_node;
            new_node->prev = cache->tail;
            cache->tail = new_node;

            if (cache->capacity == 1) {
                CacheNode* old_head = cache->head;
                cache->head = cache->head->next;
                if (cache->head != NULL) cache->head->prev = NULL;
                free(old_head);
                cache->capacity--;
            } else {
                cache->capacity--;
            }
        } else {
            asyncLog("Cache is full, consider resizing or eviction policy");
            pthread_mutex_unlock(&cache->lock);
            return;
        }
    }

    pthread_mutex_unlock(&cache->lock);
}

void resizeCache(LRUCache** cache, int new_capacity) {
    if (new_capacity <= 0) return;

    pthread_mutex_lock(&(*cache)->lock);

    // Resize logic: Adjust capacity
    (*cache)->capacity = new_capacity;
    asyncLog("Resized cache to new capacity: %d", new_capacity);

    pthread_mutex_unlock(&(*cache)->lock);
}

void freeCache(LRUCache* cache) {
    CacheNode* current = cache->head;
    while (current != NULL) {
        CacheNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&cache->lock);
    free(cache);

    // Clean up logs
    pthread_mutex_lock(&log_lock);
    Log* current_log = log_head;
    while (current_log != NULL) {
        Log* next_log = current_log->next;
        free(current_log);
        current_log = next_log;
    }
    log_head = NULL;
    pthread_mutex_unlock(&log_lock);
}

// Unit tests and main function omitted for brevity
