#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef enum { ACTIVE, INACTIVE } TaskStatus;

typedef struct {
    int id;
    int priority;
    TaskStatus status;
} Task;

typedef struct task_node {
    Task task;
    struct task_node* next;
} TaskNode;

typedef struct {
    int id;
    TaskNode* tasks_head;
    pthread_mutex_t lock; // Mutex for thread safety
} Workspace;

#define CACHE_SIZE 10

// Cache structure to store frequently accessed workspaces
typedef struct {
    Workspace** cache;
    int size;
    int capacity;
} Cache;

Cache workspace_cache;

void init_workspace(Workspace* ws, int id) {
    pthread_mutex_init(&ws->lock, NULL);
    ws->id = id;
    ws->tasks_head = NULL;
}

void add_task(Workspace* ws, Task task) {
    TaskNode* new_node = (TaskNode*)malloc(sizeof(TaskNode));
    if (!new_node) return; // Handle allocation failure
    new_node->task = task;
    new_node->next = NULL;

    pthread_mutex_lock(&ws->lock);
    new_node->next = ws->tasks_head;
    ws->tasks_head = new_node;
    pthread_mutex_unlock(&ws->lock);

    // Log the operation (simplified)
    printf("Task added to workspace %d: ID=%d, Priority=%d\n", ws->id, task.id, task.priority);
}

void remove_task(Workspace* ws, int task_id) {
    pthread_mutex_lock(&ws->lock);
    TaskNode *current = ws->tasks_head, *prev = NULL;

    while (current != NULL && current->task.id != task_id) {
        prev = current;
        current = current->next;
    }

    if (current != NULL) {
        if (prev == NULL)
            ws->tasks_head = current->next;
        else
            prev->next = current->next;

        free(current);

        // Log the operation
        printf("Task removed from workspace %d: ID=%d\n", ws->id, task_id);
    }

    pthread_mutex_unlock(&ws->lock);
}

TaskNode* get_task(Workspace* ws, int task_id) {
    pthread_mutex_lock(&ws->lock);
    TaskNode* current = ws->tasks_head;

    while (current != NULL && current->task.id != task_id) {
        current = current->next;
    }

    pthread_mutex_unlock(&ws->lock);

    return current; // NULL if not found
}

Workspace* create_workspace(int id) {
    Workspace* ws = (Workspace*)malloc(sizeof(Workspace));
    if (!ws) return NULL;

    init_workspace(ws, id);
    return ws;
}

void destroy_workspace(Workspace* ws) {
    TaskNode *current = ws->tasks_head, *next_node;

    while (current != NULL) {
        next_node = current->next;
        free(current);
        current = next_node;
    }

    pthread_mutex_destroy(&ws->lock);
    free(ws);
}

void init_cache(int capacity) {
    workspace_cache.cache = (Workspace**)malloc(sizeof(Workspace*) * capacity);
    workspace_cache.size = 0;
    workspace_cache.capacity = capacity;

    for (int i = 0; i < capacity; ++i)
        workspace_cache.cache[i] = NULL;
}

Workspace* get_cached_workspace(int id) {
    for (int i = 0; i < workspace_cache.size; ++i) {
        if (workspace_cache.cache[i]->id == id) {
            // Move accessed item to front (simple LRU strategy)
            Workspace* temp = workspace_cache.cache[i];
            for (int j = i; j > 0; --j)
                workspace_cache.cache[j] = workspace_cache.cache[j - 1];
            workspace_cache.cache[0] = temp;

            return temp;
        }
    }
    return NULL;
}

void cache_workspace(Workspace* ws) {
    if (workspace_cache.size >= workspace_cache.capacity) {
        // Evict the least recently used item
        free(workspace_cache.cache[workspace_cache.capacity - 1]);
        for (int i = workspace_cache.capacity - 1; i > 0; --i)
            workspace_cache.cache[i] = workspace_cache.cache[i - 1];
    }

    workspace_cache.cache[0] = ws;
    for (int i = workspace_cache.size; i > 0; --i)
        workspace_cache.cache[i] = workspace_cache.cache[i - 1];

    workspace_cache.size++;
}

void cleanup_cache() {
    for (int i = 0; i < workspace_cache.size; ++i) {
        if (workspace_cache.cache[i])
            destroy_workspace(workspace_cache.cache[i]);
    }
    free(workspace_cache.cache);
}

// Entry point to initialize the system
int main() {
    init_cache(CACHE_SIZE);

    Workspace* ws1 = create_workspace(1);
    Task task1 = { .id = 101, .priority = 5, .status = ACTIVE };

    add_task(ws1, task1);

    // Caching example
    cache_workspace(ws1);

    TaskNode* found_task = get_task(ws1, 101);
    if (found_task)
        printf("Task found: ID=%d, Priority=%d\n", found_task->task.id, found_task->task.priority);

    remove_task(ws1, 101);
    destroy_workspace(ws1);

    cleanup_cache();
    return 0;
}
