```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int weight;
} record;

#define MAX_VERTICES 1000
#define MAX_EDGES 5000
#define WEIGHT_RANGE_MIN 1
#define WEIGHT_RANGE_MAX 100

typedef struct {
    long *offsets; // Unique offsets for vertices
    int *keys;     // Unique identifiers with limited space
    record *edges; // Array of edge records
    int num_vertices;
    int num_edges;
} Graph;

void initialize_random() {
    srand(time(NULL));
}

Graph* create_graph(int max_vertices, int max_edges) {
    if (max_vertices <= 0 || max_vertices > MAX_VERTICES || max_edges <= 0 || max_edges > MAX_EDGES)
        return NULL;

    Graph *graph = malloc(sizeof(Graph));
    if (!graph) return NULL;

    graph->offsets = calloc(max_vertices, sizeof(long));
    graph->keys = calloc(max_vertices, sizeof(int));
    graph->edges = calloc(max_edges, sizeof(record));

    if (!graph->offsets || !graph->keys || !graph->edges) {
        free(graph->offsets);
        free(graph->keys);
        free(graph->edges);
        free(graph);
        return NULL;
    }

    initialize_random();
    for (int i = 0; i < max_vertices; ++i) {
        graph->offsets[i] = rand() % MAX_VERTICES + 1;
        graph->keys[i] = rand() % MAX_VERTICES + 1;
    }

    int edge_count = rand() % max_edges;
    for (int i = 0; i < edge_count; ++i) {
        graph->edges[i].weight = WEIGHT_RANGE_MIN + rand() % (WEIGHT_RANGE_MAX - WEIGHT_RANGE_MIN + 1);
    }

    graph->num_vertices = max_vertices;
    graph->num_edges = edge_count;

    return graph;
}

void free_graph(Graph *graph) {
    if (!graph) return;
    free(graph->offsets);
    free(graph->keys);
    free(graph->edges);
    free(graph);
}

int add_vertex(Graph *graph, long offset, int key) {
    if (graph->num_vertices >= MAX_VERTICES) return -1;

    graph->offsets[graph->num_vertices] = offset;
    graph->keys[graph->num_vertices] = key;
    graph->num_vertices++;

    return 0;
}

int add_edge(Graph *graph, int weight) {
    if (graph->num_edges >= MAX_EDGES) return -1;

    graph->edges[graph->num_edges].weight = weight;
    graph->num_edges++;

    return 0;
}

// Example usage
int main() {
    Graph *graph = create_graph(10, 20);
    if (!graph) {
        fprintf(stderr, "Failed to create graph\n");
        return EXIT_FAILURE;
    }

    add_vertex(graph, 12345, 67890);
    add_edge(graph, 42);

    free_graph(graph);
    return EXIT_SUCCESS;
}
```

