use std::process::{Command, Stdio};
use std::time::{Duration, Instant};
use sysinfo::{System, ProcessExt};
use sync_lazy::SyncLazy;

fn get_resident_set_size(pid: i32) -> u64 {
    let system = System::new_all();
    match system.get_process(pid) {
        Some(process) => process.rss(),
        None => 0,
    }
}

#[sync_lazy::sync_lazy]
static LOG_HOOK: Option<SyncLazy<dyn Fn(&str)>> = None;

fn main() -> i32 {
    let compile_start_time = Instant::now();
    let start_rss = get_resident_set_size(getpid());

    rustc_driver::catch_with_exit_code(move || {
        // Set up logging hook
        LOG_HOOK = Some(SyncLazy::new(|| {
            move |message: &str| println!("Log: {}", message)
        }));

        if let Err(e) = setup_logging_hook() {
            eprintln!("Failed to set up logging hook: {:?}", e);
            std::process::exit(1);
        }

        let output = Command::new("rustc")
            .arg("--crate-type=lib") // Example arguments
            .stdout(Stdio::null())
            .stderr(Stdio::inherit())
            .spawn()
            .expect("Failed to spawn rustc");

        match output.wait_with_output() {
            Ok(output) => {
                if !output.status.success() {
                    eprintln!("Compilation failed");
                }
            },
            Err(e) => eprintln!("Failed to execute process: {:?}", e),
        }

    }).unwrap_or_else(|e| {
        println!("Error during compilation: {}", e);
        1
    });

    let compile_end_time = Instant::now();
    let end_rss = get_resident_set_size(getpid());

    println!("Compilation time: {} ms", compile_start_time.elapsed().as_millis());
    println!("Memory usage change (RSS): {} KB", (end_rss - start_rss) / 1024);

    // Example of how you might use the logging hook
    if let Some(ref logger) = LOG_HOOK {
        logger("This is a log message.");
    }

    0
}
