    atomic_store(&list->successful_creations, 0);
    atomic_store(&list->failed_allocations, 0);
    pthread_mutex_init(&list->mutex, NULL);
}

// Function to resize the list if necessary
static void nfaapi_crc_list_resize(NFAPI_CRC_LIST *list) {
    size_t new_capacity = list->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_elements = realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_elements == NULL) {
        atomic_fetch_add(&list->failed_allocations, 1);
        return; // Handle resize failure gracefully
    }
    list->capacity = new_capacity;
    list->elements = new_elements;
}

// Function to simulate probabilistic CRCFLAG setting
