    memcpy(&element->rx_ue_information, rx_ue_info, sizeof(RX_UE_INFORMATION));
    set_crc_flag_probabilistically(&element->crc_indication_rel8_tag);

    list->count++;
    atomic_fetch_add(&list->successful_creations, 1);

