['Below is a C code implementation for managing a dynamic, multi-threaded cache system as described:

```c
#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <stdbool.h>

// Define the NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Cache entry
typedef struct cache_entry {
    int key;
    NFAPI_CRC_INDICATION_PDU_T value;
    int frequency; // For LFU strategy
    bool is_valid;
    pthread_mutex_t lock;
    struct cache_entry* next;
    struct cache_entry* prev;
} cache_entry;

// Cache structure
typedef struct {
    cache_entry** entries;
    int capacity;
    int size;
    pthread_mutex_t resize_lock;
    pthread_rwlock_t rwlock;
    int hit_count;
    int miss_count;
    // Add configuration parameters as needed
} cache_system;

// Function prototypes
cache_system* init_cache(int initial_capacity, int cache_size);
void destroy_cache(cache_system* cache);
NFAPI_CRC_INDICATION_PDU_T* get_record(cache_system* cache, int key);
bool set_record(cache_system* cache, int key, NFAPI_CRC_INDICATION_PDU_T value);
void resize_cache(cache_system* cache);

// Initialize the cache system
cache_system* init_cache(int initial_capacity, int cache_size) {
    cache_system* cache = (cache_system*)malloc(sizeof(cache_system));
    if (!cache) return NULL;

    cache->entries = (cache_entry**)calloc(initial_capacity, sizeof(cache_entry*));
    if (!cache->entries) {
        free(cache);
        return NULL;
    }

    cache->capacity = initial_capacity;
    cache->size = 0;
    pthread_mutex_init(&cache->resize_lock, NULL);
    pthread_rwlock_init(&cache->rwlock, NULL);

    for (int i = 0; i < initial_capacity; ++i) {
        cache->entries[i] = NULL;
    }

    // Initialize other fields as necessary
    return cache;
}

// Destroy the cache system and free resources
void destroy_cache(cache_system* cache) {
    if (!cache) return;

    for (int i = 0; i < cache->capacity; ++i) {
        cache_entry* entry = cache->entries[i];
        while (entry) {
            cache_entry* next = entry->next;
            pthread_mutex_destroy(&entry->lock);
            free(entry);
            entry = next;
        }
    }

    free(cache->entries);
    pthread_mutex_destroy(&cache->resize_lock);
    pthread_rwlock_destroy(&cache->rwlock);
    free(cache);
}

// Retrieve a record from the cache
NFAPI_CRC_INDICATION_PDU_T* get_record(cache_system* cache, int key) {
    if (!cache) return NULL;

    pthread_rwlock_rdlock(&cache->rwlock);

    int index = key % cache->capacity;
    cache_entry* entry = cache->entries[index];
    while (entry && entry->is_valid) {
        if (entry->key == key) {
            pthread_mutex_lock(&entry->lock);
            entry->frequency++;
            pthread_rwlock_unlock(&cache->rwlock);
            return &entry->value;
        }
        entry = entry->next;
    }

    cache->miss_count++;
    pthread_rwlock_unlock(&cache->rwlock);

    // Resize if necessary
    resize_cache(cache);

    return NULL;
}

// Set a record in the cache
bool set_record(cache_system* cache, int key, NFAPI_CRC_INDICATION_PDU_T value) {
    if (!cache) return false;

    pthread_rwlock_wrlock(&cache->rwlock);

    // Check for existing entry
    int index = key % cache->capacity;
    cache_entry* entry = cache->entries[index];
    while (entry && entry->is_valid) {
        if (entry->key == key) {
            pthread_mutex_lock(&entry->lock);
            entry->value = value;
            entry->frequency++;
            pthread_rwlock_unlock(&cache->rwlock);
            return true;
        }
        entry = entry->next;
    }

    // Create a new entry
    if (cache->size >= cache->capacity) {
        resize_cache(cache);
    }

    cache_entry* new_entry = (cache_entry*)malloc(sizeof(cache_entry));
    if (!new_entry) {
        pthread_rwlock_unlock(&cache->rwlock);
        return false;
    }

    pthread_mutex_init(&new_entry->lock, NULL);

    new_entry->key = key;
    new_entry->value = value;
    new_entry->frequency = 1;
    new_entry->is_valid = true;
    new_entry->next = cache->entries[index];
    cache->entries[index] = new_entry;

    cache->size++;
    pthread_rwlock_unlock(&cache->rwlock);

    return true;
}

// Resize the cache
void resize_cache(cache_system* cache) {
    pthread_mutex_lock(&cache->resize_lock);

    int old_capacity = cache->capacity;
    int new_capacity = 2 * old_capacity;

    cache_entry** new_entries = (cache_entry**)calloc(new_capacity, sizeof(cache_entry*));
    if (!new_entries) {
        pthread_mutex_unlock(&cache->resize_lock);
        return;
    }

    for (int i = 0; i < new_capacity; ++i) {
        new_entries[i] = NULL;
    }

    // Rehash entries
    for (int i = 0; i < old_capacity; ++i) {
        cache_entry* entry = cache->entries[i];
        while (entry) {
            int index = entry->key % new_capacity;
            cache_entry* next = entry->next;

            entry->next = new_entries[index];
            new_entries[index] = entry;

            entry = next;
        }
    }

    free(cache->entries);
    cache->entries = new_entries;
    cache->capacity = new_capacity;

    pthread_mutex_unlock(&cache->resize_lock);
}

// Unit tests
void test_cache() {
    // Initialize cache
