#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_POOL_SIZE 10

typedef struct {
    char ip_address[16];
    int port;
    int status; // Example: 0 for inactive, 1 for active
    uint64_t packet_count;
    double average_latency; // in milliseconds
} NetworkConnection;

typedef struct Node {
    NetworkConnection conn;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    pthread_mutex_t lock;
} ConnectionPool;

void init_pool(ConnectionPool* pool) {
    pool->head = NULL;
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

Node* create_node(const NetworkConnection* conn) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    memcpy(&new_node->conn, conn, sizeof(NetworkConnection));
    new_node->next = NULL;
    return new_node;
}

void add_connection(ConnectionPool* pool, const NetworkConnection* conn) {
    pthread_mutex_lock(&pool->lock);

    Node* new_node = create_node(conn);
    if (!new_node) {
        printf("Memory allocation failed\n");
        pthread_mutex_unlock(&pool->lock);
        return;
    }

    new_node->next = pool->head;
    pool->head = new_node;
    pool->count++;

    pthread_mutex_unlock(&pool->lock);
}

void remove_connection(ConnectionPool* pool, const char* ip_address) {
    pthread_mutex_lock(&pool->lock);

    Node **indirect = &pool->head;
    while (*indirect && strcmp((*indirect)->conn.ip_address, ip_address) != 0) {
        indirect = &(*indirect)->next;
    }

    if (*indirect) {
        Node* to_delete = *indirect;
        *indirect = (*indirect)->next;
        free(to_delete);
        pool->count--;
    }

    pthread_mutex_unlock(&pool->lock);
}

void update_connection(ConnectionPool* pool, const char* ip_address, int packet_count_delta, double latency) {
    pthread_mutex_lock(&pool->lock);

    Node *current = pool->head;
    while (current) {
        if (strcmp(current->conn.ip_address, ip_address) == 0) {
            current->conn.packet_count += packet_count_delta;
            // Update average latency
            current->conn.average_latency = ((current->conn.average_latency * current->conn.packet_count) + 
                                             (latency * packet_count_delta)) / (current->conn.packet_count);
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&pool->lock);
}

void free_pool(ConnectionPool* pool) {
    pthread_mutex_lock(&pool->lock);

    Node* current = pool->head;
    while (current) {
        Node* next_node = current->next;
        free(current);
        current = next_node;
    }

    pool->head = NULL;
    pool->count = 0;

    pthread_mutex_unlock(&pool->lock);
    pthread_mutex_destroy(&pool->lock);
}

// Serialization and Deserialization (simple example)
void serialize_pool(const ConnectionPool* pool, FILE *file) {
    pthread_mutex_lock((pthread_mutex_t*)&pool->lock);

    Node* current = pool->head;
    while (current) {
        fwrite(&current->conn, sizeof(NetworkConnection), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock((pthread_mutex_t*)&pool->lock);
}

void deserialize_pool(ConnectionPool* pool, FILE *file) {
    NetworkConnection conn;

    while (fread(&conn, sizeof(NetworkConnection), 1, file)) {
        add_connection(pool, &conn);
    }
}
