    if (!list) return NULL;

    list->array = calloc(INITIAL_CAPACITY, sizeof(Node*));
    if (!list->array) {
        free(list);
        return NULL;
    }

    for (size_t i = 0; i < INITIAL_CAPACITY; ++i) {
        atomic_store(&((list->array)[i]), NULL);
    }

    list->capacity = INITIAL_CAPACITY;
    list->count = 0;
    pthread_mutex_init(&list->resize_lock, NULL);

    return list;
}

void free_list(ConcurrentList* list) {
    for (size_t i = 0; i < list->capacity; ++i) {
        Node* node = atomic_load(&list->array[i]);
        while (node) {
            Node* next = atomic_load(&node->next);
            free(node);
            node = next;
        }
    }
    free(list->array);
    pthread_mutex_destroy(&list->resize_lock);
    free(list);
}

static void resize(ConcurrentList* list) {
    size_t new_capacity = list->capacity * 2;
    Node** new_array = calloc(new_capacity, sizeof(Node*));
    if (!new_array) return;

    for (size_t i = 0; i < new_capacity; ++i) {
        atomic_store(&new_array[i], NULL);
    }

    pthread_mutex_lock(&list->resize_lock);
    // Double-check locking
    if (list->capacity == list->array[0].capacity) { 
        free(list->array);

        for (size_t i = 0; i < list->count; ++i) {
            Node* node = atomic_load(&list->array[i % list->capacity]);
            while (node) {
                size_t idx = hash_function(node, new_capacity);
                Node* next = atomic_load(&node->next);

                do {
                    Node* current = atomic_load(&new_array[idx]);
                    node->next = current;
                } while (!atomic_compare_exchange_weak(&new_array[idx], &current, node));

                node = next;
            }
        }

        list->array = new_array;
        list->capacity = new_capacity;
    }
    pthread_mutex_unlock(&list->resize_lock);
}

void insert(ConcurrentList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    resize(list);

