#define MAX_ENTRIES 10000

typedef struct {
    char *name;
    int priority;
} Entry;

typedef struct {
    Entry *entries[MAX_ENTRIES];
    size_t count;
    pthread_mutex_t lock;
} EntryManager;

typedef struct {
