    pthread_mutex_t log_lock;
    pthread_cond_t cond_var;
    int running;
} ServiceThreadData;

void init_entry_manager(EntryManager *manager) {
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

void destroy_entry_manager(EntryManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->entries[i]->name);
        free(manager->entries[i]);
    }
    pthread_mutex_destroy(&manager->lock);
}

int add_entry(EntryManager *manager, char *name, int priority) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= MAX_ENTRIES) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    Entry *entry = malloc(sizeof(Entry));
    entry->name = strdup(name);
    entry->priority = priority;

    manager->entries[manager->count++] = entry;

    // Sort entries by priority
    for (size_t i = manager->count; i > 0 && manager->entries[i - 1]->priority > priority; --i) {
        Entry *temp = manager->entries[i];
        manager->entries[i] = manager->entries[i - 1];
        manager->entries[i - 1] = temp;
    }

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int remove_entry(EntryManager *manager, char *name) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->entries[i]->name, name) == 0) {
            free(manager->entries[i]->name);
            free(manager->entries[i]);

            // Shift remaining entries
            memmove(&manager->entries[i], &manager->entries[i + 1], sizeof(Entry *) * (manager->count - i - 1));
            manager->count--;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1;
}

int search_entry(EntryManager *manager, char *name) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->entries[i]->name, name) == 0) {
            return i;
        }
    }
    return -1;
}

