}

void health_check(EntryManager *manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count - 1; ++i) {
        if (manager->entries[i]->priority > manager->entries[i + 1]->priority) {
            printf("Memory corruption detected!\n");
