```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

#define INITIAL_CAPACITY 10

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements;
    size_t capacity;
    atomic_size_t count;
    pthread_mutex_t lock; // Mutex for thread-safe operations
} CRCList;

// Function to initialize the list
CRCList* create_crc_list(size_t initial_capacity) {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;

    list->elements = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->elements) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    atomic_init(&list->count, 0);

    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Function to resize the list
bool resize_crc_list(CRCList* list, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_elements = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_elements) return false;

    list->elements = new_elements;
    list->capacity = new_capacity;
    return true;
}

// Function to add an element to the list
bool add_crc_pdu(CRCList* list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&list->lock);

    if (atomic_load(&list->count) >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        bool resized = resize_crc_list(list, new_capacity);
        if (!resized) {
            pthread_mutex_unlock(&list->lock);
            return false;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = &list->elements[atomic_fetch_add(&list->count, 1)];
    pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu->RNTI = RNTI;
    pdu->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;

    // Probabilistic algorithm to set CRCFLAG
    srand(time(NULL) + pthread_self());
    pdu->CRCFLAG = (rand() % 10 < 7); // Example probability

    pthread_mutex_unlock(&list->lock);
    return true;
}

// Function to update CRCFLAG from an external source
void* periodic_update(void* arg) {
    CRCList* list = (CRCList*)arg;
    while (true) {
        pthread_mutex_lock(&list->lock);

        for (size_t i = 0; i < atomic_load(&list->count); ++i) {
            // Simulate latency
            usleep(1000);
            list->elements[i].CRCFLAG = !list->elements[i].CRCFLAG;
        }

        pthread_mutex_unlock(&list->lock);
        sleep(5); // Update every 5 seconds
    }
    return NULL;
}

// Function to gracefully handle spikes in load
void* stress_test(void* arg) {
    CRCList* list = (CRCList*)arg;

    for (int i = 0; i < 1000; ++i) {
        add_crc_pdu(list, rand() % 100, rand() % 100, rand() % 100);
    }
    return NULL;
}

// Function to free the list
void destroy_crc_list(CRCList* list) {
    if (list) {
        pthread_mutex_destroy(&list->lock);
        free(list->elements);
        free(list);
    }
}

int main() {
    CRCList* list = create_crc_list(INITIAL_CAPACITY);
    if (!list) return 1;

    pthread_t update_thread, stress_thread;
    pthread_create(&update_thread, NULL, periodic_update, list);
    pthread_create(&stress_thread, NULL, stress_test, list);

    // Wait for threads to finish
    pthread_join(update_thread, NULL);
    pthread_join(stress_thread, NULL);

    destroy_crc_list(list);
    return 0;
}
