    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->data_objects[i]->resource);
        free(collection->data_objects[i]);
    }
    free(collection->data_objects);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

// Add a new data object
int add_data_object(DataCollection *collection, Resource *resource) {
    if (!collection || !resource) return -1;

    pthread_mutex_lock(&collection->lock);

    if (collection->count == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        DataObject **new_array = (DataObject**)realloc(collection->data_objects, new_capacity * sizeof(DataObject*));
        if (!new_array) {
            pthread_mutex_unlock(&collection->lock);
            return -1;
        }
        collection->data_objects = new_array;
        collection->capacity = new_capacity;
    }

    DataObject *object = (DataObject*)malloc(sizeof(DataObject));
    if (!object) {
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    object->timestamp = time(NULL);
    object->status_flag = 0; // Default status
    object->resource = resource;

    collection->data_objects[collection->count++] = object;
    update_status_flag(object);

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

// Update the status flag of a data object
void update_status_flag(DataObject *object) {
    if (!object) return;

    // Example condition: set status to 1 if resource size is greater than 100
    if (object->resource->size > 100) {
        object->status_flag = 1;
    } else {
        object->status_flag = 0;
    }
}

// Serialize a data object
void serialize_data_object(const DataObject *object, char **serialized_data, size_t *size) {
    if (!object || !serialized_data || !size) return;

    // Example serialization logic
    const size_t estimated_size = sizeof(object->timestamp) + sizeof(object->status_flag) + strlen(object->resource->type) + 1 + sizeof(object->resource->size);
    *serialized_data = (char*)malloc(estimated_size);
    if (!*serialized_data) return;

    char *ptr = *serialized_data;
    memcpy(ptr, &object->timestamp, sizeof(object->timestamp));
    ptr += sizeof(object->timestamp);

    memcpy(ptr, &object->status_flag, sizeof(object->status_flag));
    ptr += sizeof(object->status_flag);

    strcpy(ptr, object->resource->type);
    ptr += strlen(object->resource->type) + 1;

    memcpy(ptr, &(object->resource->size), sizeof(object->resource->size));

    *size = estimated_size;
}

// Deserialize a data object
DataObject* deserialize_data_object(const char *data, size_t size) {
    if (!data || size < (sizeof(time_t) + sizeof(int) + 50 + 1 + sizeof(size_t))) return NULL;

    const char *ptr = data;
    time_t timestamp;
    int status_flag;
    char type[51];
    size_t resource_size;

    memcpy(&timestamp, ptr, sizeof(timestamp));
    ptr += sizeof(timestamp);

    memcpy(&status_flag, ptr, sizeof(status_flag));
    ptr += sizeof(status_flag);

    strncpy(type, ptr, 50);
    ptr += strlen(ptr) + 1;

    memcpy(&resource_size, ptr, sizeof(resource_size));

    Resource *resource = (Resource*)malloc(sizeof(Resource));
    if (!resource) return NULL;

    strcpy(resource->type, type);
    resource->size = resource_size;

    DataObject *object = (DataObject*)malloc(sizeof(DataObject));
    if (!object) {
        free(resource);
        return NULL;
    }

    object->timestamp = timestamp;
    object->status_flag = status_flag;
    object->resource = resource;

    return object;
}

// Update a resource via API
int update_resource_via_api(DataCollection *collection, const char *id, const char *request_body) {
    if (!collection || !id || !request_body) return -1;

    pthread_mutex_lock(&collection->lock);

    // Example: find and update the object with the matching ID
    for (size_t i = 0; i < collection->count; ++i) {
        DataObject *object = collection->data_objects[i];
        if (strcmp(object->resource->type, id) == 0) {
            // Update logic here, e.g., parse request_body and update object's resource
            update_status_flag(object);
            pthread_mutex_unlock(&collection->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return -1;
}

// Delete a resource via API
void delete_resource_via_api(DataCollection *collection, const char *id) {
    if (!collection || !id) return;

    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        DataObject *object = collection->data_objects[i];
        if (strcmp(object->resource->type, id) == 0) {
            free(object->resource);
            free(object);
            memmove(&collection->data_objects[i], &collection->data_objects[i + 1], (collection->count - i - 1) * sizeof(DataObject*));
            collection->count--;
            pthread_mutex_unlock(&collection->lock);
            return;
        }
    }

    pthread_mutex_unlock(&collection->lock);
}

// Initialize a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* initialize_nfa_crc_indication_list(size_t count) {
    if (count > 10000) count = 10000;

    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T*)calloc(count, sizeof(NFAPI_CRC_INDICATION_PDU_T));
