}

int main() {
    // Example usage
    DataCollection *collection = initialize_data_collection();
    if (!collection) {
        fprintf(stderr, "Failed to initialize data collection\n");
        return EXIT_FAILURE;
    }

    Resource resource1 = {"TypeA", 150};
    add_data_object(collection, &resource1);

    char *serialized_data;
    size_t serialized_size;
    serialize_data_object(collection->data_objects[0], &serialized_data, &serialized_size);
    DataObject *deserialized_object = deserialize_data_object(serialized_data, serialized_size);
    free(serialized_data);

    delete_resource_via_api(collection, "TypeA");

    NFAPI_CRC_INDICATION_PDU_T *crc_list = initialize_nfa_crc_indication_list(5000);
    if (crc_list) {
        // Use crc_list
        free(crc_list);
    }

    free_data_collection(collection);
    return EXIT_SUCCESS;
}
