typedef struct {
    int id;
    double min;
    double max;
    double sum;
    int count;  // To calculate average later
} ItemSummary;

// Function to dynamically allocate and manage memory for items and their summaries
void processItemsBatch(Item **items, size_t *itemCount, ItemSummary **summaries, 
                       size_t summaryCount, const char *batch[], size_t batchSize,
                       double maxMemoryUsage) {
    // Allocate initial memory for items
    *items = malloc(batchSize * sizeof(Item));
    if (*items == NULL) {
        fprintf(stderr, "Failed to allocate memory for items.\n");
        return;
    }

    // Process each item in the batch
    for (size_t i = 0; i < batchSize; ++i) {
        Item *item = &((*items)[*itemCount]);

        item->value = atof(batch[i]);  // Example of converting string to double
        item->id = rand() % 100;       // Placeholder: replace with actual id extraction logic
        item->name = strdup("example"); // Placeholder: replace with actual name logic

        // Check memory usage (simplified)
        if ((sizeof(*items) + *itemCount * sizeof(Item) + *summaryCount * sizeof(ItemSummary)) > maxMemoryUsage) {
            fprintf(stderr, "Exceeded maximum memory usage.\n");
            return;
        }

        (*itemCount)++;
    }

    // Update or create summaries for each unique item ID
    for (size_t i = 0; i < *itemCount; ++i) {
        int found = 0;
        Item *item = &((*items)[i]);

        for (size_t j = 0; j < *summaryCount; ++j) {
            ItemSummary *summary = &((*summaries)[j]);
            if (summary->id == item->id) {
                // Update existing summary
                found = 1;
                if (item->value < summary->min || summary->min == 0) {
                    summary->min = item->value;
                }
                if (item->value > summary->max) {
                    summary->max = item->value;
                }
                summary->sum += item->value;
                summary->count++;
                break;
            }
        }

        // If not found, create new summary
        if (!found && *summaryCount < *itemCount) {  // Ensure we don't exceed initial allocation
            ItemSummary *newSummary = &((*summaries)[*summaryCount]);

            newSummary->id = item->id;
            newSummary->min = item->value;
            newSummary->max = item->value;
            newSummary->sum = item->value;
            newSummary->count = 1;

            (*summaryCount)++;
        }
    }

    // Calculate average for each summary
    for (size_t i = 0; i < *summaryCount; ++i) {
        ItemSummary *summary = &((*summaries)[i]);
        if (summary->count > 0) {
            summary->sum /= summary->count;
        }
    }

    // Free resources to avoid memory leaks
    for (size_t i = 0; i < *itemCount; ++i) {
        free((*items)[i].name);
    }
}

// Helper function to resize arrays as needed
void resizeArray(void **array, size_t currentSize, size_t newSize, size_t elementSize) {
    void *newArray = realloc(*array, newSize * elementSize);
    if (newArray == NULL) {
        fprintf(stderr, "Failed to reallocate memory.\n");
        free(*array);
        *array = NULL;
    } else {
        *array = newArray;
    }
}

int main() {
    Item *items = NULL;
    size_t itemCount = 0;

    ItemSummary *summaries = NULL;
    size_t summaryCount = 0;

    const char *batch[] = {"12.34", "56.78", "90.12"};  // Example data batch
    size_t batchSize = sizeof(batch) / sizeof(batch[0]);

    double maxMemoryUsage = 1024 * 1024;  // Example: set maximum memory usage in bytes

    processItemsBatch(&items, &itemCount, &summaries, &summaryCount, batch, batchSize, maxMemoryUsage);

    // Output summaries
