        ItemSummary *summary = &summaries[i];
        printf("ID: %d, Min: %.2f, Max: %.2f, Avg: %.2f\n", 
               summary->id, summary->min, summary->max, summary->sum);
    }

    // Free allocated memory
    free(items);
    free(summaries);

