int findLargestInteger(int* keys, size_t count) {
    if (count == 0) return INT_MIN;

    int largest = keys[0];
    for (size_t i = 1; i < count; ++i) {
        if (keys[i] > largest) {
            largest = keys[i];
        }
    }
    return largest;
