        fprintf(stderr, "Failed to open file for writing: %s\n", fileName);
        cleanUpResources(task);
        return 1;
    }

    if (writePdfToFile(pdfFile, task->getPdfData(), task->getPdfSize()) != 0) {
        fprintf(stderr, "Failed to write PDF data to file.\n");
        fclose(pdfFile);
        cleanUpResources(task);
        return 1;
    }

    // Clean up resources
    fclose(pdfFile);
    free(task);

    return 0; // Success
}

// Helper function implementations would be required for:
// - isValidJPEG()
// - transformJPEGData()
// - convertToPdfAsync(), waitForConversion(), cleanUpResources(), writePdfToFile()

