            strncpy(keys[valid_count], buffer, KEY_LENGTH);
            keys[valid_count][KEY_LENGTH] = '\0'; // Ensure null termination
            valid_count++;
        } else {
            fprintf(stderr, "Invalid or oversized input\n");
        }

        pthread_mutex_unlock(&mutex);

        if (valid_count >= MAX_KEYS) break; // Stop if max capacity is reached
    }

    findAndPrintLongestString();

    for (int i = 0; i < valid_count; ++i) {
        char *processed_str = appendSlashIfNeeded(keys[i], KEY_LENGTH);
