#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define MAX_LOG_MESSAGE_SIZE 256

typedef enum {
    DEBUG,
    INFO,
    WARNING,
    ERROR
} SeverityLevel;

typedef struct {
    SeverityLevel severity;
    time_t timestamp;
    unsigned int unique_id;
    char *message;
} logEntry;

typedef struct {
    logEntry *entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} LogManager;

logManager* createLogManager() {
    LogManager *manager = (LogManager*)malloc(sizeof(LogManager));
    manager->entries = malloc(INITIAL_CAPACITY * sizeof(logEntry));
    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void freeLogMessage(char **message) {
    if (message && *message) {
        free(*message);
        *message = NULL;
    }
}

int safeAdd(unsigned int a, unsigned int b, unsigned int* result) {
    unsigned int sum = a + b;
    if (sum < a || sum < b) return -1; // Overflow occurred
    *result = sum;
    return 0;
}

void resizeLogManager(LogManager *manager) {
    size_t new_capacity = manager->capacity * 2;
    logEntry *new_entries = realloc(manager->entries, new_capacity * sizeof(logEntry));

    if (new_entries) {
        manager->entries = new_entries;
        manager->capacity = new_capacity;
    } else {
        perror("Failed to resize memory");
        exit(EXIT_FAILURE);
    }
}

void addLogEntry(LogManager *manager, SeverityLevel severity, unsigned int unique_id, const char* message_template) {
    pthread_mutex_lock(&manager->mutex);

    if (safeAdd(manager->count, 1, &(unsigned int){0}) != 0 || manager->count >= manager->capacity) {
        resizeLogManager(manager);
    }

    logEntry *entry = &manager->entries[manager->count++];
    entry->severity = severity;
    entry->timestamp = time(NULL);
    entry->unique_id = unique_id;

    size_t message_len = strlen(message_template) + 1; // +1 for null terminator
    if (message_len > MAX_LOG_MESSAGE_SIZE) {
        message_len = MAX_LOG_MESSAGE_SIZE;
    }

    entry->message = malloc(message_len);
    strncpy(entry->message, message_template, message_len - 1);
    entry->message[message_len - 1] = '\0';

    pthread_mutex_unlock(&manager->mutex);
}

void filterLogEntries(LogManager *manager, SeverityLevel min_severity) {
    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->entries[i].severity < min_severity) {
            freeLogMessage(&(manager->entries[i].message));
            // Shift remaining entries
            memmove(&manager->entries[i], &manager->entries[i + 1],
                    (manager->count - i - 1) * sizeof(logEntry));
            manager->count--;
            i--; // Adjust index after shift
        }
    }

    pthread_mutex_unlock(&manager->mutex);
}

void serializeLogManager(const LogManager *manager, const char* filename) {
    FILE *file = fopen(filename, "wb");

    if (file) {
        fwrite(&(manager->capacity), sizeof(size_t), 1, file);
        fwrite(&(manager->count), sizeof(size_t), 1, file);

        for (size_t i = 0; i < manager->count; ++i) {
            fwrite(&manager->entries[i].severity, sizeof(SeverityLevel), 1, file);
            fwrite(&manager->entries[i].timestamp, sizeof(time_t), 1, file);
            fwrite(&manager->entries[i].unique_id, sizeof(unsigned int), 1, file);
            size_t message_len = strlen(manager->entries[i].message) + 1;
            fwrite(&message_len, sizeof(size_t), 1, file);
            fwrite(manager->entries[i].message, sizeof(char), message_len, file);
        }

        fclose(file);
    } else {
        perror("Failed to open file for serialization");
    }
}

void deserializeLogManager(LogManager *manager, const char* filename) {
    FILE *file = fopen(filename, "rb");

    if (file) {
        size_t count;
        fread(&manager->capacity, sizeof(size_t), 1, file);
        fread(&count, sizeof(size_t), 1, file);

        manager->entries = realloc(manager->entries, manager->capacity * sizeof(logEntry));
        manager->count = count;

        for (size_t i = 0; i < count; ++i) {
            fread(&manager->entries[i].severity, sizeof(SeverityLevel), 1, file);
            fread(&manager->entries[i].timestamp, sizeof(time_t), 1, file);
            fread(&manager->entries[i].unique_id, sizeof(unsigned int), 1, file);

            size_t message_len;
            fread(&message_len, sizeof(size_t), 1, file);
            manager->entries[i].message = malloc(message_len * sizeof(char));
            fread(manager->entries[i].message, sizeof(char), message_len, file);
        }

        fclose(file);
    } else {
        perror("Failed to open file for deserialization");
    }
}

void destroyLogManager(LogManager **manager) {
    if (manager && *manager) {
        for (size_t i = 0; i < (*manager)->count; ++i) {
            freeLogMessage(&((*manager)->entries[i].message));
        }
        free((*manager)->entries);
        pthread_mutex_destroy(&(*manager)->mutex);
        free(*manager);
        *manager = NULL;
    }
}

// Example usage
int main() {
    LogManager *logManager = createLogManager();

    addLogEntry(logManager, INFO, 1, "This is an info message.");
    addLogEntry(logManager, ERROR, 2, "Critical error occurred!");

    filterLogEntries(logManager, WARNING);

    serializeLogManager(logManager, "logfile.dat");

    LogManager *newLogManager = createLogManager();
    deserializeLogManager(newLogManager, "logfile.dat");

    destroyLogManager(&logManager);
    destroyLogManager(&newLogManager);

    return 0;
}
