int is_integer_in_range(int value, int min, int max) {
    return (value >= min && value <= max);
}

// Main processing function
void process_network_stream(int min_value, int max_value) {
    size_t buffer_size = 0;
    size_t current_size = sizeof(int);
    char *buffer = malloc(current_size);

    if (!buffer) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    while (1) {
        // Simulating reading an integer from a network stream
        int value; 
        size_t bytes_read = fread(&value, sizeof(int), 1, stdin);

        if (bytes_read < 1) break;

        if (!is_integer_in_range(value, min_value, max_value)) {
            fprintf(stderr, "Out of range or malformed input detected\n");
            free_allocated_memory(NULL, 0);
            return;
        }

        buffer_size += sizeof(int);

        if (buffer_size > MAX_BUFFER_SIZE) {
            fprintf(stderr, "Buffer overflow risk detected\n");
            free_allocated_memory(NULL, 0);
            return;
        }

        if (buffer_size + current_size > MAX_BUFFER_SIZE) {
            char *new_buffer = realloc(buffer, buffer_size + current_size);

            if (!new_buffer) {
                fprintf(stderr, "Memory reallocation failed\n");
                free_allocated_memory((int *)buffer, buffer_size / sizeof(int));
                return;
            }
            buffer = new_buffer;
        }

        memcpy((char*)buffer + (buffer_size - sizeof(int)), &value, sizeof(int));
    }

    int *integer_list = (int *)buffer;
    size_t length = buffer_size / sizeof(int);

    if (length == 0) {
        fprintf(stderr, "The list is empty\n");
    } else {
        int max_value_found = integer_list[0];
        for (size_t i = 1; i < length; ++i) {
            if (integer_list[i] > max_value_found) {
                max_value_found = integer_list[i];
            }
        }
        printf("The largest integer in the list is: %d\n", max_value_found);
    }

    free_allocated_memory(integer_list, length);
}

// Helper function to safely release allocated memory
void free_allocated_memory(int *array, size_t length) {
    if (array != NULL) {
        free(array);
    }
}

