['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <math.h>

typedef struct {
    int value;
    int *key;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    int64_t *totals;
    size_t capacity;
    pthread_mutex_t lock;
} MemoryManager;

void initialize_memory_manager(MemoryManager *mm, size_t initial_capacity) {
    pthread_mutex_init(&mm->lock, NULL);
    mm->capacity = initial_capacity;

    size_t total_size = sizeof(long) * initial_capacity + 
                        sizeof(int) * initial_capacity +
                        sizeof(record) * initial_capacity +
                        sizeof(int64_t);

    void *block = malloc(total_size);
    if (!block) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    mm->offsets = (long *)block;
    block += sizeof(long) * initial_capacity;

    mm->keys = (int *)block;
    block += sizeof(int) * initial_capacity;

    mm->records = (record *)block;
    block += sizeof(record) * initial_capacity;

    mm->totals = (int64_t *)block;
    *mm->totals = 0;
}

void resize_memory_manager(MemoryManager *mm, size_t new_capacity) {
    pthread_mutex_lock(&mm->lock);

    size_t total_size = sizeof(long) * new_capacity + 
                        sizeof(int) * new_capacity +
                        sizeof(record) * new_capacity +
                        sizeof(int64_t);

    void *new_block = realloc(mm->offsets, total_size);
    if (!new_block) {
        perror("Failed to reallocate memory");
        pthread_mutex_unlock(&mm->lock);
        exit(EXIT_FAILURE);
    }

    mm->offsets = (long *)new_block;
    new_block += sizeof(long) * new_capacity;

    mm->keys = (int *)new_block;
    new_block += sizeof(int) * new_capacity;

    mm->records = (record *)new_block;
    new_block += sizeof(record) * new_capacity;

    mm->totals = (int64_t *)new_block;
    mm->capacity = new_capacity;

    pthread_mutex_unlock(&mm->lock);
}

void initialize_records(MemoryManager *mm, size_t num_records) {
    pthread_mutex_lock(&mm->lock);

    double mean = 0.0;
    double sum_squares = 0.0;

    for (size_t i = 0; i < num_records; ++i) {
        int range = 100; // Default range
        if (i > 0) {
            double stddev = sqrt(sum_squares / i - mean * mean);
            range = (int)(3 * stddev); // Use 3-sigma rule for balanced distribution
        }

        int value = rand() % (2 * range + 1) - range;
        mm->records[i].value = value;
        mm->keys[i] = i; // Simple key assignment, can be modified
        mm->records[i].key = &mm->keys[i];

        mean += value / num_records;
        sum_squares += value * value;

        int64_t new_total = *mm->totals + value;
        if (new_total < *mm->totals) {
            fprintf(stderr, "Integer overflow detected\n");
            pthread_mutex_unlock(&mm->lock);
            exit(EXIT_FAILURE);
        }
        *mm->totals = new_total;
    }

    pthread_mutex_unlock(&mm->lock);
}

void release_memory_manager(MemoryManager *mm) {
    free(mm->offsets);
    pthread_mutex_destroy(&mm->lock);
}

int main() {
    size_t initial_capacity = 1000;
    MemoryManager mm;

    initialize_memory_manager(&mm, initial_capacity);

    size_t num_records = 5000; // Example number of records
    if (num_records > mm.capacity) {
        resize_memory_manager(&mm, num_records);
    }

    initialize_records(&mm, num_records);

    printf("Total value: %lld\n", *mm.totals);

    release_memory_manager(&mm);

    return 0;
}
