#define LOG_FILE "validation_failures.log"

typedef struct CRC_INDICATION_REL8_TAG {
    uint16_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
