    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* head;
    size_t count;
    pthread_mutex_t mutex;
} LinkedList;

void log_failure(const char* message) {
    FILE* file = fopen(LOG_FILE, "a");
    if (file != NULL) {
        fprintf(file, "%s\n", message);
        fclose(file);
    }
}

uint16_t calculate_crcflag(uint32_t rx_ue_information_tag) {
    // Placeholder for CRCFLAG calculation logic
    return 0xFFFF; // Example value
}

int validate_rx_ue_information_tag(uint32_t tag, uint32_t reference_crc) {
    // Placeholder for signal processing library function call
    return 1; // Assume validation is successful
}

LinkedList* create_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (list != NULL) {
        list->head = NULL;
        list->count = 0;
        pthread_mutex_init(&list->mutex, NULL);
    }
    return list;
}

void add_structure(LinkedList* list, uint32_t rx_ue_information_tag, uint16_t rnti) {
    if (list == NULL || list->count >= MAX_CAPACITY) return;

    NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) return;

    uint16_t reference_crc = 0; // Placeholder for actual CRC value
    if (!validate_rx_ue_information_tag(rx_ue_information_tag, reference_crc)) {
        log_failure("Failed validation for RX_UE_INFORMATION_TAG");
        free(new_node);
        return;
    }

    new_node->RX_UE_INFORMATION_TAG = rx_ue_information_tag;
    new_node->RNTI = rnti;
    new_node->crc_tag.CRCFLAG = calculate_crcflag(rx_ue_information_tag);
    new_node->next = NULL;

    pthread_mutex_lock(&list->mutex);

    if (list->head == NULL) {
        list->head = new_node;
    } else {
        NFAPI_CRC_INDICATION_PDU_T* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    list->count++;

    if (list->count >= NOTIFICATION_THRESHOLD) {
        printf("Warning: List is at 90%% of its maximum capacity.\n");
    }

    pthread_mutex_unlock(&list->mutex);
}

void free_list(LinkedList* list) {
    if (!list) return;

    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* next_node = current->next;
        free(current);
        current = next_node;
    }

    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int main() {
    LinkedList* list = create_list();

    // Example usage
    add_structure(list, 12345, 6789);

    free_list(list);
    return 0;
}
