    Config **new_list = realloc(config_list, sizeof(Config*) * (config_count + 1));
    if (!new_list) return NULL;

    config_list = new_list;
    Config *config = malloc(sizeof(Config));
    if (!config) {
        free(new_list);
        pthread_mutex_unlock(&global_lock);
        return NULL;
    }

    config->key = strdup(key);
    config->value_type = type;
    config->default_value = default_val;

    pthread_mutex_init(&(config->lock), NULL);

    config_list[config_count++] = config;
    pthread_mutex_unlock(&global_lock);

    return config;
}

int set_config_value(const char *key, ConfigValue value) {
    pthread_mutex_lock(&global_lock);

    for (size_t i = 0; i < config_count; ++i) {
        if (strcmp(config_list[i]->key, key) == 0) {
            pthread_mutex_lock(&(config_list[i]->lock));
            if (value.value_type != config_list[i]->value_type) {
                pthread_mutex_unlock(&(config_list[i]->lock));
                pthread_mutex_unlock(&global_lock);
                return -1; // Type mismatch
            }
            memcpy(&(config_list[i]->default_value), &value, sizeof(ConfigValue));
            pthread_mutex_unlock(&(config_list[i]->lock));
            break;
        }
    }

    pthread_mutex_unlock(&global_lock);
    return 0;
}

ConfigValue get_config_value(const char *key) {
    pthread_mutex_lock(&global_lock);

    for (size_t i = 0; i < config_count; ++i) {
        if (strcmp(config_list[i]->key, key) == 0) {
            pthread_mutex_lock(&(config_list[i]->lock));
            ConfigValue value;
            memcpy(&value, &(config_list[i]->default_value), sizeof(ConfigValue));
            pthread_mutex_unlock(&(config_list[i]->lock));

            pthread_mutex_unlock(&global_lock);
            return value;
        }
    }

    pthread_mutex_unlock(&global_lock);
    // Return a default invalid value in case of error
    ConfigValue empty = { .integer_value = 0 };
    return empty;
}

