#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Node {
    char *value;
    double score;
    struct Node *left, *right;
} Node;

// Memory pool for custom allocator
#define POOL_SIZE 1024 * 128 // Example size, adjust as needed
char memory_pool[POOL_SIZE];
size_t next_free = 0;

void* allocate_memory(size_t size) {
    if (next_free + size > POOL_SIZE) return NULL;
    void *ptr = &memory_pool[next_free];
    next_free += size;
    return ptr;
}

void free_all_memory() {
    next_free = 0; // Reset memory pool
}

Node* create_node(const char *value, double score) {
    Node *node = (Node*)allocate_memory(sizeof(Node));
    if (!node) return NULL;

    node->value = strdup(value);
    node->score = score;
    node->left = node->right = NULL;

    return node;
}

void clear_node(Node* node) {
    free(node->value);
    free(node);
}

typedef struct Tree {
    Node *root;
} Tree;

Tree* create_tree() {
    Tree *tree = (Tree*)allocate_memory(sizeof(Tree));
    tree->root = NULL;
    return tree;
}

Node* rotate_right(Node *y) {
    Node *x = y->left;
    Node *T2 = x->right;

    // Perform rotation
    x->right = y;
    y->left = T2;

    return x;
}

Node* rotate_left(Node *x) {
    Node *y = x->right;
    Node *T2 = y->left;

    // Perform rotation
    y->left = x;
    x->right = T2;

    return y;
}

// A utility function to get the height of a node
int height(Node *N) {
    if (N == NULL)
        return 0;
    return 1 + ((height(N->left) > height(N->right)) ? height(N->left) : height(N->right));
}

Node* balance_node(Node *node) {
    int balance = height(node->left) - height(node->right);

    if (balance > 1 && node->left != NULL && height(node->left->left) >= height(node->left->right))
        return rotate_right(node);
    if (balance < -1 && node->right != NULL && height(node->right->right) >= height(node->right->left))
        return rotate_left(node);

    if (balance > 1 && node->left != NULL)
        node->left = rotate_left(node->left);
    if (balance < -1 && node->right != NULL)
        node->right = rotate_right(node->right);

    return node;
}

Node* insert(Node *node, const char *value, double score) {
    if (node == NULL)
        return create_node(value, score);

    if (score < node->score || (score == node->score && strcmp(value, node->value) < 0))
        node->left = insert(node->left, value, score);
    else
        node->right = insert(node->right, value, score);

    return balance_node(node);
}

Node* minValueNode(Node* node) {
    Node* current = node;

    while (current && current->left != NULL)
        current = current->left;

    return current;
}

Node* deleteNode(Node *root, double score, const char *value) {
    if (!root) return root;

    if (score < root->score || (score == root->score && strcmp(value, root->value) < 0))
        root->left = deleteNode(root->left, score, value);
    else if (score > root->score || (score == root->score && strcmp(value, root->value) > 0))
        root->right = deleteNode(root->right, score, value);
    else {
        if (!root->left) {
            Node *temp = root->right;
            clear_node(root);
            return temp;
        } else if (!root->right) {
            Node *temp = root->left;
            clear_node(root);
            return temp;
        }

        Node* temp = minValueNode(root->right);

        strcpy(root->value, temp->value);
        root->score = temp->score;

        root->right = deleteNode(root->right, temp->score, temp->value);
    }

    return balance_node(root);
}

void inorder_traversal(Node *root) {
    if (root != NULL) {
        inorder_traversal(root->left);
        printf("Value: %s, Score: %.2f\n", root->value, root->score);
        inorder_traversal(root->right);
    }
}

void clear_tree(Tree* tree) {
    void clear_subtree(Node *node) {
        if (node != NULL) {
            clear_subtree(node->left);
            clear_subtree(node->right);
            clear_node(node);
        }
    }

    clear_subtree(tree->root);
    tree->root = NULL;
}

void integrate_with_api(Tree* tree) {
    // Simulate API integration
    printf("Integrating with external API...\n");
    // Handle potential latency and errors here
}

int main() {
    Tree *myTree = create_tree();

    myTree->root = insert(myTree->root, "Node1", 10.5);
    myTree->root = insert(myTree->root, "Node2", 20.0);
    myTree->root = insert(myTree->root, "Node3", 15.0);

    inorder_traversal(myTree->root);

    printf("\nAfter Deletion:\n");
    myTree->root = deleteNode(myTree->root, 20.0, "Node2");
    inorder_traversal(myTree->root);

    clear_tree(myTree);
    free_all_memory();

    integrate_with_api(myTree);

    return 0;
}
```

### Key Points:
- Implemented a custom memory allocator to manage the allocation of nodes within a fixed-size pool (`memory_pool`).
- Used AVL tree rotations for balancing during insertions and deletions.
- Traversal function demonstrates inorder traversal, retrieving nodes by their scores in sorted order.
- Managed memory efficiently with `clear_node`, ensuring no leaks when clearing the entire structure.
- The integration function is a placeholder to simulate interaction with an external API.']

