PacketArray* create_packet_array() {
    PacketArray *array = malloc(sizeof(PacketArray));
    array->mutex = PTHREAD_MUTEX_INITIALIZER;
    array->count = 0;
    array->capacity = PACKET_ARRAY_INITIAL_SIZE;
    array->packets = malloc(array->capacity * sizeof(Packet *));
    return array;
}

void free_packet_array(PacketArray *array) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->packets[i] != NULL) {
            free(array->packets[i]->data);
            free(array->packets[i]);
        }
    }
    free(array->packets);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int initializeNetworkPackets(const char *remote_address) {
    struct jpcap_open_params params;
    memset(&params, 0, sizeof(params));
    strcpy(params.device_name, remote_address);
    params.promisc = 1;
    params.timeout_ms = 10000; // Adjust as needed
    params.max_bytes = BUFFER_SIZE;

    int linktype = DLT_EN10MB;
    struct jpcap *j = jpcap_open_live(&params, &linktype);

    if (!j) {
        fprintf(stderr, "Failed to open connection\n");
        return -1;
    }

    PacketArray *packet_array = create_packet_array();

    while (true) {  // Replace with appropriate condition
        struct pcap_pkthdr header;
        const u_char *pkt_data;

        int res = jpcap_next_ex(j, &header, &pkt_data);
        if (res <= 0)
            continue;

        Packet *packet = malloc(sizeof(Packet));
        packet->timestamp = time(NULL);
        packet->packet_size = header.len < MAX_PACKET_SIZE ? header.len : 0;
        packet->data = malloc(packet->packet_size);

        memcpy(packet->data, pkt_data, packet->packet_size);
        // Calculate checksum (pseudo function)
        packet->checksum = calculate_checksum(packet->data, packet->packet_size);

        pthread_mutex_lock(&packet_array->mutex);
        if (packet_array->count == packet_array->capacity) {
            packet_array->capacity *= 2;
            Packet **new_packets = realloc(packet_array->packets, packet_array->capacity * sizeof(Packet *));
            if (!new_packets) {
                free_packet_array(packet_array);
                fprintf(stderr, "Failed to reallocate memory\n");
                return -1;
            }
            packet_array->packets = new_packets;
        }

        // Store packet safely
        packet_array->packets[packet_array->count++] = packet;
        pthread_mutex_unlock(&packet_array->mutex);

        // Placeholder for checksum validation and reorder logic.
    }

    jpcap_close(j);
    free_packet_array(packet_array);
    return 0; 
}

unsigned int calculate_checksum(const char *data, size_t length) {
    unsigned int checksum = 0;
    for (size_t i = 0; i < length; ++i) {
        checksum += data[i];
    }
    return checksum;
}
