#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAX_INTS 10000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        bool CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

bool isValidInteger(const char *str) {
    if (*str == '-' || *str == '+') str++;
    while (*str) {
        if (*str < '0' || *str > '9') return false;
        str++;
    }
    return true;
}

unsigned int findLargest(unsigned int *arr, size_t n) {
    unsigned int largest = arr[0];
    for (size_t i = 1; i < n; ++i) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }
    return largest;
}

void processIntegers() {
    char input[11];
    size_t count = 0;
    unsigned int *intArray = malloc(MAX_INTS * sizeof(unsigned int));
    NFAPI_CRC_INDICATION_PDU_T *nfaPduList = NULL;

    if (!intArray) return;

    printf("Enter integers (max %zu): ", MAX_INTS);

    while (count < MAX_INTS && scanf("%10s", input) == 1) {
        if (!isValidInteger(input)) {
            printf("Invalid input detected. Terminating.\n");
            free(intArray);
            return;
        }

        unsigned int num = atoi(input);
        bool duplicate = false;

        for (size_t i = 0; i < count; ++i) {
            if (intArray[i] == num) {
                duplicate = true;
                break;
            }
        }

        if (!duplicate && num > 0) {
            intArray[count++] = num;
        } else {
            printf("Duplicate or invalid integer detected. Skipping.\n");
        }
    }

    size_t pduCount = count;
    nfaPduList = malloc(pduCount * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!nfaPduList) {
        free(intArray);
        return;
    }

    for (size_t i = 0; i < pduCount; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = intArray[i];
        pdu.RNTI = i + 1; // Unique RNTI
        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        nfaPduList[i] = pdu;
    }

    if (pduCount > 0) {
        unsigned int largest = findLargest(intArray, count);
        printf("Largest integer: %u\n", largest);
    } else {
        printf("No valid structures to process.\n");
    }

    free(nfaPduList);
    free(intArray);
}

int main() {
    srand((unsigned)time(NULL));
    processIntegers();
    return 0;
}
