            {
                string dirConfig = elements.First().Value;
                directoryName = Path.Combine(dirConfig, directoryName);
            }

            lock (lockObject)
            {
                if (!Environment.GetEnvironmentVariable(EnvironmentVariableName) is not null)
                {
                    CreateAndSetDirectory(directoryName);
                }
            }

            return Environment.GetEnvironmentVariable(EnvironmentVariableName);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
            return DefaultDirectoryPath;
        }
    }

    private void CreateAndSetDirectory(string path)
    {
        string parentDir = Path.GetDirectoryName(path);

        if (!Directory.Exists(parentDir))
        {
            Directory.CreateDirectory(parentDir);
        }

        if (!Directory.Exists(path))
        {
            Directory.CreateDirectory(path);
        }

        Environment.SetEnvironmentVariable(EnvironmentVariableName, path, EnvironmentVariableTarget.Machine);
    }
}

