    long totalSum;
} SharedState;

void ResourceEfficientRecordInitialization(int numRecords, int rangeStart, int rangeEnd) {
    SharedState sharedState = {PTHREAD_MUTEX_INITIALIZER, 0};

    pthread_t threads[2];
    int keys[numRecords];
    long offsets[numRecords];
    Record* records = malloc(numRecords * sizeof(Record));

    if (!keys || !offsets || !records)
        return;

    srand(time(NULL));

    for (int i = 0; i < numRecords; ++i) {
        offsets[i] = rand() % 10000; // Example offset calculation
        keys[i] = rand() % numRecords;

        pthread_create(&threads[0], NULL, InitializeRecord, (void*)&records[i]);
    }

    for (int i = 0; i < numRecords; ++i) {
        pthread_join(threads[0], NULL);
    }

    for (int i = 0; i < numRecords; ++i) {
        pthread_mutex_lock(&sharedState.lock);
        if (sharedState.totalSum > INT_MAX - records[i].value) {
            sharedState.totalSum = INT_MAX;
        } else {
            sharedState.totalSum += records[i].value;
        }
        pthread_mutex_unlock(&sharedState.lock);
    }

    free(records);
}

void* InitializeRecord(void* arg) {
    Record* record = (Record*)arg;

    record->keyIndex = rand() % 100; // Assign a key index based on some logic

    // Calculate the adjusted range
    long totalSum = sharedState.totalSum;
    int midPoint = (rangeStart + rangeEnd) / 2;
    int rangeAdjustment = (int)(totalSum % 10);

    record->value = rand() % (rangeEnd - rangeStart + 1) + rangeStart +
                    (rangeAdjustment > midPoint ? -rangeAdjustment : rangeAdjustment);

    pthread_mutex_lock(&sharedState.lock);
    if (sharedState.totalSum > INT_MAX - record->value) {
        sharedState.totalSum = INT_MAX;
    } else {
        sharedState.totalSum += record->value;
    }
    pthread_mutex_unlock(&sharedState.lock);

    return NULL;
}
