int is_duplicate(const PacketArray *array, uint64_t timestamp) {
    pthread_mutex_lock(&array->lock);
    int duplicate = 0;

    if (array->count > 0 && timestamp == array->packets[array->count - 1].timestamp) {
        duplicate = 1;
    }

    pthread_mutex_unlock(&array->lock);

    return duplicate;
}

void add_packet(PacketArray *array, uint64_t timestamp, size_t packet_size, void *data) {
