        resize_packet_array(array);
    }

    pthread_mutex_lock(&array->lock);

    if (!is_duplicate(array, timestamp)) {
        Packet new_packet = {timestamp, packet_size, data};
        array->packets[array->count++] = new_packet;

        qsort(array->packets, array->count, sizeof(Packet), compare_packets);
    } else {
        uint64_t current_time = (uint64_t)time(NULL); // Placeholder for actual timestamp
        if (current_time - array->last_logged_duplicate_timestamp > 1) { // Log every second
            log_event("Duplicate packet detected");
            array->last_logged_duplicate_timestamp = current_time;
        }
    }

