    uint64_t current_time = (uint64_t)time(NULL); // Placeholder for actual timestamp
    if (current_time - array->last_logged_loss_timestamp > 1) { // Log every second
        size_t expected_count = MAX_PACKETS; // Example estimation
        if (array->count < expected_count) {
