// Error handling function
void handleError(const char *message) {
    fprintf(stderr, "%s\n", message);
}

// Function to initialize random number generator
unsigned int seedRand(unsigned int userSeed) {
    if (userSeed == 0) {
        return (unsigned int)time(NULL);
    }
    return userSeed;
}

// Memory allocation and initialization for arrays
void allocateAndInitializeArrays(long **offsetArray, int *numOffsets, int **keyArray, int *numKeys) {
    size_t maxLongs = 1024; // Example limit
    size_t maxInts = 2048;  // Example limit

    *numOffsets = (int)(rand() % (maxLongs / 2)); // Random number of offsets
    *offsetArray = (long *)malloc(*numOffsets * sizeof(long));
    if (!*offsetArray) handleError("Failed to allocate memory for offset array");

    *numKeys = (int)(rand() % (maxInts / 2)); // Random number of keys
    *keyArray = (int *)malloc(*numKeys * sizeof(int));
    if (!*keyArray) {
        free(*offsetArray);
        handleError("Failed to allocate memory for key array");
    }

    // Initialize arrays
    for (int i = 0; i < *numOffsets; ++i) (*offsetArray)[i] = rand();
    for (int j = 0; j < *numKeys; ++j) (*keyArray)[j] = rand();
}

// Allocate and initialize records array
void allocateAndInitializeRecords(Record ***records, int numRecords) {
    if (numRecords <= 0 || numRecords > 10000) { // Example limit
        handleError("Invalid number of records requested");
        return;
    }

    *records = (Record **)malloc(numRecords * sizeof(Record *));
    if (!*records) handleError("Failed to allocate memory for records");

    for (int i = 0; i < numRecords; ++i) {
        (*records)[i] = (Record *)malloc(sizeof(Record));
        if (!(*records)[i]) {
            while (--i >= 0) free((*records)[i]);
            free(*records);
            handleError("Failed to allocate memory for a record");
            return;
        }
        (*records)[i]->value = rand();
    }
}

// Deallocate memory
void deallocateResources(long *offsetArray, int numOffsets, int *keyArray, int numKeys, Record **records, int numRecords) {
    free(offsetArray);
    free(keyArray);
    for (int i = 0; i < numRecords; ++i) {
        free(records[i]);
    }
    free(records);
}

// Serialize records to binary format
void serializeRecords(Record **records, int numRecords, char **binaryData, size_t *dataSize) {
    *dataSize = numRecords * sizeof(Record);
    *binaryData = (char *)malloc(*dataSize);
    if (!*binaryData) handleError("Failed to allocate memory for binary data");

    memcpy(*binaryData, records, *dataSize);
}

// Main function demonstrating the use
void performTasks(unsigned int seed, int numRecords) {
    long *offsetArray;
    int numOffsets, *keyArray, numKeys;
    Record **records;
    char *binaryData;
    size_t dataSize;

    // Seed random number generator
    srand(seedRand(seed));

    // Allocate and initialize arrays
    allocateAndInitializeArrays(&offsetArray, &numOffsets, &keyArray, &numKeys);

    // Allocate and initialize records
    allocateAndInitializeRecords(&records, numRecords);

    // Serialize records to binary format
    serializeRecords(records, numRecords, &binaryData, &dataSize);

    // Example usage of serialized data (e.g., write to file or send over network)

    // Deallocate resources
    deallocateResources(offsetArray, numOffsets, keyArray, numKeys, records, numRecords);
    free(binaryData);
}

int main() {
    performTasks(12345, 500); // Example call with seed and number of records
    return 0;
}
