        newNode->data = pdu;
        newNode->next = NULL;

        if (!head) {
            head = newNode;
        } else {
            tail->next = newNode;
        }

        tail = newNode;
    }

    return head;
}

void freeLinkedList(Node* head) {
    Node* current = head;
    while (current) {
        Node* nextNode = current->next;
        free(current);
        current = nextNode;
    }
}
