    array->packets = NULL;
    array->count = 0;
    array->capacity = 0;
    array->total_memory = 0;
    pthread_mutex_init(&array->lock, NULL);
    pthread_cond_init(&array->cond, NULL);
    array->memory_threshold = memory_threshold;
    return array;
