    while ((array->total_memory + packet_size) > array->memory_threshold) {
        pthread_cond_wait(&array->cond, &array->lock);
    }

    if (array->count >= array->capacity) {
        size_t new_capacity = (array->capacity == 0) ? 1 : array->capacity * 2;
        Packet **new_packets = realloc(array->packets, new_capacity * sizeof(Packet *));
        if (!new_packets) {
            pthread_mutex_unlock(&array->lock);
            return -1;
        }
        array->packets = new_packets;
        array->capacity = new_capacity;
    }

    Packet *packet = (Packet *)malloc(sizeof(Packet));
    packet->timestamp = time(NULL);
    packet->packet_size = packet_size;
    packet->data = malloc(packet_size);
    memcpy(packet->data, data, packet_size);

    array->packets[array->count++] = packet;
    array->total_memory += packet_size;

    pthread_mutex_unlock(&array->lock);
    pthread_cond_signal(&array->cond);
    log_event("Packet added successfully");

    return 0;
}

