typedef struct {
    GeoPoint *points;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} GeoList;

GeoList* create_geolist(size_t initial_capacity) {
    GeoList *list = malloc(sizeof(GeoList));
    list->points = malloc(initial_capacity * sizeof(GeoPoint));
    list->count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_geolist(GeoList *list) {
    free(list->points);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int is_valid_geo_point(const GeoPoint *point) {
    return point->latitude >= MIN_LAT && point->latitude <= MAX_LAT &&
           point->longitude >= MIN_LON && point->longitude <= MAX_LON;
}

void add_geopoint(GeoList *list, const GeoPoint *point) {
    pthread_mutex_lock(&list->lock);
    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        GeoPoint *new_points = realloc(list->points, new_capacity * sizeof(GeoPoint));
        if (!new_points) {
            pthread_mutex_unlock(&list->lock);
            return; // Handle memory allocation failure
        }
        list->points = new_points;
        list->capacity = new_capacity;
    }
    list->points[list->count++] = *point;
    pthread_mutex_unlock(&list->lock);
}

void process_batch(GeoList *list, GeoPoint *batch, size_t batch_size) {
    for (size_t i = 0; i < batch_size; ++i) {
        if (is_valid_geo_point(&batch[i])) {
            add_geopoint(list, &batch[i]);
        }
    }
}

void* process_stream(void *arg) {
    GeoList *list = (GeoList *) arg;
    // Simulate processing batches
    while (1) {
        // Assume get_next_batch() fetches the next batch of coordinates
        // and returns its size or 0 if no more data is available.
        GeoPoint *batch = NULL; // Placeholder for actual batch fetching logic
        size_t batch_size = 0;  // Placeholder for actual batch size

        if (batch_size == 0) {
            break;
        }

        process_batch(list, batch, batch_size);
    }
    return NULL;
}

double calculate_distance(const GeoPoint *p1, const GeoPoint *p2) {
    double lat_diff = p1->latitude - p2->latitude;
    double lon_diff = p1->longitude - p2->longitude;
    return sqrt(lat_diff * lat_diff + lon_diff * lon_diff);
}

void find_farthest_points(GeoList *list, GeoPoint *farthest1, GeoPoint *farthest2) {
    double max_distance = 0.0;
    for (size_t i = 0; i < list->count; ++i) {
        for (size_t j = i + 1; j < list->count; ++j) {
            double distance = calculate_distance(&list->points[i], &list->points[j]);
            if (distance > max_distance) {
                max_distance = distance;
                *farthest1 = list->points[i];
                *farthest2 = list->points[j];
            }
        }
    }
}

void print_farthest_points(const GeoPoint *p1, const GeoPoint *p2) {
    printf("Farthest Points:\n");
    printf("Point 1: (%f, %f)\n", p1->latitude, p1->longitude);
    printf("Point 2: (%f, %f)\n", p2->latitude, p2->longitude);
}

