    bool isPrimary;
    int healthScore;  // Calculated based on metrics
} ServiceStatus;

// Global variables for simplicity (in production, use proper data structures)
ServiceMetrics services[] = {
    {"WebServer", 100.0, 99.9, 500},
    {"Database", 50.0, 99.95, 200},
    {"MessagingSystem", 30.0, 99.8, 300}
};

int numServices = sizeof(services) / sizeof(services[0]);

// Function prototypes
void *monitorService(void *arg);
bool checkHealth(ServiceStatus *service);
void failoverMechanism(const char *serviceName);
void sendAlert(const char *message);

int main() {
    pthread_t threads[numServices];

    // Create a thread for each service to monitor concurrently
    for (int i = 0; i < numServices; ++i) {
        if (pthread_create(&threads[i], NULL, &monitorService, (void *)&services[i]) != 0) {
            fprintf(stderr, "Failed to create thread for %s\n", services[i].name);
            exit(EXIT_FAILURE);
        }
    }

    // Wait for all threads to complete
    for (int i = 0; i < numServices; ++i) {
        pthread_join(threads[i], NULL);
    }

    return EXIT_SUCCESS;
}

void *monitorService(void *arg) {
    ServiceMetrics service = *(ServiceMetrics *)arg;

    while (true) { // Infinite loop for continuous monitoring
        ServiceStatus status = {service.name, true, 0};

        if (!checkHealth(&status)) {
            failoverMechanism(status.serviceName);
