    unsigned int UE_ID;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Custom memory management
void* custom_malloc(size_t size) {
    void* ptr = malloc(size);
    // Track allocation here if needed
    return ptr;
}

void custom_free(void* ptr) {
    free(ptr);
    // Track deallocation here if needed
}

NFAPI_CRC_INDICATION_PDU_T* create_nfa_list(int num_structs, int thread_count) {
    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T*)custom_malloc(num_structs * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_t threads[thread_count];
    int range_per_thread = num_structs / thread_count;

    void* create_and_populate(void* arg) {
        int start_index = *(int*)arg;
        for (int i = start_index; i < start_index + range_per_thread; ++i) {
            list[i].UE_ID = i;
            list[i].crc_tag.RX_UE_INFORMATION_TAG = rand();
            list[i].crc_tag.RNTI = rand() % 1000;
            list[i].crc_tag.CRCFLAG = rand() % 2 == 0;
        }
        return NULL;
    }

    for (int i = 0; i < thread_count; ++i) {
        int start_index = i * range_per_thread;
        pthread_create(&threads[i], NULL, create_and_populate, &start_index);
    }

    for (int i = 0; i < thread_count; ++i) {
        pthread_join(threads[i], NULL);
    }

    return list;
}

void serialize_list(NFAPI_CRC_INDICATION_PDU_T* list, int num_structs, char* output_buffer) {
    for (int i = 0; i < num_structs; ++i) {
        memcpy(output_buffer + i * sizeof(NFAPI_CRC_INDICATION_PDU_T), &list[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
}

void deserialize_list(NFAPI_CRC_INDICATION_PDU_T* list, int num_structs, const char* input_buffer) {
