namespace CryptLib {

    class CryptoManager {
    public:
        static EVP_CIPHER* getCipher(const std::string& mode, int keySize) {
            if (mode == "ECB") {
                return EVP_des_ede3_ecb();
            } else if (mode == "EDE") {
                return EVP_des_ede_cbc();
            } else if (mode == "EDE3") {
                return EVP_des_ede3_cbc();
            } else if (mode == "CFB") {
                return EVP_des_cfb64();
            } else if (mode == "NULL") {
