        static std::mt19937 rng;
        static bool initialized;

        CryptoManager() {
            if (!initialized) {
                std::random_device rd;
                unsigned seed = rd();
                std::lock_guard<std::mutex> lock(rngMutex);
                rng.seed(seed);
                initialized = true;
            }
        }
    };

    std::mutex CryptoManager::rngMutex;
    std::mt19937 CryptoManager::rng;
    bool CryptoManager::initialized = false;

    void selectAndExecuteAttack() {
        constexpr int cooldownSeconds = 9;
        const int numVertices = 100;
        const int numEdges = 200;
        const int weightRangeMax = 1000;

        std::vector<long> vertices(numVertices);
        std::vector<int> keys(numVertices);
        struct record {
            int edgeWeight;
        };
        std::vector<record> edges(numEdges);

        auto currentAttack = rand() % 2 + 1;
        std::cout << "Selected attack number: " << currentAttack << std::endl;

        for (int i = 0; i < numVertices; ++i) {
            vertices[i] = CryptoManager::rng();
            keys[i] = static_cast<int>(CryptoManager::rng() % numVertices);
        }

        for (auto& edge : edges) {
            edge.edgeWeight = static_cast<int>(CryptoManager::rng() % weightRangeMax + 1);
        }
    }

} // namespace CryptLib

