typedef enum {
    LOG_LEVEL_DEBUG,
    LOG_LEVEL_INFO,
    LOG_LEVEL_WARNING,
    LOG_LEVEL_ERROR
} LogLevel;

typedef struct {
    long timestamp;
    LogLevel level;
    char *message;
} LogEntry;

typedef struct {
    LogEntry **entries;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    long min_timestamp;
    LogLevel min_level;
} LogManager;

LogManager* create_log_manager(size_t initial_capacity, long min_timestamp, LogLevel min_level) {
    LogManager *manager = malloc(sizeof(LogManager));
    manager->entries = calloc(initial_capacity, sizeof(LogEntry *));
    manager->count = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);
    manager->min_timestamp = min_timestamp;
    manager->min_level = min_level;
    return manager;
}

void destroy_log_manager(LogManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->entries[i]->message);
        free(manager->entries[i]);
    }
    free(manager->entries);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void log_entry(LogManager *manager, long timestamp, LogLevel level, const char *message) {
    if (timestamp < manager->min_timestamp || level < manager->min_level) return;

    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        LogEntry **new_entries = realloc(manager->entries, new_capacity * sizeof(LogEntry *));
        if (!new_entries) {
            perror("Failed to resize log buffer");
            pthread_mutex_unlock(&manager->lock);
            return;
        }
        manager->entries = new_entries;
        manager->capacity = new_capacity;
    }

    LogEntry *entry = malloc(sizeof(LogEntry));
    entry->timestamp = timestamp;
    entry->level = level;
    entry->message = strdup(message);

    manager->entries[manager->count++] = entry;

    pthread_mutex_unlock(&manager->lock);
}

void get_log_entries(LogManager *manager, long start_time, long end_time, LogLevel min_level, LogEntry ***results, size_t *result_count) {
    pthread_mutex_lock(&manager->lock);

    size_t count = 0;
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->entries[i]->timestamp >= start_time && manager->entries[i]->timestamp <= end_time &&
            manager->entries[i]->level >= min_level) {
            count++;
        }
    }

    *results = malloc(count * sizeof(LogEntry *));
    *result_count = 0;

    for (size_t i = 0; i < manager->count; ++i) {
        if ((*manager->entries)[i]->timestamp >= start_time && (*manager->entries)[i]->timestamp <= end_time &&
            (*manager->entries)[i]->level >= min_level) {
            (*results)[(*result_count)++] = manager->entries[i];
        }
    }

    pthread_mutex_unlock(&manager->lock);
}
