#define MAX_INTS 1000000
#define RNTI_MIN 1
#define RNTI_MAX 65535
#define CRCFLAG_VALID_PATTERNS 2

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

bool is_unique_rnti(unsigned short rnti, unsigned short* unique_rntis, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (unique_rntis[i] == rnti) return false;
    }
    return true;
}

void log_message(const char* message) {
    pthread_mutex_lock(&mutex);
    printf("%s\n", message);
    pthread_mutex_unlock(&mutex);
}

bool validate_data(NFAPI_CRC_INDICATION_PDU_T* pdu_list, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (pdu_list[i].RNTI < RNTI_MIN || pdu_list[i].RNTI > RNTI_MAX) return false;
        // Example CRCFLAG validation
        if ((pdu_list[i].CRC_INDICATION_REL8_TAG & 0x03) != (pdu_list[i].CRCFLAG ? 1 : 0)) return false;
    }
    return true;
}

int find_largest_integer(int* int_array, size_t count) {
    if (count == 0) return -1; // or an error code

    int largest = int_array[0];
    for (size_t i = 1; i < count; ++i) {
        if (int_array[i] > largest) largest = int_array[i];
    }
    return largest;
}

void process_integers() {
    size_t capacity = 10;
    size_t size = 0;
    unsigned short unique_rntis[capacity] = {0};

    int* int_array = malloc(capacity * sizeof(int));
    if (!int_array) {
        log_message("Memory allocation failed");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu_list = NULL;
    size_t pdu_capacity = 10;

    srand(time(NULL));

    while (size < MAX_INTS) {
        int input_value;
        if (!scanf("%d", &input_value)) {
            log_message("Invalid input detected, terminating.");
            break;
        }

        if (size == capacity) {
            capacity *= 2;
            int_array = realloc(int_array, capacity * sizeof(int));
            if (!int_array) {
                log_message("Memory reallocation failed");
                return;
            }
        }

        int_array[size++] = input_value;

        if (size % 10 == 0) { // Periodically process and validate
            if (pdu_list == NULL) {
                pdu_list = malloc(pdu_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                if (!pdu_list) {
                    log_message("Memory allocation failed for PDU list");
                    return;
                }
            } else if (size / 3 >= pdu_capacity) { // Assuming 3 integers per structure
                pdu_capacity *= 2;
                NFAPI_CRC_INDICATION_PDU_T* temp = realloc(pdu_list, pdu_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                if (!temp) {
                    log_message("Memory reallocation failed for PDU list");
                    return;
                }
                pdu_list = temp;
            }

            int index = size - 1;
            NFAPI_CRC_INDICATION_PDU_T* pdu = &pdu_list[size / 3 - 1];

            pdu->RX_UE_INFORMATION_TAG = int_array[index - 2];
            unsigned short rnti_candidate = (unsigned short)int_array[index - 1];
            while (!is_unique_rnti(rnti_candidate, unique_rntis, size / 3)) {
                rnti_candidate++;
            }
            pdu->RNTI = rnti_candidate;
            unique_rntis[size / 3 - 1] = rnti_candidate;

            pdu->CRC_INDICATION_REL8_TAG = (unsigned char)int_array[index];
            pdu->CRCFLAG = rand() % CRCFLAG_VALID_PATTERNS == 0; // Randomly set CRCFLAG

            if (!validate_data(pdu_list, size / 3)) {
                log_message("Data validation failed");
                return;
            }
        }
    }

    int largest_integer = find_largest_integer(int_array, size);
    if (size > 0) {
        printf("Largest integer: %d\n", largest_integer);
    } else {
        log_message("No valid integers processed.");
    }

    free(int_array);
    free(pdu_list);
}

int main() {
    process_integers();
    return 0;
}
