    int width, height;
    time_t creation_timestamp;
    unsigned char *image_data;
    char lens_info[128];
    int iso_setting;
    double exposure_time;
} ImageMetadata;

#define MAX_THREADS 8
#define INITIAL_ARRAY_SIZE 64

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
ImageMetadata **metadata_list = NULL;
size_t metadata_count = 0;
size_t capacity = 0;

void init_metadata_list() {
    pthread_mutex_lock(&mutex);
    if (capacity == 0) {
        capacity = INITIAL_ARRAY_SIZE;
        metadata_list = calloc(capacity, sizeof(ImageMetadata *));
        if (!metadata_list) {
            perror("Failed to allocate memory for metadata list");
            exit(EXIT_FAILURE);
        }
    }
    pthread_mutex_unlock(&mutex);
}

void resize_metadata_list() {
    pthread_mutex_lock(&mutex);
    capacity *= 2;
    ImageMetadata **new_list = realloc(metadata_list, capacity * sizeof(ImageMetadata *));
    if (!new_list) {
        perror("Failed to reallocate memory for metadata list");
        exit(EXIT_FAILURE);
    }
    metadata_list = new_list;
    pthread_mutex_unlock(&mutex);
}

void add_metadata_to_list(ImageMetadata *metadata) {
    pthread_mutex_lock(&mutex);
    if (metadata_count == capacity) {
        resize_metadata_list();
    }
    metadata_list[metadata_count++] = metadata;
    pthread_mutex_unlock(&mutex);
}

void free_metadata_list() {
    for (size_t i = 0; i < metadata_count; ++i) {
        if (metadata_list[i]) {
            free(metadata_list[i]->file_path);
            free(metadata_list[i]->image_data);
            free(metadata_list[i]);
        }
    }
    free(metadata_list);
}

int is_image_file(const char *path) {
    // Use third-party library to check file type
    return third_party_is_image(path);
}

ImageMetadata* extract_metadata(const char *file_path) {
    ImageMetadata *metadata = malloc(sizeof(ImageMetadata));
    if (!metadata) {
        perror("Failed to allocate memory for metadata");
        return NULL;
    }

    // Extract metadata using third-party library
    if (third_party_extract_metadata(file_path, &metadata->width, &metadata->height,
                                     &metadata->creation_timestamp, &metadata->image_data,
                                     metadata->lens_info, sizeof(metadata->lens_info),
                                     &metadata->iso_setting, &metadata->exposure_time)) {
        free(metadata);
        return NULL;
    }

    metadata->file_path = strdup(file_path);
    if (!metadata->file_path) {
        perror("Failed to duplicate file path");
        free(metadata);
        return NULL;
    }

    return metadata;
}

void* process_directory(void *arg) {
    char *dir_path = (char *)arg;
    DIR *dir = opendir(dir_path);
    if (!dir) {
        perror("Failed to open directory");
        return NULL;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        char full_path[1024];
        snprintf(full_path, sizeof(full_path), "%s/%s", dir_path, entry->d_name);

        struct stat path_stat;
        if (stat(full_path, &path_stat) != 0) {
            perror("Failed to get file status");
            continue;
        }

        if (S_ISDIR(path_stat.st_mode)) {
            // Recursively process subdirectories
            char *sub_dir = strdup(full_path);
            if (!sub_dir) {
                perror("Failed to duplicate directory path");
                continue;
            }
            pthread_t thread_id;
            if (pthread_create(&thread_id, NULL, process_directory, sub_dir) != 0) {
                perror("Failed to create thread for directory processing");
                free(sub_dir);
                continue;
            }
            pthread_detach(thread_id); // Detach the thread
        } else if (is_image_file(full_path)) {
            ImageMetadata *metadata = extract_metadata(full_path);
            if (metadata) {
                add_metadata_to_list(metadata);
            }
        }
    }

    closedir(dir);
    free(arg);
    return NULL;
}

void processImageMetadata(const char *directory_path) {
    init_metadata_list();

    pthread_t thread_id;
    char *dir_path = strdup(directory_path);
    if (!dir_path) {
        perror("Failed to duplicate directory path");
        exit(EXIT_FAILURE);
    }

    if (pthread_create(&thread_id, NULL, process_directory, dir_path) != 0) {
        perror("Failed to create initial processing thread");
        free(dir_path);
        exit(EXIT_FAILURE);
    }
    pthread_join(thread_id, NULL);

    // Further processing like calculating average pixel values, histograms, etc.
    for (size_t i = 0; i < metadata_count; ++i) {
        ImageMetadata *metadata = metadata_list[i];
        if (!metadata) continue;

        // Example: Calculate average pixel value
        unsigned long total_pixels = metadata->width * metadata->height;
        unsigned long total_value = 0;
        for (unsigned long j = 0; j < total_pixels; ++j) {
            // Assuming grayscale image data for simplicity
            total_value += metadata->image_data[j];
        }
        double average_pixel_value = (double)total_value / total_pixels;
        printf("Average pixel value for %s: %.2f\n", metadata->file_path, average_pixel_value);

        // Additional processing can be added here
    }

    free_metadata_list();
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <directory_path>\n", argv[0]);
        return EXIT_FAILURE;
    }

    processImageMetadata(argv[1]);

    return EXIT_SUCCESS;
}
