void update_sensor_reading(SensorSystem *system, size_t index, float reading) {
    pthread_mutex_lock(&system->mutex);

    if (index >= system->sensor_count) {
        fprintf(stderr, "Sensor index out of bounds\n");
        pthread_mutex_unlock(&system->mutex);
        return;
    }

    SensorData *sensor = &system->sensors[index];
    sensor->reading = reading;

    // Update running total
    system->total_readings += (reading - system->sensors[index].reading);

    // Update max and min values
    if (reading > system->max_value) {
        system->max_value = reading;
    }
    if (reading < system->min_value) {
        system->min_value = reading;
    }

    pthread_mutex_unlock(&system->mutex);
