char *resolve_env_variables(const char *str) {
    if (str == NULL) return strdup("");

    size_t len = strlen(str) + 1;
    char *resolved_str = malloc(len);
    const char *start = str;
    char *ptr = resolved_str;

    while (*str) {
        if (*str == '$' && *(str + 1) == '{') {
            // Find the end of the environment variable
            char *end = strchr(str, '}');
            if (!end) break;

            size_t var_len = end - str - 2;
            char env_var[var_len + 1];
            strncpy(env_var, str + 2, var_len);
            env_var[var_len] = '\0';

            // Get the environment variable value
            const char *env_value = getenv(env_var);
            if (env_value) {
                size_t val_len = strlen(env_value);
                ptr += sprintf(ptr, "%s", env_value);
                str = end + 1;
                continue;
            }
        }

        *ptr++ = *str++;
    }
    *ptr = '\0';
    return resolved_str;
}

