using System;
using System.IO;
using System.Xml;
using System.Xml.XPath;

public class DirectoryManager
{
    private static readonly string DefaultDirectoryPath = @"C:\Default\Path";

    public static string EnvironmentAndDataInitialization(string xmlFilePath, string configXPath)
    {
        try
        {
            XmlDocument doc = new XmlDocument();
            doc.Load(xmlFilePath);

            XPathNavigator navigator = doc.CreateNavigator();
            XPathNodeIterator nodes = navigator.Select(configXPath);

            if (nodes.Count != 1)
            {
                Console.WriteLine("Configuration element not found or multiple elements match. Using default directory.");
            }

            string targetDirectory = DefaultDirectoryPath;
            if (nodes.MoveNext())
            {
                targetDirectory = nodes.Current.Value.Trim();
            }

            string envVarName = "MY_APP_DATA_PATH";
            string dirPath = Environment.GetEnvironmentVariable(envVarName) ?? targetDirectory;

            if (!Directory.Exists(dirPath))
            {
                Directory.CreateDirectory(dirPath);
                Environment.SetEnvironmentVariable(envVarName, dirPath);
            }

            return dirPath;
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
            return null;
        }
    }
}
