void initialize_records() {
    pthread_mutex_init(&lock, NULL);
    records = (record*)malloc(MAX_RECORDS * sizeof(record));
}

void free_resources() {
    if (records) {
        free(records);
        records = NULL;
    }
    pthread_mutex_destroy(&lock);
}

int get_next_random(int range) {
    return rand() % range + 1;
}

void ResourceOptimizedDataInitialization(int numRecordsToAdd) {
    if (!records || totalRecords + numRecordsToAdd > MAX_RECORDS) {
        printf("Error: Not enough memory allocated for records.\n");
        return;
    }

    pthread_mutex_lock(&lock);

    int startIdx = totalRecords;
    for (int i = 0; i < numRecordsToAdd && totalRecords < MAX_RECORDS; ++i) {
        if (cumulativeSum == LLONG_MAX - numRecordsToAdd) {
            printf("Warning: Potential integer overflow detected.\n");
            break;
        }

        records[totalRecords].offset = (long)i * 1000; // Example offset value
        int range = get_next_random(10 + startIdx % 10); // Dynamically adjusted range

        if (__builtin_add_overflow(cumulativeSum, range, &cumulativeSum)) {
            printf("Error: Integer overflow detected.\n");
            break;
        }

        records[totalRecords].key = get_next_random(range);
        totalRecords++;
    }

    pthread_mutex_unlock(&lock);
}

int main() {
    initialize_records();
    ResourceOptimizedDataInitialization(10);

    // Example usage
