#include <iostream>
#include <vector>
#include <string>
#include <mutex>
#include <thread>
#include <queue>
#include <condition_variable>
#include <chrono>
#include <atomic>
#include <memory>
#include <algorithm>

struct LogEntry {
    int logLevel;
    std::chrono::system_clock::time_point timestamp;
    std::string message;
    void* logData;

    bool isValid() const {
        return logLevel >= 0 && !message.empty() && logData != nullptr;
    }
};

class Logger {
public:
    Logger(size_t maxLogEntries)
        : maxLogEntries(maxLogEntries), stopProcessing(false) {}

    ~Logger() {
        stop();
    }

    void addLogEntry(int logLevel, const std::string& message, void* logData) {
        auto entry = std::make_unique<LogEntry>();
        entry->logLevel = logLevel;
        entry->timestamp = std::chrono::system_clock::now();
        entry->message = message;
        entry->logData = logData;

        std::lock_guard<std::mutex> lock(queueMutex);
        if (entry->isValid()) {
            logQueue.push(std::move(entry));
            cv.notify_one();
        }
    }

    void processLogs() {
        while (!stopProcessing) {
            std::unique_lock<std::mutex> lock(queueMutex);
            cv.wait(lock, [this] { return !logQueue.empty() || stopProcessing; });

            while (!logQueue.empty()) {
                auto entry = std::move(logQueue.front());
                logQueue.pop();
                lock.unlock();

                if (logs.size() >= maxLogEntries) {
                    pruneOldLogs();
                }

                logs.push_back(std::move(*entry));
                logFrameworkIntegration(*entry);

                lock.lock();
            }
        }

        // Final cleanup
        while (!logQueue.empty()) {
            auto entry = std::move(logQueue.front());
            logQueue.pop();

            if (logs.size() >= maxLogEntries) {
                pruneOldLogs();
            }

            logs.push_back(std::move(*entry));
            logFrameworkIntegration(*entry);
        }
    }

    void startProcessing() {
        processingThread = std::thread(&Logger::processLogs, this);
    }

    void stop() {
        stopProcessing = true;
        cv.notify_all();
        if (processingThread.joinable()) {
            processingThread.join();
        }
    }

    struct Report {
        size_t totalLogCount;
        double averageLogSize;
        double malformedProportion;
    };

    Report getSummaryReport() const {
        std::lock_guard<std::mutex> lock(mutex);
        size_t totalMalformed = 0;

        for (const auto& entry : logs) {
            if (!entry.isValid()) {
                totalMalformed++;
            }
        }

        double averageSize = logs.empty() ? 0.0 :
            static_cast<double>(std::accumulate(logs.begin(), logs.end(),
                size_t(0), [](size_t sum, const LogEntry& entry) {
                    return sum + entry.message.size();
                })) / logs.size();

        Report report{
            logs.size(),
            averageSize,
            totalMalformed / static_cast<double>(logs.size())
        };

        return report;
    }

private:
    void pruneOldLogs() {
        if (logs.size() > maxLogEntries) {
            size_t excess = logs.size() - maxLogEntries;
            logs.erase(logs.begin(), logs.begin() + excess);
        }
    }

    void logFrameworkIntegration(const LogEntry& entry) const {
        // Simulate integration with an existing logging framework
        std::cout << "Log added: Level=" << entry.logLevel
                  << ", Timestamp=" << std::chrono::system_clock::to_time_t(entry.timestamp)
                  << ", Message=" << entry.message << std::endl;
    }

    size_t maxLogEntries;
    mutable std::mutex mutex, queueMutex;
    std::condition_variable cv;
    std::queue<std::unique_ptr<LogEntry>> logQueue;
    std::vector<LogEntry> logs;
    std::thread processingThread;
    std::atomic<bool> stopProcessing;
};

// Example usage
int main() {
    Logger logger(100);

    // Start log processing in the background
    logger.startProcessing();

    // Simulate adding logs from different components
    for (int i = 0; i < 150; ++i) {
        logger.addLogEntry(i % 5, "Component log message", nullptr);
    }

    std::this_thread::sleep_for(std::chrono::seconds(1));

    // Retrieve and print the summary report
    Logger::Report report = logger.getSummaryReport();
    std::cout << "Total Logs: " << report.totalLogCount
              << ", Average Log Size: " << report.averageLogSize
              << ", Malformed Proportion: " << report.malformedProportion << std::endl;

    // Stop the logger
    logger.stop();

    return 0;
}
```

### Key Features:
- **Thread Safety**: Uses `std::mutex` and `std::condition_variable` to ensure thread-safe access.
- **Non-blocking Processing**: Processes logs in a background thread, allowing concurrent log additions.
- **Log Pruning**: Maintains a maximum size by pruning older logs when necessary.
- **Integration with Logging Framework**: Simulates logging framework integration for each entry added.
- **Summary Report**: Provides statistics on processed logs without interfering with core functionality.']

