#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int id;
    char *description;
    char status[20];
} Job;

typedef struct {
    Job **jobs;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    FILE *log_file;
} JobCollection;

JobCollection* create_job_collection(size_t initial_capacity, const char *log_filename) {
    JobCollection *collection = (JobCollection *)malloc(sizeof(JobCollection));
    collection->jobs = (Job **)calloc(initial_capacity, sizeof(Job *));
    collection->capacity = initial_capacity;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);
    collection->log_file = fopen(log_filename, "a");
    if (!collection->log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    return collection;
}

void log_action(const char *message) {
    time_t now = time(NULL);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline
    pthread_mutex_lock(&log_file->lock);
    fprintf(log_file, "[%s] %s\n", time_str, message);
    fflush(log_file);
    pthread_mutex_unlock(&log_file->lock);
}

Job* allocate_job(int id, const char *description) {
    Job *job = (Job *)malloc(sizeof(Job));
    job->id = id;
    job->description = strdup(description);
    strcpy(job->status, "pending");
    return job;
}

void ensure_capacity(JobCollection *collection) {
    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Job **new_jobs = (Job **)realloc(collection->jobs, new_capacity * sizeof(Job *));
        if (!new_jobs) {
            perror("Failed to reallocate memory");
            exit(EXIT_FAILURE);
        }
        collection->jobs = new_jobs;
        collection->capacity = new_capacity;
    }
}

void add_job(JobCollection *collection, int id, const char *description) {
    pthread_mutex_lock(&collection->lock);

    ensure_capacity(collection);

    Job *job = allocate_job(id, description);
    collection->jobs[collection->count++] = job;

    char log_message[256];
    snprintf(log_message, sizeof(log_message), "Job created: ID %d", id);
    log_action(log_message);

    pthread_mutex_unlock(&collection->lock);
}

Job* find_job(JobCollection *collection, int id) {
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->jobs[i]->id == id) {
            return collection->jobs[i];
        }
    }
    return NULL;
}

void update_job_status(JobCollection *collection, int id, const char *new_status) {
    pthread_mutex_lock(&collection->lock);

    Job *job = find_job(collection, id);
    if (job) {
        strcpy(job->status, new_status);

        char log_message[256];
        snprintf(log_message, sizeof(log_message), "Job ID %d status updated to: %s", id, new_status);
        log_action(log_message);
    } else {
        char error_message[256];
        snprintf(error_message, sizeof(error_message), "Job with ID %d not found", id);
        fprintf(stderr, "%s\n", error_message);
    }

    pthread_mutex_unlock(&collection->lock);
}

void free_job_collection(JobCollection *collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->jobs[i]->description);
        free(collection->jobs[i]);
    }
    free(collection->jobs);
    fclose(collection->log_file);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

void simulate_delay() {
    // Simulate delay for fetching job descriptions
    usleep(100000); // 100ms delay
}
