import java.io.*;
import java.nio.file.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class ServerManager {

    private static final String CONFIG_FILE_NAME = "server.config";
    private static final long MAX_LOG_SIZE = 10 * 1024 * 1024; // 10 MB
    private static final int LOG_ROTATION_COUNT = 5;
    private static final Path ARCHIVE_DIR = Paths.get("archive");
    private static final Logger logger = Logger.getLogger(ServerManager.class.getName());

    public static void main(String[] args) {
        if (args.length != 2) {
            System.err.println("Usage: java ServerManager <config_directory> <server_executable>");
            System.exit(1);
        }

        Path configDir = Paths.get(args[0]);
        Path serverExecutable = Paths.get(configDir, args[1]);

        setupLogger();
        try {
            archiveConfigFile(configDir);
            launchServer(serverExecutable);
        } catch (IOException | InterruptedException e) {
            logger.log(Level.SEVERE, "Failed to manage server process", e);
        }
    }

    private static void setupLogger() throws IOException {
        FileHandler fileHandler = new FileHandler("server.log", MAX_LOG_SIZE, LOG_ROTATION_COUNT, true);
        fileHandler.setFormatter(new SimpleFormatter());
        logger.addHandler(fileHandler);

        Logger rootLogger = Logger.getLogger("");
        for (Handler handler : rootLogger.getHandlers()) {
            if (!(handler instanceof ConsoleHandler)) {
                rootLogger.removeHandler(handler);
            }
        }

        System.setErr(new PrintStream(new TeeOutputStream(System.err, fileHandler)));
        System.setOut(new PrintStream(new TeeOutputStream(System.out, fileHandler)));
    }

    private static void archiveConfigFile(Path configDir) throws IOException {
        Path configFile = configDir.resolve(CONFIG_FILE_NAME);
        if (Files.exists(configFile)) {
            Files.createDirectories(ARCHIVE_DIR);
            Path targetPath = ARCHIVE_DIR.resolve(configFile.getFileName().toString() + "-" +
                    System.currentTimeMillis());
            int counter = 1;
            while (Files.exists(targetPath)) {
                targetPath = ARCHIVE_DIR.resolve(configFile.getFileName().toString() + "-" +
                        System.currentTimeMillis() + "-" + counter++);
            }
            Files.move(configFile, targetPath);
        }
    }

    private static void launchServer(Path serverExecutable) throws IOException, InterruptedException {
        ScheduledExecutorService executor = Executors.newScheduledThreadPool(1);

        Runnable startTask = () -> {
            try (ProcessBuilder processBuilder = new ProcessBuilder(serverExecutable.toString())) {
                Process process = processBuilder.start();
                redirectStreams(process);
                monitorProcess(process);
            } catch (IOException e) {
                logger.log(Level.WARNING, "Failed to launch server: " + e.getMessage());
                retryStartingServer(executor, serverExecutable);
            }
        };

        executor.scheduleWithFixedDelay(startTask, 0, 10, TimeUnit.SECONDS);
    }

    private static void redirectStreams(Process process) throws IOException {
        try (InputStreamReader inputStreamReader = new InputStreamReader(process.getInputStream());
             BufferedReader bufferedReader = new BufferedReader(inputStreamReader);
             InputStreamReader errorInputStreamReader = new InputStreamReader(process.getErrorStream());
             BufferedReader errorBufferedReader = new BufferedReader(errorInputStreamReader)) {

            String line;
            while ((line = bufferedReader.readLine()) != null) {
                logger.info(line);
            }

            while ((line = errorBufferedReader.readLine()) != null) {
                logger.severe(line);
            }
        }
    }

    private static void monitorProcess(Process process) throws IOException, InterruptedException {
        int exitCode;
        do {
            exitCode = process.waitFor(1, TimeUnit.SECONDS);
            if (exitCode == 0) break;
            logger.log(Level.WARNING, "Server exited with code: " + exitCode);
        } while (true);
    }

    private static void retryStartingServer(ScheduledExecutorService executor, Path serverExecutable)
            throws InterruptedException {
        logger.info("Retrying to start the server...");
        try {
            Thread.sleep(5000); // Wait before retrying
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw e;
        }
    }

    private static void shutdownExecutor(ScheduledExecutorService executor) {
        executor.shutdownNow();
        try {
            if (!executor.awaitTermination(5, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }
    }
}
```

### Explanation

- **Configuration File Management**: The application checks for a configuration file and archives it with a timestamp to avoid overwriting.

- **Server Launching**: Uses `ProcessBuilder` to launch the server executable, retrying if initial attempts fail due to resource constraints.

- **Stream Redirection**: Redirects both standard output and error streams to a log file using `FileHandler`.

- **Log Rotation**: Implements log rotation with a maximum size and count of archived logs.

- **Graceful Shutdown**: Although not fully implemented here, the structure allows for clean shutdown by monitoring process exit codes.

- **Concurrency and Efficiency**: Uses `ScheduledExecutorService` for managing retries without blocking the main thread.

This code provides a robust framework for managing a local server process, with considerations for error handling, logging, and resource management.']

