record* create_managed_records(int n, double min, double max) {
    if (n <= 0 || min >= max) return NULL;

    srand(time(NULL));

    long *offsets = (long *)malloc(n * sizeof(long));
    int *keys = (int *)malloc(n * sizeof(int));
    record *records = (record *)malloc(n * sizeof(record));

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    for (int i = 0; i < n; ++i) {
        offsets[i] = rand() % 100000; // Example offset generation
        keys[i] = rand() % 1000;      // Example key generation

        double random_value = min + ((double)rand() / RAND_MAX * (max - min));
        records[i].key = keys[i];
        records[i].offset = offsets[i];
        records[i].value = (float)random_value;
    }

    free(offsets);
    free(keys);

    return records;
}
