```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define DEFAULT_KEY_RANGE (1000)
#define INITIAL_DEVICE_COUNT (10)

typedef struct {
    int key;
    long offset;
    float value;
} Record;

typedef struct {
    float current_power_consumption;
    float temperature;
    unsigned long last_uptime;
    int error_count;
} DeviceState;

typedef struct {
    size_t record_size;
    size_t device_state_size;
    void* memory_block;
    size_t capacity; // total number of records
    pthread_mutex_t lock;
    float min_power_consumption;
    float max_power_consumption;
    float avg_power_consumption;
    int device_count;

    FILE *log_file;
} MemoryManager;

static unsigned long seed = 12345;

float generate_random_float(float min, float max) {
    float r = ((float)rand_r(&seed)) / RAND_MAX;
    return min + r * (max - min);
}

void log_event(const char* event) {
    fprintf(stderr, "Event: %s\n", event);
}

MemoryManager* init_memory_manager(size_t capacity) {
    MemoryManager *manager = malloc(sizeof(MemoryManager));
    if (!manager) return NULL;

    manager->record_size = sizeof(Record);
    manager->device_state_size = sizeof(DeviceState);
    size_t total_size = capacity * (manager->record_size + manager->device_state_size);

    pthread_mutex_init(&manager->lock, NULL);
    manager->memory_block = malloc(total_size);
    if (!manager->memory_block) {
        free(manager);
        return NULL;
    }

    manager->capacity = capacity;
    manager->min_power_consumption = FLT_MAX;
    manager->max_power_consumption = -FLT_MAX;
    manager->avg_power_consumption = 0.0f;
    manager->device_count = 0;

    manager->log_file = fopen("system.log", "a");
    if (!manager->log_file) {
        free(manager->memory_block);
        free(manager);
        return NULL;
    }

    srand(seed); // Initialize pseudo-random number generator
    return manager;
}

int resize_memory_manager(MemoryManager *manager, size_t new_capacity) {
    pthread_mutex_lock(&manager->lock);

    size_t total_size = new_capacity * (manager->record_size + manager->device_state_size);
    void* new_block = realloc(manager->memory_block, total_size);

    if (!new_block) {
        log_event("Failed to resize memory block.");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    manager->capacity = new_capacity;
    manager->memory_block = new_block;

    log_event("Memory resized successfully.");

    pthread_mutex_unlock(&manager->lock);

    return 0;
}

int initialize_record_and_device_state(MemoryManager *manager, int index) {
    if (index < 0 || index >= manager->capacity)
        return -1;

    void* base = manager->memory_block + index * (manager->record_size + manager->device_state_size);

    Record* record = (Record*)base;
    DeviceState* device_state = (DeviceState*)((char*)base + manager->record_size);

    record->key = rand() % DEFAULT_KEY_RANGE;
    record->offset = index * 10; // Example offset
    record->value = generate_random_float(0.0f, 1.0f);

    float power_consumption = generate_random_float(5.0f, 15.0f);
    device_state->current_power_consumption = (manager->device_count > 0)
        ? manager->avg_power_consumption : power_consumption;

    pthread_mutex_lock(&manager->lock);
    if (power_consumption < manager->min_power_consumption)
        manager->min_power_consumption = power_consumption;
    if (power_consumption > manager->max_power_consumption)
        manager->max_power_consumption = power_consumption;

    float new_avg = ((manager->avg_power_consumption * manager->device_count) + power_consumption) / 
                    (manager->device_count + 1);

    manager->avg_power_consumption = new_avg;
    manager->device_count++;

    log_event("Initialized record and device state.");

    pthread_mutex_unlock(&manager->lock);

    return 0;
}

void cleanup_memory_manager(MemoryManager *manager) {
    if (manager) {
        if (manager->memory_block)
            free(manager->memory_block);

        if (manager->log_file)
            fclose(manager->log_file);

        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

void* update_records_thread(void* arg) {
    MemoryManager *manager = (MemoryManager*)arg;

    for (size_t i = 0; i < manager->capacity; ++i) {
        if (initialize_record_and_device_state(manager, i) != 0)
            log_event("Error initializing record and device state.");
    }

    return NULL;
}

int main() {
    MemoryManager* manager = init_memory_manager(INITIAL_DEVICE_COUNT);
    if (!manager) {
        fprintf(stderr, "Failed to initialize memory manager.\n");
        return EXIT_FAILURE;
    }

    pthread_t thread_id;
    pthread_create(&thread_id, NULL, update_records_thread, (void*)manager);
    pthread_join(thread_id, NULL);

    // Example of resizing
    if (resize_memory_manager(manager, manager->capacity * 2) != 0)
        log_event("Failed to resize memory.");

    cleanup_memory_manager(manager);

    return EXIT_SUCCESS;
}
```

This code implements a custom memory allocator for managing `Record` and `DeviceState` structures. It supports resizing the allocated memory block, initializes records with pseudo-random values, manages power consumption statistics, integrates logging for changes, handles concurrency using mutexes, and includes error handling for resource management. The function can initialize, resize, and clean up memory resources efficiently while providing basic logging functionality.']

