['Below is a C implementation of the described task using pthreads for synchronization, dynamic memory management, and basic cache pruning logic.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>

#define MAX_RECORDS 100
#define VALUE_THRESHOLD 1000

typedef struct record {
    int key;
    int value;
} record;

typedef struct records_cache {
    record *records[MAX_RECORDS];
    size_t count;
    pthread_mutex_t lock;
} records_cache;

void init_records_cache(records_cache *cache) {
    cache->count = 0;
    pthread_mutex_init(&cache->lock, NULL);
}

void free_record(record *rec) {
    if (rec) {
        free(rec);
    }
}

void prune_oldest_entry(records_cache *cache) {
    pthread_mutex_lock(&cache->lock);

    if (cache->count > 0) {
        free_record(cache->records[0]);
        for (size_t i = 1; i < cache->count; ++i) {
            cache->records[i - 1] = cache->records[i];
        }
        cache->records[--cache->count] = NULL;
    }

    pthread_mutex_unlock(&cache->lock);
}

int add_record(records_cache *cache, int key, int value, int threshold) {
    pthread_mutex_lock(&cache->lock);

    if (cache->count >= MAX_RECORDS) {
        prune_oldest_entry(cache);
    }

    int current_sum = 0;
    for (size_t i = 0; i < cache->count; ++i) {
        current_sum += cache->records[i]->value;
    }

    if (current_sum + value > threshold) {
        pthread_mutex_unlock(&cache->lock);
        return -1;
    }

    record *new_rec = malloc(sizeof(record));
    if (!new_rec) {
        pthread_mutex_unlock(&cache->lock);
        return -2; // Memory allocation failed
    }

    new_rec->key = key;
    new_rec->value = value;

    cache->records[cache->count++] = new_rec;

    pthread_mutex_unlock(&cache->lock);

    return 0;
}

void free_records_cache(records_cache *cache) {
    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        if (cache->records[i]) {
            free_record(cache->records[i]);
        }
    }
    pthread_mutex_destroy(&cache->lock);
}
```

### Key Points:
- **Thread Safety**: The use of `pthread_mutex_lock` and `pthread_mutex_unlock` ensures that the cache operations are thread-safe.
- **Dynamic Memory Management**: Records are dynamically allocated, and memory is freed when records are pruned or when the cache is destroyed.
- **Pruning Logic**: Oldest entries are removed if the maximum size (`MAX_RECORDS`) is exceeded.
- **Threshold Check**: Before adding a new record, it checks whether the total value exceeds the specified threshold to ensure data integrity.

This function can be extended for different environments by adjusting constants like `MAX_RECORDS` and integrating more sophisticated synchronization mechanisms or memory management strategies.']

