#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

#define MAX_SESSIONS 1024
#define SESSION_EXPIRY_TIME (60 * 60) // seconds

typedef struct {
    int session_id;
    time_t timestamp;
    void* data; // Pointer to actual session data
} NetworkSession;

typedef struct MemoryPool {
    size_t block_size;
    size_t pool_size;
    unsigned char* memory;
    pthread_mutex_t lock;
    size_t free_list;
} MemoryPool;

MemoryPool pool;

void init_memory_pool(size_t block_size, size_t initial_pool_size) {
    pool.block_size = block_size;
    pool.pool_size = initial_pool_size;
    pool.memory = malloc(block_size * initial_pool_size);
    pthread_mutex_init(&pool.lock, NULL);
    pool.free_list = 0; // No free blocks initially
}

void* memory_pool_alloc() {
    pthread_mutex_lock(&pool.lock);

    if (pool.free_list) {
        void* block = &pool.memory[pool.free_list];
        pool.free_list = *(size_t*)(block); // Get next free block
        pthread_mutex_unlock(&pool.lock);
        return block;
    } else {
        pthread_mutex_unlock(&pool.lock);
        return NULL; // Pool needs resizing or is full
    }
}

void memory_pool_free(void* block) {
    pthread_mutex_lock(&pool.lock);

    *(size_t*)block = pool.free_list;
    pool.free_list = (char*)block - (char*)pool.memory;

    pthread_mutex_unlock(&pool.lock);
}

typedef struct SessionList {
    NetworkSession** sessions;
    size_t capacity;
    size_t count;
    pthread_rwlock_t lock;
} SessionList;

SessionList session_list;

void init_session_list(size_t initial_capacity) {
    session_list.sessions = malloc(initial_capacity * sizeof(NetworkSession*));
    session_list.capacity = initial_capacity;
    session_list.count = 0;
    pthread_rwlock_init(&session_list.lock, NULL);
}

int add_session(NetworkSession* new_session) {
    pthread_rwlock_wrlock(&session_list.lock);

    if (session_list.count >= session_list.capacity) {
        size_t new_capacity = session_list.capacity * 2;
        NetworkSession** new_sessions = realloc(session_list.sessions, new_capacity * sizeof(NetworkSession*));
        if (!new_sessions) {
            pthread_rwlock_unlock(&session_list.lock);
            return -1; // Out of memory
        }
        session_list.sessions = new_sessions;
        session_list.capacity = new_capacity;
    }

    session_list.sessions[session_list.count++] = new_session;

    pthread_rwlock_unlock(&session_list.lock);
    return 0;
}

void cleanup_expired_sessions() {
    time_t now = time(NULL);

    pthread_rwlock_wrlock(&session_list.lock);

    size_t i, j = 0;
    for (i = 0; i < session_list.count; ++i) {
        if ((now - session_list.sessions[i]->timestamp) < SESSION_EXPIRY_TIME) {
            session_list.sessions[j++] = session_list.sessions[i];
        } else {
            // Log session expiration
            free(session_list.sessions[i]->data);
            memory_pool_free(session_list.sessions[i]);
        }
    }

    session_list.count = j;

    pthread_rwlock_unlock(&session_list.lock);
}

void log_event(const char* event) {
    // Non-blocking logging implementation
    printf("%s\n", event); // Placeholder for actual non-blocking logging
}

void get_session_stats() {
    pthread_rwlock_rdlock(&session_list.lock);

    size_t total_sessions = session_list.count;
    time_t now = time(NULL);
    double average_duration = 0.0;
    size_t peak_count = 0;

    if (total_sessions > 0) {
        for (size_t i = 0; i < total_sessions; ++i) {
            average_duration += (now - session_list.sessions[i]->timestamp);
            if (session_list.sessions[i]->data) { // Assume data indicates active sessions
                peak_count++;
            }
        }
        average_duration /= total_sessions;
    }

    printf("Total Sessions: %zu\n", total_sessions);
    printf("Average Session Duration: %.2f seconds\n", average_duration);
    printf("Peak Concurrent Sessions: %zu\n", peak_count);

    pthread_rwlock_unlock(&session_list.lock);
}

void* session_manager_thread(void* arg) {
    while (1) {
        cleanup_expired_sessions();
        sleep(30); // Rate-limit the cleanup process
    }
}

int main() {
    init_memory_pool(sizeof(NetworkSession), 1000);
    init_session_list(100);

    pthread_t cleanup_thread;
    pthread_create(&cleanup_thread, NULL, session_manager_thread, NULL);

    // Simulate adding sessions and managing them...

    return 0;
}
```

### Key Features:
- **Memory Pool**: A custom memory pool is implemented to manage `NetworkSession` allocations efficiently.
- **Thread Safety**: Uses `pthread_rwlock_t` for read-write locks on the session list to ensure thread safety during concurrent access.
- **Cleanup Mechanism**: Periodically cleans up expired sessions with rate-limiting using a separate thread.
- **Logging**: Non-blocking logging is simulated with a simple print statement, which should be replaced with an actual non-blocking logging framework.
- **Metrics Collection**: Efficiently computes session statistics for monitoring purposes.']

