    public class ConfigurationManager : IDisposable
    {
        private readonly ConcurrentDictionary<string, object> _cache = new();
        private readonly ReaderWriterLockSlim _lock = new();
        private readonly string _defaultConfigPath;
        private readonly string _userConfigPath;
        private XDocument _config;

        public ConfigurationManager(string defaultConfigPath, string userConfigPath)
        {
            _defaultConfigPath = defaultConfigPath;
            _userConfigPath = userConfigPath;
            LoadConfigurationFiles();
        }

        private void LoadConfigurationFiles()
        {
            try
            {
                var defaultConfig = XDocument.Load(_defaultConfigPath);
                var userConfig = File.Exists(_userConfigPath) ? XDocument.Load(_userConfigPath) : null;

                _config = MergeConfigs(defaultConfig, userConfig);
                ValidateConfiguration();
                LoadSettingsIntoCache();
            }
            catch (Exception ex)
            {
                LogError("Failed to load configuration files", ex);
            }
        }

        private XDocument MergeConfigs(XDocument defaultConfig, XDocument userConfig)
        {
            if (userConfig == null) return defaultConfig;

            foreach (var element in userConfig.Root.Elements())
            {
                var matchingElement = defaultConfig.Root.Element(element.Name.LocalName);
                if (matchingElement != null)
                    matchingElement.ReplaceWith(element);
                else
                    defaultConfig.Root.Add(element);
            }
            return defaultConfig;
        }

        private void ValidateConfiguration()
        {
            // Implement validation logic here
            // Example: Ensure tile size is within a specific range
        }

        private void LoadSettingsIntoCache()
        {
            _lock.EnterWriteLock();
            try
            {
                foreach (var element in _config.Root.Elements())
                {
                    string key = element.Name.LocalName;
                    if (int.TryParse(element.Value, out int intValue))
                        _cache[key] = intValue;
                    else
                        _cache[key] = element.Value;
                }
            }
            finally
            {
                _lock.ExitWriteLock();
            }
        }

        public T GetSetting<T>(string key)
        {
            _lock.EnterReadLock();
            try
            {
                if (_cache.TryGetValue(key, out var value))
                    return (T)Convert.ChangeType(value, typeof(T));
                throw new KeyNotFoundException($"Key '{key}' not found in configuration.");
            }
            finally
            {
                _lock.ExitReadLock();
            }
        }

        public void UpdateSetting(string key, object newValue)
        {
            _lock.EnterWriteLock();
            try
            {
                var element = _config.Root.Element(key);
                if (element != null)
                    element.Value = newValue.ToString();

                // Invalidate cache and reload settings
                _cache[key] = newValue;
                LogChange(key, newValue);
            }
            finally
            {
                _lock.ExitWriteLock();
            }
        }

        private void LogChange(string key, object value)
        {
            try
            {
                // Integrate with external logging service here
                Console.WriteLine($"[{DateTime.UtcNow}] Configuration changed: {key} = {value}");
            }
            catch (Exception ex)
            {
                LogError("Failed to log configuration change", ex);
            }
        }

        private void LogError(string message, Exception ex)
        {
            // Implement error logging logic here
        }

        public void Dispose()
        {
            _lock.Dispose();
        }
    }

    public class ConfigEditorForm : Form
    {
