#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    void (*on_max_capacity)(void);
    void (*on_compact)(void);
    int enable_history;
    FILE* history_file;
    time_t last_memory_report_time;
    double total_memory_used;
} CRC_Indication_List;

typedef struct {
    unsigned long RNTI;
    time_t timestamp;
} RemovedEntryRecord;

CRC_Indication_List* create_list(size_t initial_capacity, void (*on_max_capacity)(void), void (*on_compact)(void), int enable_history) {
    CRC_Indication_List* list = (CRC_Indication_List*)malloc(sizeof(CRC_Indication_List));
    list->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    list->on_max_capacity = on_max_capacity;
    list->on_compact = on_compact;
    list->enable_history = enable_history;

    if (enable_history) {
        list->history_file = fopen("history.log", "a");
    }

    list->last_memory_report_time = time(NULL);
    list->total_memory_used = 0.0;

    return list;
}

void free_list(CRC_Indication_List* list) {
    pthread_mutex_destroy(&list->mutex);
    if (list->data) free(list->data);
    if (list->history_file) fclose(list->history_file);
    free(list);
}

int add_entry(CRC_Indication_List* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->mutex);

    if (list->size >= list->capacity) {
        if (list->on_max_capacity) list->on_max_capacity();
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }

    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].RNTI == entry.RNTI) {
            pthread_mutex_unlock(&list->mutex);
            return 0;
        }
    }

    int insert_pos = -1;
    for (int i = list->size - 1; i >= 0; --i) {
        if (list->data[i].RX_UE_INFORMATION_TAG < entry.RX_UE_INFORMATION_TAG) {
            insert_pos = i + 1;
            break;
        }
    }

    if (insert_pos == -1) insert_pos = 0;

    memmove(&list->data[insert_pos + 1], &list->data[insert_pos], (list->size - insert_pos) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->data[insert_pos] = entry;
    ++list->size;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int remove_entry_by_rnti(CRC_Indication_List* list, unsigned long rnti) {
    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].RNTI == rnti) {
            if (list->enable_history && list->history_file) {
                fprintf(list->history_file, "Removed: RNTI=%lu at %ld\n", rnti, time(NULL));
                fflush(list->history_file);
            }

            memmove(&list->data[i], &list->data[i + 1], (list->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            --list->size;
            pthread_mutex_unlock(&list->mutex);
            return 0;
        }
    }

    pthread_mutex_unlock(&list->mutex);
    return -1;
}

int update_crcflag(CRC_Indication_List* list, unsigned long rnti, int new_crcflag) {
    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].RNTI == rnti) {
            list->data[i].CRC_INDICATION_REL8_TAG.CRCFLAG = new_crcflag;
            pthread_mutex_unlock(&list->mutex);
            return 0;
        }
    }

    pthread_mutex_unlock(&list->mutex);
    return -1;
}

void compact_list(CRC_Indication_List* list) {
    pthread_mutex_lock(&list->mutex);

    if (list->on_compact) list->on_compact();

    size_t write_index = 0;
    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].CRC_INDICATION_REL8_TAG.CRCFLAG != 0) {
            list->data[write_index++] = list->data[i];
        }
    }

    list->size = write_index;
    pthread_mutex_unlock(&list->mutex);
}

void merge_lists(CRC_Indication_List* dest, CRC_Indication_List* src) {
    pthread_mutex_lock(&dest->mutex);

    for (size_t i = 0; i < src->size; ++i) {
        add_entry(dest, src->data[i]);
    }

    pthread_mutex_unlock(&dest->mutex);
}

void* async_export(void* arg) {
    CRC_Indication_List* list = (CRC_Indication_List*)arg;

    // Simulate export operation
    printf("Exporting data...\n");
    sleep(2);  // Simulating time-consuming operation

    pthread_mutex_lock(&list->mutex);
    printf("Export completed. List size: %zu\n", list->size);
    pthread_mutex_unlock(&list->mutex);

    return NULL;
}

void report_memory_usage(CRC_Indication_List* list) {
    pthread_mutex_lock(&list->mutex);

    double current_time = time(NULL);
    if (current_time - list->last_memory_report_time >= 60) { // Report every minute
        printf("Average memory usage: %.2f bytes\n", list->total_memory_used / ((current_time - list->last_memory_report_time) / 60.0));
        list->last_memory_report_time = current_time;
    }

    pthread_mutex_unlock(&list->mutex);
}

void export_data_async(CRC_Indication_List* list) {
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, async_export, (void*)list);
    pthread_detach(thread_id);
}
