#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_PACKET_SIZE 1500 // Example max packet size in bytes

typedef struct {
    time_t timestamp;
    size_t size;
    void *data;
} Packet;

typedef struct {
    Packet **packets;
    size_t capacity;
    size_t count;
    size_t total_memory;
    pthread_mutex_t mutex;
    pthread_cond_t cond_var;
    FILE *log_file;
    const size_t memory_threshold;
} PacketManager;

// Function prototypes
PacketManager* init_packet_manager(size_t initial_capacity, size_t memory_threshold);
void destroy_packet_manager(PacketManager *manager);
int add_packet(PacketManager *manager, const void *packet_data, size_t packet_size);
void resize_packet_array(PacketManager *manager);

// Initialize the packet manager with given capacity and memory threshold
PacketManager* init_packet_manager(size_t initial_capacity, size_t memory_threshold) {
    PacketManager *manager = (PacketManager *)malloc(sizeof(PacketManager));
    if (!manager) return NULL;

    manager->packets = (Packet **)calloc(initial_capacity, sizeof(Packet *));
    if (!manager->packets) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    manager->total_memory = 0;
    manager->memory_threshold = memory_threshold;

    pthread_mutex_init(&manager->mutex, NULL);
    pthread_cond_init(&manager->cond_var, NULL);

    // Initialize log file
    manager->log_file = fopen("packet_log.txt", "a");
    if (!manager->log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return NULL;
    }

    return manager;
}

// Destroy the packet manager and free resources
void destroy_packet_manager(PacketManager *manager) {
    if (manager) {
        for (size_t i = 0; i < manager->count; ++i) {
            free(manager->packets[i]->data);
            free(manager->packets[i]);
        }
        free(manager->packets);

        pthread_mutex_destroy(&manager->mutex);
        pthread_cond_destroy(&manager->cond_var);

        if (manager->log_file) fclose(manager->log_file);

        free(manager);
    }
}

// Add a packet to the manager's array
int add_packet(PacketManager *manager, const void *packet_data, size_t packet_size) {
    pthread_mutex_lock(&manager->mutex);

    // Validate packet size
    if (packet_size > MAX_PACKET_SIZE || packet_size == 0) {
        fprintf(manager->log_file, "Invalid packet size: %zu\n", packet_size);
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }

    // Check memory usage before adding
    if (manager->total_memory + packet_size > manager->memory_threshold) {
        resize_packet_array(manager); // Resize to accommodate more packets
    }

    // Allocate new packet
    Packet *new_packet = (Packet *)malloc(sizeof(Packet));
    if (!new_packet) {
        fprintf(manager->log_file, "Memory allocation failed\n");
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }

    new_packet->timestamp = time(NULL);
    new_packet->size = packet_size;
    new_packet->data = malloc(packet_size);
    if (!new_packet->data) {
        free(new_packet);
        fprintf(manager->log_file, "Memory allocation failed for packet data\n");
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }

    memcpy(new_packet->data, packet_data, packet_size);

    // Add the packet to the array
    if (manager->count == manager->capacity) {
        resize_packet_array(manager);
    }

    manager->packets[manager->count++] = new_packet;
    manager->total_memory += packet_size;

    fprintf(manager->log_file, "Packet added successfully. Total packets: %zu\n", manager->count);

    pthread_mutex_unlock(&manager->mutex);

    return 0;
}

// Resize the packet array to increase capacity
void resize_packet_array(PacketManager *manager) {
    size_t new_capacity = manager->capacity * 2;

    Packet **new_packets = (Packet **)realloc(manager->packets, new_capacity * sizeof(Packet *));
    if (!new_packets) {
        fprintf(manager->log_file, "Memory reallocation failed\n");
        return;
    }

    memset(new_packets + manager->count, 0, (new_capacity - manager->count) * sizeof(Packet *));

    manager->packets = new_packets;
    manager->capacity = new_capacity;
}
