    size_t capacity_vertices;
    size_t total_edges;
    pthread_mutex_t lock;
} Graph;

void initialize_random_seed() {
    srand(time(NULL));
}

Graph* create_graph(size_t num_vertices, size_t num_edges) {
    if (num_vertices == 0 || num_edges == 0)
        return NULL;

    Graph* graph = malloc(sizeof(Graph));
    if (!graph) return NULL;

    pthread_mutex_init(&graph->lock, NULL);

    graph->capacity_vertices = num_vertices;
    graph->num_vertices = num_vertices;
    graph->total_edges = num_edges;

    // Allocate memory for vertices and edges
    graph->vertex_offsets = malloc(sizeof(long) * (graph->num_vertices + 1));
    if (!graph->vertex_offsets) {
        free(graph);
        return NULL;
    }

    graph->keys = malloc(sizeof(int) * graph->num_vertices);
    if (!graph->keys) {
        free(graph->vertex_offsets);
        free(graph);
        return NULL;
    }

    // Allocate memory for records
    graph->records = malloc(sizeof(record*) * (graph->total_edges));
    if (!graph->records) {
        free(graph->keys);
        free(graph->vertex_offsets);
        free(graph);
        return NULL;
    }

    // Initialize vertices and edges with random properties
    for (size_t i = 0; i < graph->num_vertices; ++i) {
        graph->keys[i] = rand() % 10000;  // Random unique key
        graph->vertex_offsets[i] = (long)i * (rand() % 10 + 1);  // Random offset
    }

    for (size_t i = 0; i < graph->total_edges; ++i) {
        graph->records[i] = malloc(sizeof(record));
        if (!graph->records[i]) {
            // Free previously allocated memory in case of failure
            while (i > 0 && graph->records[--i])
                free(graph->records[i]);
            free(graph->keys);
            free(graph->vertex_offsets);
            free(graph->records);
            free(graph);
            return NULL;
        }
        graph->records[i]->edge_weight = rand() % (EDGE_WEIGHT_MAX - EDGE_WEIGHT_MIN + 1) + EDGE_WEIGHT_MIN; // Random weight
    }

    // Mark end of vertex offsets array
    graph->vertex_offsets[graph->num_vertices] = (long)graph->total_edges;

    return graph;
}

void destroy_graph(Graph* graph) {
    if (!graph) return;

    for (size_t i = 0; i < graph->total_edges; ++i) {
        free(graph->records[i]);
    }
    free(graph->keys);
    free(graph->vertex_offsets);
    free(graph->records);

    pthread_mutex_destroy(&graph->lock);
    free(graph);
}

void resize_graph(Graph* graph, size_t new_vertex_count, size_t new_edge_count) {
    if (!graph || new_vertex_count == 0 || new_edge_count == 0)
        return;

    pthread_mutex_lock(&graph->lock);

    // Resize vertices
    long* new_offsets = realloc(graph->vertex_offsets, sizeof(long) * (new_vertex_count + 1));
    int* new_keys = realloc(graph->keys, sizeof(int) * new_vertex_count);

    if (!new_offsets || !new_keys) {
        pthread_mutex_unlock(&graph->lock);
        return; // Handle allocation failure gracefully
    }

    graph->vertex_offsets = new_offsets;
    graph->keys = new_keys;

    for (size_t i = graph->num_vertices; i < new_vertex_count; ++i) {
        graph->keys[i] = rand() % 10000; 
        graph->vertex_offsets[i] = (long)i * (rand() % 10 + 1);
    }

    // Resize records
    record** new_records = realloc(graph->records, sizeof(record*) * new_edge_count);

    if (!new_records) {
        pthread_mutex_unlock(&graph->lock);
        return; // Handle allocation failure gracefully
    }

    graph->records = new_records;

    for (size_t i = graph->total_edges; i < new_edge_count; ++i) {
        graph->records[i] = malloc(sizeof(record));
        if (!graph->records[i]) {
            // Free newly allocated memory in case of failure
            while (i > graph->total_edges && graph->records[--i])
                free(graph->records[i]);
            break;
        }
        graph->records[i]->edge_weight = rand() % (EDGE_WEIGHT_MAX - EDGE_WEIGHT_MIN + 1) + EDGE_WEIGHT_MIN; 
    }

    // Update metadata
    graph->num_vertices = new_vertex_count;
    graph->total_edges = new_edge_count;
    graph->vertex_offsets[graph->num_vertices] = (long)new_edge_count;

    pthread_mutex_unlock(&graph->lock);
}

void garbage_collect_graph(Graph* graph) {
    if (!graph) return;

    pthread_mutex_lock(&graph->lock);

    // Simple garbage collection: Check and free unused records
    for (size_t i = 0; i < graph->total_edges; ++i) {
        // In a real scenario, check if the record is still in use or needed
        // For demonstration, just assume we can clean up some random records
        if ((rand() % 10) == 0 && graph->records[i]) { 
            free(graph->records[i]);
            graph->records[i] = NULL;
        }
    }

    pthread_mutex_unlock(&graph->lock);
}

int main() {
    initialize_random_seed();

    // Create a default graph
    Graph* graph = create_graph(DEFAULT_NUM_VERTICES, DEFAULT_NUM_EDGES);
    if (!graph) {
        fprintf(stderr, "Failed to create graph\n");
        return 1;
    }

    // Example usage of resizing and garbage collection
    resize_graph(graph, 15, 25); // Resize the graph with more vertices and edges
    garbage_collect_graph(graph);

    destroy_graph(graph);

    return 0;
}
```

