hash_table_t* create_hash_table(size_t bucket_count) {
    hash_table_t *table = malloc(sizeof(hash_table_t));
    if (!table) return NULL;

    table->buckets = calloc(bucket_count, sizeof(hash_table_entry_t *));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    table->bucket_count = bucket_count;
    pthread_mutex_init(&table->lock, NULL);

    return table;
}

void destroy_hash_table(hash_table_t *table) {
    for (size_t i = 0; i < table->bucket_count; ++i) {
        hash_table_entry_t *entry = table->buckets[i];
        while (entry) {
            hash_table_entry_t *temp = entry;
            entry = entry->next;
            free(temp);
        }
    }

    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

unsigned int hash_function(int key, size_t bucket_count) {
    return (unsigned int)(key % bucket_count);
}

void insert_into_hash_table(hash_table_t *table, int key, void *value) {
    unsigned int index = hash_function(key, table->bucket_count);

    pthread_mutex_lock(&table->lock);
    hash_table_entry_t *entry = malloc(sizeof(hash_table_entry_t));
    if (!entry) {
        pthread_mutex_unlock(&table->lock);
        return;
    }

    entry->key = key;
    entry->value = value;
    entry->next = table->buckets[index];
    table->buckets[index] = entry;

    pthread_mutex_unlock(&table->lock);
}

void *get_from_hash_table(hash_table_t *table, int key) {
    unsigned int index = hash_function(key, table->bucket_count);

    pthread_mutex_lock(&table->lock);
    hash_table_entry_t *entry = table->buckets[index];
    while (entry) {
        if (entry->key == key) {
            void *value = entry->value;
            pthread_mutex_unlock(&table->lock);
            return value;
        }
        entry = entry->next;
    }

    pthread_mutex_unlock(&table->lock);
    return NULL;
}

// Logging functions
int log_message(const char *message) {
    printf("[%ld] %s\n", get_current_timestamp(), message);
    return 0;
}

void flush_logs_to_remote_server() {
    // Simulate flushing logs to a remote server
}

long get_current_timestamp() {
    return time(NULL);
}
