    size_t size;
    size_t capacity;
    NFAPI_CRC_INDICATION_PDU_T *array;
    pthread_mutex_t lock; // For simplicity, using mutex; consider more advanced lock-free structures for higher concurrency.
} CRC_Array;

// Function prototypes
CRC_Array* crc_array_create(size_t initial_capacity);
int crc_array_add(CRC_Array* array, const NFAPI_CRC_INDICATION_PDU_T* element);
NFAPI_CRC_INDICATION_PDU_T* crc_array_get(const CRC_Array* array, size_t index);
int crc_array_update(CRC_Array* array, size_t index, const NFAPI_CRC_INDICATION_PDU_T* element);
void crc_array_destroy(CRC_Array* array);

int crc_array_serialize(const CRC_Array* array, const char* filename);
int crc_array_deserialize(CRC_Array* array, const char* filename);

// Implementations
CRC_Array* crc_array_create(size_t initial_capacity) {
    CRC_Array *array = malloc(sizeof(CRC_Array));
    if (!array) return NULL;

    pthread_mutex_init(&array->lock, NULL);
    array->size = 0;
    array->capacity = initial_capacity;
    array->array = malloc(array->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->array) {
        free(array);
        return NULL;
    }

    return array;
}

int crc_array_add(CRC_Array* array, const NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&array->lock);

    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Memory allocation failed
        }
        array->capacity = new_capacity;
        array->array = new_array;
    }

    memcpy(&array->array[array->size], element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array->size++;

    pthread_mutex_unlock(&array->lock);
    return 0; // Success
}

NFAPI_CRC_INDICATION_PDU_T* crc_array_get(const CRC_Array* array, size_t index) {
    if (index >= array->size) return NULL;

    pthread_mutex_lock((pthread_mutex_t*)&array->lock); // Copy lock to make it const-correct
    NFAPI_CRC_INDICATION_PDU_T* element = &array->array[index];
    pthread_mutex_unlock(&array->lock);

    return element;
}

int crc_array_update(CRC_Array* array, size_t index, const NFAPI_CRC_INDICATION_PDU_T* element) {
    if (index >= array->size) return -1; // Index out of bounds

    pthread_mutex_lock(&array->lock);
    memcpy(&array->array[index], element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_unlock(&array->lock);

    return 0; // Success
}

void crc_array_destroy(CRC_Array* array) {
    if (array) {
        free(array->array);
        pthread_mutex_destroy(&array->lock);
        free(array);
    }
}

int crc_array_serialize(const CRC_Array* array, const char* filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    fwrite(&array->size, sizeof(size_t), 1, file);
    fwrite(array->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), array->size, file);

    fclose(file);
    return 0; // Success
}

int crc_array_deserialize(CRC_Array* array, const char* filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    size_t size;
    fread(&size, sizeof(size_t), 1, file);

    pthread_mutex_lock(&array->lock); // Lock during deserialization
    free(array->array);

    array->capacity = size;
    array->array = malloc(array->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->array) {
        fclose(file);
        pthread_mutex_unlock(&array->lock);
        return -1; // Memory allocation failed
    }

    fread(array->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), size, file);
    array->size = size;

    pthread_mutex_unlock(&array->lock);
    fclose(file);

    return 0; // Success
}

