// Validate filename against allowed characters and max length
int validate_filename(const char *filename, const Config *config) {
    if (strlen(filename) > config->max_length) {
        log_message("Filename exceeds maximum length.");
        return 0;
    }
    for (size_t i = 0; i < strlen(filename); ++i) {
        if (!strchr(config->allowed_chars, filename[i])) {
            char error_msg[256];
            snprintf(error_msg, sizeof(error_msg), "Invalid character '%c' in filename.", filename[i]);
            log_message(error_msg);
            return 0;
        }
    }
    return 1;
}

// Function to modify the filename
char *modify_filename(const char *original_filename) {
    pthread_mutex_lock(&mutex);

    Config config = load_config("config.txt");

    if (!validate_filename(original_filename, &config)) {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    const char *filename_copy = original_filename;
    size_t len = strlen(filename_copy);
    char *new_filename = malloc(len + 1);
    if (new_filename == NULL) {
        log_message("Memory allocation failed.");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
    strcpy(new_filename, filename_copy);

    const char *last_period = strrchr(filename_copy, '.');
    const char *digit_start = NULL;
    size_t digit_count = 0;

    if (last_period != NULL) {
        for (const char *p = last_period + 1; p < filename_copy + len; ++p) {
            if (!isdigit(*p)) {
                break;
            }
            digit_start = p;
            digit_count++;
        }

        const char *file_type_start = last_period + 1 + digit_count;
        size_t file_type_len = len - (file_type_start - filename_copy);
        char file_type[256] = {0};
        strncpy(file_type, file_type_start, file_type_len);

        if (strlen(file_type) == 0) {
            strcpy(file_type, "txt");
        }

        char *new_ext_pos = strchr(new_filename + strlen(new_filename), '.');
        if (new_ext_pos != NULL) {
            memmove(new_ext_pos + digit_count + 1, new_ext_pos, strlen(new_ext_pos) + 1);
        } else {
            strcat(new_filename, ".");
            new_ext_pos = strrchr(new_filename, '.');
        }

        strncpy(new_ext_pos + 1, file_type, strlen(file_type));
        if (digit_start != NULL) {
            memmove(new_ext_pos, digit_start, digit_count);
        }
    } else {
        char *new_ext_pos = strcat(new_filename, ".txt");
        strcpy(new_ext_pos, "txt");
    }

    char log_msg[512];
    snprintf(log_msg, sizeof(log_msg), "Original: %s, Modified: %s", original_filename, new_filename);
    log_message(log_msg);

    pthread_mutex_unlock(&mutex);
    return new_filename;
}

// Example usage
