    const char *filename = "log123.2023-10-01.txt";
    char *new_filename = modify_filename(filename);
    if (new_filename != NULL) {
        printf("Modified filename: %s\n", new_filename);
        free(new_filename);
    } else {
        printf("Filename modification failed.\n");
    }
    return 0;
}
