#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_INPUTS 15000
#define OFFSET_ARRAY_SIZE 1000
#define KEY_ARRAY_SIZE 500
#define RECORD_ARRAY_SIZE 200
#define RNTI_MIN 1
#define RNTI_MAX 65535

typedef struct {
    int int_value;
} record_t;

typedef struct {
    unsigned short RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void log_message(const char *message) {
    printf("%s\n", message);
}

int validate_rnti(unsigned short rnti) {
    return (rnti >= RNTI_MIN && rnti <= RNTI_MAX);
}

unsigned short generate_unique_rnti(unsigned short *used_rtnis, size_t count) {
    unsigned short rnti;
    do {
        rnti = rand() % (RNTI_MAX - RNTI_MIN + 1) + RNTI_MIN;
    } while (!validate_rnti(rnti) || !bsearch(&rnti, used_rtnis, count, sizeof(unsigned short), memcmp));
    return rnti;
}

void* dynamic_memory_management(void *arg) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    long *offset_array = malloc(OFFSET_ARRAY_SIZE * sizeof(long));
    int *key_array = malloc(KEY_ARRAY_SIZE * sizeof(int));
    record_t *record_array = malloc(RECORD_ARRAY_SIZE * sizeof(record_t));

    if (!offset_array || !key_array || !record_array) {
        log_message("Memory allocation failed");
        return NULL;
    }

    for (size_t i = 0; i < OFFSET_ARRAY_SIZE; ++i) {
        offset_array[i] = rand() % 10000L;
    }
    for (size_t i = 0; i < KEY_ARRAY_SIZE; ++i) {
        key_array[i] = rand() % 1000;
    }
    for (size_t i = 0; i < RECORD_ARRAY_SIZE; ++i) {
        record_array[i].int_value = rand() % 10000;
    }

    int *input_buffer = NULL;
    size_t input_count = 0;

    while (1) {
        int value;
        if (scanf("%d", &value) != 1) break;
        if (input_count >= MAX_INPUTS) break;

        pthread_mutex_lock(&lock);
        input_buffer = realloc(input_buffer, (input_count + 1) * sizeof(int));
        if (!input_buffer) {
            log_message("Reallocation failed");
            free(offset_array);
            free(key_array);
            free(record_array);
            return NULL;
        }
        input_buffer[input_count++] = value;
        pthread_mutex_unlock(&lock);
    }

    NFAPI_CRC_INDICATION_PDU_T *indication_pdu_list = malloc(input_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!indication_pdu_list) {
        log_message("Memory allocation for PDU list failed");
        free(offset_array);
        free(key_array);
        free(record_array);
        free(input_buffer);
        return NULL;
    }

    unsigned short used_rtnis[input_count];
    memset(used_rtnis, 0, input_count * sizeof(unsigned short));

    for (size_t i = 0; i < input_count; ++i) {
        indication_pdu_list[i].RX_UE_INFORMATION_TAG = (unsigned short)input_buffer[i];
        indication_pdu_list[i].RNTI = generate_unique_rnti(used_rtnis, i);
        used_rtnis[i] = indication_pdu_list[i].RNTI;
        indication_pdu_list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }

    for (size_t i = 0; i < input_count; ++i) {
        if (!validate_rnti(indication_pdu_list[i].RNTI)) {
            log_message("Invalid RNTI detected");
        }
        if (!(indication_pdu_list[i].CRC_INDICATION_REL8_TAG.CRCFLAG == 0 || indication_pdu_list[i].CRC_INDICATION_REL8_TAG.CRCFLAG == 1)) {
            log_message("Invalid CRCFLAG detected");
        }
    }

    free(offset_array);
    free(key_array);
    free(record_array);
    free(input_buffer);
    free(indication_pdu_list);

    pthread_mutex_destroy(&lock);
    return NULL;
}

int main() {
    srand(time(NULL));
    dynamic_memory_management(NULL);
    return 0;
}
