['Below is a simplified implementation of your task in C. It focuses on memory allocation, thread safety using mutexes, and basic TIFF parsing with metadata extraction. Note that handling TIFF images typically requires third-party libraries like libtiff.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <inttypes.h>
#include <string.h>
#include <time.h>

// Define a record structure
typedef struct {
    int value;
    int *keyRef;
} Record;

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize arrays and records
void* init_arrays_and_records(size_t num_offsets, size_t num_keys, long range_min, long range_max) {
    pthread_mutex_lock(&mutex);

    // Allocate memory for offsets and keys
    long *offsets = (long *)malloc(num_offsets * sizeof(long));
    int *keys = (int *)malloc(num_keys * sizeof(int));

    if (!offsets || !keys) {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    // Initialize keys with random values
    srand(time(NULL));
    for (size_t i = 0; i < num_keys; ++i) {
        keys[i] = rand() % 100; // Example initialization
    }

    // Allocate memory for records
    Record *records = (Record *)malloc(num_offsets * sizeof(Record));

    if (!records) {
        free(offsets);
        free(keys);
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    long total_sum = 0;

    // Initialize records with random values and references to keys
    for (size_t i = 0; i < num_offsets; ++i) {
        offsets[i] = rand() % (range_max - range_min + 1) + range_min;

        // Adjust the range based on total_sum
        long adjusted_range = (long)(rand() % (range_max - range_min + 1)) + range_min;

        records[i].value = adjusted_range;
        total_sum += records[i].value;

        if (total_sum > INT_MAX) {
            printf("Integer overflow detected. Adjusting sum...\n");
            total_sum -= records[i].value; // Rollback
        }

        records[i].keyRef = &keys[i % num_keys]; // Reference a key based on offset
    }

    pthread_mutex_unlock(&mutex);

    // Free allocated memory after use (for demonstration)
    free(offsets);
    free(keys);
    free(records);

    return NULL;
}

// Dummy function to simulate TIFF metadata extraction and checksum calculation
void* extract_tiff_metadata(const char *filename) {
    pthread_mutex_lock(&mutex);

    // Simulate metadata extraction
    printf("Extracting TIFF metadata from %s...\n", filename);

    int bits_per_sample = 8; // Example value
    int samples_per_pixel = 3; // Example value
    int extra_samples = 2; // Example value

    // Simulate checksum calculation (dummy)
    unsigned char *checksum = (unsigned char *)malloc(16);
    if (!checksum) {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
    memset(checksum, 0xAB, 16); // Dummy checksum

    printf("Bits per sample: %d\n", bits_per_sample);
    printf("Samples per pixel: %d\n", samples_per_pixel);
    printf("Extra samples: %d\n", extra_samples);

    // Print checksum
    for (int i = 0; i < 16; ++i) {
        printf("%02X", checksum[i]);
    }
    printf("\n");

    free(checksum);
    pthread_mutex_unlock(&mutex);

    return NULL;
}

int main() {
    size_t num_offsets = 100;
    size_t num_keys = 50;
    long range_min = 0;
    long range_max = 100;

    init_arrays_and_records(num_offsets, num_keys, range_min, range_max);
    extract_tiff_metadata("example.tiff");

    return 0;
}
```

### Key Points:

1. **Memory Allocation**: Memory is allocated for offsets, keys, and records. The function ensures memory is freed after use.

2. **Thread Safety**: A mutex (`pthread_mutex_t`) is used to ensure thread safety when accessing shared resources.

3. **Random Initialization**: Offsets and record values are initialized with random numbers within a specified range. Adjustments are made to prevent integer overflow.

4. **TIFF Metadata Simulation**: The TIFF parsing part is simulated, as actual implementation would require using a library like libtiff.

5. **Checksum Calculation**: A dummy checksum calculation is shown for demonstration purposes.

This code provides a starting point and can be expanded with real TIFF handling and more sophisticated concurrency management based on your specific requirements.']

