['```csharp
using System;
using System.Collections.Concurrent;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Memory;

public class MessageProcessingService : IDisposable
{
    private readonly TripleDESCryptoServiceProvider _tripleDesProvider = new();
    private readonly HMACSHA256 _hmacSha256 = new();
    private readonly IMemoryCache _cache = new MemoryCache(new MemoryCacheOptions());
    private readonly ConcurrentDictionary<string, Tuple<byte[], byte[]>> _cachedKeysIvs;
    private readonly IMessageBroker _messageBroker;

    public MessageProcessingService(IMessageBroker messageBroker)
    {
        _messageBroker = messageBroker ?? throw new ArgumentNullException(nameof(messageBroker));
        _cachedKeysIvs = new ConcurrentDictionary<string, Tuple<byte[], byte[]>>();
    }

    public async Task ProcessStreamAsync(Stream base64EncodedMessagesStream, string tripleDesKeyBase64, string ivBase64, string hmacSecretKey)
    {
        if (string.IsNullOrEmpty(tripleDesKeyBase64) || string.IsNullOrEmpty(ivBase64) || string.IsNullOrEmpty(hmacSecretKey))
            throw new ArgumentException("Keys and IV must be provided.");

        byte[] tripleDesKey = Convert.FromBase64String(tripleDesKeyBase64);
        byte[] iv = Convert.FromBase64String(ivBase64);

        using var hmacProvider = new HMACSHA256(Convert.FromBase64String(hmacSecretKey));

        int position = 0;
        string cacheKeyPrefix = "DecryptedMessage_";

        try
        {
            using (var reader = new StreamReader(base64EncodedMessagesStream))
            {
                string line;
                while ((line = await reader.ReadLineAsync()) != null)
                {
                    position++;
                    if (_cache.TryGetValue(cacheKeyPrefix + position, out var cachedMessage))
                    {
                        continue; // Skip already processed messages
                    }

                    try
                    {
                        byte[] encryptedBytes = Convert.FromBase64String(line);
                        Tuple<byte[], byte[]> keyIvCacheEntry = _cachedKeysIvs.GetOrAdd("TripleDesIv", _ => new Tuple<byte[], byte[]>(tripleDesKey, iv));

                        using (var memoryStream = new MemoryStream(encryptedBytes))
                        {
                            using var cryptoStream = new CryptoStream(memoryStream, _tripleDesProvider.CreateDecryptor(keyIvCacheEntry.Item1, keyIvCacheEntry.Item2), CryptoStreamMode.Read);
                            byte[] decryptedMessage = new byte[encryptedBytes.Length];
                            int bytesRead = await cryptoStream.ReadAsync(decryptedMessage, 0, decryptedMessage.Length);

                            string receivedHmacBase64 = line.Substring(line.LastIndexOf(',') + 1).Trim();
                            byte[] receivedHmac = Convert.FromBase64String(receivedHmacBase64);
                            byte[] calculatedHmac = hmacProvider.ComputeHash(decryptedMessage[..bytesRead]);

                            if (receivedHmac.SequenceEqual(calculatedHmac))
                            {
                                _cache.Set(cacheKeyPrefix + position, decryptedMessage[..bytesRead], TimeSpan.FromMinutes(10));
                            }
                            else
                            {
                                LogError(position, "Invalid HMAC");
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        LogError(position, $"Decryption failed: {ex.Message}");
                    }
                }
            }
        }
        finally
        {
            await _messageBroker.CompleteAsync();
        }
    }

    private void LogError(int position, string errorMessage)
    {
        // Implement logging mechanism with detailed error information
        Console.WriteLine($"Position: {position}, Error: {errorMessage}");
    }

    public async Task SendMessageAsync(string originalMessage, string tripleDesKeyBase64, string hmacSecretKey)
    {
        if (string.IsNullOrEmpty(tripleDesKeyBase64) || string.IsNullOrEmpty(hmacSecretKey))
            throw new ArgumentException("Keys must be provided.");

        byte[] key = Convert.FromBase64String(tripleDesKeyBase64);
        using var hmacProvider = new HMACSHA256(Convert.FromBase64String(hmacSecretKey));

        _tripleDesProvider.Key = key;
        _tripleDesProvider.Mode = CipherMode.CBC;

        string ivBase64 = Convert.ToBase64String(_tripleDesProvider.IV);
        byte[] encryptedMessageBytes;

        using var memoryStream = new MemoryStream();
        using (var cryptoStream = new CryptoStream(memoryStream, _tripleDesProvider.CreateEncryptor(key, _tripleDesProvider.IV), CryptoStreamMode.Write))
        {
            await cryptoStream.WriteAsync(Encoding.UTF8.GetBytes(originalMessage), 0, originalMessage.Length);
            encryptedMessageBytes = memoryStream.ToArray();
        }

        byte[] hmac = hmacProvider.ComputeHash(encryptedMessageBytes);
        string base64EncodedEncryptedMessage = Convert.ToBase64String(encryptedMessageBytes) + "," + Convert.ToBase64String(hmac);

        await _messageBroker.SendAsync(base64EncodedEncryptedMessage);
    }

    public void Dispose()
    {
        _tripleDesProvider.Dispose();
        _hmacSha256?.Dispose();
        // Dispose other resources if necessary
    }
}

public interface IMessageBroker
{
    Task SendAsync(string message);
    Task CompleteAsync();
}
```

### Key Points:
- This code implements a service that processes Base64-encoded, Triple DES encrypted messages with HMAC-SHA256 verification.
- Messages are decrypted and verified for integrity; successful ones are cached, while failures are logged.
- The service handles encryption and decryption of messages using the provided keys and IVs.
- It integrates with an `IMessageBroker` interface to handle message sending and completion operations.
- The service uses efficient caching and ensures proper disposal of cryptographic resources.']

