#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_RECORDS 10000

typedef struct {
    long offset;
    int key;
    unsigned long id; // Unique identifier for tracking purposes
} record;

typedef struct {
    record *records[MAX_RECORDS];
    size_t count;
    pthread_mutex_t lock;
} collection;

// Function to initialize a new collection
collection* create_collection() {
    collection *col = (collection *)malloc(sizeof(collection));
    if (!col) return NULL;

    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        col->records[i] = NULL;
    }
    col->count = 0;
    pthread_mutex_init(&col->lock, NULL);

    return col;
}

// Function to add a record to the collection
int add_record(collection *col, long offset, int key, unsigned long id) {
    if (col->count >= MAX_RECORDS) return -1;

    pthread_mutex_lock(&col->lock);

    record *new_rec = (record *)malloc(sizeof(record));
    if (!new_rec) {
        pthread_mutex_unlock(&col->lock);
        return -1;
    }

    new_rec->offset = offset;
    new_rec->key = key;
    new_rec->id = id;

    col->records[col->count++] = new_rec;

    pthread_mutex_unlock(&col->lock);
    return 0;
}

// Function to remove a record from the collection
int remove_record(collection *col, unsigned long id) {
    pthread_mutex_lock(&col->lock);

    for (size_t i = 0; i < col->count; ++i) {
        if (col->records[i] && col->records[i]->id == id) {
            free(col->records[i]);
            col->records[i] = col->records[--col->count];
            break;
        }
    }

    pthread_mutex_unlock(&col->lock);
    return 0;
}

// Function to update offset values from an external data source
void update_offsets(collection *col, long (*external_update)(unsigned long id)) {
    pthread_mutex_lock(&col->lock);

    for (size_t i = 0; i < col->count; ++i) {
        if (col->records[i]) {
            col->records[i]->offset = external_update(col->records[i]->id);
        }
    }

    pthread_mutex_unlock(&col->lock);
}

// Function to clean up resources
void destroy_collection(collection *col) {
    pthread_mutex_lock(&col->lock);

    for (size_t i = 0; i < col->count; ++i) {
        if (col->records[i]) {
            free(col->records[i]);
        }
    }

    pthread_mutex_unlock(&col->lock);
    pthread_mutex_destroy(&col->lock);
    free(col);
}

// Example external update function
long example_external_update(unsigned long id) {
    // Simulate fetching updated offset from an external source
    return (long)(id * 1000); // Dummy implementation
}
```

### Key Points:
- **Thread Safety**: Mutex locks are used to ensure thread-safe access and modification of collections.
- **Memory Management**: Dynamic allocation is used for records, with cleanup functions ensuring no memory leaks.
- **Resource Limits**: The function checks if the collection has reached its capacity before adding new records.
- **Efficiency**: Minimizes contention by using fine-grained locking on individual operations."]

