#define MAX_PACKETS 10000

typedef struct {
    long timestamp;
    size_t packet_size;
    void *data;
    char type; // Additional metadata field for the packet type
} Packet;

typedef struct {
    Packet packets[MAX_PACKETS];
    int count;
    pthread_mutex_t lock;
} PacketArray;

PacketArray* initialize_packet_array() {
    PacketArray *array = (PacketArray *)malloc(sizeof(PacketArray));
    if (!array) return NULL;

    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

int validate_packet(const void *data, size_t packet_size, char expected_type) {
    // Implement packet validation logic here
    // Return 1 for valid packets and 0 otherwise
    return 1; // Placeholder
}

void add_packet(PacketArray *array, long timestamp, void *data, size_t packet_size, char type) {
    if (!validate_packet(data, packet_size, type)) {
        fprintf(stderr, "Invalid packet data or type mismatch.\n");
        return;
    }

    pthread_mutex_lock(&array->lock);

    if (array->count >= MAX_PACKETS) {
        pthread_mutex_unlock(&array->lock);
        fprintf(stderr, "Packet array is full. Cannot add more packets.\n");
        return;
    }

    Packet *new_packet = &array->packets[array->count++];
    new_packet->timestamp = timestamp;
    new_packet->packet_size = packet_size;
    new_packet->data = data; // Consider copying the data to manage its lifecycle
    new_packet->type = type;

    pthread_mutex_unlock(&array->lock);
}

void clear_packet_array(PacketArray *array) {
    if (!array) return;

    pthread_mutex_lock(&array->lock);

    for (int i = 0; i < array->count; ++i) {
        free(array->packets[i].data); // Ensure proper cleanup of packet data
        array->packets[i].data = NULL;
    }

    array->count = 0;

    pthread_mutex_unlock(&array->lock);
}

void destroy_packet_array(PacketArray *array) {
    if (!array) return;

    clear_packet_array(array);

    pthread_mutex_destroy(&array->lock);
    free(array);
}
