#define MAX_NODES 1000
#define MAX_EDGES 5000
#define WORKLOAD_COUNT 100

typedef struct Edge {
    int target;
    double weight;
} Edge;

typedef struct Node {
    int id;
    Edge *edges;
    size_t edge_count;
    pthread_mutex_t lock; // Lock for thread-safe operations on the node
} Node;

Node* nodes[MAX_NODES];
pthread_mutex_t graph_lock = PTHREAD_MUTEX_INITIALIZER;

// Workload structure
typedef struct {
    time_t timestamp;
    int priority;
    int processing_unit_key;
} Workload;

Workload workloads[WORKLOAD_COUNT];
int workload_count = 0;
pthread_mutex_t workload_lock = PTHREAD_MUTEX_INITIALIZER;

// Processing units array
int processing_units[MAX_NODES];

void init_node(int id) {
    nodes[id] = (Node*)malloc(sizeof(Node));
    nodes[id]->id = id;
    nodes[id]->edges = NULL;
    nodes[id]->edge_count = 0;
    pthread_mutex_init(&nodes[id]->lock, NULL);
}

void add_edge(int from, int to, double weight) {
    pthread_mutex_lock(&graph_lock);

    if (from < 0 || from >= MAX_NODES || to < 0 || to >= MAX_NODES) {
        printf("Invalid node identifiers.\n");
        pthread_mutex_unlock(&graph_lock);
        return;
    }

    Node* node = nodes[from];
    pthread_mutex_lock(&node->lock);

    Edge *new_edges = (Edge*)realloc(node->edges, sizeof(Edge) * (node->edge_count + 1));
    if (!new_edges) {
        printf("Memory allocation failed.\n");
        pthread_mutex_unlock(&node->lock);
        pthread_mutex_unlock(&graph_lock);
        return;
    }
    node->edges = new_edges;

    node->edges[node->edge_count].target = to;
    node->edges[node->edge_count].weight = weight;
    node->edge_count++;

    pthread_mutex_unlock(&node->lock);
    pthread_mutex_unlock(&graph_lock);
}

void remove_edge(int from, int to) {
    if (from < 0 || from >= MAX_NODES) return;

    Node* node = nodes[from];
    pthread_mutex_lock(&node->lock);

    for (size_t i = 0; i < node->edge_count; ++i) {
        if (node->edges[i].target == to) {
            memmove(&node->edges[i], &node->edges[i + 1],
                    sizeof(Edge) * (node->edge_count - i - 1));
            node->edge_count--;
            Edge *new_edges = (Edge*)realloc(node->edges, sizeof(Edge) * node->edge_count);
            if (new_edges != NULL) {
                node->edges = new_edges;
            }
            break;
        }
    }

    pthread_mutex_unlock(&node->lock);
}

int add_workload(int priority, int processing_unit_key) {
    pthread_mutex_lock(&workload_lock);

    if (workload_count >= WORKLOAD_COUNT) {
        printf("Workload queue is full.\n");
        pthread_mutex_unlock(&workload_lock);
        return -1;
    }

    workloads[workload_count].timestamp = time(NULL);
    workloads[workload_count].priority = priority;
    workloads[workload_count].processing_unit_key = processing_unit_key;

    workload_count++;
    pthread_mutex_unlock(&workload_lock);

    return 0; // Success
}

void monitor_average_processing_time(double threshold) {
    double total_time = 0.0;
    int count = 0;

    pthread_mutex_lock(&graph_lock);
    for (int i = 0; i < MAX_NODES; ++i) {
        if (!nodes[i]) continue;

        Node* node = nodes[i];
        pthread_mutex_lock(&node->lock);

        // Simulated processing time calculation
        total_time += count ? (double)rand() / RAND_MAX * node->edge_count : 0;
        count++;

        pthread_mutex_unlock(&node->lock);
    }
    pthread_mutex_unlock(&graph_lock);

    if (count > 0 && (total_time / count) > threshold) {
        printf("Average processing time exceeded: %f\n", total_time / count);
    } else {
        printf("Processing within acceptable limits.\n");
    }
}

void serialize_workloads(const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("File opening failed");
        return;
    }

    pthread_mutex_lock(&workload_lock);

    fwrite(&workload_count, sizeof(int), 1, file);
    fwrite(workloads, sizeof(Workload), workload_count, file);

    fclose(file);
    pthread_mutex_unlock(&workload_lock);
}

void deserialize_workloads(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("File opening failed");
        return;
    }

    int count;
    fread(&count, sizeof(int), 1, file);

    pthread_mutex_lock(&workload_lock);
    workload_count = count;
    fread(workloads, sizeof(Workload), count, file);
    pthread_mutex_unlock(&workload_lock);

    fclose(file);
}

void scale_processing_units(int new_size) {
    if (new_size <= MAX_NODES) {
        printf("Processing units size must be greater than current capacity.\n");
        return;
    }

    int *new_units = realloc(processing_units, sizeof(int) * new_size);
    if (!new_units) {
        perror("Memory allocation failed during scaling.");
        return;
    }
    processing_units = new_units;

    for (int i = MAX_NODES; i < new_size; ++i) {
        processing_units[i] = -1; // Initialize as unused
    }

    printf("Processing units scaled to %d.\n", new_size);
}

// Main function for testing
int main() {
    init_node(0);
    add_edge(0, 1, 1.5);

    if (add_workload(10, 2) == 0)
        printf("Workload added successfully.\n");

    monitor_average_processing_time(0.5);

    serialize_workloads("workloads.dat");
    deserialize_workloads("workloads.dat");

    scale_processing_units(1500);

    return 0;
}
