import java.util.*;
import java.io.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

class DisjointPairProcessor {
    private final int MAX_QUERIES_PER_HOUR = 1000;
    private int queriesThisHour = 0;
    private long lastResetTime;
    private Map<Integer, Integer> parentCache = new ConcurrentHashMap<>();
    private Cache<String, Boolean> validationCache;
    private ExecutorService executorService = Executors.newCachedThreadPool();

    public DisjointPairProcessor() {
        validationCache = Caffeine.newBuilder()
                .expireAfterWrite(1, TimeUnit.HOURS)
                .maximumSize(MAX_QUERIES_PER_HOUR)
                .build();
        lastResetTime = System.currentTimeMillis();
    }

    private class UnionFind {
        private final Map<Integer, Integer> parent;
        private int[] rank;

        public UnionFind() {
            this.parent = new ConcurrentHashMap<>();
            this.rank = new AtomicInteger[Integer.MAX_VALUE];
        }

        public int find(int x) {
            if (!parent.containsKey(x)) return -1;
            if (x != parent.get(x)) parent.put(x, find(parent.get(x)));
            return parent.get(x);
        }

        public void union(int x, int y) {
            int rootX = find(x), rootY = find(y);
            if (rootX == -1 || rootY == -1) return;

            if (rootX != rootY) {
                if (rank[rootX] > rank[rootY]) parent.put(rootY, rootX);
                else {
                    parent.put(rootX, rootY);
                    if (rank[rootX].get() == rank[rootY].get()) rank.incrementAndGet(rootY);
                }
            }
        }

        public void reset() {
            this.parent.clear();
            Arrays.fill(this.rank, 0);
        }

        public synchronized void serialize(String filePath) throws IOException {
            try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream(filePath))) {
                oos.writeObject(parent);
                oos.writeObject(rank);
            }
        }

        @SuppressWarnings("unchecked")
        public void deserialize(String filePath) throws IOException, ClassNotFoundException {
            try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filePath))) {
                this.parent = (Map<Integer, Integer>) ois.readObject();
                this.rank = (int[]) ois.readObject();
            }
        }
    }

    private class PerformanceReport {
        long totalUnionOps;
        long totalFindOps;
        long totalTimeTaken;

        public void log(Operation operation) {
            switch (operation.type) {
                case UNION:
                    totalUnionOps++;
                    break;
                case FIND:
                    totalFindOps++;
                    break;
            }
            totalTimeTaken += operation.duration;
        }

        public String generateReport() {
            return "Total Union Ops: " + totalUnionOps +
                   "\nTotal Find Ops: " + totalFindOps +
                   "\nTotal Time Taken (ms): " + totalTimeTaken;
        }
    }

    private class Operation {
        enum Type { UNION, FIND }

        final Type type;
        final long duration;

        public Operation(Type type, long duration) {
            this.type = type;
            this.duration = duration;
        }
    }

    public void processStream(List<Integer> elements) throws IOException {
        UnionFind uf = new UnionFind();
        PerformanceReport report = new PerformanceReport();

        ScheduledExecutorService scheduledExecutor = Executors.newScheduledThreadPool(1);
        scheduledExecutor.scheduleAtFixedRate(() -> resetQueries(), 0, 1, TimeUnit.HOURS);

        long startTime = System.currentTimeMillis();

        for (int element : elements) {
            if (!uf.parent.containsKey(element)) uf.parent.put(element, element);

            for (Integer otherElement : elements) {
                long findStart = System.nanoTime();
                int rootOther = uf.find(otherElement);
                long findEnd = System.nanoTime();

                report.log(new Operation(Operation.Type.FIND, findEnd - findStart));

                if (otherElement != element && rootOther == uf.find(element)) continue;

                long unionStart = System.nanoTime();
                uf.union(element, otherElement);
                long unionEnd = System.nanoTime();

                report.log(new Operation(Operation.Type.UNION, unionEnd - unionStart));
            }
        }

        long endTime = System.currentTimeMillis();
        System.out.println(report.generateReport());
        System.out.println("Batch Processing Time: " + (endTime - startTime) + " ms");

        uf.serialize("unionFindState.ser");
    }

    private void resetQueries() {
        synchronized (this) {
            queriesThisHour = 0;
            lastResetTime = System.currentTimeMillis();
        }
    }

    public boolean validateDisjoint(int a, int b) throws InterruptedException {
        if (queriesThisHour >= MAX_QUERIES_PER_HOUR)
            throw new RuntimeException("Query limit reached for the current hour.");

        String cacheKey = a + "," + b;

        if (validationCache.asMap().containsKey(cacheKey)) {
            return validationCache.getIfPresent(cacheKey);
        }

        synchronized (this) {
            queriesThisHour++;
        }

        // Simulate external service call
        boolean isDisjoint = simulateExternalValidation(a, b);

        validationCache.put(cacheKey, isDisjoint);
        return isDisjoint;
    }

    private boolean simulateExternalValidation(int a, int b) throws InterruptedException {
        Thread.sleep(50); // Simulate network delay
        return true; // Assume it's always disjoint for the sake of example
    }
}
