#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <limits.h>

typedef struct {
    int value;
    int key_index;
} record_t;

// Global variables and mutexes for thread safety.
static long* offset_values = NULL;
static int* keys = NULL;
static record_t* records = NULL;
static pthread_mutex_t offset_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t key_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t record_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t sum_mutex = PTHREAD_MUTEX_INITIALIZER;

static long global_sum = 0L;
static const long threshold = 1000000; // Example predefined threshold.

// Function to initialize arrays and records safely.
void initialize_memory(int num_records) {
    pthread_mutex_lock(&offset_mutex);
    offset_values = (long*)calloc(num_records, sizeof(long));
    if (!offset_values) {
        perror("Failed to allocate memory for offsets");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_unlock(&offset_mutex);

    pthread_mutex_lock(&key_mutex);
    keys = (int*)malloc(num_records * sizeof(int));
    if (!keys) {
        free(offset_values);
        perror("Failed to allocate memory for keys");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < num_records; ++i) {
        keys[i] = rand() % 1000; // Random key generation example.
    }
    pthread_mutex_unlock(&key_mutex);

    pthread_mutex_lock(&record_mutex);
    records = (record_t*)calloc(num_records, sizeof(record_t));
    if (!records) {
        free(keys);
        free(offset_values);
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }

    long cumulative_sum = 0L;
    for (int i = 0; i < num_records; ++i) {
        int max_value = threshold - cumulative_sum;
        if (max_value <= 0) break;

        // Random value generation within the adjusted range.
        int random_value = rand() % (max_value + 1);

        records[i].value = random_value;
        records[i].key_index = i; // Example: key index same as record index.

        cumulative_sum += random_value;

        pthread_mutex_lock(&sum_mutex);
        global_sum += random_value;
        if (global_sum > threshold) {
            fprintf(stderr, "Global sum exceeded the threshold.\n");
            exit(EXIT_FAILURE);
        }
        pthread_mutex_unlock(&sum_mutex);

        offset_values[i] = cumulative_sum; // Set offset based on cumulative sum.
    }
    pthread_mutex_unlock(&record_mutex);
}

// Function to safely get the current total sum of all records' values.
long get_current_global_sum() {
    long current_sum;
    pthread_mutex_lock(&sum_mutex);
    current_sum = global_sum;
    pthread_mutex_unlock(&sum_mutex);
    return current_sum;
}
