using System;
using System.Collections.Generic;
using UnityEngine;

public class ThemeCacheManager : IDisposable
{
    private const string DefaultThemeDirectory = "Assets/Themes";

    private Dictionary<string, Texture2D> themeCache = new Dictionary<string, Texture2D>();
    private float minFloatRange = 0f;
    private float maxFloatRange = 1f;
    private int minIntRange = 0;
    private int maxIntRange = 100;

    public ThemeCacheManager()
    {
        InitializeDefaultThemeDirectory();
        LoadThemesFromCache();
    }

    private void InitializeDefaultThemeDirectory()
    {
        if (!System.IO.Directory.Exists(DefaultThemeDirectory))
        {
            System.IO.Directory.CreateDirectory(DefaultThemeDirectory);
        }
    }

    private void LoadThemesFromCache()
    {
        var themeFiles = System.IO.Directory.GetFiles(DefaultThemeDirectory, "*.png");
        foreach (var file in themeFiles)
        {
            var texture = new Texture2D(2, 2);
            if (texture.LoadImage(System.IO.File.ReadAllBytes(file)))
            {
                themeCache[Path.GetFileNameWithoutExtension(file)] = texture;
            }
        }
    }

    public void RecycleTheme(string themeName)
    {
        if (themeCache.TryGetValue(themeName, out var texture))
        {
            UnityEngine.Object.Destroy(texture);
            themeCache.Remove(themeName);
        }
    }

    public float GenerateRandomFloat()
    {
        return UnityEngine.Random.Range(minFloatRange, maxFloatRange);
    }

    public int GenerateRandomInt()
    {
        return UnityEngine.Random.Range(minIntRange, maxIntRange + 1);
    }

    public void SetFloatRange(float min, float max)
    {
        if (min >= max) throw new ArgumentException("Min must be less than Max");
        minFloatRange = min;
        maxFloatRange = max;
    }

    public void SetIntRange(int min, int max)
    {
        if (min >= max) throw new ArgumentException("Min must be less than Max");
        minIntRange = min;
        maxIntRange = max;
    }

    public override string ToString()
    {
        return $"Float Range: [{minFloatRange}, {maxFloatRange}], Int Range: [{minIntRange}, {maxIntRange}]";
    }

    public void Dispose()
    {
        foreach (var texture in themeCache.Values)
        {
            UnityEngine.Object.Destroy(texture);
