#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <errno.h>

#define MAX_PACKETS 1024

typedef struct {
    time_t timestamp;
    size_t packet_size;
    void *data;
} Packet;

typedef struct {
    Packet **array;
    size_t length;
    size_t max_packet_size;
    time_t time_window_start;
    time_t time_window_end;
    pthread_mutex_t lock;
    int error_code;
} PacketArray;

void initializePacketArray(PacketArray *packet_array, const size_t max_packet_size, const time_t current_time, const time_t allowed_time_window) {
    if (pthread_mutex_init(&packet_array->lock, NULL) != 0) {
        packet_array->error_code = errno;
        return;
    }

    packet_array->array = malloc(MAX_PACKETS * sizeof(Packet *));
    if (!packet_array->array) {
        packet_array->error_code = ENOMEM;
        pthread_mutex_destroy(&packet_array->lock);
        return;
    }

    packet_array->length = 0;
    packet_array->max_packet_size = max_packet_size;
    packet_array->time_window_start = current_time - allowed_time_window / 2;
    packet_array->time_window_end = current_time + allowed_time_window / 2;
    packet_array->error_code = 0;

    // Simulate receiving packets
    for (size_t i = 0; i < MAX_PACKETS; ++i) {
        pthread_mutex_lock(&packet_array->lock);

        if (packet_array->length >= MAX_PACKETS) {
            pthread_mutex_unlock(&packet_array->lock);
            break;
        }

        // Simulated packet data
        Packet *new_packet = malloc(sizeof(Packet));
        if (!new_packet) {
            pthread_mutex_unlock(&packet_array->lock);
            packet_array->error_code = ENOMEM;
            break;
        }

        new_packet->timestamp = time(NULL); // Assume current time as timestamp for simulation
        new_packet->packet_size = rand() % (max_packet_size * 2); // Random size for simulation

        if (new_packet->packet_size > max_packet_size || 
            new_packet->timestamp < packet_array->time_window_start ||
            new_packet->timestamp > packet_array->time_window_end) {
            free(new_packet);
            pthread_mutex_unlock(&packet_array->lock);
            continue;
        }

        new_packet->data = malloc(new_packet->packet_size);
        if (!new_packet->data) {
            free(new_packet);
            pthread_mutex_unlock(&packet_array->lock);
            packet_array->error_code = ENOMEM;
            break;
        }

        // Simulate filling data
        memset(new_packet->data, 0xAB, new_packet->packet_size);

        packet_array->array[packet_array->length++] = new_packet;

        pthread_mutex_unlock(&packet_array->lock);
    }
}

void cleanupPacketArray(PacketArray *packet_array) {
    if (!packet_array || !packet_array->array) return;

    for (size_t i = 0; i < packet_array->length; ++i) {
        free(packet_array->array[i]->data);
        free(packet_array->array[i]);
    }
    free(packet_array->array);
    pthread_mutex_destroy(&packet_array->lock);
}
```

### Key Points:
