#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_CACHE_SIZE 100
#define MAX_TEMP_READINGS 50
#define TEMP_UNIT_C 'C'
#define TEMP_UNIT_F 'F'

typedef struct {
    int value;
    char *key;
} record;

typedef struct {
    double temperature;
    char unit;
    char quality[8];
} temp_reading;

typedef struct Node {
    record data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t current_size;
    int total_sum;
} RecordCache;

typedef struct {
    temp_reading* readings;
    char** unit_strings;
    double* temperature_values;
    size_t capacity;
    pthread_mutex_t lock;
} TempManager;

RecordCache* initialize_cache(int threshold) {
    RecordCache* cache = malloc(sizeof(RecordCache));
    if (!cache) return NULL;

    cache->head = NULL;
    pthread_mutex_init(&cache->lock, NULL);
    cache->current_size = 0;
    cache->total_sum = 0;

    printf("Initialized record cache with threshold: %d\n", threshold);

    time_t now = time(NULL);
    struct tm* local_time = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", local_time);
    printf("[%s] Cache initialized.\n", timestamp);

    return cache;
}

void prune_cache(RecordCache* cache) {
    if (cache->current_size <= MAX_CACHE_SIZE) return;

    Node** curr = &(cache->head);
    while (*curr && (*curr)->next != NULL) {
        curr = &((*curr)->next);
    }

    if (!(*curr)) return;

    pthread_mutex_lock(&cache->lock);

    Node* to_remove = *curr;
    cache->current_size--;
    cache->total_sum -= to_remove->data.value;

    *curr = (*curr)->next;
    free(to_remove->data.key);
    free(to_remove->data);
    free(to_remove);

    pthread_mutex_unlock(&cache->lock);

    printf("Pruned least recently used record.\n");
}

void add_record(RecordCache* cache, int value, char* key) {
    if (value + cache->total_sum > MAX_CACHE_SIZE) return;

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return;

    new_node->data.value = value;
    new_node->data.key = strdup(key);
    new_node->next = cache->head;

    pthread_mutex_lock(&cache->lock);

    cache->head = new_node;
    cache->current_size++;
    cache->total_sum += value;

    if (cache->current_size > MAX_CACHE_SIZE) {
        prune_cache(cache);
    }

    pthread_mutex_unlock(&cache->lock);

    printf("Added record with key: %s, value: %d\n", key, value);
}

TempManager* initialize_temp_manager(size_t capacity) {
    TempManager* manager = malloc(sizeof(TempManager));
    if (!manager) return NULL;

    manager->readings = malloc(capacity * sizeof(temp_reading));
    manager->unit_strings = malloc(capacity * sizeof(char*));
    manager->temperature_values = malloc(capacity * sizeof(double));

    if (!manager->readings || !manager->unit_strings || !manager->temperature_values) {
        free(manager->readings);
        free(manager->unit_strings);
        free(manager->temperature_values);
        free(manager);
        return NULL;
    }

    manager->capacity = capacity;

    pthread_mutex_init(&manager->lock, NULL);

    printf("Initialized temperature manager with capacity: %zu\n", capacity);

    time_t now = time(NULL);
    struct tm* local_time = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", local_time);
    printf("[%s] Temperature manager initialized.\n", timestamp);

    return manager;
}

void add_temperature_reading(TempManager* manager, double temperature, char unit) {
    if (manager->capacity == 0) return;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->capacity; ++i) {
        strcpy(manager->readings[i].quality, "unknown");
        if (!manager->unit_strings[i]) {
            manager->temperature_values[i] = temperature;
            manager->readings[i].unit = unit;
            manager->unit_strings[i] = malloc(2);
            manager->unit_strings[i][0] = unit;
            manager->unit_strings[i][1] = '\0';
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);

    printf("Added temperature reading: %.2f %c\n", temperature, unit);
}

void cleanup_record_cache(RecordCache* cache) {
    Node* current = cache->head;
    while (current) {
        Node* next = current->next;
        free(current->data.key);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&cache->lock);
    free(cache);
}

void cleanup_temp_manager(TempManager* manager) {
    for (size_t i = 0; i < manager->capacity; ++i) {
        if (manager->unit_strings[i]) {
            free(manager->unit_strings[i]);
        }
    }

    pthread_mutex_destroy(&manager->lock);
    free(manager->readings);
    free(manager->unit_strings);
    free(manager->temperature_values);
    free(manager);
}
```

This code initializes and manages an in-memory data structure for `record` objects, ensuring the sum of integer values does not exceed a threshold. It prunes least recently used records when exceeding cache size. The temperature manager handles concurrent access using mutex locks. Functions to initialize, add records/temperature readings, prune entries, and cleanup are provided with logging for each operation.']

