#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    char type[20];
    size_t size;
} Resource;

typedef struct {
    int value;
    time_t timestamp;
    int status_flag;
    Resource *resource;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t total_resource_size;
    size_t max_objects;
} DynamicCollection;

DynamicCollection* create_collection(size_t max_objects) {
    DynamicCollection* collection = malloc(sizeof(DynamicCollection));
    if (!collection) return NULL;

    collection->head = NULL;
    pthread_mutex_init(&collection->lock, NULL);
    collection->total_resource_size = 0;
    collection->max_objects = max_objects;

    return collection;
}

int add_record(DynamicCollection* collection, const Resource* resource) {
    if (!collection || !resource) return -1;

    pthread_mutex_lock(&collection->lock);

    if (count_records(collection) >= collection->max_objects) {
        pthread_mutex_unlock(&collection->lock);
        return -2; // Collection is full
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&collection->lock);
        return -3; // Memory allocation failed
    }

    srand(time(NULL));
    int random_value = rand() % 100 + 1; // Random value between 1 and 100

    new_node->record.value = random_value;
    new_node->record.timestamp = time(NULL);
    new_node->record.status_flag = 0;
    new_node->record.resource = malloc(sizeof(Resource));
    if (!new_node->record.resource) {
        free(new_node);
        pthread_mutex_unlock(&collection->lock);
        return -4; // Resource allocation failed
    }

    strcpy(new_node->record.resource->type, resource->type);
    new_node->record.resource->size = resource->size;

    collection->total_resource_size += new_node->record.resource->size;

    new_node->next = collection->head;
    collection->head = new_node;

    pthread_mutex_unlock(&collection->lock);
    return 0; // Success
}

int count_records(DynamicCollection* collection) {
    int count = 0;
    Node* current = collection->head;
    while (current) {
        count++;
        current = current->next;
    }
    return count;
}

void serialize_collection(const DynamicCollection* collection, const char* filename) {
    if (!collection || !filename) return;

    pthread_mutex_lock(&collection->lock);

    FILE* file = fopen(filename, "wb");
    if (!file) {
        pthread_mutex_unlock(&collection->lock);
        return;
    }

    Node* current = collection->head;
    while (current) {
        fwrite(&(current->record), sizeof(Record), 1, file);
        current = current->next;
    }

    fclose(file);
    pthread_mutex_unlock(&collection->lock);
}

void deserialize_collection(DynamicCollection* collection, const char* filename) {
    if (!collection || !filename) return;

    pthread_mutex_lock(&collection->lock);

    FILE* file = fopen(filename, "rb");
    if (!file) {
        pthread_mutex_unlock(&collection->lock);
        return;
    }

    Node* current;
    while ((current = malloc(sizeof(Node))) && fread(&(current->record), sizeof(Record), 1, file)) {
        collection->total_resource_size += current->record.resource->size;

        Resource* resource_copy = malloc(sizeof(Resource));
        if (!resource_copy) break; // Handle allocation failure

        strcpy(resource_copy->type, current->record.resource->type);
        resource_copy->size = current->record.resource->size;

        current->record.resource = resource_copy;
        current->next = collection->head;
        collection->head = current;
    }

    fclose(file);

    // Handle potential memory leaks or incomplete reads
    while (collection->head) {
        Node* temp = collection->head;
        collection->head = collection->head->next;
        free(temp->record.resource);
        free(temp);
    }

    pthread_mutex_unlock(&collection->lock);
}

void resize_collection(DynamicCollection* collection, size_t new_max_objects) {
    if (!collection) return;

    pthread_mutex_lock(&collection->lock);

    collection->max_objects = new_max_objects;

    // In this example, the resizing strategy simply updates max capacity,
    // allowing further additions until the limit is reached.
    // For removal or redistribution of records based on load, additional logic would be added here.

    pthread_mutex_unlock(&collection->lock);
}

void cleanup_collection(DynamicCollection* collection) {
    if (!collection) return;

    pthread_mutex_lock(&collection->lock);

    Node* current = collection->head;
    while (current) {
        Node* next = current->next;
        free(current->record.resource);
        free(current);
        current = next;
    }

    collection->head = NULL;
    pthread_mutex_unlock(&collection->lock);

    pthread_mutex_destroy(&collection->lock);
    free(collection);
}
```

This code defines a C function to manage a dynamic collection of `Record` structures, including initialization with random values and handling concurrent access using mutexes. It supports serialization/deserialization for persistence, resizing the collection, and cleanup functionality while considering memory management and thread safety.']

