    long n;

    if (inet_pton(AF_INET, ip, &n)) return 1; // Using inet_pton for basic validation
    return 0;
}

void process_ip_addresses() {
    char line[MAX_IP_LENGTH + 5]; // IP + " -> " + IP + "\n"
    TCP_CONNECTION_STATUS_RECORD *records = NULL;
    size_t record_count = 0, capacity = 10;

    records = (TCP_CONNECTION_STATUS_RECORD *)malloc(capacity * sizeof(TCP_CONNECTION_STATUS_RECORD));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    char unique_sources[1000][16]; // Assuming a maximum of 1000 unique IPs
    size_t unique_count = 0;

    while (fgets(line, sizeof(line), stdin)) {
        char *src_ip = strtok(line, " -> \n");
        if (!src_ip) continue;
        char *dest_ip = strtok(NULL, "\n");

        if (!is_valid_ipv4(src_ip) || !is_valid_ipv4(dest_ip)) {
            fprintf(stderr, "Invalid IP address: %s -> %s\n", src_ip, dest_ip);
            continue;
        }

        // Check for unique source IP
        int is_unique = 1;
        for (size_t i = 0; i < unique_count; ++i) {
            if (strcmp(unique_sources[i], src_ip) == 0) {
                is_unique = 0;
                break;
            }
        }

        if (is_unique) {
            strcpy(unique_sources[unique_count++], src_ip);
        }

        // Allocate more space if needed
        if (record_count >= capacity) {
            capacity *= 2;
            records = (TCP_CONNECTION_STATUS_RECORD *)realloc(records, capacity * sizeof(TCP_CONNECTION_STATUS_RECORD));
            if (!records) {
                fprintf(stderr, "Memory reallocation failed\n");
                return;
            }
        }

        strcpy(records[record_count].source_ip, src_ip);
        strcpy(records[record_count].dest_ip, dest_ip);
        records[record_count].status = 0; // Initialize status field
        record_count++;
    }

    printf("Total unique source IP addresses: %zu\n", unique_count);

    free(records);
}
