#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int value;
} record;

void *safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

record* manage_arrays(int n_records, int min_val, int max_val) {
    long *offsets = (long *)safe_malloc(n_records * sizeof(long));
    int *keys = (int *)safe_malloc(n_records * sizeof(int));

    // Initialize offsets and keys with random values
    for (int i = 0; i < n_records; ++i) {
        offsets[i] = min_val + rand() % (max_val - min_val + 1);
        keys[i] = min_val + rand() % (max_val - min_val + 1);
    }

    record *records = (record *)safe_malloc(n_records * sizeof(record));

    // Initialize records with unique index-based values
    for (int i = 0; i < n_records; ++i) {
        records[i].value = i;
    }

    return records;
}

void deallocate_arrays(long *offsets, int *keys, record *records, int n_records) {
    free(offsets);
    free(keys);
    free(records);
}
```

