#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

#define INITIAL_CAPACITY 10
#define MAX_RESOURCES 1000

typedef struct {
    int id;
    time_t timestamp;
    int status; // Active or Inactive
    void *dependency;
} Resource;

typedef struct {
    Resource **resources;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    size_t total_size;
} ResourceManager;

ResourceManager* create_manager() {
    ResourceManager *manager = (ResourceManager *)malloc(sizeof(ResourceManager));
    if (!manager) return NULL;

    manager->resources = (Resource **)calloc(INITIAL_CAPACITY, sizeof(Resource *));
    if (!manager->resources) {
        free(manager);
        return NULL;
    }

    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    manager->total_size = 0;

    return manager;
}

void destroy_manager(ResourceManager *manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->resources[i]);
    }
    free(manager->resources);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_resource(ResourceManager *manager, int range_min, int range_max) {
    if (manager->count >= MAX_RESOURCES) return -1;

    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        Resource **new_resources = realloc(manager->resources, new_capacity * sizeof(Resource *));
        if (!new_resources) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        manager->resources = new_resources;
        manager->capacity = new_capacity;
    }

    Resource *resource = (Resource *)malloc(sizeof(Resource));
    if (!resource) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    resource->id = manager->count;
    resource->timestamp = time(NULL);
    resource->status = 1; // Active
    resource->dependency = NULL;

    int value = rand() % (range_max - range_min + 1) + range_min;
    printf("Resource ID: %d, Value: %d\n", resource->id, value);

    manager->resources[manager->count++] = resource;
    manager->total_size += sizeof(Resource);

    pthread_mutex_unlock(&manager->lock);
    return resource->id;
}

void serialize_state(ResourceManager *manager, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    pthread_mutex_lock(&manager->lock);

    fwrite(&manager->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < manager->count; ++i) {
        fwrite(manager->resources[i], sizeof(Resource), 1, file);
    }

    pthread_mutex_unlock(&manager->lock);
    fclose(file);
}

void deserialize_state(ResourceManager *manager, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    pthread_mutex_lock(&manager->lock);

    manager->resources = realloc(manager->resources, count * sizeof(Resource *));
    manager->capacity = count;
    manager->count = count;

    for (size_t i = 0; i < count; ++i) {
        Resource *resource = (Resource *)malloc(sizeof(Resource));
        fread(resource, sizeof(Resource), 1, file);
        manager->resources[i] = resource;
    }

    pthread_mutex_unlock(&manager->lock);
    fclose(file);
}

int main() {
    srand(time(NULL));

    ResourceManager *manager = create_manager();
    if (!manager) return EXIT_FAILURE;

    for (int i = 0; i < 20; ++i) {
        add_resource(manager, 1, 100);
    }

    serialize_state(manager, "resources.dat");

    destroy_manager(manager);

    manager = create_manager();
    deserialize_state(manager, "resources.dat");

    destroy_manager(manager);

    return EXIT_SUCCESS;
}
```

### Key Points:

- **Thread Safety**: Uses a single mutex to lock the entire data structure during modifications. This is simpler and reduces contention compared to fine-grained locks.

- **Dynamic Resizing**: Doubles the capacity when needed, which balances resizing cost and memory usage efficiently.

- **Serialization**: Saves and loads the state of resources to/from a file for persistence.

- **Error Handling**: Basic error handling is implemented for allocation failures.

- **Resource Limits**: Checks against `MAX_RESOURCES` to prevent resource exhaustion.']

