// Define the config_record and connection structures.
typedef struct {
    char *service_name;
    char *ip_address;
    int port;
} config_record;

typedef struct {
    bool status;
    time_t last_activity_time;
    int current_load;
} connection;

// Function prototypes for dependency injection points
void inject_logging(const char *log_message);
void setup_network(const char *ip_address, int port);
void manage_resources(const char *resource_action);

// External configuration validation function declarations.
bool is_valid_ipv4(const char *ip);
bool is_valid_ipv6(const char *ip);
bool validate_log_directory(const char *path);

// Function to handle errors
int error_handler(const char *message) {
    fprintf(stderr, "%s\n", message);
    return -1;
}

// Main function to process the JSON configuration file.
int process_config_file(const char *file_path,
                        void (*logging_api)(const char *),
                        void (*network_setup_api)(const char *, int),
                        void (*resource_management_api)(const char *)) {

    // Dependency injection
    inject_logging = logging_api;
    setup_network = network_setup_api;
    manage_resources = resource_management_api;

    FILE *file = fopen(file_path, "r");
    if (!file) {
        return error_handler("Failed to open file.");
    }

    struct json_object *parsed_json;
    struct json_object *service_name_obj, *host_ip_obj, *port_obj, *max_connections_obj, *log_rotation_size_obj;

    parsed_json = json_object_from_file(file_path);
    fclose(file);

    if (!parsed_json) {
        return error_handler("Failed to parse JSON.");
    }

    // Validate required fields
    if (json_object_object_get_ex(parsed_json, "service_name", &service_name_obj) &&
        json_object_is_type(service_name_obj, json_type_string) &&
        strlen(json_object_get_string(service_name_obj)) > 0) {

        inject_logging("Service name is valid.");
    } else {
        return error_handler("Invalid or missing service_name field.");
    }

    const char *host_ip = NULL;
    if (json_object_object_get_ex(parsed_json, "host_ip", &host_ip_obj) &&
        json_object_is_type(host_ip_obj, json_type_string)) {

        host_ip = json_object_get_string(host_ip_obj);
        if ((is_valid_ipv4(host_ip) || is_valid_ipv6(host_ip))) {
            inject_logging("Host IP is valid.");
        } else {
            return error_handler("Invalid host_ip field.");
        }
    } else {
        return error_handler("Missing or invalid host_ip field.");
    }

    int port = 0;
    if (json_object_object_get_ex(parsed_json, "port", &port_obj) &&
        json_object_is_type(port_obj, json_type_int)) {

        port = json_object_get_int(port_obj);
        if (port > 0) {
            inject_logging("Port is valid.");
        } else {
            return error_handler("Invalid port field.");
        }
    } else {
        return error_handler("Missing or invalid port field.");
    }

    int max_connections = 0;
    if (json_object_object_get_ex(parsed_json, "max_connections", &max_connections_obj) &&
        json_object_is_type(max_connections_obj, json_type_int)) {

        max_connections = json_object_get_int(max_connections_obj);
        if (max_connections >= 0) {
            inject_logging("Max connections is valid.");
        } else {
            return error_handler("Invalid max_connections field.");
        }
    }

    int log_rotation_size = 1024 * 1024; // Default to 1MB
    if (json_object_object_get_ex(parsed_json, "log_rotation_size", &log_rotation_size_obj) &&
        json_object_is_type(log_rotation_size_obj, json_type_int)) {

        log_rotation_size = json_object_get_int(log_rotation_size_obj);
        if (log_rotation_size >= 0) {
            inject_logging("Log rotation size is valid.");
        } else {
            return error_handler("Invalid log_rotation_size field.");
        }
    }

    const char *log_directory = "./logs";
    if (json_object_object_get_ex(parsed_json, "log_directory", &service_name_obj) &&
        json_object_is_type(service_name_obj, json_type_string)) {

        log_directory = json_object_get_string(service_name_obj);
        if (!validate_log_directory(log_directory)) {
            return error_handler("Invalid log directory.");
        }
    }

    // Initialize config records and connections
    int num_connections = max_connections > 0 ? max_connections : 10; // Default to 10 connections

    config_record *records = calloc(1, sizeof(config_record));
    if (!records) {
        return error_handler("Memory allocation failed for config records.");
    }

    records->service_name = strdup(json_object_get_string(service_name_obj));
    records->ip_address = strdup(host_ip);
    records->port = port;

    connection *connections = calloc(num_connections, sizeof(connection));
    if (!connections) {
        free(records->service_name);
        free(records->ip_address);
        free(records);
        return error_handler("Memory allocation failed for connections.");
    }

    for (int i = 0; i < num_connections; ++i) {
        connections[i].status = false;
        connections[i].last_activity_time = time(NULL);
        connections[i].current_load = 0;
    }

    // Setup network
    setup_network(host_ip, port);

    json_object_put(parsed_json);

    free(records->service_name);
    free(records->ip_address);
    free(records);
    free(connections);

    return 0; // Success
}

// Helper functions for validation and dependency injections

bool is_valid_ipv4(const char *ip) {
    struct sockaddr_in sa;
    return inet_pton(AF_INET, ip, &(sa.sin_addr)) == 1;
}

bool is_valid_ipv6(const char *ip) {
    struct sockaddr_in6 sa;
    return inet_pton(AF_INET6, ip, &(sa.sin6_addr)) == 1;
}

bool validate_log_directory(const char *path) {
    // Prevent log directory from being in critical system directories
    const char *critical_paths[] = {"/bin", "/sbin", "/etc", "/dev"};
    size_t num_critical_paths = sizeof(critical_paths) / sizeof(char *);

    for (size_t i = 0; i < num_critical_paths; ++i) {
        if (strncmp(path, critical_paths[i], strlen(critical_paths[i])) == 0 &&
            path[strlen(critical_paths[i])] == '/') {
            return false;
        }
    }

    // Further checks can be implemented here
    return true;
}
