    unsigned int RX_UE_INFORMATION_TAG;
    CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function prototypes
void log_error(const char *message);
int generate_crc_indication_pdu_list(NFAPI_CRC_INDICATION_PDU_T **list, size_t num_pdus);

// Implementation of the function to dynamically generate and populate a list of structures
void generate_crc_indication_pdu_list(NFAPI_CRC_INDICATION_PDU_T **list, size_t num_pdus) {
    if (num_pdus == 0 || list == NULL) return;

    *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*list == NULL) {
        log_error("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    // Seed the random number generator
    srand((unsigned int)time(NULL));

    // For tracking RNTI uniqueness
    unsigned int rnti_set[(1 << 16) / (8 * sizeof(unsigned int))] = {0};

    for (size_t i = 0; i < num_pdus; ++i) {
        (*list)[i].RX_UE_INFORMATION_TAG = rand() % 10000;

        // Generate a unique RNTI
        unsigned int rnti;
        do {
            rnti = rand() % (1 << 16);
        } while (!__sync_bool_compare_and_swap(&rnti_set[rnti / (8 * sizeof(unsigned int))], 
                                               0, 
                                               1ULL << (rnti % (8 * sizeof(unsigned int)))));

        if (__builtin_popcountll(rnti_set[rnti / (8 * sizeof(unsigned int))]) > 1) {
            log_error("Duplicate RNTI found");
            free(*list);
            exit(EXIT_FAILURE);
        }

        (*list)[i].CRC_INDICATION_REL8_TAG.RNTI = rnti;
        (*list)[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    }
}

// Simple logging function to log errors
void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}
