#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
import <unistd.h>
#include <errno.h>

#define MAX_THREADS 128
#define INITIAL_POOL_SIZE 4
#define LOG_FILE "task_log.txt"

typedef enum {
    TASK_PENDING,
    TASK_RUNNING,
    TASK_COMPLETED,
    TASK_FAILED
} TaskStatus;

typedef struct {
    void (*execute)(void *arg);
    void *arg;
    TaskStatus status;
    long startTime;
    long duration; // in milliseconds
    int resultCode;
} Task;

typedef struct {
    pthread_t *threads;
    size_t poolSize;
    size_t taskCount;
    Task **tasks;
    pthread_mutex_t mutex;
    pthread_cond_t cond_var;
    FILE *logFile;
} ThreadPool;

ThreadPool *create_thread_pool(size_t initialPoolSize);
void destroy_thread_pool(ThreadPool *pool);
int submit_task(ThreadPool *pool, void (*taskFunc)(void*), void *arg);
void log_task_info(const Task *task);

// Worker thread function
static void *worker_function(void *arg) {
    ThreadPool *pool = (ThreadPool *)arg;
    while (1) {
        pthread_mutex_lock(&pool->mutex);

        // Wait for tasks if none are available
        while (pool->taskCount == 0) {
            pthread_cond_wait(&pool->cond_var, &pool->mutex);
        }

        Task *task = pool->tasks[0]; // Get the first task
        memmove(pool->tasks, pool->tasks + 1, --pool->taskCount * sizeof(Task *));

        task->status = TASK_RUNNING;
        pthread_mutex_unlock(&pool->mutex);

        long start_time = time(NULL);
        task->startTime = start_time;

        // Execute the task and handle errors
        if (task && task->execute) {
            task->resultCode = 0; // Assume success by default
            @try {
                task->execute(task->arg);
            } @catch (...) {
                task->resultCode = -1;
            }
        } else {
            task->resultCode = errno;
        }

        task->status = TASK_COMPLETED;
        long end_time = time(NULL);
        task->duration = (end_time - start_time) * 1000; // Convert to milliseconds

        pthread_mutex_lock(&pool->mutex);

        log_task_info(task); // Log the task information
        pthread_cond_broadcast(&pool->cond_var); // Signal that a task has completed

        pthread_mutex_unlock(&pool->mutex);
    }

    return NULL;
}

ThreadPool *create_thread_pool(size_t initialPoolSize) {
    ThreadPool *pool = (ThreadPool *)malloc(sizeof(ThreadPool));
    if (!pool) {
        perror("Failed to allocate memory for thread pool");
        exit(EXIT_FAILURE);
    }

    pool->threads = (pthread_t *)malloc(initialPoolSize * sizeof(pthread_t));
    pool->tasks = NULL;
    pool->taskCount = 0;
    pool->poolSize = initialPoolSize;

    if (!pool->threads) {
        perror("Failed to allocate memory for thread pool threads");
        free(pool);
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&pool->mutex, NULL);
    pthread_cond_init(&pool->cond_var, NULL);

    pool->logFile = fopen(LOG_FILE, "a");
    if (!pool->logFile) {
        perror("Failed to open log file");
        free(pool->threads);
        free(pool);
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < initialPoolSize; ++i) {
        if (pthread_create(&pool->threads[i], NULL, worker_function, pool)) {
            perror("Failed to create thread");
            fclose(pool->logFile);
            free(pool->threads);
            free(pool);
            exit(EXIT_FAILURE);
        }
    }

    return pool;
}

void destroy_thread_pool(ThreadPool *pool) {
    pthread_mutex_lock(&pool->mutex);

    for (size_t i = 0; i < pool->taskCount; ++i) {
        free(pool->tasks[i]);
    }

    if (pool->tasks) {
        free(pool->tasks);
    }

    fclose(pool->logFile);
    pthread_mutex_unlock(&pool->mutex);
    pthread_cond_destroy(&pool->cond_var);
    pthread_mutex_destroy(&pool->mutex);

    for (size_t i = 0; i < pool->poolSize; ++i) {
        pthread_cancel(pool->threads[i]);
    }

    free(pool->threads);
    free(pool);
}

int submit_task(ThreadPool *pool, void (*taskFunc)(void*), void *arg) {
    pthread_mutex_lock(&pool->mutex);

    if (pool->taskCount >= pool->poolSize) {
        // Consider resizing logic here for dynamic adjustment
        pthread_mutex_unlock(&pool->mutex);
        return -1;
    }

    Task *newTask = (Task *)malloc(sizeof(Task));
    if (!newTask) {
        perror("Failed to allocate memory for task");
        pthread_mutex_unlock(&pool->mutex);
        return -1;
    }

    newTask->execute = taskFunc;
    newTask->arg = arg;
    newTask->status = TASK_PENDING;

    Task **tasksArray = realloc(pool->tasks, (pool->taskCount + 1) * sizeof(Task *));
    if (!tasksArray) {
        perror("Failed to allocate memory for tasks array");
        free(newTask);
        pthread_mutex_unlock(&pool->mutex);
        return -1;
    }

    pool->tasks = tasksArray;
    pool->tasks[pool->taskCount++] = newTask;

    pthread_cond_broadcast(&pool->cond_var); // Signal that a new task is available
    pthread_mutex_unlock(&pool->mutex);

    return 0;
}

void log_task_info(const Task *task) {
    if (!task || !task->execute)
        return;

    fprintf(pool->logFile, "Task executed at %ld ms with duration %ld ms and result code %d\n",
            task->startTime,
            task->duration,
            task->resultCode);

    fflush(pool->logFile); // Ensure data is written to the log file immediately
}
