#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>

#define MAX_FILES 100
#define TIMEOUT_SECONDS 300

typedef enum { READ_ONLY, WRITE_ONLY, READ_WRITE } AccessMode;

typedef struct {
    char *file_path;
    AccessMode mode;
    off_t byte_offset;
    time_t last_accessed;
    size_t bytes_read;
    size_t bytes_written;
    int is_active;
} FileDescriptorMetadata;

typedef struct Node {
    FileDescriptorMetadata metadata;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int active_count;
} DescriptorPool;

static DescriptorPool pool = {NULL, PTHREAD_MUTEX_INITIALIZER, PTHREAD_COND_INITIALIZER, 0};

// Helper functions
void handle_safe_arithmetic(size_t *a, size_t b, char op) {
    if (op == '+') {
        if ((SIZE_MAX - b) < *a) {
            fprintf(stderr, "Integer overflow detected\n");
            exit(EXIT_FAILURE);
        }
        *a += b;
    } else if (op == '-') {
        if (*a < b) {
            fprintf(stderr, "Integer underflow detected\n");
            exit(EXIT_FAILURE);
        }
        *a -= b;
    }
}

void close_inactive_descriptors() {
    time_t current_time = time(NULL);
    pthread_mutex_lock(&pool.lock);

    Node* prev = NULL;
    Node* curr = pool.head;

    while (curr) {
        if (!curr->metadata.is_active && 
            difftime(current_time, curr->metadata.last_accessed) > TIMEOUT_SECONDS) {

            if (prev) {
                prev->next = curr->next;
            } else {
                pool.head = curr->next;
            }

            free(curr->metadata.file_path);
            free(curr);

            --pool.active_count;
        } else {
            prev = curr;
        }
        curr = curr->next;
    }

    pthread_mutex_unlock(&pool.lock);
}

void serialize_pool(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open serialization file");
        return;
    }

    Node* curr = pool.head;

    while (curr) {
        fwrite(&(curr->metadata), sizeof(FileDescriptorMetadata), 1, file);
        if (strlen(curr->metadata.file_path) + 1 > 0) { // Null-terminate
            size_t path_len = strlen(curr->metadata.file_path) + 1;
            fwrite(curr->metadata.file_path, sizeof(char), path_len, file);
        }
        curr = curr->next;
    }

    fclose(file);
}

void deserialize_pool(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open deserialization file");
        return;
    }

    pthread_mutex_lock(&pool.lock);

    // Clear existing pool
    Node* curr = pool.head;
    while (curr) {
        Node* temp = curr;
        curr = curr->next;
        free(temp->metadata.file_path);
        free(temp);
    }
    pool.head = NULL;
    pool.active_count = 0;

    FileDescriptorMetadata metadata;
    while (fread(&metadata, sizeof(FileDescriptorMetadata), 1, file) == 1) {
        Node* new_node = malloc(sizeof(Node));
        if (!new_node) {
            perror("Failed to allocate memory for node");
            fclose(file);
            pthread_mutex_unlock(&pool.lock);
            return;
        }

        size_t path_len = strlen(metadata.file_path) + 1;
        char* file_path = malloc(path_len);
        fread(file_path, sizeof(char), path_len, file);

        new_node->metadata.file_path = file_path;
        new_node->metadata.mode = metadata.mode;
        new_node->metadata.byte_offset = metadata.byte_offset;
        new_node->metadata.last_accessed = metadata.last_accessed;
        new_node->metadata.bytes_read = metadata.bytes_read;
        new_node->metadata.bytes_written = metadata.bytes_written;
        new_node->metadata.is_active = 1;

        new_node->next = pool.head;
        pool.head = new_node;
        ++pool.active_count;
    }

    pthread_mutex_unlock(&pool.lock);
    fclose(file);
}

void initialize_descriptor(const char* file_path, AccessMode mode) {
    if (pool.active_count >= MAX_FILES) {
        fprintf(stderr, "Maximum number of open files reached\n");
        return;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for node");
        return;
    }

    size_t path_len = strlen(file_path) + 1;
    char* file_path_copy = malloc(path_len);
    if (!file_path_copy) {
        free(new_node);
        perror("Failed to copy file path");
        return;
    }
    strncpy(file_path_copy, file_path, path_len);

    new_node->metadata.file_path = file_path_copy;
    new_node->metadata.mode = mode;
    new_node->metadata.byte_offset = 0;
    new_node->metadata.last_accessed = time(NULL);
    new_node->metadata.bytes_read = 0;
    new_node->metadata.bytes_written = 0;
    new_node->metadata.is_active = 1;

    pthread_mutex_lock(&pool.lock);

    new_node->next = pool.head;
    pool.head = new_node;
    ++pool.active_count;

    pthread_mutex_unlock(&pool.lock);
}

void update_access(FileDescriptorMetadata* metadata) {
    metadata->last_accessed = time(NULL);
    pthread_mutex_lock(&metadata->lock); // Assuming each file descriptor has its own lock
    // Update other fields as needed
    pthread_mutex_unlock(&metadata->lock);
}

