    public List<NFAPI_CRC_INDICATION_PDU_T> AddWebsiteAndPopulateNFAPackets(string directoryPath, string siteName, double performanceThreshold)
    {
        // Check for file existence
        bool webConfigExists = File.Exists(Path.Combine(directoryPath, "web.config"));
        bool appSettingsExists = File.Exists(Path.Combine(directoryPath, "appsettings.json"));

        if (!webConfigExists || !appSettingsExists)
        {
            LogWarning("Missing configuration files.");
        }

        // Check disk space
        if (!HasSufficientDiskSpace(directoryPath))
        {
            LogError("Insufficient disk space.");
            return null;
        }

        // Check directory access
        if (IsDirectoryLocked(directoryPath))
        {
            LogError("Directory is locked by another process.");
            return null;
        }

        // Create and populate NFAPackets
