                        };
                        nfapiPackets.Add(packet);
                    }
                    finally
                    {
                        Monitor.Exit(_lockObject);
                    }
                }
            }
        });

        return nfapiPackets;
    }

    private bool HasSufficientDiskSpace(string directoryPath)
    {
        var driveInfo = new DriveInfo(Path.GetPathRoot(directoryPath));
        double freePercentage = (double)driveInfo.FreeSpace / driveInfo.TotalSize;
        return freePercentage >= 0.1; // Ensure at least 10% disk space is free
    }

    private bool IsDirectoryLocked(string directoryPath)
    {
        try
        {
            using (var handle = File.Open(Path.Combine(directoryPath, "temp.lock"), FileMode.Create))
            {
                handle.Close();
                File.Delete(Path.Combine(directoryPath, "temp.lock"));
                return false;
            }
        }
        catch
        {
            return true;
        }
    }

    private int CalculatePacketCount(double performanceThreshold)
