    if (pcap_setfilter(handle, &fp) == -1) {
        fprintf(stderr, "Couldn't install filter %s: %s\n", "tcp or udp", pcap_geterr(handle));
        cleanup_memory();
        return EXIT_FAILURE;
    }

    pcap_loop(handle, 0, process_packet, NULL);

    pcap_freecode(&fp);
    pcap_close(handle);

    cleanup_memory();

    return EXIT_SUCCESS;
