#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define the data_node structure.
typedef struct DataNode {
    long timestamp;
    int identifier;
} DataNode;

// Node for linked list overflow management.
typedef struct LinkedListNode {
    DataNode data;
    struct LinkedListNode* next;
} LinkedListNode;

// Array management structure
typedef struct DataManager {
    DataNode** array;          // Dynamic array of pointers to data nodes
    size_t capacity;           // Capacity of the dynamic array
    size_t count;              // Current number of elements in the array
    LinkedListNode* overflow;  // Pointer to start of linked list for overflow management

    pthread_mutex_t lock;      // Mutex for thread-safe operations
} DataManager;

// Function prototypes.
DataManager* create_data_manager(size_t initial_capacity);
void free_data_manager(DataManager* manager);
int add_node(DataManager* manager, long timestamp, int identifier);
DataNode* get_node_by_id(DataManager* manager, int identifier);

// Create a new data manager with an initial capacity
DataManager* create_data_manager(size_t initial_capacity) {
    DataManager* manager = (DataManager*)malloc(sizeof(DataManager));
    if (!manager) return NULL;

    manager->array = (DataNode**)malloc(initial_capacity * sizeof(DataNode*));
    if (!manager->array) {
        free(manager);
        return NULL;
    }
    for (size_t i = 0; i < initial_capacity; i++) {
        manager->array[i] = NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    manager->overflow = NULL;

    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

// Free the data manager and all associated memory
void free_data_manager(DataManager* manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->capacity; i++) {
        if (manager->array[i]) free(manager->array[i]);
    }
    free(manager->array);

    LinkedListNode* current = manager->overflow;
    while (current) {
        LinkedListNode* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

// Add a new node to the data manager
int add_node(DataManager* manager, long timestamp, int identifier) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->lock);

    // Try to insert into array if there's space
    if (manager->count < manager->capacity) {
        DataNode* new_node = (DataNode*)malloc(sizeof(DataNode));
        if (!new_node) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        new_node->timestamp = timestamp;
        new_node->identifier = identifier;

        manager->array[manager->count++] = new_node;
    } else {
        // Insert into linked list for overflow
        LinkedListNode* new_node = (LinkedListNode*)malloc(sizeof(LinkedListNode));
        if (!new_node) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        new_node->data.timestamp = timestamp;
        new_node->data.identifier = identifier;

        new_node->next = manager->overflow;
        manager->overflow = new_node;
    }

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

// Retrieve a node by its identifier
DataNode* get_node_by_id(DataManager* manager, int identifier) {
    if (!manager) return NULL;

    pthread_mutex_lock(&manager->lock);

    // Check in the array first
    for (size_t i = 0; i < manager->count; i++) {
        if (manager->array[i] && manager->array[i]->identifier == identifier) {
            DataNode* result = malloc(sizeof(DataNode));
            if (result) {
                *result = *(manager->array[i]);
                pthread_mutex_unlock(&manager->lock);
                return result;
            }
        }
    }

    // Check in the linked list
    LinkedListNode* current = manager->overflow;
    while (current) {
        if (current->data.identifier == identifier) {
            DataNode* result = malloc(sizeof(DataNode));
            if (result) {
                *result = current->data;
                pthread_mutex_unlock(&manager->lock);
                return result;
            }
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL; // Not found
}

// Example usage:
int main() {
    DataManager* manager = create_data_manager(10);

    add_node(manager, 1633072800L, 1);
    add_node(manager, 1633159200L, 2);

    DataNode* node = get_node_by_id(manager, 1);
    if (node) {
        printf("Found Node: %d at %ld\n", node->identifier, node->timestamp);
        free(node);
    }

    free_data_manager(manager);
    return 0;
}
