['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Record {
    char *key;
    time_t timestamp;
    struct Record *next;
} Record;

typedef struct Collection {
    Record *head;
    size_t count;
    pthread_mutex_t lock;
} Collection;

Collection* create_collection() {
    Collection *collection = malloc(sizeof(Collection));
    collection->head = NULL;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void add_record(Collection *collection, const char *key) {
    pthread_mutex_lock(&collection->lock);

    Record *new_record = malloc(sizeof(Record));
    new_record->key = strdup(key);
    new_record->timestamp = time(NULL);
    new_record->next = collection->head;
    collection->head = new_record;
    collection->count++;

    pthread_mutex_unlock(&collection->lock);
}

void remove_record(Collection *collection, const char *key) {
    pthread_mutex_lock(&collection->lock);

    Record **current = &collection->head;
    while (*current) {
        Record *entry = *current;
        if (strcmp(entry->key, key) == 0) {
            *current = entry->next;
            free(entry->key);
            free(entry);
            collection->count--;
            break;
        }
        current = &entry->next;
    }

    pthread_mutex_unlock(&collection->lock);
}

Record* get_record(Collection *collection, const char *key) {
    Record *current = collection->head;
    while (current) {
        if (strcmp(current->key, key) == 0) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void serialize_collection(const Collection *collection, FILE *file) {
    pthread_mutex_lock(&collection->lock);

    Record *current = collection->head;
    while (current) {
        fwrite(current->key, strlen(current->key) + 1, 1, file);
        fwrite(&current->timestamp, sizeof(time_t), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock(&collection->lock);
}

void deserialize_collection(Collection *collection, FILE *file) {
    char buffer[256];
    time_t timestamp;

    while (fread(buffer, 1, sizeof(buffer), file)) {
        if (feof(file)) break;

        Record *new_record = malloc(sizeof(Record));
        new_record->key = strdup(buffer);
        fread(&timestamp, sizeof(time_t), 1, file);

        new_record->timestamp = timestamp;
        new_record->next = collection->head;
        collection->head = new_record;
        collection->count++;
    }
}

void free_collection(Collection *collection) {
    pthread_mutex_lock(&collection->lock);

    Record *current = collection->head;
    while (current) {
        Record *temp = current;
        current = current->next;
        free(temp->key);
        free(temp);
    }

    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int main() {
    Collection *collection = create_collection();

    add_record(collection, "example_key1");
    add_record(collection, "example_key2");

    Record *record = get_record(collection, "example_key1");
    if (record) {
        printf("Retrieved: %s at %ld\n", record->key, record->timestamp);
    }

    remove_record(collection, "example_key1");

    FILE *file = fopen("collection.bin", "wb");
    serialize_collection(collection, file);
    fclose(file);

    Collection *new_collection = create_collection();
    file = fopen("collection.bin", "rb");
    deserialize_collection(new_collection, file);
    fclose(file);

    Record *deserialized_record = get_record(new_collection, "example_key2");
    if (deserialized_record) {
        printf("Deserialized: %s at %ld\n", deserialized_record->key, deserialized_record->timestamp);
    }

    free_collection(collection);
    free_collection(new_collection);

    return 0;
}
