// traverseDOM.js

function traverseDOM(node, classOrIdFilter, depthLimit, currentDepth = 0, results = []) {
    if (currentDepth > depthLimit || !node || !results.length) return [];

    if ((classOrIdFilter.startsWith('.') && node.classList.contains(classOrIdFilter.slice(1))) ||
        (classOrIdFilter.startsWith('#') && node.id === classOrIdFilter.slice(1)) ||
        (!classOrIdFilter.startsWith('.') && !classOrIdFilter.startsWith('#') && node.tagName.toLowerCase() === classOrIdFilter)) {
        results.push(node);
    }

    if (currentDepth < depthLimit) {
        const children = Array.from(node.children);
        children.forEach(child => traverseDOM(child, classOrIdFilter, depthLimit, currentDepth + 1, results));
    }

    return results;
}

