import threading
import random

class Node:
    def __init__(self, value):
        self.value = value
        self.next = None
        self.prev = None
        self.ref_count = 1
        self.lock = threading.Lock()

class DoublyLinkedList:
    def __init__(self):
        self.head = None
        self.tail = None
        self.lock = threading.RLock()

    def append(self, value):
        with self.lock:
            new_node = Node(value)
            if not self.head:
                self.head = self.tail = new_node
            else:
                self.tail.next = new_node
                new_node.prev = self.tail
                self.tail = new_node

    def prepend(self, value):
        with self.lock:
            new_node = Node(value)
            if not self.head:
                self.head = self.tail = new_node
            else:
                new_node.next = self.head
                self.head.prev = new_node
                self.head = new_node

    def remove_node(self, node):
        with node.lock:
            node.ref_count -= 1
            if node.ref_count == 0:
                with self.lock:
                    if node.prev:
                        node.prev.next = node.next
                    else:
                        self.head = node.next

                    if node.next:
                        node.next.prev = node.prev
                    else:
                        self.tail = node.prev

    def traverse_and_print(self):
        current = self.head
        while current:
            print(current.value)
            current = current.next

class MemoryManager:
    def __init__(self):
        self.lists = {}
        self.lock = threading.RLock()

    def create_list(self, list_id):
        with self.lock:
            if list_id not in self.lists:
                self.lists[list_id] = DoublyLinkedList()

    def append_to_list(self, list_id, value):
        with self.lock:
            if list_id in self.lists:
                self.lists[list_id].append(value)

    def prepend_to_list(self, list_id, value):
        with self.lock:
            if list_id in self.lists:
                self.lists[list_id].prepend(value)

    def remove_node_by_value(self, list_id, value):
        with self.lock:
            if list_id in self.lists:
                current = self.lists[list_id].head
                while current:
                    with current.lock:
                        if current.value == value and current.ref_count > 0:
                            self.lists[list_id].remove_node(current)
                    current = current.next

    def traverse_and_print_list(self, list_id):
        with self.lock:
            if list_id in self.lists:
                self.lists[list_id].traverse_and_print()

def populate_list(memory_manager, list_id, num_elements, value_range):
    for _ in range(num_elements):
        value = random.uniform(*value_range)
        memory_manager.append_to_list(list_id, value)

# Example usage
memory_manager = MemoryManager()
list_id = "list_1"
memory_manager.create_list(list_id)
populate_list(memory_manager, list_id, 10, (0.0, 100.0))
memory_manager.traverse_and_print_list(list_id)
```

This implementation provides a scalable and efficient memory management system for managing multiple independent doubly linked lists of `Node` structures. It includes thread-safe operations for appending, prepending, and removing nodes based on reference count. The design supports concurrent access and integrates well with other components by ensuring minimal locking overhead and maintaining data consistency across threads.']

