<?php

class UserProfileManager {

    private $dbConnection;
    private $cache;

    public function __construct($dbConnection) {
        $this->dbConnection = $dbConnection;
        $this->cache = new Redis();
        $this->cache->connect('127.0.0.1', 6379);
    }

    public function handleProfileUpdate() {
        header('Content-Type: application/json');

        if (!$this->isRateLimited()) {
            try {
                $response = ['status' => 'success', 'message' => ''];

                $id = $_REQUEST['id'] ?? null;
                $subAction = $_REQUEST['sub_action'] ?? '';

                if (!$id) {
                    return $this->jsonResponse(['status' => 'error', 'message' => 'User ID is required.']);
                }

                $userData = $this->getUserData($id);

                switch ($subAction) {
                    case 'change-password':
                        $response['message'] .= $this->handleChangePassword($userData);
                        break;

                    case 'update-privacy-settings':
                        $response['message'] .= $this->handleUpdatePrivacySettings($userData);
                        break;

                    default:
                        return $this->jsonResponse(['status' => 'error', 'message' => 'Invalid sub-action.']);
                }

                $this->cacheUserdata($id, $userData);

            } catch (Exception $e) {
                return $this->jsonResponse(['status' => 'error', 'message' => $e->getMessage()]);
            }
        } else {
            return $this->jsonResponse(['status' => 'error', 'message' => 'Rate limit exceeded.']);
        }

        return $this->jsonResponse($response);
    }

    private function getUserData($id) {
        $cachedData = $this->cache->get('user:' . $id);

        if ($cachedData) {
            return json_decode($cachedData, true);
        } else {
            $stmt = $this->dbConnection->prepare("SELECT * FROM users WHERE id = ?");
            $stmt->bind_param('i', $id);
            $stmt->execute();
            $result = $stmt->get_result();

            if ($result->num_rows === 0) {
                throw new Exception('User not found.');
            }

            return json_decode($result->fetch_assoc(), true);
        }
    }

    private function handleChangePassword($userData) {
        $currentPassword = $_REQUEST['current_password'] ?? '';
        $newPassword = $_REQUEST['password'] ?? '';

        if (!$this->verifyCurrentPassword($userData, $currentPassword)) {
            throw new Exception('Incorrect current password.');
        }

        if (!$this->isStrongPassword($newPassword)) {
            throw new Exception('New password does not meet the strength requirements.');
        }

        $stmt = $this->dbConnection->prepare("UPDATE users SET password = ? WHERE id = ?");
        $hashedPassword = password_hash($newPassword, PASSWORD_DEFAULT);
        $stmt->bind_param('si', $hashedPassword, $userData['id']);
        $stmt->execute();

        return 'Password changed successfully.';
    }

    private function handleUpdatePrivacySettings($userData) {
        $privacySettings = $_REQUEST['privacySettings'] ?? [];

        if (!$this->validatePrivacySettings($privacySettings)) {
            throw new Exception('Invalid privacy settings.');
        }

        // Example: Update user's privacy settings in the database
        // (Assuming a table 'user_privacy' exists with appropriate columns)
        $stmt = $this->dbConnection->prepare("UPDATE user_privacy SET settings = ? WHERE user_id = ?");
        $settingsJson = json_encode($privacySettings);
        $stmt->bind_param('si', $settingsJson, $userData['id']);
        $stmt->execute();

        return 'Privacy settings updated successfully.';
    }

    private function verifyCurrentPassword($userData, $currentPassword) {
        return password_verify($currentPassword, $userData['password']);
    }

    private function isStrongPassword($password) {
        // Implement strong password check (e.g., length, special characters)
        return strlen($password) >= 8;
    }

    private function validatePrivacySettings($settings) {
        // Validate privacy settings against predefined policies
        return true; // Simplified for example purposes
    }

    private function cacheUserdata($id, $userData) {
        $this->cache->set('user:' . $id, json_encode($userData), 3600); // Cache for an hour
    }

    private function isRateLimited() {
        $userId = $_REQUEST['id'] ?? null;
        if (!$userId) return false;

        $attemptsKey = 'rate_limit:password_change:' . $userId;
        $attempts = $this->cache->get($attemptsKey);

        if ($attempts && (int)$attempts >= 5) {
            return true; // Rate limit exceeded
        }

        $this->cache->incr($attemptsKey);
        $this->cache->expire($attemptsKey, 900); // Reset after 15 minutes

        return false;
    }

    private function jsonResponse($data) {
        return json_encode($data);
    }
}

// Usage example:
$dbConnection = new mysqli('localhost', 'username', 'password', 'database');
$userProfileManager = new UserProfileManager($dbConnection);
echo $userProfileManager->handleProfileUpdate();
