typedef struct {
    int value;
    long key_ref;
    time_t timestamp;
} record;

typedef struct {
    int total_sum;
    int resize_needed;
} metadata;

#define INITIAL_SIZE 10
#define RANGE_MIN 1
#define RANGE_MAX 100

long offsets[INITIAL_SIZE];
int keys[INITIAL_SIZE];
record records[INITIAL_SIZE];
metadata meta = {0, 0};
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void serialize_state();
void compress_records();
void transfer_to_external_system(const char *data);
void log_event(const char *event);

// Safe arithmetic operations
long safe_add(long a, long b) {
    if ((b > 0) && (a > LONG_MAX - b)) {
        // Handle overflow case
        return LONG_MAX;
    }
    if ((b < 0) && (a < LONG_MIN - b)) {
        // Handle underflow case
        return LONG_MIN;
    }
    return a + b;
}

void initialize_records(int new_size) {
    pthread_mutex_lock(&lock);

    int current_size = INITIAL_SIZE;
    if (new_size > current_size) {
        long *temp_offsets = realloc(offsets, sizeof(long) * new_size);
        int *temp_keys = realloc(keys, sizeof(int) * new_size);
        record *temp_records = realloc(records, sizeof(record) * new_size);

        if (!temp_offsets || !temp_keys || !temp_records) {
            log_event("Memory allocation failed");
            pthread_mutex_unlock(&lock);
            return;
        }

        offsets = temp_offsets;
        keys = temp_keys;
        records = temp_records;

        current_size = new_size;
    }

    for (int i = 0; i < new_size; ++i) {
        if (i >= current_size) continue;

        long random_offset = rand() % 100; // Random offset
        int key = rand() % 100; // Random key

        offsets[i] = random_offset;
        keys[i] = key;

        record rec;
        rec.value = (rand() % (RANGE_MAX - RANGE_MIN + 1)) + RANGE_MIN;
        rec.key_ref = keys[i];
        rec.timestamp = time(NULL);

        records[i] = rec;

        meta.total_sum = safe_add(meta.total_sum, rec.value);
    }

    if (meta.resize_needed) {
        compress_records();
        serialize_state();
    }

    transfer_to_external_system("Serialized data");

    pthread_mutex_unlock(&lock);
}

void serialize_state() {
    // Implement serialization logic here
    log_event("State serialized");
}

void compress_records() {
    // Implement compression logic here
    meta.resize_needed = 0;
    log_event("Records compressed");
}

void transfer_to_external_system(const char *data) {
    // Implement data transfer to external system here
    log_event("Data transferred to external system");
}

void log_event(const char *event) {
    printf("%s\n", event);
}

int main() {
    srand(time(NULL));

    initialize_records(15);

    return 0;
}
