float* read_floats(int *count) {
    float *numbers = NULL;
    size_t capacity = 0;
    size_t length = 0;

    printf("Enter floating-point numbers (CTRL+D to end):\n");
    while (1) {
        if (length == capacity) {
            capacity = capacity ? capacity * 2 : 4; // Double the capacity or initialize
            float *new_numbers = realloc(numbers, capacity * sizeof(float));
            if (!new_numbers) {
                free(numbers);
                fprintf(stderr, "Memory allocation error.\n");
                exit(EXIT_FAILURE);
            }
            numbers = new_numbers;
        }

        if (scanf("%f", &numbers[length]) != 1) {
            if (feof(stdin)) break; // End of input
            else { // Handle invalid input
                while (getchar() != '\n'); // Skip remaining line
                fprintf(stderr, "Invalid data format encountered.\n");
                continue;
            }
        }

        length++;
    }

    *count = length;
    return numbers;
}

void calculate_average(float *numbers, int count) {
    if (count == 0) {
        printf("No valid floating-point numbers to average.\n");
        return;
    }

    float sum = 0.0f;
    for (int i = 0; i < count; ++i) {
        sum += numbers[i];
    }

    float average = sum / count;
    printf("Average of the floating-point numbers: %.2f\n", average);
}

void log_error(const char *message) {
    FILE *log_file = fopen("error_log.txt", "a");
    if (log_file != NULL) {
