    LTE_RRC_RECONFIGURATION_MESSAGE *messages = malloc(count * sizeof(LTE_RRC_RECONFIGURATION_MESSAGE));
    if (!messages) {
        log_error("Memory allocation error when creating LTE messages.");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    for (int i = 0; i < count; ++i) {
        messages[i].SRB1_CONFIG = 1; // Assuming some default value
        messages[i].MME_UE_S1AP_ID = rand(); // Random ID, seeded by time in main
        messages[i].MACENTITYID = (unsigned long)rand();
        messages[i].sequence_number = i + 1;
    }

    pthread_mutex_unlock(&lock);
    return messages;
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    int count;
    float *numbers = read_floats(&count);

    LTE_RRC_RECONFIGURATION_MESSAGE *lte_messages = create_lte_rrc_messages(numbers, count);
    if (lte_messages == NULL) {
        free(numbers);
        return EXIT_FAILURE;
    }

    calculate_average(numbers, count);

    // Clean up
    free(lte_messages);
    free(numbers);

    return EXIT_SUCCESS;
}
