#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>
#include <string.h>
#include <errno.h>

// Define the record structure
typedef struct {
    int key_index;
} Record;

// Global variables for thread safety and memory management
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
long total_sum = 0;
uint64_t max_memory_usage = 1024 * 1024 * 100; // Example threshold: 100 MB

// Function to generate a random number within range, ensuring reproducibility with seed
int get_random_number(int min, int max, unsigned int *seed) {
    srand48_r(*seed, (struct drand48_data *)NULL);
    long double scale = ldexp(1.0L, 32);
    int random_value = (min + lrand48_r((struct drand48_data *)NULL) / scale * (max - min));
    *seed += 1; // Update seed for next call
    return random_value;
}

// Function to initialize arrays and records
void init_arrays(size_t num_records, long max_offset, int key_range_min, int key_range_max,
                 unsigned int seed, double time_threshold) {
    if (num_records == 0 || max_memory_usage <= 0) return;

    // Calculate memory sizes
    size_t offset_size = sizeof(long) * num_records;
    size_t keys_size = sizeof(int) * num_records;
    size_t record_size = sizeof(Record) * num_records;

    size_t total_size = offset_size + keys_size + record_size;
    if (total_size > max_memory_usage) {
        fprintf(stderr, "Memory allocation exceeds maximum allowed usage.\n");
        return;
    }

    // Allocate memory
    long *offsets = malloc(offset_size);
    int *keys = malloc(keys_size);
    Record *records = malloc(record_size);

    if (!offsets || !keys || !records) {
        perror("Failed to allocate memory");
        free(offsets); free(keys); free(records);
        return;
    }

    // Initialize arrays
    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = i * max_offset / num_records;

        int key_value = get_random_number(key_range_min, key_range_max, &seed);
        keys[i] = key_value;

        // Calculate record value based on cumulative sum
        pthread_mutex_lock(&mutex);
        total_sum += key_value;
        records[i].key_index = get_random_number(0, i, &seed) % (int)total_sum;
        pthread_mutex_unlock(&mutex);

        // Simulate real-time processing requirement
        if ((double)(clock() / CLOCKS_PER_SEC) > time_threshold) {
            fprintf(stderr, "Time threshold exceeded during initialization.\n");
            break;
        }
    }

    // Integrity check and logging (non-intrusive)
    for (size_t i = 0; i < num_records; ++i) {
        if (records[i].key_index >= total_sum) {
            fprintf(stderr, "Data corruption detected at record %zu\n", i);
        }
    }

    // Free memory
    free(offsets);
    free(keys);
    free(records);

    // Integration with external services can be added here for monitoring and alerts
}

int main(int argc, char *argv[]) {
    if (argc < 7) {
        fprintf(stderr, "Usage: %s <num_records> <max_offset> <key_range_min> <key_range_max> <seed> <time_threshold>\n", argv[0]);
        return EXIT_FAILURE;
    }

    size_t num_records = strtoul(argv[1], NULL, 10);
    long max_offset = strtol(argv[2], NULL, 10);
    int key_range_min = atoi(argv[3]);
    int key_range_max = atoi(argv[4]);
    unsigned int seed = (unsigned int)atoi(argv[5]);
    double time_threshold = atof(argv[6]);

    init_arrays(num_records, max_offset, key_range_min, key_range_max, seed, time_threshold);

    return EXIT_SUCCESS;
}
