#define MAX_PACKET_SIZE 1500
#define CONFIG_MAX_PACKETS 10000

typedef struct {
    time_t timestamp;
    size_t packet_size;
    char *data;
} Packet;

typedef struct {
    pthread_mutex_t lock;
    Packet **packets;
    size_t count;
    size_t capacity;
} PacketArray;

