int is_valid_packet(const Packet *packet);
void dispose_older_packets(PacketArray *array);
void handle_out_of_memory();
Packet *create_packet(size_t size, const char *data);

// Thread for managing packet storage capacity
void* manage_capacity(void* arg) {
    PacketArray *array = (PacketArray*)arg;
    while (1) {
        sleep(5); // Periodically check every 5 seconds
        pthread_mutex_lock(&packet_array_lock);
        if (array->count >= CONFIG_MAX_PACKETS) {
            dispose_older_packets(array);
        }
        pthread_mutex_unlock(&packet_array_lock);
    }
}

// Initialize dynamic packet array
PacketArray* init_packet_array(size_t initial_capacity) {
    PacketArray *array = malloc(sizeof(PacketArray));
    if (!array) handle_out_of_memory();

    array->packets = calloc(initial_capacity, sizeof(Packet*));
    if (!array->packets) handle_out_of_memory();

    pthread_mutex_init(&array->lock, NULL);
    array->count = 0;
    array->capacity = initial_capacity;

    pthread_t capacity_thread;
    pthread_create(&capacity_thread, NULL, manage_capacity, (void*)array);

    return array;
}

// Function to add a packet
int add_packet(PacketArray *array, Packet *packet) {
    if (!is_valid_packet(packet)) return -1; // Malformed packet

    pthread_mutex_lock(&(array->lock));

    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        Packet **new_packets = realloc(array->packets, new_capacity * sizeof(Packet*));
        if (!new_packets) handle_out_of_memory();

        array->packets = new_packets;
        array->capacity = new_capacity;
    }

    log_packet_addition(packet);
    array->packets[array->count++] = packet;

    pthread_mutex_unlock(&(array->lock));
    return 0; // Success
}

// Validate a packet (basic implementation)
int is_valid_packet(const Packet *packet) {
    if (!packet || !packet->data || packet->packet_size == 0 || packet->packet_size > MAX_PACKET_SIZE) {
        return 0;
    }
    return 1;
}

void log_packet_addition(const Packet *packet) {
    // Integrate with your logging framework
    printf("Packet added: timestamp=%ld, size=%zu\n", (long)packet->timestamp, packet->packet_size);
}

// Handle out-of-memory error
void handle_out_of_memory() {
    fprintf(stderr, "Out of memory!\n");
    exit(EXIT_FAILURE);
}

// Create a new Packet instance
Packet* create_packet(size_t size, const char *data) {
    Packet *packet = malloc(sizeof(Packet));
    if (!packet) handle_out_of_memory();

    packet->timestamp = time(NULL);
    packet->packet_size = size;
    packet->data = strdup(data); // Ensure deep copy

    return packet;
}

// Dispose older packets to maintain capacity
void dispose_older_packets(PacketArray *array) {
    for (size_t i = 0; i < array->count / 2; ++i) {
        free(array->packets[i]->data);
        free(array->packets[i]);
        array->packets[i] = array->packets[--array->count];
    }
}

// Main function to demonstrate usage
