// Resize an array dynamically, doubling its size
void resize_array(void **array, size_t *size, size_t element_size) {
    size_t new_size = (*size) * 2;
    void *new_array = realloc(*array, new_size * element_size);
    if (!new_array) handle_memory_error();
    *array = new_array;
    *size = new_size;
