        collections[i].records = malloc(MAX_RECORDS_PER_COLLECTION * sizeof(record));
        collections[i].count = 0;
        collections[i].cache_count = 0;

        pthread_mutex_init(&collection_locks[i], NULL);
    }
}

void cleanup_collections() {
    for (int i = 0; i < MAX_COLLECTIONS; ++i) {
        free(collections[i].records);
        pthread_rwlock_destroy(&collections[i].lock);
        pthread_mutex_destroy(&collection_locks[i]);
    }
}

void add_record(int collection_id, record new_record) {
    if (collection_id < 0 || collection_id >= MAX_COLLECTIONS)
        return;

    pthread_rwlock_wrlock(&collections[collection_id].lock);

    if (collections[collection_id].count < MAX_RECORDS_PER_COLLECTION) {
        collections[collection_id].records[collections[collection_id].count++] = new_record;
        log_info("Added record to collection %d", collection_id);
    } else {
        log_error("Collection %d is full. Cannot add more records.", collection_id);
    }

    pthread_rwlock_unlock(&collections[collection_id].lock);
}

record* get_record(int collection_id, int key) {
    if (collection_id < 0 || collection_id >= MAX_COLLECTIONS)
        return NULL;

    pthread_rwlock_rdlock(&collections[collection_id].lock);

    for (size_t i = 0; i < collections[collection_id].count; ++i) {
        if (collections[collection_id].records[i].key == key) {
            log_info("Retrieved record with key %d from collection %d", key, collection_id);
            pthread_rwlock_unlock(&collections[collection_id].lock);
            return &collections[collection_id].records[i];
        }
    }

    // Cache miss
    if (collections[collection_id].cache_count < CACHE_SIZE) {
        collections[collection_id].cache[collections[collection_id].cache_count] = key;
        collections[collection_id].cache_keys[collections[collection_id].cache_count++] = key;
        log_info("Cache updated for key %d in collection %d", key, collection_id);
    }

    pthread_rwlock_unlock(&collections[collection_id].lock);
    return NULL;
}

void update_offset(int collection_id, int key, long new_offset) {
    record *rec = get_record(collection_id, key);

    if (rec != NULL) {
        pthread_rwlock_wrlock(&collections[collection_id].lock);
        rec->offset = new_offset;
        log_info("Updated offset for key %d in collection %d", key, collection_id);
        pthread_rwlock_unlock(&collections[collection_id].lock);
    } else {
        log_warning("Failed to update offset for non-existent key %d in collection %d", key, collection_id);

        // Retry mechanism
        int retry_count = 0;
        while (retry_count < 3) {
            rec = get_record(collection_id, key);  // Re-attempt retrieval

            if (rec != NULL) {
                pthread_rwlock_wrlock(&collections[collection_id].lock);
                rec->offset = new_offset;
                log_info("Updated offset for key %d in collection %d after retry", key, collection_id);
                pthread_rwlock_unlock(&collections[collection_id].lock);
                break;
            }
            sleep_ms(RETRY_DELAY_MS);  // Hypothetical function to pause execution
            ++retry_count;
        }

        if (rec == NULL) {
            log_error("Failed to update offset after retries for key %d in collection %d", key, collection_id);
        }
    }
}

// Example usage and tests
void example_usage() {
