    list->max_size = max_size;
    list->current_size = 0;
    list->log_buffer_index = 0;

    return list;
}

void destroy_transaction_list(TransactionList* list) {
    if (!list) return;

    RecordNode *current = list->head, *next;
    while (current) {
        next = current->next;
        free(current->record.TX_BUFFER_DATA);
        free(current);
        current = next;
