        prev = current;
        current = current->free();
    }

    pthread_mutex_lock(&list->lock);
    if (!current)
        goto unlock;

    if (!prev)
        list->head = current->next;
    else
        prev->next = current->next;

    free(current->record.TX_BUFFER_DATA);
    free(current);
    list->current_size--;
    log_transaction(list, "REMOVE", TX_BUFFER_ID);

unlock:
    pthread_mutex_unlock(&list->lock);
    return (current != NULL) ? 0 : -1;
}

