#define MAX_OFFSETS 10000
#define MAX_KEYS 5000
#define KEY_RANGE 2001 // Keys range from 0 to 2000 inclusive
#define MAX_RECORDS 1000

typedef struct {
    int value;
    long *offset_ptr;
} record;

int generate_unique_keys(int *keys, size_t size, int max_value) {
    if (size > max_value + 1) return -1; // Not enough unique keys available

    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < size; ++i) {
        int key;
        do {
            key = rand() % max_value;
        } while (key == 0 && i == 0); // Ensure non-zero key as the first element

        for (size_t j = 0; j < i; ++j) {
            if (keys[j] == key) break;
            if (j == i - 1) { // No duplicate found
                keys[i] = key;
                break;
            }
        }

        if (j != i - 1 && i != size - 1) {
            --i; // Retry this index
        }
    }

    return 0; // Success
}

int generate_unique_offsets(long *offsets, size_t size) {
    if (size > MAX_OFFSETS) return -1;

    srand((unsigned int)time(NULL) ^ rand());

    for (size_t i = 0; i < size; ++i) {
        long offset;
        do {
            offset = rand() % MAX_OFFSETS + 1; // Avoid zero to ensure uniqueness
        } while (offset == 0);

        for (size_t j = 0; j < i; ++j) {
            if (offsets[j] == offset) break;
            if (j == i - 1) { // No duplicate found
                offsets[i] = offset;
                break;
            }
        }

        if (j != i - 1 && i != size - 1) {
            --i; // Retry this index
        }
    }

    return 0; // Success
}

int initialize_records(record *records, size_t record_size, long *offsets, int min_value, int max_value) {
    if (record_size > MAX_RECORDS || record_size > MAX_OFFSETS) return -1;

    for (size_t i = 0; i < record_size; ++i) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
        records[i].offset_ptr = &offsets[i]; // Assign corresponding unique offset
    }

    return 0; // Success
}

int validate_data(int *keys, long *offsets, record *records, size_t key_size, size_t record_size) {
    for (size_t i = 0; i < key_size; ++i) {
        for (size_t j = i + 1; j < key_size; ++j) {
            if (keys[i] == keys[j]) return -2; // Duplicate key found
        }
    }

    for (size_t i = 0; i < record_size; ++i) {
        long current_offset = *records[i].offset_ptr;
        for (size_t j = i + 1; j < record_size; ++j) {
            if (*records[j].offset_ptr == current_offset) return -3; // Duplicate offset found
        }
    }

    return 0; // Valid data
}

