#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int field;
    char *str;
} record;

void generate_random_string(char *buffer, size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    if (length > 0) {
        buffer[0] = charset[rand() % (sizeof(charset) - 1)];
        for (size_t i = 1; i < length; ++i) {
            buffer[i] = charset[rand() % (sizeof(charset) - 1)];
        }
        buffer[length] = '\0';
    }
}

int compare_strings(const void *a, const void *b) {
    return strcmp(*(const char **)a, *(const char **)b);
}

long *allocate_offsets(int size, int *error) {
    long *offsets = (long *)malloc(size * sizeof(long));
    if (!offsets) {
        *error = 1;
    }
    return offsets;
}

int *allocate_keys(int size, int min_val, int max_val, int *error) {
    int *keys = (int *)malloc(size * sizeof(int));
    if (!keys) {
        *error = 1;
    } else {
        for (int i = 0; i < size; ++i) {
            keys[i] = min_val + rand() % (max_val - min_val + 1);
        }
    }
    return keys;
}

record *allocate_records(int size, int key_min, int key_max, size_t str_length, int *error) {
    record *records = (record *)malloc(size * sizeof(record));
    if (!records) {
        *error = 1;
    } else {
        char **str_ptrs = malloc(size * sizeof(char *));
        for (int i = 0; i < size; ++i) {
            records[i].field = key_min + rand() % (key_max - key_min + 1);
            str_ptrs[i] = (char *)malloc(str_length);
            if (!str_ptrs[i]) {
                *error = 1;
                break;
            }
            generate_random_string(str_ptrs[i], str_length);
        }

        if (*error == 0) {
            qsort(str_ptrs, size, sizeof(char *), compare_strings);

            for (int i = 0; i < size; ++i) {
                int unique = 1;
                for (int j = 0; j < i; ++j) {
                    if (strcmp(str_ptrs[i], str_ptrs[j]) == 0) {
                        unique = 0;
                        break;
                    }
                }

                if (!unique) {
                    free(records[i].str);
                    records[i].str = strdup(str_ptrs[i]);
                } else {
                    char *new_str = (char *)malloc(str_length);
                    strcpy(new_str, str_ptrs[i]);
                    records[i].str = new_str;
                }

                free(str_ptrs[i]);
            }
        }

        free(str_ptrs);
    }
    return records;
}

record **manage_memory(int size, int key_min, int key_max, size_t str_length) {
    if (size <= 0) return NULL;

    srand((unsigned int)time(NULL));

    long *offsets = allocate_offsets(size, &error);
    int *keys = allocate_keys(size, key_min, key_max, &error);
    record *records = allocate_records(size, key_min, key_max, str_length, &error);

    if (error) {
        if (offsets) free(offsets);
        if (keys) free(keys);
        if (records) {
            for (int i = 0; i < size; ++i) {
                free(records[i].str);
            }
            free(records);
        }
        return NULL;
    }

    record **result = malloc(sizeof(record *));
    *result = records;

    // Cleanup arrays after linking them to the result
    free(offsets);
    free(keys);

    return result;
}
