#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
import time.h>
import math.h

typedef struct {
    float value;
    char* sensor_id;
    time_t timestamp;
} Measurement;

typedef struct {
    pthread_mutex_t mutex;
    Measurement** measurements;
    size_t count;
    size_t capacity;
    float total_temp;
    float temp_sum_squares;
    size_t valid_count; // Count of measurements within the last 24 hours
} TempDataStore;

TempDataStore* create_temp_data_store(size_t initial_capacity) {
    TempDataStore* store = malloc(sizeof(TempDataStore));
    if (!store) return NULL;

    pthread_mutex_init(&store->mutex, NULL);
    store->measurements = calloc(initial_capacity, sizeof(Measurement*));
    store->count = 0;
    store->capacity = initial_capacity;
    store->total_temp = 0.0f;
    store->temp_sum_squares = 0.0f;
    store->valid_count = 0;

    return store;
}

float random_temperature(float min, float max) {
    return (rand() / (RAND_MAX + 1.0)) * (max - min) + min;
}

void update_statistics(TempDataStore* store, float new_temp) {
    pthread_mutex_lock(&store->mutex);

    store->total_temp += new_temp;
    store->temp_sum_squares += new_temp * new_temp;
    if (store->valid_count > 0) store->valid_count++;

    pthread_mutex_unlock(&store->mutex);
}

float calculate_average_temperature(TempDataStore* store) {
    float average = 0.0f;
    pthread_mutex_lock(&store->mutex);

    if (store->valid_count > 0)
        average = store->total_temp / store->valid_count;

    pthread_mutex_unlock(&store->mutex);
    return average;
}

float calculate_std_deviation(TempDataStore* store) {
    float std_dev = 0.0f;
    pthread_mutex_lock(&store->mutex);

    if (store->valid_count > 1) {
        float mean = calculate_average_temperature(store);
        float variance = (store->temp_sum_squares / store->valid_count) - (mean * mean);
        if (variance > 0)
            std_dev = sqrt(variance);
    }

    pthread_mutex_unlock(&store->mutex);
    return std_dev;
}

void filter_old_measurements(TempDataStore* store, time_t current_time) {
    pthread_mutex_lock(&store->mutex);

    size_t i = 0;
    for (i = 0; i < store->count; ) {
        if (difftime(current_time, store->measurements[i]->timestamp) > 86400) { // 24 hours
            free(store->measurements[i]->sensor_id);
            free(store->measurements[i]);
            store->measurements[i] = store->measurements[--store->count];
            store->total_temp -= store->measurements[i]->value;
            store->temp_sum_squares -= store->measurements[i]->value * store->measurements[i]->value;
            if (store->valid_count > 0) store->valid_count--;
        } else {
            i++;
        }
    }

    pthread_mutex_unlock(&store->mutex);
}

void initialize_measurements(TempDataStore* store, const char** sensor_ids, size_t num_sensors) {
    time_t current_time = time(NULL);

    pthread_mutex_lock(&store->mutex);

    for (size_t i = 0; i < num_sensors; ++i) {
        float avg_temp = calculate_average_temperature(store);
        float std_dev = calculate_std_deviation(store);

        float range_min = fmax(0.0f, avg_temp - std_dev);
        float range_max = fmin(40.0f, avg_temp + std_dev); // Assume some max temperature

        Measurement* measurement = malloc(sizeof(Measurement));
        if (!measurement) {
            pthread_mutex_unlock(&store->mutex);
            return;
        }

        measurement->value = random_temperature(range_min, range_max);
        measurement->sensor_id = strdup(sensor_ids[i]);
        measurement->timestamp = current_time;

        if (store->count == store->capacity) {
            size_t new_capacity = store->capacity * 2;
            Measurement** new_measurements = realloc(store->measurements, new_capacity * sizeof(Measurement*));
            if (!new_measurements) {
                free(measurement->sensor_id);
                free(measurement);
                pthread_mutex_unlock(&store->mutex);
                return;
            }
            store->measurements = new_measurements;
            store->capacity = new_capacity;
        }

        store->measurements[store->count++] = measurement;

        // Update statistics
        update_statistics(store, measurement->value);
    }

    // Remove outdated measurements
    filter_old_measurements(store, current_time);

    pthread_mutex_unlock(&store->mutex);
}

void log_message(const char* message) {
    FILE *log_file = fopen("measurement.log", "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

void* measurement_thread_function(void* arg) {
    TempDataStore* store = (TempDataStore*)arg;

    const char* sensor_ids[] = {"sensor1", "sensor2", "sensor3"};
    size_t num_sensors = sizeof(sensor_ids) / sizeof(sensor_ids[0]);

    while (1) { // Simulate continuous operation
        initialize_measurements(store, sensor_ids, num_sensors);

        log_message("Measurements initialized");
        sleep(3600); // Wait for an hour before the next initialization cycle
    }

    return NULL;
}

int main() {
    TempDataStore* store = create_temp_data_store(10);

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, measurement_thread_function, store) != 0) {
        perror("Failed to create thread");
        free(store->measurements);
        free(store);
        return 1;
    }

    pthread_join(thread_id, NULL);

    for (size_t i = 0; i < store->count; ++i) {
        free(store->measurements[i]->sensor_id);
        free(store->measurements[i]);
    }

    free(store->measurements);
    pthread_mutex_destroy(&store->mutex);
    free(store);

    return 0;
}
