} Event;

// Function prototype
void initializeTelemetryData(size_t num_events, long *timestamp_offsets, int *event_ids,
                             Event **events_out, const char *order);

// Helper function to deallocate memory safely
static void safe_free(void *ptr) {
    if (ptr != NULL) {
        free(ptr);
        ptr = NULL;
    }
}

void initializeTelemetryData(size_t num_events, long *timestamp_offsets, int *event_ids,
                             Event **events_out, const char *order) {

    // Allocate memory with cache alignment
    void *aligned_mem = aligned_alloc(64, sizeof(long) * num_events + 
                                      sizeof(int) * num_events + 
                                      sizeof(Event) * num_events);

    if (!aligned_mem) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    long *timestamps = (long *)aligned_mem;
    int *ids = (int *)(timestamps + num_events);
    Event *events = (Event *)(ids + num_events);

    // Use the RNG library to initialize magnitudes
    for (size_t i = 0; i < num_events; ++i) {
        events[i].magnitude = random_lib_generate_double(0.0, 100.0); // Hypothetical function and range
    }

    // Copy timestamp offsets and event IDs into aligned arrays
    memcpy(timestamps, timestamp_offsets, sizeof(long) * num_events);
    memcpy(ids, event_ids, sizeof(int) * num_events);

    // Initialize events_out in the specified order
    if (strcmp(order, "asc") == 0) {
        *events_out = events;
    } else if (strcmp(order, "desc") == 0) {
        *events_out = (Event *)(ids + num_events);
        for (size_t i = 0; i < num_events / 2; ++i) {
            Event temp = events[i];
            events[i] = events[num_events - i - 1];
            events[num_events - i - 1] = temp;
        }
    } else {
        fprintf(stderr, "Unsupported order specified\n");
        safe_free(aligned_mem);
        return;
    }

    // Deferred cleanup strategy
    if (num_events > 1000) { // Arbitrary threshold for deferred cleanup
        atexit([]() {
            void *cleanup_mem = aligned_alloc(64, sizeof(long) * num_events + 
                                              sizeof(int) * num_events + 
                                              sizeof(Event) * num_events);
            safe_free(cleanup_mem);
        });
    } else {
        // Immediate deallocation if under threshold to free memory quickly
        safe_free(aligned_mem);
    }
}
