#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_EVENTS 10000

typedef enum { INFO, WARNING, ERROR } SeverityLevel;

typedef struct {
    char *key;
    char *value;
} Metadata;

typedef struct Event {
    time_t timestamp;
    SeverityLevel severity;
    char description[256];
    Metadata *metadata;
} Event;

typedef struct {
    Event **events;
    size_t count;
    size_t capacity;
} EventList;

void initEvent(Event *event, time_t ts, SeverityLevel sev, const char *desc, Metadata *meta) {
    event->timestamp = ts;
    event->severity = sev;
    strncpy(event->description, desc, sizeof(event->description) - 1);
    event->metadata = meta;
}

int validateEvent(const Event *event) {
    if (event == NULL || event->description[0] == '\0' || event->metadata == NULL)
        return 0;
    return 1;
}

void freeMetadata(Metadata *meta) {
    if (meta != NULL) {
        free(meta->key);
        free(meta->value);
        free(meta);
    }
}

void freeEvent(Event *event) {
    if (event != NULL) {
        free(event->metadata);
        free(event);
    }
}

int expandEventList(EventList *list) {
    size_t newCapacity = list->capacity == 0 ? 1 : list->capacity * 2;
    Event **newEvents = realloc(list->events, newCapacity * sizeof(Event *));
    if (newEvents == NULL)
        return 0;
    memset(newEvents + list->capacity, 0, newCapacity - list->capacity);
    list->events = newEvents;
    list->capacity = newCapacity;
    return 1;
}

int addEventToEventList(EventList *list, Event *event) {
    if (!validateEvent(event))
        return 0;

    if (list->count >= list->capacity && !expandEventList(list)) {
        fprintf(stderr, "Failed to expand event list\n");
        return 0;
    }

    list->events[list->count++] = event;
    return 1;
}

void processEvents(EventList *eventList) {
    for (size_t i = 0; i < eventList->count; ++i) {
        Event *event = eventList->events[i];
        // Integrate with third-party logging library here
        printf("Event: %s, Severity: %d\n", event->description, event->severity);
    }
}

void freeEventList(EventList *list) {
    for (size_t i = 0; i < list->count; ++i)
        freeEvent(list->events[i]);
    free(list->events);
    list->events = NULL;
    list->count = 0;
    list->capacity = 0;
}

int main() {
    EventList eventList = { .events = NULL, .count = 0, .capacity = 0 };

    // Example metadata creation and event addition
    Metadata *meta = malloc(sizeof(Metadata));
    meta->key = strdup("source");
    meta->value = strdup("sensor1");

    time_t ts = time(NULL);
    Event *event = malloc(sizeof(Event));
    initEvent(event, ts, INFO, "Temperature reading", meta);

    if (!addEventToEventList(&eventList, event)) {
        fprintf(stderr, "Failed to add event\n");
    }

    processEvents(&eventList);
    freeMeta(meta);
    freeEventList(&eventList);

    return 0;
}
