            }
            if (prev == NULL) { // Insert at head
                new_node->next = packet_queue->head;
                packet_queue->head = new_node;
            } else { // Insert in middle or end
                prev->next = new_node;
                new_node->next = curr;
            }
        }

        pthread_mutex_unlock(&packet_queue->lock);
        received_packets++;
    }

    printf("Packets Received: %d\n", received_packets);
    printf("Failed Checksums: %d\n", failed_checksums);
    printf("Out of Order Packets: %d\n", out_of_order);

    destroy_packet_queue(packet_queue);
    return 0;
}

int main() {
    const char *remote_address = "192.168.1.1";
    int max_packet_rate = 100; // Max packets per second
    size_t buffer_size = 32768; // Example dynamic buffer size
    double timeout_seconds = DEFAULT_TIMEOUT_SECONDS;

    return initializeNetworkPackets(remote_address, max_packet_rate, buffer_size, timeout_seconds);
}
```

