#define MAX_OFFSET 1000000000

typedef struct {
    int *key;
    long *offset;
    int *value;
} record;

void initialize_arrays(long *offsets, int *keys, size_t offset_size, int key_min, int key_max) {
    for (size_t i = 0; i < offset_size; ++i) {
        offsets[i] = i;
    }
    for (int i = key_min; i <= key_max; ++i) {
        keys[i - key_min] = i;
    }
}

void initialize_records(record *records, size_t record_count, int min_val, int max_val) {
    srand(time(NULL)); // Seed with current time for randomness
    for (size_t i = 0; i < record_count; ++i) {
        records[i].key = malloc(sizeof(int));
        records[i].offset = malloc(sizeof(long));
        records[i].value = malloc(sizeof(int));

        if (!records[i].key || !records[i].offset || !records[i].value) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        *records[i].key = rand() % (max_val - min_val + 1) + min_val;
        *records[i].offset = rand() % MAX_OFFSET;
        *records[i].value = rand() % (max_val - min_val + 1) + min_val;
    }
}

void free_memory(long *offsets, int *keys, size_t offset_size, record *records, size_t record_count) {
    for (size_t i = 0; i < record_count; ++i) {
        free(records[i].key);
        free(records[i].offset);
        free(records[i].value);
    }
    free(offsets);
    free(keys);
}

void manage_memory(size_t record_size, int random_min, int random_max) {
    if (record_size <= 0) return;

    // Allocate and initialize arrays
    long *offsets = malloc(MAX_OFFSET * sizeof(long));
    int *keys = malloc((random_max - random_min + 1) * sizeof(int));

    if (!offsets || !keys) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    initialize_arrays(offsets, keys, MAX_OFFSET, random_min, random_max);

    // Allocate and initialize records
    record *records = malloc(record_size * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        free_memory(offsets, keys, MAX_OFFSET, NULL, 0);
        exit(EXIT_FAILURE);
    }

    initialize_records(records, record_size, random_min, random_max);

    // Placeholder for logging and monitoring
    printf("Records initialized with size: %zu\n", record_size);

    // Free allocated memory
    free_memory(offsets, keys, MAX_OFFSET, records, record_size);
}

int main() {
    manage_memory(1000, -1000, 1000); // Example usage
    return 0;
}
