#define MAX_STRING_LENGTH 50

typedef struct {
    int key;
    char *str;
} record;

void generate_random_string(char *buffer, size_t max_length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    if (max_length > 0) {
        buffer[0] = '\0'; // Initialize as empty string
        for (size_t i = 0; i < max_length - 1; ++i) {
            int key = rand() % (sizeof(charset) - 1);
            strncat(buffer, &charset[key], 1);
        }
        buffer[max_length - 1] = '\0';
    }
}

int check_unique_string(const char *str, record *records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (strcmp(records[i].str, str) == 0) {
            return 0;
        }
    }
    return 1;
}

void free_resources(long *offsets, int *keys, record *records, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        free(records[i].str);
    }
    free(offsets);
    free(keys);
    free(records);
}

record* manage_memory(size_t size, int min_key, int max_key, size_t max_str_length) {
    if (size <= 0 || min_key >= max_key || max_str_length == 0) {
        return NULL;
    }

    srand((unsigned int)time(NULL));

    long *offsets = (long *)calloc(size, sizeof(long));
    int *keys = (int *)calloc(size, sizeof(int));
    record *records = (record *)malloc(size * sizeof(record));

    if (!offsets || !keys || !records) {
        free_resources(offsets, keys, records, size);
        return NULL;
    }

    char str_buffer[MAX_STRING_LENGTH + 1];

    for (size_t i = 0; i < size; ++i) {
        offsets[i] = rand() % size;

        do {
            keys[i] = min_key + rand() % (max_key - min_key + 1);
        } while ((i > 0 && keys[i] == keys[i - 1])); // Ensure uniqueness

        generate_random_string(str_buffer, max_str_length);

        record temp_record;
        temp_record.key = keys[i];
        temp_record.str = strdup(str_buffer);

        if (!temp_record.str) {
            free_resources(offsets, keys, records, size);
            return NULL;
        }

        while (!check_unique_string(temp_record.str, records, i)) {
            generate_random_string(str_buffer, max_str_length);
            free(temp_record.str); // Free the previous duplicate string
            temp_record.str = strdup(str_buffer);

            if (!temp_record.str) {
                free_resources(offsets, keys, records, size);
                return NULL;
            }
        }

        records[i] = temp_record;
    }

    return records;
}

int main() {
    size_t size = 10;
    int min_key = 1;
    int max_key = 100;
    size_t max_str_length = 10;

    record *records = manage_memory(size, min_key, max_key, max_str_length);

    if (records) {
        for (size_t i = 0; i < size; ++i) {
            printf("Record %zu: Key = %d, String = %s\n", i, records[i].key, records[i].str);
        }

        free_resources(NULL, NULL, records, size);
    } else {
        fprintf(stderr, "Memory allocation failed.\n");
    }

    return 0;
}
