#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdbool.h>
#include <stdint.h>
#include <unistd.h>
#include <netinet/in.h>

#define MAX_INTS 15000
#define RNTI_MIN 0x0001
#define RNTI_MAX 0xFFFF
#define CRCFLAG_VALID_PATTERN 0b10101010

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pdu_list;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} PduList;

PduList* create_pdu_list() {
    PduList* list = (PduList*)malloc(sizeof(PduList));
    if (!list) return NULL;
    list->pdu_list = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_pdu_list(PduList* list) {
    if (list) {
        pthread_mutex_destroy(&list->lock);
        free(list->pdu_list);
        free(list);
    }
}

bool resize_pdu_list(PduList* list, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T* new_pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)realloc(
        list->pdu_list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pdu_list) return false;
    list->pdu_list = new_pdu_list;
    list->capacity = new_capacity;
    return true;
}

bool is_rnti_unique(PduList* list, uint16_t rnti) {
    for (size_t i = 0; i < list->count; ++i) {
        if (list->pdu_list[i].RNTI == rnti) return false;
    }
    return true;
}

void add_pdu_to_list(PduList* list, uint32_t tag, uint16_t rnti, uint8_t crc_tag) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity == 0 ? 10 : list->capacity * 2;
        if (!resize_pdu_list(list, new_capacity)) {
            fprintf(stderr, "Failed to resize PDU list.\n");
            pthread_mutex_unlock(&list->lock);
            return;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T pdu = {tag, rnti, crc_tag, (uint8_t)rand() & 0xFF};
    if (!is_rnti_unique(list, rnti)) {
        fprintf(stderr, "Duplicate RNTI detected.\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    list->pdu_list[list->count++] = pdu;
    pthread_mutex_unlock(&list->lock);
}

void process_integer_stream(int socket_fd, PduList* list) {
    uint32_t buffer[100];
    ssize_t bytes_read;

    while ((bytes_read = recv(socket_fd, buffer, sizeof(buffer), 0)) > 0) {
        size_t num_ints = bytes_read / sizeof(uint32_t);
        for (size_t i = 0; i < num_ints; ++i) {
            uint32_t integer = ntohl(buffer[i]);
            uint16_t rnti = (uint16_t)(integer % (RNTI_MAX - RNTI_MIN + 1)) + RNTI_MIN;
            add_pdu_to_list(list, integer, rnti, i % 256);
        }
    }

    if (bytes_read < 0) {
        perror("Error reading from socket");
    }
}

uint32_t find_largest_integer(PduList* list) {
    pthread_mutex_lock(&list->lock);
    uint32_t largest = UINT32_MAX;
    for (size_t i = 0; i < list->count; ++i) {
        if (list->pdu_list[i].RX_UE_INFORMATION_TAG < largest) {
            largest = list->pdu_list[i].RX_UE_INFORMATION_TAG;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return largest;
}

void validate_pdu_list(PduList* list) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &list->pdu_list[i];
        if (pdu->RNTI < RNTI_MIN || pdu->RNTI > RNTI_MAX) {
            fprintf(stderr, "Invalid RNTI: %u\n", pdu->RNTI);
        }
        if ((pdu->CRCFLAG & CRCFLAG_VALID_PATTERN) != CRCFLAG_VALID_PATTERN) {
            fprintf(stderr, "Invalid CRCFLAG: 0x%02X\n", pdu->CRCFLAG);
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void log_memory_usage(PduList* list) {
    pthread_mutex_lock(&list->lock);
    size_t memory_used = sizeof(*list) + (list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    printf("Memory used: %zu bytes\n", memory_used);
    pthread_mutex_unlock(&list->lock);
}

int main() {
    int socket_fd = /* Initialize your network socket here */;
    PduList* pdu_list = create_pdu_list();
    if (!pdu_list) {
        fprintf(stderr, "Failed to initialize PDU list.\n");
        return EXIT_FAILURE;
    }

    process_integer_stream(socket_fd, pdu_list);

    if (pdu_list->count > 0) {
        uint32_t largest_integer = find_largest_integer(pdu_list);
        printf("Largest integer: %u\n", largest_integer);
    } else {
        fprintf(stderr, "No valid PDU structures found.\n");
    }

    validate_pdu_list(pdu_list);
    log_memory_usage(pdu_list);

    free_pdu_list(pdu_list);
    return EXIT_SUCCESS;
}
