#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INITIAL_POOL_SIZE 10

typedef struct {
    double value;
    char* id;
    int count;
} Item;

typedef struct {
    size_t item_size;
    void* pool;
    size_t pool_capacity;
    size_t used;
} MemoryPool;

MemoryPool* create_memory_pool(size_t item_size) {
    MemoryPool* mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!mp) return NULL;

    mp->item_size = item_size;
    mp->pool_capacity = INITIAL_POOL_SIZE;
    mp->used = 0;

    mp->pool = malloc(mp->item_size * mp->pool_capacity);
    if (!mp->pool) {
        free(mp);
        return NULL;
    }
    return mp;
}

void* memory_pool_allocate(MemoryPool* mp) {
    if (mp->used >= mp->pool_capacity) {
        size_t new_capacity = mp->pool_capacity * 2;
        void* new_pool = realloc(mp->pool, mp->item_size * new_capacity);

        if (!new_pool) return NULL;

        mp->pool = new_pool;
        mp->pool_capacity = new_capacity;
    }

    char* ptr = (char*)mp->pool + (mp->used * mp->item_size);
    mp->used++;
    return ptr;
}

void memory_pool_free(MemoryPool* mp) {
    free(mp->pool);
    free(mp);
}

void cleanup_memory_pool(MemoryPool** pools, size_t pool_count) {
    for (size_t i = 0; i < pool_count; ++i) {
        if (pools[i]) {
            memory_pool_free(pools[i]);
            pools[i] = NULL;
        }
    }
}

Item* create_item(MemoryPool* mp, double value, const char* id, int count) {
    Item* item = (Item*)memory_pool_allocate(mp);
    if (!item) return NULL;

    item->value = value;
    item->id = strdup(id); // Handle potential memory allocation failure
    if (!item->id) {
        free(item);  // Clean up partially allocated item
        return NULL;
    }
    item->count = count;

    return item;
}

void delete_item(MemoryPool* mp, Item* item) {
    if (item) {
        free(item->id);
        // No need to explicitly deallocate `Item` from the pool; it's part of the memory pool
    }
}

// Example usage function that initializes a collection from an external data source.
void populate_items_from_source(MemoryPool* mp, const char* source) {
    // Simulate loading items from an external data source (e.g., file or database)
    double sample_values[] = {1.0, 2.0, 3.0};
    char* sample_ids[] = {"ID1", "ID2", "ID3"};

    size_t num_items = sizeof(sample_values) / sizeof(double);
    for (size_t i = 0; i < num_items; ++i) {
        Item* item = create_item(mp, sample_values[i], sample_ids[i], i + 1);
        if (!item) {
            printf("Failed to allocate memory for an item.\n");
        }
    }
}

int main() {
    MemoryPool* mp = create_memory_pool(sizeof(Item));
    if (!mp) {
        fprintf(stderr, "Failed to create memory pool.\n");
        return EXIT_FAILURE;
    }

    populate_items_from_source(mp, "dummy_source");

    // Periodically clean up unused resources
    cleanup_memory_pool(&mp, 1);

    return EXIT_SUCCESS;
}
