import pthread.h

#define INITIAL_CAPACITY 10
#define SUCCESS 0
#define FAILURE -1

typedef struct {
    time_t timestamp;
    size_t packet_size;
    void *data;
} Packet;

typedef struct {
    Packet **packets;
    size_t capacity;
    size_t count;
    size_t successful_creations;
    size_t failed_allocations;
    pthread_mutex_t lock;
} PacketManager;

void init_packet_manager(PacketManager *manager) {
    manager->packets = malloc(INITIAL_CAPACITY * sizeof(Packet *));
    if (!manager->packets) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;
    manager->successful_creations = 0;
    manager->failed_allocations = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

void destroy_packet_manager(PacketManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->packets[i]->data);
        free(manager->packets[i]);
    }
    free(manager->packets);
    pthread_mutex_destroy(&manager->lock);
}

static int resize_array(PacketManager *manager, size_t new_capacity) {
    Packet **new_packets = realloc(manager->packets, new_capacity * sizeof(Packet *));
    if (!new_packets) {
        manager->failed_allocations++;
        return FAILURE;
    }
    manager->capacity = new_capacity;
    manager->packets = new_packets;
    return SUCCESS;
}

int add_packet(PacketManager *manager, time_t timestamp, size_t packet_size, void *data) {
    pthread_mutex_lock(&manager->lock);

    if (packet_size == 0 || data == NULL) {
        fprintf(stderr, "Malformed packet data\n");
        pthread_mutex_unlock(&manager->lock);
        return FAILURE;
    }

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        if (resize_array(manager, new_capacity) == FAILURE) {
            pthread_mutex_unlock(&manager->lock);
            return FAILURE;
        }
    }

    Packet *packet = malloc(sizeof(Packet));
    if (!packet) {
        manager->failed_allocations++;
        pthread_mutex_unlock(&manager->lock);
        return FAILURE;
    }

    packet->timestamp = timestamp;
    packet->packet_size = packet_size;
    packet->data = malloc(packet_size);
    if (!packet->data) {
        free(packet);
        manager->failed_allocations++;
        pthread_mutex_unlock(&manager->lock);
        return FAILURE;
    }
    memcpy(packet->data, data, packet_size);

    manager->packets[manager->count++] = packet;
    manager->successful_creations++;

    pthread_mutex_unlock(&manager->lock);
    return SUCCESS;
}

void update_crc_flags(PacketManager *manager) {
    // Simulate periodic updates from external data source.
    // Handle latency and ensure consistency.
    for (size_t i = 0; i < manager->count; ++i) {
        // Update CRC flag logic here
    }
}

