void* aligned_alloc(size_t alignment, size_t size) {
    void* ptr = NULL;
#if defined(_WIN32)
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL; 
    }
#else
    ptr = memalign(alignment, size);
#endif
    return ptr;
}

void initializeTelemetryData(long numEvents, long* timestamps, int* eventIDs, Event** events) {
    // Allocate memory for timestamps and event IDs with optimal alignment
    *timestamps = (long*) aligned_alloc(64, sizeof(long) * numEvents);
    if (!(*timestamps)) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    *eventIDs = (int*) aligned_alloc(64, sizeof(int) * numEvents);
    if (!(*eventIDs)) {
        free(*timestamps);
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for events with optimal alignment
    *events = (Event*) aligned_alloc(64, sizeof(Event) * numEvents);
    if (!(*events)) {
        free(*timestamps);
        free(*eventIDs);
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    // Initialize random number generator
    random_init();

#ifdef _OPENMP
#pragma omp parallel for
#endif
    for (long i = 0; i < numEvents; ++i) {
        (*timestamps)[i] = time(NULL);  // For simplicity, use current time offset
        (*eventIDs)[i] = rand() % 10000;  // Random event ID
        (*events)[i].magnitude = random_double(0.0, 10.0);  // Random magnitude between 0 and 10
    }

#ifdef _OPENMP
#pragma omp parallel for
#endif
    for (long i = 0; i < numEvents; ++i) {
        // Copy timestamp and event ID into the event structure
        (*events)[i].magnitude = ((double)(*timestamps)[i] + (double)(*eventIDs)[i]) / 2.0;
    }

    random_cleanup();
}

static char* generateMD5Hash(const char* inputStr) {
    if (!inputStr) return NULL;

    unsigned char digest[16];
    md5_state_t mdContext;
    char hexResult[33];

    md5_init(&mdContext);
    md5_append(&mdContext, (const unsigned char*)inputStr, strlen(inputStr));
    md5_finish(&mdContext, digest);

    for (int i = 0; i < 16; ++i) {
        snprintf(&(hexResult[i * 2]), 3, "%02x", digest[i]);
    }

    hexResult[32] = '\0';
    return strdup(hexResult);
}

// Example usage
int main() {
    long numEvents = 1000000;
    long* timestamps = NULL;
    int* eventIDs = NULL;
    Event* events = NULL;

    initializeTelemetryData(numEvents, &timestamps, &eventIDs, &events);

    // Generate an MD5 hash example
    const char* sampleStr = "Sample string for hashing";
    char* md5Hash = generateMD5Hash(sampleStr);
    if (md5Hash) {
        printf("MD5 Hash: %s\n", md5Hash);
        free(md5Hash);
    }

    // Cleanup
    free(timestamps);
    free(eventIDs);
    free(events);

    return 0;
}
