#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define TABLE_SIZE 1000
#define STRING_LENGTH 20

typedef struct Record {
    int key;
    int value;
    char *name;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

typedef struct HashTable {
    Node* buckets[TABLE_SIZE];
    pthread_mutex_t locks[TABLE_SIZE];
} HashTable;

HashTable* createHashTable() {
    HashTable* table = malloc(sizeof(HashTable));
    if (!table) return NULL;

    for (int i = 0; i < TABLE_SIZE; i++) {
        table->buckets[i] = NULL;
        pthread_mutex_init(&table->locks[i], NULL);
    }

    return table;
}

unsigned int hash(int key) {
    return key % TABLE_SIZE;
}

Record generateRandomRecord(int minVal, int maxVal, size_t strLen) {
    Record rec;
    rec.key = rand() % (maxVal - minVal + 1) + minVal;
    rec.value = rand() % (maxVal - minVal + 1) + minVal;

    rec.name = malloc(strLen + 1);
    if (!rec.name) return rec; // Handle allocation failure

    for (size_t i = 0; i < strLen; ++i) {
        rec.name[i] = 'a' + rand() % 26;
    }
    rec.name[strLen] = '\0';

    return rec;
}

void insertRecord(HashTable* table, Record record) {
    unsigned int index = hash(record.key);
    pthread_mutex_lock(&table->locks[index]);

    Node* newNode = malloc(sizeof(Node));
    if (!newNode) {
        // Handle allocation failure
        pthread_mutex_unlock(&table->locks[index]);
        return;
    }

    newNode->record = record;
    newNode->next = table->buckets[index];
    table->buckets[index] = newNode;

    pthread_mutex_unlock(&table->locks[index]);
}

void cleanupHashTable(HashTable* table) {
    for (int i = 0; i < TABLE_SIZE; ++i) {
        Node* current = table->buckets[i];
        while (current != NULL) {
            Node* temp = current;
            current = current->next;

            free(temp->record.name);
            free(temp);
        }
        pthread_mutex_destroy(&table->locks[i]);
    }
    free(table);
}

void initializeRecords(HashTable* table, int numRecords, int minVal, int maxVal) {
    for (int i = 0; i < numRecords; ++i) {
        Record rec = generateRandomRecord(minVal, maxVal, STRING_LENGTH);
        insertRecord(table, rec);
    }
}

// Usage example in main
int main() {
    srand(time(NULL));

    HashTable* table = createHashTable();
    if (!table) {
        fprintf(stderr, "Failed to initialize hash table\n");
        return 1;
    }

    initializeRecords(table, 1000, 0, 9999);

    // Assume some processing here

    cleanupHashTable(table);
    return 0;
}
```

### Performance Considerations:

- **Space Complexity**: The space complexity is driven by the number of records and their associated strings. Using a pool strategy could further optimize this if implemented.

- **Time Complexity**:
  - **Insertion**: O(1) on average due to hash table with chaining.
  - **Lookup/Deletion**: O(n/k) where n is the number of entries, and k is the load factor; typically efficient for well-distributed keys.

- **Thread Safety**: Mutexes are used to synchronize access to individual buckets. This minimizes contention by allowing concurrent access to different buckets but may introduce some overhead due to locking.

- **Memory Management**: The pool allocation strategy can be added to reduce fragmentation and improve performance in high-memory-use scenarios, though not implemented here for simplicity.

- **Error Handling**: Graceful handling of memory allocation failures ensures that the application remains stable even under adverse conditions.']

