#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
import "json-c/json.h"
#include "log_destination.h"
#include "log_buffer.h"
#include "network_manager.h"

// Define log levels
typedef enum {
    LOG_DEBUG,
    LOG_INFO,
    LOG_WARN,
    LOG_ERROR,
    LOG_CRITICAL
} LogLevel;

// Log entry structure
typedef struct {
    LogLevel level;
    char *timestamp;
    char *message;
} LogEntry;

// Logging configuration
typedef struct {
    LogLevel log_level;
    char output_format[50];
    char *destination_priority_list[3]; // File, Console, Network
    pthread_mutex_t lock;
    LogBuffer *log_buffer;
    NetworkManager *network_manager;
} LogConfig;

// Function declarations
void parse_config_file(const char *file_path, LogConfig *config);
void log_writer_thread(LogConfig *config);
void handle_log_entry(LogEntry *entry, LogConfig *config);
void retry_with_exponential_backoff(void (*operation)(LogConfig *), LogConfig *config);

// Main function to configure logging system
void configureLoggingSystem(const char *config_file_path) {
    LogConfig config;
    memset(&config, 0, sizeof(config));
    pthread_mutex_init(&config.lock, NULL);

    parse_config_file(config_file_path, &config);

    // Initialize log buffer and network manager
    config.log_buffer = init_log_buffer();
    config.network_manager = init_network_manager();

    // Start log writer thread
    pthread_t writer_thread;
    if (pthread_create(&writer_thread, NULL, (void *(*)(void *))log_writer_thread, &config) != 0) {
        perror("Failed to create log writer thread");
        exit(EXIT_FAILURE);
    }
}

// Parse configuration file and set up logging parameters
void parse_config_file(const char *file_path, LogConfig *config) {
    FILE *fp = fopen(file_path, "r");
    if (!fp) {
        perror("Failed to open config file");
        exit(EXIT_FAILURE);
    }

    fseek(fp, 0, SEEK_END);
    long length = ftell(fp);
    fseek(fp, 0, SEEK_SET);

    char *json_str = (char *)malloc(length + 1);
    fread(json_str, 1, length, fp);
    json_str[length] = '\0';
    fclose(fp);

    struct json_object *parsed_json;
    parsed_json = json_tokener_parse(json_str);
    free(json_str);

    // Extract log level
    struct json_object *log_level_obj;
    if (json_object_object_get_ex(parsed_json, "log_level", &log_level_obj)) {
        const char *level_str = json_object_get_string(log_level_obj);
        if (!strcmp(level_str, "DEBUG")) config->log_level = LOG_DEBUG;
        else if (!strcmp(level_str, "INFO")) config->log_level = LOG_INFO;
        else if (!strcmp(level_str, "WARN")) config->log_level = LOG_WARN;
        else if (!strcmp(level_str, "ERROR")) config->log_level = LOG_ERROR;
        else if (!strcmp(level_str, "CRITICAL")) config->log_level = LOG_CRITICAL;
    }

    // Extract output format
    struct json_object *output_format_obj;
    if (json_object_object_get_ex(parsed_json, "output_format", &output_format_obj)) {
        strncpy(config->output_format, json_object_get_string(output_format_obj), sizeof(config->output_format) - 1);
    }

    // Extract destination priority list
    struct json_object *destinations_obj;
    int index = 0;
    if (json_object_object_get_ex(parsed_json, "destination_priority_list", &destinations_obj)) {
        size_t n_entries = json_object_array_length(destinations_obj);
        for (size_t i = 0; i < n_entries && index < 3; i++) {
            struct json_object *entry = json_object_array_get_idx(destinations_obj, i);
            config->destination_priority_list[index++] = strdup(json_object_get_string(entry));
        }
    }

    json_object_put(parsed_json);
}

// Log writer thread function
void log_writer_thread(LogConfig *config) {
    while (1) {
        pthread_mutex_lock(&config->lock);
        LogEntry entry = pop_log_entry(config->log_buffer);
        if (entry.message != NULL) {
            handle_log_entry(&entry, config);
            free(entry.timestamp);
            free(entry.message);
        }
        pthread_mutex_unlock(&config->lock);
        usleep(1000); // Sleep for 1ms
    }
}

// Handle individual log entry
void handle_log_entry(LogEntry *entry, LogConfig *config) {
    if (entry->level < config->log_level) return;

    char formatted_message[256];
    snprintf(formatted_message, sizeof(formatted_message), "[%s] %d: %s", entry->timestamp, entry->level, entry->message);

    for (int i = 0; i < 3 && config->destination_priority_list[i] != NULL; i++) {
        if (!strcmp(config->destination_priority_list[i], "file")) {
            retry_with_exponential_backoff(write_log_to_file, config);
        } else if (!strcmp(config->destination_priority_list[i], "console")) {
            printf("%s\n", formatted_message);
        } else if (!strcmp(config->destination_priority_list[i], "network")) {
            retry_with_exponential_backoff(send_log_over_network, config);
        }
    }
}

// Retry logic with exponential backoff
void retry_with_exponential_backoff(void (*operation)(LogConfig *), LogConfig *config) {
    int retries = 0;
    while (retries < 5) {
        if ((*operation)(config)) break; // Success
        sleep((1 << retries)); // Exponential backoff
        retries++;
    }
}

// Write log to file operation
int write_log_to_file(LogConfig *config) {
    FILE *fp = fopen("log.txt", "a");
    if (!fp) return 0;

    pthread_mutex_lock(&config->lock);
    LogEntry entry = pop_log_entry(config->log_buffer);
    if (entry.message != NULL) {
        fprintf(fp, "[%s] %d: %s\n", entry.timestamp, entry.level, entry.message);
        free(entry.timestamp);
        free(entry.message);
    }
    pthread_mutex_unlock(&config->lock);

    fclose(fp);
    return 1;
}

// Send log over network operation
int send_log_over_network(LogConfig *config) {
    // Implementation of sending log over the network using config->network_manager
    return config->network_manager->send(config->log_buffer);
}
