#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Node {
    int data;
    struct Node* next;
    unsigned long id; // Unique identifier based on hash function
} Node;

unsigned long hashFunction(int data) {
    return ((unsigned long)data * 2654435761 % (1UL << 32));
}

Node** createLinkedList(int numValues, int* errorFlag);
int* createValuesArray(int numValues, int* errorFlag);
void** createHashTable(int numBuckets, int* errorFlag);

Node** initializeSystem(int numValues, int numBuckets) {
    if (numValues <= 0 || numBuckets <= 0) {
        fprintf(stderr, "Invalid number of values or buckets.\n");
        return NULL;
    }

    srand(time(NULL));
    Node** linkedList = createLinkedList(numValues, NULL);
    if (!linkedList) {
        fprintf(stderr, "Failed to allocate memory for linked list.\n");
        return NULL;
    }

    int* values = createValuesArray(numValues, NULL);
    if (!values) {
        free(linkedList);
        fprintf(stderr, "Failed to allocate memory for values array.\n");
        return NULL;
    }

    void** hashTable = createHashTable(numBuckets, NULL);
    if (!hashTable) {
        free(linkedList);
        free(values);
        fprintf(stderr, "Failed to allocate memory for hash table.\n");
        return NULL;
    }

    // Initialize linked list and values array
    for (int i = 0; i < numValues; ++i) {
        int data;
        do {
            data = rand() % 10001;
        } while (linkedList[i] && linkedList[i]->data == data);

        Node* newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) {
            fprintf(stderr, "Memory allocation failed for a new node.\n");
            // Clean up
            for (int j = 0; j <= i; ++j) {
                free(linkedList[j]);
            }
            free(linkedList);
            free(values);
            free(hashTable);
            return NULL;
        }

        newNode->data = data;
        newNode->next = NULL;
        newNode->id = hashFunction(data);

        linkedList[i] = newNode;

        // Initialize values array
        values[data]++;
    }

    // Populate hash table with frequency information
    for (int i = 0; i < numValues; ++i) {
        int data = linkedList[i]->data;
        unsigned long index = linkedList[i]->id % numBuckets;

        Node* newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) {
            fprintf(stderr, "Memory allocation failed for hash table node.\n");
            // Clean up
            for (int j = 0; j <= i; ++j) {
                free(linkedList[j]);
            }
            free(linkedList);
            free(values);
            free(hashTable);
            return NULL;
        }

        newNode->data = values[data];
        newNode->next = (Node*)hashTable[index];
        hashTable[index] = newNode;
    }

    // Return head of the linked list
    return linkedList;
}

Node** createLinkedList(int numValues, int* errorFlag) {
    Node** linkedList = (Node**)malloc(numValues * sizeof(Node*));
    if (!linkedList && errorFlag) *errorFlag = 1;
    return linkedList;
}

int* createValuesArray(int numValues, int* errorFlag) {
    int* values = (int*)calloc(10001, sizeof(int)); // Max data value is 10000
    if (!values && errorFlag) *errorFlag = 1;
    return values;
}

void** createHashTable(int numBuckets, int* errorFlag) {
    void** hashTable = (void**)malloc(numBuckets * sizeof(void*));
    if (!hashTable && errorFlag) *errorFlag = 1;
