#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define DEFAULT_POOL_SIZE 1024

typedef struct {
    int value;
} Record;

typedef struct {
    size_t current_size;
    size_t max_size;
    void* pool;
    size_t allocation_count;
    size_t deallocation_count;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_size) {
    MemoryPool* mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!mp) return NULL;
    mp->pool = malloc(initial_size);
    if (!mp->pool) {
        free(mp);
        return NULL;
    }
    mp->current_size = 0;
    mp->max_size = initial_size;
    mp->allocation_count = 0;
    mp->deallocation_count = 0;
    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

void* pool_alloc(MemoryPool* mp, size_t size) {
    pthread_mutex_lock(&mp->lock);
    void* ptr = malloc(size);
    if (ptr) {
        mp->current_size += size;
        mp->allocation_count++;
        if (mp->current_size > mp->max_size)
            mp->max_size = mp->current_size;
    }
    pthread_mutex_unlock(&mp->lock);
    return ptr;
}

void pool_free(MemoryPool* mp, void* ptr) {
    pthread_mutex_lock(&mp->lock);
    free(ptr);
    mp->deallocation_count++;
    pthread_mutex_unlock(&mp->lock);
}

void destroy_memory_pool(MemoryPool* mp) {
    if (mp) {
        free(mp->pool);
        pthread_mutex_destroy(&mp->lock);
        free(mp);
    }
}

Record* manage_records(size_t numOffsets, size_t numRecords, size_t maxRecordSize, size_t maxMemoryUsage) {
    if (!numOffsets || !numRecords || !maxRecordSize || maxRecordSize > 10000)
        return NULL;

    MemoryPool* mp = create_memory_pool(DEFAULT_POOL_SIZE);
    if (!mp) {
        fprintf(stderr, "Failed to initialize memory pool\n");
        return NULL;
    }

    int* keys = (int*)pool_alloc(mp, numOffsets * sizeof(int));
    int* offsets = (int*)pool_alloc(mp, numOffsets * sizeof(int));

    Record* records = (Record*)pool_alloc(mp, numRecords * maxRecordSize * sizeof(Record));
    if (!keys || !offsets || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        pool_free(mp, keys);
        pool_free(mp, offsets);
        pool_free(mp, records);
        destroy_memory_pool(mp);
        return NULL;
    }

    srand(time(NULL));

    for (size_t i = 0; i < numOffsets; ++i) {
        keys[i] = i;
        offsets[i] = rand() % 1001;
    }

    int used_values[10001] = {0};
    for (size_t i = 0; i < numRecords; ++i) {
        int value;
        do {
            value = rand() % 10001;
        } while (used_values[value]);
        used_values[value] = 1;

        size_t record_index = rand() % maxRecordSize;
        records[i * maxRecordSize + record_index].value = value;
    }

    if (mp->current_size > maxMemoryUsage) {
        fprintf(stderr, "Exceeding maximum memory usage threshold\n");
        pool_free(mp, keys);
        pool_free(mp, offsets);
        pool_free(mp, records);
        destroy_memory_pool(mp);
        return NULL;
    }

    printf("Memory Pool Usage: %zu allocations, %zu deallocations. Max size: %zu\n",
           mp->allocation_count, mp->deallocation_count, mp->max_size);

    // Clean up
    pool_free(mp, keys);
    pool_free(mp, offsets);
    destroy_memory_pool(mp);

    return records;
}
```

