#define MAX_THREADS 8

typedef struct {
    uint32_t RNTI;
    uint16_t RX_UE_INFORMATION_TAG;
    struct {
        bool CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Custom memory management system
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct Node *next;
} Node;

static Node *freeList = NULL;
pthread_mutex_t memMutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu() {
    pthread_mutex_lock(&memMutex);
    if (freeList != NULL) {
        Node *node = freeList;
        freeList = node->next;
        NFAPI_CRC_INDICATION_PDU_T *pdu = node->data;
        node->data = NULL; // Clearing pointer for safety
        pthread_mutex_unlock(&memMutex);
        return pdu;
    }
    pthread_mutex_unlock(&memMutex);

    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    return pdu;
}

void deallocate_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (!pdu) return;

    Node *node = (Node *)malloc(sizeof(Node));
    node->data = pdu;
    pthread_mutex_lock(&memMutex);
    node->next = freeList;
    freeList = node;
    pthread_mutex_unlock(&memMutex);

    // Optional: periodically run a garbage collection thread to free unused memory
}

// Serialization and Deserialization functions
size_t serialize_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu, uint8_t **buffer) {
    size_t size = sizeof(uint32_t) + sizeof(uint16_t) + sizeof(bool);
    *buffer = (uint8_t*)malloc(size);
    if (!*buffer) return 0;

    memcpy(*buffer, &pdu->RNTI, sizeof(pdu->RNTI));
    memcpy(*buffer + sizeof(pdu->RNTI), &pdu->RX_UE_INFORMATION_TAG, sizeof(pdu->RX_UE_INFORMATION_TAG));
    memcpy(*buffer + sizeof(pdu->RNTI) + sizeof(pdu->RX_UE_INFORMATION_TAG), &pdu->CRC_INDICATION_REL8_TAG.CRCFLAG, sizeof(pdu->CRC_INDICATION_REL8_TAG.CRCFLAG));

    return size;
}

NFAPI_CRC_INDICATION_PDU_T* deserialize_pdu(uint8_t *buffer) {
    if (!buffer) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *pdu = allocate_pdu();
    memcpy(&pdu->RNTI, buffer, sizeof(pdu->RNTI));
    memcpy(&pdu->RX_UE_INFORMATION_TAG, buffer + sizeof(pdu->RNTI), sizeof(pdu->RX_UE_INFORMATION_TAG));
    memcpy(&pdu->CRC_INDICATION_REL8_TAG.CRCFLAG, buffer + sizeof(pdu->RNTI) + sizeof(pdu->RX_UE_INFORMATION_TAG), sizeof(pdu->CRC_INDICATION_REL8_TAG.CRCFLAG));

    return pdu;
}

// Parallel processing mechanism
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t index;
} ThreadData;

void* process_pdu(void *arg) {
    ThreadData *thread_data = (ThreadData *)arg;
    // Simulate some processing on the data
    thread_data->data[thread_data->index].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2 == 0; 
    pthread_exit(NULL);
}

void parallel_process_pdu_list(NFAPI_CRC_INDICATION_PDU_T **list, size_t count) {
    int num_threads = MAX_THREADS;
    pthread_t threads[MAX_THREADS];
    ThreadData thread_data[MAX_THREADS];

    for (size_t i = 0; i < count; i += num_threads) {
        size_t current_batch = count - i < num_threads ? count - i : num_threads;

        for (int j = 0; j < current_batch; ++j) {
            thread_data[j].data = list;
            thread_data[j].index = i + j;
            pthread_create(&threads[j], NULL, process_pdu, &thread_data[j]);
        }

        for (int j = 0; j < current_batch; ++j) {
            pthread_join(threads[j], NULL);
        }
    }
}

// Error handling wrapper function
void safe_process(NFAPI_CRC_INDICATION_PDU_T **list, size_t count) {
    if (!list || !count) {
        fprintf(stderr, "Invalid input\n");
        return;
    }

    parallel_process_pdu_list(list, count);
}

int main() {
    srand(time(NULL));

    size_t num_pdus = 1000; // Example number of PDU structures
    NFAPI_CRC_INDICATION_PDU_T **list = (NFAPI_CRC_INDICATION_PDU_T **)malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T *));

    for (size_t i = 0; i < num_pdus; ++i) {
        list[i] = allocate_pdu();
        // Initialize with some example values
        list[i]->RNTI = rand();
        list[i]->RX_UE_INFORMATION_TAG = rand() % 65535;
        list[i]->CRC_INDICATION_REL8_TAG.CRCFLAG = false;
    }

    safe_process(list, num_pdus);

    for (size_t i = 0; i < num_pdus; ++i) {
        deallocate_pdu(list[i]);
    }
    free(list);

    return 0;
}

