#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <time.h>

// Assume these are part of the logging framework and analytics service.
void log_packet(const char* message);
void send_analytics_data(const char* data);

#define MAX_PACKETS 10000
#define PACKET_SIZE_MAX 1500

typedef struct {
    uint64_t timestamp;
    size_t packet_size;
    void *data_ptr;
} Packet;

typedef struct {
    Packet *packets[MAX_PACKETS];
    pthread_mutex_t lock;
    int count;
} PacketArray;

PacketArray* init_packet_array() {
    PacketArray *array = (PacketArray*)malloc(sizeof(PacketArray));
    if (!array) return NULL;

    for (int i = 0; i < MAX_PACKETS; i++) {
        array->packets[i] = NULL;
    }
    pthread_mutex_init(&array->lock, NULL);
    array->count = 0;

    return array;
}

void cleanup_packet_array(PacketArray *array) {
    if (!array) return;

    for (int i = 0; i < MAX_PACKETS; i++) {
        if (array->packets[i]) {
            free(array->packets[i]->data_ptr);
            free(array->packets[i]);
        }
    }
    pthread_mutex_destroy(&array->lock);
    free(array);
}

void add_packet(PacketArray *array, void *packet_data, size_t packet_size) {
    if (!array || !packet_data || packet_size > PACKET_SIZE_MAX) return;

    Packet *new_packet = (Packet*)malloc(sizeof(Packet));
    if (!new_packet) {
        log_packet("Failed to allocate memory for a new packet.");
        return;
    }

    new_packet->data_ptr = malloc(packet_size);
    if (!new_packet->data_ptr) {
        free(new_packet);
        log_packet("Failed to allocate memory for packet data.");
        return;
    }

    memcpy(new_packet->data_ptr, packet_data, packet_size);

    new_packet->packet_size = packet_size;
    new_packet->timestamp = time(NULL); // Replace with actual timestamp from network interface.

    pthread_mutex_lock(&array->lock);
    if (array->count < MAX_PACKETS) {
        array->packets[array->count++] = new_packet;
        char log_message[256];
        snprintf(log_message, sizeof(log_message), "Packet added: size=%zu, time=%" PRIu64,
                 packet_size, new_packet->timestamp);
        log_packet(log_message);
    } else {
        free(new_packet->data_ptr);
        free(new_packet);
        pthread_mutex_unlock(&array->lock);

        log_packet("Max packets reached. Packet discarded.");
    }
    pthread_mutex_unlock(&array->lock);
}

void* cleanup_thread(void *arg) {
    PacketArray *array = (PacketArray*)arg;

    while (1) {
        sleep(5); // Run every 5 seconds.

        pthread_mutex_lock(&array->lock);
        if (array->count >= MAX_PACKETS && array->packets[0]) {
            free(array->packets[0]->data_ptr);
            free(array->packets[0]);
            memmove(&array->packets[0], &array->packets[1],
                    sizeof(Packet*) * (--array->count));
        }
        pthread_mutex_unlock(&array->lock);

        char analytics_data[] = "Cleanup performed.";
        send_analytics_data(analytics_data);
    }

    return NULL;
}

void process_packets_concurrently(PacketArray *array) {
    pthread_t cleanup_tid;
    if (pthread_create(&cleanup_tid, NULL, cleanup_thread, array) != 0) {
        log_packet("Failed to create cleanup thread.");
    }
}

// Helper function to find and print the largest integer from list of IDs.
void find_largest_integer(int *ids, int count) {
    if (!ids || count <= 0) return;

    int max_id = ids[0];
    for (int i = 1; i < count; ++i) {
        if (ids[i] > max_id)
            max_id = ids[i];
    }
    printf("Largest ID: %d\n", max_id);
}

// Main function demonstrating the usage.
int main() {
    PacketArray *packet_array = init_packet_array();
    if (!packet_array) return EXIT_FAILURE;

    process_packets_concurrently(packet_array);

    // Simulate receiving packets
    char packet_data[PACKET_SIZE_MAX];
    for (int i = 0; i < 1000; ++i) {
        memset(packet_data, 'A' + (i % 26), sizeof(packet_data));
        add_packet(packet_array, packet_data, sizeof(packet_data));
    }

    // Cleanup
    cleanup_packet_array(packet_array);

    return EXIT_SUCCESS;
}
