    Resource res1 = {"TypeA", 1024};
    add_data_object(collection, &res1);

    Resource updated_res = {"TypeA", 2048};
    update_resource_via_put(collection, "TypeA", &updated_res);

    delete_resource_via_delete(collection, "TypeA");

    destroy_data_collection(collection);
    return 0;
}
