#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LOCATIONS 100

typedef struct {
    int timestamp;
    char location[50];
    float temperature;
} TemperatureReading;

typedef struct LocationData {
    char location[50];
    int totalTimestamps;
    float sumTemperature;
    struct LocationData* next;
} LocationData;

LocationData* hashTable[MAX_LOCATIONS] = { NULL };

unsigned int hash(char* str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c;
    return hash % MAX_LOCATIONS;
}

void processTemperatureReadings(TemperatureReading readings[], int count) {
    for (int i = 0; i < count; i++) {
        if (!readings[i].timestamp || !readings[i].location[0] || readings[i].temperature == 0.0f) {
            continue;
        }

        unsigned int index = hash(readings[i].location);
        LocationData* current = hashTable[index];
        LocationData* prev = NULL;

        while (current != NULL && strcmp(current->location, readings[i].location) != 0) {
            prev = current;
            current = current->next;
        }

        if (current == NULL) { // New location
            LocationData* newData = (LocationData*)malloc(sizeof(LocationData));
            strcpy(newData->location, readings[i].location);
            newData->totalTimestamps = 1;
            newData->sumTemperature = readings[i].temperature;
            newData->next = hashTable[index];
            hashTable[index] = newData;
        } else { // Existing location
            current->totalTimestamps++;
            current->sumTemperature += readings[i].temperature;
        }
    }
}

void computeAverageTemperatures() {
    for (int i = 0; i < MAX_LOCATIONS; i++) {
        LocationData* current = hashTable[i];
        while (current != NULL) {
            float average = current->sumTemperature / current->totalTimestamps;
            printf("Location: %s, Average Temperature: %.2f\n", current->location, average);
            current = current->next;
        }
    }
}

char* getHighestAverageTemperatureLocation() {
    char* highestLocation = NULL;
    float highestAvgTemp = -1.0f;

    for (int i = 0; i < MAX_LOCATIONS; i++) {
        LocationData* current = hashTable[i];
        while (current != NULL) {
            if (current->totalTimestamps > 0) {
                float average = current->sumTemperature / current->totalTimestamps;
                if (average > highestAvgTemp) {
                    highestAvgTemp = average;
                    highestLocation = strdup(current->location);
                }
            }
            current = current->next;
        }
    }

    return highestLocation;
}

// RESTful API Functions
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Resource {
    int id;
    char name[100];
} Resource;

Resource* resources = NULL;
int resourceCount = 0;

void createResource(char* jsonBody) {
    // Simulate parsing JSON and creating a new resource
    Resource* newResource = (Resource*)malloc(sizeof(Resource));
    sscanf(jsonBody, "{\"id\":%d,\"name\":\"%[^\"]\"}", &newResource->id, newResource->name);

    if (!resources) {
        resources = newResource;
    } else {
        Resource* temp = resources;
        while (temp->next) {
            temp = temp->next;
        }
        temp->next = newResource;
    }

    resourceCount++;
}

void getSpecificResource(int id) {
    Resource* current = resources;
    while (current != NULL) {
        if (current->id == id) {
            printf("Resource Found: ID=%d, Name=%s\n", current->id, current->name);
            return;
        }
        current = current->next;
    }
    printf("Resource not found.\n");
}

int main() {
    // Example usage
    TemperatureReading readings[] = {
        {1234567890, "LocationA", 25.5},
        {1234567891, "LocationB", 30.2},
        {1234567890, "LocationA", 26.7}, // Duplicate timestamp for LocationA should be ignored
    };

    processTemperatureReadings(readings, sizeof(readings) / sizeof(TemperatureReading));
    computeAverageTemperatures();
    char* highestLocation = getHighestAverageTemperatureLocation();
    if (highestLocation) {
        printf("Highest Average Temperature Location: %s\n", highestLocation);
        free(highestLocation);
    }

    // RESTful API example usage
    createResource("{\"id\":1,\"name\":\"ResourceOne\"}");
    createResource("{\"id\":2,\"name\":\"ResourceTwo\"}");
    getSpecificResource(1);

    return 0;
}
