} offsets_and_keys_t;

long total_sum = 0;
pthread_mutex_t sum_mutex = PTHREAD_MUTEX_INITIALIZER;

void init_data(long num_records, long range_start, long range_end) {
    pthread_t threads[2];

    // Allocate and initialize arrays
    offsets_and_keys_t* offsets_and_keys = malloc(num_records * sizeof(offsets_and_keys_t));
    if (!offsets_and_keys) return;

    record* records = malloc(num_records * sizeof(record));
    if (!records) {
        free(offsets_and_keys);
        return;
    }

    int* keys = malloc(num_records * sizeof(int));
    if (!keys) {
        free(records);
        free(offsets_and_keys);
        return;
    }

    // Seed random number generator
    srand((unsigned int)time(NULL));

    pthread_mutex_t key_ref_mutex = PTHREAD_MUTEX_INITIALIZER;

    void* thread_func(void* arg) {
        offsets_and_keys_t* data = (offsets_and_keys_t*)arg;
        long local_sum = 0;

        for (long i = 0; i < num_records; ++i) {
            pthread_mutex_lock(&key_ref_mutex);

            // Generate random int value within range
            long current_range_start = range_start + local_sum / num_records;
            long current_range_end = current_range_start + (range_end - range_start) / num_records;

            if (current_range_start > current_range_end) {
                data[i].key = 0; // Handle overflow by assigning zero
            } else {
                int value = rand() % (current_range_end - current_range_start + 1) + current_range_start;

                records[i].value = value;
                records[i].key_ref = &keys[data[i].offset];

                local_sum += value;

                pthread_mutex_unlock(&key_ref_mutex);

                pthread_mutex_lock(&sum_mutex);
                total_sum += value;
                pthread_mutex_unlock(&sum_mutex);
            }
        }

        return NULL;
    }

    // Divide the work between two threads
    long mid = num_records / 2;
    offsets_and_keys_t* part1 = offsets_and_keys;
    offsets_and_keys_t* part2 = offsets_and_keys + mid;

    pthread_create(&threads[0], NULL, thread_func, part1);
    pthread_create(&threads[1], NULL, thread_func, part2);

    for (int i = 0; i < 2; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Clean up
    free(offsets_and_keys);
    free(keys);
    pthread_mutex_destroy(&sum_mutex);
    pthread_mutex_destroy(&key_ref_mutex);
}

