    double measurement;
} record;

double sum_records = 0.0;
int total_sum_values = 0;
pthread_mutex_t lock;

void calculate_std_dev(double *measurements, size_t count, double *std_dev) {
    double mean = 0.0;
    for (size_t i = 0; i < count; ++i)
        mean += measurements[i];
    mean /= count;

    double variance = 0.0;
    for (size_t i = 0; i < count; ++i)
        variance += (measurements[i] - mean) * (measurements[i] - mean);
    variance /= count;

    *std_dev = sqrt(variance);
}

void initialize_records(long *offsets, int *keys, double *measurements,
                        record **records, size_t record_count) {
    pthread_mutex_lock(&lock);

    calculate_std_dev(measurements, record_count, &double std_dev);
    for (size_t i = 0; i < record_count; ++i) {
        int random_value;
        if (total_sum_values == 0)
            random_value = rand() % 100; // Initial range
        else
            random_value = (rand() % 100) + total_sum_values / record_count - std_dev;

        (*records)[i].value = random_value;
        (*records)[i].key_index = keys[offsets[i]];
        (*records)[i].measurement = measurements[offsets[i]];

        total_sum_values += random_value;
    }

    pthread_mutex_unlock(&lock);
}

record *manage_memory(size_t offsets_count, size_t keys_count,
