#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int value;
    const int *key;
    long offset;
} record;

typedef struct {
    record **records;
    size_t count;
    size_t capacity;
    long total_value;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} record_collection;

record_collection* init_record_collection(size_t initial_capacity) {
    record_collection *collection = malloc(sizeof(record_collection));
    if (!collection) return NULL;

    collection->records = calloc(initial_capacity, sizeof(record *));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->count = 0;
    collection->capacity = initial_capacity;
    collection->total_value = 0;
    pthread_mutex_init(&collection->lock, NULL);
    pthread_cond_init(&collection->cond, NULL);

    // Seed random number generator
    srand(time(NULL));

    return collection;
}

int safe_add(int a, int b) {
    if ((b > 0 && a > INT_MAX - b) || (b < 0 && a < INT_MIN - b)) {
        return 1; // overflow detected
    }
    return 0;
}

void resize_record_collection(record_collection *collection);

record* create_random_record(const int *key, long offset, int min_value, int max_value, long total_previous) {
    record *new_record = malloc(sizeof(record));
    if (!new_record) return NULL;

    // Simulate third-party data source retrieval
    int value_from_source = rand() % (max_value - min_value + 1) + min_value;

    new_record->value = value_from_source + total_previous;
    new_record->key = key;
    new_record->offset = offset;

    return new_record;
}

int add_record(record_collection *collection, const int *key, long offset, int min_value, int max_value) {
    pthread_mutex_lock(&collection->lock);

    // Resize if needed
    if (collection->count >= collection->capacity) {
        resize_record_collection(collection);
    }

    record *new_record = create_random_record(key, offset, min_value, max_value, collection->total_value);
    if (!new_record) {
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    // Check for integer overflow
    if (safe_add(collection->total_value, new_record->value)) {
        free(new_record);
        pthread_mutex_unlock(&collection->lock);
        return -2; // overflow detected
    }

    collection->records[collection->count++] = new_record;
    collection->total_value += new_record->value;

    pthread_cond_signal(&collection->cond);
    pthread_mutex_unlock(&collection->lock);

    return 0;
}

void resize_record_collection(record_collection *collection) {
    size_t new_capacity = collection->capacity * 2;
    record **new_records = realloc(collection->records, new_capacity * sizeof(record *));
    if (!new_records) return;

    collection->records = new_records;
    collection->capacity = new_capacity;
}

void cleanup_record_collection(record_collection *collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->records[i]);
    }
    free(collection->records);
    pthread_mutex_destroy(&collection->lock);
    pthread_cond_destroy(&collection->cond);
    free(collection);
}

int main() {
    record_collection *col = init_record_collection(10);

    // Example usage
    int key = 123;
    add_record(col, &key, 1000, 1, 100);

    cleanup_record_collection(col);
    return 0;
}
```

