    pub async fn build_client(self) -> Result<Client> {
        let client_builder = if self.disable_ssl_validation {
            ClientBuilder::new()
                .danger_accept_invalid_certs(true)
        } else {
            ClientBuilder::new()
        };

        let client = client_builder
            .build()?
            .builder()
            .retry_strategy(reqwest::RetryStrategy::Custom(
                |attempt, err| async move {
                    if attempt <= self.max_retries {
                        match err {
                            ReqwestError::Status(_) => Some(1), // Backoff for status errors
                            _ => None,
                        }
                    } else {
                        None
                    }
                },
            ))
            .build()
            .await?;

        Ok(client)
    }

