#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    size_t length;
    char* buffer;
} DataBuffer;

typedef struct Task {
    char* name;
    long priority;
    DataBuffer* dataBuffer;
} Task;

typedef struct {
    Task** tasks;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} TaskManager;

TaskManager* create_task_manager(size_t initial_capacity) {
    TaskManager* manager = malloc(sizeof(TaskManager));
    if (!manager) return NULL;

    manager->tasks = calloc(initial_capacity, sizeof(Task*));
    if (!manager->tasks) {
        free(manager);
        return NULL;
    }

    manager->count = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_task_manager(TaskManager* manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->tasks[i]->name);
        free(manager->tasks[i]->dataBuffer->buffer);
        free(manager->tasks[i]->dataBuffer);
        free(manager->tasks[i]);
    }
    free(manager->tasks);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_task(TaskManager* manager, const char* name, long priority, size_t buffer_length) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        Task** new_tasks = realloc(manager->tasks, new_capacity * sizeof(Task*));
        if (!new_tasks) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        manager->tasks = new_tasks;
        manager->capacity = new_capacity;
    }

    Task* task = malloc(sizeof(Task));
    if (!task) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    task->name = strdup(name);
    if (!task->name) {
        free(task);
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    task->priority = priority;

    DataBuffer* dataBuffer = malloc(sizeof(DataBuffer));
    if (!dataBuffer) {
        free(task->name);
        free(task);
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }
    dataBuffer->length = buffer_length;
    dataBuffer->buffer = malloc(buffer_length);
    if (!dataBuffer->buffer) {
        free(dataBuffer);
        free(task->name);
        free(task);
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    task->dataBuffer = dataBuffer;

    manager->tasks[manager->count++] = task;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void remove_task(TaskManager* manager, const char* name) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->tasks[i]->name, name) == 0) {
            free(manager->tasks[i]->name);
            free(manager->tasks[i]->dataBuffer->buffer);
            free(manager->tasks[i]->dataBuffer);
            free(manager->tasks[i]);

            manager->tasks[i] = manager->tasks[--manager->count];

            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void sort_tasks_by_priority(TaskManager* manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count - 1; ++i) {
        for (size_t j = i + 1; j < manager->count; ++j) {
            if (manager->tasks[i]->priority < manager->tasks[j]->priority) {
                Task* temp = manager->tasks[i];
                manager->tasks[i] = manager->tasks[j];
                manager->tasks[j] = temp;
            }
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void execute_task(Task* task) {
    // Simulate task execution
    printf("Executing task: %s, Priority: %ld\n", task->name, task->priority);

    // Example of buffer reuse
    memset(task->dataBuffer->buffer, 0, task->dataBuffer->length);
}

void execute_tasks(TaskManager* manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        execute_task(manager->tasks[i]);
    }

    pthread_mutex_unlock(&manager->lock);
}

```

