} Packet;

typedef struct {
    Packet packets[MAX_PACKETS];
    int count;
    pthread_mutex_t lock;
} PacketArray;

PacketArray packet_array = {{0}, 0, PTHREAD_MUTEX_INITIALIZER};

void log_packet_added(Packet *packet) {
    // Integrate with existing logging framework
    printf("Packet added at %lu with size %d\n", packet->timestamp, packet->packet_size);
}

void add_packet_to_array(Packet *packet) {
    pthread_mutex_lock(&packet_array.lock);

    if (packet_array.count >= MAX_PACKETS) {
        // Remove the oldest packet to make space
        free(packet_array.packets[0].data_ptr);
        memmove(&packet_array.packets[0], &packet_array.packets[1],
                sizeof(Packet) * (MAX_PACKETS - 1));
        packet_array.count--;
    }

    memcpy(&packet_array.packets[packet_array.count], packet, sizeof(Packet));
    log_packet_added(packet);
    packet_array.count++;

    pthread_mutex_unlock(&packet_array.lock);
}

void receive_and_validate_packet(void *interface_data, size_t data_size) {
