    packet->data_ptr = malloc(data_size);
    if (!packet->data_ptr) {
        fprintf(stderr, "Out of memory for packet data\n");
        free(packet);
        return;
    }
    memcpy(packet->data_ptr, interface_data, data_size);

    add_packet_to_array(packet);
}

void *maintain_packet_limit(void *arg) {
    while (1) {
        pthread_mutex_lock(&packet_array.lock);
