### Task 2: Processing Floating-Point Numbers and Populating LTE_RRC_RECONFIGURATION_MESSAGE Structures

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <math.h>

typedef struct {
    int SRB1_CONFIG;
    unsigned long MME_UE_S1AP_ID;
} SRB1Config;

typedef struct {
    SRB1Config srb1_config;
    unsigned long macentity_id;
    int sequence_number;
} LTE_RRC_RECONFIGURATION_MESSAGE;

void process_floating_point_numbers() {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    float *numbers = NULL, sum = 0.0f, average = 0.0f;
    size_t count = 0;

    LTE_RRC_RECONFIGURATION_MESSAGE *messages = NULL;
    size_t msg_count = 0;

    while (1) {
        pthread_mutex_lock(&lock);

        float number;
        if (scanf("%f", &number) != 1) break; // Read numbers until EOF

        numbers = realloc(numbers, (count + 1) * sizeof(float));
        if (!numbers) {
            fprintf(stderr, "Out of memory\n");
            pthread_mutex_unlock(&lock);
            continue;
        }

        numbers[count] = number;
        sum += number;
        count++;

        // Check for message population threshold
        if (count >= 10) { // Arbitrary threshold
            messages = realloc(messages, (msg_count + 1) * sizeof(LTE_RRC_RECONFIGURATION_MESSAGE));
            if (!messages) {
                fprintf(stderr, "Out of memory\n");
                pthread_mutex_unlock(&lock);
                continue;
            }

            LTE_RRC_RECONFIGURATION_MESSAGE *message = &messages[msg_count];
            message->srb1_config.SRB1_CONFIG = 1; // Example value
            message->srb1_config.MME_UE_S1AP_ID = rand(); // Random ID for simulation
            message->macentity_id = rand();
            message->sequence_number = msg_count + 1;

            msg_count++;
        }

        pthread_mutex_unlock(&lock);
    }

    if (count > 0) {
        average = sum / count;
        printf("Average of numbers: %.2f\n", average);
    } else {
        printf("No valid floating-point numbers processed.\n");
    }

    // Cleanup
    free(numbers);
    free(messages);
}

int main() {
    process_floating_point_numbers();
    return 0;
}
