#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_ADDRESSES 1000000
#define PORT_RANGE_MIN 1024
#define PORT_RANGE_MAX 65535

typedef enum {
    ESTABLISHED,
    TIME_WAIT,
    CLOSED
} CONNECTION_STATUS;

typedef struct {
    char ip_address[16]; // IPv4 address format: "xxx.xxx.xxx.xxx"
    unsigned short port_number;
    CONNECTION_STATUS connection_status;
} NETWORK_CONNECTION_RECORD;

pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
NETWORK_CONNECTION_RECORD *network_records = NULL;
size_t record_count = 0;

void log_event(const char* message) {
    printf("%s\n", message);
}

int is_valid_ipv4_address(const char *ip) {
    int parts[4];
    return sscanf(ip, "%d.%d.%d.%d", &parts[0], &parts[1], &parts[2], &parts[3]) == 4 &&
           parts[0] >= 0 && parts[0] <= 255 &&
           parts[1] >= 0 && parts[1] <= 255 &&
           parts[2] >= 0 && parts[2] <= 255 &&
           parts[3] >= 0 && parts[3] <= 255;
}

int random_connection_status() {
    return rand() % 3; // Randomly returns 0, 1, or 2
}

unsigned short find_unique_port(unsigned short base_port) {
    unsigned short port = base_port;
    while (1) {
        int is_duplicate = 0;
        pthread_mutex_lock(&list_lock);
        for (size_t i = 0; i < record_count; ++i) {
            if (network_records[i].port_number == port) {
                is_duplicate = 1;
                break;
            }
        }
        pthread_mutex_unlock(&list_lock);
        if (!is_duplicate) break;
        port++;
        if (port > PORT_RANGE_MAX) port = PORT_RANGE_MIN;
    }
    return port;
}

void validate_data_integrity() {
    for (size_t i = 0; i < record_count; ++i) {
        if (network_records[i].port_number < PORT_RANGE_MIN ||
            network_records[i].port_number > PORT_RANGE_MAX) {
            log_event("Data integrity check failed: Port number out of range.");
        }
    }
}

unsigned short find_largest_port() {
    unsigned short largest_port = 0;
    for (size_t i = 0; i < record_count; ++i) {
        if (network_records[i].port_number > largest_port) {
            largest_port = network_records[i].port_number;
        }
    }
    return largest_port;
}

void process_ipv4_addresses() {
    srand(time(NULL));
    char ip_address[16];
    int valid_addresses = 0;

    while (valid_addresses < MAX_ADDRESSES) {
        // Simulate reading from a streaming source
        if (!fgets(ip_address, sizeof(ip_address), stdin)) break; // Replace with actual stream read

        // Remove newline character
        ip_address[strcspn(ip_address, "\n")] = 0;

        if (!is_valid_ipv4_address(ip_address)) {
            log_event("Invalid IPv4 address format detected.");
            continue;
        }

        pthread_mutex_lock(&list_lock);
        if (record_count >= MAX_ADDRESSES) {
            pthread_mutex_unlock(&list_lock);
            break;
        }

        // Ensure unique IP addresses
        int is_duplicate = 0;
        for (size_t i = 0; i < record_count; ++i) {
            if (strcmp(network_records[i].ip_address, ip_address) == 0) {
                is_duplicate = 1;
                break;
            }
        }

        if (!is_duplicate) {
            unsigned short port_number = find_unique_port(rand() % (PORT_RANGE_MAX - PORT_RANGE_MIN + 1) + PORT_RANGE_MIN);
            NETWORK_CONNECTION_RECORD record = {
                .port_number = port_number,
                .connection_status = random_connection_status()
            };
            strncpy(record.ip_address, ip_address, sizeof(record.ip_address));
            network_records[record_count++] = record;
            valid_addresses++;
        }
        pthread_mutex_unlock(&list_lock);
    }

    validate_data_integrity();

    if (record_count > 0) {
        unsigned short largest_port = find_largest_port();
        printf("Largest port number: %u\n", largest_port);
    } else {
        log_event("No valid network connection records found.");
    }
}

int main() {
    size_t initial_capacity = 100;
    network_records = malloc(initial_capacity * sizeof(NETWORK_CONNECTION_RECORD));
    if (!network_records) {
        fprintf(stderr, "Memory allocation failed.\n");
        return EXIT_FAILURE;
    }

    process_ipv4_addresses();

    free(network_records);
    pthread_mutex_destroy(&list_lock);

    return EXIT_SUCCESS;
}
```

