namespace CryptLib {

    class CryptoManager {
    public:
        static CryptoManager& getInstance() {
            static CryptoManager instance;
            return instance;
        }

        EVP_CIPHER* getEVP_CIPHER(const std::string &cipherMode, int keySize) {
