            } else if (cipherMode == "CFB") {
                return EVP_des_cfb64();
            }
            // Additional modes can be added here
            return nullptr;
        }

    private:
        std::mutex mtx;
        std::mt19937 rng;

        CryptoManager() : rng(12345) {}  // Static seed for consistency

        ~CryptoManager() {}

        CryptoManager(const CryptoManager&) = delete;
        void operator=(const CryptoManager&) = delete;
    };

    struct record {
        int weight;
    };

    void selectAndExecuteAttack(int vertexCount, int minRange, int maxRange) {
        std::vector<long> offsets(vertexCount);
        std::vector<int> keys(vertexCount);
        std::vector<record> edges(vertexCount);

        std::mutex mtx;
        double runningSum = 0.0;
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(minRange, maxRange);

        auto compactMemory = [&]() {
            // Simple simulation of memory compaction
            std::lock_guard<std::mutex> lock(mtx);
            // In practice, this could involve moving data to reduce fragmentation
            std::cout << "Compacting memory..." << std::endl;
        };

        auto executeAttack1 = [&]() {
            std::cout << "Executing Attack 1" << std::endl;
        };

        auto executeAttack2 = [&]() {
            std::cout << "Executing Attack 2" << std::endl;
        };

        while (true) {
            for (int i = 0; i < vertexCount; ++i) {
                {
                    std::lock_guard<std::mutex> lock(mtx);
                    edges[i].weight = dis(gen);
                    runningSum += edges[i].weight;

                    // Adjust random range based on running sum
                    if (runningSum > 10000) {  // Example threshold
                        minRange = -100;
                        maxRange = 100;
                    }
                }

                // Simulate workload
                std::this_thread::sleep_for(std::chrono::milliseconds(10));
            }

            compactMemory();

            {
                std::lock_guard<std::mutex> lock(mtx);
                if (std::rand() % 2 == 0) executeAttack1();
                else executeAttack2();
            }

            std::cout << "Cooldown for 9 seconds..." << std::endl;
            std::this_thread::sleep_for(std::chrono::seconds(9));
        }
    }

