typedef struct {
    int value;
    int *key_ref;
} Record;

typedef struct {
    size_t count;
    size_t capacity;
    Record *records;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    uint64_t cumulative_sum;
    uint64_t memory_footprint;
    uint64_t allocations;
    uint64_t deallocations;
} RecordManager;

RecordManager manager = {0, INITIAL_SIZE, NULL, PTHREAD_MUTEX_INITIALIZER, PTHREAD_COND_INITIALIZER, 0, 0, 0, 0};

void log_message(const char *message) {
    // Hypothetical logging function
