RecordManager* create_manager(size_t initial_capacity) {
    RecordManager *mgr = malloc(sizeof(RecordManager));
    if (!mgr) {
        log_message("Failed to allocate memory for manager");
        return NULL;
    }

    mgr->count = 0;
    mgr->capacity = initial_capacity;
    mgr->records = malloc(initial_capacity * sizeof(Record));
    if (!mgr->records) {
        free(mgr);
        log_message("Failed to allocate memory for records");
        return NULL;
    }

    pthread_mutex_init(&mgr->lock, NULL);
    pthread_cond_init(&mgr->cond, NULL);

    mgr->cumulative_sum = 0;
    mgr->memory_footprint = sizeof(RecordManager) + initial_capacity * sizeof(Record);
    mgr->allocations++;

    return mgr;
}

void destroy_manager(RecordManager *mgr) {
    if (mgr) {
        free(mgr->records);
        pthread_mutex_destroy(&mgr->lock);
        pthread_cond_destroy(&mgr->cond);

        mgr->memory_footprint -= sizeof(RecordManager) + mgr->capacity * sizeof(Record);
        mgr->deallocations++;

        free(mgr);
    }
}

void resize_manager_if_needed(RecordManager *mgr) {
    if (mgr->count >= mgr->capacity) {
        size_t new_capacity = mgr->capacity * 2;
        Record *new_records = realloc(mgr->records, new_capacity * sizeof(Record));
        if (!new_records) {
            log_message("Failed to resize records");
            return;
        }

        mgr->records = new_records;
        mgr->capacity = new_capacity;

        mgr->memory_footprint += (new_capacity - mgr->capacity) * sizeof(Record);
    }
}

void* initialize_records(void *arg) {
    RecordManager *mgr = (RecordManager *)arg;
    int64_t min_value = 0;
    int64_t max_value = 100; // Example range

    pthread_mutex_lock(&mgr->lock);

    for (size_t i = mgr->count; i < mgr->capacity && i < MAX_RECORDS; ++i) {
        resize_manager_if_needed(mgr);

        Record *record = &mgr->records[i];
        int key = init_random(); // Example key generation
        record->key_ref = malloc(sizeof(int));
        if (record->key_ref) {
            *(record->key_ref) = key;
            mgr->memory_footprint += sizeof(int);
            mgr->allocations++;
        } else {
            log_message("Failed to allocate memory for key reference");
            break;
        }

        int64_t value = min_value + ((max_value - min_value + 1) * init_random() / RAND_MAX);

        if (__builtin_add_overflow(mgr->cumulative_sum, value, &record->value)) {
            log_message("Integer overflow detected in cumulative sum");
            break;
        } else {
            mgr->cumulative_sum += value;
        }

        mgr->count++;
    }

    pthread_mutex_unlock(&mgr->lock);
    return NULL;
}

void* monitor_performance(void *arg) {
    RecordManager *mgr = (RecordManager *)arg;

    while (1) {
        sleep(5); // Example interval
        pthread_mutex_lock(&mgr->lock);

        log_message("Memory footprint: ");
        printf("%lu\n", mgr->memory_footprint);

        pthread_mutex_unlock(&mgr->lock);
    }

    return NULL;
}

int main() {
    RecordManager *manager = create_manager(INITIAL_SIZE);
    if (!manager) {
        return 1;
    }

    pthread_t threads[4];
    for (int i = 0; i < 3; ++i) { // Creating multiple threads to initialize records
        pthread_create(&threads[i], NULL, initialize_records, manager);
    }

    pthread_create(&threads[3], NULL, monitor_performance, manager);

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroy_manager(manager);
    return 0;
}
