typedef struct {
    double temperature;
    double humidity;
    double pressure;
} SensorData;

typedef struct {
    long sensorID;
    time_t timestamp;
    SensorData data;
} SensorStream;

typedef struct {
    SensorStream *streams;
    size_t count;
    size_t capacity;
    double totalTemperature;
    double totalHumidity;
    double totalPressure;
    pthread_mutex_t lock;
} StreamManager;

void initialize_random_seed() {
    srand(time(NULL));
}

double generate_random_value(double average, double range) {
    return ((rand() % (int)(range * 2 + 1)) - range) + average;
}

void safe_arithmetic_add(double *total, double value) {
    long long int temp = (long long int)(*total * 1000000);
    long long int newValue = (long long int)(value * 1000000);
    temp += newValue;
    if ((temp / 1000000) > INT_MAX || (temp / 1000000) < INT_MIN)
        fprintf(stderr, "Arithmetic overflow detected\n");
    else
        *total = temp / 1000000.0;
}

void* initialize_stream(void* arg) {
    StreamManager *manager = (StreamManager *)arg;
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity == 0 ? 1 : manager->capacity * 2;
        SensorStream *new_streams = realloc(manager->streams, new_capacity * sizeof(SensorStream));
        if (!new_streams) {
            perror("Failed to reallocate memory");
            pthread_mutex_unlock(&manager->lock);
            return NULL;
        }
        manager->streams = new_streams;
        manager->capacity = new_capacity;
    }

    SensorStream *stream = &manager->streams[manager->count++];
    stream->sensorID = rand();
    stream->timestamp = time(NULL);

    double avgTemp = manager->totalTemperature / (double)(manager->count);
    double avgHumidity = manager->totalHumidity / (double)(manager->count);
    double avgPressure = manager->totalPressure / (double)(manager->count);

    stream->data.temperature = generate_random_value(avgTemp, 10.0);
    stream->data.humidity = generate_random_value(avgHumidity, 20.0);
    stream->data.pressure = generate_random_value(avgPressure, 5.0);

    safe_arithmetic_add(&manager->totalTemperature, stream->data.temperature);
    safe_arithmetic_add(&manager->totalHumidity, stream->data.humidity);
    safe_arithmetic_add(&manager->totalPressure, stream->data.pressure);

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

StreamManager* create_stream_manager() {
    StreamManager *manager = malloc(sizeof(StreamManager));
    if (!manager) {
        perror("Failed to allocate memory");
        return NULL;
    }
    manager->streams = NULL;
    manager->count = 0;
    manager->capacity = 0;
    manager->totalTemperature = 0.0;
    manager->totalHumidity = 0.0;
    manager->totalPressure = 0.0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_stream_manager(StreamManager *manager) {
    if (manager) {
        free(manager->streams);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

int main() {
    initialize_random_seed();

    StreamManager *manager = create_stream_manager();
    if (!manager) return 1;

    const size_t num_threads = 10000;
    pthread_t threads[num_threads];

    for (size_t i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, initialize_stream, manager)) {
            fprintf(stderr, "Error creating thread\n");
            destroy_stream_manager(manager);
            return 1;
        }
    }

    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Example output
    printf("Initialized %zu streams.\n", manager->count);

    destroy_stream_manager(manager);
    return 0;
}
