import java.util.concurrent.*;
import java.util.*;
import java.util.stream.Collectors;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;

class LogMessage {
    private final String LOG_ID;
    private final int SEVERITY_LEVEL;
    private final String LOG_MESSAGE;
    private final Date LOG_TIMESTAMP;
    private final String LOG_THREAD_NAME;

    public LogMessage(String logId, int severityLevel, String logMessage, Date logTimestamp, String threadName) {
        this.LOG_ID = logId;
        this.SEVERITY_LEVEL = severityLevel;
        this.LOG_MESSAGE = logMessage;
        this.LOG_TIMESTAMP = logTimestamp;
        this.LOG_THREAD_NAME = threadName;
    }

    public String getLOG_ID() { return LOG_ID; }
    public int getSEVERITY_LEVEL() { return SEVERITY_LEVEL; }
    public String getLOG_MESSAGE() { return LOG_MESSAGE; }
    public Date getLOG_TIMESTAMP() { return LOG_TIMESTAMP; }
    public String getLOG_THREAD_NAME() { return LOG_THREAD_NAME; }

    @Override
    public String toString() {
        return "LogMessage{" +
                "LOG_ID='" + LOG_ID + '\'' +
                ", SEVERITY_LEVEL=" + SEVERITY_LEVEL +
                ", LOG_MESSAGE='" + LOG_MESSAGE + '\'' +
                ", LOG_TIMESTAMP=" + LOG_TIMESTAMP +
                ", LOG_THREAD_NAME='" + LOG_THREAD_NAME + '\'' +
                '}';
    }
}

class EventEntry implements Comparable<EventEntry> {
    private final Date timestamp;
    private final int priorityLevel;
    private final LogMessage logMessage;

    public EventEntry(Date timestamp, int priorityLevel, LogMessage logMessage) {
        this.timestamp = timestamp;
        this.priorityLevel = priorityLevel;
        this.logMessage = logMessage;
    }

    public Date getTimestamp() { return timestamp; }
    public int getPriorityLevel() { return priorityLevel; }
    public LogMessage getLogMessage() { return logMessage; }

    @Override
    public int compareTo(EventEntry other) {
        return this.timestamp.compareTo(other.timestamp);
    }
}

class EventLog {
    private final ConcurrentSkipListSet<EventEntry> eventEntries = new ConcurrentSkipListSet<>();
    private volatile long totalSize;
    private final ObjectMapper objectMapper = new ObjectMapper();

    public synchronized void addEvent(EventEntry entry) {
        eventEntries.add(entry);
        updateTotalSize();
    }

    public synchronized void batchAddEvents(List<EventEntry> entries) {
        eventEntries.addAll(entries);
        updateTotalSize();
    }

    public synchronized LogMessage getLogById(String logId) {
        return eventEntries.stream()
                .filter(e -> e.getLogMessage().getLOG_ID().equals(logId))
                .findFirst()
                .map(EventEntry::getLogMessage)
                .orElse(null);
    }

    public synchronized void clearEvents() {
        eventEntries.clear();
        totalSize = 0;
    }

    public List<EventEntry> filterBySeverity(int severityLevel) {
        return new ArrayList<>(eventEntries.stream()
                .filter(e -> e.getLogMessage().getSEVERITY_LEVEL() == severityLevel)
                .collect(Collectors.toList()));
    }

    public List<EventEntry> filterByTimestamp(Date start, Date end) {
        return new ArrayList<>(eventEntries.stream()
                .filter(e -> !e.getTimestamp().before(start) && !e.getTimestamp().after(end))
                .collect(Collectors.toList()));
    }

    public String serializeToJson() throws JsonProcessingException {
        List<Map<String, Object>> jsonList = eventEntries.stream()
                .map(entry -> Map.of(
                        "timestamp", entry.getTimestamp(),
                        "priorityLevel", entry.getPriorityLevel(),
                        "logMessage", Map.of(
                                "LOG_ID", entry.getLogMessage().getLOG_ID(),
                                "SEVERITY_LEVEL", entry.getLogMessage().getSEVERITY_LEVEL(),
                                "LOG_MESSAGE", entry.getLogMessage().getLOG_MESSAGE(),
                                "LOG_TIMESTAMP", entry.getLogMessage().getLOG_TIMESTAMP(),
                                "LOG_THREAD_NAME", entry.getLogMessage().getLOG_THREAD_NAME()
                        )
                )).collect(Collectors.toList());
        return objectMapper.writeValueAsString(jsonList);
    }

    public void deserializeFromJson(String json) throws JsonProcessingException {
        List<Map<String, Object>> logEntries = objectMapper.readValue(json, 
            objectMapper.getTypeFactory().constructCollectionType(List.class, Map.class));

        eventEntries.clear();
        for (Map<String, Object> entry : logEntries) {
            Date timestamp = new Date((Long) entry.get("timestamp"));
            int priorityLevel = (int) entry.get("priorityLevel");
            Map<String, Object> logMessageData = (Map<String, Object>) entry.get("logMessage");
            LogMessage logMessage = new LogMessage(
                    (String) logMessageData.get("LOG_ID"),
                    (int) logMessageData.get("SEVERITY_LEVEL"),
                    (String) logMessageData.get("LOG_MESSAGE"),
                    (Date) logMessageData.get("LOG_TIMESTAMP"),
                    (String) logMessageData.get("LOG_THREAD_NAME")
            );
            eventEntries.add(new EventEntry(timestamp, priorityLevel, logMessage));
        }
    }

    private void updateTotalSize() {
        totalSize = eventEntries.stream()
                .mapToLong(e -> e.getLogMessage().getLOG_MESSAGE().length())
                .sum();
    }
}
