import java.util.*;
import java.util.concurrent.*;
import java.nio.file.*;
import java.io.IOException;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

public class DistributedCacheService {

    private final ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
    private final ExecutorService executor = Executors.newCachedThreadPool();
    private final ObjectMapper objectMapper = new ObjectMapper();

    public void startMonitoring() {
        scheduler.scheduleAtFixedRate(this::checkClusterHealth, 0, 10, TimeUnit.SECONDS);
    }

    private void checkClusterHealth() {
        // Simulate health check logic
        boolean isHealthy = true;
        if (!isHealthy) {
            System.out.println("Cluster needs rebalancing or scaling.");
        }
    }

    public CompletableFuture<Void> writeToCache(String key, String value) {
        return CompletableFuture.runAsync(() -> {
            try {
                // Simulated network health check and retry with exponential backoff
                int attempts = 0;
                while (attempts < 5) {
                    if (isNetworkHealthy()) {
                        cache.put(key, value);
                        logOperation("Write successful for key: " + key);
                        return;
                    }
                    Thread.sleep((long) Math.pow(2, attempts) * 100L);
                    attempts++;
                }
                throw new RuntimeException("Failed to write to cache after retries");
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                logOperation("Write failed for key: " + key, e);
            }
        }, executor);
    }

    public CompletableFuture<String> readFromCache(String key) {
        return CompletableFuture.supplyAsync(() -> {
            try {
                if (isNetworkHealthy()) {
                    String value = cache.get(key);
                    if (value != null) {
                        logOperation("Read successful for key: " + key);
                        return value;
                    } else {
                        logOperation("Cache miss for key: " + key);
                        return null;
                    }
                }
                throw new RuntimeException("Network is unhealthy");
            } catch (Exception e) {
                logOperation("Read failed for key: " + key, e);
                return null;
            }
        }, executor);
    }

    private boolean isNetworkHealthy() {
        // Simulate network health check
        return true;
    }

    private void logOperation(String message, Exception e) {
        System.out.println(message);
        if (e != null) {
            e.printStackTrace();
        }
    }

    public void processJsonFile(Path filePath) throws IOException {
        try (Stream<String> lines = Files.lines(filePath)) {
            lines.parallel()
                .map(this::parseTransaction)
                .filter(Objects::nonNull)
                .forEach(transaction -> {
                    // Aggregate data
                    System.out.println("Processing transaction: " + transaction);
                });
        }
    }

    private Transaction parseTransaction(String jsonLine) {
        try {
            JsonNode node = objectMapper.readTree(jsonLine);
            String type = node.get("type").asText();
            if (!"relevantType".equals(type)) return null;
            double value = node.get("value").asDouble();
            return new Transaction(type, value);
        } catch (IOException e) {
            logOperation("Failed to parse JSON line", e);
            return null;
        }
    }

    public static void main(String[] args) throws IOException {
        DistributedCacheService service = new DistributedCacheService();
        service.startMonitoring();

        // Example usage
        service.writeToCache("key1", "value1").join();
        service.readFromCache("key1").thenAccept(value -> System.out.println("Value: " + value));

        Path filePath = Paths.get("transactions.json");
        service.processJsonFile(filePath);
    }

    static class Transaction {
        private final String type;
        private final double value;

        public Transaction(String type, double value) {
            this.type = type;
            this.value = value;
        }

        @Override
        public String toString() {
            return "Transaction{" +
                    "type='" + type + '\'' +
                    ", value=" + value +
                    '}';
        }
    }
}
