#define MAX_UE_INSTANCES 100
#define POOL_SIZE 10

// Pre-allocated memory pool for NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* memory_pool[POOL_SIZE];
pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;
int active_pool_count = 0;

NFAPI_CRC_INDICATION_PDU_T* allocate_crc_pdu() {
    pthread_mutex_lock(&pool_mutex);

    for (int i = 0; i < POOL_SIZE; ++i) {
        if (!memory_pool[i]) {
            memory_pool[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (memory_pool[i]) {
                active_pool_count++;
                pthread_mutex_unlock(&pool_mutex);
                return memory_pool[i];
            }
        }
    }

    // If no available slots, return NULL indicating allocation failure
    pthread_mutex_unlock(&pool_mutex);
    return NULL;
}

void deallocate_crc_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    for (int i = 0; i < POOL_SIZE; ++i) {
        if (memory_pool[i] == pdu) {
            free(memory_pool[i]);
            memory_pool[i] = NULL;
            active_pool_count--;
            break;
        }
    }
}

NFAPI_CRC_INDICATION_PDU_T* create_crc_pdu_array(int num_ues) {
    NFAPI_CRC_INDICATION_PDU_T* result = (NFAPI_CRC_INDICATION_PDU_T*)calloc(num_ues, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!result) return NULL;

    for (int i = 0; i < num_ues; ++i) {
        result[i].RX_UE_INFORMATION_TAG = rand(); // Placeholder for valid tag generation
        result[i].RNTI = rand() & 0xFFFF;         // Random RNTI within a valid range

        // Set CRCFLAG randomly
        result[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }

    return result;
}

void destroy_crc_pdu_array(NFAPI_CRC_INDICATION_PDU_T* array, int num_ues) {
    if (array) {
        free(array);
    }
}

int main() {
    // Example usage
    int num_ues = 5; // Number of UE instances required

    NFAPI_CRC_INDICATION_PDU_T* pdu_array = create_crc_pdu_array(num_ues);
    if (!pdu_array) {
        fprintf(stderr, "Failed to allocate memory for CRC PDU array.\n");
        return EXIT_FAILURE;
    }

    // Simulate usage
    printf("Successfully created CRC PDU array with %d elements.\n", num_ues);

    destroy_crc_pdu_array(pdu_array, num_ues);

    // Deallocate any remaining items in the pool on exit
    for (int i = 0; i < POOL_SIZE; ++i) {
        if (memory_pool[i]) {
            deallocate_crc_pdu(memory_pool[i]);
        }
    }

    pthread_mutex_destroy(&pool_mutex);
    return EXIT_SUCCESS;
}
