#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int key_index;
} record;

// Thread-safe random number generator initialization
void init_rand(int seed) {
    srand(seed);
}

// Generate a random number within a range [min, max]
int rand_range(int min, int max) {
    return min + rand() % (max - min + 1);
}

// Function to initialize arrays and records with dynamic memory management
record* manage_memory_and_initialize(long num_offsets, long num_keys, long initial_record_count, int seed) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    double memory_threshold = 1024 * 1024 * 100; // Example threshold in bytes

    long total_records = initial_record_count;
    size_t record_size = sizeof(record);
    size_t key_array_size = num_keys * sizeof(int);
    size_t offset_array_size = num_offsets * sizeof(long);

    int *keys = (int *)malloc(key_array_size);
    long *offsets = (long *)malloc(offset_array_size);
    if (!keys || !offsets) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    // Initialize keys with random values
    for (long i = 0; i < num_keys; ++i) {
        pthread_mutex_lock(&lock);
        keys[i] = rand_range(1, 100); // Adjust range as needed
        pthread_mutex_unlock(&lock);
    }

    // Dynamic allocation for records
    record *records = NULL;
    int realloc_count = 0;

    while (total_records > 0) {
        records = (record *)realloc(records, total_records * record_size);
        if (!records) {
            perror("Memory reallocation failed");
            exit(EXIT_FAILURE);
        }

        long sum_of_values = 0;

        for (long i = 0; i < total_records; ++i) {
            pthread_mutex_lock(&lock);

            // Adjust range based on cumulative sum
            int adjusted_max = rand_range(1, 100); // Example range
            records[i].key_index = rand_range(0, num_keys - 1);
            records[i].key_index += (sum_of_values % num_keys); // Circular index adjustment

            int value = rand_range(1, adjusted_max);
            sum_of_values += value;

            pthread_mutex_unlock(&lock);

            // Track memory usage and reallocate if necessary
            size_t used_memory = record_size * total_records + key_array_size + offset_array_size;
            if (used_memory > memory_threshold) {
                fprintf(stderr, "Memory threshold exceeded\n");
                realloc_count++;
                total_records /= 2; // Example scaling policy
            }
        }

        printf("Reallocated %d times\n", realloc_count);
    }

    pthread_mutex_destroy(&lock);

    return records;
}

int main(int argc, char *argv[]) {
    if (argc < 5) {
        fprintf(stderr, "Usage: %s num_offsets num_keys initial_record_count seed\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    long num_offsets = atol(argv[1]);
    long num_keys = atol(argv[2]);
    long initial_record_count = atol(argv[3]);
    int seed = atoi(argv[4]);

    init_rand(seed);

    record *records = manage_memory_and_initialize(num_offsets, num_keys, initial_record_count, seed);

    if (records) {
        // Use records...

        free(records); // Clean up
    }

    return 0;
}
