#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Define the sensor data structure
typedef struct {
    long timestamp;
    float reading;
    int quality;
} SensorData;

// Configuration structure
typedef struct {
    size_t batch_size;
    time_t retention_period_seconds;
    int logging_level;
} Config;

// Global configuration instance
Config config = {10000, 3600, 1}; // Default values

// Logger function
void log_message(const char *message) {
    if (config.logging_level > 0) {
        printf("%s\n", message);
    }
}

// Sensor data list node
typedef struct Node {
    SensorData data;
    struct Node* next;
} Node;

// Thread-safe linked list for sensor data
typedef struct {
    Node* head;
    pthread_mutex_t mutex;
} SensorList;

SensorList sensor_list = {NULL, PTHREAD_MUTEX_INITIALIZER};

// Function to create a new sensor data node
Node* create_node(long timestamp, float reading, int quality) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_message("Memory allocation failed for new sensor data node.");
        return NULL;
    }
    new_node->data.timestamp = timestamp;
    new_node->data.reading = reading;
    new_node->data.quality = quality;
    new_node->next = NULL;
    log_message("Successfully created a new sensor data node.");
    return new_node;
}

// Function to add sensor data
void add_sensor_data(long timestamp, float reading, int quality) {
    Node* new_node = create_node(timestamp, reading, quality);
    if (!new_node) return;

    pthread_mutex_lock(&sensor_list.mutex);
    new_node->next = sensor_list.head;
    sensor_list.head = new_node;
    pthread_mutex_unlock(&sensor_list.mutex);

    log_message("Successfully added a new sensor data record.");
}

// Function to remove outdated records
void remove_outdated_records() {
    time_t now = time(NULL);
    Node *current, *prev;

    pthread_mutex_lock(&sensor_list.mutex);
    current = sensor_list.head;
    prev = NULL;

    while (current) {
        if ((now - current->data.timestamp) > config.retention_period_seconds) {
            Node* to_delete = current;
            if (prev) {
                prev->next = current->next;
            } else {
                sensor_list.head = current->next;
            }
            free(to_delete);
            log_message("Removed an outdated sensor data record.");
        } else {
            prev = current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&sensor_list.mutex);
}

// Function to process data in batches
void process_data_batch() {
    Node *current, *prev;
    size_t count = 0;

    pthread_mutex_lock(&sensor_list.mutex);
    current = sensor_list.head;
    prev = NULL;

    while (current && count < config.batch_size) {
        // Process the data here
        log_message("Processing a batch of sensor data.");

        Node* to_process = current;
        if (prev) {
            prev->next = current->next;
        } else {
            sensor_list.head = current->next;
        }
        current = current->next;

        free(to_process);
        count++;
    }

    pthread_mutex_unlock(&sensor_list.mutex);

    log_message("Finished processing a batch of data.");
}

// Function to update configuration
void update_config(size_t new_batch_size, time_t new_retention_period_seconds, int new_logging_level) {
    config.batch_size = new_batch_size;
    config.retention_period_seconds = new_retention_period_seconds;
    config.logging_level = new_logging_level;
    log_message("Configuration updated.");
}

// Function to free all sensor data
void free_sensor_data() {
    Node* current = sensor_list.head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    sensor_list.head = NULL;
    pthread_mutex_unlock(&sensor_list.mutex);
}

// Example usage
int main() {
    // Update configuration if needed
    update_config(5000, 7200, 2);

    // Simulate adding data
    for (int i = 0; i < 10000; ++i) {
        add_sensor_data(time(NULL) - i * 60, (float)i, 1);
    }

    // Remove outdated records
    remove_outdated_records();

    // Process data in batches
    process_data_batch();
    process_data_batch();

    // Free all sensor data
    free_sensor_data();

    return 0;
}
```

