void deallocate_pdu(MemoryPool* pool, NFAPI_CRC_INDICATION_PDU_T* pdu);

// CRC indication PDU management
typedef struct {
    MemoryPool* pool;
    atomic_uint_fast32_t successful_allocations;
    atomic_uint_fast32_t failed_allocations;
} CRCIndicationManager;

CRCIndicationManager* create_crc_indication_manager(size_t num_ues);
void destroy_crc_indication_manager(CRCIndicationManager* manager);
NFAPI_CRC_INDICATION_PDU_T* get_pdu(CRCIndicationManager* manager, uint16_t rnti);

// Custom memory pool allocator
MemoryPool* create_memory_pool(size_t block_size, size_t pool_size) {
    if (block_size == 0 || pool_size == 0) return NULL;

    MemoryPool* pool = malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    void* raw_memory = aligned_alloc(ALIGNMENT, block_size * pool_size);
    if (!raw_memory) {
        free(pool);
        return NULL;
    }

    pool->block_size = block_size;
    pool->memory_pool = raw_memory;
    pool->free_blocks_count = pool_size;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void destroy_memory_pool(MemoryPool* pool) {
    if (pool) {
        free(pool->memory_pool);
        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu(MemoryPool* pool) {
    if (!pool || atomic_load(&pool->free_blocks_count) == 0)
        return NULL;

    pthread_mutex_lock(&pool->lock);

    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)((uint8_t*)pool->memory_pool +
        ((atomic_fetch_sub(&pool->free_blocks_count, 1) + 1) * pool->block_size));

    pthread_mutex_unlock(&pool->lock);

    return pdu;
}

void deallocate_pdu(MemoryPool* pool, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!pool || !pdu) return;

    pthread_mutex_lock(&pool->lock);
    atomic_fetch_add(&pool->free_blocks_count, 1);
    pthread_mutex_unlock(&pool->lock);
}

CRCIndicationManager* create_crc_indication_manager(size_t num_ues) {
    CRCIndicationManager* manager = malloc(sizeof(CRCIndicationManager));
    if (!manager) return NULL;

    size_t block_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    MemoryPool* pool = create_memory_pool(block_size, POOL_SIZE);

    if (!pool) {
        free(manager);
        return NULL;
    }

    manager->pool = pool;
    atomic_init(&manager->successful_allocations, 0);
    atomic_init(&manager->failed_allocations, 0);

    return manager;
}

void destroy_crc_indication_manager(CRCIndicationManager* manager) {
    if (manager) {
        destroy_memory_pool(manager->pool);
        free(manager);
    }
}

NFAPI_CRC_INDICATION_PDU_T* get_pdu(CRCIndicationManager* manager, uint16_t rnti) {
    if (!manager) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* pdu = allocate_pdu(manager->pool);

    if (pdu) {
        atomic_fetch_add(&manager->successful_allocations, 1);
        pdu->ue_info_tag.RNTI = rnti;
        pdu->rnti = rnti;
        pdu->crc_ind_rel8_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    } else {
        atomic_fetch_add(&manager->failed_allocations, 1);
    }

    return pdu;
}

// Example usage
int main() {
    srand(time(NULL));
    size_t num_ues = 100;

    CRCIndicationManager* manager = create_crc_indication_manager(num_ues);

    if (!manager) {
        printf("Failed to create CRC indication manager.\n");
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < num_ues; ++i) {
        uint16_t rnti = rand() % 65536;
        NFAPI_CRC_INDICATION_PDU_T* pdu = get_pdu(manager, rnti);

        if (pdu) {
            // Process PDU
            deallocate_pdu(manager->pool, pdu);
        }
    }

    printf("Successful allocations: %u\n", atomic_load(&manager->successful_allocations));
    printf("Failed allocations: %u\n", atomic_load(&manager->failed_allocations));

    destroy_crc_indication_manager(manager);

    return EXIT_SUCCESS;
}
