#include <stdio.h>

// Define the record structure
typedef struct {
    int value;
    unsigned char encrypted_value[16]; // Assume 128-bit AES encryption
} Record;

void initialize_cryptography_and_data_management(int key_range_min, int key_range_max) {
    // Allocate and initialize long offset values array
    size_t num_offsets = 1024;
    long *offsets = malloc(num_offsets * sizeof(long));
    if (!offsets) {
        // Handle allocation failure
        fprintf(stderr, "Memory allocation failed for offsets\n");
        exit(EXIT_FAILURE);
    }
    memset(offsets, 0, num_offsets * sizeof(long));

    // Allocate and initialize int keys array
    size_t num_keys = 256;
    int *keys = malloc(num_keys * sizeof(int));
    if (!keys) {
        // Handle allocation failure
        fprintf(stderr, "Memory allocation failed for keys\n");
        free(offsets);
        exit(EXIT_FAILURE);
    }
    memset(keys, 0, num_keys * sizeof(int));

    // Allocate and initialize records array
    size_t num_records = 65536;
    Record *records = malloc(num_records * sizeof(Record));
    if (!records) {
        // Handle allocation failure
        fprintf(stderr, "Memory allocation failed for records\n");
        free(keys);
        free(offsets);
        exit(EXIT_FAILURE);
    }

    // Set random values for each record within specified range
    for (size_t i = 0; i < num_records; ++i) {
        if (!RAND_bytes((unsigned char*)&records[i].value, sizeof(int))) {
            // Handle random number generation failure
            fprintf(stderr, "Random number generation failed\n");
            free(records);
            free(keys);
            free(offsets);
            exit(EXIT_FAILURE);
        }
        records[i].value = ((records[i].value % (key_range_max - key_range_min + 1)) + key_range_min);

        // Encrypt the value using AES-128 CTR mode with a static key
        const unsigned char key[] = {0x2b, 0x7e, 0x15, 0x16, 0x28, 0xae, 0xd2, 0xa6, 
                                     0xab, 0xf7, 0xcf, 0x9d, 0x4c, 0x3f, 0xbf, 0xb5}; // Complete AES key
        unsigned char iv[AES_BLOCK_SIZE]; // Initialization vector for CTR mode

        if (!RAND_bytes(iv, sizeof(iv))) {
            fprintf(stderr, "Random IV generation failed\n");
            free(records);
            free(keys);
            free(offsets);
            exit(EXIT_FAILURE);
        }

        EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
        if (!ctx) {
            fprintf(stderr, "Failed to create cipher context\n");
            free(records);
            free(keys);
            free(offsets);
            exit(EXIT_FAILURE);
        }

        if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_128_ctr(), NULL, key, iv)) {
            fprintf(stderr, "Encryption initialization failed\n");
            EVP_CIPHER_CTX_free(ctx);
            free(records);
            free(keys);
            free(offsets);
            exit(EXIT_FAILURE);
        }

        int len;
        if (1 != EVP_EncryptUpdate(ctx, records[i].encrypted_value, &len, 
                                   (unsigned char*)&records[i].value, sizeof(int))) {
            fprintf(stderr, "Encryption update failed\n");
            EVP_CIPHER_CTX_free(ctx);
            free(records);
            free(keys);
            free(offsets);
            exit(EXIT_FAILURE);
        }

        int plaintext_len = len;
        if (1 != EVP_EncryptFinal_ex(ctx, records[i].encrypted_value + len, &len)) {
            fprintf(stderr, "Encryption finalization failed\n");
            EVP_CIPHER_CTX_free(ctx);
            free(records);
            free(keys);
            free(offsets);
            exit(EXIT_FAILURE);
        }
        plaintext_len += len;

        EVP_CIPHER_CTX_free(ctx);

        // Optionally print the encrypted value for verification
        printf("Encrypted value: ");
        for (int j = 0; j < sizeof(Record::encrypted_value); ++j) {
            printf("%02x", records[i].encrypted_value[j]);
        }
        printf("\n");
    }

    // Cleanup
    free(records);
    free(keys);
    free(offsets);
}
