typedef struct {
    float value;
    char* description;
    size_t index;
} operation;

typedef struct {
    float temperature;
    float pressure;
} environment_factors;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

float complex_formula(float sum_previous, size_t index, float temperature, float pressure) {
    // Example formula for demonstration
    return (sum_previous + index * 1.23f) / (temperature + pressure);
}

void* initialize_operations(void* args) {
    int start_index = *(int*)args;
    int end_index = *(int*)(args + sizeof(int));
    operation* operations = *(operation**)(args + 2 * sizeof(int));
    float temperature = *((float*)(args + 3 * sizeof(int)));
    float pressure = *((float*)(args + 4 * sizeof(int)));

    pthread_mutex_lock(&mutex);

    float sum_previous = 0.0f;
    float avg_result = 0.0f;

    for (int i = start_index; i < end_index; ++i) {
        operations[i].value = complex_formula(sum_previous, i, temperature, pressure);

        // Allocate and initialize description
        asprintf(&operations[i].description, "Operation %zu", i);

        operations[i].index = i;
        sum_previous += operations[i].value;

        avg_result = sum_previous / (i + 1);
    }

    pthread_mutex_unlock(&mutex);

    return NULL;
}

void manage_operations(operation** operations, size_t num_ops, int num_threads, float temperature, float pressure) {
    if (*operations == NULL) {
        *operations = malloc(num_ops * sizeof(operation));
        memset(*operations, 0, num_ops * sizeof(operation));
    }

    pthread_t threads[num_threads];
    int range_per_thread = num_ops / num_threads;
    int* args_array = (int*)malloc((num_threads * 5) * sizeof(int));

    for (int t = 0; t < num_threads; ++t) {
        args_array[t * 5] = t * range_per_thread;
        args_array[t * 5 + 1] = (t == num_threads - 1) ? num_ops : (t + 1) * range_per_thread;

        memcpy(args_array + t * 5 + 2, operations, sizeof(operation*));
        *(float*)(args_array + t * 5 + 3) = temperature;
        *(float*)(args_array + t * 5 + 4) = pressure;

        pthread_create(&threads[t], NULL, initialize_operations, args_array + t * 5);
    }

    for (int t = 0; t < num_threads; ++t) {
        pthread_join(threads[t], NULL);
