#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_CAPACITY 1000

typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    Record *records;
    int count;
    int capacity;
    int *keys;
    pthread_mutex_t lock;
} Collection;

// Function prototypes
Collection* create_collection(int capacity);
int add_record(Collection* collection, int key_range_min, int key_range_max, long offset_range_min, long offset_range_max);
void free_collection(Collection* collection);
void log_error(const char* message);

Collection* create_collection(int capacity) {
    Collection *collection = (Collection*)malloc(sizeof(Collection));
    if (!collection) {
        log_error("Failed to allocate memory for Collection");
        return NULL;
    }

    collection->records = (Record*)calloc(capacity, sizeof(Record));
    collection->keys = (int*)calloc(capacity, sizeof(int));
    if (!collection->records || !collection->keys) {
        free(collection);
        log_error("Failed to allocate memory for records or keys");
        return NULL;
    }

    collection->count = 0;
    collection->capacity = capacity;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

int is_key_present(Collection* collection, int key) {
    for (int i = 0; i < collection->count; ++i) {
        if (collection->records[i].key == key) {
            return 1;
        }
    }
    return 0;
}

int add_record(Collection* collection, int key_range_min, int key_range_max, long offset_range_min, long offset_range_max) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count >= collection->capacity) {
        pthread_mutex_unlock(&collection->lock);
        log_error("Collection capacity reached");
        return -1;
    }

    int new_key = rand() % (key_range_max - key_range_min + 1) + key_range_min;

    while (is_key_present(collection, new_key)) {
        new_key = rand() % (key_range_max - key_range_min + 1) + key_range_min;
    }

    long new_offset = offset_range_min + rand() % (offset_range_max - offset_range_min + 1);

    collection->records[collection->count].key = new_key;
    collection->records[collection->count].offset = new_offset;

    // Mark the key as present
    for (int i = 0; i < collection->capacity; ++i) {
        if (collection->keys[i] == 0) {
            collection->keys[i] = new_key;
            break;
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

void free_collection(Collection* collection) {
    if (!collection) return;

    free(collection->records);
    free(collection->keys);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}
```

This code defines a C function to manage memory for a dynamic collection of records with unique integer keys and long offset values. It ensures thread safety using mutex locks, handles errors gracefully, and optimizes memory usage by pre-allocating arrays based on maximum capacity. The solution is designed to be extendable and maintainable for future requirements.']

