#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_SIZE 100

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    int size;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;
    list->head = NULL;
    list->size = 0;
    return list;
}

int add_element(List* list, NFAPI_CRC_INDICATION_PDU_T element) {
    if (list->size >= MAX_SIZE) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -2;

    new_node->data = element;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    return 0;
}

int remove_element_by_rnti(List* list, int rnti) {
    Node *current = list->head, *prev = NULL;

    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            if (prev == NULL) list->head = current->next;
            else prev->next = current->next;

            free(current);
            list->size--;
            return 0;
        }
        prev = current;
        current = current->next;
    }

    return -1; // Element not found
}

int update_crcflag_by_rnti(List* list, int rnti, unsigned char crcflag) {
    Node *current = list->head;

    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            current->data.CRC_INDICATION_REL8_TAG.CRCFLAG = crcflag;
            return 0;
        }
        current = current->next;
    }

    return -1; // Element not found
}

void serialize_list(const List* list, const char* filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&list->size, sizeof(int), 1, file);

    Node* current = list->head;
    while (current != NULL) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    fclose(file);
}

int deserialize_list(List* list, const char* filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    int size;
    fread(&size, sizeof(int), 1, file);

    if (size > MAX_SIZE || size < 0) {
        fclose(file);
        return -2; // Invalid size
    }

    list->head = NULL;
    list->size = 0;

    for (int i = 0; i < size; ++i) {
        NFAPI_CRC_INDICATION_PDU_T element;
        fread(&element, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);

        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            fclose(file);
            return -3; // Memory allocation failed
        }

        new_node->data = element;
        new_node->next = list->head;
        list->head = new_node;
        list->size++;
    }

    fclose(file);
    return 0;
}

void free_list(List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

// Stress testing function (example)
void stress_test() {
    List* list = create_list();

    for (int i = 0; i < MAX_SIZE; ++i) {
        NFAPI_CRC_INDICATION_PDU_T element;
        element.RX_UE_INFORMATION_TAG = rand();
        element.RNTI = rand();
        element.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        add_element(list, element);
    }

    // Serialize and deserialize
    serialize_list(list, "nfa_data.bin");
    List* new_list = create_list();
    deserialize_list(new_list, "nfa_data.bin");

    // Verify list size matches after deserialization
    if (new_list->size != MAX_SIZE) {
        printf("Deserialization failed: expected %d elements, got %d\n", MAX_SIZE, new_list->size);
    } else {
        printf("Deserialization successful!\n");
    }

    free_list(list);
    free_list(new_list);
}

int main() {
    stress_test();
    return 0;
}
```

