using System.Threading.Tasks;

public class DecryptionService
{
    private readonly byte[] _encryptionKey;
    private readonly byte[] _iv;
    private readonly byte[] _reEncryptionKey;
    private readonly HMACSHA256 _hmac;
    private readonly ConcurrentDictionary<long, int> _offsets = new();
    private readonly ConcurrentDictionary<int, KeyRecord> _keys = new();
    private readonly BlockingCollection<DecryptionTask> _tasksQueue = new(BoundedCapacity);
    private readonly object _lockObj = new();

    public DecryptionService(byte[] encryptionKey, byte[] iv, byte[] reEncryptionKey)
    {
        _encryptionKey = encryptionKey ?? throw new ArgumentNullException(nameof(encryptionKey));
        _iv = iv ?? throw new ArgumentNullException(nameof(iv));
        _reEncryptionKey = reEncryptionKey ?? throw new ArgumentNullException(nameof(reEncryptionKey));

        _hmac = new HMACSHA256(_reEncryptionKey);
        Task.Run(() => ProcessTasks());
    }

    private class KeyRecord
    {
        public int Value { get; set; }
        public byte[] ReferenceKey { get; set; }
        public DateTime Timestamp { get; set; }
    }

    private struct Metadata
    {
        public long TotalSum;
        public bool NeedsResizing;
        public Exception OverflowException;
    }

    private class DecryptionTask
    {
        public byte[] Ciphertext { get; }
        public byte[] ExpectedHMAC { get; }

        public DecryptionTask(byte[] ciphertext, byte[] expectedHmac)
        {
            Ciphertext = ciphertext ?? throw new ArgumentNullException(nameof(ciphertext));
            ExpectedHMAC = expectedHmac ?? throw new ArgumentNullException(nameof(expectedHmac));
        }
    }

    private readonly int BoundedCapacity = 1000;

    public void EnqueueDecryptionTask(byte[] ciphertext, byte[] expectedHMAC)
    {
        _tasksQueue.Add(new DecryptionTask(ciphertext, expectedHMAC));
    }

    private async Task ProcessTasks()
    {
        while (true)
        {
            var task = await _tasksQueue.TakeAsync();
            try
            {
                var plaintext = Decrypt(task.Ciphertext);
                ValidateIntegrity(plaintext, task.ExpectedHMAC);

                // Simulate integration with external system and compression
                CompressAndSerializeData(plaintext);

                Log($"Decryption successful for task at {DateTime.Now}");
            }
            catch (Exception ex)
            {
                Log($"Error during decryption: {ex.Message}", isError: true);
                throw;
            }
        }
    }

    private byte[] Decrypt(byte[] ciphertext)
    {
        using var aes = Aes.Create();
        aes.Key = _encryptionKey;
        aes.IV = _iv;
        aes.Mode = CipherMode.CBC;

        using var decryptor = aes.CreateDecryptor(aes.Key, aes.IV);
        using var ms = new MemoryStream(ciphertext);
        using var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read);

        byte[] plaintext = new byte[ciphertext.Length];
        int readBytes = cs.Read(plaintext, 0, plaintext.Length);

        Array.Resize(ref plaintext, readBytes); // Resize to actual data size
        return plaintext;
    }

    private void ValidateIntegrity(byte[] decryptedData, byte[] expectedHMAC)
    {
        using var hmac = new HMACSHA256(_reEncryptionKey);
        byte[] computedHash = hmac.ComputeHash(decryptedData);

        if (!StructuralComparisons.StructuralEqualityComparer.Equals(computedHash, expectedHMAC))
            throw new InvalidOperationException("Data integrity check failed.");
    }

    private void CompressAndSerializeData(byte[] data)
    {
        // Simulate compression and serialization
        Log($"Compressed and serialized data at {DateTime.Now}");
    }

    private void Log(string message, bool isError = false)
    {
        var logLevel = isError ? "ERROR" : "INFO";
        Console.WriteLine($"{logLevel}: {message}");
    }
}
