        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

# Define maximum sum limit and lock for thread safety
#define MAX_SUM_LIMIT 10000
threading.Lock() = lock

def manage_dynamic_memory_allocation(records: List[record_t], nfa_pi_list: List[NFAPI_CRC_INDICATION_PDU_T]) -> int:
    if not records or len(records) == 0:
        return 0

    total_sum = 0
    initialized_count = 0

    # Lock for thread safety
    with lock:
        for record in records:
            if record.key is None or *record.key < 0:  # Invalid key reference check
                continue

            nfa_pi_entry = NFAPI_CRC_INDICATION_PDU_T()
            nfa_pi_entry.RX_UE_INFORMATION_TAG = *record.key
            nfa_pi_entry.RNTI = rand() % 1000000  # Random RNTI generation
            nfa_pi_entry.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2

            total_sum += record.value

            if total_sum > MAX_SUM_LIMIT:
                printf("Warning: Maximum sum limit exceeded\n")
                break

            nfa_pi_list.append(nfa_pi_entry)
            initialized_count += 1

        # Adjust logic based on current average value
        if initialized_count > 0:
            average_value = total_sum / initialized_count
            print(f"Average value of initialized records: {average_value}")

    return initialized_count

# Comprehensive testing function
