    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T *list;
    size_t count;
} CRC_INDICATION_LIST_T;

void init_crc_indication_list(CRC_INDICATION_LIST_T *crclist) {
    pthread_mutex_init(&crclist->lock, NULL);
    crclist->list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(MAX_LIST_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crclist->list) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    crclist->count = 0;
}

void destroy_crc_indication_list(CRC_INDICATION_LIST_T *crclist) {
    pthread_mutex_lock(&crclist->lock);
    free(crclist->list);
    pthread_mutex_unlock(&crclist->lock);
    pthread_mutex_destroy(&crclist->lock);
}

bool configure_crcflag(float probability) {
    return (float)rand() / RAND_MAX < probability;
}

void populate_crc_indication_list(CRC_INDICATION_LIST_T *crclist, size_t n_elements, float crc_probability) {
    srand(time(NULL));

    pthread_mutex_lock(&crclist->lock);
    if (n_elements > MAX_LIST_SIZE || n_elements > (MAX_LIST_SIZE - crclist->count)) {
        fprintf(stderr, "Requested number of elements exceeds maximum list size or available space\n");
        pthread_mutex_unlock(&crclist->lock);
        return;
    }

    for (size_t i = 0; i < n_elements; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &crclist->list[crclist->count + i];

        pdu->RX_UE_INFORMATION_TAG = rand(); // Simulating valid tag
        pdu->RNTI = rand() % 65536;          // Valid RNTI range
        pdu->CRC_INDICATION_REL8_TAG = rand() % 256; // Random CRC tag
        pdu->CRCFLAG = configure_crcflag(crc_probability);
    }

    crclist->count += n_elements;
    pthread_mutex_unlock(&crclist->lock);
}

int main() {
    CRC_INDICATION_LIST_T crcList;
    init_crc_indication_list(&crcList);

    size_t numElements = 500; // Example number of elements to populate
    float crcProbability = 0.5f; // Example probability

    populate_crc_indication_list(&crcList, numElements, crcProbability);

    printf("Populated %zu elements with CRCFLAG probability of %.2f\n", crcList.count, crcProbability);

    destroy_crc_indication_list(&crcList);
    return 0;
}
