    sensorData newData = { .timestamp = 1000, .temperature = 30.0f, .status = 2 };

    unsafeSensorUpdate(globalArray, sizeof(globalArray) / sizeof(sensorData), newData);

    return 0;
}

// Function to initialize SensorManager
SensorManager* initializeSensorManager(size_t initialCapacity) {
    SensorManager *manager = (SensorManager*)malloc(sizeof(SensorManager));
    if (!manager) {
        perror("Failed to allocate memory for manager");
        exit(EXIT_FAILURE);
    }

    manager->dataArray = (sensorData*)calloc(initialCapacity, sizeof(sensorData));
    if (!manager->dataArray) {
        free(manager);
        perror("Failed to allocate memory for dataArray");
        exit(EXIT_FAILURE);
    }

    manager->capacity = initialCapacity;
    manager->count = 0;

    if (pthread_mutex_init(&manager->lock, NULL) != 0) {
        perror("Mutex init has failed");
        free(manager->dataArray);
        free(manager);
        exit(EXIT_FAILURE);
    }

    return manager;
}

// Function to add sensor data safely
int addSensorData(SensorManager *manager, sensorData newData) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        resizeIfNeeded(manager);
    }

    manager->dataArray[manager->count++] = newData;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Function to resize the array if needed
void resizeIfNeeded(SensorManager *manager) {
    size_t newCapacity = manager->capacity < MAX_SENSORS ? manager->capacity * 2 : MAX_SENSORS;
    sensorData *newArray = (sensorData*)realloc(manager->dataArray, newCapacity * sizeof(sensorData));

    if (!newArray) {
        perror("Failed to reallocate memory for dataArray");
        exit(EXIT_FAILURE);
    }

    manager->dataArray = newArray;
    manager->capacity = newCapacity;
}

// Function to free resources
void freeSensorManager(SensorManager *manager) {
    pthread_mutex_destroy(&manager->lock);
    free(manager->dataArray);
    free(manager);
}
