```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_STRUCTS_PER_SESSION 1000

typedef struct {
    int sequence_number;
    time_t timestamp;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    int count;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* create_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_list(DynamicList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_to_list(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (!list || list->count >= MAX_STRUCTS_PER_SESSION) return 0;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return 0;

    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    list->count++;
    pthread_mutex_unlock(&list->lock);

    return 1;
}

int is_rnti_valid(uint16_t rnti) {
    return rnti >= 0 && rnti <= 65535;
}

void process_data(DynamicList* list, uint16_t rnti, const char* data_source_type) {
    if (!is_rnti_valid(rnti)) {
        fprintf(stderr, "Invalid RNTI: %u\n", rnti);
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.sequence_number = list->count + 1; // Unique sequence number
    pdu.timestamp = time(NULL);            // Current timestamp
    pdu.RNTI = rnti;
    pdu.CRCFLAG = rand() % 2;              // Random CRC flag

    add_to_list(list, pdu);
}

void simulate_data_sources(DynamicList* list) {
    for (int i = 0; i < 50000; ++i) {
        uint16_t rnti = rand() % 70000;     // Simulate RNTI value
        process_data(list, rnti, "sensor_feed"); // Example data source type

        if ((i + 1) % 1000 == 0) {          // Batch processing simulation
            printf("Processed batch of 1000 entries.\n");
            // Log performance metrics here (e.g., CPU usage, memory consumption)
        }
    }
}

int get_total_count(DynamicList* list) {
    pthread_mutex_lock(&list->lock);
    int count = list->count;
    pthread_mutex_unlock(&list->lock);
    return count;
}

void* threaded_data_processing(void* arg) {
    DynamicList* list = (DynamicList*)arg;
    simulate_data_sources(list);
    return NULL;
}

int main() {
    srand(time(NULL)); // Seed random number generator

    DynamicList* list = create_list();
    if (!list) {
        fprintf(stderr, "Failed to create dynamic list.\n");
        return EXIT_FAILURE;
    }

    pthread_t thread;
    if (pthread_create(&thread, NULL, threaded_data_processing, list) != 0) {
        fprintf(stderr, "Failed to create processing thread.\n");
        free_list(list);
        return EXIT_FAILURE;
    }

    pthread_join(thread, NULL);

    printf("Total successfully created structures: %d\n", get_total_count(list));

    free_list(list);
    return EXIT_SUCCESS;
}
```

### Key Points:
