#include <stdint.h>

typedef struct {
    int value;
    int* key_ref;
} record;

typedef struct {
    record** records;
    int* keys;
    size_t count;
    uint64_t total_sum;
    pthread_mutex_t lock;  // Using a mutex to manage concurrency
} record_system;

// Function to initialize the record system
record_system* init_record_system(size_t key_count, size_t record_count) {
    record_system* rs = malloc(sizeof(record_system));
    if (!rs) return NULL;

    rs->records = calloc(record_count, sizeof(record *));
    rs->keys = malloc(key_count * sizeof(int));
    rs->count = record_count;
    rs->total_sum = 0;
    pthread_mutex_init(&rs->lock, NULL);

    // Initialize keys with random values
    for (size_t i = 0; i < key_count; ++i) {
        rs->keys[i] = rand() % 100;  // Example range [0, 99]
    }

    return rs;
}

// Function to allocate and initialize records
void* init_records(void* arg) {
    record_system* rs = (record_system*)arg;

    for (size_t i = 0; i < rs->count; ++i) {
        pthread_mutex_lock(&rs->lock);

        // Allocate memory for a new record
        rs->records[i] = malloc(sizeof(record));
        if (!rs->records[i]) {
            perror("Failed to allocate memory for record");
            exit(EXIT_FAILURE);
        }

        // Assign key reference and random value within specified range
        int cumulative_sum = 0;
        for (size_t j = 0; j <= i; ++j) {
            cumulative_sum += rs->records[j]->value;
        }

        int min_value = 10, max_value = 20; // Example range [10, 20]
        rs->records[i]->value = rand() % (max_value - min_value + 1) + min_value + cumulative_sum;

        rs->records[i]->key_ref = &rs->keys[rand() % (sizeof(rs->keys) / sizeof(int))];

        // Update total sum
        rs->total_sum += rs->records[i]->value;

        pthread_mutex_unlock(&rs->lock);
    }

    return NULL;
}

// Function to deallocate the record system
void cleanup_record_system(record_system* rs) {
    if (!rs) return;

    for (size_t i = 0; i < rs->count; ++i) {
        free(rs->records[i]);
    }
    free(rs->records);
    free(rs->keys);
    pthread_mutex_destroy(&rs->lock);
    free(rs);
}

int main() {
    size_t key_count = 10;
    size_t record_count = 5;

    // Initialize the system
    record_system* rs = init_record_system(key_count, record_count);

    if (!rs) return EXIT_FAILURE;

    pthread_t threads[record_count];

    // Create multiple threads to initialize records concurrently
    for (size_t i = 0; i < record_count; ++i) {
        if (pthread_create(&threads[i], NULL, init_records, rs)) {
            perror("Failed to create thread");
            cleanup_record_system(rs);
            return EXIT_FAILURE;
        }
    }

    // Wait for all threads to finish
    for (size_t i = 0; i < record_count; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Output the results
    printf("Total Sum: %llu\n", rs->total_sum);
    for (size_t i = 0; i < record_count; ++i) {
        printf("Record %zu - Value: %d, Key: %d\n",
               i, rs->records[i]->value, *(rs->records[i]->key_ref));
    }

    // Cleanup
    cleanup_record_system(rs);

    return EXIT_SUCCESS;
}
```

This code demonstrates a C implementation that allocates and initializes memory for records in a thread-safe manner using mutexes. It handles concurrency through locking mechanisms and manages dynamic memory allocation efficiently, including handling non-contiguous allocations if required by user requests (though the demonstration keeps it simple). The function is designed to handle varying loads gracefully, ensuring robustness under different conditions.']

