} RecordManager;

#define INITIAL_CAPACITY 10
#define LOAD_FACTOR_THRESHOLD 0.75

// Function prototypes
RecordManager* create_record_manager();
void free_record_manager(RecordManager* manager);
int add_record(RecordManager* manager, long offset, int min_key, int max_key);
static void resize_record_array(RecordManager* manager);
static int generate_random_unique_key(int used_keys[], int min_key, int max_key);

// Create a new record manager
RecordManager* create_record_manager() {
    RecordManager *manager = malloc(sizeof(RecordManager));
    if (!manager) {
        log_error("Failed to allocate memory for RecordManager");
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    manager->records = malloc(INITIAL_CAPACITY * sizeof(record));
    if (!manager->records) {
        log_error("Failed to allocate memory for records array");
        free(manager);
        return NULL;
    }
    manager->size = 0;
    manager->capacity = INITIAL_CAPACITY;

    // Initialize keys tracking
    int used_keys[INT_MAX] = {0};  // Simple representation, consider using a hash table

    // Populate initial random unique keys for demonstration purposes
    while (manager->size < INITIAL_CAPACITY) {
        if (!add_record(manager, rand() % 100000, 1, INT_MAX - 1)) {
            log_error("Failed to add record with unique key");
            break;
        }
    }

    return manager;
}

// Free the record manager and its resources
void free_record_manager(RecordManager* manager) {
    if (manager) {
        pthread_mutex_destroy(&manager->lock);
        free(manager->records);
        free(manager);
    }
}

// Add a new record with a unique key and random value within specified range
int add_record(RecordManager* manager, long offset, int min_key, int max_key) {
    if (!manager || offset < 0 || min_key >= max_key) return 0;

    pthread_mutex_lock(&manager->lock);

    // Check if resize is needed
    if (manager->size >= manager->capacity * LOAD_FACTOR_THRESHOLD) {
        resize_record_array(manager);
    }

    int key = generate_random_unique_key(used_keys, min_key, max_key);
    if (key == -1) {
        pthread_mutex_unlock(&manager->lock);
        return 0;
    }

    // Insert the record
    manager->records[manager->size].key = key;
    manager->records[manager->size].offset = offset;
    used_keys[key] = 1;  // Mark this key as used

    manager->size++;
    pthread_mutex_unlock(&manager->lock);
    return 1;
}

// Resize the record array
static void resize_record_array(RecordManager* manager) {
    int new_capacity = manager->capacity * 2;
    record *new_records = realloc(manager->records, new_capacity * sizeof(record));
    if (!new_records) {
        log_error("Failed to reallocate memory for records array");
        return;
    }
    manager->records = new_records;
    manager->capacity = new_capacity;
}

// Generate a random unique key within the specified range
static int generate_random_unique_key(int used_keys[], int min_key, int max_key) {
    int attempts = 0;
    while (attempts < 100) { // Limit attempts to avoid infinite loops in tight ranges
        int key = rand() % (max_key - min_key + 1) + min_key;
        if (!used_keys[key]) {
            return key;
        }
        attempts++;
    }
    log_error("Failed to generate a unique random key");
    return -1;
}

// Example usage with logging and garbage collection placeholder
void periodic_garbage_collection(RecordManager* manager) {
    // Placeholder for invoking garbage collector periodically
    perform_garbage_collection();  // Assume this is part of the memory management library
}
