    int *key;
} Record;

typedef struct {
    Record *records;
    int count;
    int capacity;
    int totalValue;
    int minValue;
    int maxValue;
    pthread_mutex_t lock;
} RecordManager;

RecordManager* create_manager(int initial_capacity) {
    RecordManager *manager = malloc(sizeof(RecordManager));
    manager->records = calloc(initial_capacity, sizeof(Record));
    manager->count = 0;
    manager->capacity = initial_capacity;
    manager->totalValue = 0;
    manager->minValue = INT_MAX;
    manager->maxValue = INT_MIN;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void resize_manager(RecordManager *manager) {
    int new_capacity = manager->capacity * 2;
    Record *new_records = realloc(manager->records, new_capacity * sizeof(Record));
    if (new_records) {
        manager->records = new_records;
        manager->capacity = new_capacity;
    }
}

void init_random_range(int minRange, int maxRange, int *minResult, int *maxResult) {
    *minResult = rand() % (maxRange - minRange + 1) + minRange;
    *maxResult = rand() % (maxRange - minRange + 1) + minRange;
}

void init_record(RecordManager *manager, int value_range_start, int value_range_end) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        resize_manager(manager);
    }

    int median_value = manager->totalValue / manager->count;
    int new_min = median_value - 10;
    int new_max = median_value + 10;

    init_random_range(new_min, new_max, &manager->records[manager->count].value, NULL);

    manager->records[manager->count].key = malloc(sizeof(int));
    *manager->records[manager->count].key = rand();

    manager->totalValue += manager->records[manager->count].value;
    if (manager->records[manager->count].value < manager->minValue) {
        manager->minValue = manager->records[manager->count].value;
    }
    if (manager->records[manager->count].value > manager->maxValue) {
        manager->maxValue = manager->records[manager->count].value;
    }

    manager->count++;

    printf("Initialized record %d: value=%d, key=%p\n", 
           manager->count - 1, 
           manager->records[manager->count - 1].value,
           (void*)manager->records[manager->count - 1].key);

    pthread_mutex_unlock(&manager->lock);
}

void free_manager(RecordManager *manager) {
    for (int i = 0; i < manager->count; ++i) {
        free(manager->records[i].key);
    }
    free(manager->records);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int main() {
    srand(time(NULL));

    RecordManager *manager = create_manager(10);

    for (int i = 0; i < 20; ++i) {
        init_record(manager, 1, 100);
    }

    printf("Total: %d, Min: %d, Max: %d\n", manager->totalValue, manager->minValue, manager->maxValue);

    free_manager(manager);

    return 0;
}
