['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    int value;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} RecordCollection;

RecordCollection* create_collection(size_t initial_capacity) {
    RecordCollection *collection = malloc(sizeof(RecordCollection));
    collection->records = calloc(initial_capacity, sizeof(Record));
    collection->capacity = initial_capacity;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void free_collection(RecordCollection *collection) {
    free(collection->records);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int add_record(RecordCollection *collection, Record record) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Record *new_records = realloc(collection->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Memory allocation failed
        }
        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    collection->records[collection->count++] = record;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

Record* get_record(RecordCollection *collection, int key) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i].key == key) {
            Record *record = malloc(sizeof(Record));
            memcpy(record, &collection->records[i], sizeof(Record));
            pthread_mutex_unlock(&collection->lock);
            return record;
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return NULL;
}

int update_record(RecordCollection *collection, int key, int value) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i].key == key) {
            collection->records[i].value = value;
            pthread_mutex_unlock(&collection->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return -1; // Record not found
}

int delete_record(RecordCollection *collection, int key) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i].key == key) {
            memset(&collection->records[i], 0, sizeof(Record)); // Reset to default values
            pthread_mutex_unlock(&collection->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return -1; // Record not found
}

void serialize_collection(const RecordCollection *collection, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&collection->count, sizeof(size_t), 1, file);
    fwrite(collection->records, sizeof(Record), collection->count, file);

    fclose(file);
}

int deserialize_collection(RecordCollection *collection, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);
    free(collection->records);

    collection->records = malloc(count * sizeof(Record));
    fread(collection->records, sizeof(Record), count, file);

    collection->capacity = count;
    collection->count = count;

    fclose(file);
    return 0;
}

void randomize_value(int *value, int min, int max) {
    *value = rand() % (max - min + 1) + min;
}

// Example usage
int main() {
    srand(time(NULL));
    RecordCollection *collection = create_collection(10);

    Record record;
    record.offset = 1000;
    record.key = 1;
    randomize_value(&record.value, 0, 100);
    add_record(collection, record);

    Record *fetched = get_record(collection, 1);
    if (fetched) {
        printf("Record fetched: %d\n", fetched->value);
        free(fetched);
    }

    update_record(collection, 1, 42);
    delete_record(collection, 1);

    serialize_collection(collection, "data.bin");
    deserialize_collection(collection, "data.bin");

    free_collection(collection);
    return 0;
}
