// Initialize containers with default and random values
void initializeContainers(DoubleContainer **doubleArray, size_t *doubleSize,
                          CharStringContainer **charArray, size_t *charSize,
                          DataPoint **dataPoints, size_t *dataPointSize) {
    // Seed for random number generation
    srand(time(NULL));

    // Initialize DoubleContainer with random doubles
    size_t initialDoubleSize = 10;
    *doubleArray = (DoubleContainer *)malloc(initialDoubleSize * sizeof(DoubleContainer));
    if (*doubleArray == NULL) {
        fprintf(stderr, "Failed to allocate memory for doubleArray\n");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < initialDoubleSize; ++i) {
        (*doubleArray)[i].value = (double)(rand() % 100) / 10.0;
    }
    *doubleSize = initialDoubleSize;

    // Initialize CharStringContainer with random strings
    size_t initialCharSize = 5;
    *charArray = (CharStringContainer *)malloc(initialCharSize * sizeof(CharStringContainer));
    if (*charArray == NULL) {
        fprintf(stderr, "Failed to allocate memory for charArray\n");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < initialCharSize; ++i) {
        size_t strLength = rand() % 20 + 1;
        (*charArray)[i].str = (char *)malloc(strLength * sizeof(char));
        if ((*charArray)[i].str == NULL) {
            fprintf(stderr, "Failed to allocate memory for char string\n");
            exit(EXIT_FAILURE);
        }
        for (size_t j = 0; j < strLength; ++j) {
            (*charArray)[i].str[j] = 'A' + rand() % 26;
        }
    }
    *charSize = initialCharSize;

    // Initialize DataPoint with random numbers and strings
    size_t initialDataPointSize = 7;
    *dataPoints = (DataPoint *)malloc(initialDataPointSize * sizeof(DataPoint));
    if (*dataPoints == NULL) {
        fprintf(stderr, "Failed to allocate memory for dataPoints\n");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < initialDataPointSize; ++i) {
        (*dataPoints)[i].number = (double)(rand() % 100) / 10.0;
        size_t strLength = rand() % 15 + 5;
        (*dataPoints)[i].text = (char *)malloc(strLength * sizeof(char));
        if ((*dataPoints)[i].text == NULL) {
            fprintf(stderr, "Failed to allocate memory for dataPoint text\n");
            exit(EXIT_FAILURE);
        }
        for (size_t j = 0; j < strLength; ++j) {
            (*dataPoints)[i].text[j] = 'A' + rand() % 26;
        }
    }
    *dataPointSize = initialDataPointSize;

    // Log initialization
    printf("Initialized containers with random data.\n");
}

// Free allocated memory for all containers
void freeContainers(DoubleContainer *doubleArray, CharStringContainer *charArray,
                    DataPoint *dataPoints) {
    if (doubleArray != NULL) {
        free(doubleArray);
    }

    if (charArray != NULL) {
        for (size_t i = 0; i < charSize; ++i) {
            free(charArray[i].str);
        }
        free(charArray);
    }

    if (dataPoints != NULL) {
        for (size_t i = 0; i < dataPointSize; ++i) {
            free(dataPoints[i].text);
        }
        free(dataPoints);
    }

    // Log deallocation
    printf("Freed all allocated memory.\n");
}

int main() {
    manageMemory();
    return 0;
}
