#include <math.h>

typedef struct {
    float real;
    float imag;
} COMPLEX;

typedef struct {
    float power_dB;
} PHICH_DEMODULATION_INFO;

typedef struct {
    int antenna_index;
    PHICH_DEMODULATION_INFO phich_demodulation_info;
    float signal_quality;
} LTE_PHY_RX_FRAME_T;

#define MAX_ANTENNA_INDEX 4
#define VALID_SIGNAL_THRESHOLD -100.0f

int read_float(FILE *file, float *value) {
    if (fread(value, sizeof(float), 1, file) != 1) return EOF;
    return 0;
}

void process_large_binary_file(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    LTE_PHY_RX_FRAME_T *frames = NULL;
    size_t frame_count = 0;
    float number;

    while (read_float(file, &number) != EOF) {
        if (isnan(number) || isinf(number) || number < VALID_SIGNAL_THRESHOLD) continue;

        frames = realloc(frames, sizeof(LTE_PHY_RX_FRAME_T) * (frame_count + 1));
        if (!frames) break;

        int antenna_index = frame_count % MAX_ANTENNA_INDEX;
        PHICH_DEMODULATION_INFO info = {.power_dB = 10.0f * log10(fabs(number))};
        frames[frame_count].antenna_index = antenna_index;
        frames[frame_count].phich_demodulation_info = info;
        frames[frame_count].signal_quality = fabs(number);
        frame_count++;
    }

    fclose(file);

    if (frame_count == 0) return;

    int best_frame_index = 0;
    float highest_signal_quality = frames[0].signal_quality;

    for (size_t i = 1; i < frame_count; ++i) {
        if (frames[i].signal_quality > highest_signal_quality) {
            highest_signal_quality = frames[i].signal_quality;
            best_frame_index = i;
        }
    }

    printf("Frame with the highest signal quality is at index: %d\n", best_frame_index);

    free(frames);
}
