        return {'offset': self.offset, 'key': self.key, 'value': self.value}

class RecordManager:
    def __init__(self):
        self.records = []
        self.lock = Lock()
        self.capacity = INITIAL_CAPACITY

    def resize_if_needed(self):
        with self.lock:
            if len(self.records) >= self.capacity:
                self.capacity *= 2
                # Dynamic resizing logic to minimize memory fragmentation can be implemented here.

    def add_record(self, record: Record):
        with self.lock:
            self.resize_if_needed()
            self.records.append(record)

    def get_records(self, page=1, per_page=10):
        start = (page - 1) * per_page
        end = start + per_page
        return self.records[start:end]

    def find_record_by_key(self, key: int):
        with self.lock:
            for record in self.records:
                if record.key == key:
                    return record.to_dict()
        return None

    def serialize(self):
        with self.lock:
            return json.dumps([record.to_dict() for record in self.records])

    def deserialize(self, data: str):
        records = json.loads(data)
        with self.lock:
            self.records = [Record(**r) for r in records]

# Instance of RecordManager
record_manager = RecordManager()

@app.route('/records', methods=['GET'])
def get_records():
    page = int(request.args.get('page', 1))
    per_page = int(request.args.get('per_page', 10))
    records = record_manager.get_records(page, per_page)
    return jsonify([record.to_dict() for record in records])

@app.route('/records/<int:key>', methods=['GET'])
def get_record_by_key(key):
    record = record_manager.find_record_by_key(key)
    if record:
        return jsonify(record)
    return jsonify({'error': 'Record not found'}), 404

@app.route('/records', methods=['POST'])
def bulk_insert():
    data = request.json
    if not isinstance(data, list):
        return jsonify({'error': 'Invalid input format. Expected a list of records.'}), 400

    with ThreadPoolExecutor() as executor:
        for item in data:
            if 'offset' in item and 'key' in item:
                record = Record(item['offset'], item['key'])
                executor.submit(record_manager.add_record, record)
            else:
                return jsonify({'error': f"Record {item} is missing required fields."}), 400
    return jsonify({'message': 'Records added successfully'}), 201

@app.route('/serialize', methods=['GET'])
def serialize_records():
    serialized_data = record_manager.serialize()
    return jsonify({'data': serialized_data})

@app.route('/deserialize', methods=['POST'])
def deserialize_records():
    data = request.json.get('data')
    if not isinstance(data, str):
        return jsonify({'error': 'Invalid input format. Expected a JSON string.'}), 400
    try:
        record_manager.deserialize(data)
        return jsonify({'message': 'Records deserialized successfully'})
    except json.JSONDecodeError as e:
        return jsonify({'error': str(e)}), 400

if __name__ == '__main__':
    app.run(debug=True, threaded=True)

# Note: Real-time monitoring and distributed cache service integration are omitted for simplicity.
