#define MAX_RECORDS 1000
#define KEY_RANGE 100

typedef struct {
    int value;
} record_t;

typedef struct {
    long *offsets;
    int *keys;
    record_t *records;
    size_t num_records;
    size_t total_value;
    pthread_mutex_t lock;
} storage_system_t;

// Helper function to initialize the random number generator
void init_random() {
    srand((unsigned)time(NULL));
}

// Thread-safe initialization of storage system
void initialize_storage(storage_system_t *system, size_t max_records) {
    pthread_mutex_init(&system->lock, NULL);
    system->offsets = (long *)calloc(max_records, sizeof(long));
    system->keys = (int *)calloc(max_records, sizeof(int));
    system->records = (record_t *)calloc(max_records, sizeof(record_t));
    system->num_records = 0;
    system->total_value = 0;

    for (size_t i = 0; i < max_records; ++i) {
        system->offsets[i] = i * sizeof(record_t);
        system->keys[i] = rand() % KEY_RANGE;
        pthread_mutex_lock(&system->lock);

        // Adjust the range based on the total_value
        int value_range = (int)(KEY_RANGE - (float)system->total_value / (i + 1));
        if (value_range < 1) value_range = 1;

        record_t new_record;
        new_record.value = rand() % value_range;

        // Check for overflow
        if ((unsigned long)system->total_value + (unsigned int)new_record.value 
            < system->total_value || 
            (unsigned long)system->total_value - (unsigned int)new_record.value 
            > (unsigned long)(INT_MAX - new_record.value)) {
            printf("Overflow detected. Skipping record initialization.\n");
        } else {
            system->records[i] = new_record;
            system->num_records++;
            system->total_value += new_record.value;
        }

        pthread_mutex_unlock(&system->lock);
    }
}

// Serialize storage state to a file
void serialize_state(storage_system_t *system, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file) {
        pthread_mutex_lock(&system->lock);
        fwrite(&system->num_records, sizeof(size_t), 1, file);
        fwrite(system->offsets, sizeof(long), system->num_records, file);
        fwrite(system->keys, sizeof(int), system->num_records, file);
        fwrite(system->records, sizeof(record_t), system->num_records, file);
        pthread_mutex_unlock(&system->lock);
        fclose(file);
    }
}

// Simulated service monitor
void *monitor_service(void *arg) {
    storage_system_t *system = (storage_system_t *)arg;
    int running = 1;
    size_t messages_processed = 0;

    while (running) {
        sleep(5); // Simulate operational monitoring interval

        pthread_mutex_lock(&system->lock);

        if (messages_processed > 100) { // Example stop condition
            printf("Stopping service.\n");
            running = 0;

            const char *broker_message = "Service stopped. Duration: X, Messages processed: ";
            char message_buffer[128];
            snprintf(message_buffer, sizeof(message_buffer), "%s%zu", broker_message, messages_processed);

            int retry_count = 0;
            while (retry_count < 3) {
                // Simulate sending to a message broker
                printf("Sending to broker: %s\n", message_buffer);

                if (rand() % 2 == 0) { // Random failure simulation
                    printf("Broker failed. Retrying...\n");
                    retry_count++;
                } else {
                    break;
                }
            }

            if (retry_count == 3) {
                printf("Failed to send after retries.\n");
            }
        }

        pthread_mutex_unlock(&system->lock);
    }

    return NULL;
}

int main() {
    storage_system_t system;

    initialize_storage(&system, MAX_RECORDS);

    pthread_t monitor_thread;
    pthread_create(&monitor_thread, NULL, monitor_service, &system);

    // Simulate running service
    sleep(20); 

    serialize_state(&system, "storage_state.bin");

    pthread_cancel(monitor_thread);
    pthread_join(monitor_thread, NULL);

    free(system.offsets);
    free(system.keys);
    free(system.records);
    pthread_mutex_destroy(&system.lock);

    return 0;
}
