#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_TASKS 1000

typedef struct {
    char* job_id;
    int execution_priority;
    void* task_data;
} Task;

typedef struct {
    Task** tasks;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
    int max_size;
} TaskQueue;

typedef struct {
    int value;
    time_t timestamp;
} JobMetadata;

TaskQueue* initialize_task_queue(int max_size) {
    TaskQueue* queue = (TaskQueue*)malloc(sizeof(TaskQueue));
    if (!queue) return NULL;

    queue->tasks = (Task**)calloc(max_size, sizeof(Task*));
    if (!queue->tasks) {
        free(queue);
        return NULL;
    }

    queue->count = 0;
    queue->capacity = max_size;
    pthread_mutex_init(&queue->lock, NULL);
    pthread_cond_init(&queue->cond_var, NULL);
    queue->max_size = max_size;

    return queue;
}

void log_task_addition(Task* task) {
    time_t now = time(NULL);
    printf("Task added at %s: Job ID=%s, Priority=%d\n", ctime(&now), task->job_id, task->execution_priority);
}

int validate_task(const Task* task) {
    return task && task->job_id && task->task_data;
}

void add_task(TaskQueue* queue, Task* new_task) {
    pthread_mutex_lock(&queue->lock);

    while (queue->count >= queue->max_size) {
        pthread_cond_wait(&queue->cond_var, &queue->lock);
    }

    if (validate_task(new_task)) {
        queue->tasks[queue->count++] = new_task;
        log_task_addition(new_task);
        pthread_cond_signal(&queue->cond_var);
    } else {
        printf("Invalid task data\n");
    }

    pthread_mutex_unlock(&queue->lock);
}

void* dispose_tasks(void* arg) {
    TaskQueue* queue = (TaskQueue*)arg;

    while (1) {
        sleep(5);

        pthread_mutex_lock(&queue->lock);
        if (queue->count > queue->max_size / 2) {
            for (size_t i = 0; i < queue->count / 2; ++i) {
                free(queue->tasks[i]->job_id);
                free(queue->tasks[i]);
                queue->tasks[i] = NULL;
            }
            memmove(queue->tasks, queue->tasks + queue->count / 2, (queue->count - queue->count / 2) * sizeof(Task*));
            queue->count -= queue->count / 2;
        }
        pthread_mutex_unlock(&queue->lock);
    }

    return NULL;
}

int get_priority_from_job_id(const char* job_id) {
    int priority = 0;
    for (size_t i = 0; job_id[i] != '\0'; ++i) {
        if (job_id[i] >= 'A' && job_id[i] <= 'Z') priority += 3;
        else if (job_id[i] >= 'a' && job_id[i] <= 'z') priority += 2;
        else if (job_id[i] >= '0' && job_id[i] <= '9') priority += 1;
        else priority -= 1;
    }
    return priority;
}

void process_input(TaskQueue* queue) {
    int id, retries = 3;
    char job_id[256];
    time_t timestamp;

    while (scanf("%d %s %ld", &id, job_id, &timestamp) == 3) {
        Task* task = (Task*)malloc(sizeof(Task));
        if (!task) continue;

        task->job_id = strdup(job_id);
        task->execution_priority = get_priority_from_job_id(job_id);
        task->task_data = NULL; // Placeholder for actual data

        add_task(queue, task);
    }
}

void* monitor_queue_health(void* arg) {
    TaskQueue* queue = (TaskQueue*)arg;

    while (1) {
        sleep(10);

        pthread_mutex_lock(&queue->lock);
        printf("Current queue size: %zu\n", queue->count);
        // Additional metrics can be logged here
        pthread_mutex_unlock(&queue->lock);
    }

    return NULL;
}

int find_largest_id(JobMetadata* jobs, int count) {
    if (count <= 0) return -1;

    int largest_id = jobs[0].value;
    for (int i = 1; i < count; ++i) {
        if (jobs[i].value > largest_id) {
            largest_id = jobs[i].value;
        }
    }

    return largest_id;
}

void print_largest_id(JobMetadata* jobs, int count) {
    int largest_id = find_largest_id(jobs, count);
    printf("Largest ID: %d\n", largest_id);
}

int main() {
    TaskQueue* queue = initialize_task_queue(MAX_TASKS);

    pthread_t dispose_thread;
    pthread_create(&dispose_thread, NULL, dispose_tasks, queue);

    pthread_t monitor_thread;
    pthread_create(&monitor_thread, NULL, monitor_queue_health, queue);

    process_input(queue);

    pthread_join(dispose_thread, NULL);
    pthread_join(monitor_thread, NULL);

    for (size_t i = 0; i < queue->count; ++i) {
        free(queue->tasks[i]->job_id);
        free(queue->tasks[i]);
    }
    free(queue->tasks);
    pthread_mutex_destroy(&queue->lock);
    pthread_cond_destroy(&queue->cond_var);
    free(queue);

    return 0;
}
