#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
    int* key_ptr;
} record_t;

typedef struct {
    time_t timestamp;
    unsigned long usage_count;
} metadata_t;

typedef struct {
    size_t total_size;
    void* block;
    pthread_mutex_t lock;
    pthread_cond_t cond;

    long* offsets;
    int* keys;
    record_t* records;
    metadata_t* metadatas;

    size_t offset_capacity, key_capacity, record_capacity, metadata_capacity;

    unsigned long total_value_sum;
    double average_value;
} MemoryPool;

void initialize_pool(MemoryPool* pool, size_t initial_size) {
    pthread_mutex_init(&pool->lock, NULL);
    pthread_cond_init(&pool->cond, NULL);

    pool->total_size = initial_size * (sizeof(long) + sizeof(int) + sizeof(record_t) + sizeof(metadata_t));
    pool->block = malloc(pool->total_size);
    if (!pool->block) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    pool->offset_capacity = initial_size;
    pool->key_capacity = initial_size;
    pool->record_capacity = initial_size;
    pool->metadata_capacity = initial_size;

    pool->offsets = (long*)pool->block;
    pool->keys = (int*)(pool->offsets + pool->offset_capacity);
    pool->records = (record_t*)(pool->keys + pool->key_capacity);
    pool->metadatas = (metadata_t*)(pool->records + pool->record_capacity);

    pool->total_value_sum = 0;
    pool->average_value = 0.0;

    for (size_t i = 0; i < initial_size; ++i) {
        pool->keys[i] = rand() % (int)(pool->average_value + 1);
        pool->records[i].value = rand() % (int)(pool->average_value + 1);
        pool->records[i].key_ptr = &pool->keys[i];
        pool->metadatas[i].timestamp = time(NULL);
        pool->metadatas[i].usage_count = 0;
    }

    for (size_t i = 0; i < initial_size; ++i) {
        if ((unsigned long)(pool->total_value_sum + pool->records[i].value) > UINT_MAX) {
            pool->total_value_sum = UINT_MAX;
            break;
        }
        pool->total_value_sum += pool->records[i].value;
    }

    if (initial_size != 0 && pool->total_value_sum / initial_size < UINT_MAX) {
        pool->average_value = (double)pool->total_value_sum / initial_size;
    } else {
        pool->average_value = 1.0; // Fallback to prevent division by zero or overflow
    }
}

void resize_pool(MemoryPool* pool, size_t new_size) {
    pthread_mutex_lock(&pool->lock);

    while (new_size > pool->offset_capacity) {
        size_t next_capacity = pool->total_size * 2;
        if (next_capacity < new_size) {
            next_capacity = new_size;
        }

        void* new_block = realloc(pool->block, next_capacity);
        if (!new_block) {
            perror("Failed to resize memory");
            pthread_mutex_unlock(&pool->lock);
            exit(EXIT_FAILURE);
        }

        pool->total_size = next_capacity;
        pool->offsets = (long*)new_block;
        pool->keys = (int*)(pool->offsets + pool->offset_capacity);
        pool->records = (record_t*)(pool->keys + pool->key_capacity);
        pool->metadatas = (metadata_t*)(pool->records + pool->record_capacity);

        pthread_mutex_unlock(&pool->lock);

        pthread_cond_signal(&pool->cond); // Signal that resizing is done
        pthread_mutex_lock(&pool->lock);  // Re-lock for further operations
    }

    pool->offset_capacity = new_size;
    pool->key_capacity = new_size;
    pool->record_capacity = new_size;
    pool->metadata_capacity = new_size;

    pthread_mutex_unlock(&pool->lock);
}

void free_pool(MemoryPool* pool) {
    pthread_mutex_destroy(&pool->lock);
    pthread_cond_destroy(&pool->cond);

    if (pool->block) {
        free(pool->block);
        pool->block = NULL;
    }
}

int main() {
    MemoryPool pool;

    initialize_pool(&pool, 10);

    resize_pool(&pool, 20); // Example of resizing

    free_pool(&pool);
    return 0;
}
