typedef struct {
    unsigned int RNTI;
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int CRC_INDICATION_REL8_TAG;
    unsigned int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Mutex for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int valid_rx_ue_information_tags[VALID_TAGS] = {1, 2, 3, 4, 5}; // Example valid tags

void log_event(const char *message) {
    printf("%s\n", message);
}

unsigned int generate_crcflag() {
    return rand() % 2; // Randomly set CRCFLAG to 0 or 1
}

int is_valid_tag(unsigned int tag) {
    for (int i = 0; i < VALID_TAGS; ++i) {
        if (valid_rx_ue_information_tags[i] == tag)
            return 1;
    }
    return 0;
}

unsigned int find_largest(const unsigned int *array, size_t n) {
    unsigned int largest = array[0];
    for (size_t i = 1; i < n; ++i) {
        if (array[i] > largest)
            largest = array[i];
    }
    return largest;
}

unsigned int read_integers(NFAPI_CRC_INDICATION_PDU_T **pdus) {
    size_t count = 0, capacity = 10000; // Initial capacity
    *pdus = malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*pdus) {
        log_event("Memory allocation failed");
        return 0;
    }

    unsigned int number;
    while (count < MAX_ELEMENTS && scanf("%u", &number) == 1) {
        if (pthread_mutex_lock(&lock)) {
            log_event("Mutex lock error");
            free(*pdus);
            return 0;
        }

        // Ensure uniqueness of RNTI
        unsigned int rnti = count + 1;

        // Assign a valid tag and CRC flag
        unsigned int rx_ue_information_tag = number % VALID_TAGS + 1; // Simple way to map input to valid tags
        if (!is_valid_tag(rx_ue_information_tag)) {
            log_event("Invalid RX_UE_INFORMATION_TAG");
            pthread_mutex_unlock(&lock);
            free(*pdus);
            return 0;
        }

        (*pdus)[count].RNTI = rnti;
        (*pdus)[count].RX_UE_INFORMATION_TAG = rx_ue_information_tag;
        (*pdus)[count].CRC_INDICATION_REL8_TAG = number; // Example mapping
        (*pdus)[count].CRCFLAG = generate_crcflag();

        count++;

        if (pthread_mutex_unlock(&lock)) {
            log_event("Mutex unlock error");
            free(*pdus);
            return 0;
        }
    }

    if (count == 0) {
        free(*pdus);
        *pdus = NULL;
        log_event("No valid NFAPI_CRC_INDICATION_PDU_T objects found");
        return 0;
    }

    // Resize the memory block to fit exactly what we need
    *pdus = realloc(*pdus, count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*pdus) {
        log_event("Memory reallocation failed");
        return 0;
    }

    unsigned int largest_integer = find_largest(&((*pdus)[0].CRC_INDICATION_REL8_TAG), count);
    return largest_integer;
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T *pdus = NULL;

    unsigned int largest = read_integers(&pdus);

    if (largest) {
        printf("Largest integer: %u\n", largest);
    } else {
        printf("No valid input or an error occurred.\n");
    }

    free(pdus);

    return 0;
}
