FileTransferSession* create_file_transfer_session() {
    FileTransferSession* session = malloc(sizeof(FileTransferSession));
    if (!session) return NULL;

    pthread_mutex_init(&session->lock, NULL);
    pthread_cond_init(&session->cond_var, NULL);

    session->ctx = SSL_CTX_new(TLS_client_method());
    if (!session->ctx) {
        free(session);
        return NULL;
    }

    session->ssl = NULL; // Assume ssl is established later
    session->records = malloc(sizeof(TransferRecord*) * 10); // Initial capacity
    if (!session->records) {
        SSL_CTX_free(session->ctx);
        free(session);
        return NULL;
    }
    session->recordCount = 0;

    return session;
}

void destroy_file_transfer_session(FileTransferSession* session) {
    if (!session) return;

    for (int i = 0; i < session->recordCount; ++i) {
        if (session->records[i]) free(session->records[i]->fileDataSegment);
        free(session->records[i]);
    }
    free(session->records);

    SSL_shutdown(session->ssl);
    SSL_free(session->ssl);
    SSL_CTX_free(session->ctx);

    pthread_mutex_destroy(&session->lock);
    pthread_cond_destroy(&session->cond_var);
    free(session);
}

int manage_file_transfer_session(FileTransferSession* session) {
