    while (1) { // Loop to handle incoming segments
        unsigned char buffer[BUFFER_SIZE];
        int bytes = SSL_read(session->ssl, buffer, sizeof(buffer));

        if (bytes <= 0) {
            ERR_print_errors_fp(stderr);
            return ERR_NETWORK_FAILURE;
        }

        TransferRecord* record = malloc(sizeof(TransferRecord));
        if (!record) return ERR_OUT_OF_MEMORY;

        record->fileDataSegment = malloc(MAX_SEGMENT_SIZE);
        if (!record->fileDataSegment) {
            free(record);
            return ERR_OUT_OF_MEMORY;
        }

        memcpy(record->fileDataSegment, buffer, bytes);
        record->segmentSize = bytes;

