        pthread_mutex_lock(&session->lock);

        // Add the new TransferRecord to a sorted list based on sessionId or timestamp
        session->records[session->recordCount++] = record;

        if (session->recordCount >= 10) {
            // Resize records array if needed, ensuring thread safety
            int newSize = session->recordCount * 2;
            TransferRecord** newRecords = realloc(session->records, sizeof(TransferRecord*) * newSize);
            if (!newRecords) {
                free(record->fileDataSegment);
                free(record);
                pthread_mutex_unlock(&session->lock);
                return ERR_OUT_OF_MEMORY;
            }
            session->records = newRecords;
        }

        pthread_cond_signal(&session->cond_var); // Signal any waiting threads
        pthread_mutex_unlock(&session->lock);

        // Process records, handle network latency, packet loss etc.

