#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

#define MAX_STRING_LENGTH 512
#define FLOAT_RANGE_MAX 1000.0
#define FLOAT_RANGE_MIN -1000.0
#define MEMORY_LIMIT (1 * 1024 * 1024) // 1MB

typedef struct {
    float value;
    short integer;
} data_packet;

typedef struct {
    int seconds_since_epoch;
    char timezone[6];
} timestamp;

typedef struct Node {
    void* data;
    size_t size;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    uint64_t allocation_count;
    uint64_t deallocation_count;
} MemoryManager;

MemoryManager managers[4];

void initialize_manager(MemoryManager *manager) {
    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    manager->allocation_count = 0;
    manager->deallocation_count = 0;
}

void* thread_safe_allocate(size_t size) {
    static uint64_t total_memory_used = 0;
    if (total_memory_used + size > MEMORY_LIMIT) return NULL;

    void* memory = malloc(size);
    if (!memory) return NULL;

    pthread_mutex_lock(&managers[0].lock); // Using the same lock for simplicity, can be separated
    total_memory_used += size;
    pthread_mutex_unlock(&managers[0].lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = memory;
    new_node->size = size;
    new_node->next = NULL;

    // Add to the linked list for tracking
    pthread_mutex_lock(&managers[1].lock);
    new_node->next = managers[1].head;
    managers[1].head = new_node;
    managers[1].allocation_count++;
    pthread_mutex_unlock(&managers[1].lock);

    return memory;
}

void thread_safe_deallocate(void* data, size_t size) {
    Node** current = &managers[1].head;

    while (*current) {
        if ((*current)->data == data) {
            pthread_mutex_lock(&managers[2].lock);
            *current = (*current)->next;
            managers[2].deallocation_count++;
            pthread_mutex_unlock(&managers[2].lock);

            free(data);
            free(*current);

            pthread_mutex_lock(&managers[0].lock);
            total_memory_used -= size;
            pthread_mutex_unlock(&managers[0].lock);

            return;
        }
        current = &(*current)->next;
    }
}

void* allocate_large_doubles(size_t count) {
    double* array = (double*)thread_safe_allocate(count * sizeof(double));
    if (!array) {
        fprintf(stderr, "Allocation failed for large doubles\n");
        cleanup_memory();
        exit(EXIT_FAILURE);
    }
    return array;
}

char* allocate_string() {
    char* string = (char*)thread_safe_allocate(MAX_STRING_LENGTH);
    if (!string) {
        fprintf(stderr, "Allocation failed for strings\n");
        cleanup_memory();
        exit(EXIT_FAILURE);
    }
    return string;
}

data_packet* allocate_data_packets(size_t count) {
    data_packet* packets = (data_packet*)thread_safe_allocate(count * sizeof(data_packet));
    if (!packets) {
        fprintf(stderr, "Allocation failed for data packets\n");
        cleanup_memory();
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));
    for (size_t i = 0; i < count; ++i) {
        packets[i].value = ((double)rand() / RAND_MAX) * (FLOAT_RANGE_MAX - FLOAT_RANGE_MIN) + FLOAT_RANGE_MIN;
        // Hash function example: simple XOR with a fixed prime number
        const char* sample_string = "example";
        packets[i].integer = 0;
        for (int j = 0; sample_string[j] != '\0'; ++j) {
            packets[i].integer ^= sample_string[j];
        }
    }

    return packets;
}

timestamp* allocate_timestamps(size_t count) {
    timestamp* timestamps = (timestamp*)thread_safe_allocate(count * sizeof(timestamp));
    if (!timestamps) {
        fprintf(stderr, "Allocation failed for timestamps\n");
        cleanup_memory();
        exit(EXIT_FAILURE);
    }

    time_t now = time(NULL);
    struct tm* local_time = localtime(&now);

    for (size_t i = 0; i < count; ++i) {
        timestamps[i].seconds_since_epoch = (int)(now + i * 60); // Example: increment by minute
        strftime(timestamps[i].timezone, sizeof(timestamps[i].timezone), "%Z", local_time);
    }

    return timestamps;
}

void cleanup_memory() {
    for (int i = 0; i < 4; ++i) {
        pthread_mutex_lock(&managers[i].lock);
        Node* current = managers[i].head;
        while (current != NULL) {
            Node* next = current->next;
            free(current->data);
            free(current);
            current = next;
        }
        managers[i].head = NULL;
        pthread_mutex_unlock(&managers[i].lock);
    }

    // Reset global memory usage
    pthread_mutex_lock(&managers[0].lock);
    total_memory_used = 0;
    pthread_mutex_unlock(&managers[0].lock);
}

void log_allocation(const char* message) {
    static FILE* log_file = NULL;
    if (!log_file) {
        log_file = fopen("allocation.log", "a");
    }
    fprintf(log_file, "%s\n", message);
    fflush(log_file);
}

int main() {
    initialize_manager(&managers[0]);
    initialize_manager(&managers[1]);
    initialize_manager(&managers[2]);

    double* doubles = allocate_large_doubles(1000);
    char* string = allocate_string();
    data_packet* packets = allocate_data_packets(500);
    timestamp* timestamps = allocate_timestamps(200);

    log_allocation("Allocations completed successfully.");

    // Simulate usage
    sleep(5);

    cleanup_memory();

    if (managers[1].allocation_count != managers[2].deallocation_count) {
        fprintf(stderr, "Memory leak detected!\n");
        exit(EXIT_FAILURE);
    }

    fclose(log_file); // Close log file

    printf("All operations completed successfully.\n");

    return 0;
}
