#include <pthread.h>

#define MAX_STRING_LENGTH 256
#define FLOAT_MIN -1000.0f
#define FLOAT_MAX 1000.0f
#define VERSION_NUMBER 1

typedef struct {
    float value;
    short int id;
} data_packet;

typedef struct {
    time_t timestamp;
    int version_number;
} metadata;

void initialize_memory(size_t num_packets, double **large_numbers, char ***strings,
                       data_packet ***packets, metadata ***meta_info);

double* allocate_large_double_array(size_t size) {
    return (double*)aligned_alloc(64, sizeof(double) * size);
}

char** allocate_string_array(size_t size) {
    char **array = (char**)malloc(sizeof(char*) * size);
    for (size_t i = 0; i < size; ++i) {
        array[i] = (char*)aligned_alloc(64, MAX_STRING_LENGTH);
    }
    return array;
}

data_packet* allocate_data_packet_array(size_t size) {
    return (data_packet*)aligned_alloc(64, sizeof(data_packet) * size);
}

metadata* allocate_metadata_array(size_t size) {
    return (metadata*)aligned_alloc(64, sizeof(metadata) * size);
}

void fill_data_packets(size_t num_packets, char **strings,
                       data_packet *packets, metadata *meta_info) {
    for (size_t i = 0; i < num_packets; ++i) {
        packets[i].value = FLOAT_MIN + ((double)rand() / RAND_MAX) * (FLOAT_MAX - FLOAT_MIN);
        packets[i].id = rand() % 10000; // Example hash

        meta_info[i].timestamp = time(NULL);
        meta_info[i].version_number = VERSION_NUMBER;
    }
}

void initialize_memory(size_t num_packets, double **large_numbers,
                       char ***strings, data_packet ***packets, metadata ***meta_info) {
    if (!large_numbers || !strings || !packets || !meta_info) return;

    *large_numbers = allocate_large_double_array(num_packets);
    if (*large_numbers == NULL) exit(EXIT_FAILURE);

    *strings = allocate_string_array(num_packets);
    for (size_t i = 0; i < num_packets; ++i) {
        if ((*strings)[i] == NULL) exit(EXIT_FAILURE);
    }

    *packets = allocate_data_packet_array(num_packets);
    if (*packets == NULL) exit(EXIT_FAILURE);

    *meta_info = allocate_metadata_array(num_packets);
    if (*meta_info == NULL) exit(EXIT_FAILURE);

    fill_data_packets(num_packets, *strings, *packets, *meta_info);
}

int main() {
    size_t num_packets = 1000;
    double *large_numbers;
    char **strings;
    data_packet *packets;
    metadata *meta_info;

    initialize_memory(num_packets, &large_numbers, &strings, &packets, &meta_info);

    // Clean up
    free(large_numbers);
    for (size_t i = 0; i < num_packets; ++i) {
        free(strings[i]);
    }
    free(strings);
    free(packets);
    free(meta_info);

    return 0;
}
