    use tokio::test;

    #[tokio::test]
    async fn test_valid_user() -> Result<()> {
        init_user_profile("validuser", "USER_HOME_DIR").await?;
        Ok(())
    }

    #[tokio::test]
    async fn test_invalid_user() -> Result<()> {
        assert!(init_user_profile("invalid user!", "USER_HOME_DIR").await.is_err());
        Ok(())
    }

    #[tokio::test]
    async fn test_concurrent_profiles_creation() -> Result<()> {
        let handles: Vec<_> = (0..10)
            .map(|_| tokio::spawn(init_user_profile("user1", "USER_HOME_DIR")))
            .collect();

        for handle in handles {
            handle.await??;
        }

        Ok(())
    }
}

// Main function with a basic logging setup
