['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    int size;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int initialized_count;
    long total_value;
} DataStructures;

DataStructures* initialize_data_structures(int initial_size) {
    DataStructures *ds = (DataStructures*)malloc(sizeof(DataStructures));
    if (!ds) return NULL;

    ds->offsets = (long*)calloc(initial_size, sizeof(long));
    ds->keys = (int*)calloc(initial_size, sizeof(int));
    ds->records = (record*)calloc(initial_size, sizeof(record));
    if (!ds->offsets || !ds->keys || !ds->records) {
        free(ds->offsets);
        free(ds->keys);
        free(ds->records);
        free(ds);
        return NULL;
    }

    ds->size = initial_size;
    pthread_mutex_init(&ds->mutex, NULL);
    pthread_cond_init(&ds->cond, NULL);
    ds->initialized_count = 0;
    ds->total_value = 0;

    // Seed the random number generator
    srand(time(NULL));

    return ds;
}

void resize_data_structures(DataStructures *ds, int new_size) {
    pthread_mutex_lock(&ds->mutex);

    long *new_offsets = (long*)realloc(ds->offsets, new_size * sizeof(long));
    int *new_keys = (int*)realloc(ds->keys, new_size * sizeof(int));
    record *new_records = (record*)realloc(ds->records, new_size * sizeof(record));

    if (!new_offsets || !new_keys || !new_records) {
        pthread_mutex_unlock(&ds->mutex);
        return; // Handle error in real scenario
    }

    ds->offsets = new_offsets;
    ds->keys = new_keys;
    ds->records = new_records;
    ds->size = new_size;

    pthread_mutex_unlock(&ds->mutex);
}

void update_record(DataStructures *ds, int index) {
    if (index < 0 || index >= ds->size) return; // Index out of bounds

    pthread_mutex_lock(&ds->mutex);

    while (ds->initialized_count >= ds->size) {
        pthread_cond_wait(&ds->cond, &ds->mutex);
    }

    int range = (int)(ds->total_value / (ds->initialized_count + 1)) + 1;
    if (range < 1) range = 10; // Ensure a minimum range

    ds->records[index].value = rand() % range;

    long offset = index * sizeof(int);
    ds->offsets[index] = offset;
    ds->keys[index] = index; // Example key assignment, can be customized
    ds->total_value += ds->records[index].value;
    ds->initialized_count++;

    pthread_cond_signal(&ds->cond);

    pthread_mutex_unlock(&ds->mutex);
}

void free_data_structures(DataStructures *ds) {
    if (ds) {
        free(ds->offsets);
        free(ds->keys);
        free(ds->records);
        pthread_mutex_destroy(&ds->mutex);
        pthread_cond_destroy(&ds->cond);
        free(ds);
    }
}

// Example usage
void* thread_function(void* arg) {
    DataStructures *ds = (DataStructures*)arg;
    for (int i = 0; i < ds->size; ++i) {
        update_record(ds, i);
    }
    return NULL;
}

int main() {
    int initial_size = 100;
    DataStructures *ds = initialize_data_structures(initial_size);

    if (!ds) {
        fprintf(stderr, "Failed to initialize data structures\n");
        return EXIT_FAILURE;
    }

    pthread_t threads[4];
    for (int i = 0; i < 4; ++i) {
        pthread_create(&threads[i], NULL, thread_function, ds);
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    free_data_structures(ds);

    return EXIT_SUCCESS;
}
```']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_CAPACITY 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int crc_status_flag; // Example of a flag field
} PDU_T;

typedef enum { LOG_ERROR, LOG_ALLOCATE, LOG_DEALLOCATE } LogType;

typedef struct MemoryBlock {
    PDU_T *pdu;
    struct MemoryBlock *next;
} MemoryBlock;

typedef struct {
    MemoryBlock *free_list;
    pthread_mutex_t lock;
    size_t max_capacity;
} MemoryPool;

void log_event(LogType type, const char* message) {
    time_t now = time(NULL);
    printf("[%s] [%s] %s\n", ctime(&now), (type == LOG_ERROR ? "ERROR" : 
           (type == LOG_ALLOCATE ? "ALLOCATE" : "DEALLOCATE")), message);
}

MemoryPool *create_memory_pool(size_t max_capacity) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->free_list = NULL;
    pthread_mutex_init(&pool->lock, NULL);
    pool->max_capacity = max_capacity;

    // Initialize the free list
    for (size_t i = 0; i < max_capacity; ++i) {
        MemoryBlock *block = malloc(sizeof(MemoryBlock));
        if (!block) break;

        block->pdu = malloc(sizeof(PDU_T));
        if (!block->pdu) {
            free(block);
            break;
        }

        block->next = pool->free_list;
        pool->free_list = block;
    }

    return pool;
}

PDU_T *allocate_pdu(MemoryPool *pool, const char* caller_context) {
    pthread_mutex_lock(&pool->lock);

    if (pool->free_list == NULL) {
        log_event(LOG_ERROR, "Memory pool overflow");
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Pool is full
    }

    MemoryBlock *block = pool->free_list;
    pool->free_list = block->next;

    pthread_mutex_unlock(&pool->lock);

    log_event(LOG_ALLOCATE, caller_context);

    return block->pdu;
}

void deallocate_pdu(MemoryPool *pool, PDU_T *pdu, const char* caller_context) {
    if (!pdu) return;

    MemoryBlock *block = malloc(sizeof(MemoryBlock));
    if (!block) {
        log_event(LOG_ERROR, "Failed to allocate memory block for deallocation");
        return;
    }

    block->pdu = pdu;

    pthread_mutex_lock(&pool->lock);

    block->next = pool->free_list;
    pool->free_list = block;

    pthread_mutex_unlock(&pool->lock);

    log_event(LOG_DEALLOCATE, caller_context);
}

void destroy_memory_pool(MemoryPool *pool) {
    MemoryBlock *block = pool->free_list;

    while (block) {
        MemoryBlock *next = block->next;
        free(block->pdu);
        free(block);
        block = next;
    }

    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

int main() {
    MemoryPool *pool = create_memory_pool(MAX_CAPACITY);

    if (!pool) return 1;

    const char* context = "Main thread allocation";
    PDU_T *pdu = allocate_pdu(pool, context);

    if (pdu) {
        pdu->RX_UE_INFORMATION_TAG = 123;
        deallocate_pdu(pool, pdu, context);
    }

    destroy_memory_pool(pool);

    return 0;
}
```

This code snippet demonstrates how to create a memory pool for managing `PDU_T` structures with thread-safety and logging. It initializes the memory blocks in advance to minimize fragmentation and uses mutex locks to ensure safe access from multiple threads.']

