#include <stdbool.h>
#include <time.h>

#define MAX_POOL_SIZE 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    pthread_mutex_t lock;
} Pool;

Pool pool = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

bool is_valid_data(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    // Add validation logic here
    return RX_UE_INFORMATION_TAG >= 0 && RNTI > 0 && CRC_INDICATION_REL8_TAG >= 0;
}

void log_event(const char* event) {
    printf("%s\n", event);
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    if (!is_valid_data(RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG)) {
        log_event("Invalid data");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        log_event("Memory allocation failed");
        return NULL;
    }

    pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu->RNTI = RNTI;
    pdu->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    pdu->CRCFLAG = rand() % 2 == 0;

    log_event("PDU created");
    return pdu;
}

void free_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu) {
        free(pdu);
        log_event("PDU freed");
    }
}

bool add_to_pool(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&pool.lock);

    if (pool.count >= MAX_POOL_SIZE) {
        log_event("Pool limit reached");
        pthread_mutex_unlock(&pool.lock);
        return false;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = create_pdu(RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG);
    if (!pdu) {
        pthread_mutex_unlock(&pool.lock);
        return false;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        free_pdu(pdu);
        pthread_mutex_unlock(&pool.lock);
        log_event("Memory allocation failed for node");
        return false;
    }

    new_node->data = *pdu;
    new_node->next = pool.head;
    pool.head = new_node;
    pool.count++;

    pthread_mutex_unlock(&pool.lock);
    log_event("PDU added to pool");
    return true;
}

bool remove_from_pool() {
    if (!pool.head) {
        log_event("Pool is empty");
        return false;
    }

    pthread_mutex_lock(&pool.lock);

    Node* node_to_remove = pool.head;
    pool.head = node_to_remove->next;
    free_pdu(&node_to_remove->data);
    free(node_to_remove);
    pool.count--;

    pthread_mutex_unlock(&pool.lock);
    log_event("PDU removed from pool");
    return true;
}

void initialize_pool() {
    srand(time(NULL));
    pool.head = NULL;
    pool.count = 0;
}

void cleanup_pool() {
    while (remove_from_pool());
    pthread_mutex_destroy(&pool.lock);
    log_event("Pool cleaned up");
}

int main() {
    initialize_pool();

    // Example usage
    add_to_pool(1, 100, 200);
    remove_from_pool();

    cleanup_pool();
    return 0;
}
```

### Key Points:
- **Concurrency Management**: Uses `pthread_mutex_t` for thread-safe access.
- **Resource Constraints**: Limits the pool size to `MAX_POOL_SIZE`.
- **Memory Allocation**: Dynamically allocates and frees memory, using a linked list as a simple memory pool.
- **Data Validation**: Validates data before adding it to the pool.
- **Logging**: Logs events for debugging and monitoring.
- **Scalability and Maintainability**: Modular design allows easy extension and maintenance.

This implementation provides a basic framework that can be expanded upon based on specific requirements or optimizations.']

