    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NetworkPacket *new_packets = realloc(array->packets, new_capacity * sizeof(NetworkPacket));
        if (!new_packets) {
