            exit(EXIT_FAILURE);
        }
        array->packets = new_packets;
        array->capacity = new_capacity;
    }

    packet.Checksum = calculate_checksum(packet);
    array->packets[array->count++] = packet;

    pthread_mutex_unlock(&array->lock);
