#define MAX_LOG_LEVEL 3

typedef struct {
    long offset;
    int key;
    int value;
} record;

typedef struct {
    record *data;
    size_t size;
    size_t capacity;
} RecordList;

// Function prototypes
RecordList* create_record_list(size_t initial_capacity);
void free_record_list(RecordList *list, int free_data);
int resize_record_list(RecordList *list, size_t new_capacity);
void log_message(int level, const char *message);
int populate_records(RecordList *list, int num_records, int min_value, int max_value, int thread_safe);
void serialize_to_file(const RecordList *list, const char *filename);
int deserialize_from_file(RecordList *list, const char *filename);
void test_record_list();

// Function implementations

RecordList* create_record_list(size_t initial_capacity) {
    RecordList *list = (RecordList *)malloc(sizeof(RecordList));
    if (!list) {
        log_message(1, "Memory allocation failed for record list.");
        return NULL;
    }
    list->data = (record *)malloc(initial_capacity * sizeof(record));
    if (!list->data) {
        free(list);
        log_message(1, "Memory allocation failed for records.");
        return NULL;
    }
    list->size = 0;
    list->capacity = initial_capacity;
    return list;
}

void free_record_list(RecordList *list, int free_data) {
    if (free_data && list->data)
        free(list->data);
    free(list);
}

int resize_record_list(RecordList *list, size_t new_capacity) {
    record *new_data = (record *)realloc(list->data, new_capacity * sizeof(record));
    if (!new_data)
        return -1;
    list->capacity = new_capacity;
    list->data = new_data;
    return 0;
}

void log_message(int level, const char *message) {
    if (level > MAX_LOG_LEVEL) return;
    time_t now = time(NULL);
    fprintf(stderr, "[%s] %s\n", ctime(&now), message);
}

int populate_records(RecordList *list, int num_records, int min_value, int max_value, int thread_safe) {
    for (size_t i = 0; i < list->capacity && i < num_records; ++i) {
        if (thread_safe)
            pthread_mutex_lock(&mutex);

        int unique = 0;
        while (!unique) {
            record *r = &list->data[list->size];
            r->offset = rand();
            r->key = rand() % max_value;
            r->value = min_value + rand() % (max_value - min_value + 1);

            for (size_t j = 0; j < list->size; ++j) {
                if (list->data[j].key == r->key) {
                    log_message(1, "Duplicate key found. Halting execution.");
                    return -1;
                }
            }
            unique = 1;

            list->size++;
        }

        if (thread_safe)
            pthread_mutex_unlock(&mutex);
    }
    return 0;
}

void serialize_to_file(const RecordList *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        log_message(1, "Failed to open file for writing.");
        return;
    }

    fwrite(&list->size, sizeof(size_t), 1, file);
    fwrite(list->data, sizeof(record), list->size, file);

    fclose(file);
}

int deserialize_from_file(RecordList *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        log_message(1, "Failed to open file for reading.");
        return -1;
    }

    size_t new_size;
    fread(&new_size, sizeof(size_t), 1, file);
    if (resize_record_list(list, new_size) == -1) {
        fclose(file);
        return -1;
    }

    fread(list->data, sizeof(record), new_size, file);
    list->size = new_size;

    fclose(file);
    return 0;
}

void test_record_list() {
    RecordList *list = create_record_list(10);
    if (!list) return;

    populate_records(list, 20, 1, 100, 0);

    serialize_to_file(list, "records.dat");

    free_record_list(list, 1);

    list = create_record_list(5);
    deserialize_from_file(list, "records.dat");

    // Verify deserialization
    for (size_t i = 0; i < list->size; ++i) {
        printf("Record %zu: Offset=%ld Key=%d Value=%d\n", i, list->data[i].offset, list->data[i].key, list->data[i].value);
    }

    free_record_list(list, 1);
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    test_record_list();

    return 0;
}
