#include "external_data_processing_module.h"

#define MAX_CRC_INDICATIONS MAX_ALLOWED_CRC_INDICATIONS

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
