pthread_mutex_t allocation_lock = PTHREAD_MUTEX_INITIALIZER;

// Memory pool management
void* memory_pool[MAX_POOL_SIZE];
size_t pool_size = 0;
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

void* allocate_from_pool(size_t size) {
    pthread_mutex_lock(&pool_lock);
    for (size_t i = 0; i < pool_size; ++i) {
        if (memory_pool[i] != NULL && strlen(memory_pool[i]) >= size) {
            void* ptr = memory_pool[i];
            memory_pool[i] = NULL;
            pthread_mutex_unlock(&pool_lock);
            return ptr;
        }
    }
    pthread_mutex_unlock(&pool_lock);

    void* ptr = malloc(size);
    if (!ptr) {
        log_error("Memory allocation failed");
        return NULL;
    }

    pthread_mutex_lock(&allocation_lock);
    if (pool_size < MAX_POOL_SIZE) {
        memory_pool[pool_size++] = ptr;
    }
    pthread_mutex_unlock(&allocation_lock);

    return ptr;
}

void deallocate_to_pool(void* ptr) {
    pthread_mutex_lock(&allocation_lock);
    for (size_t i = 0; i < pool_size; ++i) {
        if (memory_pool[i] == NULL) {
            memory_pool[i] = ptr;
            break;
        }
    }
    pthread_mutex_unlock(&allocation_lock);
}

int compare_rnti(const void* a, const void* b) {
    NFAPI_CRC_INDICATION_PDU_T* pdu_a = (NFAPI_CRC_INDICATION_PDU_T*)a;
    NFAPI_CRC_INDICATION_PDU_T* pdu_b = (NFAPI_CRC_INDICATION_PDU_T*)b;
    return pdu_a->rnti - pdu_b->rnti;
}

