    pthread_mutex_lock(&allocation_lock);
    NFAPI_CRC_INDICATION_PDU_T* array = allocate_from_pool(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        *allocated_count = 0;
        pthread_mutex_unlock(&allocation_lock);
        return NULL;
    }
    *allocated_count = N;
    pthread_mutex_unlock(&allocation_lock);

    for (size_t i = 0; i < N; ++i) {
        array[i].rx_ue_information_tag = generate_valid_rx_ue_info();
        array[i].rnti = generate_random_rnti();
        array[i].crc_indication_rel8_tag.crcflag = rand() % 2;
