```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 10000000
#define MAX_TOTAL_SIZE (1 << 30) // 1 GB

typedef struct {
    long offset;
    int key;
    int value;
} record;

typedef struct {
    record *records;
    size_t count;
    pthread_mutex_t lock; // For thread safety
} RecordList;

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

size_t calculate_total_size(size_t record_count) {
    return record_count * sizeof(record);
}

int is_key_unique(RecordList *list, int key) {
    for (size_t i = 0; i < list->count; ++i) {
        if (list->records[i].key == key) {
            return 0;
        }
    }
    return 1;
}

record* generate_records(size_t num_records, int value_range_min, int value_range_max, RecordList *list) {
    pthread_mutex_lock(&list->lock);

    if (num_records > MAX_RECORDS || calculate_total_size(num_records) > MAX_TOTAL_SIZE) {
        log_error("Exceeded maximum records or size limit.");
        pthread_mutex_unlock(&list->lock);
        return NULL;
    }

    list->records = (record *)malloc(calculate_total_size(num_records));
    if (!list->records) {
        log_error("Memory allocation failed.");
        pthread_mutex_unlock(&list->lock);
        return NULL;
    }

    list->count = 0;

    srand(time(NULL)); // Seed for random number generation

    for (size_t i = 0; i < num_records; ++i) {
        record new_record;
        new_record.offset = rand() % 1000000; // Example offset range
        do {
