        } while (!is_key_unique(list, new_record.key));

        new_record.value = (rand() % (value_range_max - value_range_min + 1)) + value_range_min;

        list->records[list->count++] = new_record;
    }

    pthread_mutex_unlock(&list->lock);
    return list->records;
}

void free_records(RecordList *list) {
