#include <stdio.h>

typedef struct {
    int value;
} record_t;

// Mutex for thread-safe operations
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void handle_openssl_error(const char *msg) {
    fprintf(stderr, "%s: %s\n", msg, ERR_reason_text(ERR_get_error()));
    exit(EXIT_FAILURE);
}

int init_crypto_operations(long **offset_array, size_t offset_count,
                           int **keys_array, size_t key_count,
                           record_t ***records_array, size_t record_count,
                           unsigned char *aes_key, unsigned char *camellia_key,
                           RSA *rsa_key) {
    // Initialize OpenSSL
    if (!RAND_status()) handle_openssl_error("Random number generator initialization failed");

    pthread_mutex_lock(&mutex);

    // Allocate and initialize offset array
    *offset_array = malloc(offset_count * sizeof(long));
    if (*offset_array == NULL) handle_openssl_error("Failed to allocate offset array");
    for (size_t i = 0; i < offset_count; ++i) {
        (*offset_array)[i] = rand() % 1000; // Example initialization
    }

    // Allocate and initialize keys array
    *keys_array = malloc(key_count * sizeof(int));
    if (*keys_array == NULL) handle_openssl_error("Failed to allocate keys array");
    for (size_t i = 0; i < key_count; ++i) {
        RAND_bytes((unsigned char*)&((*keys_array)[i]), sizeof(int)); // Example secure key generation
    }

    // Allocate and initialize records array with random values in a range
    *records_array = malloc(record_count * sizeof(record_t*));
    if (*records_array == NULL) handle_openssl_error("Failed to allocate records array");
    for (size_t i = 0; i < record_count; ++i) {
        (*records_array)[i] = malloc(sizeof(record_t));
        if ((*records_array)[i] == NULL) handle_openssl_error("Failed to allocate a record");
        RAND_bytes((unsigned char*)&((*records_array)[i]->value), sizeof(int)); // Random value in range
    }

    // Generate AES key
    if (!RAND_bytes(aes_key, AES_BLOCK_SIZE)) {
        pthread_mutex_unlock(&mutex);
        handle_openssl_error("Failed to generate AES key");
    }

    // Generate Camellia key
    if (!RAND_bytes(camellia_key, CAMELLIA_KEYSIZE) && !RAND_bytes(camellia_key, CAMELLIA128_KEYSIZE)) {
        pthread_mutex_unlock(&mutex);
        handle_openssl_error("Failed to generate Camellia key");
    }

    // Generate RSA key pair
    BIGNUM *bn = BN_new();
    if (!BN_set_word(bn, RSA_F4)) { // 65537 as the public exponent
        pthread_mutex_unlock(&mutex);
        handle_openssl_error("Failed to set RSA public exponent");
    }
    rsa_key = RSA_new();
    if (rsa_key == NULL || !RSA_generate_key_ex(rsa_key, 2048, bn, NULL)) {
        pthread_mutex_unlock(&mutex);
        handle_openssl_error("Failed to generate RSA key pair");
    }

    BN_free(bn);

    pthread_mutex_unlock(&mutex);

    return 0;
}

void cleanup(long *offset_array, size_t offset_count,
             int *keys_array, size_t key_count,
             record_t **records_array, size_t record_count,
             RSA *rsa_key) {
    pthread_mutex_lock(&mutex);

    if (offset_array != NULL) free(offset_array);
    if (keys_array != NULL) free(keys_array);

    for (size_t i = 0; i < record_count; ++i) {
        if (records_array[i] != NULL) free(records_array[i]);
    }
    if (records_array != NULL) free(records_array);

    if (rsa_key != NULL) RSA_free(rsa_key);

    pthread_mutex_unlock(&mutex);
}

int main() {
    // Example usage
    size_t offset_count = 10;
    size_t key_count = 5;
    size_t record_count = 7;

    long *offset_array = NULL;
    int *keys_array = NULL;
    record_t **records_array = NULL;

    unsigned char aes_key[AES_BLOCK_SIZE];
    unsigned char camellia_key[CAMELLIA_KEYSIZE]; // Or CAMELLIA128_KEYSIZE

    RSA *rsa_key = NULL;

    if (init_crypto_operations(&offset_array, offset_count,
                               &keys_array, key_count,
                               &records_array, record_count,
                               aes_key, camellia_key,
                               rsa_key) != 0) {
        fprintf(stderr, "Failed to initialize cryptographic operations\n");
        return EXIT_FAILURE;
    }

    // Use the initialized arrays and keys for cryptographic operations...

    cleanup(offset_array, offset_count,
            keys_array, key_count,
            records_array, record_count,
            rsa_key);

    return 0;
}
```

