    NFAPI_CRC_INDICATION_PDU_T data;
    int priority; // Lower number means higher priority
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} PriorityQueue;

static char memory_pool[MEMORY_POOL_SIZE];
static size_t current_offset = 0;
static pthread_rwlock_t rwlock = PTHREAD_RWLOCK_INITIALIZER;

void init_priority_queue(PriorityQueue* pq) {
    pq->head = NULL;
    pthread_mutex_init(&pq->lock, NULL);
}

void destroy_priority_queue(PriorityQueue* pq) {
    Node* temp;
    while (pq->head != NULL) {
        temp = pq->head;
        pq->head = pq->head->next;
        free(temp);
    }
    pthread_mutex_destroy(&pq->lock);
}

int enqueue(PriorityQueue* pq, NFAPI_CRC_INDICATION_PDU_T data, int priority) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1;

    new_node->data = data;
    new_node->priority = priority;
    new_node->next = NULL;

    pthread_mutex_lock(&pq->lock);

    if (!pq->head || pq->head->priority > priority) {
        new_node->next = pq->head;
        pq->head = new_node;
    } else {
        Node* current = pq->head;
        while (current->next && current->next->priority <= priority) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }

    pthread_mutex_unlock(&pq->lock);
    return 0;
}

int dequeue(PriorityQueue* pq, NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&pq->lock);

    if (!pq->head) {
        pthread_mutex_unlock(&pq->lock);
        return -1;
    }

    Node* temp = pq->head;
    *data = temp->data;
    pq->head = pq->head->next;

    free(temp);
    pthread_mutex_unlock(&pq->lock);

    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_dynamic_array(size_t n) {
