    pthread_rwlock_wrlock(&rwlock);

    size_t required_size = n * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (current_offset + required_size > MEMORY_POOL_SIZE) {
        pthread_rwlock_unlock(&rwlock);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array_ptr = (NFAPI_CRC_INDICATION_PDU_T*)&memory_pool[current_offset];
    current_offset += required_size;

    pthread_rwlock_unlock(&rwlock);

    for (size_t i = 0; i < n; ++i) {
        array_ptr[i].RX_UE_INFORMATION_TAG = rand() % 100;
        array_ptr[i].RNTI = rand() % 10000;
        array_ptr[i].CRC_INDICATION_REL8_TAG = rand() % 1000;
        array_ptr[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    }

    return array_ptr;
}

void free_dynamic_array(NFAPI_CRC_INDICATION_PDU_T* array_ptr, size_t n) {
    if (!array_ptr || n <= 0) return;

    pthread_rwlock_wrlock(&rwlock);
    current_offset -= n * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    pthread_rwlock_unlock(&rwlock);
