#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define INITIAL_CAPACITY 16

typedef struct Record {
    int key;
    int value;
    struct Record *next;
} Record;

typedef struct HashTable {
    Record **buckets;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock; // Mutex for thread safety
} HashTable;

HashTable* create_table(size_t initial_capacity) {
    HashTable *table = (HashTable *)malloc(sizeof(HashTable));
    table->capacity = initial_capacity;
    table->count = 0;
    table->buckets = (Record **)calloc(initial_capacity, sizeof(Record *));
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void free_table(HashTable *table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        Record *entry = table->buckets[i];
        while (entry) {
            Record *temp = entry;
            entry = entry->next;
            free(temp);
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

unsigned long hash(int key, size_t capacity) {
    return ((unsigned long)key) % capacity;
}

void resize_table(HashTable *table);

int insert_record(HashTable *table, int key, int value) {
    pthread_mutex_lock(&table->lock);

    if (table->count > table->capacity / 2) {
        resize_table(table);
    }

    unsigned long index = hash(key, table->capacity);
    Record *entry = table->buckets[index];

    while (entry) {
        if (entry->key == key) {
            entry->value = value;
            pthread_mutex_unlock(&table->lock);
            return 0; // Key already exists
        }
        entry = entry->next;
    }

    Record *new_record = (Record *)malloc(sizeof(Record));
    new_record->key = key;
    new_record->value = value;
    new_record->next = table->buckets[index];
    table->buckets[index] = new_record;

    ++table->count;

    pthread_mutex_unlock(&table->lock);
    return 1; // New record added
}

int get_record(HashTable *table, int key, int *value) {
    pthread_mutex_lock(&table->lock);

    unsigned long index = hash(key, table->capacity);
    Record *entry = table->buckets[index];

    while (entry) {
        if (entry->key == key) {
            *value = entry->value;
            pthread_mutex_unlock(&table->lock);
            return 1; // Key found
        }
        entry = entry->next;
    }

    pthread_mutex_unlock(&table->lock);
    return 0; // Key not found
}

int delete_record(HashTable *table, int key) {
    pthread_mutex_lock(&table->lock);

    unsigned long index = hash(key, table->capacity);
    Record *entry = table->buckets[index];
    Record *prev = NULL;

    while (entry) {
        if (entry->key == key) {
            if (prev) {
                prev->next = entry->next;
            } else {
                table->buckets[index] = entry->next;
            }
            free(entry);
            --table->count;

            pthread_mutex_unlock(&table->lock);
            return 1; // Key deleted
        }
        prev = entry;
        entry = entry->next;
    }

    pthread_mutex_unlock(&table->lock);
    return 0; // Key not found
}

void resize_table(HashTable *table) {
    size_t new_capacity = table->capacity * 2;
    Record **new_buckets = (Record **)calloc(new_capacity, sizeof(Record *));

    for (size_t i = 0; i < table->capacity; ++i) {
        Record *entry = table->buckets[i];
        while (entry) {
            unsigned long new_index = hash(entry->key, new_capacity);
            Record *next_entry = entry->next;
            entry->next = new_buckets[new_index];
            new_buckets[new_index] = entry;
            entry = next_entry;
        }
    }

    free(table->buckets);
    table->buckets = new_buckets;
    table->capacity = new_capacity;
}

// Example usage
int main() {
    HashTable *table = create_table(INITIAL_CAPACITY);

    insert_record(table, 1, 100);
    insert_record(table, 2, 200);

    int value;
    if (get_record(table, 1, &value)) {
        printf("Key 1: %d\n", value);
    }

    delete_record(table, 1);

    free_table(table);
    return 0;
}
```

### Key Points:

- **Thread Safety**: The `pthread_mutex_t` is used to ensure thread-safe operations on the hash table.

- **Dynamic Resizing**: The table resizes when it exceeds half of its capacity to maintain efficient performance.

- **Memory Management**: Proper allocation and deallocation are handled, preventing memory leaks.

- **Concurrency Considerations**: Mutex locks provide simplicity in handling concurrent access but could be replaced with lock-free algorithms for performance-critical applications.

- **Integer Overflow**: Direct assignment is used; additional checks can be added if necessary to handle overflow cases explicitly. 

This implementation balances between clarity and efficiency while providing a robust foundation for future enhancements like metadata or other data types.']

