typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG_T ue_information_tag;
    CRC_INDICATION_REL8_TAG_T crc_indication_rel8_tag;
    uint32_t rnti;
    size_t version;  // Versioning support
} NFAPI_CRC_INDICATION_PDU_T;

// Memory Pool Structure
typedef struct MemoryPool {
    void *pool;
    size_t block_size;
    size_t pool_size;
    pthread_mutex_t lock;
    void **free_list;
    size_t free_count;
} MemoryPool;

// Dynamic List Structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t count;
    pthread_rwlock_t rwlock;
    MemoryPool mem_pool;
} DynamicList;

// Function Prototypes
DynamicList* create_dynamic_list(size_t initial_capacity, size_t block_size);
void destroy_dynamic_list(DynamicList *list);
bool add_pdu_to_list(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T pdu);
bool validate_pdu(const NFAPI_CRC_INDICATION_PDU_T *pdu);
NFAPI_CRC_INDICATION_PDU_T* allocate_pooled_memory(MemoryPool *pool);
void free_pooled_memory(MemoryPool *pool, void *ptr);

// Function Implementations
DynamicList* create_dynamic_list(size_t initial_capacity, size_t block_size) {
    DynamicList *list = malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->data = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->count = 0;

    pthread_rwlock_init(&list->rwlock, NULL);

    pthread_mutex_init(&list->mem_pool.lock, NULL);
    list->mem_pool.pool_size = block_size * 100; // example size
    list->mem_pool.block_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    list->mem_pool.free_list = malloc(block_size * sizeof(void*));
    if (!list->mem_pool.free_list) {
        free(list->data);
        free(list);
        return NULL;
    }
    memset(list->mem_pool.free_list, 0, block_size * sizeof(void*));

    list->mem_pool.pool = malloc(list->mem_pool.pool_size);
    if (!list->mem_pool.pool) {
        for (size_t i = 0; i < block_size; ++i) {
            free(list->mem_pool.free_list[i]);
        }
        free(list->mem_pool.free_list);
        free(list->data);
        free(list);
        return NULL;
    }

    list->mem_pool.free_count = 0;
    for (size_t i = 0; i < block_size; ++i) {
        void *ptr = (char*)list->mem_pool.pool + i * list->mem_pool.block_size;
        list->mem_pool.free_list[i] = ptr;
        list->mem_pool.free_count++;
    }

    return list;
}

void destroy_dynamic_list(DynamicList *list) {
    if (!list) return;

    pthread_rwlock_destroy(&list->rwlock);
    pthread_mutex_destroy(&list->mem_pool.lock);

    for (size_t i = 0; i < list->count; ++i) {
        void* ptr = (void*)&(list->data[i]);
        free_pooled_memory(&list->mem_pool, ptr);
    }

    free(list->data);
    free(list->mem_pool.free_list);
    free(list->mem_pool.pool);
    free(list);
}

bool add_pdu_to_list(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!validate_pdu(&pdu)) return false;

    pthread_rwlock_wrlock(&list->rwlock);

    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_rwlock_unlock(&list->rwlock);
            return false;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T* allocated_memory = allocate_pooled_memory(&list->mem_pool);
    if (!allocated_memory) {
        pthread_rwlock_unlock(&list->rwlock);
        return false;
    }

    memcpy(allocated_memory, &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->data[list->count++] = *allocated_memory;

    pthread_rwlock_unlock(&list->rwlock);
