#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>
#include <string.h>

#define INITIAL_POOL_SIZE 1024

typedef enum { ACTIVE, INACTIVE } StatusFlag;

typedef struct {
    char type[32];
    size_t size;
} Resource;

typedef struct {
    time_t timestamp;
    atomic_int status_flag;
    Resource *resource;
} User;

typedef struct MemoryPoolNode {
    User user;
    struct MemoryPoolNode* next;
} MemoryPoolNode;

MemoryPoolNode* memory_pool = NULL;
pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;
size_t total_resources_size = 0;

// Custom lock-free stack for concurrent access
MemoryPoolNode* head = NULL;

User* allocate_user(Resource* resource) {
    User* user = NULL;

    // Try to pop from the free list (lock-free)
    while (!__atomic_compare_exchange_n(&head, &user, user->next, 0, __ATOMIC_SEQ_CST, __ATOMIC_SEQ_CST)) {}

    if (user == NULL) {
        pthread_mutex_lock(&pool_mutex);

        // Check pool for available users
        MemoryPoolNode* node = memory_pool;
        memory_pool = memory_pool->next;
        user = &node->user;

        pthread_mutex_unlock(&pool_mutex);

        if (!memory_pool && malloc(10 * sizeof(MemoryPoolNode)) == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
    }

    // Initialize User object
    time(&user->timestamp);
    atomic_store(&(user->status_flag), INACTIVE);  // Default status

    user->resource = resource;
    total_resources_size += resource->size;

    return user;
}

void free_user(User* user) {
    Resource* res = user->resource;

    total_resources_size -= res->size;
    pthread_mutex_lock(&pool_mutex);

    MemoryPoolNode* node = (MemoryPoolNode*)user;
    node->next = memory_pool;
    memory_pool = node;

    pthread_mutex_unlock(&pool_mutex);
}

void log_operation(const char *operation) {
    // Simplified logging mechanism
    printf("Log: %s\n", operation);
}

void serialize_users(FILE* file) {
    MemoryPoolNode* current = head;

    while (current != NULL) {
        User* user = &current->user;

        fprintf(file, "Timestamp: %ld, Status: %d, Resource Type: %s, Resource Size: %zu\n",
                user->timestamp, atomic_load(&user->status_flag),
                user->resource->type, user->resource->size);

        current = (MemoryPoolNode*)current->next;
    }
}

void exponential_backoff(int attempt) {
    int wait_time = 1 << attempt; // Exponential backoff
    if (wait_time > 60) {  // Cap at 60 seconds for practicality
        wait_time = 60;
    }

    sleep(wait_time);
}

// Example function to interact with external data source
Resource* fetch_resource_from_source(const char *resource_id, int attempt) {
    Resource* resource = NULL;

    // Simulate fetching logic and retry mechanism
    if (attempt > 5 || simulate_fetch(resource_id)) { 
        return resource;
    }

    exponential_backoff(attempt);
    return fetch_resource_from_source(resource_id, ++attempt);
}

// Example function to simulate data fetching success/failure
int simulate_fetch(const char *resource_id) {
    static int fail = 1; // Simulate an intermittent failure scenario

    if (fail--) {
        Resource* resource = malloc(sizeof(Resource));
        strcpy(resource->type, "ExampleType");
        resource->size = rand() % 1024;
        return resource;
    }

    return NULL;
}

int main(void) {
