```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

// Define structures
typedef struct {
    int tag;
} RX_UE_INFORMATION_TAG;

typedef unsigned short RNTI;

typedef struct {
    int crcFlag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ueInfoTag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcIndication;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a node for the pool
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Pool structure with read-write lock
typedef struct {
    Node* head;
    pthread_rwlock_t rwlock;
    atomic_size_t size;
} PduPool;

// Function to initialize pool
void initPduPool(PduPool* pool) {
    pool->head = NULL;
    pthread_rwlock_init(&pool->rwlock, NULL);
    atomic_store(&pool->size, 0);
}

// Function to generate random CRC flag
int getRandomCrcFlag() {
    return rand() % 2; // Randomly returns 0 or 1
}

// Function to create a new PDU and add it to the pool
void addToPduPool(PduPool* pool, RX_UE_INFORMATION_TAG ueInfoTag, RNTI rnti) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return;

    newNode->data.ueInfoTag = ueInfoTag;
    newNode->data.rnti = rnti;
    newNode->data.crcIndication.crcFlag = getRandomCrcFlag();
    newNode->next = NULL;

    pthread_rwlock_wrlock(&pool->rwlock);
    newNode->next = pool->head;
    pool->head = newNode;
    atomic_fetch_add(&pool->size, 1);
    pthread_rwlock_unlock(&pool->rwlock);
}

// Function to remove a PDU from the pool
int removeFromPduPool(PduPool* pool, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_rwlock_rdlock(&pool->rwlock);

    Node** current = &pool->head;
    while (*current) {
        if (pdu->rnti == (*current)->data.rnti) {
            Node* toRemove = *current;
            *current = toRemove->next;

            // Copy data
            *pdu = toRemove->data;

            free(toRemove);
            atomic_fetch_sub(&pool->size, 1);

            pthread_rwlock_unlock(&pool->rwlock);
            return 0; // Success
        }
        current = &(*current)->next;
    }

    pthread_rwlock_unlock(&pool->rwlock);
    return -1; // Not found
}

// Function to cleanup pool
void destroyPduPool(PduPool* pool) {
    Node* current = pool->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_rwlock_destroy(&pool->rwlock);
}

// Example usage
int main() {
    PduPool pool;
    initPduPool(&pool);

    RX_UE_INFORMATION_TAG ueInfoTag = { .tag = 1 };
    RNTI rnti = 1234;

    addToPduPool(&pool, ueInfoTag, rnti);

    NFAPI_CRC_INDICATION_PDU_T pdu;
    if (removeFromPduPool(&pool, &pdu) == 0) {
        printf("Removed PDU with RNTI: %d\n", pdu.rnti);
    }

    destroyPduPool(&pool);
    return 0;
}
```

### Key Points:
