```python
import os
import sys
import logging
from ctypes import CDLL, c_int, c_char_p, Structure, POINTER, byref

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Load the C library
c_lib = CDLL('./libfilename_analyzer.so')  # Ensure this shared object is compiled from C code provided below

def analyze_filename(filename):
    try:
        c_lib.analyze_filename.argtypes = [c_char_p, POINTER(c_int)]
        count_uppercase = c_int()
        file_type = c_lib.analyze_filename(filename.encode('utf-8'), byref(count_uppercase))
        return count_uppercase.value, 'Binary' if file_type == 1 else 'Text'
    except Exception as e:
        logging.error(f"Error analyzing filename {filename}: {e}")
        return None, None

def execute_scripts(script_dir):
    for script in sorted(os.listdir(script_dir)):
        if script.endswith('.py'):
            count_uppercase, file_type = analyze_filename(script)
            if count_uppercase is not None:
                metadata = {'uppercase_count': count_uppercase, 'file_type': file_type}
                logging.info(f"Metadata for {script}: {metadata}")

            try:
                with open(os.path.join(script_dir, script), 'r') as f:
                    exec(compile(f.read(), script, 'exec'))
                logging.info(f"Executed {script} successfully.")
            except Exception as e:
                logging.error(f"Error executing {script}: {e}")

if __name__ == '__main__':
    if len(sys.argv) != 2:
        print("Usage: python execute_scripts.py <directory>")
        sys.exit(1)

    script_directory = sys.argv[1]
    if not os.path.isdir(script_directory):
        logging.error(f"Directory {script_directory} does not exist.")
        sys.exit(1)

    execute_scripts(script_directory)
```

