['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef enum {
    STATUS_OK,
    STATUS_ERROR,
    STATUS_PENDING
} Status;

typedef struct entry_t {
    float value;
    char *message;
    Status status;
} Entry;

#define INITIAL_CAPACITY 10

typedef struct {
    Entry *entries;
    size_t count;
    size_t capacity;
    size_t total_size; // Total memory footprint in bytes
    size_t max_entries;
    size_t max_total_size;
    pthread_mutex_t lock;
} EntryList;

// Function to create a new list
EntryList* create_entry_list(size_t max_entries, size_t max_total_size) {
    EntryList *list = malloc(sizeof(EntryList));
    if (!list) return NULL;

    list->entries = calloc(INITIAL_CAPACITY, sizeof(Entry));
    list->count = 0;
    list->capacity = INITIAL_CAPACITY;
    list->total_size = 0;
    list->max_entries = max_entries;
    list->max_total_size = max_total_size;

    if (pthread_mutex_init(&list->lock, NULL) != 0) {
        free(list->entries);
        free(list);
        return NULL;
    }

    return list;
}

// Function to add an entry
int add_entry(EntryList *list, float value, const char *message, Status status) {
    pthread_mutex_lock(&list->lock);

    size_t message_size = strlen(message) + 1;
    size_t new_total_size = list->total_size + sizeof(Entry) + message_size;

    if (list->count >= list->max_entries || new_total_size > list->max_total_size) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Resource limit reached
    }

    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        Entry *new_entries = realloc(list->entries, new_capacity * sizeof(Entry));

        if (!new_entries) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Allocation failed
        }

        list->entries = new_entries;
        list->capacity = new_capacity;
    }

    Entry *entry = &list->entries[list->count++];
    entry->value = value;
    entry->message = malloc(message_size);
    if (!entry->message) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Allocation failed
    }
    strcpy(entry->message, message);
    entry->status = status;

    list->total_size = new_total_size;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Function to serialize the list to a file
int save_entries(const EntryList *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    fwrite(&list->count, sizeof(size_t), 1, file);
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        fwrite(&list->entries[i], sizeof(Entry), 1, file);
        size_t message_size;
        memcpy(&message_size, &((char*)list->entries[i].message)[-sizeof(size_t)], sizeof(size_t));
        fwrite(list->entries[i].message, message_size, 1, file);
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);
    return 0;
}

// Function to load entries from a file
int load_entries(EntryList *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    pthread_mutex_lock(&list->lock);
    for (size_t i = list->count; i < count && i < list->max_entries; ++i) {
        Entry entry;
        fread(&entry, sizeof(Entry), 1, file);

        size_t message_size;
        memcpy(&message_size, &((char*)entry.message)[-sizeof(size_t)], sizeof(size_t));
        char *message = malloc(message_size);
        if (!message) break;

        fread(message, message_size, 1, file);
        entry.message = message;

        list->entries[list->count++] = entry;
    }
    pthread_mutex_unlock(&list->lock);

    fclose(file);
    return 0;
}

// Function to free the list
void destroy_entry_list(EntryList *list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        free(list->entries[i].message);
    }
    free(list->entries);

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Function to log an entry initialization
void log_entry_init(const Entry *entry, const char *source) {
    // Example simple logging, can be expanded for thread-safe logging as needed
    printf("Initialized Entry: value=%.2f, message='%s', status=%d, source=%s\n", 
           entry->value, entry->message, entry->status, source);
}

// Example usage
int main() {
    EntryList *list = create_entry_list(100, 1024*1024); // Max 100 entries, max total size 1MB

    if (add_entry(list, 3.14f, "Test message", STATUS_OK) == 0) {
        log_entry_init(&list->entries[0], "External Source");
    }

    save_entries(list, "entry_data.bin");

    destroy_entry_list(list);
    return 0;
}
```

