['Below is an implementation of the C function that manages a dynamic array of `record` structures as described:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <errno.h>

typedef struct {
    long offset;
    int key;
    int value;
} record;

typedef struct {
    record *array;
    size_t capacity;
    size_t count;
    size_t total_value_sum;
    pthread_mutex_t lock;
} RecordManager;

RecordManager* init_record_manager(size_t initial_capacity, const char *error_message) {
    RecordManager *rm = malloc(sizeof(RecordManager));
    if (!rm) {
        fprintf(stderr, "%s: Failed to allocate memory for RecordManager\n", error_message);
        return NULL;
    }

    rm->array = calloc(initial_capacity, sizeof(record));
    if (!rm->array) {
        fprintf(stderr, "%s: Failed to allocate memory for record array\n", error_message);
        free(rm);
        return NULL;
    }

    rm->capacity = initial_capacity;
    rm->count = 0;
    rm->total_value_sum = 0;
    pthread_mutex_init(&rm->lock, NULL);

    return rm;
}

int resize_record_manager(RecordManager *rm) {
    size_t new_capacity = rm->capacity * 2;
    record *new_array = realloc(rm->array, new_capacity * sizeof(record));
    if (!new_array) {
        fprintf(stderr, "Failed to reallocate memory for record array\n");
        return -1; // Indicate failure
    }

    rm->array = new_array;
    rm->capacity = new_capacity;

    return 0; // Success
}

int add_record(RecordManager *rm, long offset, int key, int value_range_min, int value_range_max) {
    pthread_mutex_lock(&rm->lock);

    if (rm->count == rm->capacity && resize_record_manager(rm) != 0) {
        pthread_mutex_unlock(&rm->lock);
        return -1; // Indicate failure due to resizing
    }

    record *rec = &rm->array[rm->count];
    rec->offset = offset;
    rec->key = key;

    srand(time(NULL) + rec->offset); // Seed with offset for randomness

    long value;
    do {
        value = (long)rand() % (value_range_max - value_range_min + 1) + value_range_min;
    } while ((rm->total_value_sum > LLONG_MAX - value)); // Overflow check

    rec->value = (int)value;

    if (__builtin_add_overflow(rm->total_value_sum, value, &rm->total_value_sum)) {
        fprintf(stderr, "Integer overflow detected when updating total value sum\n");
        pthread_mutex_unlock(&rm->lock);
        return -1; // Indicate failure due to overflow
    }

    rm->count++;
    pthread_mutex_unlock(&rm->lock);

    return 0; // Success
}

void free_record_manager(RecordManager *rm) {
    if (rm) {
        free(rm->array);
        pthread_mutex_destroy(&rm->lock);
        free(rm);
    }
}

// Usage example:
int main() {
    const size_t initial_capacity = 10;
    RecordManager *manager = init_record_manager(initial_capacity, "Initialization");
    if (!manager) return EXIT_FAILURE;

    int keys[] = {1, 2, 3};
    size_t num_keys = sizeof(keys) / sizeof(keys[0]);

    for (size_t i = 0; i < num_keys; ++i) {
        if (add_record(manager, i * 10, keys[i], 1, 100) != 0) {
            fprintf(stderr, "Failed to add record\n");
            free_record_manager(manager);
            return EXIT_FAILURE;
        }
    }

    printf("Total Value Sum: %zu\n", manager->total_value_sum);

    free_record_manager(manager);
    return EXIT_SUCCESS;
}
```

### Key Points:

- **Concurrency**: The function uses `pthread_mutex` to ensure thread safety when accessing and modifying the record array.

- **Dynamic Resizing**: The array is resized using `realloc` when capacity is exceeded, doubling its size each time.

- **Overflow Handling**: Uses GCC built-in functions to detect integer overflow during sum updates.

- **Memory Management**: Custom memory allocation and deallocation are managed with checks for errors and memory leaks.

- **Error Handling**: Provides meaningful error messages on failures like memory allocation issues or overflow detection.

This code provides a thread-safe dynamic array management system, balancing performance and resource constraints as specified.']

