#define MEMORY_ERROR -1

DataFile* initialize_data_files(size_t count, int compression_level, const char file_names[][256], size_t file_sizes[], int access_frequencies[], int *error_code) {
    DataFile *dataFiles = (DataFile*)malloc(count * sizeof(DataFile));
    if (!dataFiles) {
        *error_code = MEMORY_ERROR;
        return NULL;
    }

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    for (size_t i = 0; i < count; ++i) {
        strncpy(dataFiles[i].FileName, file_names[i], sizeof(dataFiles[i].FileName) - 1);
        dataFiles[i].FileSize = file_sizes[i];
        dataFiles[i].AccessFrequency = access_frequencies[i];

        // Calculate hash
        dataFiles[i].HashValue = calculate_hash(dataFiles[i].FileName, strlen(dataFiles[i].FileName));

        // Compress file if needed
        pthread_mutex_lock(&mutex);
        char *compressed_data = compress_file(file_names[i], compression_level);  // Assume this function is defined in the library
        if (compressed_data) {
            // Store or handle compressed data as needed
            free(compressed_data);
        }
        pthread_mutex_unlock(&mutex);

        // External storage integration can be handled here, e.g., save to disk or database
    }

    pthread_mutex_destroy(&mutex);
    *error_code = INIT_SUCCESS;
    return dataFiles;
}

