['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define INITIAL_CAPACITY 16

typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    Record *records;
    int capacity;
    size_t size;
    pthread_mutex_t lock;
} RecordsDatabase;

static void resize(RecordsDatabase *db, int new_capacity);

RecordsDatabase* create_database() {
    RecordsDatabase *db = malloc(sizeof(RecordsDatabase));
    db->capacity = INITIAL_CAPACITY;
    db->size = 0;
    db->records = calloc(db->capacity, sizeof(Record));
    pthread_mutex_init(&db->lock, NULL);
    return db;
}

void destroy_database(RecordsDatabase *db) {
    free(db->records);
    pthread_mutex_destroy(&db->lock);
    free(db);
}

int hash(int key, int capacity) {
    return abs(key) % capacity;
}

void add_record(RecordsDatabase *db, int key, long offset) {
    pthread_mutex_lock(&db->lock);

    if (db->size >= db->capacity / 2) {
        resize(db, db->capacity * 2);
    }

    int index = hash(key, db->capacity);
    while (db->records[index].key != 0 && db->records[index].key != key) {
        index = (index + 1) % db->capacity;
    }

    if (db->records[index].key == 0) {
        db->records[index] = (Record){.key = key, .offset = offset};
        db->size++;
    } else {
        db->records[index].offset = offset; // Update existing record
    }

    pthread_mutex_unlock(&db->lock);
}

long get_record_offset(RecordsDatabase *db, int key) {
    pthread_mutex_lock(&db->lock);

    int index = hash(key, db->capacity);
    while (db->records[index].key != 0) {
        if (db->records[index].key == key) {
            long offset = db->records[index].offset;
            pthread_mutex_unlock(&db->lock);
            return offset;
        }
        index = (index + 1) % db->capacity;
    }

    pthread_mutex_unlock(&db->lock);
    return -1; // Record not found
}

static void resize(RecordsDatabase *db, int new_capacity) {
    Record *new_records = calloc(new_capacity, sizeof(Record));
    for (size_t i = 0; i < db->capacity; ++i) {
        if (db->records[i].key != 0) {
            int index = hash(db->records[i].key, new_capacity);
            while (new_records[index].key != 0) {
                index = (index + 1) % new_capacity;
            }
            new_records[index] = db->records[i];
        }
    }

    free(db->records);
    db->records = new_records;
    db->capacity = new_capacity;

    if (db->size < db->capacity / 4 && db->capacity > INITIAL_CAPACITY) {
        resize(db, db->capacity / 2); // Shrink capacity if necessary
    }
}

// Example usage of the function
int main() {
    RecordsDatabase *db = create_database();

    add_record(db, 1, 100);
    printf("Offset for key 1: %ld\n", get_record_offset(db, 1));

    add_record(db, 2, 200);
    printf("Offset for key 2: %ld\n", get_record_offset(db, 2));

    destroy_database(db);
    return 0;
}
```

### Design Choices and Trade-offs:
- **Data Structure**: A simple open-addressed hash table was chosen to balance ease of implementation with performance. It provides average-case O(1) time complexity for insertions and lookups.
- **Concurrency Control**: Mutex locks are used to ensure thread safety, allowing concurrent access from multiple threads while avoiding race conditions.
- **Dynamic Resizing**: The capacity is doubled when the load factor exceeds 0.5 and halved when it drops below 0.25, provided it's greater than the initial capacity, to balance between memory usage and access speed.
- **Memory Management**: Use of `calloc` for initialization ensures zeroed-out entries, reducing false positives during lookups.
- **Cache Utilization**: Linear probing in a fixed-size array helps in better cache utilization compared to linked-list structures.

This implementation aims to provide a balanced approach for handling dynamic records with efficient memory usage and concurrency support.']

