#include <stdint.h>

#define MAX_PACKETS 50000

typedef struct {
    uint32_t SourceIP;
    uint32_t DestinationIP;
    size_t PacketSize;
    uint16_t Checksum;
} NetworkPacket;

typedef struct {
    int value;
    int keyIndex; // Index from an array of keys
} Record;

typedef struct {
    pthread_mutex_t lock;
    NetworkPacket* packets;
    long* offsets;
    Record* records;
    int* keys;
    size_t packetCount;
    size_t recordCount;
    uint64_t totalRecordValueSum;
} SharedData;

uint16_t calculateChecksum(NetworkPacket* packet) {
    // Implement a simple checksum calculation
    return (packet->SourceIP ^ packet->DestinationIP ^ packet->PacketSize) & 0xFFFF;
}

void* processData(void* arg) {
    SharedData* sharedData = (SharedData*)arg;

    pthread_mutex_lock(&sharedData->lock);

    for (size_t i = 0; i < sharedData->packetCount; ++i) {
        NetworkPacket* packet = &sharedData->packets[i];

        // Simulate IP address assignment
        packet->SourceIP = rand() % 256;
        packet->DestinationIP = rand() % 256;
        packet->PacketSize = rand() % 1500 + 1; // Typical MTU size

        // Calculate checksum
        packet->Checksum = calculateChecksum(packet);
    }

    uint64_t previousSum = sharedData->totalRecordValueSum;
    for (size_t i = 0; i < sharedData->recordCount; ++i) {
        Record* record = &sharedData->records[i];

        // Generate a random value within the range
        int minValue = 0, maxValue = previousSum + sharedData->keys[i] % 100;
        if (minValue > maxValue) { // Handle potential overflow
            int temp = minValue;
            minValue = maxValue;
            maxValue = temp;
        }
        record->value = minValue + rand() % (maxValue - minValue + 1);

        previousSum += record->value;
    }

    sharedData->totalRecordValueSum = previousSum;

    pthread_mutex_unlock(&sharedData->lock);

    return NULL;
}

void initializeSharedData(SharedData* sharedData, size_t packetCount, size_t recordCount) {
    pthread_mutex_init(&sharedData->lock, NULL);

    sharedData->packets = (NetworkPacket*)malloc(packetCount * sizeof(NetworkPacket));
    sharedData->offsets = (long*)calloc(recordCount, sizeof(long)); // Initialize offsets to 0
    sharedData->records = (Record*)malloc(recordCount * sizeof(Record));
    sharedData->keys = (int*)malloc(recordCount * sizeof(int));

    if (!sharedData->packets || !sharedData->offsets || !sharedData->records || !sharedData->keys) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    // Initialize keys with some values for demonstration purposes
    for (size_t i = 0; i < recordCount; ++i) {
        sharedData->keys[i] = rand() % 100;
    }

    sharedData->packetCount = packetCount;
    sharedData->recordCount = recordCount;
    sharedData->totalRecordValueSum = 0;

    // Log the initialization
    printf("Initialized with %zu packets and %zu records.\n", packetCount, recordCount);
}

void cleanupSharedData(SharedData* sharedData) {
    pthread_mutex_destroy(&sharedData->lock);
    free(sharedData->packets);
    free(sharedData->offsets);
    free(sharedData->records);
    free(sharedData->keys);
}

int main() {
    srand(time(NULL));

    SharedData sharedData;
    initializeSharedData(&sharedData, MAX_PACKETS, 1000);

    pthread_t threads[4];
    for (int i = 0; i < 4; ++i) {
        if (pthread_create(&threads[i], NULL, processData, &sharedData)) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    printf("Total Record Value Sum: %llu\n", sharedData.totalRecordValueSum);

    cleanupSharedData(&sharedData);

    return 0;
}
```

This code demonstrates how to initialize and process data using threads, while maintaining thread safety with mutexes. It includes dynamic memory allocation for the structures, error handling for memory operations, and random value generation for records within a configurable range. The checksum calculation is simple but can be replaced with a more complex algorithm if needed.']

