### `Config.h`

```cpp
#ifndef CONFIG_H
#define CONFIG_H

#include <string>
#include <chrono>

class Config {
public:
    std::string networkSettings;
    std::string loggingSettings;
    std::string userPreferences;

    std::chrono::system_clock::time_point lastModified;
    int version;

    Config() : version(0) {
        auto now = std::chrono::system_clock::now();
        lastModified = now;
    }

    void update(const std::string& network, const std::string& logging, const std::string& userPrefs);
};

#endif // CONFIG_H
```

### `Config.cpp`

```cpp
#include "Config.h"
#include <algorithm>

void Config::update(const std::string& network, const std::string& logging, const std::string& userPrefs) {
    auto now = std::chrono::system_clock::now();

    if (networkSettings != network || loggingSettings != logging || userPreferences != userPrefs) {
        networkSettings = network;
        loggingSettings = logging;
        userPreferences = userPrefs;

        lastModified = now;
        ++version;
    }
}
```

### `ConfigManager.h`

```cpp
#ifndef CONFIG_MANAGER_H
#define CONFIG_MANAGER_H

#include "Config.h"
#include <map>
#include <mutex>
#include <memory>

class ConfigManager {
public:
    std::shared_ptr<Config> loadConfig(const std::string& key);
    void saveConfig(const std::string& key, const std::shared_ptr<Config>& config);
    void updateConfig(const std::string& key, const std::string& network, const std::string& logging, const std::string& userPrefs);

private:
    std::map<std::string, std::shared_ptr<Config>> configs;
    mutable std::mutex mtx;

    // In-memory LRU cache
    std::deque<std::string> lruCache;
    size_t cacheSize = 10;  // Example size

    void updateLRUCache(const std::string& key);
};

#endif // CONFIG_MANAGER_H
```

### `ConfigManager.cpp`

```cpp
#include "ConfigManager.h"
#include <iostream>
#include <stdexcept>

std::shared_ptr<Config> ConfigManager::loadConfig(const std::string& key) {
    std::lock_guard<std::mutex> lock(mtx);

    if (configs.find(key) == configs.end()) {
        throw std::runtime_error("Configuration not found.");
    }

    updateLRUCache(key);
    return configs[key];
}

void ConfigManager::saveConfig(const std::string& key, const std::shared_ptr<Config>& config) {
    std::lock_guard<std::mutex> lock(mtx);

    configs[key] = config;
    updateLRUCache(key);
}

void ConfigManager::updateConfig(const std::string& key, const std::string& network, const std::string& logging, const std::string& userPrefs) {
    std::shared_ptr<Config> config = loadConfig(key);

    config->update(network, logging, userPrefs);
    saveConfig(key, config);
}

void ConfigManager::updateLRUCache(const std::string& key) {
    auto it = std::find(lruCache.begin(), lruCache.end(), key);
    if (it != lruCache.end()) {
        lruCache.erase(it);
    }
    lruCache.push_front(key);

    if (lruCache.size() > cacheSize) {
        configs.erase(lruCache.back());
        lruCache.pop_back();
    }
}
```

### `CLI.h`

```cpp
#ifndef CLI_H
#define CLI_H

#include "ConfigManager.h"

class CLI {
public:
    void run();

private:
    ConfigManager configManager;

    void showHelp();
    void handleCommand(const std::vector<std::string>& args);
};

#endif // CLI_H
```

### `CLI.cpp`

```cpp
#include "CLI.h"
#include <iostream>
#include <sstream>

void CLI::run() {
    std::cout << "Welcome to the Config Manager CLI\n";
    showHelp();

    std::string line;
    while (std::getline(std::cin, line)) {
        std::istringstream iss(line);
        std::vector<std::string> args{std::istream_iterator<std::string>{iss},
                                      std::istream_iterator<std::string>{}};

        handleCommand(args);
    }
}

void CLI::showHelp() {
    std::cout << "Available commands:\n"
              << "  load <key>\n"
              << "  save <key> <network> <logging> <userPrefs>\n"
              << "  update <key> <network> <logging> <userPrefs>\n"
              << "  help\n";
}

void CLI::handleCommand(const std::vector<std::string>& args) {
    if (args.empty()) return;

    if (args[0] == "load" && args.size() == 2) {
        try {
            auto config = configManager.loadConfig(args[1]);
            std::cout << "Loaded Config: Network=" << config->networkSettings
                      << ", Logging=" << config->loggingSettings
                      << ", UserPrefs=" << config->userPreferences 
                      << ", Version=" << config->version << "\n";
        } catch (const std::exception& e) {
            std::cerr << "Error: " << e.what() << '\n';
        }
    } else if (args[0] == "save" && args.size() == 5) {
        auto config = std::make_shared<Config>();
        config->update(args[2], args[3], args[4]);
        configManager.saveConfig(args[1], config);
        std::cout << "Configuration saved.\n";
    } else if (args[0] == "update" && args.size() == 5) {
        try {
            configManager.updateConfig(args[1], args[2], args[3], args[4]);
            std::cout << "Configuration updated.\n";
        } catch (const std::exception& e) {
            std::cerr << "Error: " << e.what() << '\n';
        }
    } else if (args[0] == "help") {
        showHelp();
    } else {
        std::cerr << "Unknown command. Type 'help' for a list of commands.\n";
    }
}
```

### `main.cpp`

