#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

#define MAX_NODES 1000000

typedef struct CRC_INDICATION_REL8_TAG {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct DoublyLinkedList {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
} DoublyLinkedList;

DoublyLinkedList* create_list() {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_node(Node* node) {
    free(node);
}

void destroy_list(DoublyLinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        destroy_node(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int validate_structure(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu->RX_UE_INFORMATION_TAG == 0 || pdu->RNTI == 0)
        return 0; // Invalid
    return 1;
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    node->data = data;
    node->prev = node->next = NULL;
    return node;
}

void add_to_list(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = create_node(data);
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    pthread_mutex_lock(&list->lock);

    if (list->tail) {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    } else {
        list->head = list->tail = new_node;
    }

    pthread_mutex_unlock(&list->lock);
}

void generate_random_data(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pdu->RX_UE_INFORMATION_TAG = rand();
    pdu->RNTI = rand() % 10000;
    pdu->crc_tag.CRCFLAG = rand() % 2;
}

void create_and_populate_list(DoublyLinkedList** list, size_t max_count) {
    *list = create_list();
    if (!*list) return;

    for (size_t i = 0; i < max_count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        generate_random_data(&pdu);

        if (!validate_structure(&pdu)) {
            fprintf(stderr, "Invalid structure at index %zu\n", i);
            continue;
        }

        add_to_list(*list, pdu);
    }
}

void serialize_list(DoublyLinkedList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);
}

void deserialize_list(DoublyLinkedList* list, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return;

    NFAPI_CRC_INDICATION_PDU_T pdu;
    while (fread(&pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        add_to_list(list, pdu);
    }

    fclose(file);
}

void* monitor_performance(void* arg) {
    DoublyLinkedList* list = (DoublyLinkedList*)arg;
    struct timespec start, end;
    double elapsed_time;

    while (1) {
        pthread_mutex_lock(&list->lock);

        clock_gettime(CLOCK_MONOTONIC, &start);
        Node* current = list->head;
        while (current && current->next) {
            current = current->next; // Traverse
        }
        clock_gettime(CLOCK_MONOTONIC, &end);

        elapsed_time = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1e9;
        printf("Average time per node: %f seconds\n", elapsed_time / ((current && current->prev) ? current->prev : list->head));

        pthread_mutex_unlock(&list->lock);
        sleep(10); // Log every 10 seconds
    }

    return NULL;
}

int main() {
    srand(time(NULL));
    DoublyLinkedList* list = NULL;
    create_and_populate_list(&list, 10000);

    pthread_t monitor_thread;
    pthread_create(&monitor_thread, NULL, monitor_performance, (void*)list);

    serialize_list(list, "nfa_data.bin");
    deserialize_list(list, "nfa_data.bin");

    destroy_list(list);
    return 0;
}
```

