#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>

#define MAX_CONFIG_LINES 1024
#define MAX_MAC_ADDRESSES 64

typedef struct {
    char ip[16];
    char subnet_mask[16];
    char gateway[16];
    char mac_addresses[MAX_MAC_ADDRESSES][18]; // MAC addresses in "XX:XX:XX:XX:XX:XX" format
} NetworkInterfaceSettings;

// Function to check if an IP address is valid and unique within a list.
int validate_and_adjust_ip(char ip_list[][16], int count, char *ip) {
    struct in_addr addr, candidate;
    inet_aton(ip, &addr);

    for (int i = 0; i < count; i++) {
        if (!inet_aton(ip_list[i], &candidate) || memcmp(&addr, &candidate, sizeof(struct in_addr)) == 0) {
            int suffix = 1;
            char adjusted_ip[16];
            snprintf(adjusted_ip, sizeof(adjusted_ip), "%s-%d", ip, suffix);

            while (inet_aton(adjusted_ip, &candidate) && memcmp(&addr, &candidate, sizeof(struct in_addr)) == 0) {
                suffix++;
                snprintf(adjusted_ip, sizeof(adjusted_ip), "%s-%d", ip, suffix);
            }

            strcpy(ip, adjusted_ip); // Adjust the IP to be unique
            return 0; // Indicates an adjustment was made
        }
    }

    return 1; // No adjustment needed
}

// Function to parse network configuration based on device type.
int parse_network_config(const char *filename, NetworkInterfaceSettings **interfaces) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Error opening file: %s\n", filename);
        return -1;
    }

    char line[256];
    int count = 0;

    while (fgets(line, sizeof(line), file)) {
        // Assume each entry is a new line and fields are comma-separated
        NetworkInterfaceSettings *interfaces_temp = realloc(*interfaces, sizeof(NetworkInterfaceSettings) * (count + 1));
        if (!interfaces_temp) {
            free(*interfaces);
            fprintf(stderr, "Memory allocation error\n");
            fclose(file);
            return -1;
        }

        // Parse the line into IP address, subnet mask, gateway, and MAC addresses
        char ip[16], subnet_mask[16], gateway[16];
        int mac_count = 0;

        if (sscanf(line, "%[^,],%[^,],%[^,]", ip, subnet_mask, gateway) == 3) {
            strcpy((*interfaces_temp + count)->ip, ip);
            strcpy((*interfaces_temp + count)->subnet_mask, subnet_mask);
            strcpy((*interfaces_temp + count)->gateway, gateway);

            char mac[18];
            while (sscanf(line + strlen(line), ",%17[^,\n]", mac) == 1 && mac_count < MAX_MAC_ADDRESSES) {
                strncpy((*interfaces_temp + count)->mac_addresses[mac_count], mac, sizeof(mac));
                mac_count++;
            }

            (*interfaces_temp + count)->mac_addresses[mac_count][0] = '\0'; // Null-terminate the MAC array
        } else {
            fprintf(stderr, "Invalid line format: %s\n", line);
            continue;
        }

        if (!validate_and_adjust_ip((*interfaces_temp), count, ip)) {
            fprintf(stderr, "Adjusted IP for uniqueness: %s\n", ip);
        }

        count++;
    }

    fclose(file);

    *interfaces = interfaces_temp;
    return count; // Return the number of parsed entries
}

// Function to print network interface settings.
void print_network_interface_settings(NetworkInterfaceSettings *interfaces, int count) {
    for (int i = 0; i < count; i++) {
        printf("Interface %d:\n", i + 1);
        printf("  IP: %s\n", interfaces[i].ip);
        printf("  Subnet Mask: %s\n", interfaces[i].subnet_mask);
        printf("  Gateway: %s\n", interfaces[i].gateway);

        for (int j = 0; interfaces[i].mac_addresses[j][0] != '\0'; j++) {
            printf("  MAC Address: %s\n", interfaces[i].mac_addresses[j]);
        }
    }
}

// Main function to demonstrate functionality.
int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <config_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    NetworkInterfaceSettings *interfaces = NULL;

    int count = parse_network_config(argv[1], &interfaces);
    if (count < 0) {
        free(interfaces);
        return EXIT_FAILURE;
    }

    print_network_interface_settings(interfaces, count);

    // Return the list of unique NetworkInterfaceSettings
    for (int i = 0; i < count; i++) {
        printf("Returning Interface %d settings\n", i + 1);
    }

    free(interfaces);
    return EXIT_SUCCESS;
}
```']

