void flush_to_disk(Packet **packets, size_t count);

Packet** initialize_dynamic_array(size_t max_packets, NetworkInterfaceConfig interfaces[], size_t num_interfaces) {
    if (max_packets == 0 || max_packets > MAX_PACKETS) {
        fprintf(stderr, "Invalid maximum packet configuration.\n");
        return NULL;
    }

    Packet **packet_array = (Packet **)calloc(max_packets, sizeof(Packet *));
    if (!packet_array) {
        perror("Failed to allocate memory for packet array");
        return NULL;
    }

    size_t current_count = 0;

    while (current_count < max_packets) {
        // Simulate receiving packets from interfaces
        for (size_t i = 0; i < num_interfaces; ++i) {
            // Example of handling based on interface priority
            if (interfaces[i].priority == INTERFACE_HIGH) {
                // Code to handle high-priority packets first...

                Packet *packet = (Packet *)malloc(sizeof(Packet));
                if (!packet) {
                    perror("Failed to allocate memory for packet");
                    return NULL;
                }

                // Simulate packet receiving
                packet->timestamp = time(NULL);
                packet->packet_size = 1024; // Example size
                packet->data = (char *)malloc(packet->packet_size);

                if (!packet->data) {
                    free(packet);
                    perror("Failed to allocate memory for packet data");
                    return NULL;
                }

                if (!validate_packet(packet)) {
                    free(packet->data);
                    free(packet);
                    continue; // Skip invalid packets
                }

                packet_array[current_count++] = packet;

                if (current_count >= max_packets) break;
            }
        }

        // Periodically flush to disk
        if (current_count % 256 == 0 && current_count > 0) {
            flush_to_disk(packet_array, current_count);
        }
    }

    return packet_array;
}

int validate_packet(const Packet *packet) {
    if (!packet || !packet->data || packet->packet_size == 0) return 0;

    // Example validation: check data integrity
    const char expected_signature[] = "VALID"; // Hypothetical signature
    if (strncmp(packet->data, expected_signature, sizeof(expected_signature) - 1) != 0)
        return 0; // Invalid packet

    return 1;
}

void flush_to_disk(Packet **packets, size_t count) {
    FILE *file = fopen("packet_data.bin", "ab");
    if (!file) {
        perror("Failed to open file for flushing packets");
        return;
    }

    for (size_t i = 0; i < count; ++i) {
        fwrite(packets[i], sizeof(Packet), 1, file);
    }

    fclose(file);
}

void free_dynamic_array(Packet **packet_array, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (packet_array[i]) {
            free(packet_array[i]->data);
            free(packet_array[i]);
        }
    }
    free(packet_array);
}
