// Thread-safe queue for storing packets
typedef struct Node {
    Packet packet;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
} PacketQueue;

PacketQueue* createQueue() {
    PacketQueue* q = (PacketQueue*)malloc(sizeof(PacketQueue));
    q->head = q->tail = NULL;
    pthread_mutex_init(&q->lock, NULL);
    return q;
}

void enqueue(PacketQueue* q, Packet packet) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->packet = packet;
    newNode->next = NULL;

    pthread_mutex_lock(&q->lock);

    if (q->tail) {
        q->tail->next = newNode;
    } else {
        q->head = newNode;
    }
    q->tail = newNode;

    pthread_mutex_unlock(&q->lock);
}

Packet dequeue(PacketQueue* q) {
    Packet packet;
    pthread_mutex_lock(&q->lock);

    if (q->head == NULL) {
        pthread_mutex_unlock(&q->lock);
        return (Packet){0}; // Return an empty packet
    }

    Node* temp = q->head;
    packet = temp->packet;
    q->head = q->head->next;

    if (q->head == NULL) {
