['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Task {
    char* name;
    int priority;
    double deadline;
} Task;

typedef struct TaskCollection {
    Task** tasks;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} TaskCollection;

TaskCollection* createTaskCollection(size_t initial_capacity) {
    TaskCollection* collection = (TaskCollection*)malloc(sizeof(TaskCollection));
    if (!collection) return NULL;

    collection->tasks = (Task**)malloc(initial_capacity * sizeof(Task*));
    if (!collection->tasks) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void addTask(TaskCollection* collection, const char* name, int priority, double deadline) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Task** new_tasks = (Task**)realloc(collection->tasks, new_capacity * sizeof(Task*));
        if (!new_tasks) {
            pthread_mutex_unlock(&collection->lock);
            return;
        }
        collection->tasks = new_tasks;
        collection->capacity = new_capacity;
    }

    Task* task = (Task*)malloc(sizeof(Task));
    task->name = strdup(name);
    task->priority = priority;
    task->deadline = deadline;

    collection->tasks[collection->count++] = task;

    pthread_mutex_unlock(&collection->lock);
}

int comparePriority(const void* a, const void* b) {
    Task* taskA = *(Task**)a;
    Task* taskB = *(Task**)b;
    return taskB->priority - taskA->priority; // Descending order
}

void sortTasks(TaskCollection* collection) {
    pthread_mutex_lock(&collection->lock);
    qsort(collection->tasks, collection->count, sizeof(Task*), comparePriority);
    pthread_mutex_unlock(&collection->lock);
}

void printTaskDetails(const Task* task) {
    printf("Name: %s, Priority: %d, Deadline: %.2f\n", task->name, task->priority, task->deadline);
}

void iterateAndPrintTasks(const TaskCollection* collection) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        printTaskDetails(collection->tasks[i]);
    }

    pthread_mutex_unlock(&collection->lock);
}

void freeTaskCollection(TaskCollection* collection) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->tasks[i]->name);
        free(collection->tasks[i]);
    }

    free(collection->tasks);
    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int main() {
    TaskCollection* collection = createTaskCollection(10);

    addTask(collection, "Task 1", 5, 123.45);
    addTask(collection, "Task 2", 9, 67.89);
    addTask(collection, "Task 3", 7, 234.56);

    sortTasks(collection);
    iterateAndPrintTasks(collection);

    freeTaskCollection(collection);

    return 0;
}
