['Below is a C implementation that addresses your requirements. This code includes dynamic memory management for interconnected data structures, random initialization with adaptive ranges, caching for frequently accessed records, thread safety using mutexes, resizing strategy, and a mechanism to release allocated memory safely.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>

typedef struct {
    int value;
    int* key_ptr;
} record;

typedef struct {
    long* offsets;          // Array of offset values
    int* keys;              // Array of integer keys
    record* records;        // Collection of record structures
    size_t count;           // Number of initialized records
    double total_value;     // Running total of all records' values
    pthread_mutex_t lock;   // Mutex for thread safety

    int* cache_keys;        // Cache keys for frequently accessed records
    record* cache_records;  // Cached records for fast access
    size_t cache_size;      // Current size of the cache
} data_structure;

// Function to initialize the data structure with specified initial count
data_structure* init_data_structure(size_t initial_count) {
    data_structure* ds = (data_structure*)malloc(sizeof(data_structure));
    if (!ds) return NULL;

    pthread_mutex_init(&ds->lock, NULL);

    size_t total_size = sizeof(long) * initial_count + 
                        sizeof(int) * initial_count + 
                        sizeof(record) * initial_count;

    void* mem_block = malloc(total_size);
    if (!mem_block) {
        free(ds);
        return NULL;
    }

    ds->offsets = (long*)mem_block;
    mem_block = ((char*)mem_block) + sizeof(long) * initial_count;

    ds->keys = (int*)mem_block;
    mem_block = ((char*)mem_block) + sizeof(int) * initial_count;

    ds->records = (record*)mem_block;

    for (size_t i = 0; i < initial_count; ++i) {
        ds->offsets[i] = -1;
        ds->keys[i] = rand() % 1000; // Example key initialization
        ds->records[i].value = 0;
        ds->records[i].key_ptr = &ds->keys[i];
    }

    ds->count = initial_count;
    ds->total_value = 0.0;
    ds->cache_keys = NULL;
    ds->cache_records = NULL;
    ds->cache_size = 0;

    return ds;
}

// Function to resize the data structure
int resize_data_structure(data_structure* ds, size_t new_count) {
    if (!ds || !pthread_mutex_trylock(&ds->lock)) return -1;

    size_t total_size = sizeof(long) * new_count + 
                        sizeof(int) * new_count + 
                        sizeof(record) * new_count;

    void* mem_block = realloc((char*)ds->offsets - 
                              (sizeof(long) + sizeof(int)) * ds->count,
                             total_size);
    if (!mem_block) {
        pthread_mutex_unlock(&ds->lock);
        return -1;
    }

    long* old_offsets = ds->offsets;
    int* old_keys = ds->keys;
    record* old_records = ds->records;

    ds->offsets = (long*)mem_block;
    mem_block = ((char*)mem_block) + sizeof(long) * new_count;

    ds->keys = (int*)mem_block;
    mem_block = ((char*)mem_block) + sizeof(int) * new_count;

    ds->records = (record*)mem_block;

    size_t copy_size = ds->count < new_count ? ds->count : new_count;
    for (size_t i = 0; i < copy_size; ++i) {
        ds->offsets[i] = old_offsets[i];
        ds->keys[i] = old_keys[i];
        ds->records[i].value = old_records[i].value;
        ds->records[i].key_ptr = &ds->keys[i];
    }

    if (old_offsets != ds->offsets) free(old_offsets);
    if (old_keys != ds->keys) free(old_keys);
    if (old_records != ds->records) free(old_records);

    ds->count = new_count;
    pthread_mutex_unlock(&ds->lock);
    return 0;
}

// Function to initialize records with random values
void init_random_values(data_structure* ds, size_t count) {
    if (!pthread_mutex_trylock(&ds->lock)) return;

    for (size_t i = 0; i < count; ++i) {
        double avg_value = ds->total_value / ((double)ds->count);

        // Dynamic range based on average value
        int min_val = (int)(avg_value - 50);
        int max_val = (int)(avg_value + 50);

        if (max_val <= min_val)
            max_val = min_val + 1;

        ds->records[i].value = rand() % (max_val - min_val) + min_val;
        ds->total_value += ds->records[i].value;
    }

    pthread_mutex_unlock(&ds->lock);
}

// Function to cache frequently accessed records
void update_cache(data_structure* ds, size_t count) {
    if (!pthread_mutex_trylock(&ds->lock)) return;

    // Simple caching strategy: cache the first 'cache_size' elements
    size_t new_cache_size = ds->count / 10; // Example: Cache 1/10th of records

    if (new_cache_size != ds->cache_size) {
        if (ds->cache_keys)
            free(ds->cache_keys);

        if (ds->cache_records)
            free(ds->cache_records);

        ds->cache_keys = malloc(sizeof(int) * new_cache_size);
        ds->cache_records = malloc(sizeof(record) * new_cache_size);

        for (size_t i = 0; i < new_cache_size && i < count; ++i) {
            ds->cache_keys[i] = ds->keys[i];
            ds->cache_records[i] = ds->records[i];
        }

        ds->cache_size = new_cache_size;
    }

    pthread_mutex_unlock(&ds->lock);
}

// Function to safely release all allocated memory
void free_data_structure(data_structure* ds) {
    if (!ds) return;

    if (pthread_mutex_trylock(&ds->lock)) return;

    free(ds->offsets);
    free(ds->keys);
    free(ds->records);

    if (ds->cache_keys)
        free(ds->cache_keys);

    if (ds->cache_records)
        free(ds->cache_records);

    pthread_mutex_unlock(&ds->lock);
    pthread_mutex_destroy(&ds->lock);
    free(ds);
}

// Example usage
int main() {
    data_structure* ds = init_data_structure(100);
    if (!ds) return EXIT_FAILURE;

    resize_data_structure(ds, 200);
    init_random_values(ds, 200);
    update_cache(ds, 200);

    // Monitor memory usage and performance metrics (simple example)
    printf("Total Value: %f\n", ds->total_value);

    free_data_structure(ds);
    return EXIT_SUCCESS;
}
