['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define a record structure
typedef struct {
    int key;
    long *offset;
    double value;
} Record;

// Node for linked list
typedef struct Node {
    Record data;
    struct Node *next;
} Node;

// Collection structure with synchronization mechanisms
typedef struct {
    Node *head;
    pthread_mutex_t lock; // Mutex for thread safety
    size_t node_count;
    size_t memory_usage;
} RecordCollection;

// Function to initialize the collection
void init_collection(RecordCollection *collection) {
    collection->head = NULL;
    pthread_mutex_init(&collection->lock, NULL);
    collection->node_count = 0;
    collection->memory_usage = 0;
}

// Function to calculate value based on key
double calculate_value(int key) {
    return (double)key / 2.0; // Example formula
}

// Insert a record into the collection
void insert_record(RecordCollection *collection, int key, long offset) {
    pthread_mutex_lock(&collection->lock);

    Node *new_node = malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&collection->lock);
        return;
    }

    new_node->data.key = key;
    new_node->data.offset = &offset;
    new_node->data.value = calculate_value(key);

    // Insert at the beginning for simplicity
    new_node->next = collection->head;
    collection->head = new_node;

    collection->node_count++;
    collection->memory_usage += sizeof(Node) + sizeof(Record);

    pthread_mutex_unlock(&collection->lock);
}

// Delete a record by key
void delete_record(RecordCollection *collection, int key) {
    pthread_mutex_lock(&collection->lock);

    Node *current = collection->head;
    Node *prev = NULL;

    while (current != NULL && current->data.key != key) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&collection->lock);
        return;
    }

    if (prev == NULL) {
        collection->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);

    collection->node_count--;
    collection->memory_usage -= sizeof(Node) + sizeof(Record);

    pthread_mutex_unlock(&collection->lock);
}

// Lookup a record by key
Record *lookup_record(RecordCollection *collection, int key) {
    pthread_mutex_lock(&collection->lock);

    Node *current = collection->head;
    while (current != NULL) {
        if (current->data.key == key) {
            pthread_mutex_unlock(&collection->lock);
            return &current->data;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&collection->lock);
    return NULL; // Not found
}

// Log memory usage and access patterns
void log_statistics(RecordCollection *collection) {
    pthread_mutex_lock(&collection->lock);

    printf("Memory Usage: %zu bytes\n", collection->memory_usage);
    printf("Node Count: %zu\n", collection->node_count);

    pthread_mutex_unlock(&collection->lock);
}

// Cleanup function for the collection
void cleanup_collection(RecordCollection *collection) {
    pthread_mutex_lock(&collection->lock);

    Node *current = collection->head;
    while (current != NULL) {
        Node *next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
}
```

This code provides a thread-safe implementation for managing records in a dynamic collection with efficient insertion, deletion, and lookup operations. It uses a mutex to ensure that concurrent modifications are handled safely. The function `log_statistics` logs memory usage and access patterns, which can be used for performance analysis.']

