['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_LIST_SIZE 100

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG; // Randomly set
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef void (*Callback)(int);

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    pthread_mutex_t lock;
    Callback overflow_callback;
} CRCList;

CRCList* create_crc_list(Callback callback) {
    CRCList* list = malloc(sizeof(CRCList));
    if (list) {
        list->head = NULL;
        list->count = 0;
        pthread_mutex_init(&list->lock, NULL);
        list->overflow_callback = callback;
    }
    return list;
}

int is_valid(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Example validation logic
    return pdu->RX_UE_INFORMATION_TAG >= 0 && 
           pdu->RNTI > 0 &&
           pdu->CRC_INDICATION_REL8_TAG.CRCFLAG != -1; // Assuming valid CRCFLAGS are non-negative
}

void log_message(const char* message) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), message);
}

void add_to_list(CRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!is_valid(&pdu)) {
        log_message("Error: Invalid PDU fields.");
        return;
    }

    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_LIST_SIZE) {
        if (list->overflow_callback)
            list->overflow_callback(1);
        pthread_mutex_unlock(&list->lock);
        log_message("Info: List overflow, callback notified.");
        return;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        log_message("Error: Memory allocation failed for new node.");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    memcpy(&new_node->data, &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    log_message("Info: PDU added successfully.");

    pthread_mutex_unlock(&list->lock);
}

void free_crc_list(CRCList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}
