['Below is a C code implementation for a memory-efficient database using a hash table with separate chaining, dynamic resizing, concurrency control, and other specified features:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 16
#define LOAD_FACTOR_THRESHOLD 0.75

typedef struct Record {
    int key;
    int value;
    struct Record *next;
} Record;

typedef struct HashTable {
    Record **buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

HashTable* create_hash_table(size_t initial_capacity) {
    HashTable *table = (HashTable *)malloc(sizeof(HashTable));
    table->capacity = initial_capacity;
    table->size = 0;
    table->buckets = (Record **)calloc(initial_capacity, sizeof(Record *));
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

unsigned long hash(int key, size_t capacity) {
    return ((unsigned long)key * 2654435761ul) % capacity;
}

void resize_hash_table(HashTable *table);

int insert_record(HashTable *table, int key, int value) {
    pthread_mutex_lock(&table->lock);

    if (table->size >= table->capacity * LOAD_FACTOR_THRESHOLD) {
        resize_hash_table(table);
    }

    unsigned long index = hash(key, table->capacity);
    Record *new_record = (Record *)malloc(sizeof(Record));
    new_record->key = key;
    new_record->value = value;
    new_record->next = table->buckets[index];
    table->buckets[index] = new_record;

    table->size++;

    pthread_mutex_unlock(&table->lock);
    return 0;
}

void* get_record(HashTable *table, int key) {
    unsigned long index = hash(key, table->capacity);
    pthread_mutex_lock(&table->lock);
    Record *record = table->buckets[index];
    while (record != NULL && record->key != key) {
        record = record->next;
    }
    pthread_mutex_unlock(&table->lock);
    return (void *)record;
}

void delete_record(HashTable *table, int key) {
    unsigned long index = hash(key, table->capacity);
    pthread_mutex_lock(&table->lock);

    Record *current = table->buckets[index];
    Record *prev = NULL;

    while (current != NULL && current->key != key) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&table->lock);
        return;
    }

    if (prev == NULL) {
        table->buckets[index] = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    table->size--;
    pthread_mutex_unlock(&table->lock);
}

void resize_hash_table(HashTable *table) {
    size_t new_capacity = table->capacity * 2;
    Record **new_buckets = (Record **)calloc(new_capacity, sizeof(Record *));
    for (size_t i = 0; i < table->capacity; i++) {
        Record *record = table->buckets[i];
        while (record != NULL) {
            Record *next_record = record->next;
            unsigned long new_index = hash(record->key, new_capacity);
            record->next = new_buckets[new_index];
            new_buckets[new_index] = record;
            record = next_record;
        }
    }
    free(table->buckets);
    table->buckets = new_buckets;
    table->capacity = new_capacity;
}

void compact_and_rehash(HashTable *table) {
    pthread_mutex_lock(&table->lock);

    size_t new_capacity = table->capacity / 2;
    if (new_capacity < INITIAL_CAPACITY) new_capacity = INITIAL_CAPACITY;

    Record **new_buckets = (Record **)calloc(new_capacity, sizeof(Record *));
    for (size_t i = 0; i < table->capacity; i++) {
        Record *record = table->buckets[i];
        while (record != NULL) {
            Record *next_record = record->next;
            unsigned long new_index = hash(record->key, new_capacity);
            record->next = new_buckets[new_index];
            new_buckets[new_index] = record;
            record = next_record;
        }
    }

    free(table->buckets);
    table->buckets = new_buckets;
    table->capacity = new_capacity;

    pthread_mutex_unlock(&table->lock);
}

void destroy_hash_table(HashTable *table) {
    for (size_t i = 0; i < table->capacity; i++) {
        Record *record = table->buckets[i];
        while (record != NULL) {
            Record *next_record = record->next;
            free(record);
            record = next_record;
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

int main() {
    // Example usage
    HashTable *db = create_hash_table(INITIAL_CAPACITY);

    insert_record(db, 1, rand() % 100);
    insert_record(db, 2, rand() % 100);

    Record *record = (Record *)get_record(db, 1);
    if (record != NULL) {
        printf("Key: %d, Value: %d\n", record->key, record->value);
    }

    delete_record(db, 1);
    compact_and_rehash(db);

    destroy_hash_table(db);
    return 0;
}
```

### Design Considerations:

- **Concurrency**: Thread-safe operations using `pthread_mutex_lock` and `pthread_mutex_unlock`.
- **Dynamic Resizing**: Implemented through `resize_hash_table` to maintain optimal load factors.
- **Memory Management**: Proper allocation and deallocation of records and hash table buckets.
- **Compaction and Rehashing**: Periodically reduce memory usage with `compact_and_rehash`.
- **Scalability**: Designed to handle increasing numbers of records and concurrent operations efficiently.
- **External Configuration**: Not fully implemented in this snippet but can be added via configuration parsing libraries.

This code provides a basic framework for the described database system, focusing on core functionality while leaving room for enhancements such as logging, external integration, and additional data types.']

