import csv
import json
from collections import defaultdict
import pandas as pd

def process_user_activity_logs(file_path, output_format='json', criteria=None):
    if criteria is None:
        criteria = {}

    def filter_entry(entry):
        # Filter entries based on predefined criteria like specific timestamps or user IDs
        timestamp = entry.get('timestamp')
        user_id = entry.get('user_id')

        if 'start_time' in criteria and 'end_time' in criteria:
            start_time = pd.to_datetime(criteria['start_time'])
            end_time = pd.to_datetime(criteria['end_time'])
            entry_time = pd.to_datetime(timestamp)
            if not (start_time <= entry_time <= end_time):
                return False

        if 'user_ids' in criteria and user_id not in criteria['user_ids']:
            return False

        return True

    try:
        data = []
        with open(file_path, mode='r') as file:
            reader = csv.DictReader(file)
            for row in reader:
                if filter_entry(row):
                    data.append(row)

        # Calculate metrics
        user_sessions = defaultdict(list)
        for entry in data:
            user_id = entry['user_id']
            session_duration = pd.to_timedelta(entry['session_end']) - pd.to_timedelta(entry['session_start'])
            user_sessions[user_id].append(session_duration.total_seconds())

        avg_session_durations = {user: sum(durations) / len(durations) for user, durations in user_sessions.items()}
        total_sessions = sum(len(durations) for durations in user_sessions.values())
        most_active_user = max(user_sessions, key=lambda u: len(user_sessions[u]))

        result = {
            'average_session_duration': avg_session_durations,
            'total_number_of_sessions': total_sessions,
            'most_active_users': most_active_user
        }

        if output_format == 'json':
            with open('output.json', 'w') as json_file:
                json.dump(result, json_file)

        elif output_format == 'html':
            html_content = "<html><body>"
            for user, avg_duration in result['average_session_duration'].items():
                html_content += f"<p>User {user}: Avg Session Duration: {avg_duration}s</p>"

            html_content += f"<h3>Total Sessions: {result['total_number_of_sessions']}</h3>"
            html_content += f"<h3>Most Active User: {result['most_active_users']}</h3>"
            html_content += "</body></html>"

            with open('output.html', 'w') as html_file:
                html_file.write(html_content)

        print("Processing completed successfully.")

    except Exception as e:
        print(f"An error occurred: {e}")

# Example usage
process_user_activity_logs('user_activities.csv', output_format='json', criteria={'start_time': '2023-01-01', 'end_time': '2023-12-31', 'user_ids': ['12345', '67890']})
