// Define the structure as described in the task.
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRC_FLAG;  // Assuming a flag for CRC status
} NFAPI_CRC_INDICATION_PDU_T;

// Define the dynamic array manager with thread safety.
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArrayManager;

// Function prototypes
DynamicArrayManager* create_dynamic_array_manager(size_t initial_capacity);
void destroy_dynamic_array_manager(DynamicArrayManager *manager);
int add_entry(DynamicArrayManager *manager, NFAPI_CRC_INDICATION_PDU_T entry);
int remove_entry_by_rnti(DynamicArrayManager *manager, int rnti);
int update_crc_flag(DynamicArrayManager *manager, int rnti, int new_crc_flag);
static void resize_if_needed(DynamicArrayManager *manager);

// Implementation
DynamicArrayManager* create_dynamic_array_manager(size_t initial_capacity) {
    DynamicArrayManager *manager = malloc(sizeof(DynamicArrayManager));
    if (!manager) return NULL;

    pthread_mutex_init(&manager->lock, NULL);
    manager->capacity = initial_capacity;
    manager->size = 0;
    manager->array = calloc(manager->capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        free(manager);
        return NULL;
    }

    return manager;
}

void destroy_dynamic_array_manager(DynamicArrayManager *manager) {
    pthread_mutex_destroy(&manager->lock);
    free(manager->array);
    free(manager);
}

int add_entry(DynamicArrayManager *manager, NFAPI_CRC_INDICATION_PDU_T entry) {
    if (!manager || !entry) return -1;

    pthread_mutex_lock(&manager->lock);

    resize_if_needed(manager);

    memcpy(&manager->array[manager->size], &entry, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->size++;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int remove_entry_by_rnti(DynamicArrayManager *manager, int rnti) {
    if (!manager || manager->size == 0) return -1;

    pthread_mutex_lock(&manager->lock);

    size_t i;
    for (i = 0; i < manager->size; ++i) {
        if (manager->array[i].RNTI == rnti) break;
    }

    if (i == manager->size) { // RNTI not found
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    for (; i < manager->size - 1; ++i) {
        memcpy(&manager->array[i], &manager->array[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    manager->size--;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int update_crc_flag(DynamicArrayManager *manager, int rnti, int new_crc_flag) {
    if (!manager || manager->size == 0) return -1;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->array[i].RNTI == rnti) {
            manager->array[i].CRC_FLAG = new_crc_flag;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1;
}

static void resize_if_needed(DynamicArrayManager *manager) {
    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity == 0 ? 2 : manager->capacity * 2;

        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) return; // Handle memory allocation failure gracefully

        manager->array = new_array;
        manager->capacity = new_capacity;
    }
}
