#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the NFAPI_CRC_INDICATION_PDU_T structure
typedef struct CRC_INDICATION_REL8_TAG {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct RX_UE_INFORMATION_TAG {
    // Add necessary fields here
} RX_UE_INFORMATION_TAG;

typedef struct RNTI {
    unsigned long value;  // Assuming RNTI is a numeric type, adjust as needed
} RNTI;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

// Linked list structure with head and size
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    size_t size;
    pthread_mutex_t mutex;  // Mutex for thread safety
    pthread_rwlock_t rwlock;  // Read-write lock for better concurrency
} LinkedList;

// Function to create a new node
static NFAPI_CRC_INDICATION_PDU_T* create_node(const RX_UE_INFORMATION_TAG *rx_ue_info_tag, const RNTI *rnti) {
    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) return NULL;

    new_node->rx_ue_info_tag = *rx_ue_info_tag;
    new_node->rnti = *rnti;
    new_node->crc_indication_rel8_tag.CRCFLAG = rand() % 2;  // Randomly set CRCFLAG
    new_node->next = NULL;

    return new_node;
}

// Function to check if RNTI already exists in the list
static int rnti_exists(LinkedList *list, const RNTI *rnti) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        if (current->rnti.value == rnti->value) return 1;
        current = current->next;
    }
    return 0;
}

// Function to add a node to the linked list
int add_to_list(LinkedList *list, const RX_UE_INFORMATION_TAG *rx_ue_info_tag, const RNTI *rnti) {
    if (list->size >= 1000) return -1;  // Maximum size check

    pthread_rwlock_wrlock(&list->rwlock);
    if (rnti_exists(list, rnti)) {
        pthread_rwlock_unlock(&list->rwlock);
        return -2;  // RNTI already exists
    }

    NFAPI_CRC_INDICATION_PDU_T *new_node = create_node(rx_ue_info_tag, rnti);
    if (!new_node) {
        pthread_rwlock_unlock(&list->rwlock);
        return -3;  // Memory allocation failed
    }

    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    pthread_rwlock_unlock(&list->rwlock);
    return 0;  // Success
}

// Function to free the linked list
void free_list(LinkedList *list) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->size = 0;
}

// Main function to manage the linked list
NFAPI_CRC_INDICATION_PDU_T* manage_crc_list(const RX_UE_INFORMATION_TAG **rx_ue_info_tags, const RNTI **rntis, size_t count) {
    if (count > 10000) return NULL;  // Maximum elements check

    LinkedList *list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    pthread_rwlock_init(&list->rwlock, NULL);

    for (size_t i = 0; i < count; ++i) {
        int result = add_to_list(list, &rx_ue_info_tags[i], &rntis[i]);
        if (result != 0) {
            free_list(list);
            pthread_mutex_destroy(&list->mutex);
            pthread_rwlock_destroy(&list->rwlock);
            free(list);
            return NULL;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T *head = list->head;

    // Clean up
    pthread_mutex_destroy(&list->mutex);
    pthread_rwlock_destroy(&list->rwlock);
    free(list);

    return head;  // Return the head of the list
}
