import "lz4/lz4.h"  // Assuming LZ4 compression library

typedef struct {
    char nas_message[1024];
    char rrc_connection_reconfiguration[2048];
} LTE_RRC_Message;

#define MAX_MESSAGES 10000
#define COMPRESSION_LEVEL 1  // Example compression level, can be adjusted dynamically

pthread_mutex_t message_lock = PTHREAD_MUTEX_INITIALIZER;
LTE_RRC_Message messages[MAX_MESSAGES];
int message_count = 0;

void log_message_update(const char* operation, int index) {
    printf("Log: %s at index %d\n", operation, index);
}

// Function to add or update an LTE_RRC_Message
void update_message(int index, const LTE_RRC_Message* new_message, int compress) {
    pthread_mutex_lock(&message_lock);

    if (index < 0 || index >= MAX_MESSAGES) {
        printf("Error: Index out of bounds.\n");
        pthread_mutex_unlock(&message_lock);
        return;
    }

    log_message_update("Update", index);

    if (compress) {
        // Compress the message
        int nas_size = compress_lz4(new_message->nas_message, messages[index].nas_message, sizeof(messages[index].nas_message), COMPRESSION_LEVEL);
        int rrc_size = compress_lz4(new_message->rrc_connection_reconfiguration, messages[index].rrc_connection_reconfiguration, sizeof(messages[index].rrc_connection_reconfiguration), COMPRESSION_LEVEL);

        // Handle possible compression failures
        if (nas_size < 0 || rrc_size < 0) {
            printf("Compression failed.\n");
            pthread_mutex_unlock(&message_lock);
            return;
        }
    } else {
        // Copy the message without compression
        strcpy(messages[index].nas_message, new_message->nas_message);
        strcpy(messages[index].rrc_connection_reconfiguration, new_message->rrc_connection_reconfiguration);
    }

    pthread_mutex_unlock(&message_lock);
}

// Function to read an LTE_RRC_Message with optional decompression
void get_message(int index, LTE_RRC_Message* out_message, int decompress) {
    pthread_mutex_lock(&message_lock);

    if (index < 0 || index >= MAX_MESSAGES) {
        printf("Error: Index out of bounds.\n");
        pthread_mutex_unlock(&message_lock);
        return;
    }

    log_message_update("Read", index);

    if (decompress) {
        // Decompress the message
        int nas_size = decompress_lz4(messages[index].nas_message, out_message->nas_message, sizeof(out_message->nas_message));
        int rrc_size = decompress_lz4(messages[index].rrc_connection_reconfiguration, out_message->rrc_connection_reconfiguration, sizeof(out_message->rrc_connection_reconfiguration));

        if (nas_size < 0 || rrc_size < 0) {
            printf("Decompression failed.\n");
            pthread_mutex_unlock(&message_lock);
            return;
        }
    } else {
        // Copy the message without decompression
        strcpy(out_message->nas_message, messages[index].nas_message);
        strcpy(out_message->rrc_connection_reconfiguration, messages[index].rrc_connection_reconfiguration);
    }

    pthread_mutex_unlock(&message_lock);
}

