#include <stdio.h>
#include <stdlib.h>
import <pthread.h>
#include <errno.h>

#define MAX_DATA_RECORDS 1024

typedef struct {
    int unique_value;
    char *metadata;
} DataRecord;

typedef enum {
    MODE_CONSERVATIVE,
    MODE_AGGRESSIVE
} ProcessingMode;

typedef struct {
    pthread_mutex_t lock;
    pthread_cond_t cond;
    DataRecord **data_records;
    size_t capacity;
    size_t count;
    ProcessingMode mode;
    int network_status; // 0 for stable, non-zero for issues
} DataManager;

void initialize_data_manager(DataManager *manager) {
    manager->capacity = MAX_DATA_RECORDS;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    pthread_cond_init(&manager->cond, NULL);
    manager->data_records = (DataRecord **)malloc(manager->capacity * sizeof(DataRecord *));
    if (!manager->data_records) {
        perror("Failed to allocate memory for data records");
        exit(EXIT_FAILURE);
    }
}

void destroy_data_manager(DataManager *manager) {
    pthread_mutex_destroy(&manager->lock);
    pthread_cond_destroy(&manager->cond);
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->data_records[i]->metadata);
        free(manager->data_records[i]);
    }
    free(manager->data_records);
}

void *process_data(void *arg) {
    DataManager *manager = (DataManager *)arg;

    while (1) { // Loop for continuous processing
        pthread_mutex_lock(&manager->lock);

        if (manager->network_status != 0) {
            printf("Network issue detected, switching to conservative mode\n");
            manager->mode = MODE_CONSERVATIVE;
        } else if (manager->count > manager->capacity / 2) {
            printf("High load detected, switching to aggressive mode\n");
            manager->mode = MODE_AGGRESSIVE;
        }

        // Simulate data processing
        for (size_t i = 0; i < manager->count; ++i) {
            // Process data record here...
            // Example: Adjust processing based on the mode
            if (manager->mode == MODE_CONSERVATIVE) {
                printf("Processing %d in conservative mode\n", manager->data_records[i]->unique_value);
            } else {
                printf("Processing %d in aggressive mode\n", manager->data_records[i]->unique_value);
            }
        }

        pthread_cond_wait(&manager->cond, &manager->lock);

        // Adjust processing strategy based on load or network status
        if (manager->mode == MODE_CONSERVATIVE && manager->count < manager->capacity / 4) {
            printf("Low load detected, switching to conservative mode\n");
            manager->mode = MODE_CONSERVATIVE;
        }

        pthread_mutex_unlock(&manager->lock);
    }
    return NULL;
}

int add_data_record(DataManager *manager, int unique_value, const char *metadata) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        printf("Data capacity reached, unable to add more records\n");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    DataRecord *record = (DataRecord *)malloc(sizeof(DataRecord));
    record->unique_value = unique_value;
    record->metadata = strdup(metadata);

    if (!record || !record->metadata) {
        perror("Failed to allocate memory for data record");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    manager->data_records[manager->count++] = record;

    printf("Added data record with unique value %d\n", unique_value);

    pthread_cond_signal(&manager->cond);
    pthread_mutex_unlock(&manager->lock);

    return 0;
}

void simulate_network_change(DataManager *manager, int status) {
    pthread_mutex_lock(&manager->lock);
    manager->network_status = status;
    printf("Network status changed to %d\n", status);
    pthread_cond_signal(&manager->cond);
    pthread_mutex_unlock(&manager->lock);
}
```

This code sets up a `DataManager` structure to manage data records with thread-safe mechanisms, supports dynamic mode switching based on network conditions, and includes error handling. It uses POSIX threads for concurrency and synchronization.']

