    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

// Global variables and mutex for thread safety
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T *head = NULL;
uint64_t crc_count_success = 0;
uint64_t crc_count_failure = 0;

// Logging function (thread-safe)
void log_message(const char* level, const char* message) {
    static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&log_mutex);
    printf("[%s] %s\n", level, message);
    pthread_mutex_unlock(&log_mutex);
}

// Function to create a new NFAPI_CRC_INDICATION_PDU_T structure
NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu() {
    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) {
