    new_node->rnti = rand() % 1000; // Example value
    new_node->crc_indication_rel8_tag.CRCFLAG = rand() % 2;

    log_message("INFO", "Created new CRC indication PDU");
    return new_node;
}

// Function to add a node to the linked list
void add_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *node) {
    pthread_mutex_lock(&list_mutex);
    node->next = head;
    head = node;
    pthread_mutex_unlock(&list_mutex);

    crc_count_success++;
    log_message("INFO", "Added new CRC indication PDU to list");
}

// Function to free the linked list
void free_crc_indication_list() {
    pthread_mutex_lock(&list_mutex);
    NFAPI_CRC_INDICATION_PDU_T *current = head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        log_message("INFO", "Freed CRC indication PDU");
        current = next;
    }
    head = NULL;
    pthread_mutex_unlock(&list_mutex);

    log_message("INFO", "All CRC indications freed");
}

// Function to dynamically populate the list
void populate_crc_indication_list(int num_elements) {
    for (int i = 0; i < num_elements; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *node = create_crc_indication_pdu();
        if (!node) {
            crc_count_failure++;
            continue;
        }
        add_crc_indication_pdu(node);
    }
}

// Reporting function
void report_performance() {
    log_message("INFO", "Reporting performance metrics");
    printf("CRC Indications Successfully Processed: %lu\n", crc_count_success);
    printf("CRC Indications Failed Due to Errors: %lu\n", crc_count_failure);
}

int main() {
    srand(time(NULL));

    int num_elements = 10; // Example number of elements
    populate_crc_indication_list(num_elements);

    report_performance();

    free_crc_indication_list();
    return 0;
}
