// Structure to define a vertex
typedef struct Vertex {
    int id;
    long offset;
} Vertex;

// Structure to define an edge record with weight
typedef struct EdgeRecord {
    int weight;
} EdgeRecord;

// Structure to define an edge
typedef struct Edge {
    int source;
    int target;
    EdgeRecord *record;
} Edge;

// Structure for a dynamic graph
typedef struct Graph {
    Vertex **vertices;
    Edge **edges;
    int vertexCount;
    int edgeCount;
    size_t maxVertices;
    size_t maxEdges;
} Graph;

Graph* createGraph(size_t initialCapacity) {
    Graph *graph = malloc(sizeof(Graph));
    if (!graph) return NULL;

    graph->vertices = calloc(initialCapacity, sizeof(Vertex *));
    graph->edges = calloc(initialCapacity, sizeof(Edge *));
    graph->vertexCount = 0;
    graph->edgeCount = 0;
    graph->maxVertices = initialCapacity;
    graph->maxEdges = initialCapacity;

    return graph;
}

void resizeGraph(Graph *graph) {
    if (graph->vertexCount >= graph->maxVertices || graph->edgeCount >= graph->maxEdges) {
        size_t newMaxVertices = graph->maxVertices * 2;
        size_t newMaxEdges = graph->maxEdges * 2;

        Vertex **newVertices = realloc(graph->vertices, newMaxVertices * sizeof(Vertex *));
        Edge **newEdges = realloc(graph->edges, newMaxEdges * sizeof(Edge *));

        if (!newVertices || !newEdges) {
            free(newVertices);
            free(newEdges);
            fprintf(stderr, "Memory allocation failed during graph resize.\n");
            exit(EXIT_FAILURE);
        }

        graph->vertices = newVertices;
        graph->edges = newEdges;
        graph->maxVertices = newMaxVertices;
        graph->maxEdges = newMaxEdges;
    }
}

Vertex* addVertex(Graph *graph, int id, long offset) {
    resizeGraph(graph);

    Vertex *vertex = malloc(sizeof(Vertex));
    if (!vertex) {
        fprintf(stderr, "Memory allocation failed for vertex.\n");
        exit(EXIT_FAILURE);
    }

    vertex->id = id;
    vertex->offset = offset;

    graph->vertices[graph->vertexCount++] = vertex;
    return vertex;
}

Edge* addEdge(Graph *graph, int sourceId, int targetId, int weight) {
    resizeGraph(graph);

    Vertex *source = NULL;
    Vertex *target = NULL;

    for (int i = 0; i < graph->vertexCount; ++i) {
        if (graph->vertices[i]->id == sourceId) source = graph->vertices[i];
        if (graph->vertices[i]->id == targetId) target = graph->vertices[i];
    }

    if (!source || !target) {
        fprintf(stderr, "Invalid vertex ID(s).\n");
        return NULL;
    }

    Edge *edge = malloc(sizeof(Edge));
    if (!edge) {
        fprintf(stderr, "Memory allocation failed for edge.\n");
        exit(EXIT_FAILURE);
    }

    edge->source = sourceId;
    edge->target = targetId;

    EdgeRecord *record = malloc(sizeof(EdgeRecord));
    if (!record) {
        free(edge);
        fprintf(stderr, "Memory allocation failed for edge record.\n");
        exit(EXIT_FAILURE);
    }

    record->weight = weight;
    edge->record = record;

    graph->edges[graph->edgeCount++] = edge;
    return edge;
}

void initializeRandomWeights(Graph *graph, int minWeight, int maxWeight) {
    srand((unsigned int)time(NULL));
    for (int i = 0; i < graph->edgeCount; ++i) {
        Edge *edge = graph->edges[i];
        bool unique;

        do {
            unique = true;
            edge->record->weight = rand() % (maxWeight - minWeight + 1) + minWeight;

            for (int j = 0; j < i; ++j) {
                if (graph->edges[j]->record->weight == edge->record->weight) {
                    unique = false;
                    break;
                }
            }
        } while (!unique);
    }
}

