    addVertex(myGraph, 1, 100L);
    addVertex(myGraph, 2, 200L);

    initializeRandomWeights(myGraph, 1, 100);

    addEdge(myGraph, 1, 2, myGraph->edges[0]->record->weight);

    breadthFirstSearch(myGraph, 1); // Example traversal call

    // Cleanup
    for (int i = 0; i < myGraph->vertexCount; ++i) {
        free(myGraph->vertices[i]);
    }
    for (int i = 0; i < myGraph->edgeCount; ++i) {
