    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node *next;
} Node;

int is_unique_rnti(int rnti, Node **head) {
    Node *current = *head;
    while (current != NULL) {
        if (current->data.RNTI == rnti)
            return 0;
        current = current->next;
    }
    return 1;
}

void append_node(Node **head, NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node *new_node = (Node *)malloc(sizeof(Node));
    if (!new_node) exit(1);
    new_node->data = pdu;
    new_node->next = NULL;

    if (*head == NULL) {
        *head = new_node;
    } else {
        Node *current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

NFAPI_CRC_INDICATION_PDU_T create_pdu(int index, int rnti) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
