    pdu.CRC_INDICATION_REL8_TAG = index * 10; // Example logic
    pdu.CRCFLAG = (rand() / (float)RAND_MAX < CRCFLAG_PROBABILITY);
    return pdu;
}

void reverse_list(Node **head) {
    Node *prev = NULL, *current = *head, *next_node = NULL;
    while (current != NULL) {
        next_node = current->next;
        current->next = prev;
        prev = current;
        current = next_node;
    }
    *head = prev;
}

void print_list(Node *head) {
    Node *current = head;
    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n",
               current->data.RX_UE_INFORMATION_TAG,
               current->data.RNTI,
               current->data.CRC_INDICATION_REL8_TAG,
               current->data.CRCFLAG);
        current = current->next;
    }
}

int find_largest(int *arr, int size) {
    int largest = arr[0];
    for (int i = 1; i < size; ++i) {
        if (arr[i] > largest)
            largest = arr[i];
    }
    return largest;
}

void process_integers(Node **head) {
    srand(time(NULL));
    int *array = NULL, array_size = 0;

    printf("Enter integers (end with a non-integer):\n");
    while (1) {
        if (scanf("%d", &array_size) != 1) break;
        if (array_size < 0 || array_size > MAX_ARRAY_SIZE) {
            printf("Invalid input. Must be between 0 and %d.\n", MAX_ARRAY_SIZE);
            continue;
        }

        int *new_array = realloc(array, sizeof(int) * (array_size + 1));
        if (!new_array) exit(1);
        array = new_array;

        for (int i = 0; i < array_size; ++i) {
            if (scanf("%d", &array[i]) != 1) break;
        }
        array[array_size] = -1; // Sentinel value
    }

    int largest = find_largest(array, array_size);
    printf("Largest integer: %d\n", largest);

    for (int i = 0; i < array_size; ++i) {
        if (is_unique_rnti(array[i], head)) {
            NFAPI_CRC_INDICATION_PDU_T pdu = create_pdu(i, array[i]);
            append_node(head, pdu);
        }
    }

    printf("List before reversal:\n");
    print_list(*head);

    reverse_list(head);

    printf("List after reversal:\n");
    print_list(*head);

    free(array);
}

int main() {
    Node *head = NULL;
    process_integers(&head);

    // Free the linked list
    while (head != NULL) {
        Node *temp = head;
        head = head->next;
        free(temp);
    }

    return 0;
}
