void* memory_pool_alloc(MemoryPool *mp) {
    pthread_mutex_lock(&mp->lock);

    if (mp->used_blocks >= mp->total_blocks) {
        pthread_mutex_unlock(&mp->lock);
        return NULL; // Out of memory
    }

    void *block = ((char*)mp->pool) + (mp->used_blocks++ * mp->block_size);
    pthread_mutex_unlock(&mp->lock);

    return block;
}

void initialize_packet_manager(PacketManager **manager) {
    *manager = malloc(sizeof(PacketManager));
    if (!*manager) return;

    (*manager)->packets = malloc(MAX_PACKETS * sizeof(Packet *));
    if (!(*manager)->packets) {
        free(*manager);
        return;
    }

    (*manager)->count = 0;
    pthread_mutex_init(&(*manager)->lock, NULL);
    (*manager)->current_capacity = MAX_PACKETS;

    // Initialize memory pool for packet data
    MemoryPool *mp = create_memory_pool(1024, 100); // Example values
    if (!mp) {
        free((*manager)->packets);
        free(*manager);
        return;
    }
    (*manager)->memory_pool = mp;

    // Open log file
    (*manager)->log_file = fopen("packet_log.txt", "a");
    if (!(*manager)->log_file) {
        free(mp->pool);
        pthread_mutex_destroy(&mp->lock);
        free(mp);
        free((*manager)->packets);
        free(*manager);
        return;
    }

    // Start background threads
    pthread_create(&(*manager)->cleaner_thread, NULL, packet_cleaner, *manager);
    pthread_create(&(*manager)->monitor_thread, NULL, performance_monitor, *manager);

    // Additional initialization for plugins and load balancing...
}

void* packet_cleaner(void *arg) {
    PacketManager *manager = (PacketManager *)arg;
    while (1) {
        sleep(60); // Run every minute

        pthread_mutex_lock(&manager->lock);
        if (manager->count > manager->current_capacity / 2) {
            for (int i = manager->count - manager->current_capacity / 4; i < manager->count; ++i) {
                free(manager->packets[i]->data);
                free(manager->packets[i]);
                --manager->count;
            }
        }
        pthread_mutex_unlock(&manager->lock);
    }
}

void* performance_monitor(void *arg) {
    PacketManager *manager = (PacketManager *)arg;
    while (1) {
        sleep(10); // Run every 10 seconds

        pthread_mutex_lock(&manager->lock);
        printf("Current packet count: %d\n", manager->count);
        // Additional metrics logging...
        pthread_mutex_unlock(&manager->lock);
    }
}

int add_packet(PacketManager *manager, const char *data, size_t data_size) {
    if (!data || data_size == 0) return -1;

    void *packet_data = memory_pool_alloc(manager->memory_pool);
    if (!packet_data) return -2; // Out of memory

    time_t current_time;
    time(&current_time);

    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->current_capacity) {
        pthread_mutex_unlock(&manager->lock);
        return -3; // Array full
    }

    Packet *packet = malloc(sizeof(Packet));
    if (!packet) {
        free(packet_data);
        pthread_mutex_unlock(&manager->lock);
        return -4;
    }

    packet->timestamp = current_time;
    packet->packet_size = data_size;
    memcpy(packet_data, data, data_size);
    packet->data = packet_data;

    manager->packets[manager->count++] = packet;

    // Logging
    if (manager->log_file) {
        fprintf(manager->log_file, "Packet added: timestamp=%ld size=%zu\n", current_time, data_size);
        fflush(manager->log_file);
    }

    pthread_mutex_unlock(&manager->lock);

    return 0;
}

void get_packet_summary(PacketManager *manager, int *total_count, double *average_size, double *malformed_ratio) {
    pthread_mutex_lock(&manager->lock);

    *total_count = manager->count;
    size_t total_size = 0;
    int malformed_count = 0;

    for (int i = 0; i < manager->count; ++i) {
        Packet *packet = manager->packets[i];
        total_size += packet->packet_size;
        if (!is_packet_valid(packet)) { // Assume this function checks validity
            malformed_count++;
        }
    }

    pthread_mutex_unlock(&manager->lock);

    *average_size = (total_count > 0) ? (double)total_size / manager->count : 0.0;
    *malformed_ratio = (total_count > 0) ? (double)malformed_count / manager->count : 0.0;
}

int main() {
    PacketManager *manager;
    initialize_packet_manager(&manager);

    // Example packet addition
    const char *packet_data = "Example data";
    add_packet(manager, packet_data, strlen(packet_data));

    int total_packets;
    double avg_size, malformed_ratio;
    get_packet_summary(manager, &total_packets, &avg_size, &malformed_ratio);

    printf("Total packets: %d\n", total_packets);
    printf("Average size: %.2f\n", avg_size);
    printf("Malformed ratio: %.2f\n", malformed_ratio);

    return 0;
}
