#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_CAPACITY 1024

typedef enum {
    STATUS_OK,
    STATUS_ERROR
} StatusFlag;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    StatusFlag STATUS_FLAG;
} PHY_RX_BUFFER_INFO_TAG_T;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    PHY_RX_BUFFER_INFO_TAG_T PHY_RX_BUFFER_INFO_TAG;
} NFAPI_RX_BUFFER_INFO_PDU_T;

typedef struct Node {
    NFAPI_RX_BUFFER_INFO_PDU_T data;
    time_t timestamp; // For removed history
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    size_t capacity;
    int priority_configured;
    int history_enabled;
    pthread_mutex_t lock;
    float average_memory_usage;
    time_t last_report_time;
    double total_memory_allocated; // For average calculation
} DynamicList;

DynamicList* create_list(size_t initial_capacity, int max_capacity, int priority_configured, int history_enabled) {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->head = NULL;
    list->count = 0;
    list->capacity = initial_capacity;
    list->priority_configured = priority_configured;
    list->history_enabled = history_enabled;
    pthread_mutex_init(&list->lock, NULL);
    list->average_memory_usage = 0.0f;
    list->last_report_time = time(NULL);
    list->total_memory_allocated = 0.0;

    return list;
}

int add_entry(DynamicList* list, NFAPI_RX_BUFFER_INFO_PDU_T entry) {
    if (list->count >= list->capacity) return -1; // Capacity reached

    pthread_mutex_lock(&list->lock);

    Node** current = &(list->head);
    while (*current && list->priority_configured && (*current)->data.RX_UE_INFORMATION_TAG > entry.RX_UE_INFORMATION_TAG) {
        current = &((*current)->next);
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }

    list->total_memory_allocated += sizeof(Node);

    new_node->data = entry;
    new_node->next = *current;
    *current = new_node;

    list->count++;
    compact_list(list);  // Call compaction after addition

    pthread_mutex_unlock(&list->lock);
    return 0; 
}

int remove_entry_by_rnti(DynamicList* list, int rnti) {
    pthread_mutex_lock(&list->lock);

    Node **current = &(list->head), *temp;
    while (*current && (*current)->data.RNTI != rnti) {
        current = &((*current)->next);
    }

    if (!*current) { // Entry not found
        pthread_mutex_unlock(&list->lock);
        return -1; 
    }

    temp = *current;
    *current = (*current)->next;

    free(temp);

    list->count--;
    compact_list(list);  // Call compaction after removal

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int update_status_flag(DynamicList* list, int rnti, StatusFlag new_status) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current && current->data.RNTI != rnti) {
        current = current->next;
    }

    if (!current) { // Entry not found
        pthread_mutex_unlock(&list->lock);
        return -1; 
    }

    current->data.PHY_RX_BUFFER_INFO_TAG.STATUS_FLAG = new_status;
    compact_list(list);  // Call compaction after update

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void compact_list(DynamicList* list) {
    Node **current = &(list->head), *temp, *prev = NULL;

    while (*current) {
        if ((*current)->data.PHY_RX_BUFFER_INFO_TAG.STATUS_FLAG == STATUS_ERROR) {
            temp = *current;
            *current = (*current)->next;
            free(temp);
            list->count--;
        } else {
            current = &((*current)->next);
            prev = *current;
        }
    }
}

void export_list_to_binary(DynamicList* list, FILE* file) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current) {
        fwrite(&(current->data), sizeof(NFAPI_RX_BUFFER_INFO_PDU_T), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

int get_entry_count(DynamicList* list) {
    return list->count;
}

void calculate_average_memory_usage(DynamicList* list) {
    time_t now = time(NULL);
    if (now - list->last_report_time >= 60) { // Calculate every minute
        pthread_mutex_lock(&list->lock);

        float avg_memory = list->total_memory_allocated / ((double)(now - list->last_report_time));
        printf("Average memory usage: %f bytes\n", avg_memory);

        list->average_memory_usage = avg_memory;
        list->total_memory_allocated = 0.0;
        list->last_report_time = now;

        pthread_mutex_unlock(&list->lock);
    }
}

// Note: You need to implement the removal history and merging of two lists as described.
// For asynchronous export, you can use pthread_create and handle it similarly.

void free_list(DynamicList* list) {
    Node *current = list->head;
    while (current) {
        Node *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}
