#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_SIZE 10
#define MEMORY_THRESHOLD_UPPER 10000
#define MEMORY_THRESHOLD_LOWER 1000

typedef struct {
    int value;
    int *key;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    int total_value_sum;
    int cache_hits;
    int cache_misses;
} DataManager;

DataManager* create_data_manager() {
    DataManager *dm = (DataManager*)malloc(sizeof(DataManager));
    dm->capacity = INITIAL_SIZE;
    dm->count = 0;
    dm->offsets = malloc(dm->capacity * sizeof(long));
    dm->keys = malloc(dm->capacity * sizeof(int));
    dm->records = malloc(dm->capacity * sizeof(record));

    pthread_mutex_init(&dm->lock, NULL);
    dm->total_value_sum = 0;
    dm->cache_hits = 0;
    dm->cache_misses = 0;

    return dm;
}

void resize_data_manager(DataManager *dm) {
    size_t new_capacity = (dm->count < MEMORY_THRESHOLD_LOWER)
        ? INITIAL_SIZE
        : (dm->capacity * 2 <= MEMORY_THRESHOLD_UPPER)
          ? dm->capacity * 2
          : MEMORY_THRESHOLD_UPPER;

    long *new_offsets = realloc(dm->offsets, new_capacity * sizeof(long));
    int *new_keys = realloc(dm->keys, new_capacity * sizeof(int));
    record *new_records = realloc(dm->records, new_capacity * sizeof(record));

    if (!new_offsets || !new_keys || !new_records) {
        perror("Failed to resize memory");
        exit(EXIT_FAILURE);
    }

    dm->offsets = new_offsets;
    dm->keys = new_keys;
    dm->records = new_records;
    dm->capacity = new_capacity;
}

void initialize_record(record *rec, int key_value, int average_range) {
    rec->value = rand() % (average_range * 2) - average_range + 1;
    rec->key = &key_value;
}

void add_record(DataManager *dm, int key) {
    pthread_mutex_lock(&dm->lock);

    if (dm->count >= dm->capacity) {
        resize_data_manager(dm);
    }

    long offset = sizeof(long) * dm->count + sizeof(int) * dm->count + sizeof(record) * dm->count;
    dm->offsets[dm->count] = offset;

    initialize_record(&dm->records[dm->count], key, (dm->total_value_sum / (dm->count ? dm->count : 1)));

    dm->keys[dm->count] = key;
    dm->total_value_sum += dm->records[dm->count].value;

    dm->count++;
    pthread_mutex_unlock(&dm->lock);
}

void release_data_manager(DataManager *dm) {
    free(dm->offsets);
    free(dm->keys);
    free(dm->records);
    pthread_mutex_destroy(&dm->lock);
    free(dm);
}

// Logging utility
void log_performance(const DataManager *dm) {
    printf("Capacity: %zu, Count: %zu, Cache Hits: %d, Cache Misses: %d\n",
           dm->capacity, dm->count, dm->cache_hits, dm->cache_misses);
}

// Example usage within a larger system
void batch_add_records(DataManager *dm, int *keys, size_t num_keys) {
    for (size_t i = 0; i < num_keys; ++i) {
        add_record(dm, keys[i]);
    }

    log_performance(dm);

    // Simulate interaction with external database and cache mechanism
}

int main() {
    srand(time(NULL));

    DataManager *dm = create_data_manager();
    int keys[] = {1, 2, 3, 4, 5};
    batch_add_records(dm, keys, sizeof(keys) / sizeof(int));

    release_data_manager(dm);
    return 0;
}
```

