#define MAX_RETRIES 3
#define TIMEOUT_SECONDS 2

typedef struct {
    int value;
} record;

void log_warning(const char *message) {
    fprintf(stderr, "Warning: %s\n", message);
}

int get_metadata_from_external_source(int *metadata) {
    // Simulated external data source interaction with retry logic
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        // Simulate a network call or database query here
        // For simulation, we'll just return a dummy value
        *metadata = rand() % 100;
        if (*metadata > 0) { // Assume success if metadata is positive
            return 1;
        }
        sleep(TIMEOUT_SECONDS);
    }
    return 0; // Failure after retries
}

void initialize_offsets(const char *file_path, long **offsets, size_t size) {
    FILE *file = fopen(file_path, "r");
    if (!file) {
        perror("Failed to open file");
        exit(EXIT_FAILURE);
    }

    *offsets = malloc(size * sizeof(long));
    if (*offsets == NULL) {
        perror("Memory allocation failed for offsets");
        fclose(file);
        exit(EXIT_FAILURE);
    }

    size_t count = 0;
    while (count < size && fscanf(file, "%ld", &(*offsets)[count]) != EOF) {
        ++count;
    }

    if (ferror(file)) {
        perror("Error reading file");
    }
    fclose(file);

    // Initialize remaining elements to zero
    for (size_t i = count; i < size; ++i) {
        (*offsets)[i] = 0;
    }
}

void initialize_keys(int **keys, size_t size, int min_key, int max_key) {
    if (min_key > max_key) {
        log_warning("Invalid key range");
        *keys = NULL;
        return;
    }

    srand(time(NULL)); // Consistent seed for reproducibility
    *keys = malloc(size * sizeof(int));
    if (*keys == NULL) {
        perror("Memory allocation failed for keys");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < size; ++i) {
        (*keys)[i] = rand() % (max_key - min_key + 1) + min_key;
    }
}

void initialize_records(record **records, size_t size, int min_value, int max_value) {
    if (min_value > max_value) {
        perror("Invalid value range");
        exit(EXIT_FAILURE);
    }

    *records = malloc(size * sizeof(record));
    if (*records == NULL) {
        perror("Memory allocation failed for records");
        exit(EXIT_FAILURE);
    }

    int metadata;
    if (!get_metadata_from_external_source(&metadata)) {
        fprintf(stderr, "Failed to retrieve metadata from external source\n");
        free(*records);
        *records = NULL;
        return;
    }

    for (size_t i = 0; i < size; ++i) {
        (*records)[i].value = rand() % (max_value - min_value + 1) + min_value + metadata;
    }
}

record* manage_memory_allocation(size_t offsets_size, const char *file_path,
                                 size_t keys_size, int min_key, int max_key,
                                 size_t records_size, int min_value, int max_value) {
    long *offsets = NULL;
    int *keys = NULL;
    record *records = NULL;

    initialize_offsets(file_path, &offsets, offsets_size);
    initialize_keys(&keys, keys_size, min_key, max_key);
    initialize_records(&records, records_size, min_value, max_value);

    // Free resources if any allocation failed
    if (!records) {
        free(offsets);
        free(keys);
    }

    return records;
}

int main() {
    const char *file_path = "input.txt";
    size_t offsets_size = 10;
    size_t keys_size = 5;
    int min_key = 1, max_key = 100;
    size_t records_size = 8;
    int min_value = 0, max_value = 50;

    record *records = manage_memory_allocation(offsets_size, file_path,
                                               keys_size, min_key, max_key,
                                               records_size, min_value, max_value);

    if (records) {
        for (size_t i = 0; i < records_size; ++i) {
            printf("Record %zu: Value = %d\n", i, records[i].value);
        }
        free(records);
    } else {
        fprintf(stderr, "Failed to initialize all data structures\n");
    }

    return 0;
}
```

This code provides a robust solution for memory allocation and initialization under dynamic conditions. It includes error handling, resource management, and integration with an external data source. The function is designed to be modular and maintainable, considering scalability and future enhancements.']

