#include <pthread.h>
#include <time.h>

#define MAX_PACKET_SIZE 1024

typedef struct {
    time_t timestamp;
    size_t packet_size;
    char *data;
} Packet;

typedef struct {
    Packet **packets;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} PacketArray;

void log_packet(const Packet *packet);
int validate_packet(const char *data, size_t size);

PacketArray* init_packet_array(size_t initial_capacity) {
    PacketArray *array = (PacketArray*)malloc(sizeof(PacketArray));
    array->packets = (Packet**)malloc(initial_capacity * sizeof(Packet*));
    array->count = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void add_packet(PacketArray *array, const char *data, size_t size) {
    if (!validate_packet(data, size)) {
        log_packet(NULL); // Log invalid packet
        return;
    }

    pthread_mutex_lock(&array->lock);

    if (array->count >= array->capacity) {
        array->capacity *= 2;
        array->packets = (Packet**)realloc(array->packets, array->capacity * sizeof(Packet*));
    }

    Packet *packet = (Packet*)malloc(sizeof(Packet));
    packet->timestamp = time(NULL);
    packet->packet_size = size;
    packet->data = strdup(data);

    array->packets[array->count++] = packet;

    log_packet(packet);

    pthread_mutex_unlock(&array->lock);
}

void* cleanup_thread(void *arg) {
    PacketArray *array = (PacketArray*)arg;
    while (1) {
        sleep(5); // Cleanup interval
        pthread_mutex_lock(&array->lock);

        if (array->count > array->capacity / 2) {
            free(array->packets[0]->data);
            free(array->packets[0]);
            memmove(array->packets, array->packets + 1, 
                    (array->count - 1) * sizeof(Packet*));
            array->count--;
        }

        pthread_mutex_unlock(&array->lock);
    }
}

void log_packet(const Packet *packet) {
    if (!packet) return;
    printf("Packet logged at %ld with size %zu\n", packet->timestamp, packet->packet_size);
}

int validate_packet(const char *data, size_t size) {
    // Simple validation logic
    return size > 0 && data != NULL;
}

void get_summary_report(PacketArray *array) {
    pthread_mutex_lock(&array->lock);

    size_t total_size = 0;
    int malformed_count = 0;

    for (size_t i = 0; i < array->count; ++i) {
        Packet *packet = array->packets[i];
        if (!validate_packet(packet->data, packet->packet_size)) {
            malformed_count++;
        }
        total_size += packet->packet_size;
    }

    printf("Total packets: %zu\n", array->count);
    printf("Malformed packets discarded: %d\n", malformed_count);
    printf("Average packet size: %.2f\n", array->count ? (double)total_size / array->count : 0.0);

    pthread_mutex_unlock(&array->lock);
}

void free_packet_array(PacketArray *array) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        free(array->packets[i]->data);
        free(array->packets[i]);
    }

    free(array->packets);
    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int main() {
    PacketArray *packet_array = init_packet_array(10);
    pthread_t cleanup_tid;
    pthread_create(&cleanup_tid, NULL, cleanup_thread, packet_array);

    // Simulate adding packets
    add_packet(packet_array, "Packet1", 7);
    add_packet(packet_array, "Packet2", 7);

    get_summary_report(packet_array);

    free_packet_array(packet_array);

    return 0;
}
