#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_CONNECTIONS 1000

typedef struct {
    char ip_address[16];
    int port_number;
    int connection_status;
    time_t last_packet_timestamp;
    unsigned long sequence_number;
    unsigned int packet_count;
    double average_latency;
    unsigned long peak_bandwidth;
} Connection;

typedef struct {
    Connection *connections;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    FILE *log_file;
} ConnectionPool;

ConnectionPool* initialize_pool(size_t initial_capacity) {
    if (initial_capacity == 0) return NULL;

    ConnectionPool *pool = malloc(sizeof(ConnectionPool));
    pool->connections = calloc(initial_capacity, sizeof(Connection));
    pool->capacity = initial_capacity;
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);
    pool->log_file = fopen("connection_log.txt", "a");

    if (!pool || !pool->connections || !pool->log_file) {
        free(pool->connections);
        free(pool);
        fclose(pool->log_file);
        return NULL;
    }

    return pool;
}

int resize_pool(ConnectionPool *pool, size_t new_capacity) {
    pthread_mutex_lock(&pool->lock);

    Connection *new_connections = realloc(pool->connections, new_capacity * sizeof(Connection));
    if (!new_connections) {
        pthread_mutex_unlock(&pool->lock);
        return -1; // Failure
    }

    pool->connections = new_connections;
    pool->capacity = new_capacity;

    pthread_mutex_unlock(&pool->lock);
    return 0; // Success
}

int add_connection(ConnectionPool *pool, const char *ip_address, int port_number) {
    if (pthread_mutex_lock(&pool->lock)) return -1;

    if (pool->count >= pool->capacity) {
        int result = resize_pool(pool, pool->capacity * 2);
        if (result != 0) {
            pthread_mutex_unlock(&pool->lock);
            return -1;
        }
    }

    Connection *conn = &pool->connections[pool->count++];
    strncpy(conn->ip_address, ip_address, sizeof(conn->ip_address) - 1);
    conn->port_number = port_number;
    conn->connection_status = 0; // Assume initial status as disconnected
    conn->last_packet_timestamp = time(NULL);
    conn->sequence_number = 0;
    conn->packet_count = 0;
    conn->average_latency = 0.0;
    conn->peak_bandwidth = 0;

    fprintf(pool->log_file, "Connection added: %s:%d\n", ip_address, port_number);

    pthread_mutex_unlock(&pool->lock);
    return 0; // Success
}

int update_connection(ConnectionPool *pool, const char *ip_address, int port_number, 
                      time_t last_packet_timestamp, unsigned long sequence_number) {
    if (pthread_mutex_lock(&pool->lock)) return -1;

    for (size_t i = 0; i < pool->count; ++i) {
        Connection *conn = &pool->connections[i];

        if (strcmp(conn->ip_address, ip_address) == 0 && conn->port_number == port_number) {
            conn->last_packet_timestamp = last_packet_timestamp;
            conn->sequence_number = sequence_number;

            fprintf(pool->log_file, "Connection updated: %s:%d\n", ip_address, port_number);

            pthread_mutex_unlock(&pool->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&pool->lock);
    return -1; // Not found
}

void serialize_connections(ConnectionPool *pool, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&pool->capacity, sizeof(pool->capacity), 1, file);
    fwrite(&pool->count, sizeof(pool->count), 1, file);

    for (size_t i = 0; i < pool->count; ++i) {
        Connection *conn = &pool->connections[i];
        fwrite(conn, sizeof(Connection), 1, file);
    }

    fclose(file);
}

int deserialize_connections(ConnectionPool **out_pool, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    size_t capacity;
    fread(&capacity, sizeof(capacity), 1, file);

    ConnectionPool *pool = initialize_pool(capacity);
    if (!pool) {
        fclose(file);
        return -1;
    }

    size_t count;
    fread(&count, sizeof(count), 1, file);

    for (size_t i = 0; i < count; ++i) {
        Connection conn;
        fread(&conn, sizeof(Connection), 1, file);

        add_connection(pool, conn.ip_address, conn.port_number);
        update_connection(pool, conn.ip_address, conn.port_number, 
                          conn.last_packet_timestamp, conn.sequence_number);
    }

    fclose(file);
    *out_pool = pool;
    return 0; // Success
}

void cleanup(ConnectionPool *pool) {
    if (!pool) return;

    pthread_mutex_destroy(&pool->lock);
    free(pool->connections);
    fclose(pool->log_file);
    free(pool);
}
