typedef struct {
    int value;
    char status;
    char *string_field;
} record;

static int global_error_flag = 0; // Global flag for error tracking

void free_resources(record *records, size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) {
        if (records[i].string_field != NULL) {
            free(records[i].string_field);
        }
    }
    free(records);
}

char* generate_random_string(size_t length) {
    char *random_str = malloc(length + 1); // +1 for null terminator
    if (!random_str) {
        global_error_flag = 1;
        return NULL;
    }

    const char charset[] = "abcdefghijklmnopqrstuvwxyz";
    size_t max_index = sizeof(charset) - 1;

    srand((unsigned int)time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < length; ++i) {
        random_str[i] = charset[rand() % max_index];
    }
    random_str[length] = '\0'; // Null-terminate the string
    return random_str;
}

void initializeDataStructures(size_t num_records, record **records_out) {
    if (num_records <= 0 || global_error_flag) {
        *records_out = NULL;
        return;
    }

    record *records = malloc(num_records * sizeof(record));
    if (!records) {
        global_error_flag = 1;
        return;
    }

    srand((unsigned int)time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = rand() % 1001;

        if (records[i].value % 2 == 0) {
            records[i].status = 'E';
        } else {
            records[i].status = 'O';
        }

        char *random_string = generate_random_string(10);
        if (!random_string) {
            global_error_flag = 1;
            free_resources(records, num_records);
            return;
        }
        records[i].string_field = random_string;
    }

    *records_out = records; // Set output parameter to the allocated array
}

