int create_directory_recursively(const char *path);

// XML and environment handling function
char* DynamicEnvironmentAndResourceManagement(const char *configFile, const xmlChar *elementName) {
    xmlDocPtr doc;
    xmlXPathContextPtr xpathCtx;
    xmlXPathObjectPtr xpathObj;
    xmlNodeSetPtr nodeset;
    int i;
    char *directoryPath = NULL;

    // Parse the XML configuration file
    doc = xmlReadFile((const char *)configFile, NULL, 0);
    if (doc == NULL) {
        log_info("Failed to parse XML file.");
        return strdup("/default/path");  // Return default path on error
    }

    xpathCtx = xmlXPathNewContext(doc);
    if (xpathCtx == NULL) {
        log_info("Error in XPath context creation");
        xmlFreeDoc(doc);
        return strdup("/default/path");
    }

    xpathObj = xmlXPathEvalExpression(elementName, xpathCtx);
    nodeset = xpathObj->nodesetval;

    if (nodeset == NULL || nodeset->nodeNr != 1) {
        log_info("No unique element found. Using default path.");
        directoryPath = strdup("/default/path");
    } else {
        xmlNode *node = nodeset->nodeTab[0];
        if (xmlStrcmp(node->name, BAD_CAST "directory") == 0 && node->children != NULL) {
            directoryPath = (char *)xmlNodeListGetString(doc, node->children, 1);
        }
    }

    // Clean up XML
    xmlXPathFreeObject(xpathObj);
    xmlXPathFreeContext(xpathCtx);
    xmlFreeDoc(doc);

    if (!directoryPath) {
        directoryPath = strdup("/default/path");
    }

    // Check and create parent directories recursively
    char fullPath[1024];
    snprintf(fullPath, sizeof(fullPath), "%s/new_directory", directoryPath);
    create_directory_recursively(directoryPath);

    // Create the new directory
    mkdir(fullPath, 0755);

    // Set environment variable or use existing one
    const char *envVar = getenv("MY_ENV_VAR");
    if (!envVar) {
        setenv("MY_ENV_VAR", fullPath, 1);
    }

    return strdup(fullPath);
}

