    long totalSum = 0;

    *records = (record *)malloc(numRecords * sizeof(record));
    if (!*records) {
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < numOffsets; ++i) {
        long rangeStart = totalSum / numKeys;
        long rangeEnd = rangeStart + 10;

        pthread_mutex_lock(&lock);

        for (int j = 0; j < numRecords; ++j) {
            (*records)[j].value = rand() % (rangeEnd - rangeStart) + rangeStart;

            // Assuming offset logic to link keys
            if (offsets[i] == 0 || offsets[i] >= numKeys) continue;

            (*records)[j].keyIndex = keys[offsets[i]];
        }

        for (int j = 0; j < numRecords; ++j) {
            totalSum += (*records)[j].value;
        }

        pthread_mutex_unlock(&lock);
    }
}

