} memory_pool;

memory_pool mp = {NULL, MEMORY_POOL_SIZE, 0, PTHREAD_MUTEX_INITIALIZER};

void* allocate_from_pool(size_t size) {
    pthread_mutex_lock(&mp.lock);
    if (size + sizeof(size_t) > mp.capacity - mp.used) {
        pthread_mutex_unlock(&mp.lock);
        return NULL; // Pool exhausted
    }

    void* ptr = ((char*)mp.pool + mp.used);
    *((size_t*)ptr) = size;
    mp.used += size + sizeof(size_t);
    pthread_mutex_unlock(&mp.lock);

    return (char*)ptr + sizeof(size_t);
}

void init_memory_pool() {
    mp.pool = malloc(MEMORY_POOL_SIZE);
    if (!mp.pool) {
        fprintf(stderr, "Failed to allocate memory pool: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

record* create_records(int num_keys, int* keys, int min_value, int max_value, size_t* out_size) {
    record* records = (record*)allocate_from_pool(num_keys * sizeof(record));
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        return NULL;
    }

    for (size_t i = 0; i < num_keys; ++i) {
        records[i].offset = rand(); // Simulate fetching metadata
        records[i].key = keys[i];
        int value;

        if ((unsigned)(max_value - min_value) > INT_MAX) {
            fprintf(stderr, "Integer overflow in random range calculation\n");
            return NULL;
        }

        value = (rand() % (max_value - min_value + 1)) + min_value;

        // Check for integer overflow
        if (value < 0 || records[i].offset + value < records[i].offset) {
            fprintf(stderr, "Integer overflow detected during record initialization\n");
            return NULL;
        }

        records[i].value = value;
    }

    *out_size = num_keys;
    return records;
}

void resize_records(record** records_ref, size_t new_capacity) {
    record* old_records = *records_ref;
    size_t old_capacity = (*records_ref == NULL) ? 0 : (mp.used / sizeof(record));

    record* new_records = (record*)allocate_from_pool(new_capacity * sizeof(record));
    if (!new_records) {
        fprintf(stderr, "Failed to allocate memory for resized records\n");
        return;
    }

    size_t copy_size = old_capacity < new_capacity ? old_capacity : new_capacity;
    memcpy(new_records, old_records, copy_size * sizeof(record));

    // Free the old records in the pool
    pthread_mutex_lock(&mp.lock);
    mp.used -= (old_capacity * sizeof(record));
    if (*records_ref) {
        free(*records_ref); // Assuming we have a method to free from the pool
    }
    pthread_mutex_unlock(&mp.lock);

    *records_ref = new_records;
}

void shutdown_memory_pool() {
    free(mp.pool);
}

int main() {
    srand(time(NULL)); // Initialize random number generator

    init_memory_pool();

    int keys[] = {1, 2, 3}; // Example keys
    size_t num_keys = sizeof(keys) / sizeof(keys[0]);

    size_t out_size;
    record* records = create_records(num_keys, keys, 0, 100, &out_size);
    if (!records) {
        fprintf(stderr, "Failed to initialize records\n");
        shutdown_memory_pool();
        return EXIT_FAILURE;
    }

    // Example: resizing
    resize_records(&records, num_keys * 2);

    // Cleanup and shutdown
    free(records); // Assuming we have a method to free from the pool
    shutdown_memory_pool();

    return 0;
}
```

### Key Points:
- **Memory Pool**: A simple memory pool is implemented for efficient memory management.
- **Thread Safety**: Mutex locks are used to ensure thread-safe access to the memory pool.
- **Integer Overflow Handling**: Checks are in place to handle potential integer overflows during initialization and resizing.
- **Error Handling**: Graceful error handling with meaningful messages for allocation failures.
- **Dynamic Resizing**: Functionality to resize the record array dynamically is provided.

This implementation provides a starting point, but further optimizations and customizations may be needed based on specific system constraints and requirements.']

