static int global_error_flag = 0;

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

char* generate_random_string(size_t length) {
    static const size_t pool_size = 10000;
    static char string_pool[pool_size][16];
    static int initialized = 0;
    if (!initialized) {
        for (size_t i = 0; i < pool_size; ++i) {
            for (size_t j = 0; j < length; ++j) {
                size_t rand_index = rand() % strlen(ALPHANUMERIC_CHARS);
                string_pool[i][j] = ALPHANUMERIC_CHARS[rand_index];
            }
            string_pool[i][length] = '\0';
        }
        initialized = 1;
    }
    return string_pool[rand() % pool_size];
}

ItemList* initialize_item_list(size_t num_items) {
    if (num_items == 0 || global_error_flag) {
        return NULL;
    }

    ItemList *list = (ItemList *)malloc(sizeof(ItemList));
    if (!list) {
        log_error("Failed to allocate memory for ItemList");
        global_error_flag = 1;
        return NULL;
    }

    list->items = (Item *)calloc(num_items, sizeof(Item));
    if (!list->items) {
        free(list);
        log_error("Failed to allocate memory for items array");
        global_error_flag = 1;
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < num_items; ++i) {
        list->items[i].id = i + 1;
        list->items[i].value = ((double)rand() / RAND_MAX) * 100.0;

        char* random_str = generate_random_string(15);
        list->items[i].str = strdup(random_str);
        if (!list->items[i].str) {
            log_error("Failed to allocate memory for string");
            global_error_flag = 1;

            // Cleanup already allocated items
            while (i-- > 0) free(list->items[i].str);
            free(list->items);
            free(list);
            return NULL;
        }
    }

    list->count = num_items;
    return list;
}

void free_item_list(ItemList *list) {
    if (!list || global_error_flag) return;

    for (size_t i = 0; i < list->count; ++i) {
        free(list->items[i].str);
    }
    free(list->items);
    free(list);
}

// Example iterator function
void iterate_item_list(const ItemList *list, void (*process)(const Item *)) {
    if (!list || !process) return;

    for (size_t i = 0; i < list->count; ++i) {
        process(&list->items[i]);
    }
}

// Example processing function
