    printf("ID: %d, Value: %.2f, String: %s\n", item->id, item->value, item->str);
}

int main() {
    size_t num_items = 10; // Example number of items
    ItemList *list = initialize_item_list(num_items);

    if (!list || global_error_flag) {
        log_error("Initialization failed");
        return EXIT_FAILURE;
    }

    iterate_item_list(list, print_item);

    free_item_list(list);
    return EXIT_SUCCESS;
}
