public class DirectoryManager
{
    public static string ConfigureEnvironmentAndManageRecords(string configFilePath, string elementName)
    {
        XmlDocument xmlDoc = new XmlDocument();
        xmlDoc.Load(configFilePath);

        XmlNodeList nodes = xmlDoc.SelectNodes($"//{elementName}");
        string directoryPath = null;

        if (nodes.Count == 1)
        {
            directoryPath = nodes[0].InnerText;
        }
        else
        {
            Console.WriteLine("Element not found or multiple elements match; proceeding with default path.");
            XmlNode defaultNode = xmlDoc.SelectSingleNode("//defaultDirectory");
            directoryPath = defaultNode?.InnerText ?? "C:\\DefaultPath";
        }

        string environmentVariableName = "MY_ENV_VAR";

        if (!Environment.GetEnvironmentVariables(EnvironmentVariableTarget.Machine).Keys.Cast<string>().Contains(environmentVariableName))
        {
            Directory.CreateDirectory(directoryPath);
            Environment.SetEnvironmentVariable(environmentVariableName, directoryPath, EnvironmentVariableTarget.Machine);
        }
        else
        {
            directoryPath = Environment.GetEnvironmentVariable(environmentVariableName);
        }

        return directoryPath;
    }
}

