    Record* records = (Record*)malloc(totalSize);

    if (!records) {
        perror("Failed to allocate memory");
        return;
    }

    srand(time(NULL));
    long sum = 0;

    for (int i = 0; i < numOffsets; ++i) {
        int range = (sum % 100) + 1; // Adjust range based on sum
