        if ((size_t)(offsets[i]) >= sizeof(Record)/sizeof(long)) {
            perror("Offset out of bounds");
            free(records);
            return;
        }

        records[i].key = &keys[(int)offsets[i]];
        sum += records[i].value;
    }

    printf("Total Sum: %ld\n", sum);

    // Free memory
