#include <iostream>
#include <unordered_map>
#include <mutex>
#include <shared_mutex>
#include <atomic>
#include <vector>
#include <algorithm>

// Custom memory allocator (simplified version)
template<typename T>
class MemoryPool {
public:
    MemoryPool(size_t size = 1024) : poolSize(size), currentIndex(0) {
        data.reserve(poolSize);
        for (size_t i = 0; i < poolSize; ++i) {
            data.push_back(std::make_unique<T>());
        }
    }

    T* allocate() {
        std::lock_guard<std::mutex> lock(mutex_);
        if (currentIndex >= poolSize) {
            // Expand the memory pool if needed
            expandPool();
        }
        return data[currentIndex++].get();
    }

    void deallocate(T* ptr, size_t index) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (index < currentIndex) {
            data[index] = std::move(data.back());
            data.pop_back();
            --currentIndex;
        }
    }

private:
    void expandPool() {
        size_t newElements = poolSize;
        for (size_t i = 0; i < newElements; ++i) {
            data.push_back(std::make_unique<T>());
        }
        poolSize += newElements;
    }

    std::vector<std::unique_ptr<T>> data;
    size_t poolSize, currentIndex;
    std::mutex mutex_;
};

// Node structure
struct Node {
    double value;
    Node* next;

    Node(double val) : value(val), next(nullptr) {}
};

// Linked List with Hash Table integration
class HybridDataStructure {
public:
    HybridDataStructure() = default;

    // Insert a node at the end of linked list and into hash table
    void insertNode(Node* node, int key) {
        std::unique_lock lock(mutex_);
        if (!head) {
            head = tail = node;
        } else {
            tail->next = node;
            tail = node;
        }
        nodeList[key] = node;
    }

    // Retrieve a node by key
    Node* getNodeByKey(int key) {
        std::shared_lock lock(mutex_);
        auto it = nodeList.find(key);
        return (it != nodeList.end()) ? it->second : nullptr;
    }

    // Traverse the linked list and print values
    void traverse() const {
        std::shared_lock lock(mutex_);
        Node* current = head;
        while (current) {
            std::cout << current->value << " ";
            current = current->next;
        }
        std::cout << "\n";
    }

    // Sort linked list by value
    void sortLinkedList() {
        if (!head) return;

        std::vector<Node*> nodes;
        Node* current = head;
        while (current) {
            nodes.push_back(current);
            current = current->next;
        }

        std::sort(nodes.begin(), nodes.end(), [](Node* a, Node* b) { 
            return a->value < b->value; 
        });

        for (size_t i = 0; i + 1 < nodes.size(); ++i) {
            nodes[i]->next = nodes[i + 1];
        }
        nodes.back()->next = nullptr;

        head = nodes.front();
        Node* currentTail = head;
        while (currentTail->next) {
            currentTail = currentTail->next;
        }
        tail = currentTail;
    }

    // Delete a node by key
    bool deleteNodeByKey(int key) {
        std::unique_lock lock(mutex_);
        auto it = nodeList.find(key);
        if (it == nodeList.end()) return false;

        Node* nodeToDelete = it->second;
        if (!head) return false;  // should never happen

        if (head == tail && head == nodeToDelete) {
            head = tail = nullptr;
        } else if (head == nodeToDelete) {
            head = head->next;
        } else {
            Node* current = head;
            while (current->next != nodeToDelete) {
                current = current->next;
            }
            current->next = nodeToDelete->next;
            if (nodeToDelete == tail) {
                tail = current;
            }
        }

        nodeList.erase(it);
        memoryPool.deallocate(nodeToDelete, key);  // Use appropriate index/key logic
        return true;
    }

private:
    Node* head = nullptr;
    Node* tail = nullptr;
    std::unordered_map<int, Node*> nodeList;
    MemoryPool<Node> memoryPool;
    mutable std::shared_mutex mutex_;
};

