#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define TABLE_SIZE 101

typedef struct Record {
    int key;
    int value;
} Record;

// Hash table for efficient key lookup and insertion
typedef struct HashNode {
    Record *record;
    struct HashNode *next;
} HashNode;

typedef struct {
    HashNode **buckets;
    size_t count;
    float utilization;
} HashTable;

HashTable *create_hash_table() {
    HashTable *table = malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->buckets = calloc(TABLE_SIZE, sizeof(HashNode *));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    table->count = 0;
    table->utilization = 0.0f;
    return table;
}

unsigned int hash(int key) {
    return (key % TABLE_SIZE);
}

void free_hash_table(HashTable *table) {
    for (int i = 0; i < TABLE_SIZE; ++i) {
        HashNode *node = table->buckets[i];
        while (node) {
            HashNode *temp = node;
            node = node->next;
            free(temp);
        }
    }
    free(table->buckets);
    free(table);
}

int insert_record(HashTable *table, Record *record) {
    unsigned int index = hash(record->key);

    for (HashNode *node = table->buckets[index]; node; node = node->next) {
        if (node->record->key == record->key) return -1;
    }

    HashNode *new_node = malloc(sizeof(HashNode));
    if (!new_node) return -1;

    new_node->record = record;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;
    table->count++;
    return 0;
}

Record *find_record(HashTable *table, int key) {
    unsigned int index = hash(key);

    for (HashNode *node = table->buckets[index]; node; node = node->next) {
        if (node->record->key == key) {
            return node->record;
        }
    }

    return NULL;
}

void handle_allocation_failure() {
    fprintf(stderr, "Memory allocation failed.\n");
    exit(EXIT_FAILURE);
}

// Custom memory allocator
typedef struct MemoryBlock {
    size_t size;
    int free;
    void *ptr;
} MemoryBlock;

#define MEMORY_POOL_SIZE 1024

MemoryBlock pool[MEMORY_POOL_SIZE];

void init_memory_pool() {
    for (int i = 0; i < MEMORY_POOL_SIZE - 1; ++i) {
        pool[i].size = sizeof(MemoryBlock);
        pool[i].free = 1;
        pool[i].ptr = &pool[i + 1];
    }
    pool[MEMORY_POOL_SIZE - 1].size = 0;
    pool[MEMORY_POOL_SIZE - 1].free = 1;
    pool[MEMORY_POOL_SIZE - 1].ptr = NULL;
}

void *custom_malloc(size_t size) {
    MemoryBlock *best_fit = NULL, *worst_fit = NULL;

    for (int i = 0; i < MEMORY_POOL_SIZE; ++i) {
        if (pool[i].free && pool[i].size >= size) {
            if (!best_fit || pool[i].size < best_fit->size) {
                best_fit = &pool[i];
            }
            if (!worst_fit || pool[i].size > worst_fit->size) {
                worst_fit = &pool[i];
            }
        }
    }

    MemoryBlock *block = (float)size / sizeof(MemoryBlock) <= 0.5 ? best_fit : worst_fit;

    if (!block) handle_allocation_failure();

    block->free = 0;

    void *allocated_ptr = block->ptr;
    size_t remaining_size = block->size - size;

    if (remaining_size > sizeof(MemoryBlock)) {
        MemoryBlock *new_block = (MemoryBlock *)block->ptr;
        new_block->size = remaining_size;
        new_block->free = 1;
        new_block->ptr = ((char *)block->ptr) + remaining_size;
        block->size = size;
        block->ptr = new_block->ptr;
    } else {
        block->size = 0;
        block->ptr = NULL;
    }

    return allocated_ptr;
}

void custom_free(void *ptr) {
    for (int i = 0; i < MEMORY_POOL_SIZE; ++i) {
        if (pool[i].ptr == ptr) {
            pool[i].free = 1;
            while (i > 0 && !pool[i - 1].free) {
                MemoryBlock *prev_block = &pool[i - 1];
                prev_block->size += sizeof(MemoryBlock) + pool[i].size;
                prev_block->ptr = pool[i].ptr;
                i--;
            }
        }
    }
}

Record **create_pointer_array(size_t num_records, HashTable *table) {
    Record **pointer_array = (Record **)custom_malloc(num_records * sizeof(Record *));
    if (!pointer_array) handle_allocation_failure();

    for (int i = 0; i < num_records; ++i) {
        pointer_array[i] = NULL;
    }

    int key = 1;
    while (table->count < num_records) {
        Record *record = custom_malloc(sizeof(Record));
        if (!record) handle_allocation_failure();

        record->key = key++;
        for (int i = 0; i < TABLE_SIZE; ++i) {
            key = hash(key);
            HashNode *node = table->buckets[key];
            while (node && node->record->key != record->key) {
                node = node->next;
            }
            if (!node) break;
        }

        record->value = rand(); // Initialize with random value
        insert_record(table, record);
    }

    for (int i = 0; i < TABLE_SIZE; ++i) {
        HashNode *node = table->buckets[i];
        while (node) {
            pointer_array[node->record->key] = node->record;
            node = node->next;
        }
    }

    return pointer_array;
}

// Example usage
int main() {
    init_memory_pool();

    HashTable *table = create_hash_table();
    if (!table) {
        handle_allocation_failure();
    }

    Record **pointer_array = create_pointer_array(100, table);
    if (!pointer_array) {
        free_hash_table(table);
        handle_allocation_failure();
    }

    // Clean up
    custom_free(pointer_array);

    free_hash_table(table);
    return 0;
}
