        int index = (hash(key) + i) % HASH_TABLE_SIZE;
        if (collection->records[index] && collection->records[index]->key == key) {
            return collection->records[index];
        }
    }
    return NULL;
}

void update_record(DynamicCollection *collection, int key, int new_value) {
    pthread_mutex_lock(&collection->lock);
    Record *record = find_record(collection, key);
    if (record) {
        record->value = new_value;
    } else {
        fprintf(stderr, "Record not found\n");
    }
    pthread_mutex_unlock(&collection->lock);
}

void delete_record(DynamicCollection *collection, int key) {
    pthread_mutex_lock(&collection->lock);
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        int index = (hash(key) + i) % HASH_TABLE_SIZE;
        if (collection->records[index] && collection->records[index]->key == key) {
            free_record(collection->records[index]);
            collection->records[index] = NULL;
            collection->count--;
            break;
        }
    }
    pthread_mutex_unlock(&collection->lock);
}

// RESTful API simulation
void handle_put(int key, int new_value) {
    update_record(&collection, key, new_value);
    printf("Record with key %d updated\n", key);
}

void handle_delete(int key) {
    delete_record(&collection, key);
    printf("Record with key %d deleted\n", key);
}

int main() {
    srand(time(NULL));

    // Example usage
    Record *record = allocate_record(100, 1, 100);
    if (insert_record(&collection, record) == 0) {
        handle_put(1, 50); // Update value
        handle_delete(1);  // Delete record
    }

    return 0;
}
