#include <time.h>

typedef struct {
    long timestamp;
    double value;
} Entry;

Entry* create_entries(size_t initial_size) {
    Entry *entries = (Entry *)malloc(initial_size * sizeof(Entry));
    if (!entries) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srand(time(NULL)); // Initialize random seed
    for (size_t i = 0; i < initial_size; ++i) {
        entries[i].timestamp = time(NULL);
        entries[i].value = (double)rand() / RAND_MAX;
    }

    return entries;
}

void update_timestamps(Entry *entries, size_t count) {
    if (!entries) return;

    long current_time = time(NULL);
    for (size_t i = 0; i < count; ++i) {
        entries[i].timestamp = current_time;
    }
}

int append_entry(Entry **entries, size_t *current_size, size_t *capacity) {
    if (!*entries || !current_size || !capacity) return -1;

    // Double the capacity when needed
    if (*current_size >= *capacity) {
        size_t new_capacity = *capacity == 0 ? 10 : *capacity * 2;
        Entry *new_entries = (Entry *)realloc(*entries, new_capacity * sizeof(Entry));

        if (!new_entries) {
            fprintf(stderr, "Memory reallocation failed\n");
            return -1;
        }

        *entries = new_entries;
        *capacity = new_capacity;
    }

    // Add a new entry
    (*entries)[*current_size].timestamp = time(NULL);
    (*entries)[*current_size].value = (double)rand() / RAND_MAX;
    (*current_size)++;

    return 0; 
}

void free_entries(Entry *entries) {
    if (!entries) return;

    free(entries);
}
