import threading
import random

// Define constants
#define MAX_NUMBERS 10000
#define DEFAULT_RX_UE_TAG 0x01
#define VALID_TAGS {0x01, 0x02, 0x03} // Add valid tags here

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Global variables
NFAPI_CRC_INDICATION_PDU_T* pdu_list = NULL;
int list_size = 0;
int max_pdu_capacity = MAX_NUMBERS;
pthread_mutex_t list_mutex;

// Function to initialize the mutex
void init_mutex() {
    pthread_mutex_init(&list_mutex, NULL);
}

// Function to destroy the mutex
void destroy_mutex() {
    pthread_mutex_destroy(&list_mutex);
}

// Function to check if a tag is valid
int is_valid_tag(int tag) {
    int valid_tags[] = VALID_TAGS;
    for (int i = 0; i < sizeof(valid_tags) / sizeof(valid_tags[0]); ++i) {
        if (valid_tags[i] == tag) return 1;
    }
    return 0;
}

// Function to dynamically grow the list
void ensure_capacity(int new_size) {
    pthread_mutex_lock(&list_mutex);
    while (new_size > max_pdu_capacity) {
        max_pdu_capacity *= 2; // Double the capacity
    }
    if (pdu_list == NULL || list_size >= max_pdu_capacity) {
        pdu_list = realloc(pdu_list, max_pdu_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pdu_list == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
    }
    pthread_mutex_unlock(&list_mutex);
}

// Function to add a PDU to the list
void add_pdu(int rx_ue_tag, int rnti) {
    ensure_capacity(list_size + 1);

    pthread_mutex_lock(&list_mutex);
    for (int i = 0; i < list_size; ++i) {
        if (pdu_list[i].RNTI == rnti) {
            pthread_mutex_unlock(&list_mutex);
            return;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = rx_ue_tag ? rx_ue_tag : DEFAULT_RX_UE_TAG;
    pdu.RNTI = rnti;
    pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = random.getrandbits(1);

    if (!is_valid_tag(pdu.RX_UE_INFORMATION_TAG)) {
        fprintf(stderr, "Invalid RX UE tag\n");
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    pdu_list[list_size++] = pdu;
    pthread_mutex_unlock(&list_mutex);
}

// Function to find and print the largest integer
void print_largest_integer() {
    if (list_size == 0) {
        printf("List is empty\n");
        return;
    }

    int max_rnti = pdu_list[0].RNTI;
    for (int i = 1; i < list_size; ++i) {
        if (pdu_list[i].RNTI > max_rnti) {
            max_rnti = pdu_list[i].RNTI;
        }
    }
    printf("Largest RNTI: %d\n", max_rnti);
}

// Function to filter the list
NFAPI_CRC_INDICATION_PDU_T* filter_list(int(*criteria)(int)) {
    pthread_mutex_lock(&list_mutex);
    NFAPI_CRC_INDICATION_PDU_T* filtered_list = malloc(list_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    int filtered_size = 0;

    for (int i = 0; i < list_size; ++i) {
        if (criteria(pdu_list[i].RX_UE_INFORMATION_TAG)) {
            filtered_list[filtered_size++] = pdu_list[i];
        }
    }

    pthread_mutex_unlock(&list_mutex);
    return filtered_size > 0 ? filtered_list : NULL;
}

// Main function to process input
void process_input() {
    int number;
    init_mutex();

    while (scanf("%d", &number) == 1 && list_size < MAX_NUMBERS) {
        add_pdu(number, random.randint(0, 10000)); // Random RNTI for demonstration
    }

    if (list_size > 0) {
        print_largest_integer();
    } else {
        printf("No valid structures in the list.\n");
    }

    // Example filter: keep only specific RX_UE tags
    NFAPI_CRC_INDICATION_PDU_T* filtered = filter_list(is_valid_tag);
    if (filtered != NULL) {
        printf("Filtered list size: %d\n", list_size); // Should be adjusted to actual filtered size
        free(filtered);
    }

    destroy_mutex();
}

int main() {
    process_input();
    free(pdu_list);
    return 0;
}
