// Define the record structure
typedef struct Record {
    int value;
    char identifier[256];
    time_t timestamp;
} Record;

// Hash table entry for collision-resistant hash table
typedef struct HashTableEntry {
    Record *record;
    struct HashTableEntry *next;
} HashTableEntry;

#define HASH_TABLE_SIZE 1024

// Memory pool structure for tiered memory management
typedef struct MemoryPool {
    void **pool;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} MemoryPool;

// Global variables for hash table and memory pools
static HashTableEntry *hash_table[HASH_TABLE_SIZE];
static MemoryPool *best_fit_pool, *worst_fit_pool;

// Function prototypes
unsigned long hash_function(const char *key);
HashTableEntry* create_hash_entry(Record *record);
void insert_record(Record *record, const char *identifier);
Record* get_record(const char *identifier);
void delete_record(const char *identifier);

void initialize_memory_pools();
void* custom_allocator(size_t size, int strategy);
void free_custom_allocated(void *ptr);

// Hash function for string key
unsigned long hash_function(const char *key) {
    unsigned long hash = 5381;
    int c;
    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    return hash % HASH_TABLE_SIZE;
}

// Create a new hash table entry
HashTableEntry* create_hash_entry(Record *record) {
    HashTableEntry *entry = (HashTableEntry*)malloc(sizeof(HashTableEntry));
    if (!entry) {
        fprintf(stderr, "Memory allocation failed for hash table entry\n");
        return NULL;
    }
    entry->record = record;
    entry->next = NULL;
    return entry;
}

// Insert a new record into the hash table
void insert_record(Record *record, const char *identifier) {
    unsigned long index = hash_function(identifier);
    HashTableEntry *entry = create_hash_entry(record);

    if (!entry) {
        fprintf(stderr, "Failed to create hash entry for identifier: %s\n", identifier);
        return;
    }

    pthread_mutex_lock(&hash_table[index]->lock); // Ensure thread safety
    entry->next = hash_table[index];
    hash_table[index] = entry;
    pthread_mutex_unlock(&hash_table[index]->lock);

    printf("Record inserted with identifier: %s\n", identifier);
}

// Retrieve a record by its identifier
Record* get_record(const char *identifier) {
    unsigned long index = hash_function(identifier);

    pthread_mutex_lock(&hash_table[index]->lock); // Ensure thread safety
    HashTableEntry *entry = hash_table[index];

    while (entry) {
        if (strcmp(entry->record->identifier, identifier) == 0) {
            Record* found_record = entry->record;
            pthread_mutex_unlock(&hash_table[index]->lock);
            return found_record;
        }
        entry = entry->next;
    }

    pthread_mutex_unlock(&hash_table[index]->lock);
    printf("Record not found with identifier: %s\n", identifier);
    return NULL;
}

// Delete a record by its identifier
void delete_record(const char *identifier) {
    unsigned long index = hash_function(identifier);

    pthread_mutex_lock(&hash_table[index]->lock); // Ensure thread safety
    HashTableEntry **entry_ptr = &hash_table[index];

    while (*entry_ptr) {
        if (strcmp((*entry_ptr)->record->identifier, identifier) == 0) {
            HashTableEntry *to_delete = *entry_ptr;
            *entry_ptr = to_delete->next;
            free(to_delete);
            printf("Record deleted with identifier: %s\n", identifier);
            break;
        }
        entry_ptr = &(*entry_ptr)->next;
    }

    pthread_mutex_unlock(&hash_table[index]->lock);
}

// Initialize memory pools
void initialize_memory_pools() {
    // Example pool initialization (expand as needed)
    best_fit_pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    worst_fit_pool = (MemoryPool*)malloc(sizeof(MemoryPool));

    if (!best_fit_pool || !worst_fit_pool) {
        fprintf(stderr, "Failed to initialize memory pools\n");
        return;
    }

    // Initialize pools
    pthread_mutex_init(&best_fit_pool->lock, NULL);
    pthread_mutex_init(&worst_fit_pool->lock, NULL);

    best_fit_pool->capacity = 1024; // Example capacity
    worst_fit_pool->capacity = 1024;

    best_fit_pool->pool = (void**)malloc(best_fit_pool->capacity * sizeof(void*));
    worst_fit_pool->pool = (void**)malloc(worst_fit_pool->capacity * sizeof(void*));

    if (!best_fit_pool->pool || !worst_fit_pool->pool) {
        fprintf(stderr, "Failed to allocate memory pool\n");
        return;
    }

    // Initialize the pools with NULLs
    memset(best_fit_pool->pool, 0, best_fit_pool->capacity * sizeof(void*));
    memset(worst_fit_pool->pool, 0, worst_fit_pool->capacity * sizeof(void*));

    printf("Memory pools initialized\n");
}

// Custom memory allocator based on strategy (best-fit/worst-fit)
void* custom_allocator(size_t size, int strategy) {
    MemoryPool *selected_pool = strategy ? best_fit_pool : worst_fit_pool;

    pthread_mutex_lock(&selected_pool->lock);
    for (size_t i = 0; i < selected_pool->capacity; ++i) {
        if (!selected_pool->pool[i]) {
            selected_pool->pool[i] = malloc(size);
            if (selected_pool->pool[i]) {
                pthread_mutex_unlock(&selected_pool->lock);
                return selected_pool->pool[i];
            }
        }
    }

    pthread_mutex_unlock(&selected_pool->lock);
    fprintf(stderr, "Failed to allocate memory using %s strategy\n", strategy ? "worst-fit" : "best-fit");
    return NULL;
}

// Free custom allocated memory
void free_custom_allocated(void *ptr) {
    // Implement logic to identify which pool the ptr belongs to and free it accordingly
    pthread_mutex_lock(&best_fit_pool->lock);
    for (size_t i = 0; i < best_fit_pool->capacity; ++i) {
        if (best_fit_pool->pool[i] == ptr) {
            free(best_fit_pool->pool[i]);
            best_fit_pool->pool[i] = NULL;
            pthread_mutex_unlock(&best_fit_pool->lock);
            return;
        }
    }

    pthread_mutex_lock(&worst_fit_pool->lock);
    for (size_t i = 0; i < worst_fit_pool->capacity; ++i) {
        if (worst_fit_pool->pool[i] == ptr) {
            free(worst_fit_pool->pool[i]);
            worst_fit_pool->pool[i] = NULL;
            pthread_mutex_unlock(&worst_fit_pool->lock);
            return;
        }
    }

    pthread_mutex_unlock(&best_fit_pool->lock);
    pthread_mutex_unlock(&worst_fit_pool->lock);

    fprintf(stderr, "Failed to free memory: pointer not found in any pool\n");
}

int main() {
    initialize_memory_pools();

    // Example usage
    Record *record = (Record*)custom_allocator(sizeof(Record), 0); // Best-fit strategy
    if (record) {
        record->value = 42;
        strcpy(record->identifier, "example123");
        time(&record->timestamp);

        insert_record(record, "example123");

        Record* fetched_record = get_record("example123");
        if (fetched_record)
            printf("Fetched record: %d\n", fetched_record->value);

        delete_record("example123");
    }

    // Free pools
    free(best_fit_pool->pool);
    free(worst_fit_pool->pool);
    free(best_fit_pool);
    free(worst_fit_pool);

    return 0;
}
