// Define structures for packets and tasks
typedef struct {
    time_t timestamp;
    size_t packet_size;
    char *data;
} Packet;

typedef struct {
    int priority;
    char status[50];
    int dependencies_count;
    char **dependencies;
} Task;

// Global variables for managing dynamic arrays
#define MAX_PACKETS 1000
#define PACKET_THRESHOLD 1024

Packet *packet_array[MAX_PACKETS];
int packet_count = 0;
pthread_mutex_t packet_mutex = PTHREAD_MUTEX_INITIALIZER;

Task *task_array[100];
int task_count = 0;
pthread_mutex_t task_mutex = PTHREAD_MUTEX_INITIALIZER;

// Logging framework placeholder (use your existing logging library)
void log_info(const char *message) {
    printf("INFO: %s\n", message);
}

void log_error(const char *message) {
    printf("ERROR: %s\n", message);
}

// Function to initialize packet
Packet* init_packet(size_t size, const char *data) {
    Packet *packet = (Packet*)malloc(sizeof(Packet));
    if (!packet) {
        log_error("Failed to allocate memory for packet.");
        return NULL;
    }

    packet->timestamp = time(NULL);
    packet->packet_size = size;
    packet->data = strdup(data);

    if (!packet->data) {
        free(packet);
        log_error("Failed to duplicate packet data.");
        return NULL;
    }

    return packet;
}

// Thread-safe function to add a packet
void add_packet(Packet *packet) {
    pthread_mutex_lock(&packet_mutex);

    if (packet_count >= MAX_PACKETS || packet->packet_size > PACKET_THRESHOLD) {
        log_info("Packet discarded due to size limit or max capacity.");
        free(packet->data);
        free(packet);
        pthread_mutex_unlock(&packet_mutex);
        return;
    }

    packet_array[packet_count++] = packet;

    pthread_mutex_unlock(&packet_mutex);
}

// Thread-safe function to process packets
void process_packets(void (*process_fn)(Packet*)) {
    pthread_mutex_lock(&packet_mutex);

    for (int i = 0; i < packet_count; ++i) {
        if (packet_array[i]) {
            process_fn(packet_array[i]);
        }
    }

    // Remove processed packets
    for (int i = 0; i < packet_count; ) {
        if (!packet_array[i] || packet_array[i]->packet_size == 0) {
            free(packet_array[i]->data);
            free(packet_array[i]);
            memmove(&packet_array[i], &packet_array[i + 1], sizeof(Packet*) * (packet_count - i - 1));
            --packet_count;
        } else {
            ++i;
        }
    }

    pthread_mutex_unlock(&packet_mutex);
}

// Function to initialize task
Task* init_task(int priority, const char *status, int dependencies_count, char **dependencies) {
    Task *task = (Task*)malloc(sizeof(Task));
    if (!task) {
        log_error("Failed to allocate memory for task.");
        return NULL;
    }

    task->priority = priority;
    strncpy(task->status, status, sizeof(task->status) - 1);
    task->dependencies_count = dependencies_count;

    task->dependencies = (char**)malloc(dependencies_count * sizeof(char*));
    if (!task->dependencies) {
        free(task);
        log_error("Failed to allocate memory for task dependencies.");
        return NULL;
    }

    for (int i = 0; i < dependencies_count; ++i) {
        task->dependencies[i] = strdup(dependencies[i]);
        if (!task->dependencies[i]) {
            // Clean up already allocated data
            for (int j = 0; j < i; ++j) free(task->dependencies[j]);
            free(task->dependencies);
            free(task);
            log_error("Failed to duplicate dependency.");
            return NULL;
        }
    }

    return task;
}

// Thread-safe function to add a task
void add_task(Task *task) {
    pthread_mutex_lock(&task_mutex);

    if (task_count >= 100) {
        log_info("Task discarded due to max capacity.");
        free(task);
        for (int i = 0; i < task->dependencies_count; ++i)
            free(task->dependencies[i]);
        free(task->dependencies);
        pthread_mutex_unlock(&task_mutex);
        return;
    }

    task_array[task_count++] = task;

    pthread_mutex_unlock(&task_mutex);
}

// Thread-safe function to update a task
void update_task(int index, int priority, const char *status) {
    if (index < 0 || index >= task_count) {
        log_error("Invalid task index for update.");
        return;
    }

    pthread_mutex_lock(&task_mutex);

    Task *task = task_array[index];
    task->priority = priority;
    strncpy(task->status, status, sizeof(task->status) - 1);

    pthread_mutex_unlock(&task_mutex);
}

// Thread-safe function to retrieve a task
Task* get_task(int index) {
    if (index < 0 || index >= task_count) {
        log_error("Invalid task index for retrieval.");
        return NULL;
    }

    pthread_mutex_lock(&task_mutex);

    Task *task = task_array[index];

    pthread_mutex_unlock(&task_mutex);
    return task;
}

// Parse deadlines from various date strings
int parse_deadline(const char *date_str, time_t *deadline) {
    struct tm tm = {0};
    if (strptime(date_str, "%Y-%m-%d", &tm)) {
        *deadline = mktime(&tm);
    } else if (strptime(date_str, "%b %d, %Y", &tm)) {
        *deadline = mktime(&tm);
    } else {
        log_error("Failed to parse date string.");
        return 0;
    }

    if (*deadline == -1) {
        log_error("Invalid date in deadline parsing.");
        return 0;
    }

    return 1;
}

// Health monitoring
void monitor_health(void) {
    // Placeholder for health checking logic, e.g., check packet count against thresholds.
    pthread_mutex_lock(&packet_mutex);
    if (packet_count > MAX_PACKETS / 2) {
        log_info("High packet load detected. Consider increasing limits.");
    }
    pthread_mutex_unlock(&packet_mutex);

    // Additional checks can be performed here
}

// Main function for demonstration purposes
