#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    long timestamp;
    double value;
} Entry;

typedef struct {
    Entry *entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    if (initial_capacity == 0) return NULL;

    DynamicArray *array = malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->entries = malloc(initial_capacity * sizeof(Entry));
    if (!array->entries) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);

    srand(time(NULL)); // Seed for random number generation

    for (size_t i = 0; i < initial_capacity; ++i) {
        Entry entry;
        entry.timestamp = time(NULL);
        entry.value = ((double)rand() / RAND_MAX);
        array->entries[i] = entry;
        array->count++;
    }

    return array;
}

void update_timestamps(DynamicArray *array) {
    if (!array) return;

    pthread_mutex_lock(&array->lock);

    long current_time = time(NULL);
    for (size_t i = 0; i < array->count; ++i) {
        array->entries[i].timestamp = current_time;
    }

    pthread_mutex_unlock(&array->lock);
}

int append_entry(DynamicArray *array, Entry new_entry) {
    if (!array) return -1;

    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        Entry *new_entries = realloc(array->entries, new_capacity * sizeof(Entry));
        if (!new_entries) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Memory allocation failed
        }
        array->entries = new_entries;
        array->capacity = new_capacity;
    }

    array->entries[array->count++] = new_entry;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

void destroy_dynamic_array(DynamicArray *array) {
    if (!array) return;

    free(array->entries);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

// Example usage
int main() {
    DynamicArray *array = create_dynamic_array(100);

    // Update timestamps periodically (e.g., in a separate thread)
    update_timestamps(array);

    // Append new entries
    Entry new_entry;
    new_entry.timestamp = time(NULL);
    new_entry.value = ((double)rand() / RAND_MAX);
    append_entry(array, new_entry);

    // Clean up
    destroy_dynamic_array(array);

    return 0;
}
```

