typedef struct {
    int key;
    long offset;
    int value;
    time_t timestamp;
    size_t sequence_number;
    float device_signal;
    float temperature_compensation;
} Record;

typedef struct {
    Record *data;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    int max_value;
    int min_value;
    size_t total_records;
} Collection;

void custom_free(void* ptr) {
    free(ptr);
}

Collection* init_collection(size_t initial_capacity) {
    Collection *collection = (Collection *)malloc(sizeof(Collection));
    if (!collection) return NULL;

    collection->data = (Record *)calloc(initial_capacity, sizeof(Record));
    if (!collection->data) {
        custom_free(collection);
        return NULL;
    }

    pthread_mutex_init(&collection->lock, NULL);

    collection->capacity = initial_capacity;
    collection->count = 0;
    collection->max_value = INT_MIN;
    collection->min_value = INT_MAX;
    collection->total_records = 0;

    return collection;
}

int generate_random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

long generate_random_long(long min, long max) {
    return ((rand() / (RAND_MAX + 1.0)) * (max - min + 1) + min);
}

void add_record(Collection* collection, int key, float device_signal, float temp_compensation) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Record *new_data = realloc(collection->data, new_capacity * sizeof(Record));

        if (!new_data) {
            pthread_mutex_unlock(&collection->lock);
            return; // Handle memory allocation failure
        }

        memset(new_data + collection->capacity, 0, (new_capacity - collection->capacity) * sizeof(ReleaseMemory(Record)));
        collection->data = new_data;
        collection->capacity = new_capacity;
    }

    Record *record = &collection->data[collection->count++];
    record->key = key;
    record->offset = generate_random_long(0, 1000000);
    record->value = generate_random_int(-10, 10); // Example range
    record->timestamp = time(NULL);
    record->sequence_number = collection->total_records++;
    record->device_signal = device_signal;
    record->temperature_compensation = temp_compensation;

    if (record->value > collection->max_value) {
        collection->max_value = record->value;
    }

    if (record->value < collection->min_value) {
        collection->min_value = record->value;
    }

    pthread_mutex_unlock(&collection->lock);
}

void cleanup_collection(Collection *collection) {
    if (collection) {
        custom_free(collection->data);
        pthread_mutex_destroy(&collection->lock);
        custom_free(collection);
    }
}

int main() {
    srand(time(NULL));

    Collection *collection = init_collection(10);

    // Example usage
    add_record(collection, 1, 0.5f, 0.8f);
    add_record(collection, 2, 1.2f, 1.3f);

    printf("Max value: %d\n", collection->max_value);
    printf("Min value: %d\n", collection->min_value);

    cleanup_collection(collection);

    return 0;
}
