Packet *packetArray = NULL;
size_t packetCount = 0;
const size_t maxPacketSize = 100; // Configurable maximum size

void initializeRandom(long *timestamp, double *measurement) {
    srand(time(NULL));
    *timestamp = rand() % 1000000L; // Example range
    *measurement = (double)(rand() % 10000) / 10.0; // Example range
}

SensorData* allocateSensorData(size_t sensorNameCount) {
    SensorData *data = malloc(sizeof(SensorData));
    if (!data) return NULL;

    data->sensorNames = malloc(sensorNameCount * sizeof(char *));
    for (size_t i = 0; i < sensorNameCount; ++i) {
        data->sensorNames[i] = strdup("SensorName"); // Example name
    }

    initializeRandom(&data->timestamp, &data->measurement);
    data->status = rand() % 2 ? 'A' : 'B'; // Example status

    return data;
}

void freeSensorData(SensorData *data) {
    if (data) {
        for (size_t i = 0; data->sensorNames && i < sensorNameCount; ++i) {
            free(data->sensorNames[i]);
        }
        free(data->sensorNames);
        free(data);
    }
}

void processPacket(Packet *packet) {
    pthread_mutex_lock(&lock);

    if (packetCount >= maxPacketSize) {
        free(packetArray[0].packetData); // Free oldest packet data
        memmove(&packetArray[0], &packetArray[1], sizeof(Packet) * (packetCount - 1));
        --packetCount;
    }

    if (packetArray == NULL) {
        packetArray = malloc(sizeof(Packet));
    } else {
        packetArray = realloc(packetArray, sizeof(Packet) * (packetCount + 1));
    }

    packetArray[packetCount] = *packet;

    pthread_mutex_unlock(&lock);
}

void* disposeOldPackets(void *arg) {
    while (1) {
        sleep(5); // Example interval
        pthread_mutex_lock(&lock);

        if (packetCount > maxPacketSize / 2) { // Adjust threshold as needed
            free(packetArray[0].packetData);
            memmove(&packetArray[0], &packetArray[1], sizeof(Packet) * (packetCount - 1));
            --packetCount;
        }

        pthread_mutex_unlock(&lock);
    }
}

void startPacketDisposalThread() {
    pthread_t threadID;
    pthread_create(&threadID, NULL, disposeOldPackets, NULL);
}

int loadResourceBundle(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) return 0;

    int itemCount = 0;
    while (!feof(file)) {
        char buffer[256];
        if (fgets(buffer, sizeof(buffer), file)) {
            ++itemCount;
        }
    }

    fclose(file);
    return itemCount;
}
```

