}

NFAPI_CRC_INDICATION_PDU_T* createCRCList(int count, int (*validate)(NFAPI_CRC_INDICATION_PDU_T*)) {
    NFAPI_CRC_INDICATION_PDU_T *head = NULL, *tail = NULL;

    for (int i = 0; i < count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!node) {
            freeCRCList(head);
            return NULL;
        }

        node->RX_UE_INFORMATION_TAG = rand();
        node->RNTI = rand() % 1000; // Example range
        node->CRC_INDICATION_REL8_TAG = (rand() & 1) ? 'Y' : 'N'; // Example: Random CRCFLAG

        if (!validate(node)) {
            fprintf(stderr, "Error: Invalid structure at index %d\n", i);
            free(node);
            continue;
        }

        node->next = NULL;

        pthread_mutex_lock(&mutex);
        if (!head) {
            head = node;
        } else {
            tail->next = node;
        }
        tail = node;
        pthread_mutex_unlock(&mutex);
    }

    return head;
}

void freeCRCList(NFAPI_CRC_INDICATION_PDU_T *head) {
    NFAPI_CRC_INDICATION_PDU_T *tmp;

    while (head) {
        tmp = head;
        head = head->next;
        free(tmp);
    }
}
