typedef struct {
    int value;
} record;

#define CACHE_LINE_SIZE 64

void log(const char *message) {
    printf("%s\n", message);
}

int align_up(size_t size, size_t alignment) {
    return (size + alignment - 1) & ~(alignment - 1);
}

int validate_memory(void *ptr, size_t size) {
    // Simulate memory validation; in real scenarios, use platform-specific APIs
    if (!ptr || ((uintptr_t)ptr % CACHE_LINE_SIZE != 0)) {
        log("Memory validation failed.");
        return 0;
    }
    return 1;
}

int generate_unique_key(int used_keys[], int max_size) {
    while (1) {
        int key = rand() % max_size;
        if (!used_keys[key]) {
            used_keys[key] = 1;
            return key;
        }
    }
}

void initialize_arrays(long *offsets, int *keys, record *records, size_t size, unsigned long seed, int value_range_min, int value_range_max) {
    srand(seed);

    for (size_t i = 0; i < size; ++i) {
        offsets[i] = rand() % size;
        keys[i] = generate_unique_key(keys, size);
        records[i].value = (rand() % (value_range_max - value_range_min + 1)) + value_range_min;
    }
}

void* aligned_alloc(size_t size, size_t alignment) {
    void *ptr = NULL;
#if defined(_WIN32)
    ptr = _aligned_malloc(size, alignment);
#else
    if (posix_memalign(&ptr, alignment, size) != 0) {
        ptr = NULL;
    }
#endif
    return ptr;
}

int free_memory(void *ptr, size_t size) {
    if (!validate_memory(ptr, size)) {
        return -1;
    }

#if defined(_WIN32)
    _aligned_free(ptr);
#else
    free(ptr);
#endif
    return 0;
}

size_t get_unique_keys_count(const int *keys, size_t size) {
    int used_keys[size];
    memset(used_keys, 0, sizeof(int) * size);

    for (size_t i = 0; i < size; ++i) {
        used_keys[keys[i]] = 1;
    }

    size_t count = 0;
    for (size_t i = 0; i < size; ++i) {
        if (used_keys[i]) {
            count++;
        }
    }

    return count;
}

int main() {
    size_t size = 1000;
    unsigned long seed = 12345;
    int value_range_min = 10, value_range_max = 100;

    log("Allocating memory...");
    long *offsets = aligned_alloc(align_up(sizeof(long) * size, CACHE_LINE_SIZE), CACHE_LINE_SIZE);
    int *keys = aligned_alloc(align_up(sizeof(int) * size, CACHE_LINE_SIZE), CACHE_LINE_SIZE);
    record *records = aligned_alloc(align_up(sizeof(record) * size, CACHE_LINE_SIZE), CACHE_LINE_SIZE);

    if (!validate_memory(offsets, sizeof(long) * size) ||
        !validate_memory(keys, sizeof(int) * size) ||
        !validate_memory(records, sizeof(record) * size)) {
        log("Memory allocation or validation failed.");
        return -1;
    }

    initialize_arrays(offsets, keys, records, size, seed, value_range_min, value_range_max);

    log("Retrieving unique key count...");
    size_t unique_keys_count = get_unique_keys_count(keys, size);
    printf("Unique keys count: %zu\n", unique_keys_count);

    log("Freeing memory...");
    if (free_memory(offsets, sizeof(long) * size) != 0 ||
        free_memory(keys, sizeof(int) * size) != 0 ||
        free_memory(records, sizeof(record) * size) != 0) {
        log("Memory deallocation failed.");
        return -1;
    }

    log("Execution completed successfully.");
    return 0;
}
