#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long timestamp;
    float temperature;
    int key;
    float value;
} DataPacket;

int streamProcessingModule(DataPacket **dataArray, size_t count, 
                          float tempMin, float tempMax, 
                          int keyMin, int keyMax) {

    // Check for invalid parameters
    if (dataArray == NULL || count <= 0 || tempMin >= tempMax || keyMin > keyMax)
        return -1;

    srand((unsigned)time(NULL)); // Seed the random number generator

    *dataArray = malloc(count * sizeof(DataPacket));
    if (*dataArray == NULL) {
        printf("Memory allocation failed\n");
        return -2; // Indicate memory allocation failure
    }

    for (size_t i = 0; i < count; ++i) {
        (*dataArray)[i].timestamp = time(NULL);
        (*dataArray)[i].temperature = tempMin + ((float)rand() / RAND_MAX) * (tempMax - tempMin);
        (*dataArray)[i].key = keyMin + rand() % (keyMax - keyMin + 1);
        (*dataArray)[i].value = (float)rand(); // Random float value
    }

    return 0; // Indicate success
}

int main() {
    size_t numPackets = 100;
    DataPacket *packets = NULL;

    if (streamProcessingModule(&packets, numPackets, -10.0f, 35.0f, 1, 100) == 0) {
        printf("Data packets initialized successfully.\n");
        // Use the data packets for further processing
        free(packets); // Don't forget to free allocated memory
    } else {
        printf("Failed to initialize data packets.\n");
    }

    return 0;
}
