// C Module for Managing NR_PHY_RX_FRAME_PDU_T Structures

#include <stdlib.h>
#include <pthread.h>

typedef struct {
    // Define fields for NR_RX_FRAME_INFO_T and NR_PHY_SYNC_RESULT_T
} NR_PHY_RX_FRAME_PDU_T;

typedef struct {
    NR_PHY_RX_FRAME_PDU_T* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} PduList;

void initializePduList(PduList* list, size_t initialCapacity) {
    list->data = (NR_PHY_RX_FRAME_PDU_T*)malloc(initialCapacity * sizeof(NR_PHY_RX_FRAME_PDU_T));
    list->capacity = initialCapacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void addPdu(PduList* list, NR_PHY_RX_FRAME_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= list->capacity) {
        size_t newCapacity = list->capacity * 2;
        list->data = realloc(list->data, newCapacity * sizeof(NR_PHY_RX_FRAME_PDU_T));
        list->capacity = newCapacity;
    }

    list->data[list->size++] = pdu;

    pthread_mutex_unlock(&list->lock);
}

void freePduList(PduList* list) {
    pthread_mutex_lock(&list->lock);

    free(list->data);
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
}
