        ("Synchronization Accuracy Test", execute_tests.sync_accuracy_test),
        ("Load Stress Test", execute_tests.load_stress_test)
    ]

    threads = []

    for name, test in tests:
        thread = Thread(target=run_test, args=(test, name))
        threads.append(thread)
        thread.start()

    for thread in threads:
        thread.join()

if __name__ == "__main__":
