#include <iostream>
#include <string>
#include <unordered_map>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <vector>
#include <memory>
#include <random>
#include <chrono>
#include <openssl/evp.h>

namespace ConfigCryptLib {

    enum class ValueType { Integer, String, Boolean };

    struct Configuration {
        std::string key;
        ValueType type;
        union Value {
            int intValue;
            bool boolValue;
            std::string* stringValue;
        } value;
        void* defaultValue;
    };

    using ConfigurationMap = std::unordered_map<std::string, Configuration>;

    class ConfigManager {
    private:
        mutable std::mutex configMutex;
        ConfigurationMap configs;
        size_t totalSize = 0;

        void updateTotalSize(Configuration& config) {
            if (config.type == ValueType::String && config.value.stringValue != nullptr) {
                totalSize += sizeof(std::string*) + config.value.stringValue->size();
            } else {
                totalSize += sizeof(config.value.intValue);
            }
        }

    public:
        ConfigManager() = default;

        void setConfig(const std::string& key, ValueType type, const void* defaultValue) {
            std::lock_guard<std::mutex> lock(configMutex);
            if (configs.find(key) == configs.end()) {
                Configuration config;
                config.key = key;
                config.type = type;
                config.defaultValue = new char[sizeof(*defaultValue)];
                memcpy(config.defaultValue, defaultValue, sizeof(*defaultValue));

                switch (type) {
                    case ValueType::Integer:
                        config.value.intValue = *static_cast<int*>(defaultValue);
                        break;
                    case ValueType::Boolean:
                        config.value.boolValue = *static_cast<bool*>(defaultValue);
                        break;
                    case ValueType::String:
                        config.value.stringValue = new std::string(*static_cast<std::string*>(defaultValue));
                        break;
                }

                configs[key] = config;
                updateTotalSize(configs[key]);
            } else {
                // Update existing configuration with validation and memory management
                Configuration& existingConfig = configs[key];
                delete[] static_cast<char*>(existingConfig.defaultValue);

                switch (type) {
                    case ValueType::Integer:
                        if (existingConfig.type == ValueType::Integer)
                            existingConfig.value.intValue = *static_cast<int*>(defaultValue);
                        break;
                    case ValueType::Boolean:
                        if (existingConfig.type == ValueType::Boolean)
                            existingConfig.value.boolValue = *static_cast<bool*>(defaultValue);
                        break;
                    case ValueType::String:
                        if (existingConfig.type == ValueType::String) {
                            delete existingConfig.value.stringValue;
                            existingConfig.value.stringValue = new std::string(*static_cast<std::string*>(defaultValue));
                        }
                        break;
                }

                updateTotalSize(existingConfig);
            }
        }

        template<typename T>
        T getConfig(const std::string& key, const T& defaultValue) {
            std::lock_guard<std::mutex> lock(configMutex);
            auto it = configs.find(key);

            if (it != configs.end()) {
                switch (it->second.type) {
                    case ValueType::Integer:
                        return static_cast<T>(it->second.value.intValue);
                    case ValueType::Boolean:
                        return static_cast<T>(it->second.value.boolValue);
                    case ValueType::String:
                        return *static_cast<std::string*>(it->second.value.stringValue);
                }
            }

            return defaultValue;
        }

        size_t getTotalSize() const {
            std::lock_guard<std::mutex> lock(configMutex);
            return totalSize;
        }

