// Helper function to create a new DataObject
DataObject* create_data_object(const Resource *resource) {
    DataObject *obj = (DataObject *)malloc(sizeof(DataObject));
    if (!obj) return NULL;
    obj->timestamp = time(NULL);
    obj->status_flag = 0; // Default status flag
    memcpy(&obj->resource, resource, sizeof(Resource));
    return obj;
}

// Initialize DynamicCollection with thread-safe mechanisms
DynamicCollection* init_collection(size_t initial_capacity) {
    DynamicCollection *collection = (DynamicCollection *)malloc(sizeof(DynamicCollection));
    if (!collection) return NULL;

    collection->objects = (DataObject *)malloc(initial_capacity * sizeof(DataObject));
    if (!collection->objects) {
        free(collection);
        return NULL;
    }

    pthread_mutex_init(&collection->mutex, NULL);
    collection->count = 0;
    collection->capacity = initial_capacity;

    return collection;
}

// Thread-safe function to add a new DataObject
int add_data_object(DynamicCollection *collection, const Resource *resource) {
    pthread_mutex_lock(&collection->mutex);

    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        DataObject *new_objects = (DataObject *)realloc(collection->objects, new_capacity * sizeof(DataObject));
        if (!new_objects) {
            pthread_mutex_unlock(&collection->mutex);
            return -1; // Memory allocation failed
        }
        collection->objects = new_objects;
        collection->capacity = new_capacity;
    }

    DataObject *obj = create_data_object(resource);
    if (!obj) {
        pthread_mutex_unlock(&collection->mutex);
        return -1; // Object creation failed
    }
    collection->objects[collection->count++] = *obj;

    free(obj); // Free temporary allocation
    pthread_mutex_unlock(&collection->mutex);

    return 0;
}

