    for (size_t i = 1; i < count; ++i) {
        if (list[i].CRCFLAG > largest) {
            largest = list[i].CRCFLAG;
        }
    }
    return largest;
}

// Semaphore management functions
sem_t *init_semaphore(int value) {
    sem_t *sem = malloc(sizeof(sem_t));
    if (!sem) return NULL;
    sem_init(sem, 0, value);
    return sem;
}

void delete_semaphore(sem_t *sem) {
    if (sem) {
        sem_destroy(sem);
        free(sem);
    }
}

// Serialization and deserialization methods
int serialize_data_object(const DataObject *obj, char **buffer, size_t *size) {
    // Serialize the object to a buffer
    *size = sizeof(DataObject);
    *buffer = malloc(*size);
    if (!*buffer) return -1;
    memcpy(*buffer, obj, *size);
    return 0;
}

int deserialize_data_object(const char *buffer, size_t size, DataObject **obj) {
    // Deserialize the buffer into a DataObject
