#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

typedef struct {
    int value;
    pthread_mutex_t lock;
} Record;

typedef struct {
    Record *records;
    long *offsets;
    int *keys;
    size_t count;
    size_t capacity;
    double totalSum;
    double avgAccessFrequency;
    pthread_rwlock_t rwlock;
} DataStore;

// Helper function to safely add two integers with overflow check
int safe_add(int a, int b) {
    if ((b > 0 && a > INT_MAX - b) || (b < 0 && a < INT_MIN - b)) {
        fprintf(stderr, "Integer overflow detected\n");
        exit(EXIT_FAILURE);
    }
    return a + b;
}

// Helper function to safely multiply two integers with overflow check
int safe_mul(int a, int b) {
    if (a > 0 && b > 0 && a > INT_MAX / b) {
        fprintf(stderr, "Integer overflow detected\n");
        exit(EXIT_FAILURE);
    }
    if (a < 0 && b < 0 && a < INT_MIN / b) {
        fprintf(stderr, "Integer overflow detected\n");
        exit(EXIT_FAILURE);
    }
    return a * b;
}

// Function to initialize the data store
DataStore* init_data_store(size_t initial_capacity) {
    DataStore *store = malloc(sizeof(DataStore));
    if (!store) return NULL;

    store->records = calloc(initial_capacity, sizeof(Record));
    store->offsets = calloc(initial_capacity, sizeof(long));
    store->keys = calloc(initial_capacity, sizeof(int));
    store->count = 0;
    store->capacity = initial_capacity;
    store->totalSum = 0.0;
    store->avgAccessFrequency = 0.0;

    pthread_rwlock_init(&store->rwlock, NULL);
    for (size_t i = 0; i < initial_capacity; ++i) {
        pthread_mutex_init(&store->records[i].lock, NULL);
    }

    return store;
}

// Function to resize the data store
int resize_data_store(DataStore *store, size_t new_capacity) {
    if (new_capacity <= store->capacity) return 0;

    Record *new_records = realloc(store->records, new_capacity * sizeof(Record));
    long *new_offsets = realloc(store->offsets, new_capacity * sizeof(long));
    int *new_keys = realloc(store->keys, new_capacity * sizeof(int));

    if (!new_records || !new_offsets || !new_keys) return -1;

    store->records = new_records;
    store->offsets = new_offsets;
    store->keys = new_keys;
    store->capacity = new_capacity;

    for (size_t i = store->count; i < new_capacity; ++i) {
        pthread_mutex_init(&store->records[i].lock, NULL);
    }

    return 0;
}

// Function to add a record
int add_record(DataStore *store, int key, int value_range_min, int value_range_max) {
    pthread_rwlock_wrlock(&store->rwlock);

    if (store->count >= store->capacity && resize_data_store(store, store->capacity * 2) != 0) {
        pthread_rwlock_unlock(&store->rwlock);
        return -1;
    }

    Record *record = &store->records[store->count];
    pthread_mutex_lock(&record->lock);

    int cumulative_sum = 0;
    for (size_t i = 0; i < store->count; ++i) {
        cumulative_sum += store->records[i].value;
    }
    double avg_access_frequency = store->avgAccessFrequency;

    // Generate random value
    srand(time(NULL) ^ pthread_self());
    int random_value = rand() % (value_range_max - value_range_min + 1) + value_range_min;
    record->value = safe_add(random_value, cumulative_sum / (store->count ? store->count : 1));
    record->value = safe_add(record->value, avg_access_frequency);

    // Update total sum and average access frequency
    store->totalSum = safe_add(store->totalSum, record->value);
    store->avgAccessFrequency = ((store->avgAccessFrequency * store->count) + random_value) / (store->count + 1);

    store->keys[store->count] = key;
    store->offsets[store->count] = rand(); // Example offset value

    pthread_mutex_unlock(&record->lock);
    store->count++;

    pthread_rwlock_unlock(&store->rwlock);
    return 0;
}

// Function to serialize the data store
int serialize_data_store(DataStore *store, const char *filename) {
    pthread_rwlock_rdlock(&store->rwlock);

    FILE *file = fopen(filename, "wb");
    if (!file) {
        pthread_rwlock_unlock(&store->rwlock);
        return -1;
    }

    fwrite(&store->count, sizeof(size_t), 1, file);
    fwrite(store->records, sizeof(Record), store->count, file);
    fwrite(store->offsets, sizeof(long), store->count, file);
    fwrite(store->keys, sizeof(int), store->count, file);

    fclose(file);
    pthread_rwlock_unlock(&store->rwlock);
    return 0;
}

// Function to free the data store
void free_data_store(DataStore *store) {
    if (!store) return;

    for (size_t i = 0; i < store->capacity; ++i) {
        pthread_mutex_destroy(&store->records[i].lock);
    }

    free(store->records);
    free(store->offsets);
    free(store->keys);

    pthread_rwlock_destroy(&store->rwlock);
    free(store);
}

int main() {
    DataStore *store = init_data_store(1000);
    if (!store) {
        fprintf(stderr, "Failed to initialize data store\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 10000; ++i) {
        add_record(store, rand(), 1, 100);
    }

    serialize_data_store(store, "data_store.dat");

    free_data_store(store);
    return EXIT_SUCCESS;
}
