#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef enum { INFO, DEBUG, ERROR } LogLevel;

typedef struct LogEntry {
    time_t timestamp;
    LogLevel logLevel;
    char *message;
    struct LogEntry *next;
} LogEntry;

typedef struct SourceInfo {
    int sourceID;
    int infoCount;
    int debugCount;
    int errorCount;
    long firstTimestamp;
    long lastTimestamp;
    struct SourceInfo *next;
} SourceInfo;

LogEntry* initializeLogList() {
    return NULL;
}

int validateLogEntry(LogEntry *entry) {
    if (!entry || !entry->message || entry->timestamp <= 0)
        return 0;
    return 1;
}

void addLogEntry(LogEntry **head, LogEntry *newEntry) {
    newEntry->next = *head;
    *head = newEntry;
}

SourceInfo* findOrCreateSource(SourceInfo **sources, int sourceID) {
    SourceInfo *current = *sources;
    while (current) {
        if (current->sourceID == sourceID)
            return current;
        current = current->next;
    }
    SourceInfo *newSource = (SourceInfo *)malloc(sizeof(SourceInfo));
    if (!newSource) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    newSource->sourceID = sourceID;
    newSource->infoCount = 0;
    newSource->debugCount = 0;
    newSource->errorCount = 0;
    newSource->firstTimestamp = -1;
    newSource->lastTimestamp = 0;
    newSource->next = *sources;
    *sources = newSource;
    return newSource;
}

void processLogEntry(LogEntry **logList, SourceInfo **sourceList, int sourceID, LogEntry *entry) {
    if (!validateLogEntry(entry)) {
        free(entry->message);
        free(entry);
        return;
    }
    addLogEntry(logList, entry);

    SourceInfo *source = findOrCreateSource(sourceList, sourceID);
    switch (entry->logLevel) {
        case INFO: source->infoCount++; break;
        case DEBUG: source->debugCount++; break;
        case ERROR: source->errorCount++; break;
    }
    if (source->firstTimestamp == -1 || entry->timestamp < source->firstTimestamp)
        source->firstTimestamp = entry->timestamp;
    if (entry->timestamp > source->lastTimestamp)
        source->lastTimestamp = entry->timestamp;

    free(entry->message);
    free(entry);
}

void calculateAverageRate(SourceInfo *sources) {
    SourceInfo *current = sources;
    while (current) {
        double duration = difftime(current->lastTimestamp, current->firstTimestamp);
        if (duration > 0) {
            double rate = ((double)(current->infoCount + current->debugCount + current->errorCount)) / duration;
            printf("Source %d: %.2f logs per second\n", current->sourceID, rate);
        }
        current = current->next;
    }
}

void generateSummaryReport(SourceInfo *sources) {
    SourceInfo *current = sources;
    int maxErrorCount = 0;
    int errorSourceID = -1;

    while (current) {
        if (current->errorCount > maxErrorCount) {
            maxErrorCount = current->errorCount;
            errorSourceID = current->sourceID;
        }
        current = current->next;
    }

    char report[1024] = {0};
    sprintf(report, "Summary Report:\n");
    current = sources;
    while (current) {
        strcat(report, "Source ID: ");
        char buffer[32];
        sprintf(buffer, "%d\n", current->sourceID);
        strcat(report, buffer);

        strcat(report, "INFO: ");
        sprintf(buffer, "%d\n", current->infoCount);
        strcat(report, buffer);

        strcat(report, "DEBUG: ");
        sprintf(buffer, "%d\n", current->debugCount);
        strcat(report, buffer);

        strcat(report, "ERROR: ");
        sprintf(buffer, "%d\n", current->errorCount);
        strcat(report, buffer);

        if (current->sourceID == errorSourceID) {
            strcat(report, "* Highest ERROR count *\n");
        }

        strcat(report, "\n");
        current = current->next;
    }
    printf("%s", report);
}

void freeSources(SourceInfo **sources) {
    SourceInfo *current = *sources;
    while (current) {
        SourceInfo *next = current->next;
        free(current);
        current = next;
    }
    *sources = NULL;
}

int main() {
    LogEntry *logList = initializeLogList();
    SourceInfo *sourceList = NULL;

    int sourceID;
    time_t timestamp;
    LogLevel logLevel;
    char message[256];

    while (scanf("%d %ld %d %[^\n]", &sourceID, &timestamp, &logLevel, message) == 4) {
        LogEntry *entry = (LogEntry *)malloc(sizeof(LogEntry));
        if (!entry) {
            fprintf(stderr, "Out of memory\n");
            exit(EXIT_FAILURE);
        }
        entry->timestamp = timestamp;
        entry->logLevel = logLevel;
        entry->message = strdup(message);
        processLogEntry(&logList, &sourceList, sourceID, entry);
    }

    generateSummaryReport(sourceList);
    calculateAverageRate(sourceList);

    freeSources(&sourceList);
    return 0;
}
