#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>

// Define a node structure for the linked list.
typedef struct Node {
    int key;
    int value;
    struct Node* next;
} Node;

// Define the record collection structure with a lock-free mechanism and thread-safe operations.
typedef struct RecordCollection {
    Node* head;
    pthread_mutex_t mutex;
} RecordCollection;

// Function to initialize the record collection.
RecordCollection* create_record_collection() {
    RecordCollection* rc = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!rc) return NULL;

    rc->head = NULL;
    pthread_mutex_init(&rc->mutex, NULL);
    return rc;
}

// Lock-free insert/update node into the linked list.
void insert_record(RecordCollection* rc, int key, int value) {
    Node** current = &(rc->head);

    while (*current != NULL) {
        if ((*current)->key == key) {
            pthread_mutex_lock(&rc->mutex);
            (*current)->value = value;
            pthread_mutex_unlock(&rc->mutex);
            return;
        }
        current = &((*current)->next);
    }

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return;

    newNode->key = key;
    newNode->value = value;
    newNode->next = *current;

    pthread_mutex_lock(&rc->mutex);
    *current = newNode;
    pthread_mutex_unlock(&rc->mutex);
}

// Delete node by key.
void delete_record(RecordCollection* rc, int key) {
    pthread_mutex_lock(&rc->mutex);

    Node** current = &(rc->head);
    while (*current != NULL && (*current)->key != key) {
        current = &((*current)->next);
    }

    if (*current != NULL) {
        Node* temp = *current;
        *current = (*current)->next;
        free(temp);
    }

    pthread_mutex_unlock(&rc->mutex);
}

// Retrieve value by key.
int get_record(RecordCollection* rc, int key) {
    pthread_mutex_lock(&rc->mutex);

    Node* current = rc->head;
    while (current != NULL && current->key != key) {
        current = current->next;
    }

    int value = (current != NULL) ? current->value : -1;

    pthread_mutex_unlock(&rc->mutex);
    return value;
}

// Serialize the record collection to a file.
int serialize_record_collection(RecordCollection* rc, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return 0;

    Node* current = rc->head;
    while (current != NULL) {
        fwrite(&current->key, sizeof(int), 1, file);
        fwrite(&current->value, sizeof(int), 1, file);
        current = current->next;
    }

    fclose(file);
    return 1;
}

// Deserialize the record collection from a file.
int deserialize_record_collection(RecordCollection* rc, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return 0;

    int key, value;
    while (fread(&key, sizeof(int), 1, file) == 1 && fread(&value, sizeof(int), 1, file) == 1) {
        insert_record(rc, key, value);
    }

    fclose(file);
    return 1;
}

// Free the record collection.
void free_record_collection(RecordCollection* rc) {
    pthread_mutex_lock(&rc->mutex);

    Node* current = rc->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&rc->mutex);
    pthread_mutex_destroy(&rc->mutex);
    free(rc);
}

// Test cases to demonstrate functionality.
void test_record_collection() {
    RecordCollection *rc = create_record_collection();
    if (!rc) return;

    insert_record(rc, 1, 100);
    insert_record(rc, 2, 200);

    printf("Value for key 1: %d\n", get_record(rc, 1));
    printf("Value for key 2: %d\n", get_record(rc, 2));

    delete_record(rc, 1);
    printf("Value for key 1 after deletion: %d\n", get_record(rc, 1));

    if (serialize_record_collection(rc, "records.bin")) {
        RecordCollection *rc_copy = create_record_collection();
        deserialize_record_collection(rc_copy, "records.bin");
        printf("Deserialized value for key 2: %d\n", get_record(rc_copy, 2));
        free_record_collection(rc_copy);
    }

    free_record_collection(rc);
}

int main() {
    test_record_collection();
    return 0;
}
```

**Notes:**
- The code uses a simple mutex lock to ensure thread-safety during insertions, deletions, and retrievals. This is because a complete lock-free design would significantly increase the complexity for this example.
- Serialization and deserialization functions handle basic I/O operations with error checking.
- Tests are included within `test_record_collection` function demonstrating normal operations and serialization functionality.
- For production use, consider more robust error handling and additional concurrency management mechanisms.']

