['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>
#include <openssl/md5.h>

#define MAX_RECORDS 1000
#define KEY_RANGE 100
#define VALUE_RANGE 1000

typedef struct {
    int value;
    pthread_mutex_t lock;
} Record;

typedef struct {
    Record *records;
    int *keys;
    long *offsets;
    size_t count;
    size_t capacity;
    double totalValueSum;
    double accessFrequencyAverage;
    pthread_rwlock_t rwlock;
} DataStore;

void init_data_store(DataStore *store, size_t initial_capacity) {
    store->records = (Record *)calloc(initial_capacity, sizeof(Record));
    store->keys = (int *)malloc(initial_capacity * sizeof(int));
    store->offsets = (long *)malloc(initial_capacity * sizeof(long));
    store->count = 0;
    store->capacity = initial_capacity;
    store->totalValueSum = 0.0;
    store->accessFrequencyAverage = 0.0;
    pthread_rwlock_init(&store->rwlock, NULL);
}

void resize_data_store(DataStore *store) {
    size_t new_capacity = store->capacity * 2;
    Record *new_records = (Record *)realloc(store->records, new_capacity * sizeof(Record));
    int *new_keys = (int *)realloc(store->keys, new_capacity * sizeof(int));
    long *new_offsets = (long *)realloc(store->offsets, new_capacity * sizeof(long));

    if (new_records && new_keys && new_offsets) {
        store->records = new_records;
        store->keys = new_keys;
        store->offsets = new_offsets;
        store->capacity = new_capacity;
    }
}

void free_data_store(DataStore *store) {
    for (size_t i = 0; i < store->count; ++i) {
        pthread_mutex_destroy(&store->records[i].lock);
    }
    free(store->records);
    free(store->keys);
    free(store->offsets);
    pthread_rwlock_destroy(&store->rwlock);
}

void update_record(DataStore *store, size_t index, int value) {
    if (index >= store->count) return;

    pthread_mutex_lock(&store->records[index].lock);
    int oldValue = store->records[index].value;
    store->totalValueSum -= oldValue;
    store->totalValueSum += value;
    store->records[index].value = value;
    pthread_mutex_unlock(&store->records[index].lock);

    pthread_rwlock_wrlock(&store->rwlock);
    store->accessFrequencyAverage = (store->accessFrequencyAverage * index + 1) / (index + 1);
    pthread_rwlock_unlock(&store->rwlock);
}

void initialize_records(DataStore *store, int range_min, int range_max) {
    srand(time(NULL));
    for (size_t i = 0; i < store->count; ++i) {
        int value = rand() % (range_max - range_min + 1) + range_min;
        update_record(store, i, value);
    }
}

uint8_t *compute_md5_hash(const char *str, size_t *len) {
    if (!str || !len) return NULL;

    MD5_CTX ctx;
    uint8_t hash[MD5_DIGEST_LENGTH];
    int result = MD5_Init(&ctx);
    if (result != 1) return NULL;

    result = MD5_Update(&ctx, str, strlen(str));
    if (result != 1) return NULL;

    result = MD5_Final(hash, &ctx);
    if (result != 1) return NULL;

    *len = MD5_DIGEST_LENGTH;
    uint8_t *digest = malloc(*len);
    if (!digest) return NULL;

    memcpy(digest, hash, *len);
    return digest;
}

void serialize_data_store(DataStore *store, const char *filename) {
    pthread_rwlock_rdlock(&store->rwlock);

    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&store->count, sizeof(size_t), 1, file);
    fwrite(store->records, sizeof(Record), store->count, file);
    fwrite(store->keys, sizeof(int), store->count, file);
    fwrite(store->offsets, sizeof(long), store->count, file);
    fwrite(&store->totalValueSum, sizeof(double), 1, file);
    fwrite(&store->accessFrequencyAverage, sizeof(double), 1, file);

    size_t hash_len;
    uint8_t *hash = compute_md5_hash("specific_string_key", &hash_len);
    if (hash) {
        fwrite(hash, sizeof(uint8_t), hash_len, file);
        free(hash);
    }

    fclose(file);
    pthread_rwlock_unlock(&store->rwlock);
}

void manage_records(DataStore *store, int range_min, int range_max, const char *filename) {
    init_data_store(store, 10);

    while (store->count < MAX_RECORDS || store->capacity - store->count > 0) {
        if (store->count == store->capacity) {
            resize_data_store(store);
        }

        pthread_mutex_t lock;
        pthread_mutex_init(&lock, NULL);
        store->records[store->count].value = 0;
        store->records[store->count].lock = lock;
        store->keys[store->count] = rand() % KEY_RANGE;
        store->offsets[store->count] = (long)(rand() % 100000);

        pthread_rwlock_wrlock(&store->rwlock);
        store->count++;
        pthread_rwlock_unlock(&store->rwlock);
    }

    initialize_records(store, range_min, range_max);
    serialize_data_store(store, filename);

    free_data_store(store);
}
