void initialize_profile(UserProfile *profile) {
    profile->username = NULL;
    profile->email = NULL;
    profile->creation_timestamp = time(NULL);
    profile->num_activities = 0;
    profile->activity_capacity = INITIAL_ACTIVITIES_PER_PROFILE;
    profile->activities = malloc(sizeof(double) * profile->activity_capacity);
}

void free_profile(UserProfile *profile) {
    if (profile->username) free(profile->username);
    if (profile->email) free(profile->email);
    if (profile->activities) free(profile->activities);
}

void add_user_profile(const char *username, const char *email) {
    pthread_mutex_lock(&manager.lock);

    if (manager.profile_count >= MAX_PROFILES) {
        printf("Max profiles reached.\n");
        pthread_mutex_unlock(&manager.lock);
        return;
    }

    UserProfile *profile = &manager.profiles[manager.profile_count++];
    profile->username = strdup(username);
    profile->email = strdup(email);
    initialize_profile(profile);

    pthread_mutex_unlock(&manager.lock);
}

void add_activity_to_profile(int index, double duration) {
    pthread_mutex_lock(&manager.lock);

    if (index < 0 || index >= manager.profile_count) {
        printf("Invalid profile index.\n");
        pthread_mutex_unlock(&manager.lock);
        return;
    }

    UserProfile *profile = &manager.profiles[index];
    if (profile->num_activities >= profile->activity_capacity) {
        profile->activity_capacity *= 2;
        profile->activities = realloc(profile->activities, sizeof(double) * profile->activity_capacity);
    }

    profile->activities[profile->num_activities++] = duration;

    manager.total_duration += duration;
    manager.session_frequency_sum += 1.0; // Assuming each activity is a session
    manager.session_count++;

    pthread_mutex_unlock(&manager.lock);
}

void serialize_profiles(const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&manager.profile_count, sizeof(int), 1, file);
    for (int i = 0; i < manager.profile_count; ++i) {
        UserProfile profile = manager.profiles[i];
        size_t username_len = strlen(profile.username);
        size_t email_len = strlen(profile.email);

        fwrite(&username_len, sizeof(size_t), 1, file);
        fwrite(profile.username, sizeof(char), username_len + 1, file);

        fwrite(&email_len, sizeof(size_t), 1, file);
        fwrite(profile.email, sizeof(char), email_len + 1, file);

        fwrite(&profile.creation_timestamp, sizeof(time_t), 1, file);
        fwrite(&profile.num_activities, sizeof(int), 1, file);
        fwrite(&profile.activity_capacity, sizeof(size_t), 1, file);

        fwrite(profile.activities, sizeof(double), profile.num_activities, file);
    }

    fclose(file);
}

void deserialize_profiles(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    fread(&manager.profile_count, sizeof(int), 1, file);

    for (int i = 0; i < manager.profile_count; ++i) {
        UserProfile profile;
        size_t username_len, email_len;

        fread(&username_len, sizeof(size_t), 1, file);
        profile.username = malloc(username_len + 1);
        fread(profile.username, sizeof(char), username_len + 1, file);

        fread(&email_len, sizeof(size_t), 1, file);
        profile.email = malloc(email_len + 1);
        fread(profile.email, sizeof(char), email_len + 1, file);

        fread(&profile.creation_timestamp, sizeof(time_t), 1, file);
        fread(&profile.num_activities, sizeof(int), 1, file);
        fread(&profile.activity_capacity, sizeof(size_t), 1, file);

        profile.activities = malloc(sizeof(double) * profile.activity_capacity);
        fread(profile.activities, sizeof(double), profile.num_activities, file);

        manager.profiles[i] = profile;
    }

    fclose(file);
}

void cleanup_manager() {
    pthread_mutex_lock(&manager.lock);

    for (int i = 0; i < manager.profile_count; ++i) {
        free_profile(&manager.profiles[i]);
    }

    pthread_mutex_unlock(&manager.lock);
}

// Example of random activity generation
double generate_random_activity(double min_duration, double max_duration) {
    return ((double)rand() / RAND_MAX) * (max_duration - min_duration) + min_duration;
}
```

