void* processStringAndManageMemory(const char* input, int sizeLimit, void (*callback)(const char*)) {
    if (!input || strlen(input) > sizeLimit) {
        return NULL;
    }

    // Allocate memory for the new string with a slash
    char* processedString = (char*)malloc(strlen(input) + 2);
    strcpy(processedString, input);
    strcat(processedString, "/");

    // Call the callback function
    if (callback) {
        callback(processedString);
    }

    return processedString;
}

MemoryPool* createMemoryPool() {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pool->base = malloc(INITIAL_POOL_SIZE);
    pool->capacity = INITIAL_POOL_SIZE;
    pool->used = 0;
    pthread_mutex_init(&pool->lock, NULL);
    pool->totalValue = 0;

    return pool;
}

int resizeMemoryPool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);

    size_t newCapacity = pool->capacity * 2;
    void* newBase = realloc(pool->base, newCapacity);

    if (!newBase) {
        pthread_mutex_unlock(&pool->lock);
        return -1; // Failed to resize
    }

    pool->base = newBase;
    pool->capacity = newCapacity;

    pthread_mutex_unlock(&pool->lock);
    return 0;
}

int addRecord(MemoryPool* pool, Record record) {
    pthread_mutex_lock(&pool->lock);

    if (pool->used + sizeof(Record) > pool->capacity) {
        int resizeResult = resizeMemoryPool(pool);
        if (resizeResult != 0) {
            pthread_mutex_unlock(&pool->lock);
            return -1; // Failed to resize
        }
    }

    Record* recordPtr = (Record*)(pool->base + pool->used);
    *recordPtr = record;
    pool->used += sizeof(Record);

    pool->totalValue += record.value;

    pthread_mutex_unlock(&pool->lock);
    return 0;
}

int initializeRecords(MemoryPool* pool, int count) {
    srand(time(NULL));
    for (int i = 0; i < count; ++i) {
        Record newRecord;
        newRecord.key = NULL; // Example key initialization
        int avgValue = calculateAverageValue(pool);
        int rangeMin = avgValue > 0 ? avgValue / 2 : 1;
        int rangeMax = avgValue + 100;

        newRecord.value = rand() % (rangeMax - rangeMin) + rangeMin;

        if (addRecord(pool, newRecord) != 0) {
            return -1; // Failed to add record
        }
    }

    return 0;
}

void releaseMemoryPool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);

    free(pool->base);
    pthread_mutex_unlock(&pool->lock);

    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

int calculateAverageValue(const MemoryPool* pool) {
    if (pool->used == 0) return 0;
    return pool->totalValue / (pool->used / sizeof(Record));
}

int handleFragmentation(MemoryPool* pool) {
    // Placeholder for fragmentation handling logic
    return 0;
}
