    size_t resource_limits[3]; // max_concurrent_requests, memory_limit, disk_space_limit
    char **api_endpoints;
    size_t api_endpoint_count;
    size_t metrics_interval;
} AppConfig;

typedef struct Request {
    int request_count;
    struct Request *next;
} RequestNode;

// Function prototypes
int validate_log_level(const char *log_level);
size_t hash_string(const char *str);

// Thread-safe configuration cache
pthread_mutex_t config_cache_lock = PTHREAD_MUTEX_INITIALIZER;
AppConfig cached_config;

// Main function to process YAML configuration file
int process_yaml_configuration(const char *yaml_file, void (*logger)(const char*), void (*resource_monitor)(size_t*)) {
    FILE *file = fopen(yaml_file, "rb");
    if (!file) {
        logger("Failed to open YAML file.");
        return errno;
    }

    yaml_parser_t parser;
    if (!yaml_parser_initialize(&parser)) {
        fclose(file);
        logger("Failed to initialize YAML parser.");
        return ENOMEM;
    }
    yaml_parser_set_input_file(&parser, file);

    yaml_event_t event;
    int done = 0;
    AppConfig config = {0};

    while (!done) {
        if (!yaml_parser_parse(&parser, &event)) {
            logger("Failed to parse YAML event.");
            fclose(file);
            yaml_parser_delete(&parser);
            return ENOMSG;
        }

        switch (event.type) {
            case YAML_SCALAR_EVENT:
                if (strcmp(event.data.scalar.value, "application_name") == 0 &&
                    yaml_parser_parse(&parser, &event)) {
                    config.application_name = strdup(event.data.scalar.value);
                } else if (strcmp(event.data.scalar.value, "server_port") == 0 &&
                           yaml_parser_parse(&parser, &event)) {
                    config.server_port = atoi(event.data.scalar.value);
                    if (config.server_port <= 0) {
                        logger("Invalid server port.");
                        fclose(file);
                        yaml_parser_delete(&parser);
                        return EINVAL;
                    }
                } else if (strcmp(event.data.scalar.value, "log_level") == 0 &&
                           yaml_parser_parse(&parser, &event)) {
                    if (!validate_log_level(event.data.scalar.value)) {
                        logger("Invalid log level.");
                        fclose(file);
                        yaml_parser_delete(&parser);
                        return EINVAL;
                    }
                    config.log_level = event.data.scalar.value;
                } else if (strcmp(event.data.scalar.value, "max_concurrent_requests") == 0 &&
                           yaml_parser_parse(&parser, &event)) {
                    config.resource_limits[0] = strtoull(event.data.scalar.value, NULL, 10);
                } else if (strcmp(event.data.scalar.value, "memory_limit") == 0 &&
                           yaml_parser_parse(&parser, &event)) {
                    config.resource_limits[1] = strtoull(event.data.scalar.value, NULL, 10);
                } else if (strcmp(event.data.scalar.value, "disk_space_limit") == 0 &&
                           yaml_parser_parse(&parser, &event)) {
                    config.resource_limits[2] = strtoull(event.data.scalar.value, NULL, 10);
                } else if (strcmp(event.data.scalar.value, "api_endpoints") == 0 ||
                           strcmp(event.data.scalar.value, "metrics_interval") == 0) {
                    // Handle optional fields as needed
                }
                break;
            case YAML_SEQUENCE_START_EVENT:
                if (yaml_parser_parse(&parser, &event)) { // Assume next event is a sequence item
                    char *endpoint = strdup(event.data.scalar.value);
                    config.api_endpoints = realloc(config.api_endpoints, sizeof(char*) * (++config.api_endpoint_count));
                    config.api_endpoints[config.api_endpoint_count - 1] = endpoint;
                }
                break;
            case YAML_SEQUENCE_END_EVENT:
                // End of sequence handling
                break;
        }

        yaml_event_delete(&event);

        done = (event.type == YAML_STREAM_END_EVENT);
    }

    fclose(file);
    yaml_parser_delete(&parser);

    if (!config.application_name || strlen(config.application_name) == 0) {
        logger("Application name is required.");
        return EINVAL;
    }

    pthread_mutex_lock(&config_cache_lock);
    cached_config = config;
    pthread_mutex_unlock(&config_cache_lock);

    // Initialize resource limits and request nodes
    resource_monitor(config.resource_limits);

    RequestNode *head = NULL, *current;
    for (size_t i = 0; i < config.resource_limits[0]; ++i) {
        current = malloc(sizeof(RequestNode));
        if (!current) {
            logger("Failed to allocate memory for request node.");
            return ENOMEM;
        }
        current->request_count = rand() % 100 + 1; // Random value between 1 and 100
        current->next = head;
        head = current;
    }

    return 0; // Success
}

int validate_log_level(const char *log_level) {
    for (size_t i = 0; i < NUM_LOG_LEVELS; ++i) {
        if (strcmp(log_level, valid_log_levels[i]) == 0) {
            return 1;
        }
    }
    return 0;
}
