use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use log::{info, error};

const ENV_VAR_NAME: &str = "MY_DIRECTORY_PATH";
const MAX_PATH_LENGTH: usize = 255;

fn create_truncated_path_with_env_var(dir_name: &str) -> bool {
    // Arc and Mutex to ensure thread-safe access to the environment variable
    let env_var_mutex = Arc::new(Mutex::new(None));

    {
        let mut env_var_guard = env_var_mutex.lock().unwrap();

        if let Some(path) = *env_var_guard {
            info!("Using existing directory path from ENV: {}", path);
            return truncate_and_append_slash(&path);
        }
    }

    // Create a new directory and set the environment variable
    match create_directory(dir_name) {
        Ok(path) => {
            if truncate_and_append_slash(&path) {
                let mut env_var_guard = env_var_mutex.lock().unwrap();
                *env_var_guard = Some(path.clone());

                // Set environment variable for future accesses
                set_env_variable(ENV_VAR_NAME, &path);

                true
            } else {
                error!("Directory path too long after appending slash.");
                false
            }
        },
        Err(e) => {
            error!("Failed to create directory: {}", e);
            false
        }
    }
}

fn create_directory(dir_name: &str) -> std::io::Result<PathBuf> {
    let path = PathBuf::from(dir_name);

    if !path.exists() {
        fs::create_dir(&path)?;
    }

    Ok(path)
}

fn truncate_and_append_slash(path: &Path) -> bool {
    let mut path_str = path.to_string_lossy().to_string();

    // Truncate the path to fit within MAX_PATH_LENGTH - 1 for the slash
    if path_str.len() >= MAX_PATH_LENGTH {
        path_str.truncate(MAX_PATH_LENGTH - 1);
    }

    // Append a slash if it fits within the limit
    if path_str.len() < MAX_PATH_LENGTH {
        path_str.push('/');

        info!("Truncated and appended slash to path: {}", path_str);
        true
    } else {
        false
    }
}

fn set_env_variable(key: &str, value: &str) {
    env::set_var(key, value);
    info!("Set environment variable {} to {}", key, value);

    // Optional: Integrate with a remote service for additional configuration updates.
