int expandNFAPIDataList(NFAPIDataList *list) {
    size_t new_capacity = list->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
    if (!new_data) return -1; // Memory allocation failed
    list->data = new_data;
    list->capacity = new_capacity;
    return 0;
