    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    bool stop_processing;
    pthread_t background_thread;
    pthread_t cleanup_thread;
} PacketManager;

// Mock logging function
void log_info(const char *message) {
    printf("[INFO] %s\n", message);
}

void log_error(const char *message) {
    printf("[ERROR] %s\n", message);
}

// Function prototypes
PacketManager* packet_manager_init(size_t initial_capacity);
bool packet_manager_add_packet(PacketManager *manager, uint64_t timestamp, size_t packet_size, void *packet_data);
void packet_manager_destroy(PacketManager *manager);
void* process_packets(void *arg);
void* cleanup_old_packets(void *arg);

// Initialize Packet Manager
PacketManager* packet_manager_init(size_t initial_capacity) {
    PacketManager *manager = (PacketManager*) malloc(sizeof(PacketManager));
    if (!manager) return NULL;

    manager->packets = (Packet**) calloc(initial_capacity, sizeof(Packet*));
    if (!manager->packets) {
        free(manager);
        log_error("Failed to allocate memory for packets");
        return NULL;
    }

    manager->count = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);
    pthread_cond_init(&manager->cond, NULL);
    manager->stop_processing = false;

    if (pthread_create(&manager->background_thread, NULL, process_packets, manager)) {
        log_error("Failed to create background thread");
        free(manager->packets);
        free(manager);
        return NULL;
    }

    if (pthread_create(&manager->cleanup_thread, NULL, cleanup_old_packets, manager)) {
        log_error("Failed to create cleanup thread");
        pthread_cancel(manager->background_thread);  // Attempt clean-up
        pthread_mutex_destroy(&manager->lock);
        pthread_cond_destroy(&manager->cond);
        free(manager->packets);
        free(manager);
        return NULL;
    }

    log_info("Packet Manager initialized successfully");
    return manager;
}

// Add packet to PacketManager
bool packet_manager_add_packet(PacketManager *manager, uint64_t timestamp, size_t packet_size, void *packet_data) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= MAX_PACKETS) {
        log_error("Max packet limit reached");
        pthread_mutex_unlock(&manager->lock);
        return false;
    }

    // Simulate packet validation
    bool valid_packet = true;  // Replace with actual validation logic

    if (!valid_packet || !packet_data) {
        log_error("Malformed or null packet data received");
        pthread_mutex_unlock(&manager->lock);
        return false;
    }

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        Packet **new_packets = (Packet**) realloc(manager->packets, new_capacity * sizeof(Packet*));
        if (!new_packets) {
            log_error("Failed to reallocate memory for packets");
            pthread_mutex_unlock(&manager->lock);
            return false;
        }
        manager->packets = new_packets;
        manager->capacity = new_capacity;
    }

    Packet *packet = (Packet*) malloc(sizeof(Packet));
    if (!packet) {
        log_error("Failed to allocate memory for packet structure");
        pthread_mutex_unlock(&manager->lock);
        return false;
    }

    packet->timestamp = timestamp;
    packet->packet_size = packet_size;
    packet->packet_data = malloc(packet_size);  // Assume data needs copying
    if (!packet->packet_data) {
        log_error("Failed to allocate memory for packet data");
        free(packet);
        pthread_mutex_unlock(&manager->lock);
        return false;
    }
    memcpy(packet->packet_data, packet_data, packet_size);

    manager->packets[manager->count++] = packet;

    pthread_cond_signal(&manager->cond);
    pthread_mutex_unlock(&manager->lock);

    log_info("Packet added successfully");
    return true;
}

// Destroy Packet Manager
void packet_manager_destroy(PacketManager *manager) {
    if (!manager) return;

    manager->stop_processing = true;
    pthread_cond_broadcast(&manager->cond);  // Wake up threads for cleanup

    pthread_join(manager->background_thread, NULL);
    pthread_join(manager->cleanup_thread, NULL);

    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->packets[i]->packet_data);
        free(manager->packets[i]);
    }
    free(manager->packets);
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    pthread_cond_destroy(&manager->cond);

    free(manager);
    log_info("Packet Manager destroyed successfully");
}

// Process packets in the background
void* process_packets(void *arg) {
    PacketManager *manager = (PacketManager*) arg;
    while (!manager->stop_processing) {
        pthread_mutex_lock(&manager->lock);

        if (manager->count == 0) {
            pthread_cond_wait(&manager->cond, &manager->lock);
        }

        // Process packets here
        for (size_t i = 0; i < manager->count && !manager->stop_processing; ++i) {
            Packet *packet = manager->packets[i];
            log_info("Processing packet with timestamp: %llu and size: %zu", packet->timestamp, packet->packet_size);
        }

        pthread_mutex_unlock(&manager->lock);
    }
    return NULL;
}

// Cleanup old packets periodically
void* cleanup_old_packets(void *arg) {
    PacketManager *manager = (PacketManager*) arg;
    while (!manager->stop_processing) {
        sleep(10);  // Run every 10 seconds

        pthread_mutex_lock(&manager->lock);

        if (manager->count > MAX_PACKETS) {
            size_t packets_to_remove = manager->count - MAX_PACKETS;
            for (size_t i = 0; i < packets_to_remove; ++i) {
                Packet *packet = manager->packets[i];
                free(packet->packet_data);
                free(packet);

                // Shift remaining packets
                memmove(&manager->packets[i], &manager->packets[i + 1], (manager->count - i - 1) * sizeof(Packet*));
            }
            manager->count -= packets_to_remove;
        }

        pthread_mutex_unlock(&manager->lock);
    }
    return NULL;
}
