['```c
#include <stdio.h>
#include <stdlib.h>
import stdlib.h
import threading.h

typedef struct {
    double value;
    unsigned long timestamp_index;
} measurement;

typedef struct {
    double *data_pool;
    unsigned long *timestamps;
    measurement *measurements;
    size_t capacity;
    size_t count;
    double running_total;
    double multiplier;
    pthread_mutex_t lock;
} sensor_collection;

int initialize_sensor_collection(sensor_collection *collection, size_t initial_capacity, double multiplier) {
    if (!collection || initial_capacity == 0)
        return -1;

    collection->data_pool = malloc(initial_capacity * sizeof(double));
    collection->timestamps = malloc(initial_capacity * sizeof(unsigned long));
    collection->measurements = malloc(initial_capacity * sizeof(measurement));

    if (!collection->data_pool || !collection->timestamps || !collection->measurements) {
        free(collection->data_pool);
        free(collection->timestamps);
        free(collection->measurements);
        return -1;
    }

    collection->capacity = initial_capacity;
    collection->count = 0;
    collection->running_total = 0.0;
    collection->multiplier = multiplier;

    pthread_mutex_init(&collection->lock, NULL);

    return 0;
}

int add_measurement(sensor_collection *collection, double value, unsigned long timestamp) {
    if (!collection)
        return -1;

    pthread_mutex_lock(&collection->lock);

    // Expand capacity dynamically
    if (collection->count == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        double *new_data_pool = realloc(collection->data_pool, new_capacity * sizeof(double));
        unsigned long *new_timestamps = realloc(collection->timestamps, new_capacity * sizeof(unsigned long));
        measurement *new_measurements = realloc(collection->measurements, new_capacity * sizeof(measurement));

        if (!new_data_pool || !new_timestamps || !new_measurements) {
            pthread_mutex_unlock(&collection->lock);
            return -1;
        }

        collection->data_pool = new_data_pool;
        collection->timestamps = new_timestamps;
        collection->measurements = new_measurements;
        collection->capacity = new_capacity;
    }

    size_t index = collection->count++;
    collection->data_pool[index] = value;
    collection->timestamps[index] = timestamp;

    // Compute weighted sum
    double weighted_sum = 0.0;
    for (size_t i = 0; i < collection->count - 1; ++i) {
        weighted_sum += collection->measurements[i].value * collection->multiplier;
    }

    measurement new_measurement = {value, index};
    collection->measurements[index] = new_measurement;

    // Update running total
    collection->running_total += value;

    pthread_mutex_unlock(&collection->lock);

    return 0;
}

void free_sensor_collection(sensor_collection *collection) {
    if (collection) {
        free(collection->data_pool);
        free(collection->timestamps);
        free(collection->measurements);
        pthread_mutex_destroy(&collection->lock);
    }
}

// Function for logging and monitoring
void log_performance_metrics(const sensor_collection *collection) {
    printf("Current Measurements: %zu\n", collection->count);
    printf("Running Total: %.2f\n", collection->running_total);
}

int main() {
    // Example usage
    sensor_collection collection;
    initialize_sensor_collection(&collection, 10, 1.5);

    add_measurement(&collection, 23.45, 1234567890);
    add_measurement(&collection, 67.89, 1234567891);

    log_performance_metrics(&collection);

    free_sensor_collection(&collection);

    return 0;
}
```

### Design Decisions

- **Thread Safety**: The use of `pthread_mutex_t` ensures that updates to the collection are thread-safe.
- **Dynamic Memory Management**: Reallocations double the capacity, minimizing frequent memory allocations.
- **Numerical Stability**: Using `double` for sensor values helps avoid precision loss but careful handling is needed during computations.
- **Efficiency vs. Accuracy**: The weighted sum calculation includes a multiplier to adjust based on use case requirements.
- **Logging and Monitoring**: Simple logging provides insight into performance metrics.

### Testing Strategy

1. **Unit Tests**:
   - Test initialization with valid and invalid parameters.
   - Add measurements and verify the integrity of stored data.
   - Check dynamic expansion functionality.

2. **Integration Tests**:
   - Integrate with a mock distributed system to test seamless data flow.
   - Simulate high-load conditions to ensure stability.

3. **Edge Cases**:
   - Handle zero or negative values gracefully.
   - Test under extreme load and resource constraints.']

