#include <arpa/inet.h>
#include <netdb.h>

#define MAX_DNS_QUERIES 5

void dnsResolution() {
    char hostname[MAX_INPUT_SIZE];
    if (!fgets(hostname, MAX_INPUT_SIZE, stdin)) return;

    static int query_count = 0;
    static time_t last_minute_start = time(NULL);

    time_t now = time(NULL);
    if (now - last_minute_start >= 60) {
        query_count = 0;
        last_minute_start = now;
    }

    if (query_count >= MAX_DNS_QUERIES) {
        printf("Query limit exceeded.\n");
        return;
    }

    struct addrinfo hints, *res, *p;
    int status;
    char ipstr[INET6_ADDRSTRLEN];
    u_char ip_address[16]; // Supports both IPv4 and IPv6

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // Either IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
            memcpy(ip_address, addr, sizeof(struct in_addr));
            break; 
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
            memcpy(ip_address, addr, sizeof(struct in6_addr));
            break;
        }
    }

    freeaddrinfo(res);

    if (inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr) != NULL) {
        printf("IP Address: %s\n", ipstr);
    } else {
        fprintf(stderr, "Error converting IP to string.\n");
    }

    query_count++;
}

// Note: Web API functions are not implemented here as they require an HTTP server framework.
