typedef struct {
    int value;
    int key_index;  // Index into keys array
} record_t;

#define INITIAL_MEMORY_LIMIT 1024 * 1024  // Example memory limit in bytes

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Struct to manage dynamic memory and data
typedef struct {
    long *offsets;
    int *keys;
    record_t *records;
    size_t offset_count;
    size_t key_count;
    size_t record_count;
    long total_memory_allocated;
    uint64_t cumulative_value_sum;
} MemoryManager;

// Logging function
void log_message(const char *message) {
    static FILE *log_file = NULL;
    if (!log_file) {
        log_file = fopen("memory_log.txt", "w");
        if (!log_file) {
            perror("Failed to open log file");
            exit(EXIT_FAILURE);
        }
    }

    fprintf(log_file, "%s\n", message);
    fflush(log_file);  // Ensure logs are flushed to disk
}

// Function to reset memory allocation
void reset_memory(MemoryManager *manager) {
    pthread_mutex_lock(&lock);

    free(manager->offsets);
    free(manager->keys);
    free(manager->records);
    manager->offset_count = 0;
    manager->key_count = 0;
    manager->record_count = 0;
    manager->total_memory_allocated = 0;

    log_message("Memory allocation reset");

    pthread_mutex_unlock(&lock);
}

// Function to initialize memory and structures
void init_memory_manager(MemoryManager *manager, size_t initial_size) {
    pthread_mutex_lock(&lock);

    if (manager->total_memory_allocated > INITIAL_MEMORY_LIMIT) {
        reset_memory(manager);
    }

    manager->offset_count = initial_size;
    manager->key_count = initial_size;
    manager->record_count = initial_size;

    size_t total_bytes = sizeof(long) * manager->offset_count +
                         sizeof(int) * manager->key_count +
                         sizeof(record_t) * manager->record_count;

    if (total_bytes + manager->total_memory_allocated > INITIAL_MEMORY_LIMIT) {
        reset_memory(manager);
    }

    manager->offsets = realloc(manager->offsets, total_bytes + sizeof(long) * initial_size);
    manager->keys = realloc(manager->keys, total_bytes + sizeof(int) * initial_size);
    manager->records = realloc(manager->records, total_bytes + sizeof(record_t) * initial_size);

    if (!manager->offsets || !manager->keys || !manager->records) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    manager->total_memory_allocated += total_bytes;

    for (size_t i = 0; i < manager->record_count; ++i) {
        int range_start = 1;
        int range_end = 100 + (int)(manager->cumulative_value_sum % 50);

        if (range_start > range_end) {
            int temp = range_start;
            range_start = range_end;
            range_end = temp;
        }

        manager->records[i].value = rand() % (range_end - range_start + 1) + range_start;
        manager->records[i].key_index = i;

        manager->cumulative_value_sum += manager->records[i].value;
    }

    log_message("Memory initialized");

    pthread_mutex_unlock(&lock);
}

// Function to periodically check memory usage and log
void* monitor_memory_usage(void *arg) {
    MemoryManager *manager = (MemoryManager *)arg;

    while (1) {
        sleep(5);  // Log every 5 seconds

        pthread_mutex_lock(&lock);

        char message[256];
        snprintf(message, sizeof(message), "Total memory allocated: %ld bytes", manager->total_memory_allocated);
        log_message(message);

        pthread_mutex_unlock(&lock);
    }

    return NULL;
}

int main() {
    MemoryManager manager = {NULL, NULL, NULL, 0, 0, 0, 0, 0};
    init_memory_manager(&manager, 100); // Initialize with a size of 100

    pthread_t monitor_thread;
    if (pthread_create(&monitor_thread, NULL, monitor_memory_usage, &manager) != 0) {
        perror("Failed to create monitoring thread");
        exit(EXIT_FAILURE);
    }

    // Simulate other work
    sleep(60);

    pthread_cancel(monitor_thread);
    pthread_join(monitor_thread, NULL);

    reset_memory(&manager);
    fclose(log_file);  // Close the log file

    return 0;
}
