['Below is a C implementation that addresses the requirements specified for managing memory with concurrent access:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>

typedef struct {
    long offset;
    int key;
    int value;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int total_sum;
    const size_t max_capacity;
} MemoryManager;

MemoryManager* init_memory_manager(size_t initial_size, size_t max_capacity) {
    MemoryManager *manager = malloc(sizeof(MemoryManager));
    if (!manager) return NULL;

    manager->records = calloc(initial_size, sizeof(Record));
    if (!manager->records) {
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    pthread_cond_init(&manager->cond, NULL);

    manager->capacity = initial_size;
    manager->count = 0;
    manager->total_sum = 0;
    manager->max_capacity = max_capacity;

    printf("MemoryManager initialized with capacity %zu\n", initial_size);
    return manager;
}

void free_memory_manager(MemoryManager *manager) {
    if (manager) {
        pthread_mutex_destroy(&manager->lock);
        pthread_cond_destroy(&manager->cond);

        free(manager->records);
        free(manager);

        printf("MemoryManager destroyed\n");
    }
}

int add_record(MemoryManager *manager, long offset, int key) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity && manager->capacity < manager->max_capacity) {
        size_t new_capacity = manager->capacity * 2;
        if (new_capacity > manager->max_capacity) {
            new_capacity = manager->max_capacity;
        }

        Record *new_records = realloc(manager->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Reallocation failed
        }

        manager->records = new_records;
        manager->capacity = new_capacity;

        printf("Resized memory to capacity %zu\n", manager->capacity);
    } else if (manager->count >= manager->max_capacity) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Exceeded max capacity
    }

    Record *new_record = &manager->records[manager->count++];
    new_record->offset = offset;
    new_record->key = key;
    new_record->value = manager->total_sum;

    manager->total_sum += new_record->value;

    printf("Added record: offset=%ld, key=%d, value=%d\n", offset, key, new_record->value);

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int get_total_sum(MemoryManager *manager) {
    pthread_mutex_lock(&manager->lock);
    int total = manager->total_sum;
    pthread_mutex_unlock(&manager->lock);
    return total;
}

size_t get_record_count(MemoryManager *manager) {
    pthread_mutex_lock(&manager->lock);
    size_t count = manager->count;
    pthread_mutex_unlock(&manager->lock);
    return count;
}

void log_memory_usage(MemoryManager *manager) {
    pthread_mutex_lock(&manager->lock);

    printf("Current memory usage: %zu records, total sum=%d\n", get_record_count(manager), get_total_sum(manager));

    pthread_mutex_unlock(&manager->lock);
}
```

### Key Points:
- **Concurrency**: Uses `pthread_mutex_t` for thread safety when accessing shared data.
- **Dynamic Resizing**: Doubles the capacity until it reaches a maximum limit, reallocating memory as needed.
- **Resource Limits**: Enforces a maximum capacity to prevent excessive memory usage.
- **Diagnostic Features**: Simple logging with `printf`, ensuring minimal performance impact. Logs key operations and states.

This code provides a foundation for managing records in a thread-safe manner while addressing the specified engineering challenges.']

