#define INITIAL_POOL_SIZE 100

typedef struct Record {
    int value;
    void *key;
} Record;

typedef struct MemoryPool {
    size_t block_size;
    size_t num_blocks;
    char *pool_memory;
    size_t next_free_index;
    pthread_mutex_t lock;
} MemoryPool;

// Global variables for managing records and memory pool
MemoryPool record_pool;
pthread_mutex_t total_lock;
int total_value = 0;
size_t max_records = 1000; // Adjust as needed

void initialize_memory_pool(MemoryPool *mp, size_t block_size, size_t initial_blocks) {
    mp->block_size = sizeof(Record);
    mp->num_blocks = initial_blocks;
    mp->pool_memory = malloc(mp->block_size * initial_blocks);
    mp->next_free_index = 0;
    pthread_mutex_init(&mp->lock, NULL);
}

void *allocate_record(MemoryPool *mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->next_free_index < mp->num_blocks) {
        char *record_ptr = &mp->pool_memory[mp->next_free_index * mp->block_size];
        mp->next_free_index++;
        pthread_mutex_unlock(&mp->lock);
        return record_ptr;
    } else {
        // Expand pool if needed
        size_t new_num_blocks = mp->num_blocks * 2;
        char *new_pool_memory = realloc(mp->pool_memory, mp->block_size * new_num_blocks);
        if (new_pool_memory) {
            mp->pool_memory = new_pool_memory;
            mp->num_blocks = new_num_blocks;
            pthread_mutex_unlock(&mp->lock);
            return allocate_record(mp); // Retry allocation
        }
        pthread_mutex_unlock(&mp->lock);
    }
    return NULL; // Allocation failed
}

void deallocate_all(MemoryPool *mp) {
    free(mp->pool_memory);
    mp->pool_memory = NULL;
    mp->next_free_index = 0;
}

Record* add_record(void *key, int avg_value_range) {
