    pthread_mutex_lock(&total_lock);
    int new_total_value = total_value + record->value;
    if (new_total_value > max_records * avg_value_range) {
        pthread_mutex_unlock(&total_lock);
        // Deallocation not shown here for simplicity, should be handled in real scenarios
        return NULL; 
    }
    total_value = new_total_value;
    pthread_mutex_unlock(&total_lock);

    record->key = key;
    return record;
}

void* streaming_data_handler(void *arg) {
    while (1) { // Replace with proper condition or signal handling
        void *new_key = malloc(sizeof(int));  // Example key, replace with actual logic
        *(int *)new_key = rand();

        int avg_value_range = total_value / (rand() % max_records + 1);
        Record *record = add_record(new_key, avg_value_range);

        if (!record) {
            free(new_key);  // Clean up in case of failed insertion
        }

        // Simulate data stream delay
        usleep(rand() % 1000);
    }
    return NULL;
}

int main() {
    srand(time(NULL));

    initialize_memory_pool(&record_pool, sizeof(Record), INITIAL_POOL_SIZE);

    pthread_t threads[4]; // Adjust number of threads based on requirements

    for (size_t i = 0; i < sizeof(threads) / sizeof(pthread_t); ++i) {
        pthread_create(&threads[i], NULL, streaming_data_handler, NULL);
    }

