['```c
#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

typedef struct CacheEntry {
    char* key;
    long timestamp;
    double value;
} CacheEntry;

typedef struct DistributedCache {
    int capacity;
    int size;
    pthread_mutex_t lock;
    CacheEntry** entries;
} DistributedCache;

DistributedCache* init_cache(int initial_capacity) {
    DistributedCache* cache = (DistributedCache*)malloc(sizeof(DistributedCache));
    if (!cache) return NULL;

    cache->capacity = initial_capacity;
    cache->size = 0;
    pthread_mutex_init(&cache->lock, NULL);
    cache->entries = (CacheEntry**)calloc(initial_capacity, sizeof(CacheEntry*));

    return cache;
}

void resize_cache(DistributedCache* cache, int new_capacity) {
    CacheEntry** new_entries = (CacheEntry**)realloc(cache->entries, new_capacity * sizeof(CacheEntry*));
    if (!new_entries) return;

    memset(new_entries + cache->size, 0, (new_capacity - cache->size) * sizeof(CacheEntry*));
    cache->entries = new_entries;
    cache->capacity = new_capacity;
}

int insert_cache_entry(DistributedCache* cache, const char* key, long timestamp, double value) {
    pthread_mutex_lock(&cache->lock);

    for (int i = 0; i < cache->size; ++i) {
        if (strcmp(cache->entries[i]->key, key) == 0) {
            cache->entries[i]->timestamp = timestamp;
            cache->entries[i]->value = value;
            pthread_mutex_unlock(&cache->lock);
            return 1; // Updated existing entry
        }
    }

    if (cache->size >= cache->capacity) {
        resize_cache(cache, cache->capacity * 2);
    }

    CacheEntry* new_entry = (CacheEntry*)malloc(sizeof(CacheEntry));
    new_entry->key = strdup(key);
    new_entry->timestamp = timestamp;
    new_entry->value = value;

    cache->entries[cache->size++] = new_entry;
    pthread_mutex_unlock(&cache->lock);

    return 0; // Inserted new entry
}

int get_cache_entry(DistributedCache* cache, const char* key, long* timestamp, double* value) {
    pthread_mutex_lock(&cache->lock);

    for (int i = 0; i < cache->size; ++i) {
        if (strcmp(cache->entries[i]->key, key) == 0) {
            *timestamp = cache->entries[i]->timestamp;
            *value = cache->entries[i]->value;
            pthread_mutex_unlock(&cache->lock);
            return 1;
        }
    }

    pthread_mutex_unlock(&cache->lock);
    return 0; // Key not found
}

void get_cache_state(DistributedCache* cache, int* total_entries, long* most_recent_time, double* average_value) {
    pthread_mutex_lock(&cache->lock);

    *total_entries = cache->size;
    long max_timestamp = 0;
    double sum_values = 0;

    for (int i = 0; i < cache->size; ++i) {
        if (cache->entries[i]->timestamp > max_timestamp) {
            max_timestamp = cache->entries[i]->timestamp;
        }
        sum_values += cache->entries[i]->value;
    }

    *most_recent_time = max_timestamp;
    *average_value = (*total_entries > 0) ? (sum_values / cache->size) : 0.0;

    pthread_mutex_unlock(&cache->lock);
}

void free_cache(DistributedCache* cache) {
    if (!cache) return;

    for (int i = 0; i < cache->size; ++i) {
        free(cache->entries[i]->key);
        free(cache->entries[i]);
    }
    free(cache->entries);

    pthread_mutex_destroy(&cache->lock);
    free(cache);
}

// Example usage
int main() {
    DistributedCache* cache = init_cache(10);
    insert_cache_entry(cache, "metric1", 1627849200, 75.5);
    long timestamp;
    double value;
    if (get_cache_entry(cache, "metric1", &timestamp, &value)) {
        printf("Metric: %f at time: %ld\n", value, timestamp);
    }

    int total_entries;
    long most_recent_time;
    double average_value;
    get_cache_state(cache, &total_entries, &most_recent_time, &average_value);

    printf("Total Entries: %d, Most Recent Update Time: %ld, Average Value: %f\n",
           total_entries, most_recent_time, average_value);

    free_cache(cache);
    return 0;
}
```

This code implements a basic distributed cache system with dynamic resizing and thread-safe operations using mutex locks. It supports insertion, retrieval, and state querying while maintaining data consistency. Future enhancements can include more sophisticated synchronization strategies, fault tolerance mechanisms, and scalability features.']

