namespace CryptLib {

    class CryptoManager {
    public:
        static std::mt19937& getThreadSafeRandomGenerator() {
            static std::once_flag flag;
            static std::mt19937 rng;
            std::call_once(flag, []() { 
                std::random_device rd; 
                rng.seed(rd()); 
            });
            return rng;
        }

        static EVP_CIPHER* selectCipher(const std::string& mode) {
            if (mode == "ECB") {
                return EVP_des_ecb();
            } else if (mode == "EDE") {
                return EVP_des_ede();
            } else if (mode == "EDE3") {
                return EVP_des_ede3();
            } else if (mode == "CFB") {
                return EVP_des_cfb64();
            } else if (mode == "NULL") {
                return NULL;
            }
            throw std::invalid_argument("Unsupported cipher mode");
        }

    private:
        CryptoManager() = delete; // Prevent instantiation
    };

    struct record {
        int weight;
    };

    void selectAndExecuteAttack(int vertexCount, int edgeRange) {
        try {
            auto rng = CryptoManager::getThreadSafeRandomGenerator();

            std::vector<long> offsets(vertexCount);
            std::vector<int> keys(vertexCount);

            std::vector<record> edges(edgeRange * (vertexCount - 1));

            for (auto& offset : offsets) {
                offset = rng() % 1000;
            }

            for (auto& key : keys) {
                key = rng() % 256;
            }

            for (auto& edge : edges) {
                edge.weight = rng() % edgeRange;
            }

            // Simulate attack selection and execution
            int attackNumber = rng() % 2 + 1; 
            std::cout << "Executing Attack #" << attackNumber << std::endl;

            // Implement cooldown mechanism (9 seconds)
            std::this_thread::sleep_for(std::chrono::seconds(9));

            validateGraphData(offsets, keys, edges);

        } catch (const std::exception& e) {
            std::cerr << "Error during graph operation: " << e.what() << std::endl;
        }
    }

    void validateGraphData(const std::vector<long>& offsets, const std::vector<int>& keys, const std::vector<record>& edges) {
        for (const auto& offset : offsets) {
            if (offset < 0 || offset > 1000) {
                throw std::invalid_argument("Invalid vertex offset detected");
            }
        }

        for (const auto& key : keys) {
            if (key < 0 || key > 255) {
                throw std::invalid_argument("Invalid vertex key detected");
            }
        }

        // Add more validation as needed
    }

    // Interface for integration with other game components
    class GameComponentInterface {
    public:
        virtual void integrateWith(CryptoManager& manager) = 0;
    };

} // namespace CryptLib

int main() {
    try {
        CryptLib::CryptoManager cryptoManager;
        auto* cipher = CryptLib::CryptoManager::selectCipher("ECB");
        std::cout << "Selected Cipher: " << EVP_CIPHER_name(cipher) << std::endl;

        CryptLib::selectAndExecuteAttack(10, 50);
    } catch (const std::exception& e) {
        std::cerr << "Exception: " << e.what() << std::endl;
    }

    return 0;
}
```

