        pthread_mutex_lock(&lock);

        // Insert into the min-heap (ordered by timestamp)
        insert_into_heap(packet_heap, packet);

        pthread_mutex_unlock(&lock);
    }

    close(socket_fd);
    pthread_mutex_destroy(&lock);
    destroy_heap(packet_heap);

    return SUCCESS;
}

