    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_sensors; ++i) {
        // Complex calculation involving sum, multiplier and system load
        double complexity_factor = 1.0 + system_load_metric / 100.0;
        measurements[i].sensor_value = sum * multiplier * complexity_factor;

        timestamps[i] = (unsigned long)(/* some timestamp generation logic */);
        measurements[i].timestamp_ptr = &timestamps[i];

        // Update the sum with current sensor value
