['Below is an outline of how you might structure the C code for such a modular data management library, addressing your specified requirements.

```c
#include <stdio.h>
#include <stdlib.h>
import <pthread.h>  // For thread safety.
#include <string.h>

// Configuration parameters struct.
typedef struct {
    size_t initial_size;
    int random_range_min;
    int random_range_max;
    size_t memory_threshold;
    double idle_timeout; 
} Config;

// Structure for a record.
typedef struct {
    int value;
    size_t key_index;
} Record;

// Data management structure.
typedef struct {
    long *offsets;
    int *keys;
    Record *records;
    size_t size;
    size_t count;
    int total_sum;
    pthread_mutex_t lock;  // Mutex for thread safety.

    Config config;
} DataManager;

// Initialize the data manager with a configuration.
DataManager* create_data_manager(Config config) {
    DataManager *dm = (DataManager *)malloc(sizeof(DataManager));
    if (!dm) return NULL;

    dm->size = config.initial_size;
    dm->count = 0;
    dm->total_sum = 0;
    pthread_mutex_init(&dm->lock, NULL);

    // Allocate initial memory blocks.
    dm->offsets = (long *)malloc(dm->size * sizeof(long));
    dm->keys = (int *)malloc(dm->size * sizeof(int));
    dm->records = (Record *)calloc(dm->size, sizeof(Record));

    if (!dm->offsets || !dm->keys || !dm->records) {
        // Handle allocation failure gracefully.
        free(dm->offsets);
        free(dm->keys);
        free(dm->records);
        free(dm);
        return NULL;
    }

    dm->config = config;
    return dm;
}

// Resize the data structures as needed.
void resize_data_manager(DataManager *dm) {
    pthread_mutex_lock(&dm->lock);

    if (dm->count >= dm->size) {
        size_t new_size = dm->size * 2; // Double the size.

        long *new_offsets = realloc(dm->offsets, new_size * sizeof(long));
        int *new_keys = realloc(dm->keys, new_size * sizeof(int));
        Record *new_records = realloc(dm->records, new_size * sizeof(Record));

        if (!new_offsets || !new_keys || !new_records) {
            // Handle reallocation failure gracefully.
            pthread_mutex_unlock(&dm->lock);
            return;
        }

        dm->offsets = new_offsets;
        dm->keys = new_keys;
        dm->records = new_records;
        dm->size = new_size;
    }

    pthread_mutex_unlock(&dm->lock);
}

// Function to initialize a record with random value.
int generate_random_value(int previous_sum, Config config) {
    int max_val = config.random_range_max - (previous_sum % config.random_range_max);
    if (max_val < config.random_range_min) return config.random_range_min;
    return rand() % (max_val - config.random_range_min + 1) + config.random_range_min;
}

// Add a new record.
void add_record(DataManager *dm, int key) {
    pthread_mutex_lock(&dm->lock);

    resize_data_manager(dm); // Ensure enough space.

    size_t idx = dm->count++;
    dm->records[idx].key_index = idx;  // Assuming key indices are sequential for simplicity.
    dm->keys[idx] = key;

    int random_value = generate_random_value(dm->total_sum, dm->config);
    dm->records[idx].value = random_value;

    // Update total sum safely.
    long new_total = (long)dm->total_sum + random_value;
    if ((new_total - random_value != dm->total_sum)) {
        printf("Integer overflow detected! Resetting total sum.\n");
        dm->total_sum = 0; // Handle overflow.
    } else {
        dm->total_sum = new_total;
    }

    pthread_mutex_unlock(&dm->lock);
}

// Query current state of data structures.
void query_state(DataManager *dm) {
    pthread_mutex_lock(&dm->lock);

    printf("Total Sum: %d\n", dm->total_sum);
    printf("Active Records: %zu\n", dm->count);

    pthread_mutex_unlock(&dm->lock);
}

// Free the resources used by DataManager.
void free_data_manager(DataManager *dm) {
    if (!dm) return;

    pthread_mutex_destroy(&dm->lock);
    free(dm->offsets);
    free(dm->keys);
    free(dm->records);
    free(dm);
}

// Example configuration setup function
Config default_config() {
    Config config;
    config.initial_size = 10;
    config.random_range_min = 1;
    config.random_range_max = 100;
    config.memory_threshold = 1024 * 1024; // 1MB for example.
    config.idle_timeout = 5.0; 
    return config;
}

int main() {
    Config config = default_config();
    DataManager *dm = create_data_manager(config);

    if (!dm) {
        fprintf(stderr, "Failed to initialize data manager.\n");
        return EXIT_FAILURE;
    }

    add_record(dm, 1);
    query_state(dm);

    free_data_manager(dm);
    return EXIT_SUCCESS;
}
```

### Key Points:

- **Concurrency**: The `pthread_mutex_t` ensures thread-safe access.
- **Dynamic Resizing**: Implemented through a simple doubling strategy to manage growth efficiently.
- **Integer Overflow Handling**: Checks are made when updating the total sum to prevent overflow issues.
- **Configuration**: Allows specification of performance parameters and system-specific settings.
- **Memory Management**: Efficient allocation, reallocation, and deallocation strategies minimize memory waste.
- **Logging/Monitoring Placeholder**: Code is structured to easily add logging or diagnostic functionality.

This example provides a foundation that can be extended with additional diagnostics, configuration options, or optimization for specific hardware architectures as needed.']

['Below is a C++ implementation that addresses your requirements for a video game character attack selection with cooldowns, concurrent access management, persistent storage of session data, dynamic weighting using machine learning insights, and seamless integration into an existing game framework. The code includes mechanisms for thread safety, logging, external configuration, and efficient resource usage.

```cpp
#include <iostream>
#include <random>
#include <chrono>
#include <mutex>
#include <fstream>
#include <thread>
#include <atomic>
#include <unordered_map>
#include <nlohmann/json.hpp> // Use JSON library for configuration

// Configuration constants (these would typically be loaded from a config file)
const int COOLDOWN_PERIOD = 9; // seconds
constexpr char CONFIG_FILE[] = "attack_config.json";
std::atomic<bool> running(true); // To control the session lifecycle

class AttackSelector {
public:
    AttackSelector();
    ~AttackSelector();

    void selectAndLogAttack();

    // Accessor for attack probabilities (for integration with game framework)
    std::unordered_map<int, double> getAttackProbabilities() const;

    // Function to update attack probabilities externally
    void updateProbabilities(const std::unordered_map<int, double>& newProbs);

private:
    std::mutex attackMutex;
    std::chrono::time_point<std::chrono::steady_clock> lastAttackTime;
    std::atomic<int> totalAttacks{0};

    // Probabilities for attacks
    mutable std::unordered_map<int, double> attackProbabilities;

    void loadConfig();
    void saveSessionData() const;
    int weightedRandomSelection();
};

AttackSelector::AttackSelector() {
    lastAttackTime = std::chrono::steady_clock::now() - COOLDOWN_PERIOD * 1000ms; // Start cooldown
    loadConfig();
}

AttackSelector::~AttackSelector() {
    saveSessionData(); // Save data on destruction, usually when session ends
}

void AttackSelector::selectAndLogAttack() {
    auto now = std::chrono::steady_clock::now();

    // Cooldown management
    {
        std::lock_guard<std::mutex> lock(attackMutex);
        if (std::chrono::duration_cast<std::chrono::seconds>(now - lastAttackTime).count() < COOLDOWN_PERIOD) {
            return; // Skip selection if within cooldown period
        }
        lastAttackTime = now;
    }

    int attackNumber = weightedRandomSelection();

    std::cout << "Selected Attack: " << attackNumber << "\n";

    // Increment total attacks atomically to ensure thread safety
    totalAttacks++;

    // Log the attack with elapsed time since last attack
    auto elapsedTime = std::chrono::duration_cast<std::chrono::seconds>(now - lastAttackTime).count();
    logAttack(attackNumber, elapsedTime);
}

std::unordered_map<int, double> AttackSelector::getAttackProbabilities() const {
    return attackProbabilities;
}

void AttackSelector::updateProbabilities(const std::unordered_map<int, double>& newProbs) {
    std::lock_guard<std::mutex> lock(attackMutex);
    for (const auto& prob : newProbs) {
        attackProbabilities[prob.first] = prob.second;
    }
}

int AttackSelector::weightedRandomSelection() {
    std::random_device rd;
    std::mt19937 gen(rd());

    double totalWeight = 0.0;
    for (auto const& pair : attackProbabilities) {
        totalWeight += pair.second;
    }

    double randomValue = ((double) rand() / RAND_MAX) * totalWeight;

    for (const auto &attack : attackProbabilities) {
        if (randomValue < attack.second) return attack.first;
        randomValue -= attack.second;
    }

    // Fallback in case of rounding errors
    return 1; 
}

void AttackSelector::loadConfig() {
    std::ifstream configFile(CONFIG_FILE);
    nlohmann::json configJson;

    if (configFile.is_open()) {
        configFile >> configJson;

        for (auto& [key, value] : configJson.items()) {
            int attackId = key.get<int>();
            double prob = value.get<double>();

            // Initial configuration setup
            attackProbabilities[attackId] = prob;
        }
    }
}

void AttackSelector::saveSessionData() const {
    std::ofstream sessionFile("session_data.txt");

    if (sessionFile.is_open()) {
        sessionFile << "Total Attacks: " << totalAttacks.load();
    }
}

void AttackSelector::logAttack(int attackNumber, int elapsedTime) {
    // Simple logging mechanism; replace with database/log system as needed
    std::ofstream logFile("attack_log.txt", std::ios_base::app);

    if (logFile.is_open()) {
        auto now = std::chrono::system_clock::to_time_t(std::chrono::steady_clock::now());
        logFile << "Time: " << std::ctime(&now) 
                << "Attack Number: " << attackNumber
                << ", Elapsed Time Since Last Attack: " << elapsedTime << " seconds\n";
    }
}

// Main function to simulate the use case
int main() {
    AttackSelector selector;

    // Simulate multiple threads accessing the selectAndLogAttack method
    std::vector<std::thread> threads;
    for (int i = 0; i < 10; ++i) { // Example of high-load simulation with 10 threads
        threads.emplace_back(&AttackSelector::selectAndLogAttack, &selector);
    }

    for (auto& thread : threads) {
        thread.join();
    }

    return 0;
}
```

