            if (!newPackets) {
                perror("Failed to reallocate memory for packets");
                break;
            }
            packets = newPackets;
            currentCapacity = newCapacity;
        }
    }

    // Free remaining allocated packet data
    for (size_t i = numPackets; i < currentCapacity; ++i) {
        free(packets[i].data);
    }

    return packets;
}

void cleanupPackets(Packet *packets, size_t numPackets) {
    if (!packets) return;

    for (size_t i = 0; i < numPackets; ++i) {
        free(packets[i].data);
    }
    free(packets);
}
