#include <pthread.h>

typedef struct {
    int key;
    double value;
} record;

typedef struct {
    record *records;
    size_t capacity;
    size_t count;
    size_t max_size;
    pthread_mutex_t lock;  // Mutex for thread-safe operations
} RecordArray;

// Function prototypes
RecordArray* create_record_array(size_t initial_capacity, size_t max_size);
void destroy_record_array(RecordArray *ra);
int add_record(RecordArray *ra, int key, double value);
void log_event(const char *message);

#define SUCCESS 0
#define ERROR_INVALID_INPUT -1
#define ERROR_ALLOCATION_FAILED -2

// Create and initialize a record array
RecordArray* create_record_array(size_t initial_capacity, size_t max_size) {
    if (initial_capacity <= 0 || max_size <= 0 || initial_capacity > max_size) {
        log_event("Invalid initial capacity or max size.");
        return NULL;
    }

    RecordArray *ra = malloc(sizeof(RecordArray));
    if (!ra) {
        log_event("Failed to allocate memory for record array structure.");
        return NULL;
    }

    pthread_mutex_init(&ra->lock, NULL);
    ra->records = malloc(initial_capacity * sizeof(record));
    if (!ra->records) {
        free(ra);
        log_event("Failed to allocate memory for records.");
        return NULL;
    }

    ra->capacity = initial_capacity;
    ra->count = 0;
    ra->max_size = max_size;

    log_event("Record array created successfully.");
    return ra;
}

// Destroy the record array and free all allocated resources
void destroy_record_array(RecordArray *ra) {
    if (ra) {
        pthread_mutex_destroy(&ra->lock);
        free(ra->records);
        free(ra);
        log_event("Record array destroyed successfully.");
    }
}

// Add a new record to the array, resizing if necessary
int add_record(RecordArray *ra, int key, double value) {
    if (!ra || ra->count >= ra->max_size) {
        log_event("Cannot add record: invalid input or max size reached.");
        return ERROR_INVALID_INPUT;
    }

    pthread_mutex_lock(&ra->lock);

    if (ra->count == ra->capacity) {
        size_t new_capacity = ra->capacity * 2 <= ra->max_size ? ra->capacity * 2 : ra->max_size;
        record *new_records = realloc(ra->records, new_capacity * sizeof(record));

        if (!new_records) {
            pthread_mutex_unlock(&ra->lock);
            log_event("Failed to resize records array.");
            return ERROR_ALLOCATION_FAILED;
        }

        ra->records = new_records;
        ra->capacity = new_capacity;
        log_event("Records array resized successfully.");
    }

    ra->records[ra->count].key = key;
    ra->records[ra->count].value = value;
    ra->count++;

    pthread_mutex_unlock(&ra->lock);

    return SUCCESS;
}

// Log events for debugging purposes
void log_event(const char *message) {
    // In a real application, consider using a proper logging framework.
    printf("LOG: %s\n", message);
}
