    // Priority: 1 (high) to 10 (low)
    if (connectionID % 2 == 0) {
        *priority = 5; // Stable connections get higher priority
        return 1;
    }
    *priority = 15; // Unstable connections get lower priority
    return 0;
}

void resize_dynamic_array(DynamicArray *array, size_t newCapacity) {
    NetworkConnection **newConnections = realloc(array->connections, newCapacity * sizeof(NetworkConnection *));
    if (!newConnections) return;

    array->connections = newConnections;
    array->capacity = newCapacity;
}

int add_connection(DynamicArray *array, int connectionID, time_t lastActiveTimestamp, size_t bufferSize) {
    pthread_mutex_lock(&array->lock);

    int priority;
    if (!validate_connection(connectionID, &priority, bufferSize)) {
        pthread_mutex_unlock(&array->lock);
        return 0; // Invalid connection
    }

    if (array->count == array->capacity) {
        resize_dynamic_array(array, array->capacity * 2);
        if (!array->connections) {
            pthread_mutex_unlock(&array->lock);
            return 0; // Out of memory
        }
    }

    NetworkConnection *newConn = malloc(sizeof(NetworkConnection));
    if (!newConn) {
        pthread_mutex_unlock(&array->lock);
        return 0; // Out of memory
    }

    newConn->connectionID = connectionID;
    newConn->lastActiveTimestamp = lastActiveTimestamp;
    newConn->buffer = malloc(bufferSize);
    if (!newConn->buffer) {
        free(newConn);
        pthread_mutex_unlock(&array->lock);
        return 0; // Out of memory
    }
    memset(newConn->buffer, 0, bufferSize);
    newConn->referenceCount = 1;

    array->connections[array->count++] = newConn;
    pthread_mutex_unlock(&array->lock);

    return 1;
}

void cleanup_dynamic_array(DynamicArray *array) {
    for (size_t i = 0; i < array->count; ++i) {
        free(array->connections[i]->buffer);
        free(array->connections[i]);
    }
    free(array->connections);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

// Example usage
