    DynamicArray *array = initialize_dynamic_array(10);
    if (!array) return 1;

    add_connection(array, 1, time(NULL), 1024);
    add_connection(array, 2, time(NULL), 2048);

    cleanup_dynamic_array(array);
    return 0;
}
