typedef struct {
    offset_t index;
    key_t unique_key;
    int value;
} record_t;

#define MAX_KEY 1000

// Function prototypes
int allocate_memory(offset_t **offset_array, size_t *size);
int resize_memory(offset_t **offset_array, size_t *current_size, size_t new_size);
int allocate_keys(key_t **key_array, size_t *size);
void initialize_record(record_t *record, offset_t index, key_t unique_key, int min_val, int max_val);
int allocate_records(record_t **records, size_t num_records, offset_t *offsets, key_t *keys, int min_val, int max_val);
int verify_memory(offset_t *offset_array, size_t size);
void free_all(offset_t *offset_array, key_t *key_array, record_t *records);

// Main function
int main() {
    // Example usage
    offset_t *offsets = NULL;
    key_t *keys = NULL;
    record_t *records = NULL;

    if (allocate_memory(&offsets, 10) != 0 || allocate_keys(&keys, 10) != 0) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    if (allocate_records(&records, 10, offsets, keys, 1, 100) != 0) {
        free_all(offsets, keys, NULL);
        fprintf(stderr, "Record allocation failed\n");
        return EXIT_FAILURE;
    }

    // Verification
    if (verify_memory(offsets, 10) != 0) {
        free_all(offsets, keys, records);
        fprintf(stderr, "Verification failed\n");
        return EXIT_FAILURE;
    }

    // Free all allocated memory
    free_all(offsets, keys, records);

    return EXIT_SUCCESS;
}

// Function implementations

int allocate_memory(offset_t **offset_array, size_t *size) {
    if (size == NULL || offset_array == NULL) return -1;

    *offset_array = malloc(*size * sizeof(offset_t));
    if (*offset_array == NULL) return -2;

    memset(*offset_array, 0, *size * sizeof(offset_t));
    return 0;
}

int resize_memory(offset_t **offset_array, size_t *current_size, size_t new_size) {
    if (offset_array == NULL || current_size == NULL || new_size <= 0) return -1;

    offset_t *new_array = realloc(*offset_array, new_size * sizeof(offset_t));
    if (new_array == NULL) return -2;

    memset(new_array + *current_size, 0, (new_size - *current_size) * sizeof(offset_t));
    *offset_array = new_array;
    *current_size = new_size;

    return 0;
}

int allocate_keys(key_t **key_array, size_t *size) {
    if (key_array == NULL || size == NULL) return -1;

    *key_array = malloc(*size * sizeof(key_t));
    if (*key_array == NULL) return -2;

    for (size_t i = 0; i < *size; ++i) {
        (*key_array)[i] = rand() % MAX_KEY;
    }

    return 0;
}

void initialize_record(record_t *record, offset_t index, key_t unique_key, int min_val, int max_val) {
    if (record == NULL) return;

    record->index = index;
    record->unique_key = unique_key;
    record->value = rand() % (max_val - min_val + 1) + min_val;
}

int allocate_records(record_t **records, size_t num_records, offset_t *offsets, key_t *keys, int min_val, int max_val) {
    if (records == NULL || offsets == NULL || keys == NULL) return -1;

    *records = malloc(num_records * sizeof(record_t));
    if (*records == NULL) return -2;

    for (size_t i = 0; i < num_records; ++i) {
        initialize_record(&(*records)[i], offsets[i % (num_records / 2)], keys[i % MAX_KEY], min_val, max_val);
    }

    return 0;
}

int verify_memory(offset_t *offset_array, size_t size) {
    if (offset_array == NULL || size == 0) return -1;

    for (size_t i = 0; i < size; ++i) {
        if (offset_array[i] != 0) return -2;
    }

    return 0;
}

void free_all(offset_t *offset_array, key_t *key_array, record_t *records) {
    if (offset_array != NULL) free(offset_array);
    if (key_array != NULL) free(key_array);
    if (records != NULL) free(records);
}
