        data->records[i].value = generate_random_int(lower_bound, upper_bound);
    }

    if (offset_index < num_offsets && offset_index < num_keys) {
        for (size_t i = 0; i < num_records; ++i) {
            data->records[i].value = data->int_keys[(long)data->offset_values[offset_index] % num_keys];
        }
    }

    pthread_mutex_unlock(&lock);

    return 0;
}

void free_managed_data(ManagedData *data) {
    if (data) {
        pthread_mutex_lock(&lock);
        custom_free(data->pdu_array);
        custom_free(data->offset_values);
        custom_free(data->int_keys);
        custom_free(data->records);
        data->pdu_array = NULL;
        data->offset_values = NULL;
        data->int_keys = NULL;
        data->records = NULL;
        pthread_mutex_unlock(&lock);
    }
}

// Example usage
int main() {
    ManagedData data;

    if (initialize_managed_data(&data, 10, 5, 8, 6, 1, 100, 2) != 0) {
        fprintf(stderr, "Failed to initialize managed data.\n");
        return EXIT_FAILURE;
    }

    // Use the initialized data...

    free_managed_data(&data);

    return EXIT_SUCCESS;
}
