typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t size;
    size_t capacity;
    size_t max_capacity;
    int priority_level;
    int history_enabled;
    pthread_mutex_t lock;
    void (*capacity_reached_callback)(void);
    void (*compaction_initiated_callback)(void);
} CRCList;

typedef struct {
    unsigned int RNTI;
    time_t timestamp;
} RemovedEntryHistory;

CRCList* create_crc_list(size_t max_capacity, int priority_level, int history_enabled) {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;

    list->data = NULL;
    list->size = 0;
    list->capacity = 0;
    list->max_capacity = max_capacity;
    list->priority_level = priority_level;
    list->history_enabled = history_enabled;
    pthread_mutex_init(&list->lock, NULL);
    list->capacity_reached_callback = NULL;
    list->compaction_initiated_callback = NULL;

    return list;
}

int resize_list(CRCList* list) {
    size_t new_capacity = list->capacity == 0 ? 1 : list->capacity * 2;
    if (new_capacity > list->max_capacity) return -1;

    NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) return -1;

    list->data = new_data;
    list->capacity = new_capacity;
    return 0;
}

int add_entry(CRCList* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= list->max_capacity) {
        if (list->capacity_reached_callback) list->capacity_reached_callback();
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    if (resize_list(list) != 0) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    list->data[list->size++] = entry;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_entry_by_rnti(CRCList* list, unsigned int rnti) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].RNTI == rnti) {
            if (list->history_enabled) {
                RemovedEntryHistory* history = malloc(sizeof(RemovedEntryHistory));
                if (!history) {
                    pthread_mutex_unlock(&list->lock);
                    return -1;
                }
                history->RNTI = rnti;
                time_t now = time(NULL);
                history->timestamp = now;
                // Store or log the history as needed
            }

            memmove(&list->data[i], &list->data[i + 1], (list->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            list->size--;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return -1;
}

int update_crcflag(CRCList* list, unsigned int rnti, int crc_flag) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].RNTI == rnti) {
            list->data[i].CRC_INDICATION_REL8_TAG.CRCFLAG = crc_flag;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return -1;
}

void compact_list(CRCList* list) {
    pthread_mutex_lock(&list->lock);

    if (list->compaction_initiated_callback) list->compaction_initiated_callback();

    size_t write_index = 0;
    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].CRC_INDICATION_REL8_TAG.CRCFLAG != 0) {
            list->data[write_index++] = list->data[i];
        }
    }

    list->size = write_index;
    pthread_mutex_unlock(&list->lock);
}

void merge_lists(CRCList* dest, CRCList* src) {
    pthread_mutex_lock(&dest->lock);

    for (size_t i = 0; i < src->size; ++i) {
        add_entry(dest, src->data[i]);
    }

    pthread_mutex_unlock(&dest->lock);
}

void export_data_async(CRCList* list, void (*export_callback)(const NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_t thread;
    pthread_create(&thread, NULL, (void*)export_callback, list->data);
    pthread_detach(thread);
}

double report_average_memory_usage() {
    // Implement logic to track and report average memory usage
    return 0.0;
}

