#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <errno.h>

#define MAX_NICP 1000
#define MAC_ADDRESS_LENGTH 18 // "XX:XX:XX:XX:XX:XX"
#define LOG_FILE "nicp_init_log.txt"

typedef struct {
    char mac_address[MAC_ADDRESS_LENGTH + 1];
    int port;
    char security_profile_key[65]; // SHA-256 key length in hex
} NICP_Config;

typedef struct {
    NICP_Config *configs[MAX_NICP];
    pthread_mutex_t lock;
    size_t count;
} NICP_Array;

// Function prototypes
void initialize_dynamic_array(NICP_Array *nicp_array);
int generate_random_mac_address(char *mac_address);
int generate_security_profile_key(char *key, size_t key_length);
int validate_mac_uniqueness(NICP_Array *nicp_array, const char *mac_address);
void log_failure(const char *message);

// Initialize the NICP array
void initialize_dynamic_array(NICP_Array *nicp_array) {
    pthread_mutex_init(&nicp_array->lock, NULL);
    nicp_array->count = 0;

    for (int i = 0; i < MAX_NICP; ++i) {
        NICP_Config *config = malloc(sizeof(NICP_Config));
        if (!config) {
            log_failure("Failed to allocate memory for NICP configuration.");
            continue;
        }

        pthread_mutex_lock(&nicp_array->lock);
        while (1) {
            if (generate_random_mac_address(config->mac_address)) {
                log_failure("Failed to generate a random MAC address.");
                free(config);
                pthread_mutex_unlock(&nicp_array->lock);
                break;
            }

            if (!validate_mac_uniqueness(nicp_array, config->mac_address)) {
                // Handle transient connectivity issues with backoff strategy
                int attempts = 0;
                while (attempts < 5) {
                    sleep(1 << attempts); // Exponential backoff
                    if (generate_random_mac_address(config->mac_address)) {
                        log_failure("Failed to generate a unique MAC address after retries.");
                        free(config);
                        pthread_mutex_unlock(&nicp_array->lock);
                        break;
                    }
                    if (validate_mac_uniqueness(nicp_array, config->mac_address)) {
                        break;
                    }
                    attempts++;
                }

                if (!validate_mac_uniqueness(nicp_array, config->mac_address)) {
                    free(config);
                    pthread_mutex_unlock(&nicp_array->lock);
                    continue;
                }
            }

            generate_security_profile_key(config->security_profile_key, sizeof(config->security_profile_key));
            config->port = rand() % 65536; // Random port number

            nicp_array->configs[nicp_array->count++] = config;
            pthread_mutex_unlock(&nicp_array->lock);
            break;
        }
    }

    pthread_mutex_destroy(&nicp_array->lock);
}

int generate_random_mac_address(char *mac_address) {
    const char valid_hextets[] = "0123456789ABCDEF";
    for (int i = 0; i < MAC_ADDRESS_LENGTH; i += 3) {
        if (i > 0) mac_address[i] = ':';
        for (int j = 0; j < 2; ++j) {
            int r = rand() % (sizeof(valid_hextets) - 1);
            mac_address[i + j + 1] = valid_hextets[r];
        }
    }
    mac_address[MAC_ADDRESS_LENGTH] = '\0';
    return 0;
}

int generate_security_profile_key(char *key, size_t key_length) {
    const char hex_chars[] = "0123456789ABCDEF";
    for (size_t i = 0; i < key_length - 1; ++i) {
        int r = rand() % (sizeof(hex_chars) - 1);
        key[i] = hex_chars[r];
    }
    key[key_length - 1] = '\0';
    return 0;
}

int validate_mac_uniqueness(NICP_Array *nicp_array, const char *mac_address) {
    pthread_mutex_lock(&nicp_array->lock);
    for (size_t i = 0; i < nicp_array->count; ++i) {
        if (strcmp(nicp_array->configs[i]->mac_address, mac_address) == 0) {
            pthread_mutex_unlock(&nicp_array->lock);
            return 1;
        }
    }
    pthread_mutex_unlock(&nicp_array->lock);
    return 0;
}

void log_failure(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    } else {
        perror("Failed to open log file");
    }
}
