// Type to represent the dynamic array as a linked list head pointer.
typedef Node* UECtxList;

// Function to create a new node and add it at the end of the list (or update existing).
void addOrUpdateUEContext(UECtxList *list, int UE_ID, RRC_Connection_Status status, PDU_Session_ID *pdu_sessions, size_t count) {
    Node **current = list;
    while (*current != NULL && (*current)->context.UE_ID < UE_ID)
        current = &(*current)->next;

    if (*current != NULL && (*current)->context.UE_ID == UE_ID) { // Update existing
        (*current)->context.rrc_connection_status = status;

        // Free old pdu sessions and allocate new ones.
        free((*current)->context.pdu_sessions);
        (*current)->context.pdu_sessions = (pdu_sessions != NULL) ? malloc(count * sizeof(PDU_Session_ID)) : NULL;
        if (pdu_sessions != NULL && count > 0) {
            memcpy((*current)->context.pdu_sessions, pdu_sessions, count * sizeof(PDU_Session_ID));
        }
        (*current)->context.pdu_session_count = count;
    } else { // Add new
        Node* newNode = malloc(sizeof(Node));
        if (newNode == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }

        newNode->context.UE_ID = UE_ID;
        newNode->context.rrc_connection_status = status;

        newNode->context.pdu_sessions = (pdu_sessions != NULL) ? malloc(count * sizeof(PDU_Session_ID)) : NULL;
        if (pdu_sessions != NULL && count > 0) {
            memcpy(newNode->context.pdu_sessions, pdu_sessions, count * sizeof(PDU_Session_ID));
        }

        newNode->context.pdu_session_count = count;
        newNode->next = (*current);

        *list = newNode; // Insert at the beginning for simplicity and efficiency.
    }
}

// Function to retrieve a specific UEContext by its UE_ID.
UEContext* getUEContext(UECtxList list, int UE_ID) {
    Node *current = list;
    while (current != NULL) {
        if (current->context.UE_ID == UE_ID)
            return &current->context;
        current = current->next;
    }
    return NULL; // Not found
}

// Function to free all allocated resources.
void freeUEContextList(UECtxList *list) {
    Node *current = *list, *temp;
    while (current != NULL) {
        temp = current;
        current = current->next;

        free(temp->context.pdu_sessions);
        free(temp);
    }
    *list = NULL;
}

// Example usage
int main() {
    UECtxList ueCtxList = NULL;

    // Add a new UEContext entry.
    PDU_Session_ID sessions[] = {{101}, {102}};
    addOrUpdateUEContext(&ueCtxList, 1, CONNECTION_ACTIVE, sessions, 2);

    // Retrieve and print a specific UEContext by its UE_ID.
    UEContext *context = getUEContext(ueCtxList, 1);
    if (context) {
        printf("UE ID: %d\n", context->UE_ID);
        printf("RRC Connection Status: %d\n", context->rrc_connection_status);

        for (size_t i = 0; i < context->pdu_session_count; ++i)
            printf("PDU Session ID: %d\n", context->pdu_sessions[i].session_id);
    }

    // Free all allocated resources.
    freeUEContextList(&ueCtxList);

    return 0;
}
```

### Key Considerations:
- **Performance**: The linked list implementation allows for efficient insertion and search operations due to its dynamic nature, although not as fast as a hash table for very large datasets. For even larger scales or more frequent updates, consider using a hash map.
- **Memory Management**: Carefully manage memory allocation and deallocation to prevent leaks. Each `UEContext` node manages its own `pdu_sessions`, allowing individual control over each entry's memory usage.
- **Scalability**: The function can be easily deployed in multiple instances for horizontal scaling, with appropriate external mechanisms for state sharing (e.g., distributed databases or shared caches).']

