#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <curl/curl.h>

#define HASH_TABLE_SIZE 1024

typedef struct {
    char USER_ID[256];
    time_t EXPIRATION_TIMESTAMP;
    char SESSION_DATA[512];
} AuthToken;

typedef struct HashNode {
    AuthToken token;
    struct HashNode* next;
} HashNode;

typedef struct {
    HashNode** buckets;
    pthread_mutex_t mutexes[HASH_TABLE_SIZE];
    int size;
} DynamicHashTable;

DynamicHashTable* init_hash_table(int size) {
    if (size <= 0) return NULL;

    DynamicHashTable* table = (DynamicHashTable*)malloc(sizeof(DynamicHashTable));
    table->buckets = (HashNode**)calloc(size, sizeof(HashNode*));
    table->size = size;

    for (int i = 0; i < size; i++) {
        pthread_mutex_init(&table->mutexes[i], NULL);
    }

    return table;
}

unsigned long hash_function(const char *USER_ID) {
    unsigned long hash = 5381;
    int c;

    while ((c = *USER_ID++))
        hash = ((hash << 5) + hash) + c;

    return hash % HASH_TABLE_SIZE;
}

int add_token(DynamicHashTable* table, const AuthToken* token) {
    if (!table || !token) return -1;

    unsigned long index = hash_function(token->USER_ID);
    pthread_mutex_lock(&table->mutexes[index]);

    HashNode* newNode = (HashNode*)malloc(sizeof(HashNode));
    *newNode = *(HashNode*)malloc(sizeof(HashNode));
    newNode->token = *token;
    newNode->next = table->buckets[index];
    table->buckets[index] = newNode;

    pthread_mutex_unlock(&table->mutexes[index]);
    return 0;
}

int is_token_expired(const AuthToken* token) {
    if (!token) return -1;
    return (time(NULL) >= token->EXPIRATION_TIMESTAMP);
}

void log_failed_authentication(const char *USER_ID) {
    CURL *curl = curl_easy_init();
    if(curl) {
        char post_data[512];
        snprintf(post_data, sizeof(post_data), "{\"user_id\":\"%s\"}", USER_ID);

        struct curl_slist* headers = NULL;
        headers = curl_slist_append(headers, "Content-Type: application/json");

        curl_easy_setopt(curl, CURLOPT_URL, "https://logging-service.example.com/log");
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, post_data);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        CURLcode res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
    }
}

AuthToken* get_token(DynamicHashTable* table, const char *USER_ID) {
    if (!table || !USER_ID) return NULL;

    unsigned long index = hash_function(USER_ID);
    pthread_mutex_lock(&table->mutexes[index]);

    HashNode* node = table->buckets[index];
    while (node) {
        if (strcmp(node->token.USER_ID, USER_ID) == 0 && !is_token_expired(&node->token)) {
            AuthToken *result = (AuthToken*)malloc(sizeof(AuthToken));
            *result = node->token;
            pthread_mutex_unlock(&table->mutexes[index]);
            return result;
        }
        node = node->next;
    }

    log_failed_authentication(USER_ID);
    pthread_mutex_unlock(&table->mutexes[index]);
    return NULL;
}

void free_hash_table(DynamicHashTable* table) {
    if (!table) return;

    for (int i = 0; i < table->size; i++) {
        HashNode *node = table->buckets[i];
        while (node) {
            HashNode *temp = node;
            node = node->next;
            free(temp);
        }
        pthread_mutex_destroy(&table->mutexes[i]);
    }

    free(table->buckets);
    free(table);
}
```

This code includes:
- Initialization of a dynamic hash table with thread-safe operations using mutexes.
- Functions to add, retrieve, and check expiration of tokens.
- Logging failed authentication attempts via a REST API call using libcurl for HTTP requests.
- Ensuring the system is scalable by managing concurrency efficiently.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

typedef struct {
    int value;
    int* key;
} Record;

typedef struct {
    Record** records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    uint64_t total_sum; // Using uint64_t to handle overflow
    uint32_t compact_count;
    uint32_t processed_records;
    pthread_mutex_t stats_lock;
} RecordCollection;

RecordCollection* create_collection(size_t initial_capacity) {
    RecordCollection* collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);
    collection->total_sum = 0;
    collection->compact_count = 0;
    collection->processed_records = 0;
    pthread_mutex_init(&collection->stats_lock, NULL);

    return collection;
}

void free_collection(RecordCollection* collection) {
    if (!collection) return;

    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->records[i]);
    }
    free(collection->records);
    pthread_mutex_destroy(&collection->lock);
    pthread_mutex_destroy(&collection->stats_lock);
    free(collection);
}

void compact_memory(RecordCollection* collection);

int add_record(RecordCollection* collection, int key_value) {
    if (!collection) return -1;

    pthread_mutex_lock(&collection->lock);

    // Check capacity and possibly compact
    if (collection->count >= collection->capacity * 0.75) {
        compact_memory(collection);
    }

    // Allocate new record
    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) {
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    int64_t prev_total = collection->total_sum;

    // Random value initialization within a range based on the rolling sum
    srand(time(NULL) + collection->count); // Seed based on count for diversity
    new_record->value = rand() % (prev_total + 100);

    if (new_record->value < 0) { // Ensure positive values to simplify overflow handling
        new_record->value = -new_record->value;
    }

    int64_t potential_new_sum = prev_total + new_record->value;

    // Handle integer overflow
    if (potential_new_sum < prev_total) {
        free(new_record);
        pthread_mutex_unlock(&collection->lock);
        return -2; // Overflow detected, cannot safely add the record
    }

    collection->total_sum = potential_new_sum;
    new_record->key = &key_value;

    // Add record to array and increase count
    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Record** new_records = (Record**)realloc(collection->records, new_capacity * sizeof(Record*));
        if (!new_records) {
            free(new_record);
            pthread_mutex_unlock(&collection->lock);
            return -1; // Realloc failed
        }
        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    collection->records[collection->count++] = new_record;

    pthread_mutex_lock(&collection->stats_lock);
    ++collection->processed_records;
    pthread_mutex_unlock(&collection->stats_lock);

    pthread_mutex_unlock(&collection->lock);
    return 0; // Success
}

void compact_memory(RecordCollection* collection) {
    if (!collection || collection->count == 0) return;

    pthread_mutex_lock(&collection->lock);

    size_t new_capacity = collection->capacity > 16 ? collection->capacity / 2 : 16;
    Record** new_records = (Record**)realloc(collection->records, new_capacity * sizeof(Record*));

    if (!new_records && new_capacity < collection->capacity) {
        pthread_mutex_unlock(&collection->lock);
        return; // Keep existing memory if reallocation fails and new capacity is smaller
    }

    for (size_t i = 0; i < collection->count; ++i) {
        new_records[i] = collection->records[i];
    }

    free(collection->records);
    collection->records = new_records;
    collection->capacity = new_capacity;

    pthread_mutex_lock(&collection->stats_lock);
    ++collection->compact_count;
    pthread_mutex_unlock(&collection->stats_lock);

    pthread_mutex_unlock(&collection->lock);
}

// Optional function to print stats
void print_stats(RecordCollection* collection) {
    if (!collection) return;
    pthread_mutex_lock(&collection->stats_lock);
    printf("Total records processed: %u\n", collection->processed_records);
    printf("Memory compactions performed: %u\n", collection->compact_count);
    pthread_mutex_unlock(&collection->stats_lock);
}
```

### Decision-making comments in the code:

1. **Rolling Sum with Overflow Handling**: The sum of all record values is managed using `uint64_t` to minimize overflow risk, allowing up to 18 quintillion as a safe limit for addition operations.

2. **Compact Memory**: To reduce memory fragmentation and overhead from reallocations, compaction occurs when the collection exceeds 75% capacity but not more frequently than necessary to avoid performance hits due to frequent reallocations.

3. **Thread Safety**: Mutexes ensure thread safety during read-modify-write operations on shared data structures (`records` array and `total_sum`).

4. **Compaction Strategy**: The compaction is performed when collection usage exceeds 75% of its capacity, aiming for a balance between performance and memory efficiency. A minimum threshold ensures we never compact below a base size to avoid excessive shrinking.

5. **Logging**: Tracks the number of compactions and records processed to help assess performance impact over time.']

