const fs = require('fs').promises;
const path = require('path');

async function processFiles(filePaths, initialState, callback) {
  const cache = new Map();
  let finalState = { ...initialState };

  async function readFile(filePath) {
    if (cache.has(filePath)) return cache.get(filePath);

    try {
      const data = await fs.readFile(filePath, 'utf8');
      cache.set(filePath, data);
      return data;
    } catch (error) {
      throw new Error(`Error reading file ${filePath}: ${error.message}`);
    }
  }

  async function processFile(filePath) {
    try {
      // Optional filtering criteria
      const stats = await fs.stat(filePath);
      if (/skip_this_pattern/.test(path.basename(filePath)) || stats.size > 1e6) return;

      const content = await readFile(filePath);
      const metadata = parseMetadata(content);

      callback(finalState, { filePath, content, metadata });
    } catch (error) {
      console.error(error.message);
    }
  }

  async function processFilesInParallel() {
    const promises = filePaths.map(processFile);
    await Promise.all(promises);
  }

  try {
    await processFilesInParallel();
  } catch (error) {
    throw new Error(`Processing error: ${error.message}`);
  }

  return finalState;
}

function parseMetadata(content) {
  // Dummy implementation for metadata extraction
  const lines = content.split('\n');
  const headerLine = lines.find(line => line.startsWith('Header:'));
  if (!headerLine) return {};

  const attributes = headerLine.split(':').slice(1).join(':').trim().split(',');
  return attributes.reduce((acc, attr) => {
    const [key, value] = attr.split('=');
    acc[key.trim()] = value ? value.trim() : true;
    return acc;
  }, {});
}

// Sample usage
(async () => {
  const initialState = {};
  const filePaths = ['file1.txt', 'file2.txt', 'skip_this_pattern_file.txt'];

  function updateState(state, fileData) {
    if (fileData.metadata['important']) {
      state[fileData.filePath] = fileData.content.length;
    }
  }

  try {
    const finalState = await processFiles(filePaths, initialState, updateState);
    console.log(finalState);
  } catch (error) {
    console.error(error.message);
  }
})();
