                log_event("External API call failed. Retrying...");
                sleep(backoff_ms / 1000);
                retry_count++;
                backoff_ms *= 2; // Exponential backoff
            } else {
                cached_data.string = "FetchedData";
            }
        }

        if (cached_data.string) {
            update_cache(cache_key, &cached_data);
        } else {
