#include <unistd.h>

#define MAX_RETRIES 5

typedef struct {
    char MAC_ADDRESS[18]; // Format XX:XX:XX:XX:XX:XX
    int PORT;
    unsigned long SECURITY_PROFILE_KEY;
} NICP_Config;

typedef struct Record {
    int offset_value;
    int key_index;
} Record;

// Global variables and structures for thread-safe operations
pthread_mutex_t nicp_lock = PTHREAD_MUTEX_INITIALIZER;
NICP_Config* configurations;
int num_configs = 0;
Record* records;
size_t record_count = 0;
pthread_mutex_t record_lock = PTHREAD_MUTEX_INITIALIZER;
unsigned long total_sum = 0;

// Function declarations
void initialize_dynamic_array(size_t initial_capacity);
int add_nicp_configuration(const char* mac, int port, unsigned long key);
void log_failure(const char* message);
long backoff_strategy(int attempt);

// Thread-safe logging function
void log_failure(const char* message) {
    pthread_mutex_lock(&record_lock);
    FILE* log_file = fopen("error_log.txt", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
    pthread_mutex_unlock(&record_lock);
}

// Backoff strategy for retries
long backoff_strategy(int attempt) {
    return (1 << attempt); // Exponential backoff
}

// Function to initialize the dynamic array with initial capacity
void initialize_dynamic_array(size_t initial_capacity) {
    configurations = malloc(sizeof(NICP_Config) * initial_capacity);
    records = malloc(sizeof(Record) * initial_capacity);
    if (!configurations || !records) {
        log_failure("Memory allocation failed during initialization.");
        exit(EXIT_FAILURE);
    }
}

// Add a new NICP configuration, ensuring thread safety
int add_nicp_configuration(const char* mac, int port, unsigned long key) {
    pthread_mutex_lock(&nicp_lock);

    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        // Validate MAC address uniqueness and network latency handling
        int unique = 1;
        for (int i = 0; i < num_configs; ++i) {
            if (strcmp(configurations[i].MAC_ADDRESS, mac) == 0) {
                unique = 0;
                break;
            }
        }

        if (unique) {
            // Handle MAC address addition
            strncpy(configurations[num_configs].MAC_ADDRESS, mac, sizeof(configurations[0].MAC_ADDRESS));
            configurations[num_configs].PORT = port;
            configurations[num_configs].SECURITY_PROFILE_KEY = key;
            num_configs++;

            pthread_mutex_unlock(&nicp_lock);
            return 0; // Success
        }

        // Log failure and perform backoff before retrying
        char log_msg[256];
        snprintf(log_msg, sizeof(log_msg), "MAC address %s already exists. Retry attempt %d.", mac, attempt + 1);
        log_failure(log_msg);

        sleep(backoff_strategy(attempt)); // Backoff strategy for network latency

        pthread_mutex_unlock(&nicp_lock);
    }

    pthread_mutex_unlock(&nicp_lock);
    return -1; // Failure after retries
}

// Function to initialize records with constraints from external data sources
void initialize_records(size_t num) {
    srand(time(NULL));

    pthread_mutex_lock(&record_lock);

    for (size_t i = 0; i < record_count; ++i) {
        long min_range = total_sum + 1;
        long max_range = min_range + 100;

        if ((max_range - min_range) > LONG_MAX) {
            log_failure("Integer overflow detected in range calculation.");
            pthread_mutex_unlock(&record_lock);
            return;
        }

        records[i].offset_value = rand() % (max_range - min_range) + min_range;
        total_sum += records[i].offset_value;
    }

    record_count = num;

    pthread_mutex_unlock(&record_lock);
}

int main() {
    initialize_dynamic_array(10);

    // Example of adding configurations
    add_nicp_configuration("00:11:22:33:44:55", 8080, 123456789);
    add_nicp_configuration("66:77:88:99:AA:BB", 9090, 987654321);

    initialize_records(5);

    // Free allocated memory
    free(configurations);
    free(records);

    return 0;
}
