#include <pthread.h>
#include <stdlib.h>
#include <string.h>

#define MAX_SESSION_DATA_SIZE 1000

typedef struct {
    int UEIdentifier;
    int RRCConnectionStatus;
    char *sessionData;
} UESessionState;

typedef struct SessionNode {
    UESessionState session;
    struct SessionNode* next;
} SessionNode;

typedef struct {
    SessionNode* head;
    pthread_rwlock_t lock;
} SessionManager;

// Function to initialize the session manager
void initSessionManager(SessionManager *manager) {
    manager->head = NULL;
    pthread_rwlock_init(&manager->lock, NULL);
}

// Helper function to create a new session node
SessionNode* createSessionNode(UESessionState session) {
    SessionNode* newNode = (SessionNode*)malloc(sizeof(SessionNode));
    if (!newNode) return NULL;

    newNode->session.UEIdentifier = session.UEIdentifier;
    newNode->session.RRCConnectionStatus = session.RRCConnectionStatus;
    newNode->session.sessionData = malloc(MAX_SESSION_DATA_SIZE);
    if (!newNode->session.sessionData) {
        free(newNode);
        return NULL;
    }

    newNode->next = NULL;
    return newNode;
}

// Function to add or update a session
void updateSession(SessionManager *manager, UESessionState newSession) {
    pthread_rwlock_wrlock(&manager->lock);

    SessionNode *current = manager->head;
    SessionNode *prev = NULL;

    while (current != NULL && current->session.UEIdentifier != newSession.UEIdentifier) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        // Create a new session
        SessionNode* newNode = createSessionNode(newSession);
        if (!newNode) return;

        if (prev == NULL) {
            manager->head = newNode;
        } else {
            prev->next = newNode;
        }
    } else {
        // Update existing session
        current->session.RRCConnectionStatus = newSession.RRCConnectionStatus;
        memcpy(current->session.sessionData, newSession.sessionData,
               MIN(strlen((char*)newSession.sessionData) + 1, MAX_SESSION_DATA_SIZE));
    }

    pthread_rwlock_unlock(&manager->lock);
}

// Function to delete a session
void deleteSession(SessionManager *manager, int UEIdentifier) {
    pthread_rwlock_wrlock(&manager->lock);

    SessionNode *current = manager->head;
    SessionNode *prev = NULL;

    while (current != NULL && current->session.UEIdentifier != UEIdentifier) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) return;

    if (prev == NULL) {
        // Deleting the head
        manager->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current->session.sessionData);
    free(current);

    pthread_rwlock_unlock(&manager->lock);
}

// Function to clean up the session manager
void destroySessionManager(SessionManager *manager) {
    pthread_rwlock_wrlock(&manager->lock);

    SessionNode* current = manager->head;
    while (current != NULL) {
        SessionNode* temp = current;
        current = current->next;

        free(temp->session.sessionData);
        free(temp);
    }

    manager->head = NULL;
    pthread_rwlock_unlock(&manager->lock);
    pthread_rwlock_destroy(&manager->lock);
}

// Example test case
void testSessionManager() {
    SessionManager manager;
    initSessionManager(&manager);

    UESessionState session1 = {1, 0, "Initial Data"};
    updateSession(&manager, session1);

    char newData[] = "Updated Data";
    strcpy(session1.sessionData, newData);
    updateSession(&manager, session1);

    deleteSession(&manager, 1);
    destroySessionManager(&manager);
}
``` 

### Design Choices:

- **Thread Safety**: Used `pthread_rwlock_t` for read-write locks to allow concurrent reads and exclusive writes. This reduces lock contention compared to a global mutex.

- **Memory Management**: Dynamic allocation for session data ensures flexibility in handling varying session sizes up to 1000 bytes, while individual node memory management prevents fragmentation.

- **Concurrency Handling**: Locks are applied at the granularity of operations (update, delete), minimizing contention during high-throughput scenarios.

- **Scalability and Extendibility**: The linked list structure allows easy extension for additional session attributes without major restructuring. Use of `pthread_rwlock_t` aids in scalability under concurrent access.

### Test Cases:

1. **Basic Functionality**:
   - Add a session, update it, then delete it.

2. **Concurrent Updates**:
   - Simulate multiple threads updating different sessions concurrently to ensure data integrity.

3. **Edge Cases**:
   - Attempt to delete a non-existent session.
   - Update a session with buffer size larger than 1000 bytes (ensure truncation).

4. **Stress Testing**:
   - Rapidly add, update, and delete thousands of sessions to test performance under load.']

