        NFAPI_CRC_INDICATION_PDU_T *new_cache = realloc(cache->cache, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_cache) {
            pthread_mutex_unlock(&cache_lock);
            return -1; // Memory allocation failed
        }
        cache->capacity = new_capacity;
        cache->cache = new_cache;
    }

    cache->cache[cache->count] = pdu;
    cache->count++;
    pthread_mutex_unlock(&cache_lock);
    return 0;
}

