    if (!ptr) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

unsigned int pseudo_random(unsigned int *seed, unsigned int min, unsigned int max) {
    *seed = (*seed * 1103515245 + 12345) & 0x7fffffff;
    return min + ((*seed % (max - min + 1))));
}

int is_unique(char *identifiers[], const char *identifier, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (strcmp(identifiers[i], identifier) == 0) {
            return 0;
        }
    }
    return 1;
}

void generate_unique_identifier(char *identifiers[], char *identifier, size_t index) {
    unsigned int seed = index;
    do {
        for (int i = 0; i < IDENTIFIER_LEN - 1; ++i) {
            identifier[i] = 'a' + pseudo_random(&seed, 0, 25);
        }
        identifier[IDENTIFIER_LEN - 1] = '\0';
    } while (!is_unique(identifiers, identifier, index));
}

typedef struct {
    long *offsets;
    int *keys;
    Record *records;
    char **identifiers;
    pthread_mutex_t mutex;
} DataStructures;

int initialize_data_structures(size_t maxSize, unsigned int minValue, unsigned int maxValue, DataStructures *data) {
    if (maxSize > MAX_RECORDS) {
        fprintf(stderr, "Invalid maxSize: exceeds maximum allowed records of %d\n", MAX_RECORDS);
        return -1;
    }

    pthread_mutex_init(&data->mutex, NULL);

    data->offsets = (long *)allocate_memory(maxSize * sizeof(long));
    data->keys = (int *)allocate_memory(maxSize * sizeof(int));
    data->records = (Record *)allocate_memory(maxSize * sizeof(Record));
    data->identifiers = (char **)allocate_memory(maxSize * sizeof(char *));

    for (size_t i = 0; i < maxSize; ++i) {
        data->offsets[i] = i;
        data->keys[i] = i + 1;

        unsigned int seed = i;
        data->records[i].value = pseudo_random(&seed, minValue, maxValue);

        data->identifiers[i] = (char *)allocate_memory(IDENTIFIER_LEN);
        generate_unique_identifier(data->identifiers, data->identifiers[i], i);

        data->records[i].identifier = data->identifiers[i];
    }

    return 0;
}

void free_data_structures(DataStructures *data) {
    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        if (data->identifiers[i]) {
            free(data->identifiers[i]);
        }
    }
    pthread_mutex_destroy(&data->mutex);
    free(data->offsets);
    free(data->keys);
    free(data->records);
    free(data->identifiers);
}

