#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef enum {
    ERROR,
    WARNING,
    INFO,
    DEBUG
} EventType;

typedef struct {
    long eventTime;
    EventType eventType;
    char *message;
} NetworkEvent;

typedef struct Node {
    NetworkEvent event;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    pthread_mutex_t lock;
} EventCollection;

// Initialize the collection
void initEventCollection(EventCollection* collection) {
    collection->head = NULL;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);
}

// Validate network event
int isValidNetworkEvent(NetworkEvent* event) {
    return event != NULL && event->eventTime > 0 && event->message != NULL && strlen(event->message) > 0;
}

// Add a new event to the collection
void addEvent(EventCollection* collection, NetworkEvent* event) {
    if (!isValidNetworkEvent(event)) return;

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return;

    newNode->event = *event;
    newNode->next = NULL;

    pthread_mutex_lock(&collection->lock);

    if (!collection->head || collection->head->event.eventTime > event->eventTime) {
        newNode->next = collection->head;
        collection->head = newNode;
    } else {
        Node* current = collection->head;
        while (current->next && current->next->event.eventTime <= event->eventTime) {
            current = current->next;
        }
        newNode->next = current->next;
        current->next = newNode;
    }

    collection->count++;
    pthread_mutex_unlock(&collection->lock);
}

// Free the memory of all events in the collection
void freeEventCollection(EventCollection* collection) {
    pthread_mutex_lock(&collection->lock);

    Node* current = collection->head;
    while (current) {
        Node* next = current->next;
        free(current->event.message);
        free(current);
        current = next;
    }

    collection->head = NULL;
    collection->count = 0;

    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
}

