#define MAX_RECORDS 1000
#define IDENTIFIER_LENGTH 16

typedef struct {
    int value;
    char *identifier;
} Record;

void* custom_malloc(size_t size);
int custom_rand(int min, int max);
void initialize_bloom_filter(unsigned char *filter, size_t filter_size);

unsigned char bloom_filter[64]; // Simple bloom filter for demonstration
int bloom_size = sizeof(bloom_filter) / 8; // Number of bits

typedef struct {
    long *offsets;
    int *keys;
    Record *records;
} MemoryManager;

MemoryManager* allocate_memory(int maxSize, int minValue, int maxValue) {
    if (maxSize <= 0 || maxSize > MAX_RECORDS) {
        fprintf(stderr, "Invalid maxSize: %d. Must be between 1 and %d.\n", maxSize, MAX_RECORDS);
        return NULL;
    }

    MemoryManager *manager = custom_malloc(sizeof(MemoryManager));
    if (!manager) {
        perror("Failed to allocate memory manager");
        return NULL;
    }

    // Allocate arrays
    manager->offsets = custom_malloc(maxSize * sizeof(long));
    manager->keys = custom_malloc(maxSize * sizeof(int));
    manager->records = custom_malloc(maxSize * sizeof(Record));

    if (!manager->offsets || !manager->keys || !manager->records) {
        fprintf(stderr, "Memory allocation failed for one or more arrays.\n");
        free(manager->offsets);
        free(manager->keys);
        free(manager->records);
        free(manager);
        return NULL;
    }

    // Initialize offsets and keys
    for (int i = 0; i < maxSize; ++i) {
        manager->offsets[i] = i;
        manager->keys[i] = i + 1;
    }

    srand(time(NULL)); // Seed the random number generator

    initialize_bloom_filter(bloom_filter, bloom_size);

    for (int i = 0; i < maxSize; ++i) {
        // Generate a unique identifier
        char identifier[IDENTIFIER_LENGTH + 1];
        int is_unique;
        do {
            is_unique = 1;
            for (int j = 0; j < IDENTIFIER_LENGTH; ++j) {
                identifier[j] = 'A' + rand() % 26; // Random ASCII characters A-Z
            }
            identifier[IDENTIFIER_LENGTH] = '\0';

            // Check for uniqueness using bloom filter
            unsigned char hash1 = (unsigned char)(strtol(identifier, NULL, 36) % bloom_size);
            if (bloom_filter[hash1 / 8] & (1 << (hash1 % 8))) {
                is_unique = 0;
            }
        } while (!is_unique);

        // Set the identifier in the record
        manager->records[i].identifier = custom_malloc(IDENTIFIER_LENGTH + 1);
        if (!manager->records[i].identifier) {
            fprintf(stderr, "Failed to allocate memory for identifier.\n");
            return NULL;
        }
        strcpy(manager->records[i].identifier, identifier);

        // Set the value
        manager->records[i].value = custom_rand(minValue, maxValue);

        // Add identifier hash to bloom filter
        unsigned char hash1 = (unsigned char)(strtol(identifier, NULL, 36) % bloom_size);
        bloom_filter[hash1 / 8] |= (1 << (hash1 % 8));
    }

    return manager;
}

void free_memory(MemoryManager *manager) {
    if (!manager) return;

    for (int i = 0; i < MAX_RECORDS && manager->records[i].identifier; ++i) {
        free(manager->records[i].identifier);
    }
    free(manager->offsets);
    free(manager->keys);
    free(manager->records);
    free(manager);
}

void* custom_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr && size != 0) {
        perror("malloc");
    }
    return ptr;
}

int custom_rand(int min, int max) {
    return min + rand() % (max - min + 1);
}

void initialize_bloom_filter(unsigned char *filter, size_t filter_size) {
    memset(filter, 0, filter_size);
}
