#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

#define MAX_RNTI 65535
#define MAX_CHECS_PER_SEGMENT 15000
#define NUM_THREADS 5

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        int32_t CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
uint16_t global_rnti_seed = 0; // Global seed for generating unique RNTIs

void* process_segment(void* args) {
    int* segment_data = (int*)args;
    int segment_size = *(segment_data + 1);
    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(segment_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pdus) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_exit(NULL);
    }

    for (int i = 0; i < segment_size; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = segment_data[i];
        pthread_mutex_lock(&mutex);
        pdus[i].RNTI = global_rnti_seed++;
        if (pdus[i].RNTI >= MAX_RNTI)
            pdus[i].RNTI = 0; // wrap around
        pthread_mutex_unlock(&mutex);

        srand(time(NULL) + i);
        pdus[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
    }

    int max_value = INT32_MIN;
    for (int i = 0; i < segment_size; ++i) {
        if (pdus[i].RX_UE_INFORMATION_TAG > max_value) {
            max_value = pdus[i].RX_UE_INFORMATION_TAG;
        }
    }

    printf("Max value in segment: %d\n", max_value);

    free(pdus);
    pthread_exit(NULL);
}

int main() {
    int segments[NUM_THREADS][MAX_CHECS_PER_SEGMENT + 1] = {0};
    pthread_t threads[NUM_THREADS];

    // Example of initializing segments with dummy data
    for (int i = 0; i < NUM_THREADS; ++i) {
        segments[i][1] = rand() % MAX_CHECS_PER_SEGMENT + 1;
        for (int j = 0; j < segments[i][1]; ++j) {
            segments[i][j] = rand() % 1000000; // Random integer values
        }
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        if (pthread_create(&threads[i], NULL, process_segment, &segments[i])) {
            fprintf(stderr, "Error creating thread\n");
            return 1;
        }
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    pthread_mutex_destroy(&mutex);
    return 0;
}
```

### Key Points:
- **Memory Allocation**: Each segment is dynamically allocated and processed in separate threads.
- **Unique RNTI Generation**: Uses a global seed protected by a mutex to ensure unique `RNTI` values across all segments.
- **Concurrency**: Utilizes pthreads for concurrent processing of each segment.
- **Error Handling**: Checks for memory allocation failures and thread creation errors.
- **Max Value Calculation**: Each thread calculates the maximum integer in its respective segment.
- **Logging**: Outputs the maximum value found in each segment.

This code is designed to be modular, allowing easy integration into larger systems. Adjustments may be needed based on specific system requirements or constraints.']

