static pthread_mutex_t mem_lock = PTHREAD_MUTEX_INITIALIZER;

void log_memory_usage(size_t allocation_count, size_t deallocation_count) {
    printf("Allocations: %zu, Deallocations: %zu\n", allocation_count, deallocation_count);
