CustomAllocator* create_allocator(size_t block_size, size_t pool_size) {
    CustomAllocator *allocator = malloc(sizeof(CustomAllocator));
    allocator->block_size = block_size;
    allocator->pool_size = pool_size;
    allocator->pool = malloc(pool_size * block_size);

    pthread_mutex_init(&allocator->lock, NULL);
    return allocator;
}

void* custom_alloc(CustomAllocator *allocator) {
    pthread_mutex_lock(&allocator->lock);
    void *block = malloc(allocator->block_size);
    if (pthread_mutex_trylock(&mem_lock) == 0) {
        // Check memory usage and free if necessary
        pthread_mutex_unlock(&mem_lock);
    }
    pthread_mutex_unlock(&allocator->lock);
    return block;
}

void custom_free(CustomAllocator *allocator, void *ptr) {
    pthread_mutex_lock(&allocator->lock);
    free(ptr);
    if (pthread_mutex_trylock(&mem_lock) == 0) {
        // Check memory usage and free if necessary
        pthread_mutex_unlock(&mem_lock);
    }
    pthread_mutex_unlock(&allocator->lock);
}

void destroy_allocator(CustomAllocator *allocator) {
    free(allocator->pool);
    pthread_mutex_destroy(&allocator->lock);
    free(allocator);
}

int generate_random(int min, int max) {
    return rand() % (max - min + 1) + min;
}

