    DataRecord *records = custom_alloc(allocator, sizeof(DataRecord) * record_count);
    if (!records) return NULL;

    size_t allocation_count = 0;
    for (size_t i = 0; i < record_count && atomic_load(&cumulative_sum) < MAX_SUM_LIMIT; ++i) {
        int value = generate_random(range_min, range_max);

        pthread_mutex_lock(&sum_lock);
        if (atomic_add_fetch(&cumulative_sum, value) >= MAX_SUM_LIMIT) {
            pthread_mutex_unlock(&sum_lock);
            custom_free(allocator, records);
            return NULL;
        }
        pthread_mutex_unlock(&sum_lock);

        records[i].offset = i * sizeof(DataRecord);
        records[i].key = generate_random(range_min, range_max);
        records[i].record.value = value;

        allocation_count++;
    }

    log_memory_usage(allocation_count, 0); // Initial logging

    return records;
}

void free_records(DataRecord *records, CustomAllocator *allocator) {
    if (records) custom_free(allocator, records);
    size_t deallocation_count = 1; // Simplified for example
    log_memory_usage(0, deallocation_count); // Logging on deallocation
}

void* thread_func(void *arg) {
