#define MAX_RECORDS 1000
#define INITIAL_CAPACITY 10

typedef struct {
    int value;
} Record;

typedef struct {
    char type[50];
    size_t size;
} Resource;

typedef struct {
    time_t timestamp;
    int status_flag;
    Resource* resource;
    Record record;
} DataObject;

typedef struct {
    DataObject** objects;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    uint64_t total_record_value;
    uint64_t total_resource_size;
} DataManager;

DataManager* create_data_manager() {
    DataManager* manager = (DataManager*)malloc(sizeof(DataManager));
    if (!manager) return NULL;

    manager->objects = (DataObject**)calloc(INITIAL_CAPACITY, sizeof(DataObject*));
    if (!manager->objects) {
        free(manager);
        return NULL;
    }

    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    manager->total_record_value = 0;
    manager->total_resource_size = 0;

    return manager;
}

void resize_data_manager(DataManager* manager) {
    size_t new_capacity = manager->capacity * 2;
    DataObject** new_objects = (DataObject**)realloc(manager->objects, new_capacity * sizeof(DataObject*));
    if (!new_objects) return; // handle realloc failure

    memset(new_objects + manager->capacity, 0, manager->capacity * sizeof(DataObject*));

    manager->objects = new_objects;
    manager->capacity = new_capacity;
}

DataObject* create_data_object(Resource* resource, int min_value, int max_value) {
    DataObject* obj = (DataObject*)malloc(sizeof(DataObject));
    if (!obj) return NULL;

    pthread_mutex_lock(&manager.lock);
    if (manager.count >= MAX_RECORDS) {
        pthread_mutex_unlock(&manager.lock);
        free(obj);
        return NULL;
    }

    // Allocate resource and initialize the object
    obj->resource = resource;
    obj->timestamp = time(NULL);
    obj->status_flag = 0; // default status

    int sum_of_previous_values = manager.total_record_value;
    uint32_t range = (uint32_t)((max_value - min_value + 1) * ((double)rand() / RAND_MAX));
    obj->record.value = min_value + (range % (sum_of_previous_values + 1));

    manager.objects[manager.count++] = obj;
    if (manager.count >= manager.capacity) {
        resize_data_manager(manager);
    }

    manager.total_record_value += obj->record.value;
    manager.total_resource_size += resource->size;

    pthread_mutex_unlock(&manager.lock);

    return obj;
}

void destroy_data_manager(DataManager* manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->objects[i]);
    }
    free(manager->objects);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

// Example usage
int main() {
    srand(time(NULL));

    DataManager* manager = create_data_manager();
    if (!manager) return EXIT_FAILURE;

    Resource resource = {"example", 1024};

    for (int i = 0; i < 100; ++i) {
        create_data_object(&resource, 1, 100);
    }

    destroy_data_manager(manager);

    return EXIT_SUCCESS;
}
