import java.io.*;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.locks.ReentrantLock;

class Record {
    long offset;
    int key;
    double value;

    public Record(long offset, int key, double value) {
        this.offset = offset;
        this.key = key;
        this.value = value;
    }
}

public class ExternalCommandExecutor {

    private static final ReentrantLock lock = new ReentrantLock();

    public static void main(String[] args) {
        String command = "your-command-here";
        String directoryPath = "/path/to/directory";

        if (isDirectoryWritable(directoryPath)) {
            executeCommand(command, 10000);
        }

        try {
            int numRecords = readConfigFile("config.txt");
            allocateMemory(numRecords);
        } catch (IOException e) {
            System.err.println("Error reading config file: " + e.getMessage());
        }
    }

    private static boolean isDirectoryWritable(String path) {
        File dir = new File(path);
        return dir.canWrite();
    }

    private static void executeCommand(String command, int timeoutMillis) {
        try {
            Process process = Runtime.getRuntime().exec(command);
            if (process.waitFor(timeoutMillis, java.util.concurrent.TimeUnit.MILLISECONDS)) {
                captureOutput(process.getInputStream());
                captureError(process.getErrorStream());
            } else {
                System.err.println("Command execution timed out");
                process.destroy();
            }
        } catch (IOException | InterruptedException e) {
            System.err.println("Error executing command: " + e.getMessage());
        }
    }

    private static void captureOutput(InputStream inputStream) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream))) {
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
        }
    }

    private static void captureError(InputStream errorStream) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(errorStream))) {
            String line;
            while ((line = reader.readLine()) != null) {
                System.err.println("ERROR: " + line);
            }
        }
    }

    private static int readConfigFile(String filePath) throws IOException {
        return Integer.parseInt(Files.readString(Paths.get(filePath)).trim());
    }

    private static void allocateMemory(int numRecords) {
        lock.lock();
        try {
            long totalMemory = 2 * 1024 * 1024; // 2 MB
            long recordSize = Long.BYTES + Integer.BYTES + Double.BYTES;
            int maxRecords = (int) (totalMemory / recordSize);

            if (numRecords > maxRecords) {
                System.err.println("Warning: Reducing number of records to fit within memory limit");
                numRecords = maxRecords;
            }

            long[] offsets = new long[numRecords];
            int[] keys = new int[numRecords];
            Record[] records = new Record[numRecords];

            for (int i = 0; i < numRecords; i++) {
                offsets[i] = i * recordSize;
                keys[i] = i + 1;
                records[i] = new Record(offsets[i], keys[i], Math.random() * 100);
            }

            displayRecords(records);
        } catch (Exception e) {
            System.err.println("Memory allocation failed: " + e.getMessage());
        } finally {
            lock.unlock();
        }
    }

    private static void displayRecords(Record[] records) {
        Map<Integer, Record> recordMap = new HashMap<>();
        for (Record record : records) {
            recordMap.put(record.key, record);
        }

