#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_PACKET_SIZE 1500
#define INITIAL_CACHE_CAPACITY 100

typedef struct {
    time_t timestamp;
    size_t packet_size;
    void *packet_data; // Pointer to actual data
} Packet;

typedef struct {
    Packet **packets;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    int packets_received;
    int packets_dropped;
    size_t retention_duration;
    time_t last_flush_time;
} PacketCache;

PacketCache *init_packet_cache(size_t capacity, size_t retention_duration) {
    PacketCache *cache = malloc(sizeof(PacketCache));
    cache->packets = malloc(capacity * sizeof(Packet*));
    cache->capacity = capacity;
    cache->count = 0;
    pthread_mutex_init(&cache->lock, NULL);
    cache->packets_received = 0;
    cache->packets_dropped = 0;
    cache->retention_duration = retention_duration;
    cache->last_flush_time = time(NULL);

    return cache;
}

void flush_packet_cache(PacketCache *cache) {
    pthread_mutex_lock(&cache->lock);
    time_t current_time = time(NULL);

    // Remove old packets
    for (size_t i = 0; i < cache->count; ++i) {
        if ((current_time - cache->packets[i]->timestamp) > cache->retention_duration) {
            free(cache->packets[i]->packet_data);
            free(cache->packets[i]);
            memmove(&cache->packets[i], &cache->packets[i + 1],
                    (cache->count - i - 1) * sizeof(Packet*));
            --cache->count;
            --i;
        }
    }

    pthread_mutex_unlock(&cache->lock);
}

int validate_packet(void *data, size_t data_size) {
    // Implement packet validation logic
    return data_size <= MAX_PACKET_SIZE && data != NULL;
}

void log_packet_details(const Packet *packet, const char *source_ip, const char *dest_ip, int error_code) {
    printf("Packet: %s -> %s | Size: %zu | Error Code: %d\n", source_ip, dest_ip, packet->packet_size, error_code);
}

int add_packet_to_cache(PacketCache *cache, void *data, size_t data_size, const char *source_ip, const char *dest_ip) {
    if (!validate_packet(data, data_size)) {
        log_packet_details(NULL, source_ip, dest_ip, 1); // Error code for invalid packet
        ++(cache->packets_dropped);
        return -1;
    }

    pthread_mutex_lock(&cache->lock);

    if (cache->count >= cache->capacity) {
        flush_packet_cache(cache);
        if (cache->count >= cache->capacity) {
            log_packet_details(NULL, source_ip, dest_ip, 2); // Error code for overflow
            ++(cache->packets_dropped);
            pthread_mutex_unlock(&cache->lock);
            return -1;
        }
    }

    Packet *packet = malloc(sizeof(Packet));
    packet->timestamp = time(NULL);
    packet->packet_size = data_size;
    packet->packet_data = malloc(data_size);

    memcpy(packet->packet_data, data, data_size);

    cache->packets[cache->count++] = packet;
    ++(cache->packets_received);

    log_packet_details(packet, source_ip, dest_ip, 0); // No error

    pthread_mutex_unlock(&cache->lock);
    return 0;
}

void free_packet_cache(PacketCache *cache) {
    for (size_t i = 0; i < cache->count; ++i) {
        free(cache->packets[i]->packet_data);
        free(cache->packets[i]);
    }
    free(cache->packets);
    pthread_mutex_destroy(&cache->lock);
    free(cache);
}

int main() {
    PacketCache *cache = init_packet_cache(INITIAL_CACHE_CAPACITY, 300); // Retention for 5 minutes

    // Simulate adding packets
    char data[] = "Example packet data";
    add_packet_to_cache(cache, data, sizeof(data), "192.168.1.1", "192.168.1.2");

    // Periodically flush cache (could be in a separate thread or timer)
    while (1) {
        sleep(60);  // Flush every minute
        flush_packet_cache(cache);
    }

    free_packet_cache(cache);
    return 0;
}
