            packets[i].packet_size = rand() % 1024 + 1; // Random size between 1 and 1024 bytes
            packets[i].packet_data = malloc(packets[i].packet_size);

            if (!packets[i].packet_data) {
                log_message("Memory allocation failed for packet data.");
                --i;
                continue;
            }

            memset(packets[i].packet_data, rand() % 256, packets[i].packet_size); // Fill with random bytes
        }

        validate_and_process_packets(packets, record_count);

        free_resources_for_packets(packets, record_count);

        pthread_mutex_unlock(&mutex);
    }
}

void log_message(const char* message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        time_t current_time = time(NULL);
        fprintf(log_file, "[%ld] %s\n", (long)current_time, message);
        fclose(log_file);
    }
}

int read_config_file(const char* filename, int* range_start, int* range_end, size_t* record_count) {
    FILE *file = fopen(filename, "r");
    if (!file) return 1;

    fscanf(file, "%d %d %zu", range_start, range_end, record_count);
    fclose(file);

    return 0;
}

void initialize_packet_array(size_t initial_size) {
    pthread_mutex_lock(&mutex);

    packet_array = malloc(sizeof(NetworkPacket) * initial_size);
    if (!packet_array) {
        log_message("Memory allocation failed for initializing packet array.");
        pthread_exit(NULL);
    }

    packet_array_size = initial_size;
    num_packets = 0;

    pthread_mutex_unlock(&mutex);
}

void resize_packet_array() {
    size_t new_size = packet_array_size * 2;

    if (new_size > MAX_MEMORY_THRESHOLD / sizeof(NetworkPacket)) {
        log_message("Memory usage threshold exceeded.");
        return;
    }

    NetworkPacket *new_array = realloc(packet_array, sizeof(NetworkPacket) * new_size);
    if (!new_array) {
        log_message("Failed to resize packet array.");
        return;
    }

    pthread_mutex_lock(&mutex);
    packet_array = new_array;
    packet_array_size = new_size;
    pthread_mutex_unlock(&mutex);
}

void validate_and_process_packets(NetworkPacket *packets, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (!packets[i].packet_data || packets[i].packet_size == 0) {
            log_message("Invalid packet encountered.");
            error_count++;
            continue;
        }

        // Process packet
        total_packets_processed++;

        pthread_mutex_lock(&mutex);
        if (num_packets < packet_array_size) {
            packet_array[num_packets++] = packets[i];
        }
        pthread_mutex_unlock(&mutex);

        free(packets[i].packet_data);  // Free individual packet data after processing
    }

    log_message("Packets processed successfully.");
}

void free_resources_for_packets(NetworkPacket *packets, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (packets[i].packet_data) {
            free(packets[i].packet_data);
        }
    }
    free(packets);
}

void free_resources() {
    pthread_mutex_lock(&mutex);

    if (packet_array) free(packet_array);
    if (offset_values) free(offset_values);
    if (keys) free(keys);
    if (records) free(records);

    packet_array = NULL;
    offset_values = NULL;
    keys = NULL;
    records = NULL;

    pthread_mutex_unlock(&mutex);
}

int main() {
    const char* config_file = "config.txt";

    manage_network_packets(config_file);

    free_resources();

    return 0;
}
