typedef void (*resource_management_func)(void);

int process_json_config(const char *json_file_path,
                        log_func logger, 
                        network_setup_func setup_network, 
                        resource_management_func manage_resources) {

    if (!logger || !setup_network || !manage_resources) return -1;

    json_error_t error;
    json_t *root = json_load_file(json_file_path, 0, &error);
    if (!root) {
        logger("Failed to load JSON file.");
        return -1;
    }

    // Parse and validate fields
    const char *service_name = json_string_value(json_object_get(root, "service_name"));
    if (!service_name || strlen(service_name) == 0) {
        logger("Invalid or missing service_name.");
        goto cleanup;
    }

    const char *host_ip = json_string_value(json_object_get(root, "host_ip"));
    struct in_addr ipv4_addr;
    struct in6_addr ipv6_addr;
    if (!inet_pton(AF_INET, host_ip, &ipv4_addr) && !inet_pton(AF_INET6, host_ip, &ipv6_addr)) {
        logger("Invalid IP address.");
        goto cleanup;
    }

    int port = json_integer_value(json_object_get(root, "port"));
    if (port <= 0) {
        logger("Port must be a positive integer.");
        goto cleanup;
    }

    int max_connections = json_is_integer(json_object_get(root, "max_connections")) ?
                          json_integer_value(json_object_get(root, "max_connections")) : 1024;

    int log_rotation_size = json_is_integer(json_object_get(root, "log_rotation_size")) ?
                            json_integer_value(json_object_get(root, "log_rotation_size")) : 10485760; // Default to 10MB

    if (log_rotation_size < 0) {
        logger("Log rotation size must be non-negative.");
        goto cleanup;
    }

    const char *log_directory = json_string_value(json_object_get(root, "log_directory"));
    if (!validate_log_directory(log_directory)) {
        logger("Invalid log directory path.");
        goto cleanup;
    }

    // Dependency injections
    setup_network();
    manage_resources();

    // Allocate memory for config records and initialize default values
    size_t num_records = 1; // Change as necessary for multiple records
    config_record *records = malloc(num_records * sizeof(config_record));
    if (!records) {
        logger("Memory allocation failed.");
        goto cleanup;
    }

    records[0] = (config_record){.service_name = strdup(service_name), .ip_address = strdup(host_ip), .port = port};

    // Allocate memory for connections and set default values
    size_t num_connections = 100; // Adjust as necessary
    connection *connections = malloc(num_connections * sizeof(connection));
    if (!connections) {
        logger("Memory allocation failed.");
        free(records);
        goto cleanup;
    }

    for (size_t i = 0; i < num_connections; ++i) {
        connections[i] = (connection){.status = 0, .last_activity_time = time(NULL), .current_load = 0};
    }

    // Log success
    logger("Configuration processed successfully.");

cleanup:
    json_decref(root);
    free(records[0].service_name);
    free(records[0].ip_address);
    free(records);
    free(connections);

    return (root != NULL) ? 0 : -1;
}

// Helper function to validate log directory paths
int validate_log_directory(const char *path) {
    struct stat sb;

    // Ensure path is not null and does not refer to special files or directories like /, /dev, etc.
    if (!path || strcmp(path, "/") == 0 || strncmp(path, "/dev", 4) == 0) return 0;

    if (stat(path, &sb) != 0) {
        // Directory does not exist
        return mkdir(path, 0755) != 0;
    }

    return S_ISDIR(sb.st_mode);
}

