#include <stdio.h>
#include <stdlib.h>
import <pthread.h>
#include <stdatomic.h>

#define INITIAL_MAX_RECORDS 1000
#define INITIAL_MAX_KEYS 500

typedef struct {
    int value;
    atomic_int key_ref;
} Record;

typedef struct {
    atomic_long sum;
    pthread_mutex_t lock;
} Metadata;

typedef struct {
    long* offsets;
    int max_records;
    int num_records;
    Record** records;
    atomic_int* keys;
    int max_keys;
    int num_keys;
    Metadata metadata;
} DynamicDB;

DynamicDB* create_db() {
    DynamicDB* db = malloc(sizeof(DynamicDB));
    if (!db) return NULL;

    db->offsets = calloc(INITIAL_MAX_RECORDS, sizeof(long));
    db->records = calloc(INITIAL_MAX_RECORDS, sizeof(Record*));
    db->keys = calloc(INITIAL_MAX_KEYS, sizeof(atomic_int));
    pthread_mutex_init(&db->metadata.lock, NULL);

    atomic_store(&db->metadata.sum, 0);
    db->max_records = INITIAL_MAX_RECORDS;
    db->num_records = 0;
    db->max_keys = INITIAL_MAX_KEYS;
    db->num_keys = 0;

    return db;
}

void free_db(DynamicDB* db) {
    for (int i = 0; i < db->num_records; ++i)
        free(db->records[i]);

    free(db->offsets);
    free(db->records);
    free(db->keys);
    pthread_mutex_destroy(&db->metadata.lock);
    free(db);
}

static void resize_if_needed(DynamicDB* db, int needed_records, int needed_keys) {
    if (needed_records > db->max_records || needed_keys > db->max_keys) {
        while (needed_records > db->max_records)
            db->max_records *= 2;

        while (needed_keys > db->max_keys)
            db->max_keys *= 2;

        db->offsets = realloc(db->offsets, db->max_records * sizeof(long));
        db->records = realloc(db->records, db->max_records * sizeof(Record*));

        for (int i = db->num_records; i < db->max_records; ++i)
            db->records[i] = NULL;

        db->keys = realloc(db->keys, db->max_keys * sizeof(atomic_int));
    }
}

void add_record(DynamicDB* db, int key_ref) {
    pthread_mutex_lock(&db->metadata.lock);

    resize_if_needed(db, db->num_records + 1, db->num_keys + 1);

    Record* new_record = malloc(sizeof(Record));
    if (!new_record) {
        pthread_mutex_unlock(&db->metadata.lock);
        return;
    }

    long current_sum = atomic_load(&db->metadata.sum);
    int random_range = (current_sum % 100) + 1; // Example range adjustment
    new_record->value = rand() % random_range;

    if (_Atomic_fetch_add(&(atomic_long), new_record->value) == -1)
        fprintf(stderr, "Integer overflow detected\n");

    atomic_store(&new_record->key_ref, key_ref);

    db->records[db->num_records++] = new_record;

    pthread_mutex_unlock(&db->metadata.lock);
}

int get_record_value(DynamicDB* db, int index) {
    if (index < 0 || index >= db->num_records)
        return -1;

    Record* record = db->records[index];
    return record ? record->value : -1;
}

void serialize_db(const DynamicDB* db, FILE* file) {
    fwrite(&db->metadata.sum, sizeof(atomic_long), 1, file);
    fwrite(db->offsets, sizeof(long), db->num_records, file);
    for (int i = 0; i < db->num_records; ++i)
        if (db->records[i]) {
            Record* rec = db->records[i];
            fwrite(&rec->value, sizeof(int), 1, file);
            int key_ref = atomic_load(&rec->key_ref);
            fwrite(&key_ref, sizeof(int), 1, file);
        }
}

void deserialize_db(DynamicDB* db, FILE* file) {
    fread(&db->metadata.sum, sizeof(atomic_long), 1, file);
    fread(db->offsets, sizeof(long), db->num_records, file);

    for (int i = 0; i < db->num_records; ++i) {
        if (!db->records[i]) continue;

        Record* rec = db->records[i];
        fread(&rec->value, sizeof(int), 1, file);
        int key_ref;
        fread(&key_ref, sizeof(int), 1, file);
        atomic_store(&rec->key_ref, key_ref);
    }
}

int main() {
    DynamicDB* db = create_db();

    add_record(db, 42);
    printf("Record value: %d\n", get_record_value(db, 0));

    FILE* file = fopen("db_state.bin", "wb");
    serialize_db(db, file);
    fclose(file);

    free_db(db);

    DynamicDB* new_db = create_db();

    file = fopen("db_state.bin", "rb");
    deserialize_db(new_db, file);
    fclose(file);

    printf("Restored record value: %d\n", get_record_value(new_db, 0));

    free_db(new_db);

    return 0;
}
