    size_t max_records;
    size_t current_count;
    size_t total_value;

    record_t **records;
    size_t index;
    pool_node_t *free_list_head;
    pool_node_t *memory_blocks;
} record_pool_t;

// Global variables
record_pool_t global_pool = {0};
pthread_mutex_t config_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_pool(size_t max_records) {
    pthread_mutex_lock(&config_lock);

    // Initialize the free list and memory blocks
    size_t num_blocks = (max_records * RECORD_SIZE + BLOCK_SIZE - 1) / BLOCK_SIZE;
    global_pool.memory_blocks = malloc(num_blocks * sizeof(pool_node_t));
    for (size_t i = 0; i < num_blocks - 1; ++i) {
        ((pool_node_t *)global_pool.memory_blocks)[i].next = &((pool_node_t *)global_pool.memory_blocks)[i + 1];
    }
    ((pool_node_t *)global_pool.memory_blocks)[num_blocks - 1].next = NULL;

    global_pool.free_list_head = (pool_node_t *)global_pool.memory_blocks;
    global_pool.max_records = max_records;
    global_pool.current_count = 0;
    global_pool.total_value = 0;
    global_pool.records = malloc(max_records * sizeof(record_t *));

    pthread_mutex_init(&global_pool.lock, NULL);
    pthread_cond_init(&global_pool.cond, NULL);

    pthread_mutex_unlock(&config_lock);
}

void* allocate_record() {
    pthread_mutex_lock(&global_pool.lock);

    while (global_pool.free_list_head == NULL) {
        // Wait for memory to be freed
        pthread_cond_wait(&global_pool.cond, &global_pool.lock);
    }

    pool_node_t *node = global_pool.free_list_head;
    global_pool.free_list_head = node->next;

    pthread_mutex_unlock(&global_pool.lock);

    return (void *)((uint8_t *)node + sizeof(pool_node_t));
}

void free_record(void *ptr) {
    pthread_mutex_lock(&global_pool.lock);

    pool_node_t *node = ((pool_node_t *)((uint8_t *)ptr - sizeof(pool_node_t)));
    node->next = global_pool.free_list_head;
    global_pool.free_list_head = node;

    pthread_cond_signal(&global_pool.cond);
    pthread_mutex_unlock(&global_pool.lock);
}

void update_record(record_t *record, int new_value) {
    uint64_t old_total = (uint64_t)global_pool.total_value;
    uint64_t new_total = old_total - record->value + new_value;

    if ((new_total < old_total && record->value > 0) || 
        (new_total > old_total && record->value < 0)) {
        // Handle integer overflow case
        printf("Integer overflow detected\n");
        return;
    }

    pthread_mutex_lock(&global_pool.lock);

    global_pool.total_value = new_total;
    record->value = new_value;
    record->timestamp = time(NULL);

    pthread_mutex_unlock(&global_pool.lock);
}

void add_record(int *key) {
    if (pthread_mutex_trylock(&global_pool.lock) != 0) {
        // Try again later or handle contention
        return;
    }

    if (global_pool.current_count >= global_pool.max_records) {
        pthread_mutex_unlock(&global_pool.lock);
        return; // Pool is full, apply LRU eviction logic here if needed
    }

    record_t *record = allocate_record();
    record->key = key;
    record->value = 0; // Initialize value to zero or some default

    size_t index = global_pool.current_count++;
    global_pool.records[index] = record;

    update_record(record, record->value);

    pthread_mutex_unlock(&global_pool.lock);
}

void cleanup_pool() {
    pthread_mutex_lock(&config_lock);

    for (size_t i = 0; i < global_pool.current_count; ++i) {
        free_record(global_pool.records[i]);
    }
    free(global_pool.memory_blocks);
    free(global_pool.records);

    pthread_mutex_unlock(&config_lock);
}

int main() {
    initialize_pool(100); // Example: Initialize with a maximum of 100 records

    int key = 42;
    add_record(&key);

    cleanup_pool();

    return 0;
}
