void initializeMemoryPool(MemoryPool *pool, int initialBlocks) {
    pool->freeList = NULL;
    pthread_mutex_init(&pool->mutex, NULL);

    for (int i = 0; i < initialBlocks; ++i) {
        void *memory = malloc(BLOCK_SIZE);
        if (memory) {
            MemoryBlock *block = (MemoryBlock *)malloc(sizeof(MemoryBlock));
            block->memory = memory;
            block->size = BLOCK_SIZE;
            block->next = pool->freeList;
            pool->freeList = block;
        }
    }
}

MemoryBlock* allocateFromPool(MemoryPool *pool, size_t size) {
    pthread_mutex_lock(&pool->mutex);
    MemoryBlock *current = pool->freeList;

    while (current != NULL) {
        if (current->size >= size) {
            pool->freeList = current->next;
            pthread_mutex_unlock(&pool->mutex);
            return (MemoryBlock *)current->memory;
        }
        current = current->next;
    }

    void *memory = malloc(size);
    MemoryBlock *block = (MemoryBlock *)malloc(sizeof(MemoryBlock));
    block->memory = memory;
    block->size = size;
    pthread_mutex_unlock(&pool->mutex);

    return block;
}

void freeToPool(MemoryPool *pool, void *memory, size_t size) {
    pthread_mutex_lock(&pool->mutex);
    MemoryBlock *block = (MemoryBlock *)malloc(sizeof(MemoryBlock));
    block->memory = memory;
    block->size = size;
    block->next = pool->freeList;
    pool->freeList = block;
    pthread_mutex_unlock(&pool->mutex);
}

