#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <ctype.h>

// Function to generate a unique filename based on an input filename.
char* generate_unique_filename(const char *input_filename, const char *file_type) {
    if (!input_filename || !file_type) return "Error";

    // Constants
    const int MAX_FILENAME_LENGTH = 256;
    const int MAX_TRUNCATED_LENGTH = 128;

    // Truncate input filename to MAX_TRUNCATED_LENGTH
    size_t input_length = strlen(input_filename);
    char *base_name = (input_length > MAX_TRUNCATED_LENGTH) ? 
                      strndup(input_filename, MAX_TRUNCATED_LENGTH) : strdup(input_filename);

    if (!base_name) return "Error";

    // Check for existing file type at the end of the filename
    const char *ext_pos = strrchr(base_name, '.');
    int has_ext = ext_pos && strcmp(ext_pos, file_type) != 0;

    // Extract version number or initialize it
    int version_number = 1;
    if (strcasestr(base_name, "v")) {
        char *version_str = strcasestr(base_name, "v");
        char num_str[10];
        int i = 0;

        while (isdigit(version_str[i + 2])) { // Skip 'v'
            num_str[i] = version_str[i + 2];
            ++i;
        }
        num_str[i] = '\0';
        if (num_str[0]) {
            version_number = atoi(num_str) + 1;
        }
    }

    // Generate timestamp
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[15];
    snprintf(timestamp, sizeof(timestamp), "%04d%02d%02d%02d%02d%02d", 
             t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
             t->tm_hour, t->tm_min, t->tm_sec);

    // Create a unique filename
    char unique_filename[MAX_FILENAME_LENGTH];
    snprintf(unique_filename, sizeof(unique_filename), "%s_v%d_%s", 
             base_name, version_number, timestamp);

    // Append file type if needed
    if (has_ext) {
        strncat(unique_filename, ".", MAX_FILENAME_LENGTH - strlen(unique_filename) - 1);
        strncat(unique_filename, file_type, MAX_FILENAME_LENGTH - strlen(unique_filename) - 1);
    }

    // Ensure the filename does not exceed maximum length
    int len = strlen(unique_filename);
    if (len > MAX_FILENAME_LENGTH - 1) {
        unique_filename[MAX_FILENAME_LENGTH - 1] = '\0';
    }

    char *result = strdup(unique_filename);
    free(base_name);

    return result ? result : "Error";
}
```

### Notes:
- The function handles spaces and special characters in the filename by not modifying them.
- It checks for an existing versioning scheme, increments it if present, or initializes from 1 otherwise.
- The timestamp is generated in `YYYYMMDDHHMMSS` format.
- If the original filename has a different extension than provided, it appends the correct one without duplication.
- Error handling ensures that null inputs and memory allocation failures return `"Error"`.
- Truncation and length checks prevent buffer overflow issues.']

