#include "external_memory_manager.h"
#include "logging_framework.h"

#define MAX_MEMORY_USAGE 1024 * 1024 // Example max memory usage limit in bytes

typedef struct {
    int value;
    int* key_ref;
} record;

void dynamic_record_management(int num_records, int min_range, int max_range) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    int current_memory_usage = 0;
    record* records = NULL;

    // Memory for the keys
    int* keys = (int*)external_malloc(num_records * sizeof(int));
    if (!keys) {
        logging_log("Failed to allocate memory for keys");
        return;
    }

    pthread_mutex_lock(&lock);
    current_memory_usage += num_records * sizeof(int);

    records = (record*)external_calloc(num_records, sizeof(record));
    if (!records) {
        external_free(keys);
        logging_log("Failed to allocate memory for records");
        return;
    }

    current_memory_usage += num_records * sizeof(record);

    // Check initial memory usage
    if (current_memory_usage > MAX_MEMORY_USAGE) {
        external_free(records);
        external_free(keys);
        pthread_mutex_unlock(&lock);
        logging_log("Exceeded maximum allowed memory usage during initialization");
        return;
    }

    int cumulative_sum = 0;

    for (int i = 0; i < num_records; ++i) {
        // Randomly initialize key
        keys[i] = rand() % (max_range - min_range + 1) + min_range;

        // Custom overflow detection
        long temp_cumulative = cumulative_sum;
        if ((temp_cumulative > INT_MAX - keys[i]) || (temp_cumulative < INT_MIN - keys[i])) {
            logging_log("Overflow detected in cumulative sum calculation");
            continue; // Skip this iteration on overflow
        }
        cumulative_sum += keys[i];

        // Adjust range based on cumulative sum
        int adjusted_min = min_range + (cumulative_sum % 10);
        int adjusted_max = max_range - (cumulative_sum % 10);

        // Initialize record value with random value within the adjusted range
        records[i].value = rand() % (adjusted_max - adjusted_min + 1) + adjusted_min;

        // Reference to key
        records[i].key_ref = &keys[i];

        // Real-time memory monitoring
        current_memory_usage += sizeof(int); // Added for each key reference storage
        if (current_memory_usage > MAX_MEMORY_USAGE) {
            external_free(records);
            external_free(keys);
            pthread_mutex_unlock(&lock);
            logging_log("Exceeded maximum allowed memory usage during processing");
            return;
        }
    }

    // Logging the final state of records
    for (int i = 0; i < num_records; ++i) {
        char log_message[256];
        snprintf(log_message, sizeof(log_message), "Record %d: value=%d, key_ref=%p", 
                 i, records[i].value, (void*)records[i].key_ref);
        logging_log(log_message);
    }

    // Clean up
    external_free(records);
    external_free(keys);

    pthread_mutex_unlock(&lock);
}
