#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>

#define MEMORY_POOL_SIZE 1024 // Size of the memory pool in bytes.
#define RECORD_SIZE sizeof(Record) // Assuming size is calculated based on defined structures.
#define MAX_RECORDS (MEMORY_POOL_SIZE / RECORD_SIZE)

typedef enum {
    MODE_A,
    MODE_B
} OperationalMode;

typedef struct {
    float floatValue;
    int intValue;
    _Bool boolValue;
} CustomStructure;

typedef struct {
    double start;
    double end;
} TimeInterval;

typedef struct Record {
    int value;
    int *keyRef;
    time_t timestamp;
    double floatingPointNumber;
    char string[256];
    CustomStructure customData;
    TimeInterval interval;
    OperationalMode mode;
    struct Record *next; // For LRU eviction list.
} Record;

Record *memoryPool = NULL;
pthread_mutex_t poolMutex = PTHREAD_MUTEX_INITIALIZER;
Record *freeListHead = NULL;
size_t freeListSize = 0;
Record **lruTail = NULL;
size_t recordCount = 0;

void initMemoryPool() {
    memoryPool = (Record *)malloc(MEMORY_POOL_SIZE);
    if (!memoryPool) {
        perror("Failed to allocate memory pool");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        Record *record = (Record *)(memoryPool + i * RECORD_SIZE);
        record->next = freeListHead;
        freeListHead = record;
    }
    freeListSize = MAX_RECORDS;
}

void *allocateRecord() {
    pthread_mutex_lock(&poolMutex);

    if (!freeListHead) {
        fprintf(stderr, "Out of memory\n");
        pthread_mutex_unlock(&poolMutex);
        return NULL;
    }

    Record *record = freeListHead;
    freeListHead = record->next;
    --freeListSize;

    // Initialize the new record
    memset(record, 0, RECORD_SIZE);

    pthread_mutex_unlock(&poolMutex);
    return record;
}

void deallocateRecord(Record *record) {
    pthread_mutex_lock(&poolMutex);

    record->next = freeListHead;
    freeListHead = record;
    ++freeListSize;

    // Add to LRU list
    if (*lruTail) {
        (*lruTail)->next = record;
    }
    *lruTail = record;

    pthread_mutex_unlock(&poolMutex);
}

Record *getLRURecord() {
    pthread_mutex_lock(&poolMutex);

    Record *record = freeListHead; // LRU is the first in the list
    if (!record) {
        pthread_mutex_unlock(&poolMutex);
        return NULL;
    }

    freeListHead = record->next;
    --freeListSize;

    pthread_mutex_unlock(&poolMutex);
    return record;
}

void processRecord(Record *record, double newValue) {
    // Example operation on floating-point number
    record->floatingPointNumber += newValue;

    // String manipulation example
    snprintf(record->string, sizeof(record->string), "Processed at %ld", time(NULL));

    // Simulate sensor data or environment input for the custom structure
    record->customData.floatValue = (float)rand() / RAND_MAX;
    record->customData.intValue = rand();
    record->customData.boolValue = rand() % 2;

    // Example arithmetic on TimeInterval
    record->interval.start += 0.1;
    record->interval.end -= 0.1;
}

void updateRecord(int key, double newValue) {
    pthread_mutex_lock(&poolMutex);

    for (size_t i = 0; i < MAX_RECORDS && freeListSize + recordCount > 0; ++i) {
        Record *record = (Record *)(memoryPool + i * RECORD_SIZE);

        if (record->keyRef == &key) {
            processRecord(record, newValue);
            pthread_mutex_unlock(&poolMutex);
            return;
        }
    }

    // If the record is not found and free list is exhausted
    if (!freeListHead && freeListSize < MAX_RECORDS) {
        Record *newRecord = getLRURecord();
        newRecord->keyRef = &key; // Assign key reference
        processRecord(newRecord, newValue);
    }

    pthread_mutex_unlock(&poolMutex);
}

void cleanup() {
    if (memoryPool) {
        free(memoryPool);
        memoryPool = NULL;
    }
}

int main() {
    initMemoryPool();

    int sampleKey = 1;

    // Example thread function
    void *threadFunc(void *arg) {
        updateRecord(*(int *)arg, 1.23);
        return NULL;
    }

    pthread_t threads[4];
    for (size_t i = 0; i < sizeof(threads) / sizeof(pthread_t); ++i) {
        if (pthread_create(&threads[i], NULL, threadFunc, &sampleKey)) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }

    for (size_t i = 0; i < sizeof(threads) / sizeof(pthread_t); ++i) {
        pthread_join(threads[i], NULL);
    }

    cleanup();
    return 0;
}
