    LogLevel level;
    Message *message;
} LogEntry;

typedef struct {
    LogEntry **entries;
    size_t capacity;
    size_t count;
    size_t total_size;
    pthread_mutex_t lock;
} LogManager;

LogManager* create_log_manager(size_t initial_capacity) {
    LogManager *manager = malloc(sizeof(LogManager));
    manager->entries = calloc(initial_capacity, sizeof(LogEntry *));
    manager->capacity = initial_capacity;
    manager->count = 0;
    manager->total_size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

uint64_t generate_unique_id() {
    time_t now = time(NULL);
    struct timespec spec;
    clock_gettime(CLOCK_REALTIME, &spec);
    return (uint64_t)now * 1000000000 + spec.tv_nsec;
}

void resize_log_manager(LogManager *manager);

LogEntry* create_log_entry(LogLevel level, Message *message) {
    LogEntry *entry = malloc(sizeof(LogEntry));
    entry->id = generate_unique_id();
    entry->timestamp = time(NULL);
    entry->level = level;
    entry->message = message;
    return entry;
}

void add_log_entry(LogManager *manager, LogLevel level, Message *message) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        resize_log_manager(manager);
    }

    LogEntry *entry = create_log_entry(level, message);
    manager->entries[manager->count++] = entry;
    manager->total_size += sizeof(LogEntry); // Simplified size estimation

    pthread_mutex_unlock(&manager->lock);
}

void resize_log_manager(LogManager *manager) {
    size_t new_capacity = manager->capacity * 2;
    LogEntry **new_entries = realloc(manager->entries, new_capacity * sizeof(LogEntry *));
    if (new_entries) {
        memset(new_entries + manager->capacity, 0, manager->capacity * sizeof(LogEntry *));
        manager->entries = new_entries;
        manager->capacity = new_capacity;
    }
}

void free_log_manager(LogManager *manager) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->entries[i]->message->message);
        free(manager->entries[i]);
    }
    free(manager->entries);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void filter_and_retrieve_logs(LogManager *manager, LogLevel level, time_t start_time, time_t end_time) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        LogEntry *entry = manager->entries[i];
        if (entry->level == level && entry->timestamp >= start_time && entry->timestamp <= end_time) {
            printf("Log ID: %llu, Level: %d, Timestamp: %ld\n", entry->id, entry->level, entry->timestamp);
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

int main() {
    LogManager *log_manager = create_log_manager(10);

    Message msg1 = {.message = strdup("This is a debug message"), .source_file = "main.c", .line_number = 42};
    add_log_entry(log_manager, DEBUG, &msg1);

    time_t now = time(NULL);
    filter_and_retrieve_logs(log_manager, DEBUG, now - 3600, now);

    free_log_manager(log_manager);
    return 0;
}
```

This code sets up a basic logging system with thread safety and dynamic resizing. It includes mechanisms for creating log entries, filtering them by level and time, and managing memory efficiently. Adjustments may be needed based on specific application requirements or integration with external services.']

