// Memory pool for efficient memory management
#define MEMORY_POOL_SIZE 1024*1024 // 1MB example size
void *memory_pool[MEMORY_POOL_SIZE];
size_t free_index = 0;

unsigned char *allocate_from_memory_pool(size_t size) {
    if (free_index + size > MEMORY_POOL_SIZE) return NULL; // Pool exhausted
    unsigned char *ptr = &memory_pool[free_index];
    free_index += size;
    return ptr;
}

void reset_memory_pool() {
    free_index = 0;
}

// Function prototypes
Packet* init_dynamic_array(size_t initial_capacity);
void add_packet(Packet **array, size_t *capacity, Packet packet);
void process_packets(int network_interface);

// Initialize dynamic array of packets with an initial capacity
Packet* init_dynamic_array(size_t initial_capacity) {
    Packet *array = malloc(initial_capacity * sizeof(Packet));
    if (!array) return NULL;

    for (size_t i = 0; i < initial_capacity; ++i)
        array[i] = (Packet){ .timestamp = 0, .packet_size = 0, .data = NULL, .rnti_list = NULL, .rnti_count = 0 };

    return array;
}

// Add a packet to the dynamic array
void add_packet(Packet **array, size_t *capacity, Packet new_packet) {
    if (*array == NULL) {
        *capacity = 1;
        *array = init_dynamic_array(*capacity);
        if (!*array) return;
    }

    // Check if resizing is needed
    for (size_t i = 0; i < **capacity; ++i)
        if ((*array)[i].packet_size == 0) {
            (*array)[i] = new_packet;
            return;
        }

    size_t new_capacity = *capacity * 2;
    Packet *temp_array = realloc(*array, new_capacity * sizeof(Packet));
    if (!temp_array) return; // Handle allocation failure gracefully

    for (size_t i = **capacity; i < new_capacity; ++i)
        temp_array[i] = (Packet){ .timestamp = 0, .packet_size = 0, .data = NULL, .rnti_list = NULL, .rnti_count = 0 };

    *array = temp_array;
    *capacity = new_capacity;

    // Add the packet to the array
    for (size_t i = 0; i < new_capacity; ++i)
        if ((*array)[i].packet_size == 0) {
            (*array)[i] = new_packet;
            return;
        }
}

// Process packets over a network interface, validate and manage them
void process_packets(int network_interface) {
    Packet *packets = NULL;
    size_t capacity = 0;

    while (1) { // Simulated loop for receiving packets
        unsigned char packet_data[1024]; // Example fixed buffer size
        int received_size; // Assume this is set by a function call to receive data from the network

        if (received_size <= 0) continue; // No valid packet

        Packet new_packet = {
            .timestamp = time(NULL),
            .packet_size = received_size,
            .data = allocate_from_memory_pool(received_size)
        };

        if (!new_packet.data) { // Handle allocation failure
            fprintf(stderr, "Failed to allocate memory for packet data\n");
            continue;
        }

        memcpy(new_packet.data, packet_data, received_size);

        // Example: Set RNTI list and count (simulated with fixed values here)
        new_packet.rnti_list = malloc(10 * sizeof(int)); // Assume 10 RNTIs
        if (!new_packet.rnti_list) {
            fprintf(stderr, "Failed to allocate memory for RNTI list\n");
            continue;
        }
        new_packet.rnti_count = 10;

        add_packet(&packets, &capacity, new_packet);

        // Process and handle database operations here...
    }

    // Cleanup on shutdown
    if (packets) {
        for (size_t i = 0; i < capacity; ++i)
            free(packets[i].rnti_list);
        free(packets);
    }

    reset_memory_pool();
}

int main() {
    // Example call to process_packets
    pthread_t thread;
    if (pthread_create(&thread, NULL, (void *(*)(void *))process_packets, (void *)0)) {
