#include <iostream>
#include <vector>
#include <cstdlib>
#include <ctime>

struct record {
    float distance;
};

void selectAndExecuteAction() {
    const size_t maxHistory = 50;
    std::vector<std::pair<int*, long*>> commandHistory;

    // Initialize random seed
    srand(static_cast<unsigned int>(time(0)));

    // Define the number of objects, can be adjusted for testing or gameplay
    size_t numObjects = 100; 
    long* offsets = new (std::nothrow) long[numObjects];
    int* ids = new (std::nothrow) int[numObjects];
    record* distances = new (std::nothrow) record[numObjects];

    if (!offsets || !ids || !distances) {
        std::cerr << "Memory allocation failed." << std::endl;
        delete[] offsets; 
        delete[] ids; 
        delete[] distances; 
        return;
    }

    // Initialize arrays
    for (size_t i = 0; i < numObjects; ++i) {
        offsets[i] = rand() % 1000;  // Random offset value
        ids[i] = rand();             // Unique ID
        distances[i].distance = static_cast<float>(rand() % 100) / 10.0f;  // Example distance
    }

    std::vector<size_t> activeObjects;

    for (size_t i = 0; i < numObjects; ++i) {
        if (rand() % 2 == 0) {  // Randomly decide to add object
            activeObjects.push_back(i);
        }
    }

    auto executeAction = [&]() {
        std::pair<int*, long*> action;

        for (size_t i : activeObjects) {
            int* idPtr = &ids[i];
            long* offsetPtr = &offsets[i];

            // Simulate some operation on each object
            offsets[i] += rand() % 10; // Random modification of offsets

            // Save the current state to history
            action.first = idPtr;
            action.second = offsetPtr;
            if (commandHistory.size() == maxHistory) {
                delete[] commandHistory.front().first;
                delete[] commandHistory.front().second;
                commandHistory.erase(commandHistory.begin());
            }
            commandHistory.push_back(action);
        }

        std::cout << "Action executed with " << activeObjects.size() << " objects." << std::endl;
    };

    auto undoLastAction = [&]() {
        if (commandHistory.empty()) {
            std::cerr << "No actions to undo." << std::endl;
            return;
        }

        auto lastAction = commandHistory.back();
        for (size_t i : activeObjects) {
            *lastAction.first = ids[i];
            *lastAction.second = offsets[i];
        }

        commandHistory.pop_back();
        std::cout << "Last action undone." << std::endl;
    };

    // Example of executing an action
    executeAction();

    // Example of undoing the last action
    undoLastAction();

    // Cleanup
    for (auto& historyItem : commandHistory) {
        delete[] historyItem.first;
