#define BASE_DIR "/tmp/crc_dir"
#define MAX_RNTI 1024

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int get_crc_dir(char *buffer, size_t buffer_size) {
    const char *env_value = getenv("CRC_DIR");

    if (env_value && strlen(env_value) + 1 <= buffer_size) {
        strncpy(buffer, env_value, buffer_size);
        return 0;
    }

    srand(time(NULL));
    int attempts = 0;
    while (attempts < MAX_RNTI) {
        snprintf(buffer, buffer_size, "%s_%d", BASE_DIR, rand());
        if (mkdir(buffer, S_IRWXU) == 0 || (errno != EEXIST && errno != EACCES)) {
            if (setenv("CRC_DIR", buffer, 1) == 0) {
                return 0;
            }
        }
        attempts++;
    }

    return -1;
}

int generate_nfa_list(NFAPI_CRC_INDICATION_PDU_T **nfa_list, size_t n_elements) {
    if (n_elements <= 0 || !nfa_list) return -1;

    *nfa_list = malloc(n_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*nfa_list) return -2;

    uint16_t rnti_set[MAX_RNTI] = {0};
    int count_rnti = 0;

    for (size_t i = 0; i < n_elements; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &(*nfa_list)[i];

        pdu->RX_UE_INFORMATION_TAG = rand();
        do {
            pdu->RNTI = rand() % MAX_RNTI;
        } while (rnti_set[pdu->RNTI]);

        rnti_set[pdu->RNTI] = 1;
        count_rnti++;

        pdu->CRC_INDICATION_REL8_TAG = rand();
        pdu->CRCFLAG = rand() & 0x01;

        if (count_rnti >= MAX_RNTI) break;
    }

    return 0;
}

int main() {
    size_t n_elements = 10;
    NFAPI_CRC_INDICATION_PDU_T *nfa_list;

    char crc_dir_path[256];
    if (get_crc_dir(crc_dir_path, sizeof(crc_dir_path)) != 0) {
        fprintf(stderr, "Failed to get or create CRC directory\n");
        return -1;
    }

    printf("CRC Directory: %s\n", crc_dir_path);

    if (generate_nfa_list(&nfa_list, n_elements) != 0) {
        fprintf(stderr, "Failed to generate NFA list\n");
        return -2;
    }

    for (size_t i = 0; i < n_elements; ++i) {
        printf("RX_UE_INFORMATION_TAG: %u, RNTI: %hu, CRC_INDICATION_REL8_TAG: %hhu, CRCFLAG: %hhu\n",
               nfa_list[i].RX_UE_INFORMATION_TAG, nfa_list[i].RNTI,
               nfa_list[i].CRC_INDICATION_REL8_TAG, nfa_list[i].CRCFLAG);
    }

    free(nfa_list);
    return 0;
}
