#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <arpa/inet.h>

typedef struct {
    char source_ip[16];
    char destination_ip[16];
    int status;
} NetworkConnectionRecord;

bool is_valid_ipv4(const char *ip) {
    struct sockaddr_in sa;
    return inet_pton(AF_INET, ip, &(sa.sin_addr)) != 0;
}

int count_unique_ips(NetworkConnectionRecord *records, size_t record_count) {
    // Use a simple hash set approach for unique IP addresses
    const int hash_table_size = 1024;
    char hash_table[hash_table_size][16] = {0};
    int ip_count = 0;

    for (size_t i = 0; i < record_count; ++i) {
        bool source_added = false, dest_added = false;

        // Hash and add source IP
        unsigned int hash_source = 5381;
        const char *src_ip = records[i].source_ip;
        while (*src_ip) {
            hash_source = ((hash_source << 5) + hash_source) + (unsigned char)(*src_ip++);
        }
        int index_source = hash_source % hash_table_size;

        if (strcmp(hash_table[index_source], "") == 0) {
            strcpy(hash_table[index_source], records[i].source_ip);
            ip_count++;
            source_added = true;
        }

        // Hash and add destination IP
        unsigned int hash_dest = 5381;
        const char *dest_ip = records[i].destination_ip;
        while (*dest_ip) {
            hash_dest = ((hash_dest << 5) + hash_dest) + (unsigned char)(*dest_ip++);
        }
        int index_dest = hash_dest % hash_table_size;

        if (!source_added && strcmp(hash_table[index_dest], "") == 0) {
            strcpy(hash_table[index_dest], records[i].destination_ip);
            ip_count++;
            dest_added = true;
        } else if (strcmp(hash_table[index_dest], records[i].destination_ip) != 0) {
            strcpy(hash_table[index_dest], records[i].destination_ip);
            ip_count++;
        }
    }

    return ip_count;
}

void process_network_connections() {
    size_t capacity = 10; // Initial allocation
    NetworkConnectionRecord *records = malloc(capacity * sizeof(NetworkConnectionRecord));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    size_t record_count = 0;
    char line[256];

    while (fgets(line, sizeof(line), stdin)) {
        if (record_count >= capacity) {
            capacity *= 2;
            NetworkConnectionRecord *new_records = realloc(records, capacity * sizeof(NetworkConnectionRecord));
            if (!new_records) {
                fprintf(stderr, "Memory reallocation failed\n");
                free(records);
                return;
            }
            records = new_records;
        }

        // Parse input line
        NetworkConnectionRecord record;
        if (sscanf(line, "%15[^ ] %15[^ ] %d", record.source_ip, record.destination_ip, &record.status) != 3) {
            fprintf(stderr, "Invalid input format\n");
            free(records);
            return;
        }

        // Validate IP addresses
        if (!is_valid_ipv4(record.source_ip) || !is_valid_ipv4(record.destination_ip)) {
            fprintf(stderr, "Invalid IPv4 address detected: %s or %s\n", record.source_ip, record.destination_ip);
            free(records);
            return;
        }

        records[record_count++] = record;
    }

    printf("Total unique IP addresses: %d\n", count_unique_ips(records, record_count));

    free(records);
}

int main() {
#ifdef _WIN32
    freopen_s(NULL, "CONIN$", "r", stdin); // Redirect standard input for Windows compatibility
#endif

    process_network_connections();
    return 0;
}
```

This code snippet defines a C function to read network connection records from standard input, validates them as IPv4 addresses, and calculates the total number of unique IP addresses. It handles memory allocation dynamically and ensures safe termination on invalid input or memory issues. The solution is designed with modularity and compatibility across different platforms in mind.']

