#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char* session_id;
    time_t connection_start_time;
    char* log_data;
} NetworkSession;

typedef struct Node {
    NetworkSession* session;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t mutex;
    size_t max_memory_usage;  // maximum memory usage in bytes
} SessionCollection;

// Function to check if a session is valid
int isValidSession(const NetworkSession* session) {
    return (session->session_id != NULL && strlen(session->session_id) > 0 &&
            session->connection_start_time != 0 && session->log_data != NULL);
}

// Function to initialize the collection
void initCollection(SessionCollection* collection, size_t max_memory_usage) {
    collection->head = NULL;
    pthread_mutex_init(&collection->mutex, NULL);
    collection->max_memory_usage = max_memory_usage;
}

// Helper function to calculate memory usage of a session
size_t getSessionMemoryUsage(const NetworkSession* session) {
    return sizeof(NetworkSession) + strlen(session->session_id) + 1 +
           sizeof(time_t) + strlen(session->log_data) + 1;
}

// Function to add a session to the collection
int addSession(SessionCollection* collection, const NetworkSession* new_session) {
    if (!isValidSession(new_session)) return -1;

    pthread_mutex_lock(&collection->mutex);

    size_t current_memory_usage = 0;
    Node* node = collection->head;
    while (node != NULL) {
        current_memory_usage += getSessionMemoryUsage(node->session);
        node = node->next;
    }

    if (current_memory_usage + getSessionMemoryUsage(new_session) > collection->max_memory_usage) {
        pthread_mutex_unlock(&collection->mutex);
        return -1;  // Out of memory
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&collection->mutex);
        return -1;
    }

    new_node->session = malloc(sizeof(NetworkSession));
    if (!new_node->session) {
        free(new_node);
        pthread_mutex_unlock(&collection->mutex);
        return -1;
    }

    *new_node->session = *new_session;

    new_node->next = collection->head;
    collection->head = new_node;

    pthread_mutex_unlock(&collection->mutex);

    return 0; // Success
}

// Function to destroy the session collection and free memory
void destroyCollection(SessionCollection* collection) {
    pthread_mutex_lock(&collection->mutex);
    Node* current = collection->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current->session->log_data);
        free(current->session->session_id);
        free(current->session);
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&collection->mutex);
    pthread_mutex_destroy(&collection->mutex);
}

// Function to process a batch of sessions
void processSessions(SessionCollection* collection, NetworkSession* sessions, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (addSession(collection, &sessions[i]) != 0) {
            // Handle out-of-memory or invalid session case
            fprintf(stderr, "Failed to add session: %zu\n", i);
        }
    }
}

// Example usage
int main() {
    SessionCollection collection;
    initCollection(&collection, 1024 * 1024); // 1 MB max memory

    NetworkSession sessions[] = {
        {"session1", 1622470427, "Log data for session 1"},
        {"session2", 1622470527, "Log data for session 2"}
    };

    processSessions(&collection, sessions, sizeof(sessions) / sizeof(sessions[0]));

    destroyCollection(&collection);

    return 0;
}
```

This code sets up a simple dynamic collection of `NetworkSession` objects with thread-safe access using mutex locks. It includes memory usage checks and handles adding new sessions only if there's enough available memory, ensuring that the system can gracefully manage memory pressure and prevent out-of-memory conditions. The session validation is basic but can be expanded as needed for more complex scenarios.']

