typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    Record *records;
    size_t size;
    pthread_mutex_t lock;
} RecordArray;

#define MIN_SIZE 1
#define MAX_SIZE 10000

void handle_error(const char *message) {
    fprintf(stderr, "%s\n", message);
    exit(EXIT_FAILURE);
}

RecordArray* initialize_records(size_t num_records, int random_seed) {
    if (num_records < MIN_SIZE || num_records > MAX_SIZE)
        handle_error("Number of records is out of range.");

    RecordArray *array = malloc(sizeof(RecordArray));
    if (!array) handle_error("Failed to allocate memory for record array.");

    array->records = calloc(num_records, sizeof(Record));
    if (!array->records) {
        free(array);
        handle_error("Failed to allocate memory for records.");
    }
    array->size = num_records;

    pthread_mutex_init(&array->lock, NULL);

    srand(random_seed);

    for (size_t i = 0; i < num_records; ++i) {
        pthread_mutex_lock(&array->lock);
        array->records[i].key = rand() % num_records;
        array->records[i].offset = rand();
        pthread_mutex_unlock(&array->lock);
    }

    return array;
}

void free_records(RecordArray *array) {
    if (!array) return;

    pthread_mutex_lock(&array->lock);
    free(array->records);
    pthread_mutex_unlock(&array->lock);

    pthread_mutex_destroy(&array->lock);
    free(array);
}
```

