    return SUCCESS;
}

static uint32_t generate_crcflag(uint16_t rnti, ConfigMode mode) {
    uint32_t crcflag = 0;

    switch (mode) {
        case HIGH_PERFORMANCE_MODE:
            // Use an efficient algorithm for performance-critical applications
            crcflag = (rnti ^ (rnti << 5)) & 0xFFFFFFFF;
            break;
        case DEBUG_MODE:
            // Include additional details in debug mode
            crcflag = ((rnti * rnti) + (rnti >> 2)) & 0xFFFFFFFF;
            break;
        case EXTENDED_STATS_MODE:
            // Use a more complex algorithm for extended statistics
            crcflag = (((rnti ^ 0xA5A5) << 3) | (rnti >> 7)) & 0xFFFFFFFF;
            break;
        default:
            // Default CRCFLAG generation
            crcflag = rnti ^ (rnti << 11);
            break;
    }
    return crcflag;
}

static void validate_array(NFAPI_CRC_INDICATION_PDU_T *array, size_t n, ConfigMode mode) {
