#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char *name;
    int age;
    double balance;
} Item;

// Function to read items from a file and return an array of items
Item* loadItems(const char *filename, size_t *count) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        exit(EXIT_FAILURE);
    }

    // Read number of items
    fscanf(file, "%zu", count);

    Item *items = malloc(*count * sizeof(Item));
    if (!items) {
        perror("Memory allocation failed");
        fclose(file);
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < *count; ++i) {
        char name[256];
        fscanf(file, "%s %d %lf", name, &items[i].age, &items[i].balance);
        items[i].name = strdup(name); // Duplicate the string
    }

    fclose(file);
    return items;
}

// Function to sort items by age using a stable sorting algorithm (Merge Sort)
void merge(Item *array, size_t left, size_t mid, size_t right) {
    size_t n1 = mid - left + 1;
    size_t n2 = right - mid;

    Item *L = malloc(n1 * sizeof(Item));
    Item *R = malloc(n2 * sizeof(Item));

    for (size_t i = 0; i < n1; ++i) L[i] = array[left + i];
    for (size_t j = 0; j < n2; ++j) R[j] = array[mid + 1 + j];

    size_t i = 0, j = 0, k = left;
    while (i < n1 && j < n2) {
        if (L[i].age <= R[j].age) {
            array[k++] = L[i++];
        } else {
            array[k++] = R[j++];
        }
    }

    while (i < n1) array[k++] = L[i++];
    while (j < n2) array[k++] = R[j++];

    free(L);
    free(R);
}

void mergeSort(Item *array, size_t left, size_t right) {
    if (left < right) {
        size_t mid = left + (right - left) / 2;

        mergeSort(array, left, mid);
        mergeSort(array, mid + 1, right);

        merge(array, left, mid, right);
    }
}

// Function to update balance for a given name
void updateBalance(Item *items, size_t count, const char *name, double new_balance) {
    for (size_t i = 0; i < count; ++i) {
        if (strcmp(items[i].name, name) == 0) {
            items[i].balance = new_balance;
            return;
        }
    }
}

// Function to free allocated memory
void freeItems(Item *items, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free(items[i].name);
    }
    free(items);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return EXIT_FAILURE;
    }

    size_t count;
    Item *items = loadItems(argv[1], &count);

    // Sort items by age
    mergeSort(items, 0, count - 1);

    // Example of updating balance
    updateBalance(items, count, "JohnDoe", 1234.56);

    // Free allocated memory
    freeItems(items, count);

    return EXIT_SUCCESS;
}
