#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    long offset;
    int key;
    double value;
} record;

typedef struct {
    size_t count;
    size_t batch_size;
    record *records;
    size_t total_records;
    pthread_mutex_t lock;
} RecordManager;

RecordManager* create_record_manager(size_t total_records, size_t batch_size) {
    if (total_records == 0 || batch_size == 0) return NULL;

    RecordManager *manager = malloc(sizeof(RecordManager));
    if (!manager) return NULL;

    manager->count = 0;
    manager->batch_size = batch_size;
    manager->records = calloc(total_records, sizeof(record));
    if (!manager->records) {
        free(manager);
        return NULL;
    }
    manager->total_records = total_records;

    pthread_mutex_init(&manager->lock, NULL);

    // Seed for reproducible random data
    srand(42);  // Replace with a custom seed function as necessary

    for (size_t i = 0; i < total_records; ++i) {
        manager->records[i].offset = rand();
        manager->records[i].key = rand() % 100;
        manager->records[i].value = (double)(rand()) / RAND_MAX * 10.0;
    }

    return manager;
}

int record_stream(RecordManager* manager, size_t start_index, record* batch) {
    if (!manager || !batch || start_index >= manager->total_records) return -1;

    pthread_mutex_lock(&manager->lock);

    size_t end_index = (start_index + manager->batch_size < manager->total_records) ?
                       start_index + manager->batch_size : manager->total_records;

    size_t actual_batch_size = end_index - start_index;
    memcpy(batch, &manager->records[start_index], actual_batch_size * sizeof(record));

    pthread_mutex_unlock(&manager->lock);

    return (int)actual_batch_size;  // Return the number of records in the batch
}

void serialize_records(const RecordManager* manager, const char* filename) {
    if (!manager || !filename) return;

    FILE* file = fopen(filename, "wb");
    if (!file) return;

    pthread_mutex_lock(&manager->lock);

    fwrite(manager->records, sizeof(record), manager->total_records, file);

    fclose(file);
    pthread_mutex_unlock(&manager->lock);
}

int deserialize_records(RecordManager* manager, const char* filename) {
    if (!manager || !filename) return -1;

    FILE* file = fopen(filename, "rb");
    if (!file) return -1;

    pthread_mutex_lock(&manager->lock);

    size_t read_count = fread(manager->records, sizeof(record), manager->total_records, file);
    if (read_count != manager->total_records) {
        fclose(file);
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    fclose(file);
    pthread_mutex_unlock(&manager->lock);

    return 0; // Success
}

void destroy_record_manager(RecordManager* manager) {
    if (manager) {
        free(manager->records);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}
