void process_input_and_create_structures();
int64_t find_largest_integer(const NFAPI_CRC_INDICATION_PDU_T *list, size_t count);
int write_to_file(const char *filename, const NFAPI_CRC_INDICATION_PDU_T *data, size_t count);

void process_input_and_create_structures() {
    int *ints = (int *)malloc(MAX_INTS * sizeof(int));
    if (!ints) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    int num_read = 0;
    while (num_read < MAX_INTS && scanf("%d", &ints[num_read]) == 1) {
        num_read++;
    }

    // Remove invalid inputs and duplicates
    if (num_read <= 0 || ferror(stdin)) {
        free(ints);
        fprintf(stderr, "Invalid input detected\n");
        exit(EXIT_FAILURE);
    }

    int *unique_ints = (int *)malloc(num_read * sizeof(int));
    if (!unique_ints) {
        free(ints);
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    size_t unique_count = 0;
    for (int i = 0; i < num_read; i++) {
        int is_unique = 1;
        for (size_t j = 0; j < unique_count; j++) {
            if (ints[i] == unique_ints[j]) {
                is_unique = 0;
                break;
            }
        }
        if (is_unique) {
            unique_ints[unique_count++] = ints[i];
        }
    }

    NFAPI_CRC_INDICATION_PDU_T *struct_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(unique_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!struct_list) {
        free(ints);
        free(unique_ints);
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < unique_count; i++) {
        struct_list[i].RX_UE_INFORMATION_TAG = 1;
        struct_list[i].RNTI = unique_ints[i] % MAX_INTS;
        struct_list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }

    if (unique_count > 0) {
        int64_t largest_integer = find_largest_integer(struct_list, unique_count);
        printf("Largest integer: %ld\n", largest_integer);

        if (!write_to_file("crc_indications.bin", struct_list, unique_count)) {
            fprintf(stderr, "Failed to write to file\n");
        }
    } else {
        fprintf(stderr, "No valid structures created\n");
    }

    free(ints);
    free(unique_ints);
