#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    int key;
    long offset;
    void *payload;
} Record;

typedef struct {
    size_t max_payload_size;
    unsigned int max_record_count;
    pthread_mutex_t lock;
    Record **records;
    size_t capacity;
    size_t count;
    size_t record_size;
    unsigned int seed;
} RecordManager;

// Function to initialize a random number generator
void init_rng(unsigned int *seed) {
    *seed = rand();
}

// Memory allocation with custom pool
RecordManager* create_record_manager(size_t max_payload_size, unsigned int max_record_count, unsigned int seed) {
    if (max_payload_size == 0 || max_record_count == 0) return NULL;

    RecordManager *manager = malloc(sizeof(RecordManager));
    if (!manager) return NULL;

    manager->max_payload_size = max_payload_size;
    manager->max_record_count = max_record_count;
    manager->capacity = max_record_count;
    manager->count = 0;
    manager->record_size = sizeof(int) + sizeof(long) + max_payload_size;
    manager->seed = seed;

    pthread_mutex_init(&manager->lock, NULL);
    manager->records = calloc(manager->capacity, sizeof(Record*));
    if (!manager->records) {
        free(manager);
        return NULL;
    }

    init_rng(&seed);

    return manager;
}

// Function to safely add a new record
int add_record(RecordManager *manager, int key, long offset, void *payload, size_t payload_size) {
    if (payload_size > manager->max_payload_size || manager->count >= manager->max_record_count) 
        return -1;

    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        // Resize logic
        size_t new_capacity = manager->capacity * 2;
        Record **new_records = realloc(manager->records, new_capacity * sizeof(Record*));

        if (!new_records) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Allocation failure
        }

        memset(new_records + manager->capacity, 0, (new_capacity - manager->capacity) * sizeof(Record*));
        manager->records = new_records;
        manager->capacity = new_capacity;
    }

    Record *record = malloc(manager->record_size);
    if (!record) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Allocation failure
    }

    record->key = key;
    record->offset = offset;
    memcpy(record->payload, payload, payload_size);

    manager->records[manager->count++] = record;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Function to free memory used by RecordManager
void destroy_record_manager(RecordManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->records[i]);
    }
    free(manager->records);

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

// Example usage
int main() {
    size_t max_payload_size = 1024;
    unsigned int max_record_count = 1000;
    unsigned int seed = 12345;

    RecordManager *mgr = create_record_manager(max_payload_size, max_record_count, seed);
    if (!mgr) {
        fprintf(stderr, "Failed to initialize record manager\n");
        return EXIT_FAILURE;
    }

    char payload[256] = "Example Payload";
    add_record(mgr, 1, 100, payload, sizeof(payload));

    destroy_record_manager(mgr);

    return EXIT_SUCCESS;
}
```

