```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Node {
    double value;
    struct Node* next;
    long offset;
    int key;
} Node;

// Function prototypes
void initialize_list(Node** head, int size, double min_val, double max_val, int min_key, int max_key, unsigned int seed);
Node* create_node(double value, long offset, int key);
void append_node(Node** head, Node* new_node);
void traverse_and_print_list(const Node* node);
void modify_keys(Node* head, int min_value, int max_value, unsigned int seed);
void free_list(Node* head);

// Thread synchronization primitives
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_list(Node** head, int size, double min_val, double max_val, int min_key, int max_key, unsigned int seed) {
    srand(seed);  // Initialize random number generator with seed
    *head = NULL;
    for (int i = 0; i < size; ++i) {
        double value = min_val + (double)rand() / RAND_MAX * (max_val - min_val);
        long offset = rand();
        int key = min_key + rand() % (max_key - min_key + 1);

        Node* new_node = create_node(value, offset, key);
        if (new_node == NULL) {
            fprintf(stderr, "Memory allocation failed.\n");
            free_list(*head);
            *head = NULL;
            return;
        }
        append_node(head, new_node);
    }
}

Node* create_node(double value, long offset, int key) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (node == NULL) {
        return NULL;
    }
    node->value = value;
    node->offset = offset;
    node->key = key;
    node->next = NULL;
    return node;
}

void append_node(Node** head, Node* new_node) {
    pthread_mutex_lock(&lock);  // Ensure thread safety
    if (*head == NULL) {
        *head = new_node;
    } else {
        Node* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    pthread_mutex_unlock(&lock);
}

void traverse_and_print_list(const Node* node) {
    while (node != NULL) {
        printf("Value: %.2f, Offset: %ld, Key: %d\n", node->value, node->offset, node->key);
        node = node->next;
    }
}

void modify_keys(Node* head, int min_value, int max_value, unsigned int seed) {
    srand(seed);  // Re-seed for key modification
    Node* current = head;
    while (current != NULL) {
        current->key = min_value + rand() % (max_value - min_value + 1);
        current = current->next;
    }
}

void free_list(Node* head) {
    pthread_mutex_lock(&lock);  // Ensure thread safety
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
    pthread_mutex_unlock(&lock);
}

// Example usage:
int main() {
    Node* list_head = NULL;
    initialize_list(&list_head, 10, 0.0, 100.0, 1, 100, 42);

    printf("Initial List:\n");
    traverse_and_print_list(list_head);

    modify_keys(list_head, 50, 150, 24);
    printf("\nModified Keys List:\n");
    traverse_and_print_list(list_head);

    free_list(list_head);
    return 0;
}
```

This code implements a singly linked list with dynamic memory management. It includes functions for initializing the list with random values, appending nodes safely in a multi-threaded environment using mutex locks, traversing and printing the list, modifying node keys, and freeing allocated memory to prevent leaks. The design considers thread safety and efficient memory management strategies suitable for concurrent applications.']

