void process_data_with_retry(void (*callback)(NFAPI_CRC_INDICATION_PDU_T *)) {
    int retries = 0;
    const int max_retries = 5;
    while (retries < max_retries) {
        if (fetch_private_key_and_certificate(NULL, NULL)) {
            return; // Success
        }
        retries++;
        sleep((1 << retries)); // Exponential backoff
    }
    log_error("Failed to fetch private key and certificate after retries", 1001);
}

void create_pdu(NFAPI_CRC_INDICATION_PDU_T **pdus, int *count, int value) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        log_error("Memory allocation failed", 1002);
        return;
    }

    pdu->RX_UE_INFORMATION_TAG = value;
    pdu->RNTI = *count + 1; // Ensure unique RNTI
    pdu->CRC_INDICATION_REL8_TAG = rand() % 1024; // Random tag
    pdu->CRCFLAG = rand() % 2; // Random CRCFLAG

    (*pdus)[(*count)++] = pdu;
}

void generateCertificateFromStream(void (*callback)(NFAPI_CRC_INDICATION_PDU_T *)) {
    int values[MAX_INTS];
    int count = 0, input;
    bool seen[MAX_INTS] = {false};
    NFAPI_CRC_INDICATION_PDU_T *pdus[MAX_INTS];

    if (!fetch_private_key_and_certificate(NULL, NULL)) {
        log_error("Initial fetch failed", 1003);
        return;
    }

    while (scanf("%d", &input) == 1 && count < MAX_INTS) {
        if (seen[input]) continue; // Skip duplicates

        seen[input] = true;
        create_pdu(pdus, &count, input);

        callback(pdus[count - 1]); // Call the provided callback function
    }

    if (count > 0) {
        int largest = values[0];
        for (int i = 1; i < count; ++i) {
            if (values[i] > largest) {
                largest = values[i];
            }
        }
        printf("Largest integer in the array: %d\n", largest);
    } else {
        log_error("No valid PDUs were created", 1004);
    }

    // Free allocated memory
    for (int i = 0; i < count; ++i) {
        free(pdus[i]);
    }
}

void my_callback(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    printf("PDU Created: RX_UE_INFORMATION_TAG=%d, RNTI=%d\n", pdu->RX_UE_INFORMATION_TAG, pdu->RNTI);
}

int main() {
    srand(time(NULL)); // Seed the random number generator
    process_data_with_retry(my_callback);
    generateCertificateFromStream(my_callback);

    return 0;
}
