#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>
#include <sys/time.h>

#define MAX_OBJECTS 1000
#define MEMORY_LIMIT 10485760 // 10 MB for simplicity
#define LRU_CACHE_SIZE 100
#define LATENCY_THRESHOLD_MS 50

typedef struct {
    int rnti;
    char *crcIndicationRel8Tag;
    unsigned int crcFlag; // Randomly set CRCFLAG
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct cache_node {
    int key;
    NFAPI_CRC_INDICATION_PDU_T data;
    struct cache_node *prev, *next;
} CacheNode;

typedef struct {
    CacheNode *head, *tail;
    int size;
    pthread_mutex_t lock;
} LRUCache;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T objects[MAX_OBJECTS];
    int count;
    pthread_rwlock_t rwlock;
    LRUCache cache;
    double avgLatency;
    int alertCount;
    pthread_mutex_t monitorLock;
} StorageSystem;

StorageSystem storage = {.count = 0, .avgLatency = 0.0, .alertCount = 0};

void initLRU(LRUCache *cache) {
    cache->head = NULL;
    cache->tail = NULL;
    cache->size = 0;
    pthread_mutex_init(&cache->lock, NULL);
}

void lruAccess(CacheNode **node) {
    if (*node == NULL) return;
    CacheNode *temp = storage.cache.head;

    // Move accessed node to the front
    if (temp != *node) {
        if ((*node)->prev)
            (*node)->prev->next = (*node)->next;
        if ((*node)->next)
            (*node)->next->prev = (*node)->prev;
        if (*node == storage.cache.tail)
            storage.cache.tail = (*node)->prev;

        (*node)->next = temp;
        (*node)->prev = NULL;
        if (temp) temp->prev = *node;
        storage.cache.head = *node;
    }
}

void lruAdd(int key, NFAPI_CRC_INDICATION_PDU_T data) {
    CacheNode *new_node = malloc(sizeof(CacheNode));
    new_node->key = key;
    new_node->data = data;
    pthread_mutex_lock(&storage.cache.lock);

    if (storage.cache.size == LRU_CACHE_SIZE) {
        // Remove least recently used element
        CacheNode *last = storage.cache.tail;
        storage.cache.tail = last->prev;
        if (storage.cache.tail)
            storage.cache.tail->next = NULL;

        free(last);
        storage.cache.size--;
    }

    new_node->next = storage.cache.head;
    if (new_node->next) new_node->next->prev = new_node;
    new_node->prev = NULL;
    storage.cache.head = new_node;
    if (!storage.cache.tail)
        storage.cache.tail = new_node;

    storage.cache.size++;
    pthread_mutex_unlock(&storage.cache.lock);
}

void lruRemove(int key) {
    pthread_mutex_lock(&storage.cache.lock);

    CacheNode *current = storage.cache.head;
    while (current) {
        if (current->key == key) {
            if (current->prev)
                current->prev->next = current->next;
            else
                storage.cache.head = current->next;

            if (current->next)
                current->next->prev = current->prev;
            else
                storage.cache.tail = current->prev;

            free(current);
            storage.cache.size--;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&storage.cache.lock);
}

void *threadSafeWrite(void *arg) {
    NFAPI_CRC_INDICATION_PDU_T data = *(NFAPI_CRC_INDICATION_PDU_T *)arg;
    int rnti = data.rnti;

    struct timeval start, end;
    gettimeofday(&start, NULL);

    pthread_rwlock_wrlock(&storage.rwlock);
    if (storage.count < MAX_OBJECTS) {
        storage.objects[storage.count++] = data;
        lruAdd(rnti, data);
    }
    pthread_rwlock_unlock(&storage.rwlock);

    gettimeofday(&end, NULL);
    double elapsedTime = ((double)(end.tv_sec - start.tv_sec) * 1000.0 + (double)(end.tv_usec - start.tv_usec) / 1000.0);

    pthread_mutex_lock(&storage.monitorLock);
    storage.avgLatency = ((storage.avgLatency * storage.count) + elapsedTime) / (storage.count + 1);
    if (elapsedTime > LATENCY_THRESHOLD_MS)
        storage.alertCount++;
    pthread_mutex_unlock(&storage.monitorLock);

    return NULL;
}

void *threadSafeRead(void *arg) {
    int rnti = *(int *)arg;

    struct timeval start, end;
    gettimeofday(&start, NULL);

    NFAPI_CRC_INDICATION_PDU_T result;
    pthread_rwlock_rdlock(&storage.rwlock);
    for (int i = 0; i < storage.count; ++i) {
        if (storage.objects[i].rnti == rnti) {
            result = storage.objects[i];
            break;
        }
    }

    CacheNode *node = NULL;
    pthread_mutex_lock(&storage.cache.lock);
    CacheNode *current = storage.cache.head;
    while (current) {
        if (current->key == rnti) {
            node = current;
            lruAccess(&node);
            result = current->data;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&storage.cache.lock);

    gettimeofday(&end, NULL);
    double elapsedTime = ((double)(end.tv_sec - start.tv_sec) * 1000.0 + (double)(end.tv_usec - start.tv_usec) / 1000.0);

    pthread_mutex_lock(&storage.monitorLock);
    storage.avgLatency = ((storage.avgLatency * storage.count) + elapsedTime) / (storage.count + 1);
    if (elapsedTime > LATENCY_THRESHOLD_MS)
        storage.alertCount++;
    pthread_mutex_unlock(&storage.monitorLock);

    return (void *)&result;
}

// RESTful API handler stubs
void handlePutRequest(int rnti, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_t thread;
    pthread_create(&thread, NULL, threadSafeWrite, &data);
    pthread_join(thread, NULL);
}

NFAPI_CRC_INDICATION_PDU_T *handleGetRequest(int rnti) {
    pthread_t thread;
    NFAPI_CRC_INDICATION_PDU_T *result = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_create(&thread, NULL, threadSafeRead, &rnti);
    pthread_join(thread, result);
    return result;
}

void handleDeleteRequest(int rnti) {
    NFAPI_CRC_INDICATION_PDU_T defaultData = {0};
    lruRemove(rnti);

    pthread_rwlock_wrlock(&storage.rwlock);
    for (int i = 0; i < storage.count; ++i) {
        if (storage.objects[i].rnti == rnti) {
            storage.objects[i] = defaultData;
            break;
        }
    }
    pthread_rwlock_unlock(&storage.rwlock);
}

void initStorageSystem() {
    pthread_rwlock_init(&storage.rwlock, NULL);
    initLRU(&storage.cache);
    pthread_mutex_init(&storage.monitorLock, NULL);
}

int main() {
    initStorageSystem();

    // Simulate some operations
    NFAPI_CRC_INDICATION_PDU_T data = {1234, "tag1", rand()};
    handlePutRequest(data.rnti, data);

    NFAPI_CRC_INDICATION_PDU_T *result = handleGetRequest(1234);
    printf("RNTI: %d, CRC Flag: %u\n", result->rnti, result->crcFlag);

    handleDeleteRequest(1234);

    // Monitoring and logging
    pthread_mutex_lock(&storage.monitorLock);
    if (storage.alertCount > 0) {
        printf("Alert! High latency detected.\n");
    }
    printf("Average Latency: %.2f ms\n", storage.avgLatency);
    pthread_mutex_unlock(&storage.monitorLock);

    return 0;
}
```

This code includes:
- A `StorageSystem` structure with a read-write lock for concurrent access.
- An LRU cache implementation for frequently accessed data.
- Thread-safe write and read operations using POSIX threads.
- Basic RESTful API stubs (`handlePutRequest`, `handleGetRequest`, `handleDeleteRequest`) to simulate API interactions.
- A simple monitoring mechanism tracking average latency and alerting when it exceeds a threshold.

This is a simplified example and would need further development for production use, including:
- Detailed logging and metrics collection.
- Integration with external databases and services.
- Scalability enhancements for distributed environments.']

['Below is a C implementation that initializes and populates a dynamic array of `TrafficEvent` structures with thread safety using mutexes:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef enum {
    EVENT_TYPE_A,
    EVENT_TYPE_B,
    // Add more event types as needed
} EventType;

typedef struct {
    time_t timestamp;
    EventType eventType;
    char *description;  // Dynamically allocated string for the description
} TrafficEvent;

typedef struct {
    TrafficEvent **events;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} TrafficEventManager;

// Function to initialize a new traffic event manager
int initTrafficEventManager(TrafficEventManager *manager) {
    if (pthread_mutex_init(&manager->lock, NULL) != 0) {
        fprintf(stderr, "Failed to initialize mutex\n");
        return -1;
    }

    manager->events = NULL;
    manager->count = 0;
    manager->capacity = 0;

    // Initial capacity
    size_t initial_capacity = 10;
    manager->events = malloc(initial_capacity * sizeof(TrafficEvent *));
    if (!manager->events) {
        fprintf(stderr, "Memory allocation failed for events\n");
        return -1;
    }
    manager->capacity = initial_capacity;

    return 0;
}

// Function to free the memory allocated for traffic event descriptions
void freeTrafficEvents(TrafficEventManager *manager) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->events[i]->description) {
            free(manager->events[i]->description);
        }
        free(manager->events[i]);
    }
    free(manager->events);
    pthread_mutex_unlock(&manager->lock);
}

// Function to add a new traffic event
int addTrafficEvent(TrafficEventManager *manager, EventType eventType, const char *description) {
    pthread_mutex_lock(&manager->lock);

    // Resize if necessary
    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity ? manager->capacity * 2 : 10;
        TrafficEvent **new_events = realloc(manager->events, new_capacity * sizeof(TrafficEvent *));
        if (!new_events) {
            fprintf(stderr, "Memory allocation failed while resizing events\n");
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        manager->events = new_events;
        manager->capacity = new_capacity;
    }

    TrafficEvent *event = malloc(sizeof(TrafficEvent));
    if (!event) {
        fprintf(stderr, "Memory allocation failed for event\n");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    time_t now = time(NULL);
    event->timestamp = now;
    event->eventType = eventType;

    size_t description_length = strlen(description) + 1; // Include null-terminator
    event->description = malloc(description_length);
    if (!event->description) {
        fprintf(stderr, "Memory allocation failed for event description\n");
        free(event);
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    memcpy(event->description, description, description_length);

    manager->events[manager->count++] = event;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Function to serialize a traffic event into JSON format
void serializeTrafficEvent(const TrafficEvent *event, char *buffer, size_t buffer_size) {
    snprintf(buffer, buffer_size,
             "{\"timestamp\": %ld, \"eventType\": %d, \"description\": \"%s\"}",
             (long int)event->timestamp, event->eventType, event->description);
}

// Example usage
int main() {
    TrafficEventManager manager;
    if (initTrafficEventManager(&manager) != 0) {
        return EXIT_FAILURE;
    }

    addTrafficEvent(&manager, EVENT_TYPE_A, "Example event description");

    // Serialize and print the first event as an example
    char buffer[256];
    serializeTrafficEvent(manager.events[0], buffer, sizeof(buffer));
    printf("%s\n", buffer);

    freeTrafficEvents(&manager);
    pthread_mutex_destroy(&manager.lock);

    return EXIT_SUCCESS;
}
```

This code initializes a dynamic array of `TrafficEvent` structures with thread safety using mutexes. It includes functions to initialize the manager, add events, serialize them into JSON format, and handle memory cleanup. Memory allocation failures are logged, and the implementation is designed for scalability and maintainability.']

