// Global variables for memory management
long offsets[MAX_RECORDS];
int keys1[INITIAL_ARRAY_SIZE], keys2[INITIAL_ARRAY_SIZE];
Record records[MAX_RECORDS];
double doubles_array[INITIAL_ARRAY_SIZE];

size_t offset_count = 0;
size_t key1_count = 0, key2_count = 0, record_count = 0;

void resize_arrays_if_needed() {
    if (offset_count >= MAX_RECORDS) {
        fprintf(stderr, "Offset array reached max capacity\n");
        return;
    }
    if (key1_count >= INITIAL_ARRAY_SIZE || key2_count >= INITIAL_ARRAY_SIZE) {
        size_t new_size = INITIAL_ARRAY_SIZE * 2;
        int* temp_keys1 = realloc(keys1, new_size * sizeof(int));
        int* temp_keys2 = realloc(keys2, new_size * sizeof(int));

        if (!temp_keys1 || !temp_keys2) {
            fprintf(stderr, "Memory allocation error\n");
            return;
        }
        keys1 = temp_keys1;
        keys2 = temp_keys2;

        INITIAL_ARRAY_SIZE = new_size; // Update global size
    }
    if (record_count >= MAX_RECORDS) {
        fprintf(stderr, "Record array reached max capacity\n");
        return;
    }
}

void initialize_arrays() {
    srand(time(NULL));
    for (size_t i = 0; i < INITIAL_ARRAY_SIZE; ++i) {
        offsets[i] = rand() % 100000;
        keys1[i] = rand() % 1000;
        doubles_array[i] = (double)keys1[i] / offsets[i];
    }
}

void initialize_records() {
    int cumulative_sum = 0;

    for (size_t i = 0; i < MAX_RECORDS && record_count < MAX_RECORDS; ++i) {
        resize_arrays_if_needed();

        int value;
        safe_add(rand() % 100, cumulative_sum, &value);

        records[record_count].value = value;
        records[record_count].key = &keys1[key1_count];
        keys1[key1_count] = rand() % 1000; // Example logic to populate keys

        cumulative_sum += value;

        record_count++;
    }
}

int safe_add(int a, int b, int *result) {
    long long sum = (long long)a + b;
    if (sum > INT_MAX || sum < INT_MIN) {
        fprintf(stderr, "Integer overflow detected\n");
        return 0; // Overflow occurred
    }
    *result = (int)sum;
    return 1; // Successful addition
}

void* record_manager(void* arg) {
    pthread_mutex_lock(&memory_lock);
    initialize_arrays();
    initialize_records();
    log_memory_usage(); // Example logging at intervals
    pthread_mutex_unlock(&memory_lock);

    return NULL;
}

int main() {
    pthread_t thread_id;

    if (pthread_create(&thread_id, NULL, record_manager, NULL) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return EXIT_FAILURE;
    }

    pthread_join(thread_id, NULL);

    // Cleanup
    free(records); // Assuming records was dynamically allocated somewhere
    free(keys1);
    free(keys2);

    return EXIT_SUCCESS;
}
