#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define constants for JSON serialization
#define JSON_KEY_TIMESTAMP "\"timestamp\":"
#define JSON_KEY_EVENT_TYPE "\"eventType\":"
#define JSON_KEY_DESCRIPTION "\"description\":"

typedef struct {
    time_t timestamp;
    char* eventType;
    char* description;
} TrafficEvent;

typedef struct {
    double value;
    char* uniqueID;
    int count;
} Item;

// Mutex for thread-safe operations
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Dynamic array of TrafficEvents
TrafficEvent** trafficEvents = NULL;
size_t eventCount = 0;
size_t capacity = 0;

// Memory pool for Items
Item* itemPool = NULL;
size_t itemCapacity = 0;
size_t itemCount = 0;

// Function to initialize the dynamic array and memory pool
void initSystem(size_t initialEventCapacity, size_t initialItemCapacity) {
    pthread_mutex_lock(&mutex);

    // Initialize traffic events array
    capacity = initialEventCapacity;
    eventCount = 0;
    trafficEvents = malloc(capacity * sizeof(TrafficEvent*));

    // Initialize item pool
    itemCapacity = initialItemCapacity;
    itemCount = 0;
    itemPool = malloc(itemCapacity * sizeof(Item));

    pthread_mutex_unlock(&mutex);
}

// Function to add a TrafficEvent
void addTrafficEvent(time_t timestamp, const char* eventType, const char* description) {
    pthread_mutex_lock(&mutex);

    if (eventCount >= capacity) {
        // Double the capacity when needed
        capacity *= 2;
        trafficEvents = realloc(trafficEvents, capacity * sizeof(TrafficEvent*));
    }

    TrafficEvent* newEvent = malloc(sizeof(TrafficEvent));
    newEvent->timestamp = timestamp;
    newEvent->eventType = strdup(eventType);
    newEvent->description = strdup(description);

    trafficEvents[eventCount++] = newEvent;

    pthread_mutex_unlock(&mutex);
}

// Function to serialize a TrafficEvent into JSON
char* serializeTrafficEvent(const TrafficEvent* event) {
    char* json = malloc(256); // Adjust size as necessary for your use case
    snprintf(json, 256, "{ %s \"%ld\", %s \"%s\", %s \"%s\" }",
             JSON_KEY_TIMESTAMP, (long)event->timestamp,
             JSON_KEY_EVENT_TYPE, event->eventType,
             JSON_KEY_DESCRIPTION, event->description);
    return json;
}

// Function to add an Item asynchronously
void* addItemAsync(void* data) {
    pthread_mutex_lock(&mutex);

    if (itemCount >= itemCapacity) {
        // Double the capacity when needed
        itemCapacity *= 2;
        itemPool = realloc(itemPool, itemCapacity * sizeof(Item));
    }

    Item* newItem = &itemPool[itemCount++];
    newItem->value = ((double*)data)[0];
    newItem->uniqueID = strdup((char*)data + sizeof(double)); // Assuming unique ID follows value
    newItem->count = 1;

    pthread_mutex_unlock(&mutex);
    return NULL;
}

// Periodic cleanup function
void periodicCleanup() {
    while (1) {
        sleep(60); // Run every 60 seconds

        pthread_mutex_lock(&mutex);

        for (size_t i = 0; i < eventCount; ++i) {
            if (!trafficEvents[i]->description || !*trafficEvents[i]->description) { 
                free(trafficEvents[i]->eventType);
                free(trafficEvents[i]->description);
                free(trafficEvents[i]);
                trafficEvents[i] = NULL;
            }
        }

        // Adjust eventCount after cleanup
        size_t newEventCount = 0;
        for (size_t i = 0; i < eventCount; ++i) {
            if (trafficEvents[i]) {
                trafficEvents[newEventCount++] = trafficEvents[i];
            }
        }
        eventCount = newEventCount;

        // Clean up unused items in the pool
        for (size_t i = 0; i < itemCount; ++i) {
            if (itemPool[i].uniqueID && !*itemPool[i].uniqueID) { 
                free(itemPool[i].uniqueID);
                itemPool[i] = itemPool[--itemCount];
                --i;
            }
        }

        pthread_mutex_unlock(&mutex);
    }
}

// Function to start the periodic cleanup in a separate thread
void startCleanupThread() {
    pthread_t cleanupThread;
    pthread_create(&cleanupThread, NULL, (void* (*)(void*))periodicCleanup, NULL);
}
