#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

typedef struct Metadata {
    // Define metadata fields as needed.
} Metadata;

typedef struct Record {
    long offset;
    int key1, key2;
    int value;
    int *key_ptr;
    Metadata *metadata_ptr;
} Record;

typedef struct RecordArray {
    size_t capacity;
    size_t count;
    Record *records;
    pthread_mutex_t lock;
    double running_total;
    double max_value;
    double min_value;
    double decay_factor;  // Decay factor to adjust influence of older values
} RecordArray;

void initialize_record_array(RecordArray *arr, size_t initial_capacity) {
    arr->capacity = initial_capacity;
    arr->count = 0;
    arr->records = (Record *)malloc(initial_capacity * sizeof(Record));
    pthread_mutex_init(&arr->lock, NULL);
    arr->running_total = 0.0;
    arr->max_value = -1.0;
    arr->min_value = 1.0;
    arr->decay_factor = 0.9; // Example decay factor
}

void destroy_record_array(RecordArray *arr) {
    free(arr->records);
    pthread_mutex_destroy(&arr->lock);
}

int random_int_in_range(int min, int max) {
    return rand() % (max - min + 1) + min;
}

void update_running_total(double new_value, RecordArray *arr) {
    double old_average = arr->running_total / ((double)arr->count);
    double adjusted_new_value = (old_average * (1.0 - arr->decay_factor)) +
                                (new_value * arr->decay_factor);

    // Update max and min values
    if (adjusted_new_value > arr->max_value) {
        arr->max_value = adjusted_new_value;
    }
    if (adjusted_new_value < arr->min_value) {
        arr->min_value = adjusted_new_value;
    }

    arr->running_total += (adjusted_new_value - old_average);
}

int add_record(RecordArray *arr, long offset, int key1, int key2) {
    pthread_mutex_lock(&arr->lock);

    if (arr->count >= arr->capacity) {
        size_t new_capacity = arr->capacity * 2;
        Record *new_records = (Record *)realloc(arr->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&arr->lock);
            return -1; // Memory allocation failed
        }
        arr->records = new_records;
        arr->capacity = new_capacity;
    }

    Record *rec = &arr->records[arr->count];
    rec->offset = offset;
    rec->key1 = key1;
    rec->key2 = key2;

    int avg_based_range_min = (int)(arr->min_value + 0.5);
    int avg_based_range_max = (int)(arr->max_value + 0.5);

    rec->value = random_int_in_range(avg_based_range_min, avg_based_range_max);
    rec->key_ptr = &rec->key1;
    rec->metadata_ptr = NULL; // Assign as needed

    update_running_total(rec->value, arr);

    arr->count++;
    pthread_mutex_unlock(&arr->lock);

    return 0; // Success
}

void adjust_value_distribution(RecordArray *arr) {
    double current_avg = arr->running_total / ((double)arr->count);
    if (current_avg > arr->max_value) {
        arr->max_value = current_avg;
    }
    if (current_avg < arr->min_value) {
        arr->min_value = current_avg;
    }

    for (size_t i = 0; i < arr->count; ++i) {
        double adjusted_new_value = arr->records[i].value;

        // Update max and min values
        if (adjusted_new_value > arr->max_value) {
            arr->max_value = adjusted_new_value;
        }
        if (adjusted_new_value < arr->min_value) {
            arr->min_value = adjusted_new_value;
        }

        update_running_total(adjusted_new_value, arr);
    }
}

int main() {
    srand(time(NULL));

    RecordArray arr;
    initialize_record_array(&arr, 10);

    for (int i = 0; i < 100; ++i) {
        add_record(&arr, i, rand(), rand());
    }

    adjust_value_distribution(&arr);

    printf("Running total: %f\n", arr.running_total);
    printf("Max value: %f\n", arr.max_value);
    printf("Min value: %f\n", arr.min_value);

    destroy_record_array(&arr);
    return 0;
}
```

This code provides a basic implementation of dynamic memory management for records in C, supporting efficient resizing and concurrent updates. It uses mutexes to ensure thread safety during modifications. Adjustments are made based on a running total influenced by a decay factor, which helps manage the influence of older values. The custom allocator is simple, using `realloc` for resizing. Consider profiling this solution under your specific workload conditions to evaluate its efficiency and make further optimizations as needed.']

['Here's a C implementation to manage a dynamic list of `NFAPI_CRC_INDICATION_PDU_T` structures as per your specifications:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef void (*Callback)(const char* message);

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t count;
    pthread_rwlock_t lock;
    Callback on_max_capacity;
    Callback on_compact_initiated;
} CRCList;

#define INITIAL_CAPACITY 10
#define MAX_CAPACITY 100

void notify(const char* message, Callback callback) {
    if (callback != NULL) {
        callback(message);
    }
}

CRCList* create_crc_list(Callback on_max_capacity_cb, Callback on_compact_cb) {
    CRCList* list = malloc(sizeof(CRCList));
    if (!list) return NULL;

    pthread_rwlock_init(&list->lock, NULL);
    list->data = malloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    list->capacity = INITIAL_CAPACITY;
    list->count = 0;
    list->on_max_capacity = on_max_capacity_cb;
    list->on_compact_initiated = on_compact_cb;

    return list;
}

int add_crc_pdu(CRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_rwlock_wrlock(&list->lock);

    if (list->count >= MAX_CAPACITY) {
        notify("Max capacity reached", list->on_max_capacity);
        pthread_rwlock_unlock(&list->lock);
        return -1;
    }

    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_rwlock_unlock(&list->lock);
            return -1; // Handle memory allocation failure
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }

    for (size_t i = 0; i < list->count; ++i) {
        if (list->data[i].RNTI == pdu.RNTI) {
            list->data[i] = pdu;
            break;
        }
    } else {
        list->data[list->count++] = pdu;
    }

    compact_crc_list(list);
    pthread_rwlock_unlock(&list->lock);

    return 0;
}

int remove_crc_pdu(CRCList* list, int rnti) {
    pthread_rwlock_wrlock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->data[i].RNTI == rnti) {
            memmove(&list->data[i], &list->data[i + 1], (list->count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            --list->count;
            compact_crc_list(list);
            break;
        }
    }

    pthread_rwlock_unlock(&list->lock);

    return 0;
}

int update_crcflag(CRCList* list, int rnti, int crcflag) {
    pthread_rwlock_wrlock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->data[i].RNTI == rnti) {
            list->data[i].CRC_INDICATION_REL8_TAG.CRCFLAG = crcflag;
            break;
        }
    }

    pthread_rwlock_unlock(&list->lock);

    return 0;
}

size_t get_crc_list_count(CRCList* list) {
    pthread_rwlock_rdlock(&list->lock);
    size_t count = list->count;
    pthread_rwlock_unlock(&list->lock);
    return count;
}

int export_crc_list(const CRCList* list, void** buffer, size_t* length) {
    pthread_rwlock_rdlock(&list->lock);

    *length = list->count * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    *buffer = malloc(*length);
    if (!*buffer) {
        pthread_rwlock_unlock(&list->lock);
        return -1;
    }

    memcpy(*buffer, list->data, *length);

    pthread_rwlock_unlock(&list->lock);
    return 0;
}

void compact_crc_list(CRCList* list) {
    notify("Compact operation initiated", list->on_compact_initiated);

    size_t write_index = 0;

    for (size_t i = 0; i < list->count; ++i) {
        if (list->data[i].CRC_INDICATION_REL8_TAG.CRCFLAG != 0) {
            list->data[write_index++] = list->data[i];
        }
    }

    list->count = write_index;
}

void free_crc_list(CRCList* list) {
    pthread_rwlock_destroy(&list->lock);
    free(list->data);
    free(list);
}
```

### Explanation:
- **Thread Safety**: Utilizes `pthread_rwlock_t` for concurrency control, allowing multiple readers or a single writer.
- **Dynamic Resizing**: Doubles the capacity when necessary but respects maximum capacity constraints.
- **Compacting and Callbacks**: Compacts on each modification, removing entries with zero `CRCFLAG`, and uses callbacks for notifications.
- **Export Functionality**: Exports list contents to binary format.
- **Memory Management**: Handles allocation failures gracefully.

This code provides a robust starting point for managing the dynamic list of `NFAPI_CRC_INDICATION_PDU_T` structures in a concurrent environment. Adjustments may be needed based on specific external service integration requirements or additional performance tuning needs.']

