#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>
#include <openssl/md5.h>

#define MAX_RECORDS 1000
#define INITIAL_CAPACITY 10

typedef struct {
    int value;
    int key_ref;
    char metadata[256];
} Record;

typedef struct {
    long *vertices;
    int *keys;
    Record *records;
    size_t vertex_count;
    size_t record_count;
    pthread_mutex_t lock;
    double total_sum;
    double access_frequency_sum;
    int access_count;
} Graph;

Graph* initialize_graph() {
    Graph *graph = malloc(sizeof(Graph));
    if (!graph) return NULL;

    graph->vertices = calloc(INITIAL_CAPACITY, sizeof(long));
    graph->keys = calloc(INITIAL_CAPACITY, sizeof(int));
    graph->records = calloc(INITIAL_CAPACITY, sizeof(Record));

    if (!graph->vertices || !graph->keys || !graph->records) {
        free(graph->vertices);
        free(graph->keys);
        free(graph->records);
        free(graph);
        return NULL;
    }

    pthread_mutex_init(&graph->lock, NULL);

    graph->vertex_count = 0;
    graph->record_count = 0;
    graph->total_sum = 0.0;
    graph->access_frequency_sum = 0.0;
    graph->access_count = 0;

    return graph;
}

void resize_graph(Graph *graph) {
    pthread_mutex_lock(&graph->lock);

    size_t new_capacity = graph->vertex_count ? (graph->vertex_count * 2) : INITIAL_CAPACITY;
    long *new_vertices = realloc(graph->vertices, new_capacity * sizeof(long));
    int *new_keys = realloc(graph->keys, new_capacity * sizeof(int));
    Record *new_records = realloc(graph->records, new_capacity * sizeof(Record));

    if (new_vertices && new_keys && new_records) {
        graph->vertices = new_vertices;
        graph->keys = new_keys;
        graph->records = new_records;
    } else {
        // Handle allocation failure
        fprintf(stderr, "Memory reallocation failed\n");
        pthread_mutex_unlock(&graph->lock);
        return;
    }

    pthread_mutex_unlock(&graph->lock);
}

void free_graph(Graph *graph) {
    if (graph) {
        pthread_mutex_destroy(&graph->lock);
        free(graph->vertices);
        free(graph->keys);
        free(graph->records);
        free(graph);
    }
}

const unsigned char* compute_md5(const char* str) {
    MD5_CTX mdContext;
    unsigned char hash[MD5_DIGEST_LENGTH];

    MD5_Init(&mdContext);
    MD5_Update(&mdContext, str, strlen(str));
    MD5_Final(hash, &mdContext);

    return hash;
}

void serialize_graph(Graph *graph, const char* filename) {
    pthread_mutex_lock(&graph->lock);

    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for serialization\n");
        pthread_mutex_unlock(&graph->lock);
        return;
    }

    fwrite(&graph->vertex_count, sizeof(size_t), 1, file);
    fwrite(graph->vertices, sizeof(long), graph->vertex_count, file);
    fwrite(graph->keys, sizeof(int), graph->vertex_count, file);

    for (size_t i = 0; i < graph->record_count; ++i) {
        fwrite(&graph->records[i], sizeof(Record), 1, file);
    }

    fclose(file);
    pthread_mutex_unlock(&graph->lock);
}

void deserialize_graph(Graph *graph, const char* filename) {
    pthread_mutex_lock(&graph->lock);

    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for deserialization\n");
        pthread_mutex_unlock(&graph->lock);
        return;
    }

    fread(&graph->vertex_count, sizeof(size_t), 1, file);
    resize_graph(graph); // Ensure capacity
    fread(graph->vertices, sizeof(long), graph->vertex_count, file);
    fread(graph->keys, sizeof(int), graph->vertex_count, file);

    for (size_t i = 0; i < graph->record_count; ++i) {
        fread(&graph->records[i], sizeof(Record), 1, file);
    }

    fclose(file);
    pthread_mutex_unlock(&graph->lock);
}

void add_random_vertices_and_edges(Graph *graph) {
    pthread_mutex_lock(&graph->lock);

    for (size_t i = 0; i < graph->vertex_count; ++i) {
        graph->vertices[i] = rand() % 10000;
        graph->keys[i] = rand() % 1000;

        if (graph->record_count >= MAX_RECORDS) {
            resize_graph(graph);
        }

        Record new_record;
        new_record.value = rand() % 100; // Random edge weight
        snprintf(new_record.metadata, sizeof(new_record.metadata), "Edge metadata for vertex %zu", i);

        graph->records[graph->record_count++] = new_record;
    }

    pthread_mutex_unlock(&graph->lock);
}

void log_event(const char *message) {
    printf("[LOG] %s\n", message);
}

int main() {
    srand(time(NULL));

    Graph *graph = initialize_graph();
    if (!graph) return EXIT_FAILURE;

    add_random_vertices_and_edges(graph);

    const unsigned char* md5_hash = compute_md5("specific_key");
    printf("MD5 Hash: ");
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i)
        printf("%02x", md5_hash[i]);
    printf("\n");

    serialize_graph(graph, "graph_state.dat");
    deserialize_graph(graph, "graph_state.dat");

    free_graph(graph);
    return EXIT_SUCCESS;
}
```

