    interface->successful_operations = 0;
    interface->failed_operations = 0;
    interface->total_latency = 0.0;
    interface->throughput = 0.0;

    return interface;
}

void update_configuration(NetworkInterface *interface, Config new_config) {
    pthread_rwlock_wrlock(&interface->config_lock);
    // Update configuration logic
    memcpy(&(interface->current_config), &new_config, sizeof(Config));
    pthread_rwlock_unlock(&interface->config_lock);
}

int add_packet(NetworkInterface *interface, unsigned long timestamp, size_t packet_size, const char *data) {
    if (packet_size > interface->current_config.max_packet_size) return -1;

    pthread_mutex_lock(&interface->mutex);

    if (interface->count == interface->capacity) {
        // Resize the array
        size_t new_capacity = interface->capacity * 2;
        Packet *new_packets = (Packet *)realloc(interface->packets, new_capacity * sizeof(Packet));
        if (!new_packets) {
            pthread_mutex_unlock(&interface->mutex);
            return -1; // Out of memory error
        }
        interface->packets = new_packets;
        interface->capacity = new_capacity;
    }

    Packet *packet = &interface->packets[interface->count++];
    packet->timestamp = timestamp;
    packet->packet_size = packet_size;

    if (data == NULL || !validate_packet_data(data, packet_size)) {
        // Handle malformed packet
        pthread_mutex_unlock(&interface->mutex);
        interface->failed_operations++;
        log_error("Malformed packet data");
        return -1; // Malformed packet error
    }

    packet->data = strdup(data);
    if (!packet->data) {
        pthread_mutex_unlock(&interface->mutex);
        interface->failed_operations++;
        log_error("Failed to allocate memory for packet data");
        return -1;
    }

    interface->successful_operations++;

    pthread_mutex_unlock(&interface->mutex);
    return 0; // Success
}

