#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_SIZE 16
#define LOAD_FACTOR 0.75

typedef struct {
    int id;
    float value;
    time_t timestamp;
} UserDefinedData;

typedef struct HashEntry {
    char *key;
    UserDefinedData data;
    struct HashEntry *next; // For collision resolution via chaining
} HashEntry;

typedef struct {
    HashEntry **table;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} ResizingHashTable;

// Utility function to generate a random integer within a range
int getRandomInRange(int min, int max) {
    return rand() % (max - min + 1) + min;
}

void initHashTable(ResizingHashTable *hashTable) {
    hashTable->capacity = INITIAL_SIZE;
    hashTable->count = 0;
    hashTable->table = malloc(sizeof(HashEntry *) * hashTable->capacity);
    memset(hashTable->table, 0, sizeof(HashEntry *) * hashTable->capacity);
    pthread_mutex_init(&hashTable->lock, NULL);
}

unsigned long hashFunction(const char *key, size_t capacity) {
    unsigned long hash = 5381;
    int c;

    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c

    return hash % capacity;
}

void resizeHashTable(ResizingHashTable *hashTable);

HashEntry* createHashEntry(const char *key, UserDefinedData data) {
    HashEntry *entry = malloc(sizeof(HashEntry));
    entry->key = strdup(key);
    entry->data = data;
    entry->next = NULL;
    return entry;
}

void insert(ResizingHashTable *hashTable, const char *key, UserDefinedData data) {
    pthread_mutex_lock(&hashTable->lock);

    unsigned long index = hashFunction(key, hashTable->capacity);
    HashEntry *entry = createHashEntry(key, data);

    if (hashTable->table[index]) {
        entry->next = hashTable->table[index];
    }
    hashTable->table[index] = entry;
    hashTable->count++;

    if ((float)hashTable->count / hashTable->capacity > LOAD_FACTOR) {
        resizeHashTable(hashTable);
    }

    pthread_mutex_unlock(&hashTable->lock);
}

void resizeHashTable(ResizingHashTable *hashTable) {
    size_t newCapacity = 2 * hashTable->capacity;
    HashEntry **newTable = malloc(sizeof(HashEntry *) * newCapacity);
    memset(newTable, 0, sizeof(HashEntry *) * newCapacity);

    for (size_t i = 0; i < hashTable->capacity; ++i) {
        HashEntry *entry = hashTable->table[i];
        while (entry) {
            unsigned long newIndex = hashFunction(entry->key, newCapacity);
            HashEntry *next = entry->next;

            if (!newTable[newIndex]) {
                newTable[newIndex] = entry;
            } else {
                // Insert at beginning for efficiency
                entry->next = newTable[newIndex];
                newTable[newIndex] = entry;
            }

            entry = next;
        }
    }

    free(hashTable->table);
    hashTable->table = newTable;
    hashTable->capacity = newCapacity;
}

void freeHashTable(ResizingHashTable *hashTable) {
    pthread_mutex_lock(&hashTable->lock);

    for (size_t i = 0; i < hashTable->capacity; ++i) {
        HashEntry *entry = hashTable->table[i];
        while (entry) {
            HashEntry *next = entry->next;
            free(entry->key);
            free(entry);
            entry = next;
        }
    }

    free(hashTable->table);
    pthread_mutex_unlock(&hashTable->lock);

    pthread_mutex_destroy(&hashTable->lock);
}

void iterateHashTable(ResizingHashTable *hashTable, void (*callback)(const char*, UserDefinedData)) {
    pthread_mutex_lock(&hashTable->lock);

    for (size_t i = 0; i < hashTable->capacity; ++i) {
        HashEntry *entry = hashTable->table[i];
        while (entry) {
            callback(entry->key, entry->data);
            entry = entry->next;
        }
    }

    pthread_mutex_unlock(&hashTable->lock);
}

// Example of a function that calculates dynamic range for random values
int calculateDynamicRange(ResizingHashTable *hashTable, int defaultMin, int defaultMax) {
    // This is just an example logic; actual implementation might differ
    int sum = 0;
    for (size_t i = 0; i < hashTable->capacity; ++i) {
        HashEntry *entry = hashTable->table[i];
        while (entry) {
            sum += entry->data.id;
            entry = entry->next;
        }
    }

    int average = hashTable->count ? sum / hashTable->count : defaultMin;

    // Adjust the range based on the calculated average
    return (average + 10 > defaultMax) ? defaultMin : average + 10;
}

// Example usage of initializing user-defined data and inserting it into a hash table.
void addRandomData(ResizingHashTable *hashTable, const char *key, int minRange, int maxRange) {
    pthread_mutex_lock(&hashTable->lock);

    // Calculate the dynamic range for random values
    int dynamicMax = calculateDynamicRange(hashTable, minRange, maxRange);
    UserDefinedData data;
    data.id = getRandomInRange(minRange, dynamicMax);
    data.value = (float)rand() / RAND_MAX;  // Random float
    data.timestamp = time(NULL);

    insert(hashTable, key, data);

    pthread_mutex_unlock(&hashTable->lock);
}

// Main function demonstrating usage
int main() {
    ResizingHashTable hashTables[2];

    srand(time(NULL));

    for (size_t i = 0; i < sizeof(hashTables) / sizeof(ResizingHashTable); ++i) {
        initHashTable(&hashTables[i]);
    }

    // Example of adding data concurrently can be added here

    freeHashTable(&hashTables[0]);
    freeHashTable(&hashTables[1]);

    return 0;
}
