#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>

#define MAX_CONNECTIONS 1000

typedef struct {
    char ip_address[16];
    uint16_t port_number;
    int connection_status; // e.g., 1 for active, 0 for inactive
    size_t packet_count;
    double average_latency;
} Connection;

typedef struct {
    Connection *connections[MAX_CONNECTIONS];
    pthread_mutex_t lock;
    size_t count;
    size_t capacity;
} ConnectionPool;

ConnectionPool* create_connection_pool(size_t initial_capacity) {
    ConnectionPool *pool = (ConnectionPool *)malloc(sizeof(ConnectionPool));
    if (!pool) return NULL;

    pool->count = 0;
    pool->capacity = initial_capacity;
    for (size_t i = 0; i < initial_capacity; ++i) {
        pool->connections[i] = NULL;
    }
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

int add_connection(ConnectionPool *pool, const char *ip_address, uint16_t port_number) {
    pthread_mutex_lock(&pool->lock);

    if (pool->count >= pool->capacity) {
        size_t new_capacity = pool->capacity + 100; // Increment by a fixed amount
        Connection **new_connections = realloc(pool->connections, new_capacity * sizeof(Connection *));
        if (!new_connections) {
            pthread_mutex_unlock(&pool->lock);
            return -1;
        }
        memset(new_connections + pool->capacity, 0, (new_capacity - pool->capacity) * sizeof(Connection *));
        pool->connections = new_connections;
        pool->capacity = new_capacity;
    }

    Connection *conn = (Connection *)malloc(sizeof(Connection));
    if (!conn) {
        pthread_mutex_unlock(&pool->lock);
        return -1;
    }

    strncpy(conn->ip_address, ip_address, sizeof(conn->ip_address) - 1);
    conn->port_number = port_number;
    conn->connection_status = 1;
    conn->packet_count = 0;
    conn->average_latency = 0.0;

    pool->connections[pool->count++] = conn;

    pthread_mutex_unlock(&pool->lock);
    return 0;
}

void remove_connection(ConnectionPool *pool, const char *ip_address) {
    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->count; ++i) {
        if (strcmp(pool->connections[i]->ip_address, ip_address) == 0) {
            free(pool->connections[i]);
            pool->connections[i] = pool->connections[--pool->count];
            break;
        }
    }

    pthread_mutex_unlock(&pool->lock);
}

void serialize_state(ConnectionPool *pool, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&pool->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < pool->count; ++i) {
        fwrite(pool->connections[i], sizeof(Connection), 1, file);
    }

    fclose(file);
}

void deserialize_state(ConnectionPool *pool, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < count; ++i) {
        Connection *conn = (Connection *)malloc(sizeof(Connection));
        if (!conn) continue;

        fread(conn, sizeof(Connection), 1, file);
        pool->connections[pool->count++] = conn;
    }
    pthread_mutex_unlock(&pool->lock);

    fclose(file);
}

void integrate_with_ui(ConnectionPool *pool, const char **field_names, size_t field_count) {
    for (size_t i = 0; i < pool->count; ++i) {
        Connection *conn = pool->connections[i];

        for (size_t j = 0; j < field_count; ++j) {
            if (strcmp(conn->ip_address, field_names[j]) == 0) {
                // Send message to parent window with the field name
                printf("Refreshing field for IP: %s\n", conn->ip_address);

                // Update connection statistics or any other UI element as needed
                // Example: printf("Packet count: %zu\n", conn->packet_count);
            }
        }
    }
}

void cleanup_connection_pool(ConnectionPool *pool) {
    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->count; ++i) {
        free(pool->connections[i]);
    }

    free(pool->connections);
    pthread_mutex_unlock(&pool->lock);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

int main() {
    ConnectionPool *pool = create_connection_pool(10);

    add_connection(pool, "192.168.1.1", 8080);
    add_connection(pool, "192.168.1.2", 8081);

    const char *fields[] = {"192.168.1.1"};
    integrate_with_ui(pool, fields, 1);

    serialize_state(pool, "connections.bin");
    deserialize_state(pool, "connections.bin");

    remove_connection(pool, "192.168.1.1");

    cleanup_connection_pool(pool);
    return 0;
}
```

