    uint32_t age;
    uint16_t rnti;
} RX_UE_INFORMATION_TAG;

typedef struct {
    uint8_t crcflag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_ind_rel8_tag;
    float weighted_importance_score;
} NFAPI_CRC_INDICATION_PDU_T;

// Network condition monitoring
typedef struct {
    float current_load;  // Simulated network load
    float available_bandwidth; // Simulated bandwidth
} NetworkCondition;

// Performance metrics
typedef struct {
    uint64_t throughput;
    double latency;
    double error_rate;
} PerformanceMetrics;

// Mutex for thread safety and logging
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void log_message(const char* message);
void update_performance_metrics(PerformanceMetrics* metrics, uint64_t processed_packets, double time_spent);

// Global variables for dynamic adjustments
NetworkCondition global_network_condition;
PerformanceMetrics global_performance_metrics;
uint64_t total_processed_packets = 0;

// Main processing function
NFAPI_CRC_INDICATION_PDU_T* process_packet_stream(NFAPI_CRC_INDICATION_PDU_T** output_list, size_t max_count) {
    static pthread_mutex_t data_mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&data_mutex);

    NFAPI_CRC_INDICATION_PDU_T* list = malloc(max_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        log_message("Memory allocation failed");
        return NULL;
    }

    size_t count = 0;
    float highest_score = -1.0f;
    uint16_t highest_packet_id = 0;

    // Simulated packet stream processing
    for (size_t i = 0; i < max_count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;

        // Randomly populate the structure for demonstration purposes
        pdu.ue_info_tag.age = rand() % 1000;
        pdu.rnti = rand();
        pdu.crc_ind_rel8_tag.crcflag = rand() & 1;
        pdu.weighted_importance_score = (float)rand() / RAND_MAX;

        // Filter based on criteria
        if (pdu.ue_info_tag.age < 150 && pdu.weighted_importance_score > 0.5) {
            if (count < max_count) {
                list[count++] = pdu;
                if (pdu.weighted_importance_score > highest_score) {
                    highest_score = pdu.weighted_importance_score;
                    highest_packet_id = pdu.rnti;
                }
            } else {
                break;  // Exceeded specified limit
            }
        }
    }

    // Validate integrity of the populated structures
    for (size_t i = 0; i < count; ++i) {
        if (!list[i].ue_info_tag.age || !list[i].rnti) {
            log_message("Validation failed");
            free(list);
            return NULL;
        }
    }

    *output_list = list;

    // Update performance metrics
    update_performance_metrics(&global_performance_metrics, count, 1.0);

    pthread_mutex_unlock(&data_mutex);
    return list;
}

// Logging function for thread-safe logging
void log_message(const char* message) {
    pthread_mutex_lock(&log_mutex);
    printf("Log: %s\n", message);
    pthread_mutex_unlock(&log_mutex);
}

// Update performance metrics with calculated values
void update_performance_metrics(PerformanceMetrics* metrics, uint64_t processed_packets, double time_spent) {
    static struct timespec last_update = {0};
    struct timespec current_time;
    clock_gettime(CLOCK_REALTIME, &current_time);

    if (last_update.tv_sec == 0 || (current_time.tv_sec - last_update.tv_sec >= 1)) {
        metrics->throughput += processed_packets;
        // Placeholder for actual latency calculation
        metrics->latency = time_spent / (double)processed_packets;
        metrics->error_rate = fmod(time_spent, 1.0);

        last_update = current_time;
    }
}

// Entry point for demonstration purposes
int main() {
    NFAPI_CRC_INDICATION_PDU_T* output_list = NULL;
    size_t max_count = 100;

    output_list = process_packet_stream(&output_list, max_count);

    if (output_list) {
        printf("Processing complete. Highest score: %.2f for packet ID %u\n",
               highest_score, highest_packet_id);
        free(output_list);
    }

    return 0;
}
