void generate_random_message(char *message, size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    if (length > 0) {
        --length; // Leave space for the null terminator
        for (size_t n = 0; n < length; ++n) {
            int key = rand() % (int)(sizeof(charset) - 1);
            message[n] = charset[key];
        }
        message[length] = '\0';
    } else {
        *message = '\0';
    }
}

void add_log_entry(log_entry **entries, float timestamp, char *level, const char *message) {
    size_t new_size = (*entries == NULL ? 1 : (sizeof(*entries) / sizeof(**entries)) + 1);
    log_entry *new_entries = realloc(*entries, new_size * sizeof(log_entry));
    if (!new_entries) {
        perror("Failed to allocate memory for log entries");
        exit(EXIT_FAILURE);
    }
    *entries = new_entries;

    log_entry *entry = &((*entries)[new_size - 1]);
    entry->timestamp = timestamp;
    entry->level = strdup(level); // Manage level string separately
    strncpy(entry->message, message, MAX_MESSAGE_LENGTH);
}

void process_data_pipeline() {
    float *timestamps = malloc(MAX_LOG_ENTRIES * sizeof(float));
    char **log_levels = malloc(MAX_LOG_ENTRIES * sizeof(char *));
    log_entry *entries = NULL;

    if (!timestamps || !log_levels) {
        perror("Failed to allocate memory for timestamps or log levels");
        exit(EXIT_FAILURE);
    }

    const char *levels[] = {"INFO", "WARNING", "ERROR"};
    size_t num_levels = sizeof(levels) / sizeof(levels[0]);

    srand(time(NULL)); // Seed random number generator

    pthread_mutex_lock(&log_lock);

    for (size_t i = 0; i < MAX_LOG_ENTRIES; ++i) {
        float timestamp = (float)(rand() % 100000);
        char level_key = rand() % num_levels;
        char message[MAX_MESSAGE_LENGTH + 1];

        timestamps[i] = timestamp;
        log_levels[i] = strdup(levels[level_key]);
        generate_random_message(message, MIN_MESSAGE_LENGTH + rand() % (MAX_MESSAGE_LENGTH - MIN_MESSAGE_LENGTH));

        add_log_entry(&entries, timestamp, log_levels[i], message);

        // Log to backends
        for (int j = 0; j < sizeof(console_backend) / sizeof(logging_backend); ++j) {
            if (console_backend.log != NULL) {
                console_backend.log(entries + i);
            }
        }

        // Similarly, add logging for other backends like file_backend, etc.
    }

    pthread_mutex_unlock(&log_lock);

    free(timestamps);
    for (size_t i = 0; i < MAX_LOG_ENTRIES; ++i) {
        free(log_levels[i]);
    }
    free(log_levels);
    for (size_t i = 0; i < sizeof(entries)/sizeof(*entries); ++i) {
        free(entries[i].level);
    }
    free(entries);

    // Flush all backends
    console_backend.flush();
    file_backend.flush();
}

int main() {
    init_logging_backends();
    process_data_pipeline();
    return 0;
}
