    FIRST_FIT,
    BEST_FIT,
    WORST_FIT
} AllocationPolicy;

// Configuration structure
typedef struct {
    LogLevel logging_level;
    AllocationPolicy allocation_policy;
    unsigned int max_structures;
    pthread_mutex_t lock; // For thread safety
} Config;

// Function to dynamically generate and populate NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* generate_nfa_pi_crc_indications(
    unsigned int* ue_ids, size_t num_ues, unsigned int threshold,
    const Config* config, size_t* out_num_structures) {

    pthread_mutex_lock(&config->lock);

    if (!ue_ids || num_ues == 0 || !out_num_structures || !config) {
        log_message(config->logging_level, "Invalid input parameters.");
        pthread_mutex_unlock(&config->lock);
        return NULL;
    }

    size_t available_memory = get_available_memory();
    size_t max_possible_structures = available_memory / sizeof(NFAPI_CRC_INDICATION_PDU_T);

    if (max_possible_structures == 0) {
        log_message(config->logging_level, "Insufficient memory for any structure.");
        pthread_mutex_unlock(&config->lock);
        return NULL;
    }

    size_t num_structures = (num_ues > max_possible_structures || threshold < max_possible_structures)
                            ? max_possible_structures
                            : (threshold >= num_ues) ? num_ues : threshold;

    NFAPI_CRC_INDICATION_PDU_T* structures = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!structures) {
        log_message(config->logging_level, "Memory allocation failed.");
        pthread_mutex_unlock(&config->lock);
        return NULL;
    }

    for (size_t i = 0; i < num_structures; ++i) {
        structures[i].RX_UE_INFORMATION_TAG = ue_ids[i];
        structures[i].RNTI = ue_ids[i] + 100; // Example transformation
        structures[i].CRC_INDICATION_REL8_TAG.CRCFLAG = generate_random_crcflag();
    }

    *out_num_structures = num_structures;
    pthread_mutex_unlock(&config->lock);

    return structures;
}

