    Employee *foundEmp = find_employee(employeeTree->root, "Alice", compare);
    if (foundEmp) {
        printf("\nFound: %s\n", foundEmp->name);
    }

    // Further operations like delete_by_name, sorting by salary, etc.

    free_tree(employeeTree->root);
    free(employeeTree);

    return 0;
}
