```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <pthread.h>

typedef struct {
    char* data;
    int length;
} data_record;

typedef struct {
    long* offsets;
    int offset_count;

    int* keys;
    int key_count;

    data_record* records;
    int record_count;

    pthread_mutex_t lock; // For thread safety
} crypto_pipeline;

int init_crypto_pipeline(crypto_pipeline *pipeline, int offset_size, int key_size, int record_size) {
    if (!pipeline) return -1;

    pthread_mutex_init(&pipeline->lock, NULL);

    pipeline->offsets = (long*)calloc(offset_size, sizeof(long));
    pipeline->keys = (int*)calloc(key_size, sizeof(int));
    pipeline->records = (data_record*)malloc(record_size * sizeof(data_record));

    if (!pipeline->offsets || !pipeline->keys || !pipeline->records) {
        free(pipeline->offsets);
        free(pipeline->keys);
        free(pipeline->records);
        pthread_mutex_destroy(&pipeline->lock);
        return -1;
    }

    pipeline->offset_count = offset_size;
    pipeline->key_count = key_size;
    pipeline->record_count = record_size;

    // Register cryptographic algorithms
    if (EVP_add_cipher(EVP_aes_128_cbc()) != 1 ||
        EVP_add_digest(EVP_sha256()) != 1 ||
        EVP_PKEY_add_digest(0, EVP_sha256()) != 1 ||
        EVP_add_cipher(EVP_camellia_192_cbc()) != 1) {

        cleanup_pipeline(pipeline);
        return -1;
    }

    // Example: Initialize with some default keys/offsets/records
    for (int i = 0; i < offset_size; ++i) pipeline->offsets[i] = i * 10;
    for (int j = 0; j < key_size; ++j) pipeline->keys[j] = j + 1;

    for (int k = 0; k < record_size; ++k) {
        size_t data_length = (k + 1) * 5;
        pipeline->records[k].data = malloc(data_length);
        if (!pipeline->records[k].data) {
            cleanup_pipeline(pipeline);
            return -1;
        }
        memset(pipeline->records[k].data, 'A' + k % 26, data_length);
        pipeline->records[k].length = (int)data_length;
    }

    return 0; // Success
}

void cleanup_pipeline(crypto_pipeline *pipeline) {
    if (!pipeline) return;

    free(pipeline->offsets);
    free(pipeline->keys);

    for (int i = 0; i < pipeline->record_count; ++i)
        free(pipeline->records[i].data);

    free(pipeline->records);

    pthread_mutex_destroy(&pipeline->lock);
}

void encrypt_decrypt(crypto_pipeline *pipeline, const unsigned char *input, int input_len, 
                     unsigned char *output, int mode) {
    if (!pipeline || !input || !output) return;

    // Lock for thread safety
    pthread_mutex_lock(&pipeline->lock);

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        pthread_mutex_unlock(&pipeline->lock);
        return;
    }

    int out_len1, out_len2;
    unsigned char iv[16]; // Example IV for AES

    memset(iv, 0x00, sizeof(iv));

    if (mode == 1) { // Encryption
        if (!EVP_EncryptInit_ex(ctx, EVP_aes_128_cbc(), NULL, pipeline->keys, iv)) {
            goto cleanup;
        }
        if (!EVP_EncryptUpdate(ctx, output, &out_len1, input, input_len)) {
            goto cleanup;
        }
        if (!EVP_EncryptFinal_ex(ctx, output + out_len1, &out_len2)) {
            goto cleanup;
        }
    } else { // Decryption
        if (!EVP_DecryptInit_ex(ctx, EVP_aes_128_cbc(), NULL, pipeline->keys, iv)) {
            goto cleanup;
        }
        if (!EVP_DecryptUpdate(ctx, output, &out_len1, input, input_len)) {
            goto cleanup;
        }
        if (!EVP_DecryptFinal_ex(ctx, output + out_len1, &out_len2)) {
            goto cleanup;
        }
    }

cleanup:
    EVP_CIPHER_CTX_free(ctx);
    pthread_mutex_unlock(&pipeline->lock);
}

void periodic_update_keys(crypto_pipeline *pipeline) {
    // Placeholder: Update keys/algorithm configuration from an external source
    pthread_mutex_lock(&pipeline->lock);

    for (int i = 0; i < pipeline->key_count; ++i)
        pipeline->keys[i] += 1;

    pthread_mutex_unlock(&pipeline->lock);
}

int main() {
    crypto_pipeline pipeline;

    if (init_crypto_pipeline(&pipeline, 10, 10, 5) != 0) {
        fprintf(stderr, "Failed to initialize the crypto pipeline\n");
        return EXIT_FAILURE;
    }

    // Example usage
    unsigned char input[] = "Sensitive data for encryption";
    unsigned char output[128];

    encrypt_decrypt(&pipeline, (unsigned char *)input, strlen((char *)input), 
                    output, 1);

    encrypt_decrypt(&pipeline, output, sizeof(output), 
                    output, 0);

    printf("Decrypted: %s\n", output);

    cleanup_pipeline(&pipeline);
    return EXIT_SUCCESS;
}
```

This function includes memory management and cryptographic operations with OpenSSL. It initializes a data structure to hold arrays of `long`, `int`, and custom structures for records. Cryptographic algorithms are registered, and encryption/decryption functions handle input/output buffers. Thread safety is ensured using mutexes, and resources are freed properly to prevent leaks. The function supports periodic updates of cryptographic keys.']

