public class URLProcessor {

    private static final Logger logger = Logger.getLogger(URLProcessor.class.getName());
    private ConcurrentHashMap<String, Integer> tldCounts = new ConcurrentHashMap<>();
    private Set<String> excludedTlds;
    private ExecutorService executor;

    public URLProcessor() {
        this.excludedTlds = Collections.synchronizedSet(new HashSet<>());
        this.executor = Executors.newFixedThreadPool(10); // Adjust thread pool size based on expected load
    }

    public Map<String, Integer> processURLs(Stream<URL> urlStream) {
        urlStream.forEach(url -> executor.submit(() -> {
            long startTime = System.currentTimeMillis();
            try {
                String tld = extractTLD(new URL(url.toString()));
                if (tld == null || excludedTlds.contains(tld)) return;

                tldCounts.merge(tld, 1, Integer::sum);
                enrichTLDData(tld); // Non-blocking call to an external service

            } catch (MalformedURLException e) {
                logger.warning("Invalid URL: " + url + ", Time taken: " + (System.currentTimeMillis() - startTime));
            }
        }));

        executor.shutdown();
        return new HashMap<>(tldCounts);
    }

    private String extractTLD(URL url) throws MalformedURLException {
        try {
