            String host = url.getHost();
            int lastDotIndex = host.lastIndexOf('.');

            if (lastDotIndex == -1 || host.indexOf('.', lastDotIndex + 1) == -1) return null;

            return host.substring(lastDotIndex + 1);
        } catch (MalformedURLException e) {
            logger.warning("Malformed URL: " + url.toString());
            return null;
        }
