#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Define structures for resource and data objects.
typedef struct {
    char type[50];
    size_t size;
} Resource;

typedef struct {
    time_t timestamp;
    int status_flag;
    Resource *resource;
    double value;
} DataObject;

typedef struct {
    pthread_mutex_t lock;
    DataObject **objects;
    size_t count;
    size_t capacity;
    double total_value;
    size_t total_resource_size;
} DataManager;

// Function prototypes
void initialize_manager(DataManager *manager, size_t initial_capacity);
void destroy_manager(DataManager *manager);
DataObject* add_data_object(DataManager *manager, Resource *resource);
void update_status_flag(DataObject *obj);
double calculate_new_average_value(DataManager *manager, double new_value);
void remove_data_object(DataManager *manager, DataObject *obj);
void resize_manager(DataManager *manager, size_t new_capacity);
void aggregate_statistics(DataManager *manager);

// Initialize the manager
void initialize_manager(DataManager *manager, size_t initial_capacity) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->objects = malloc(initial_capacity * sizeof(DataObject*));
    manager->count = 0;
    manager->capacity = initial_capacity;
    manager->total_value = 0.0;
    manager->total_resource_size = 0;
}

// Destroy the manager and free resources
void destroy_manager(DataManager *manager) {
    pthread_mutex_destroy(&manager->lock);
    for (size_t i = 0; i < manager->count; i++) {
        if (manager->objects[i]->resource != NULL) {
            free(manager->objects[i]->resource);
        }
        free(manager->objects[i]);
    }
    free(manager->objects);
}

// Add a new data object
DataObject* add_data_object(DataManager *manager, Resource *resource) {
    pthread_mutex_lock(&manager->lock);

    // Resize if necessary
    if (manager->count == manager->capacity) {
        resize_manager(manager, manager->capacity * 2);
    }

    DataObject *new_obj = malloc(sizeof(DataObject));
    new_obj->timestamp = time(NULL);
    new_obj->resource = resource ? malloc(sizeof(Resource)) : NULL;
    if (new_obj->resource != NULL) {
        *new_obj->resource = *resource;
        manager->total_resource_size += resource->size;
    }
    new_obj->value = calculate_new_average_value(manager, 0.0); // initial value
    update_status_flag(new_obj);

    manager->objects[manager->count++] = new_obj;
    manager->total_value += new_obj->value;

    pthread_mutex_unlock(&manager->lock);
    return new_obj;
}

// Update status flag based on predefined conditions (simple example)
void update_status_flag(DataObject *obj) {
    if (time(NULL) % 2 == 0) {
        obj->status_flag = 1; // Arbitrary condition
    } else {
        obj->status_flag = 0;
    }
}

// Calculate new average value for a DataObject
double calculate_new_average_value(DataManager *manager, double new_value) {
    size_t total_objects = manager->count + (new_value != 0.0 ? 1 : 0);
    return (manager->total_value + new_value) / total_objects;
}

// Remove a data object and update manager's statistics
void remove_data_object(DataManager *manager, DataObject *obj) {
    pthread_mutex_lock(&manager->lock);

    size_t index = -1;
    for (size_t i = 0; i < manager->count; i++) {
        if (manager->objects[i] == obj) {
            index = i;
            break;
        }
    }

    if (index != -1) {
        if (obj->resource != NULL) {
            manager->total_resource_size -= obj->resource->size;
            free(obj->resource);
        }
        free(manager->objects[index]);

        for (size_t i = index; i < manager->count - 1; i++) {
            manager->objects[i] = manager->objects[i + 1];
        }
        manager->count--;

        if (manager->count > 0 && manager->capacity > initial_capacity) {
            resize_manager(manager, manager->capacity / 2);
        }

        manager->total_value -= obj->value;
    }

    pthread_mutex_unlock(&manager->lock);
}

// Resize the data objects array
void resize_manager(DataManager *manager, size_t new_capacity) {
    DataObject **new_objects = realloc(manager->objects, new_capacity * sizeof(DataObject*));

    if (new_objects != NULL) {
        manager->objects = new_objects;
        manager->capacity = new_capacity;
    }
}

// Aggregate statistics and report
void aggregate_statistics(DataManager *manager) {
    pthread_mutex_lock(&manager->lock);

    // Dummy implementation for aggregating stats
    printf("Total Resource Size: %zu\n", manager->total_resource_size);
    printf("Average Value of Records: %.2f\n", manager->count > 0 ? (manager->total_value / manager->count) : 0.0);

    pthread_mutex_unlock(&manager->lock);
}

// Main function for demonstration
int main() {
    DataManager manager;
    initialize_manager(&manager, 10); // Start with an initial capacity of 10

    Resource res1 = {.type = "Resource Type A", .size = 100};
    add_data_object(&manager, &res1);

    Resource res2 = {.type = "Resource Type B", .size = 200};
    add_data_object(&manager, &res2);

    aggregate_statistics(&manager);

    destroy_manager(&manager);
    return 0;
}
```

### Explanation:
- The `DataManager` structure manages dynamic collections of `DataObject`s.
- Concurrency is handled using a mutex (`pthread_mutex_t`) to ensure thread safety when accessing and modifying shared resources.
- Memory for data objects is dynamically allocated, with resizing mechanisms in place to manage capacity efficiently.
- Summary statistics are calculated and can be reported periodically.
- The code provides functions for initialization, adding/removing objects, updating status flags, calculating averages, resizing the collection, and destroying the manager.']

