['Below is a C++ implementation for the `manageGameEnvironment` function. This code includes thread-safe management of game environment components, a command history buffer, and optimizations for handling large numbers of objects efficiently.

```cpp
#include <iostream>
#include <vector>
#include <unordered_map>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <chrono>

struct Record {
    std::string actionType;
    double calculatedDistance;
};

class GameEnvironmentManager {
public:
    GameEnvironmentManager() 
        : cooldownPeriod(std::chrono::milliseconds(100)) {}

    void manageGameEnvironment(long offset, int id, const Record& record) {
        std::unique_lock<std::mutex> lock(mutex_);

        // Update game object coordinates
        coordinates_[id] = offset;

        // Store action in the command history buffer
        if (commandHistoryBuffer_.size() >= 50) {
            commandHistoryBuffer_.pop();
        }
        commandHistoryBuffer_.push({ id, record });

        // Optimize records' int values sum
        optimizeRecordsSum();

        lock.unlock();
        std::this_thread::sleep_for(cooldownPeriod);
    }

    void undoLastAction() {
        std::unique_lock<std::mutex> lock(mutex_);

        if (commandHistoryBuffer_.empty()) {
            std::cerr << "No operations to undo." << std::endl;
            return;
        }

        auto lastCommand = commandHistoryBuffer_.front();
        commandHistoryBuffer_.pop();

        // Undo the action
        coordinates_.erase(lastCommand.first);
    }

    void setCooldownPeriod(std::chrono::milliseconds period) {
        cooldownPeriod = period;
    }

private:
    struct Command {
        int id;
        Record record;
    };

    std::unordered_map<int, long> coordinates_;
    std::queue<Command> commandHistoryBuffer_;
    std::mutex mutex_;
    std::condition_variable cv_;
    std::chrono::milliseconds cooldownPeriod;

    void optimizeRecordsSum() {
        // Implement optimization logic here
        int sum = 0;
        for (const auto& [id, offset] : coordinates_) {
            sum += static_cast<int>(offset);
        }
        // Optimization logic can be added based on specific requirements
        std::cout << "Current sum of records' int values: " << sum << std::endl;
    }
};

int main() {
    GameEnvironmentManager manager;

    Record record1 = { "move", 10.5 };
    manager.manageGameEnvironment(100, 1, record1);

    Record record2 = { "attack", 20.0 };
    manager.manageGameEnvironment(200, 2, record2);

    manager.undoLastAction();

    return 0;
}
```

### Key Points:

- **Thread Safety**: The function uses a mutex to ensure thread-safe updates and access to shared resources.
- **Command History Buffer**: A queue is used to store the last 50 operations, allowing undo functionality.
- **Cooldown Period**: The cooldown period between actions can be adjusted dynamically.
- **Optimization**: The `optimizeRecordsSum` function calculates the sum of record values, which can be expanded with specific optimization logic as needed.
- **Error Handling**: Basic error handling is included for cases like attempting to undo without any recorded operations.']

