#define MAX_MEMORY_USAGE 1024 * 1024 // 1 MB limit for demonstration
#define CRCFLAG_PATTERN_SIZE 256

typedef struct {
    uint8_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Randomly set based on predefined pattern
} NFAPI_CRC_INDICATION_PDU_T;

static pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;
static size_t current_memory_usage = 0;
#define MEMORY_THRESHOLD MAX_MEMORY_USAGE

uint8_t crcflag_pattern[CRCFLAG_PATTERN_SIZE];

// Function to initialize the CRC flag pattern for specific RNTI values
void init_crcflag_pattern() {
    // Populate this with a predefined pattern, e.g., every even index is 1, odd is 0
    for (int i = 0; i < CRCFLAG_PATTERN_SIZE; ++i) {
        crcflag_pattern[i] = (i % 2 == 0) ? 1 : 0;
    }
}

// Function to generate a random patterned CRC flag based on RNTI
int get_crc_flag(uint16_t rnti) {
    return crcflag_pattern[rnti & 0xFF]; // Simple example using lower byte of RNTI
}

// Pool structure to manage dynamic memory for pdu structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t capacity;
    size_t count;
} PduPool;

PduPool *create_pdu_pool(size_t initial_capacity) {
    PduPool *pool = (PduPool *)malloc(sizeof(PduPool));
    if (!pool) return NULL;

    pool->pdus = (NFAPI_CRC_INDICATION_PDU_T *)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->pdus) {
        free(pool);
        return NULL;
    }

    pool->capacity = initial_capacity;
    pool->count = 0;

    pthread_mutex_lock(&pool_mutex);
    current_memory_usage += initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    pthread_mutex_unlock(&pool_mutex);

    return pool;
}

int add_pdu_to_pool(PduPool *pool, uint8_t tag, uint16_t rnti) {
    if (current_memory_usage + sizeof(NFAPI_CRC_INDICATION_PDU_T) > MEMORY_THRESHOLD) {
        fprintf(stderr, "Memory threshold exceeded\n");
        return -1; // Out of memory
    }

    pthread_mutex_lock(&pool_mutex);

    if (pool->count >= pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_pdus = realloc(pool->pdus, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pdus) {
            pthread_mutex_unlock(&pool_mutex);
            return -1; // Out of memory
        }

        pool->pdus = new_pdus;
        pool->capacity = new_capacity;

        current_memory_usage += (new_capacity - pool->capacity) * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = &pool->pdus[pool->count++];
    pdu->RX_UE_INFORMATION_TAG = tag;
    pdu->RNTI = rnti;
    pdu->CRC_INDICATION_REL8_TAG = 0; // Example value, can be set as needed
    pdu->CRCFLAG = get_crc_flag(rnti);

    pthread_mutex_unlock(&pool_mutex);

    return 0; // Success
}

void free_pdu_pool(PduPool *pool) {
    if (!pool) return;

    pthread_mutex_lock(&pool_mutex);
    current_memory_usage -= pool->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    pthread_mutex_unlock(&pool_mutex);

    free(pool->pdus);
    free(pool);
}

void* handle_pdu_requests(void *arg) {
    PduPool *pool = (PduPool *)arg;

    for (size_t i = 0; i < 100; ++i) { // Example loop, replace with actual logic
        uint8_t tag = rand() % 256;
        uint16_t rnti = rand() % CRCFLAG_PATTERN_SIZE;

        if (add_pdu_to_pool(pool, tag, rnti) != 0) {
            fprintf(stderr, "Failed to add PDU\n");
            break;
        }
    }

    return NULL;
}

int main() {
    init_crcflag_pattern();

    size_t pool_initial_capacity = 10; // Example initial capacity
    PduPool *pool = create_pdu_pool(pool_initial_capacity);
    if (!pool) {
        fprintf(stderr, "Failed to create PDU pool\n");
        return -1;
    }

    const int num_threads = 5;
    pthread_t threads[num_threads];

    for (int i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, handle_pdu_requests, pool)) {
            fprintf(stderr, "Failed to create thread\n");
            free_pdu_pool(pool);
            return -1;
        }
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    printf("Finished processing PDUs\n");

    free_pdu_pool(pool);
    return 0;
}
```

### Key Points:

- **Memory Management**: The pool dynamically resizes to accommodate more `NFAPI_CRC_INDICATION_PDU_T` structures, while ensuring memory usage does not exceed a set threshold.
- **Concurrency Handling**: A mutex (`pool_mutex`) ensures that operations on the shared pool are thread-safe.
- **Scalability**: The function can handle an increasing number of concurrent requests and pdus by resizing the internal array as needed.
