['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

// Define Packet structure
typedef struct {
    time_t timestamp;
    size_t packet_size;
    char *data; // Pointer to the actual packet data
} Packet;

// Dynamic array for storing packets
typedef struct {
    Packet **packets;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} PacketArray;

// Logging function (stub)
void log_packet_info(const char *info) {
    printf("LOG: %s\n", info);
}

// Function to initialize the packet array
PacketArray* init_packet_array(size_t initial_capacity) {
    PacketArray *packet_array = malloc(sizeof(PacketArray));
    if (!packet_array) return NULL;

    pthread_mutex_init(&packet_array->lock, NULL);

    packet_array->packets = calloc(initial_capacity, sizeof(Packet *));
    if (!packet_array->packets) {
        free(packet_array);
        return NULL;
    }

    packet_array->count = 0;
    packet_array->capacity = initial_capacity;

    return packet_array;
}

// Function to resize the packet array
int resize_packet_array(PacketArray *packet_array, size_t new_capacity) {
    Packet **new_packets = realloc(packet_array->packets, new_capacity * sizeof(Packet *));
    if (!new_packets) return -1; // Memory allocation failed

    packet_array->packets = new_packets;
    packet_array->capacity = new_capacity;

    return 0;
}

// Function to add a validated packet to the array
int add_packet(PacketArray *packet_array, const char *data, size_t data_size) {
    if (data_size == 0) return -1; // Invalid packet

    pthread_mutex_lock(&packet_array->lock);

    if (packet_array->count >= packet_array->capacity) {
        size_t new_capacity = packet_array->capacity * 2;
        if (resize_packet_array(packet_array, new_capacity)) {
            pthread_mutex_unlock(&packet_array->lock);
            return -1; // Resizing failed
        }
    }

    Packet *new_packet = malloc(sizeof(Packet));
    if (!new_packet) {
        pthread_mutex_unlock(&packet_array->lock);
        return -1;
    }

    new_packet->timestamp = time(NULL);
    new_packet->packet_size = data_size;
    new_packet->data = strdup(data);

    packet_array->packets[packet_array->count++] = new_packet;

    char log_entry[256];
    snprintf(log_entry, sizeof(log_entry), "Packet added at %ld with size %zu", new_packet->timestamp, new_packet->packet_size);
    log_packet_info(log_entry);

    pthread_mutex_unlock(&packet_array->lock);

    return 0;
}

// Cleanup function for packet array
void cleanup_packet_array(PacketArray *packet_array) {
    if (!packet_array) return;

    pthread_mutex_lock(&packet_array->lock);

    for (size_t i = 0; i < packet_array->count; ++i) {
        free(packet_array->packets[i]->data);
        free(packet_array->packets[i]);
    }

    free(packet_array->packets);
    pthread_mutex_unlock(&packet_array->lock);
    pthread_mutex_destroy(&packet_array->lock);

    free(packet_array);
}

// Example usage
int main() {
    PacketArray *packet_array = init_packet_array(10);
    if (!packet_array) return -1;

    const char *sample_data = "Sample packet data";
    add_packet(packet_array, sample_data, strlen(sample_data));

    cleanup_packet_array(packet_array);

    return 0;
}
