void insertIntoHashTable(CustomHashTable *ht, int key, Record *record) {
    unsigned long index = hashFunction(key);
    HashTableEntry *newEntry = (HashTableEntry *)malloc(sizeof(HashTableEntry));
    newEntry->key = key;
    newEntry->record = record;
    newEntry->next = ht->table[index];
    ht->table[index] = newEntry;
}

Record* lookupInHashTable(CustomHashTable *ht, int key) {
    unsigned long index = hashFunction(key);
    HashTableEntry *entry = ht->table[index];
    while (entry != NULL) {
