void initializeRecordSets(RecordSet **recordSets, size_t numReadings, size_t windowSize) {
    pthread_mutex_lock(&lock);

    size_t numWindows = (numReadings + windowSize - 1) / windowSize; // Ceil division
    *recordSets = malloc(numWindows * sizeof(RecordSet));

    if (*recordSets == NULL) {
        perror("Failed to allocate RecordSets");
        pthread_mutex_unlock(&lock);
        return;
    }

    for (size_t i = 0; i < numWindows; ++i) {
        (*recordSets)[i].records = malloc(windowSize * sizeof(MeasurementRecord*));
        if ((*recordSets)[i].records == NULL) {
            perror("Failed to allocate MeasurementRecords");
            // Cleanup
            for (size_t j = 0; j < i; ++j) {
                free((*recordSets)[j].records);
            }
            free(*recordSets);
            pthread_mutex_unlock(&lock);
            return;
        }

        (*recordSets)[i].count = 0;
        (*recordSets)[i].sum = 0.0;

        for (size_t j = i * windowSize; j < numReadings && j < (i + 1) * windowSize; ++j) {
            // Assuming records[] is an array of MeasurementRecord pointers
            // Initialize records[j] here and add to the current RecordSet
            (*recordSets)[i].records[(*recordSets)[i].count++] = &records[j];
            (*recordSets)[i].sum += records[j].value;
        }
    }

    pthread_mutex_unlock(&lock);
}

