    double averageProcessingTime = (dataProcessedCount > 0) ? totalProcessingTime / dataProcessedCount : 0;

    printf("Max Weighted Sum: %f, Sensor ID: %d\n", maxWeightedSum, correspondingSensorID);
    printf("Average Processing Time: %f ms, Data Throughput: %zu records\n",
           averageProcessingTime, *count);

    pthread_mutex_unlock(&lock);
}

void cleanupRecordSets(RecordSet *recordSets, size_t numWindows) {
    for (size_t i = 0; i < numWindows; ++i) {
