typedef struct {
    Record **records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    long running_total;
} RecordCollection;

// Utility function to dynamically resize the array
void resize_array(Record ***array, size_t *capacity) {
    size_t new_capacity = (*capacity) * 2;
    *array = realloc(*array, new_capacity * sizeof(Record *));
    if (!*array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    memset((*array) + *capacity, 0, (*capacity) * sizeof(Record *));
    *capacity = new_capacity;
}

// Function to initialize records
void init_records(RecordCollection *collection, int min_range, int max_range) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        Record *record = collection->records[i];

        // Initialize with a random integer value within the range
        int rand_value = rand() % (max_range - min_range + 1) + min_range;
        record->offset = rand_value;

        // Adjust range based on cumulative sum
        collection->running_total += rand_value;
        min_range = collection->running_total / (i + 1);
        max_range = min_range * 2;

        // Initialize key and metadata
        record->key = i; // Simplified for demonstration
        record->metadata.file_path = "path/to/image";
        record->metadata.width = 1024;
        record->metadata.height = 768;
        record->metadata.creation_timestamp = time(NULL);
        record->metadata.image_data = NULL;

        printf("Initialized record %zu with offset: %ld\n", i, record->offset);
    }

    pthread_mutex_unlock(&collection->lock);
}

// Function to dynamically manage memory for records
void manage_records(RecordCollection *collection, int min_range, int max_range) {
    if (collection->count >= collection->capacity) {
        resize_array(&(collection->records), &collection->capacity);
    }

    Record *new_record = malloc(sizeof(Record));
    if (!new_record) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    memset(new_record, 0, sizeof(Record));

    collection->records[collection->count++] = new_record;
}

// Function to serialize records
void serialize_records(const RecordCollection *collection) {
    pthread_mutex_lock(&collection->lock);

    FILE *file = fopen("records_state.dat", "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        exit(EXIT_FAILURE);
    }

    fwrite(collection->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < collection->count; ++i) {
        Record *record = collection->records[i];
        fwrite(&record->offset, sizeof(long), 1, file);
        fwrite(&record->key, sizeof(int), 1, file);
        // Serialize metadata if needed
    }

    fclose(file);

    pthread_mutex_unlock(&collection->lock);
}

// Function to load records from serialized state
void load_records(RecordCollection *collection) {
    FILE *file = fopen("records_state.dat", "rb");
    if (!file) return;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    resize_array(&(collection->records), &collection->capacity);
    collection->count = count;

    for (size_t i = 0; i < count; ++i) {
        Record *record = malloc(sizeof(Record));
        if (!record) exit(EXIT_FAILURE);

        fread(&record->offset, sizeof(long), 1, file);
        fread(&record->key, sizeof(int), 1, file);
        // Deserialize metadata if needed

        collection->records[i] = record;
    }

    fclose(file);
}

// Function to process image metadata
