    collection.capacity = INITIAL_CAPACITY;
    collection.records = malloc(collection.capacity * sizeof(Record *));
    if (!collection.records) exit(EXIT_FAILURE);

    pthread_mutex_init(&collection.lock, NULL);

    // Example usage
    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        manage_records(&collection, 1, 100);
    }

    init_records(&collection, 1, 100);
