```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_EVENTS 5000
#define MAX_THREADS 10000
#define OFFSET_ARRAY_SIZE 1000
#define KEY_ARRAY_SIZE 1000
#define MEMORY_LIMIT (1024 * 1024 * 50) // Example memory limit: 50 MB

typedef struct {
    int event_id;
    time_t timestamp;
    void* data; // Pointer to event-specific data
} Event;

typedef struct {
    long offsets[OFFSET_ARRAY_SIZE];
    int keys[KEY_ARRAY_SIZE];
    Event events[MAX_EVENTS];
    pthread_mutex_t lock;
    size_t used_events;
} EventManager;

EventManager* initialize_event_manager() {
    EventManager* manager = (EventManager*)malloc(sizeof(EventManager));
    if (!manager) return NULL;

    pthread_mutex_init(&manager->lock, NULL);
    memset(manager->offsets, 0, sizeof(manager->offsets));
    memset(manager->keys, 0, sizeof(manager->keys));
    manager->used_events = 0;

    // Seed random number generator
    srand((unsigned int)time(NULL));

    return manager;
}

int allocate_unique_key(int* keys, size_t used_keys, int range_min, int range_max) {
    if (used_keys >= KEY_ARRAY_SIZE) return -1;

    while (1) {
        int key = rand() % (range_max - range_min + 1) + range_min;

        for (size_t i = 0; i < used_keys; ++i) {
            if (keys[i] == key) continue;
        }

        keys[used_keys++] = key;
        return key;
    }
}

void reset_event_manager(EventManager* manager) {
    pthread_mutex_lock(&manager->lock);

    memset(manager->events, 0, sizeof(manager->events));
    manager->used_events = 0;

    pthread_mutex_unlock(&manager->lock);
}

int add_event(EventManager* manager, int event_id, time_t timestamp, void* data) {
    pthread_mutex_lock(&manager->lock);

    if (manager->used_events >= MAX_EVENTS) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Buffer full
    }

    Event new_event;
    new_event.event_id = event_id;
    new_event.timestamp = timestamp;
    new_event.data = data;

    int key = allocate_unique_key(manager->keys, manager->used_events, 0, 10000);

    if (key == -1) {
        pthread_mutex_unlock(&manager->lock);
        return -2; // Failed to generate unique key
    }

    manager->events[manager->used_events++] = new_event;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void free_event_manager(EventManager* manager) {
    if (!manager) return;

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
```

### Key Features:

1. **Thread Safety**: Uses `pthread_mutex_t` to ensure thread-safe operations.
2. **Random Unique Keys**: Allocates unique keys for events within a specified range.
3. **Reset Functionality**: Allows resetting the event manager without deallocating memory.
4. **Error Logging**: In a real-world scenario, integrate logging mechanisms like `fprintf()` or use a library such as `log.h`.
5. **Network and External Dependency Handling**: Not implemented directly in this code; you would typically use external libraries for fetching configuration files and handling network operations.

### Considerations:

- This example assumes a fixed size of arrays to simplify the implementation.
- You may need to handle dynamic resizing if you plan to exceed initial allocations.
- Memory limits are assumed but not actively enforced; consider implementing memory checks based on your system's requirements."]

["```javascript
const fs = require('fs');
const crypto = require('crypto');

// Function to read file contents synchronously
function readFileContentsSync(filePath) {
  try {
    return fs.readFileSync(filePath, 'utf8');
  } catch (error) {
    console.error(`Error reading file ${filePath}:`, error);
    return null;
  }
}

// Asynchronous function to read configuration and generate hash
async function generateAndHashRandomString(configFilePath) {
  const configFileContent = readFileContentsSync(configFilePath);

  if (!configFileContent) {
    throw new Error('Failed to read config file');
  }

  try {
    const { charset, length } = JSON.parse(configFileContent);
    const randomString = generateRandomString(charset, length);
    const hash = crypto.createHash('sha256').update(randomString).digest('hex');

    return { randomString, hash };
  } catch (error) {
    console.error('Error processing config:', error);
    throw error;
  }
}

// Helper function to compute MD5 hash
function computeMD5Hash(key) {
  return crypto.createHash('md5').update(key).digest('hex');
}

// Function to generate a random string from a given character set and length
function generateRandomString(charset, length) {
  let result = '';
  for (let i = 0; i < length; i++) {
    const index = Math.floor(Math.random() * charset.length);
    result += charset[index];
  }
  return result;
}

// Example usage:
(async () => {
  try {
    const { randomString, hash } = await generateAndHashRandomString('./config.json');
    console.log('Generated String:', randomString);
    console.log('SHA-256 Hash:', hash);

    // Compute MD5 for a specific key
    const key = 'exampleKey';
    const md5Hash = computeMD5Hash(key);
    console.log(`MD5 Hash of ${key}:`, md5Hash);

    // Serialize data with additional information
    const serializedData = JSON.stringify({
      randomString,
      hash,
      md5: md5Hash
    });

    console.log('Serialized Data:', serializedData);
  } catch (error) {
    console.error('Error during execution:', error);
  }
})();
