#include <time.h>

// Define the Packet structure
typedef struct {
    time_t timestamp;
    size_t packet_size;
    void *packet_data;
    int identifier; // Unique identifier for classification
} Packet;

// Structure to manage dynamic array of packets and results buffer
typedef struct {
    Packet **packets;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    size_t result_buffer_capacity;
    Result *results; // Array of processed results
    pthread_mutex_t result_mutex;
} PacketManager;

// Structure to represent a processed result
typedef struct {
    int identifier;
    char classification[128]; // Example classification data
} Result;

// Function prototypes
void initialize_packet_manager(PacketManager *manager, size_t initial_capacity);
void free_packet_manager(PacketManager *manager);
int add_packet(PacketManager *manager, const void *data, size_t packet_size, int identifier);
void process_packets(PacketManager *manager);

// Thread-safe function to initialize the PacketManager
void initialize_packet_manager(PacketManager *manager, size_t initial_capacity) {
    manager->packets = malloc(sizeof(Packet*) * initial_capacity);
    if (!manager->packets) exit(EXIT_FAILURE); // Handle out-of-memory error

    for (size_t i = 0; i < initial_capacity; ++i) {
        manager->packets[i] = NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;

    pthread_mutex_init(&manager->mutex, NULL);
    pthread_cond_init(&manager->cond, NULL);

    // Initialize result buffer
    manager->result_buffer_capacity = 10; // Example capacity
    manager->results = malloc(sizeof(Result) * manager->result_buffer_capacity);
    if (!manager->results) exit(EXIT_FAILURE); // Handle out-of-memory error

    pthread_mutex_init(&manager->result_mutex, NULL);

    printf("PacketManager initialized.\n");
}

// Thread-safe function to free resources held by PacketManager
void free_packet_manager(PacketManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->packets[i]) {
            free(manager->packets[i]->packet_data);
            free(manager->packets[i]);
        }
    }

    pthread_mutex_destroy(&manager->mutex);
    pthread_cond_destroy(&manager->cond);

    for (size_t i = 0; i < manager->result_buffer_capacity; ++i) {
        // Cleanup results if needed
    }

    pthread_mutex_destroy(&manager->result_mutex);

    free(manager->packets);
    free(manager->results);

    printf("PacketManager resources freed.\n");
}

// Thread-safe function to add a packet, resizing the array as necessary
int add_packet(PacketManager *manager, const void *data, size_t packet_size, int identifier) {
    pthread_mutex_lock(&manager->mutex);

    // Resize if needed
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        Packet **new_packets = realloc(manager->packets, sizeof(Packet*) * new_capacity);
        if (!new_packets) {
            pthread_mutex_unlock(&manager->mutex);
            return -1; // Out-of-memory error
        }
        manager->packets = new_packets;

        for (size_t i = manager->capacity; i < new_capacity; ++i) {
            manager->packets[i] = NULL;
        }

        manager->capacity = new_capacity;
    }

    Packet *packet = malloc(sizeof(Packet));
    if (!packet) {
        pthread_mutex_unlock(&manager->mutex);
        return -1; // Out-of-memory error
    }

    packet->timestamp = time(NULL);
    packet->packet_size = packet_size;
    packet->packet_data = malloc(packet_size);
    memcpy(packet->packet_data, data, packet_size);
    packet->identifier = identifier;

    manager->packets[manager->count++] = packet;

    pthread_cond_signal(&manager->cond); // Notify processing thread
    pthread_mutex_unlock(&manager->mutex);

    return 0;
}

// Function to process packets (runs in a separate thread)
void *process_packets(void *arg) {
    PacketManager *manager = (PacketManager*) arg;

    while (1) {
        pthread_mutex_lock(&manager->mutex);
        while (manager->count == 0) {
            // Wait for new packet
            pthread_cond_wait(&manager->cond, &manager->mutex);
        }

        // Simulate processing a packet
        Packet *packet = manager->packets[0];
        memmove(manager->packets, manager->packets + 1, (manager->count - 1) * sizeof(Packet*));
        --manager->count;

        pthread_mutex_unlock(&manager->mutex);

        // Process the packet and store results
        Result result;
        strcpy(result.classification, "example_classification"); // Simulated classification logic
        result.identifier = packet->identifier;

        pthread_mutex_lock(&manager->result_mutex);
        if (/* condition to check for full buffer */) {
            // Resize or handle backpressure here
        }

        // Assume we are always adding results at index 0 for simplicity
        manager->results[0] = result; // Replace with actual logic

        pthread_mutex_unlock(&manager->result_mutex);

        free(packet->packet_data);
        free(packet);
    }

    return NULL;
}

// Example usage
int main() {
    PacketManager manager;
    initialize_packet_manager(&manager, 4); // Initialize with a small capacity for example

    pthread_t processing_thread;
    if (pthread_create(&processing_thread, NULL, process_packets, &manager) != 0) {
        perror("Failed to create thread");
        exit(EXIT_FAILURE);
    }

    // Simulate adding packets
    const char *data = "example_packet_data";
    add_packet(&manager, data, strlen(data), 1);

    // Allow some time for processing before exiting (in a real application, this would be more sophisticated)
    sleep(2);

    pthread_cancel(processing_thread);
    pthread_join(processing_thread, NULL);

    free_packet_manager(&manager);

    return 0;
}
```

### Key Design Choices:

- **Dynamic Array Management**: The dynamic array of `Packet` pointers allows for handling variable packet sizes and counts. It uses a simple doubling strategy to resize when full.

- **Thread Safety**: Mutexes ensure exclusive access to shared resources, while condition variables synchronize the producer (packet addition) and consumer (processing) threads.

- **Result Buffer**: A separate result buffer is used to store processed results, protected by its own mutex to allow concurrent read/write operations without interference.

- **Error Handling**: Out-of-memory conditions are checked after memory allocation attempts, with appropriate handling strategies such as returning error codes or exiting the program if necessary.

- **Scalability and Performance**: This design allows the system to scale efficiently in multi-threaded environments while maintaining data integrity and minimizing contention between threads.']

