class ConfigManager {
    private $config = [];
    private $cacheFile = 'config_cache.php';
    private $logger: LoggerInterface;

    public function __construct(LoggerInterface $logger) {
        $this->logger = $logger;
    }

    public function loadConfig() {
        if ($this->isCacheValid()) {
            $this->config = include($this->cacheFile);
        } else {
            $this->config = $this->fetchConfig();
            $this->writeCache();
        }
    }

    private function isCacheValid(): bool {
        return file_exists($this->cacheFile) && (filemtime($this->cacheFile) > $this->getLastModifiedTime());
    }

    private function getLastModifiedTime(): int {
        // Logic to determine last modification time of config files or environments
        return 0;
    }

    private function fetchConfig() {
        // Load environment variables
        $dotenv = Dotenv::createImmutable(__DIR__);
        $dotenv->load();

        $this->validateEnvVars([
            'APP_ENV' => ['development', 'testing', 'production'],
            'DB_HOST',
            'DB_NAME',
            'API_KEY'
        ]);

        $config = [
            'environment' => $_ENV['APP_ENV'] ?? 'production',
            'database' => [
                'host' => $_ENV['DB_HOST'] ?? 'localhost',
                'name' => $_ENV['DB_NAME'] ?? 'default_db'
            ],
            'api_key' => $_ENV['API_KEY']
        ];

        // Load from file and API
        $fileConfig = $this->loadFromFile('config.json');
        $externalConfig = $this->fetchFromExternalApi();

        return array_merge($config, $fileConfig, $externalConfig);
    }

    private function loadFromFile(string $filePath) {
        if (file_exists($filePath)) {
            return json_decode(file_get_contents($filePath), true);
        }
        return [];
    }

    private function fetchFromExternalApi() {
        // Logic to make external API call
        try {
            $apiResponse = file_get_contents('https://example.com/api/config');
            return json_decode($apiResponse, true) ?? [];
        } catch (\Exception $e) {
            $this->logger->error("API call failed: " . $e->getMessage());
            return [];
        }
    }

    private function writeCache() {
        file_put_contents($this->cacheFile, '<?php return ' . var_export($this->config, true) . ';');
    }

    public function getConfig(): array {
        return $this->config;
    }

    private function validateEnvVars(array $requiredVars) {
        foreach ($requiredVars as $key => $optionalValues) {
            if (!isset($_ENV[$key])) {
                throw new \Exception("Missing environment variable: $key");
            }
            if (is_array($optionalValues) && !in_array($_ENV[$key], $optionalValues)) {
                throw new \Exception("Invalid value for environment variable: $key");
            }
        }
    }
}

