    }
}

class AutoloaderManager {
    private static $autoloaders = [];

    public static function registerAutoloaders(array $rules) {
        foreach ($rules as $namespace => $path) {
            self::$autoloaders[] = [$namespace, $path];
        }

        spl_autoload_register(function($className) use ($rules) {
            foreach (self::$autoloaders as $autoloadRule) {
                list($prefix, $baseDir) = $autoloadRule;
                // Logic to match and include class files
                if (strncmp($prefix, $className, strlen($prefix)) === 0) {
                    $relativeClass = substr($className, strlen($prefix));
                    $file = $baseDir . str_replace('\\', '/', $relativeClass) . '.php';
                    if (file_exists($file)) {
                        require $file;
                        return;
                    }
                }
            }
        });
    }
}

class CliCommandInterface {
