    pthread_mutex_t lock;
} ConnectionPoolItem;

#define MAX_CONNECTIONS 10

// Global variables for thread-safe operations
pthread_mutex_t packet_pool_lock = PTHREAD_MUTEX_INITIALIZER;
Packet *packet_pool[100]; // Pre-allocate pool of packets
size_t current_packet_index = 0; 

// Error handling with exponential backoff strategy
void handle_transient_failure(int retry_count) {
    int wait_time = (1 << retry_count); // Exponential backoff
    sleep(wait_time);
}

// Function to initialize a new connection or reuse from pool
ConnectionPoolItem* get_connection(ConnectionPoolItem *pool, size_t pool_size) {
    for (size_t i = 0; i < pool_size; ++i) {
        pthread_mutex_lock(&pool[i].lock);
        if (pool[i].channel == NULL) { // Simulated check for connection availability
            // Establish a new "connection" here
            pool[i].channel = malloc(1); // Placeholder
            pthread_mutex_unlock(&pool[i].lock);
            return &pool[i];
        }
        pthread_mutex_unlock(&pool[i].lock);
    }

    // If no available connections, handle backoff and retry (placeholder)
    handle_transient_failure(0);

    return NULL; // Return failure if no connection is available
}

// Thread function to process packets
void* packet_processor(void *arg) {
    ConnectionPoolItem *connection = (ConnectionPoolItem*) arg;

    while (1) { // Simulated loop for processing packets
        pthread_mutex_lock(&packet_pool_lock);
        Packet *packet = NULL;

        if (current_packet_index < 100) {
            packet = malloc(sizeof(Packet));
            packet->timestamp = time(NULL);
            packet->packet_size = rand() % 1024; // Random packet size
            packet->data = malloc(packet->packet_size);
            packet->error_flag = 0; // Assume valid for now

            packet_pool[current_packet_index++] = packet;
        }

        pthread_mutex_unlock(&packet_pool_lock);

        if (packet) {
            // Simulated validation and processing of the packet
            free(packet->data);
            free(packet);
        } else {
            // Sleep to simulate waiting period before retrying
            sleep(1); 
        }
    }

    return NULL;
}

// Main function to initialize network packets
void initializeNetworkPackets(const char *remote_address) {
    pthread_t threads[4];
    ConnectionPoolItem connection_pool[MAX_CONNECTIONS];

    // Initialize the connection pool with mutex locks
    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        connection_pool[i].channel = NULL;
        pthread_mutex_init(&connection_pool[i].lock, NULL);
    }

    // Create threads to handle packets concurrently
    for (int i = 0; i < 4; ++i) {
        ConnectionPoolItem *conn = get_connection(connection_pool, MAX_CONNECTIONS);

        if (conn) {
            pthread_create(&threads[i], NULL, packet_processor, conn);
        }
    }

    // Join threads (in a real implementation, you might manage thread lifecycle differently)
    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Cleanup connection pool
    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        if (connection_pool[i].channel) {
            free(connection_pool[i].channel); 
        }
        pthread_mutex_destroy(&connection_pool[i].lock);
    }
}

// Entry point for testing
int main() {
