#include <iostream>
#include <vector>
#include <mutex>
#include <thread>
#include <condition_variable>
#include <queue>
#include <chrono>
#include <atomic>
#include <memory>

// Mocked existing logging framework interface.
namespace LoggingFramework {
    void Log(const std::string& message) {
        // Simulate logging to a file or external system
        std::cout << "[LOG] " << message << std::endl;
    }
}

struct LogEntry {
    enum Level { INFO, WARNING, ERROR };
    Level level;
    std::chrono::system_clock::time_point timestamp;
    std::string message;
    const void* logData;

    LogEntry(Level lvl, std::string msg, const void* data)
        : level(lvl), timestamp(std::chrono::system_clock::now()), message(std::move(msg)), logData(data) {}
};

class LogManager {
public:
    LogManager(size_t maxLogs);

    void AddLog(LogEntry::Level level, const std::string& message, const void* data);
    void ProcessLogs();
    void RetrieveSummaryReport();

private:
    struct LogItem {
        std::unique_ptr<LogEntry> entry;
        std::chrono::system_clock::time_point enqueueTime;

        LogItem(std::unique_ptr<LogEntry> e)
            : entry(std::move(e)), enqueueTime(std::chrono::system_clock::now()) {}
    };

    void RemoveOldLogs();

    std::vector<std::unique_ptr<LogItem>> logs;
    std::mutex logMutex;
    std::condition_variable cv;
    std::atomic<bool> stopProcessing{false};
    std::thread processingThread;
    size_t maxLogs;

    // Logging statistics
    size_t totalLoggedCount = 0;
    size_t malformedDiscardedCount = 0;
    std::chrono::duration<double> totalLogSize = {};
};

LogManager::LogManager(size_t maxLogs) : maxLogs(maxLogs) {
    processingThread = std::thread(&LogManager::ProcessLogs, this);
}

void LogManager::AddLog(LogEntry::Level level, const std::string& message, const void* data) {
    if (message.empty()) {
        LoggingFramework::Log("Malformed log entry: empty message");
        ++malformedDiscardedCount;
        return;
    }

    auto log = std::make_unique<LogEntry>(level, message, data);

    // Simulating log size calculation
    auto logSize = message.size();

    {
        std::lock_guard<std::mutex> lock(logMutex);
        logs.emplace_back(std::make_unique<LogItem>(std::move(log)));
        totalLogSize += std::chrono::duration<double>(logSize);
        ++totalLoggedCount;

        LoggingFramework::Log("Log added: " + message);

        if (logs.size() > maxLogs) {
            cv.notify_one();
        }
    }
}

void LogManager::ProcessLogs() {
    while (!stopProcessing.load()) {
        std::unique_lock<std::mutex> lock(logMutex);
        cv.wait(lock, [this] { return logs.size() >= maxLogs || stopProcessing.load(); });

        RemoveOldLogs();

        // Simulate processing delay
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
    }
}

void LogManager::RemoveOldLogs() {
    if (logs.empty()) return;

    while (logs.size() > maxLogs) {
        LoggingFramework::Log("Removing oldest log entry.");
        logs.erase(logs.begin());
    }
}

void LogManager::RetrieveSummaryReport() {
    std::lock_guard<std::mutex> lock(logMutex);

    std::cout << "Total Logs: " << totalLoggedCount << "\n"
              << "Malformed Discarded: " << malformedDiscardedCount << "\n"
              << "Average Log Size (bytes): "
              << (totalLogSize.count() / (double)std::max(1, totalLoggedCount)) << "\n";
}

// Example usage:
int main() {
    LogManager logManager(100);

    // Add logs
    logManager.AddLog(LogEntry::INFO, "System started", nullptr);
    logManager.AddLog(LogEntry::ERROR, "", nullptr);  // Malformed

    std::this_thread::sleep_for(std::chrono::seconds(2));

    // Retrieve report
    logManager.RetrieveSummaryReport();

    return 0;
}
