#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 1000

typedef struct {
    int value;
} Record;

void freeResources(long *offsets, int *keys, Record *records) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) free(records);
}

Record* allocateDataset(size_t numOffsets, size_t numRecords, int minValue, int maxValue) {
    // Validate input parameters
    if (numOffsets < 0 || numRecords > MAX_RECORDS || numRecords < 0) return NULL;

    long *offsets = NULL;
    int *keys = NULL;
    Record *records = NULL;
    srand(time(NULL));

    size_t retries = 3; // Configurable backoff strategy
    while (retries--) {
        offsets = (long*)calloc(numOffsets, sizeof(long));
        keys = (int*)calloc(numOffsets, sizeof(int));
        records = (Record*)malloc(numRecords * sizeof(Record));

        if (offsets && keys && records) break;

        freeResources(offsets, keys, records);
        sleep(1); // Simple backoff strategy
    }

    if (!offsets || !keys || !records) return NULL; // Allocation failed

    // Initialize and populate the `Record` array with unique random integers
    int range = maxValue - minValue + 1;
    int *usedValues = (int*)calloc(range, sizeof(int));

    for (size_t i = 0; i < numRecords; ++i) {
        int value;
        do {
            value = rand() % range + minValue;
        } while (usedValues[value]);

        records[i].value = value;
        usedValues[value] = 1; // Mark as used
    }

    free(usedValues);

    return records; // Return the pointer to the allocated `Record` array
}

int main() {
    size_t numOffsets = 10;
    size_t numRecords = 5;
    int minValue = 0;
    int maxValue = 100;

    Record* dataset = allocateDataset(numOffsets, numRecords, minValue, maxValue);

    if (dataset) {
        for (size_t i = 0; i < numRecords; ++i) {
            printf("Record %zu: Value = %d\n", i, dataset[i].value);
        }
        free(dataset); // Free allocated memory
    } else {
        fprintf(stderr, "Failed to allocate memory for the dataset.\n");
    }

    return 0;
}
```

This code snippet defines a function `allocateDataset` that dynamically allocates and initializes memory for managing records as per the requirements. It uses basic error handling with retries on allocation failure and ensures unique random values in the `Record` array while minimizing memory usage. The main function demonstrates how to call this function and handle its output.']

['Below is a C implementation of a dynamic database managing `record` structures in a multi-threaded environment using a hash map for efficient access. This example employs pthreads for threading and uses mutexes for thread safety.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define TABLE_SIZE 1024

typedef struct record {
    int key;
    long offset;
    time_t last_modified;
} Record;

typedef struct node {
    Record data;
    struct node *next;
} Node;

typedef struct hashmap {
    Node **buckets;
    pthread_mutex_t locks[TABLE_SIZE];
} HashMap;

void init_hashmap(HashMap *hashmap) {
    hashmap->buckets = (Node **)calloc(TABLE_SIZE, sizeof(Node *));
    for (int i = 0; i < TABLE_SIZE; ++i) {
        pthread_mutex_init(&hashmap->locks[i], NULL);
    }
}

unsigned int hash(int key) {
    return key % TABLE_SIZE;
}

void insert_record(HashMap *hashmap, Record record) {
    unsigned int index = hash(record.key);
    Node *new_node = (Node *)malloc(sizeof(Node));
    new_node->data = record;
    pthread_mutex_lock(&hashmap->locks[index]);

    new_node->next = hashmap->buckets[index];
    hashmap->buckets[index] = new_node;

    pthread_mutex_unlock(&hashmap->locks[index]);
}

Record* find_record(HashMap *hashmap, int key) {
    unsigned int index = hash(key);
    Node *current;
    pthread_mutex_lock(&hashmap->locks[index]);

    current = hashmap->buckets[index];
    while (current != NULL) {
        if (current->data.key == key) {
            pthread_mutex_unlock(&hashmap->locks[index]);
            return &current->data;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&hashmap->locks[index]);
    return NULL;
}

void delete_record(HashMap *hashmap, int key) {
    unsigned int index = hash(key);
    Node *current = hashmap->buckets[index];
    Node *prev = NULL;

    pthread_mutex_lock(&hashmap->locks[index]);

    while (current != NULL && current->data.key != key) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&hashmap->locks[index]);
        return; // Record not found
    }

    if (prev == NULL) {
        hashmap->buckets[index] = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    pthread_mutex_unlock(&hashmap->locks[index]);
}

int count_records(HashMap *hashmap) {
    int count = 0;
    for (int i = 0; i < TABLE_SIZE; ++i) {
        pthread_mutex_lock(&hashmap->locks[i]);

        Node *current = hashmap->buckets[i];
        while (current != NULL) {
            count++;
            current = current->next;
        }

        pthread_mutex_unlock(&hashmap->locks[i]);
    }
    return count;
}

void cleanup_inactive_records(HashMap *hashmap, time_t threshold) {
    for (int i = 0; i < TABLE_SIZE; ++i) {
        pthread_mutex_lock(&hashmap->locks[i]);

        Node **current = &hashmap->buckets[i];
        while (*current != NULL) {
            if ((*current)->data.last_modified < threshold) {
                Node *to_delete = *current;
                *current = (*current)->next;
                free(to_delete);
            } else {
                current = &(*current)->next;
            }
        }

        pthread_mutex_unlock(&hashmap->locks[i]);
    }
}

void free_hashmap(HashMap *hashmap) {
    for (int i = 0; i < TABLE_SIZE; ++i) {
        Node *current = hashmap->buckets[i];
        while (current != NULL) {
            Node *to_delete = current;
            current = current->next;
            free(to_delete);
        }
        pthread_mutex_destroy(&hashmap->locks[i]);
    }
    free(hashmap->buckets);
}

int main() {
    HashMap hashmap;
    init_hashmap(&hashmap);

    Record record1 = { .key = 10, .offset = 1000, .last_modified = time(NULL) };
    insert_record(&hashmap, record1);

    // Example operations
    int count = count_records(&hashmap);
    printf("Record count: %d\n", count);

    Record *found = find_record(&hashmap, 10);
    if (found != NULL) {
        printf("Found record with key %d and offset %ld\n", found->key, found->offset);
    }

    cleanup_inactive_records(&hashmap, time(NULL) - 3600); // Cleanup inactive records older than an hour

    free_hashmap(&hashmap);

    return 0;
}
```

This code sets up a basic hash map to manage `Record` structures with thread-safe insertions and deletions. It includes functions for initialization, insertion, retrieval, deletion, counting records, cleaning up inactive records, and freeing resources. Thread safety is ensured using individual mutexes per bucket in the hash map.

For logging, you can add your own implementation or use an existing library to log operations within each function as needed. Ensure appropriate error checking and handling based on specific requirements or constraints of your environment.']

