#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} Record;

typedef struct {
    long* offsets;
    int* keys;
    Record* records;
    size_t num_elements;
    pthread_mutex_t mutex;
} Collection;

// Function prototypes
Collection* init_collection(size_t num_offsets, size_t num_keys, size_t num_records);
bool add_record(Collection* collection, int key, int value);
int generate_unique_key(Collection* collection, size_t range_min, size_t range_max);
void cleanup_collection(Collection* collection);

// Random number generator initialization
void init_random() {
    srand((unsigned)time(NULL));
}

// Initialize the collection with dynamic arrays
Collection* init_collection(size_t num_offsets, size_t num_keys, size_t num_records) {
    if (num_offsets == 0 || num_keys == 0 || num_records == 0) {
        fprintf(stderr, "Error: Array sizes must be greater than zero.\n");
        return NULL;
    }

    Collection* collection = (Collection*)malloc(sizeof(Collection));
    if (!collection) {
        fprintf(stderr, "Memory allocation failed for collection.\n");
        return NULL;
    }

    pthread_mutex_init(&collection->mutex, NULL);

    collection->offsets = (long*)calloc(num_offsets, sizeof(long));
    collection->keys = (int*)calloc(num_keys, sizeof(int));
    collection->records = (Record*)calloc(num_records, sizeof(Record));

    if (!collection->offsets || !collection->keys || !collection->records) {
        fprintf(stderr, "Memory allocation failed for collection arrays.\n");
        cleanup_collection(collection);
        return NULL;
    }

    collection->num_elements = num_keys;
    return collection;
}

// Add a record to the collection with unique key generation
bool add_record(Collection* collection, int key, int value) {
    if (!collection) return false;

    pthread_mutex_lock(&collection->mutex);

    // Check for duplicate keys
    bool is_unique = true;
    for (size_t i = 0; i < collection->num_elements && is_unique; ++i) {
        if (collection->keys[i] == key) {
            is_unique = false;
        }
    }

    if (!is_unique) {
        // Generate a unique key
        key = generate_unique_key(collection, 1, INT_MAX);
    }

    for (size_t i = 0; i < collection->num_elements; ++i) {
        if (collection->keys[i] == 0) { // Find an empty slot
            collection->keys[i] = key;
            collection->records[i].value = value;
            pthread_mutex_unlock(&collection->mutex);
            return true;
        }
    }

    pthread_mutex_unlock(&collection->mutex);
    return false;
}

// Generate a unique key within the specified range
int generate_unique_key(Collection* collection, size_t range_min, size_t range_max) {
    int new_key;
    do {
        new_key = rand() % (range_max - range_min + 1) + range_min;
    } while (!add_record(collection, new_key, 0)); // Try adding with the generated key
    return new_key;
}

// Cleanup all allocated memory in the collection
void cleanup_collection(Collection* collection) {
    if (collection) {
        free(collection->offsets);
        free(collection->keys);
        free(collection->records);
        pthread_mutex_destroy(&collection->mutex);
        free(collection);
    }
}

// Main function for testing
int main() {
    init_random();

    Collection* coll = init_collection(10, 100, 100);
    if (!coll) return EXIT_FAILURE;

    add_record(coll, 42, 100);

    cleanup_collection(coll);
    return EXIT_SUCCESS;
}
```

### Explanation

- **Dynamic Initialization**: The `init_collection` function initializes the collection with dynamic arrays based on input sizes.
- **Memory Management**: Uses `calloc` for initialization and handles allocation failures gracefully by cleaning up resources.
- **Key Uniqueness**: Checks for key uniqueness and generates a new key if duplicates are found using `generate_unique_key`.
- **Thread Safety**: Utilizes a mutex (`pthread_mutex_t`) to ensure thread-safe operations.
- **Input Validation**: Validates input parameters, ensuring sizes are greater than zero.
- **Performance Optimization**: Uses simple random number generation with `rand()` for demonstration purposes. For better performance, consider using more advanced libraries like `random` in C++ or other RNG techniques.
- **Cleanup Mechanism**: The `cleanup_collection` function deallocates all resources to prevent memory leaks.
- **Scalability and Maintainability**: Designed to be easily extendable by adding new features or modifying existing ones with minimal changes.
- **Integration Testing**: Basic testing is demonstrated in the `main` function. For comprehensive testing, consider using a framework like CUnit or similar.

