#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
    int key_index;
} record;

pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;

long* allocate_long_array(size_t size) {
    pthread_mutex_lock(&memory_lock);
    long* array = (size_t)size > 0 ? malloc(sizeof(long) * size) : NULL;
    pthread_mutex_unlock(&memory_lock);
    return array;
}

int* allocate_int_array(size_t size) {
    pthread_mutex_lock(&memory_lock);
    int* array = (size_t)size > 0 ? malloc(sizeof(int) * size) : NULL;
    pthread_mutex_unlock(&memory_lock);
    return array;
}

record* allocate_record_array(size_t size) {
    pthread_mutex_lock(&memory_lock);
    record* array = (size_t)size > 0 ? malloc(sizeof(record) * size) : NULL;
    pthread_mutex_unlock(&memory_lock);
    return array;
}

void free_memory(long* longArray, int* intArray, record* recordArray) {
    pthread_mutex_lock(&memory_lock);
    free(longArray);
    free(intArray);
    free(recordArray);
    pthread_mutex_unlock(&memory_lock);
}

int generate_unique_key(int* keys, size_t num_keys, size_t key_index) {
    while (1) {
        int candidate = rand() % 1000; // Example range
        int is_duplicate = 0;

        for (size_t i = 0; i < key_index; ++i) {
            if (keys[i] == candidate) {
                is_duplicate = 1;
                break;
            }
        }

        if (!is_duplicate) {
            return candidate;
        }
    }
}

void initialize_data(size_t num_records, int min_value_range, int max_value_range) {
    pthread_mutex_lock(&memory_lock);

    long* offsets = allocate_long_array(num_records);
    int* keys = allocate_int_array(num_records);
    record* records = allocate_record_array(num_records);

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        free_memory(offsets, keys, records);
        pthread_mutex_unlock(&memory_lock);
        return;
    }

    srand(time(NULL));
    int total_value_sum = 0;

    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = rand() % 100000; // Example range for offset

        keys[i] = generate_unique_key(keys, num_records, i);

        int random_value_range = max_value_range - min_value_range;
        records[i].value = (rand() % (random_value_range + 1)) + min_value_range + total_value_sum;

        total_value_sum += records[i].value;

        // Assume key_index is derived from offset
        records[i].key_index = i; 
    }

    pthread_mutex_unlock(&memory_lock);

    // Example cleanup call
    free_memory(offsets, keys, records);
}

int main() {
    size_t num_records = 1000;
    int min_value_range = 10;
    int max_value_range = 50;

    initialize_data(num_records, min_value_range, max_value_range);

    return 0;
}
