// Define the Packet structure
typedef struct {
    unsigned long timestamp;
    size_t packet_size;
    char *data;
} Packet;

// Define the dynamic array structure for packets
typedef struct {
    Packet **packets;
    int capacity;
    int count;
    pthread_mutex_t lock;
} PacketArray;

// Function declarations
PacketArray* init_packet_array(int max_capacity);
void free_packet_array(PacketArray *packet_array);
int add_packet(PacketArray *packet_array, unsigned long timestamp, size_t packet_size, const char *data, size_t max_data_size);
void cleanup_thread_resources(void (*cleanup_func)(PacketArray *));
void *process_packets(void *arg);

// Initialize the dynamic array of packets
PacketArray* init_packet_array(int max_capacity) {
    PacketArray *packet_array = (PacketArray *)malloc(sizeof(PacketArray));
    if (!packet_array) return NULL;

    packet_array->packets = (Packet **)calloc(max_capacity, sizeof(Packet *));
    if (!packet_array->packets) {
        free(packet_array);
        return NULL;
    }

    packet_array->capacity = max_capacity;
    packet_array->count = 0;
    pthread_mutex_init(&packet_array->lock, NULL);

    return packet_array;
}

// Free the dynamic array and associated resources
void free_packet_array(PacketArray *packet_array) {
    if (!packet_array) return;

    pthread_mutex_lock(&packet_array->lock);
    for (int i = 0; i < packet_array->count; ++i) {
        free(packet_array->packets[i]->data);
        free(packet_array->packets[i]);
    }
    free(packet_array->packets);

    pthread_mutex_unlock(&packet_array->lock);
    pthread_mutex_destroy(&packet_array->lock);
    free(packet_array);
}

// Add a packet to the dynamic array
int add_packet(PacketArray *packet_array, unsigned long timestamp, size_t packet_size, const char *data, size_t max_data_size) {
    if (packet_size > max_data_size) return 0; // Discard oversized packets

    pthread_mutex_lock(&packet_array->lock);

    if (packet_array->count >= packet_array->capacity) {
        pthread_mutex_unlock(&packet_array->lock);
        return 0; // No space for new packets
    }

    Packet *new_packet = (Packet *)malloc(sizeof(Packet));
    if (!new_packet) {
        pthread_mutex_unlock(&packet_array->lock);
        return 0; // Memory allocation failure
    }

    new_packet->timestamp = timestamp;
    new_packet->packet_size = packet_size;

    new_packet->data = (char *)malloc(packet_size);
    if (!new_packet->data) {
        free(new_packet);
        pthread_mutex_unlock(&packet_array->lock);
        return 0; // Memory allocation failure
    }

    memcpy(new_packet->data, data, packet_size);

    packet_array->packets[packet_array->count++] = new_packet;

    pthread_mutex_unlock(&packet_array->lock);
    return 1;
}

// Cleanup resources for threads after processing
void cleanup_thread_resources(void (*cleanup_func)(PacketArray *)) {
    // Placeholder for thread-specific resource cleanup logic
    if (cleanup_func) cleanup_func(NULL); 
}

// Thread function to process packets
void *process_packets(void *arg) {
    PacketArray *packet_array = (PacketArray *)arg;

    // Simulate packet processing
    while (1) {  // Replace with actual condition for termination
        pthread_mutex_lock(&packet_array->lock);

        if (packet_array->count == 0) {
            pthread_mutex_unlock(&packet_array->lock);
            break;
        }

        Packet *packet = packet_array->packets[0];
        printf("Processing packet with timestamp: %lu, size: %zu\n", packet->timestamp, packet->packet_size);

        // Shift remaining packets
        for (int i = 1; i < packet_array->count; ++i) {
            packet_array->packets[i - 1] = packet_array->packets[i];
        }

        free(packet->data);
        free(packet);
        packet_array->count--;

        pthread_mutex_unlock(&packet_array->lock);

        // Simulate delay
        usleep(100000); 
    }

    cleanup_thread_resources(free_packet_array);

    return NULL;
}

// Main function to demonstrate usage
int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <max_packets>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int max_capacity = atoi(argv[1]);
    PacketArray *packet_array = init_packet_array(max_capacity);
    if (!packet_array) {
        perror("Failed to initialize packet array");
        return EXIT_FAILURE;
    }

    // Example of creating and joining threads
    pthread_t threads[4];

    for (int i = 0; i < 4; ++i) {
        if (pthread_create(&threads[i], NULL, process_packets, packet_array)) {
            perror("Failed to create thread");
            free_packet_array(packet_array);
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    free_packet_array(packet_array);

