    int *keys;
    Record **records;
    size_t numOffsets;
    size_t numRecords;
    pthread_mutex_t lock;
} FileIndexManagerContext;

typedef struct {
    int minInt, maxInt;
    double minFloat, maxFloat;
    uint64_t intCount, floatCount;
} RandomValueGenerator;

RandomValueGenerator* createRandomValueGenerator(int minInt, int maxInt, double minFloat, double maxFloat) {
    RandomValueGenerator *rng = malloc(sizeof(RandomValueGenerator));
    if (rng == NULL) return NULL;

    rng->minInt = minInt;
    rng->maxInt = maxInt;
    rng->minFloat = minFloat;
    rng->maxFloat = maxFloat;
    rng->intCount = 0;
    rng->floatCount = 0;

    return rng;
}

void freeRandomValueGenerator(RandomValueGenerator *rng) {
    if (rng) free(rng);
}

int getRandomInt(RandomValueGenerator *rng, int inclusive) {
    if (!rng) return -1;

    pthread_mutex_lock(&rng->lock);
    int value = rand() % (inclusive ? (rng->maxInt - rng->minInt + 1) : (rng->maxInt - rng->minInt)) + rng->minInt;
    rng->intCount++;
    pthread_mutex_unlock(&rng->lock);

    return value;
}

float getRandomFloat(RandomValueGenerator *rng, int inclusive) {
    if (!rng) return -1.0f;

    pthread_mutex_lock(&rng->lock);
    float range = (inclusive ? (rng->maxFloat - rng->minFloat + 0.00001) : (rng->maxFloat - rng->minFloat));
    float value = ((float)rand() / RAND_MAX) * range + rng->minFloat;
    rng->floatCount++;
    pthread_mutex_unlock(&rng->lock);

    return value;
}

void toString(RandomValueGenerator *rng, char *buffer, size_t bufferSize) {
    if (!rng || !buffer) return;

    snprintf(buffer, bufferSize, "Int Range: [%d, %d], Float Range: [%f, %f]",
             rng->minInt, rng->maxInt, rng->minFloat, rng->maxFloat);
}

void executeBackgroundTask(RandomValueGenerator *rng) {
    if (!rng) return;

    // Example task
    int value = getRandomInt(rng, 1);
    float floatValue = getRandomFloat(rng, 0);

    printf("Executed Background Task: Int=%d, Float=%.2f\n", value, floatValue);
}

FileIndexManagerContext* FileIndexManager(size_t numOffsets) {
    if (numOffsets == 0) return NULL;

    pthread_mutex_init(&lock, NULL);

    FileIndexManagerContext *context = malloc(sizeof(FileIndexManagerContext));
    if (!context) return NULL;

    context->offsets = calloc(numOffsets, sizeof(long));
    if (!context->offsets) {
        free(context);
        return NULL;
    }

    context->keys = calloc(numOffsets, sizeof(int));
    if (!context->keys) {
        free(context->offsets);
        free(context);
        return NULL;
    }

    size_t numRecords = numOffsets; // Assuming 1:1 ratio for simplicity
    context->records = malloc(numRecords * sizeof(Record*));
    if (!context->records) {
        free(context->keys);
        free(context->offsets);
        free(context);
        return NULL;
    }

    for (size_t i = 0; i < numRecords; ++i) {
        context->records[i] = malloc(sizeof(Record));
        if (!context->records[i]) {
            for (size_t j = 0; j < i; ++j)
                free(context->records[j]);
            free(context->records);
            free(context->keys);
            free(context->offsets);
            free(context);
            return NULL;
        }
    }

    context->numOffsets = numOffsets;
    context->numRecords = numRecords;

    RandomValueGenerator *rng = createRandomValueGenerator(0, 100, 0.0, 1.0);
    if (!rng) {
        for (size_t i = 0; i < numRecords; ++i)
            free(context->records[i]);
        free(context->records);
        free(context->keys);
        free(context->offsets);
        free(context);
        return NULL;
    }

    executeBackgroundTask(rng);
    freeRandomValueGenerator(rng);

    pthread_mutex_destroy(&context->lock);
    return context;
}

void cleanupFileIndexManagerContext(FileIndexManagerContext *context) {
    if (!context) return;

    for (size_t i = 0; i < context->numRecords; ++i)
        free(context->records[i]);

    free(context->records);
    free(context->keys);
    free(context->offsets);
    free(context);
}
```

This code includes:

- Dynamic memory allocation and initialization for `offsets`, `keys`, and an array of `Record` pointers.
- Thread-safe access to the random value generator using a mutex.
- Error handling for memory allocation failures, returning `NULL` if any allocation fails.
- A simple background task execution within the `RandomValueGenerator` class.']

