#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 10000
#define LOG_SOURCE_COUNT_MAX 10
#define RETRY_LIMIT 5
#define BACKOFF_BASE 100

typedef enum { INFO, DEBUG, ERROR } LogLevel;

typedef struct LogEntry {
    time_t timestamp;
    LogLevel level;
    char *message;
    struct LogEntry *next;
} LogEntry;

int randomInRange(int min, int max) {
    return rand() % (max - min + 1) + min;
}

char* fetchDataFromNetworkSource(int sourceId) {
    // Simulate network data retrieval
    static const char *messages[] = {
        "INFO: System boot successful.",
        "DEBUG: Variable x initialized to 0.",
        "ERROR: Unable to open file.",
        "INFO: User logged in.",
        "ERROR: Disk space low."
    };
    return messages[sourceId % 5];
}

int validateLogEntry(const char *message) {
    // Basic validation logic
    return message != NULL && strlen(message) > 0;
}

void retryWithBackoff(void (*action)(int), int sourceId, int retries) {
    int attempt = 0;
    while (attempt < retries) {
        action(sourceId);
        if (/* condition to check success */) break; // Implement actual success condition
        sleep(BACKOFF_BASE * (1 << attempt));
        attempt++;
    }
}

void initializeLogEntry(LogEntry **head, LogLevel level, const char *message) {
    LogEntry *entry = (LogEntry *)malloc(sizeof(LogEntry));
    if (!entry) return;

    entry->timestamp = time(NULL);
    entry->level = level;
    entry->message = strdup(message);
    entry->next = NULL;

    if (*head == NULL) {
        *head = entry;
    } else {
        LogEntry *current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = entry;
    }
}

void* manageRecordsAndLogs(int numOffsets, int numRecords, int minValue, int logSourceCount) {
    if (numOffsets < 0 || numRecords < 0 || logSourceCount < 0 ||
        numRecords > MAX_RECORDS || logSourceCount > LOG_SOURCE_COUNT_MAX) {
        return NULL;
    }

    int *records = (int *)malloc(numRecords * sizeof(int));
    if (!records) return NULL;

    srand(time(NULL));
    for (int i = 0; i < numRecords; ++i) {
        records[i] = randomInRange(minValue, minValue + numOffsets - 1);
    }

    LogEntry *logHead = NULL;
    int errorCounts[LOG_SOURCE_COUNT_MAX] = {0};
    char report[256] = "";

    for (int sourceId = 0; sourceId < logSourceCount; ++sourceId) {
        retryWithBackoff(fetchDataFromNetworkSource, sourceId, RETRY_LIMIT);

        const char *message = fetchDataFromNetworkSource(sourceId);
        if (!validateLogEntry(message)) continue;

        LogLevel level;
        if (strstr(message, "ERROR")) level = ERROR;
        else if (strstr(message, "DEBUG")) level = DEBUG;
        else level = INFO;

        initializeLogEntry(&logHead, level, message);

        if (level == ERROR) {
            errorCounts[sourceId]++;
        }

        char temp[64];
        sprintf(temp, "%d: %s\n", sourceId + 1, message);
        strcat(report, temp);
    }

    int maxErrorIndex = -1;
    int maxErrors = 0;

    for (int i = 0; i < logSourceCount; ++i) {
        if (errorCounts[i] > maxErrors) {
            maxErrors = errorCounts[i];
            maxErrorIndex = i;
        }
    }

    char summary[256];
    sprintf(summary, "Log source %d generated the highest number of ERROR messages: %d",
            maxErrorIndex + 1, maxErrors);
    strcat(report, "\n");
    strcat(report, summary);

    printf("%s", report);

    return (void *)(uintptr_t)((long)records | ((long)logHead << 32));
}

int main() {
    void *result = manageRecordsAndLogs(100, 10, 0, 3);
    if (!result) {
        fprintf(stderr, "Memory allocation failed.\n");
        return EXIT_FAILURE;
    }

    // Extract pointers from result
    int *records = (int *)((long)result & ((1LL << 32) - 1));
    LogEntry *logHead = (LogEntry *)((long)result >> 32);

    // Use records and logHead...

    free(records);
    while (logHead != NULL) {
        LogEntry *temp = logHead;
        logHead = logHead->next;
        free(temp->message);
        free(temp);
    }

    return EXIT_SUCCESS;
}
