#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

#define INITIAL_POOL_SIZE 1024

typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    size_t capacity;
    size_t count;
    Record *records;
    char *pool;
} RecordPool;

RecordPool* create_pool(size_t initial_capacity) {
    RecordPool *pool = (RecordPool *)malloc(sizeof(RecordPool));
    if (!pool) return NULL;

    pool->capacity = initial_capacity;
    pool->count = 0;
    pool->records = (Record *)(pool->pool = malloc(initial_capacity * sizeof(Record)));

    return pool;
}

void destroy_pool(RecordPool *pool) {
    if (pool) {
        free(pool->pool);
        free(pool);
    }
}

int add_record(RecordPool *pool, int key_range_min, int key_range_max) {
    if (!pool || !pool->records) return -1;

    if (pool->count == pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        Record *new_records = realloc(pool->records, new_capacity * sizeof(Record));
        if (!new_records) return -1;

        pool->records = new_records;
        pool->capacity = new_capacity;
    }

    int key = rand() % (key_range_max - key_range_min + 1) + key_range_min;
    pool->records[pool->count].key = key;
    pool->records[pool->count++].offset = rand(); // Random long for demonstration

    return 0;
}

int serialize_pool(const RecordPool *pool, const char *filename) {
    if (!pool || !filename) return -1;

    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    size_t write_count = fwrite(pool->records, sizeof(Record), pool->count, file);
    fclose(file);

    return (write_count == pool->count) ? 0 : -1;
}

int deserialize_pool(RecordPool *pool, const char *filename) {
    if (!pool || !filename) return -1;

    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    Record temp_record;
    size_t record_count = 0;

    while (fread(&temp_record, sizeof(Record), 1, file)) {
        add_record(pool, INT_MIN, INT_MAX); // Add space
        pool->records[record_count++] = temp_record;
    }

    pool->count = record_count;
    fclose(file);

    return 0;
}

int main() {
    RecordPool *pool = create_pool(INITIAL_POOL_SIZE);
    if (!pool) return EXIT_FAILURE;

    for (int i = 0; i < 100; ++i) {
        add_record(pool, 1, 100); // Example key range
    }

    serialize_pool(pool, "records.dat");
    destroy_pool(pool);

    pool = create_pool(INITIAL_POOL_SIZE);
    if (!pool || deserialize_pool(pool, "records.dat")) return EXIT_FAILURE;

    destroy_pool(pool);
    return EXIT_SUCCESS;
}
```

### Key Features:
- **Memory Pool**: A simple dynamic memory pool for managing `Record` structures.
- **Dynamic Allocation**: Automatically resizes the pool when more space is needed.
- **Serialization/Deserialization**: Supports writing to and reading from a binary file for efficient storage.
- **Error Handling**: Checks for null pointers and memory allocation errors.
- **Extensibility**: Easily extendable by modifying the `Record` structure.

### Trade-offs:
- **Memory Usage vs. Speed**: The dynamic resizing of the pool balances memory usage against speed, reducing fragmentation at the cost of occasional reallocations.
- **Serialization Format**: Binary format chosen for fast I/O operations and compact storage, though it may require more care with backward compatibility compared to text formats like JSON or XML.']
